--
-- Name: ams_asset_state(uuid, bigint, bigint, integer, boolean, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ams_asset_state(p_user uuid, p_xp bigint, p_min_xp bigint, p_stage integer, p_earned boolean, p_claimed boolean) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  select case
    when p_user is null            then 'locked'
    when p_claimed                 then 'claimed'
    when p_earned                  then 'earned'
    -- Requirement met, issuance not yet run.
    when p_xp >= p_min_xp          then 'eligible'
    -- Working toward it: any XP at all counts as started, and stage 1 is
    -- always the one in progress for a new person.
    when p_xp > 0 or p_stage = 1   then 'in_progress'
    else 'locked'
  end;
$$;


--
-- Name: ams_claim_award(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ams_claim_award(p_award_slug text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_award uuid; v_row public.user_awards;
begin
  if auth.uid() is null then
    return jsonb_build_object('ok', false, 'reason', 'not_signed_in');
  end if;

  select id into v_award from public.awards where slug = p_award_slug;
  if v_award is null then
    return jsonb_build_object('ok', false, 'reason', 'unknown_award');
  end if;

  select * into v_row from public.user_awards
  where user_id = auth.uid() and award_id = v_award;

  -- Not earned means not claimable. There is deliberately no branch here that
  -- creates the row.
  if v_row.id is null then
    return jsonb_build_object('ok', false, 'reason', 'not_earned');
  end if;
  if v_row.claimed_at is not null then
    return jsonb_build_object('ok', true, 'already_claimed', true);
  end if;

  update public.user_awards set claimed_at = now()
  where id = v_row.id;

  insert into public.ams_award_ledger (user_id, role, asset_kind, asset_slug, reason)
  select auth.uid(), coalesce(a.conditions->>'role','-'), 'certificate', a.slug, 'claimed'
  from public.awards a where a.id = v_award;

  return jsonb_build_object('ok', true, 'claimed', p_award_slug);
end $$;


--
-- Name: ams_evaluate_user(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ams_evaluate_user(p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_role      text;
  v_xp_added  bigint := 0;
  v_unlocked  int := 0;
  v_assets    int := 0;
  v_total     bigint;
  v_stage     int;
  v_rank      int;
  v_prev      int;
  ev          record;
  rl          record;
  ach         record;
  v_today     int;
  v_last      timestamptz;
  v_gain      bigint;
  v_passport  text;
begin
  select role into v_role from public.ams_activity_events
  where user_id = p_user_id order by occurred_at desc limit 1;
  if v_role is null then
    select r.role::text into v_role from public.user_roles r where r.user_id = p_user_id limit 1;
  end if;
  if v_role is null then
    return jsonb_build_object('ok', false, 'reason', 'no_role');
  end if;

  -- ---- XP from rules, one unprocessed event at a time -----------------------
  for ev in
    select * from public.ams_activity_events
    where user_id = p_user_id and processed_at is null
    order by occurred_at
  loop
    for rl in
      select r.id, r.xp_value, r.multiplier, r.cooldown_seconds, r.max_per_day, r.conditions
      from public.xp_rules r
      join public.xp_sources s on s.id = r.source_id
      where s.slug = ev.event_key
        and coalesce(r.status,'active') = 'active'
        and coalesce(s.status,'active') = 'active'
        -- A rule may be scoped to a role; an unscoped rule applies to all.
        and (r.conditions->>'role' is null or r.conditions->>'role' = ev.role)
    loop
      -- Cooldown: has this rule paid this person too recently?
      if coalesce(rl.cooldown_seconds,0) > 0 then
        select max(created_at) into v_last
        from public.xp_transactions
        where user_id = p_user_id and rule_id = rl.id;
        if v_last is not null and v_last > ev.occurred_at - make_interval(secs => rl.cooldown_seconds) then
          continue;
        end if;
      end if;

      -- Daily ceiling, counted against the day the event belongs to.
      if coalesce(rl.max_per_day,0) > 0 then
        select count(*) into v_today
        from public.xp_transactions
        where user_id = p_user_id and rule_id = rl.id
          and created_at >= date_trunc('day', ev.occurred_at)
          and created_at <  date_trunc('day', ev.occurred_at) + interval '1 day';
        if v_today >= rl.max_per_day then
          continue;
        end if;
      end if;

      v_gain := floor(coalesce(rl.xp_value,0) * coalesce(rl.multiplier,1))::bigint;
      if v_gain <> 0 then
        insert into public.xp_transactions (user_id, amount, source_id, rule_id, reason, metadata)
        select p_user_id, v_gain, r.source_id, rl.id,
               'ams:' || ev.event_key,
               jsonb_build_object('event_id', ev.id, 'entity', ev.entity_id)
        from public.xp_rules r where r.id = rl.id;

        insert into public.ams_award_ledger
          (user_id, role, event_id, rule_id, asset_kind, xp_awarded, reason)
        values (p_user_id, ev.role, ev.id, rl.id, 'xp', v_gain, 'ams:' || ev.event_key);

        v_xp_added := v_xp_added + v_gain;
      end if;
    end loop;

    update public.ams_activity_events set processed_at = now() where id = ev.id;
  end loop;

  -- ---- Totals, stage and rank ----------------------------------------------
  select coalesce(sum(amount),0) into v_total from public.xp_transactions where user_id = p_user_id;

  select coalesce(max(rank_number),1) into v_rank
  from public.ranks where min_xp <= v_total and coalesce(status,'active') = 'active';
  v_stage := v_rank;

  select current_level into v_prev from public.user_xp where user_id = p_user_id;

  insert into public.user_xp (user_id, total_xp, current_level, current_rank, updated_at)
  values (p_user_id, v_total, v_stage, v_rank, now())
  on conflict (user_id) do update
    set total_xp = excluded.total_xp,
        current_level = excluded.current_level,
        current_rank = excluded.current_rank,
        updated_at = now();

  if v_prev is null or v_stage > v_prev then
    insert into public.ams_award_ledger (user_id, role, asset_kind, asset_slug, reason)
    values (p_user_id, v_role, 'stage', v_role || '-' || lpad(v_stage::text,2,'0'),
            'reached stage ' || v_stage);
  end if;

  -- ---- Achievements whose requirement is now met ---------------------------
  -- Convention: conditions carries {"role":…, "event_key":…, "threshold":N} to
  -- count activity, or {"role":…, "stage":N} to follow progression.
  for ach in
    select a.id, a.slug, a.name, a.xp_reward, a.conditions
    from public.achievements a
    where coalesce(a.status,'active') = 'active'
      and (a.conditions->>'role' is null or a.conditions->>'role' = v_role)
      and not exists (
        select 1 from public.user_achievements ua
        where ua.user_id = p_user_id and ua.achievement_id = a.id
          and ua.unlocked_at is not null)
  loop
    if ach.conditions ? 'stage' then
      if v_stage >= (ach.conditions->>'stage')::int then
        insert into public.user_achievements (user_id, achievement_id, progress, unlocked_at)
        values (p_user_id, ach.id, 100, now())
        on conflict do nothing;
        insert into public.ams_award_ledger (user_id, role, asset_kind, asset_slug, reason)
        values (p_user_id, v_role, 'achievement', ach.slug, 'stage ' || v_stage);
        v_unlocked := v_unlocked + 1;
      end if;
    elsif ach.conditions ? 'event_key' then
      if (select coalesce(sum(value),0) from public.ams_activity_events
          where user_id = p_user_id and event_key = ach.conditions->>'event_key')
         >= coalesce((ach.conditions->>'threshold')::numeric, 1)
      then
        insert into public.user_achievements (user_id, achievement_id, progress, unlocked_at)
        values (p_user_id, ach.id, 100, now())
        on conflict do nothing;
        insert into public.ams_award_ledger (user_id, role, asset_kind, asset_slug, reason)
        values (p_user_id, v_role, 'achievement', ach.slug, ach.conditions->>'event_key');
        v_unlocked := v_unlocked + 1;
      end if;
    end if;
  end loop;

  -- ---- Stage trophies and badges the person has now reached -----------------
  insert into public.user_trophies (user_id, trophy_id, earned_at)
  select p_user_id, t.id, now()
  from public.trophies t
  where t.conditions->>'role' = v_role
    and (t.conditions->>'stage')::int <= v_stage
    and coalesce(t.status,'active') = 'active'
    and not exists (select 1 from public.user_trophies ut
                    where ut.user_id = p_user_id and ut.trophy_id = t.id)
  on conflict do nothing;
  get diagnostics v_assets = row_count;

  insert into public.user_badges (user_id, badge_id, earned_at)
  select p_user_id, b.id, now()
  from public.badges b
  where b.conditions->>'role' = v_role
    and (b.conditions->>'stage')::int <= v_stage
    and coalesce(b.status,'active') = 'active'
    and not exists (select 1 from public.user_badges ub
                    where ub.user_id = p_user_id and ub.badge_id = b.id)
  on conflict do nothing;

  -- Stage awards, the fourth asset class in the chain.
  perform public.ams_issue_awards(p_user_id, v_role, v_stage);

  -- ---- Passport keeps up with the person -----------------------------------
  v_passport := 'SV-AMS-'
    || lpad(((('x' || substr(replace(p_user_id::text,'-',''),1,6))::bit(24)::int) % 10000)::text, 4, '0')
    || '-'
    || lpad(((('x' || substr(replace(p_user_id::text,'-',''),7,6))::bit(24)::int) % 10000)::text, 4, '0');

  insert into public.ams_passports (user_id, role, passport_no, level, stage, updated_at)
  values (p_user_id, v_role, v_passport, v_stage, v_stage, now())
  on conflict (user_id) do update
    set level = excluded.level, stage = excluded.stage,
        role = excluded.role, updated_at = now();

  return jsonb_build_object(
    'ok', true, 'role', v_role, 'xp_awarded', v_xp_added,
    'total_xp', v_total, 'stage', v_stage, 'rank', v_rank,
    'achievements_unlocked', v_unlocked, 'trophies_granted', v_assets);
end $$;


--
-- Name: ams_events_immutable(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ams_events_immutable() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  -- The engine marks work done; nothing else about a recorded event may move.
  if tg_op = 'UPDATE'
     and (new.user_id, new.event_key, new.value, new.occurred_at, new.dedupe_key)
      is distinct from (old.user_id, old.event_key, old.value, old.occurred_at, old.dedupe_key)
  then
    raise exception 'ams_activity_events is append-only';
  end if;
  if tg_op = 'DELETE' then
    raise exception 'ams_activity_events is append-only';
  end if;
  return new;
end $$;


--
-- Name: ams_ingest_event(uuid, text, text, text, numeric, timestamp with time zone, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ams_ingest_event(p_user_id uuid, p_event_key text, p_entity_type text DEFAULT NULL::text, p_entity_id text DEFAULT NULL::text, p_value numeric DEFAULT 1, p_occurred_at timestamp with time zone DEFAULT now(), p_source text DEFAULT 'system'::text, p_payload jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_role text;
  v_key  text;
  v_id   uuid;
begin
  if p_user_id is null or coalesce(p_event_key,'') = '' then
    return jsonb_build_object('ok', false, 'reason', 'user_and_event_required');
  end if;

  -- The person's role decides which rules can apply. Taken from user_roles
  -- rather than from the caller, so a caller cannot claim a role.
  select r.role::text into v_role
  from public.user_roles r
  where r.user_id = p_user_id
  order by case r.role::text
             when 'boss' then 0 when 'admin' then 1 else 2 end
  limit 1;

  if v_role is null then
    -- Not an error: plenty of accounts hold no role, and AMS simply does not
    -- apply to them yet. Saying so is more useful than failing.
    return jsonb_build_object('ok', false, 'reason', 'no_role');
  end if;

  -- Derived from the occurrence itself, so the same real thing reported twice
  -- lands once. This is what makes re-imports and retried triggers safe.
  v_key := coalesce(p_entity_type,'-') || ':' || coalesce(p_entity_id,'-')
           || ':' || p_event_key || ':' || p_user_id::text;

  insert into public.ams_activity_events
    (user_id, role, event_key, entity_type, entity_id, value,
     occurred_at, source, dedupe_key, payload)
  values
    (p_user_id, v_role, p_event_key, p_entity_type, p_entity_id, coalesce(p_value,1),
     coalesce(p_occurred_at, now()), coalesce(p_source,'system'), v_key,
     coalesce(p_payload,'{}'::jsonb))
  on conflict (dedupe_key) do nothing
  returning id into v_id;

  if v_id is null then
    return jsonb_build_object('ok', true, 'duplicate', true);
  end if;
  return jsonb_build_object('ok', true, 'duplicate', false, 'event_id', v_id);
end $$;


--
-- Name: ams_is_operator(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ams_is_operator() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select exists (
    select 1 from public.user_roles r
    where r.user_id = auth.uid()
      and r.role::text in ('admin','boss','manager','operator')
  );
$$;


--
-- Name: ams_issue_awards(uuid, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ams_issue_awards(p_user_id uuid, p_role text, p_stage integer) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare n int;
begin
  insert into public.user_awards (user_id, award_id, earned_at)
  select p_user_id, a.id, now()
  from public.awards a
  where a.conditions->>'role' = p_role
    and (a.conditions->>'stage')::int <= p_stage
    and a.status = 'published'
    and not exists (select 1 from public.user_awards ua
                    where ua.user_id = p_user_id and ua.award_id = a.id)
  on conflict (user_id, award_id) do nothing;
  get diagnostics n = row_count;

  insert into public.ams_award_ledger (user_id, role, asset_kind, asset_slug, reason)
  select p_user_id, p_role, 'certificate', a.slug, 'stage ' || (a.conditions->>'stage')
  from public.awards a
  join public.user_awards ua on ua.award_id = a.id and ua.user_id = p_user_id
  where a.conditions->>'role' = p_role
    and ua.earned_at > now() - interval '5 seconds';

  return n;
end $$;


--
-- Name: ams_ledger_immutable(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ams_ledger_immutable() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  raise exception 'ams_award_ledger is append-only';
end $$;


--
-- Name: ams_on_campaign(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ams_on_campaign() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if new.status::text = 'completed' and coalesce(old.status::text,'') is distinct from 'completed'
     and new.owner_id is not null then
    begin
      perform public.ams_ingest_event(
        new.owner_id, 'campaign.delivered', 'marketing_campaigns', new.id::text, 1,
        now(), 'trigger', '{}'::jsonb);
    exception when others then null;
    end;
  end if;
  return new;
end $$;


--
-- Name: ams_on_lead(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ams_on_lead() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  begin
    -- Captured: only once an agent owns it, because an unassigned lead has not
    -- been earned by anybody.
    if tg_op = 'INSERT' and new.assigned_agent_id is not null then
      perform public.ams_ingest_event(
        new.assigned_agent_id, 'lead.captured', 'leads', new.id::text, 1,
        coalesce(new.created_at, now()), 'trigger', '{}'::jsonb);
    elsif tg_op = 'UPDATE' then
      if new.assigned_agent_id is not null
         and old.assigned_agent_id is distinct from new.assigned_agent_id then
        perform public.ams_ingest_event(
          new.assigned_agent_id, 'lead.captured', 'leads', new.id::text, 1,
          now(), 'trigger', '{}'::jsonb);
      end if;
      if new.status::text = 'won' and coalesce(old.status::text,'') is distinct from 'won'
         and new.assigned_agent_id is not null then
        perform public.ams_ingest_event(
          new.assigned_agent_id, 'lead.converted', 'leads', new.id::text, 1,
          now(), 'trigger', '{}'::jsonb);
      end if;
    end if;
  exception when others then null;
  end;
  return new;
end $$;


--
-- Name: ams_on_lead_contact(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ams_on_lead_contact() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if new.created_by is not null then
    begin
      perform public.ams_ingest_event(
        new.created_by, 'lead.contacted', 'lead_communications', new.id::text, 1,
        coalesce(new.created_at, now()), 'trigger', '{}'::jsonb);
    exception when others then null;
    end;
  end if;
  return new;
end $$;


--
-- Name: ams_on_order_paid(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ams_on_order_paid() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare r record;
begin
  if new.status::text = 'paid' and coalesce(old.status::text,'') is distinct from 'paid' then
    begin
      -- The seller who fulfilled each line.
      for r in
        select distinct oi.seller_id as who
        from public.marketplace_order_items oi
        where oi.order_id = new.id and oi.seller_id is not null
      loop
        perform public.ams_ingest_event(
          r.who, 'order.paid', 'marketplace_orders', new.id::text, 1,
          coalesce(new.updated_at, now()), 'trigger',
          jsonb_build_object('order_id', new.id, 'as', 'seller'));
      end loop;

      -- The affiliate the order was attributed to.
      for r in
        select distinct ap.user_id as who
        from public.marketplace_order_attributions a
        join public.marketplace_affiliate_partners ap on ap.id = a.affiliate_partner_id
        where a.order_id = new.id and ap.user_id is not null
      loop
        perform public.ams_ingest_event(
          r.who, 'order.paid', 'marketplace_orders', new.id::text, 1,
          coalesce(new.updated_at, now()), 'trigger',
          jsonb_build_object('order_id', new.id, 'as', 'affiliate'));
      end loop;

      -- The influencer the order was attributed to.
      for r in
        select distinct ip.user_id as who
        from public.marketplace_order_attributions a
        join public.influencer_profiles ip on ip.id = a.influencer_profile_id
        where a.order_id = new.id and ip.user_id is not null
      loop
        perform public.ams_ingest_event(
          r.who, 'order.paid', 'marketplace_orders', new.id::text, 1,
          coalesce(new.updated_at, now()), 'trigger',
          jsonb_build_object('order_id', new.id, 'as', 'influencer'));
      end loop;
    exception when others then
      null;  -- Recognition never blocks a payment.
    end;
  end if;
  return new;
end $$;


--
-- Name: ams_on_product_published(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ams_on_product_published() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if new.content_status = 'published'
     and coalesce(old.content_status::text,'') is distinct from 'published'
     and new.seller_id is not null then
    begin
      perform public.ams_ingest_event(
        new.seller_id, 'product.published', 'marketplace_products', new.id::text, 1,
        now(), 'trigger', jsonb_build_object('slug', new.slug));
    exception when others then null;
    end;
  end if;
  return new;
end $$;


--
-- Name: ams_on_task(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ams_on_task() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if new.assigned_to is null then return new; end if;
  begin
    if new.status::text = 'completed' and coalesce(old.status::text,'') is distinct from 'completed' then
      perform public.ams_ingest_event(
        new.assigned_to, 'task.completed', 'tm_tasks', new.id::text, 1,
        now(), 'trigger', '{}'::jsonb);
    end if;
    -- Approval is a separate, harder milestone, so it is its own event rather
    -- than a bonus on completion.
    if new.status::text = 'approved' and coalesce(old.status::text,'') is distinct from 'approved' then
      perform public.ams_ingest_event(
        new.assigned_to, 'task.approved', 'tm_tasks', new.id::text, 1,
        now(), 'trigger', '{}'::jsonb);
    end if;
  exception when others then null;
  end;
  return new;
end $$;


--
-- Name: ams_recompute(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ams_recompute(p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if not public.ams_is_operator() then
    return jsonb_build_object('ok', false, 'reason', 'not_permitted');
  end if;
  return public.ams_evaluate_user(p_user_id);
end $$;


--
-- Name: ams_role_chain(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ams_role_chain(p_role text, p_user_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_target  uuid;
  v_xp      bigint := 0;
  v_stage   int := 0;
  v_chain   jsonb;
begin
  -- Default to the caller. An operator may ask about somebody else; nobody
  -- else can, so a role filter cannot become a way to read a colleague's
  -- standing.
  v_target := coalesce(p_user_id, auth.uid());
  if v_target is distinct from auth.uid() and not public.ams_is_operator() then
    return jsonb_build_object('ok', false, 'reason', 'not_permitted');
  end if;

  if v_target is not null then
    select coalesce(total_xp, 0), coalesce(current_level, 0)
      into v_xp, v_stage
    from public.user_xp where user_id = v_target;
    v_xp := coalesce(v_xp, 0);
    v_stage := coalesce(v_stage, 0);
  end if;

  select jsonb_agg(row_to_json(s)::jsonb order by s.stage) into v_chain
  from (
    select
      st.stage,
      st.title,
      st.tagline,
      st.min_xp,
      -- What it takes to finish this stage, so the UI can draw a real bar.
      (select min_xp from public.ams_role_stages n
        where n.role = st.role and n.stage = st.stage + 1) as next_min_xp,
      case
        when v_target is null then 0
        when v_xp >= coalesce((select min_xp from public.ams_role_stages n
                               where n.role = st.role and n.stage = st.stage + 1),
                              st.min_xp) then 100
        when v_xp <= st.min_xp then 0
        else floor(
          (v_xp - st.min_xp)::numeric * 100
          / nullif((select min_xp from public.ams_role_stages n
                    where n.role = st.role and n.stage = st.stage + 1) - st.min_xp, 0)
        )::int
      end as progress_pct,

      -- Each asset class, with the state this person is in for it.
      jsonb_build_object(
        'slug',  t.slug,
        'name',  t.name,
        'tier',  t.tier,
        'state', public.ams_asset_state(
                   v_target, v_xp, st.min_xp, st.stage,
                   exists (select 1 from public.user_trophies ut
                           where ut.user_id = v_target and ut.trophy_id = t.id),
                   false)
      ) as trophy,

      jsonb_build_object(
        'slug',  aw.slug,
        'name',  aw.name,
        'rarity', aw.rarity,
        'state', public.ams_asset_state(
                   v_target, v_xp, st.min_xp, st.stage,
                   exists (select 1 from public.user_awards ua
                           where ua.user_id = v_target and ua.award_id = aw.id),
                   exists (select 1 from public.user_awards ua
                           where ua.user_id = v_target and ua.award_id = aw.id
                             and ua.claimed_at is not null))
      ) as award,

      jsonb_build_object(
        'slug',  b.slug,
        'name',  b.name,
        'rarity', b.rarity,
        'state', public.ams_asset_state(
                   v_target, v_xp, st.min_xp, st.stage,
                   exists (select 1 from public.user_badges ub
                           where ub.user_id = v_target and ub.badge_id = b.id),
                   false)
      ) as badge,

      jsonb_build_object(
        'slug',  ac.slug,
        'name',  ac.name,
        'rarity', ac.rarity,
        'state', public.ams_asset_state(
                   v_target, v_xp, st.min_xp, st.stage,
                   exists (select 1 from public.user_achievements ua
                           where ua.user_id = v_target and ua.achievement_id = ac.id
                             and ua.unlocked_at is not null),
                   false)
      ) as achievement,

      -- Rank and level share the stage number, and the passport records the
      -- stage a person actually holds.
      jsonb_build_object(
        'rank',  (select name from public.ranks  where rank_number  = st.stage),
        'level', (select name from public.levels where level_number = st.stage)
      ) as standing

    from public.ams_role_stages st
    left join public.trophies     t  on t.conditions->>'role'  = st.role
                                    and (t.conditions->>'stage')::int  = st.stage
    left join public.awards       aw on aw.conditions->>'role' = st.role
                                    and (aw.conditions->>'stage')::int = st.stage
    left join public.badges       b  on b.conditions->>'role'  = st.role
                                    and (b.conditions->>'stage')::int  = st.stage
    left join public.achievements ac on ac.conditions->>'role' = st.role
                                    and (ac.conditions->>'stage')::int = st.stage
    where st.role = p_role
  ) s;

  return jsonb_build_object(
    'ok', true,
    'role', p_role,
    -- Null when nobody is signed in: the UI shows the chain as a catalogue
    -- rather than pretending it belongs to someone.
    'user_id', v_target,
    'total_xp', v_xp,
    'current_stage', v_stage,
    'passport', (select jsonb_build_object('passport_no', passport_no,
                                           'verification', verification,
                                           'issued_at', issued_at)
                 from public.ams_passports where user_id = v_target),
    'stages', coalesce(v_chain, '[]'::jsonb));
end $$;


--
-- Name: ams_sweep(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ams_sweep() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare u uuid; n int := 0;
begin
  for u in
    select distinct user_id from public.ams_activity_events where processed_at is null limit 500
  loop
    perform public.ams_evaluate_user(u);
    n := n + 1;
  end loop;
  return jsonb_build_object('ok', true, 'users_evaluated', n);
end $$;


--
-- Name: application_staff(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.application_staff() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select auth.uid() is not null and exists (
    select 1 from public.user_roles
     where user_id = auth.uid()
       and lower(role::text) in ('admin', 'boss', 'super_admin', 'boss_owner', 'founder', 'marketing'));
$$;


--
-- Name: apply_gateway_payment(text, text, text, numeric, text, text, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_gateway_payment(p_gateway text, p_payment_id text, p_status text, p_amount numeric, p_currency text, p_order_id text DEFAULT NULL::text, p_intent_id uuid DEFAULT NULL::uuid, p_last4 text DEFAULT NULL::text, p_brand text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_intent public.payment_intents%ROWTYPE;
  v_payment public.payments%ROWTYPE;
  v_status text := CASE WHEN lower(p_status) IN ('success','succeeded','paid','completed') THEN 'approved' ELSE 'rejected' END;
BEGIN
  IF p_payment_id IS NULL OR p_amount IS NULL OR p_currency IS NULL THEN RAISE EXCEPTION 'Incomplete gateway payment'; END IF;
  IF EXISTS (SELECT 1 FROM public.payments WHERE gateway = p_gateway AND payment_id = p_payment_id) THEN
    SELECT * INTO v_payment FROM public.payments WHERE gateway = p_gateway AND payment_id = p_payment_id;
    RETURN to_jsonb(v_payment);
  END IF;
  SELECT * INTO v_intent FROM public.payment_intents WHERE (id = p_intent_id OR order_id = p_order_id) FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Payment intent not found'; END IF;
  IF v_intent.amount <> p_amount OR v_intent.currency <> upper(p_currency) THEN
    UPDATE public.payment_intents SET status = 'rejected', updated_at = now() WHERE id = v_intent.id;
    RAISE EXCEPTION 'Gateway amount or currency mismatch';
  END IF;
  INSERT INTO public.payments (user_id, intent_id, item_id, item_type, amount, submitted_amount, currency, order_id, payment_type, reference_id, screenshot, status, gateway, payment_id, last4, brand, mismatch_flag)
  VALUES (v_intent.user_id, v_intent.id, v_intent.item_id, v_intent.item_type, v_intent.amount, p_amount, upper(p_currency), v_intent.order_id, 'card', p_payment_id, NULL, v_status, p_gateway, p_payment_id, p_last4, p_brand, false)
  RETURNING * INTO v_payment;
  UPDATE public.payment_intents SET status = CASE WHEN v_status = 'approved' THEN 'completed' ELSE 'rejected' END, updated_at = now() WHERE id = v_intent.id;
  RETURN to_jsonb(v_payment);
END; $$;


--
-- Name: approve_influencer_earning(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.approve_influencer_earning(p_earning_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE e public.influencer_earnings%ROWTYPE;
BEGIN
  IF NOT public.influencer_manager_access() THEN RAISE EXCEPTION 'Manager access required'; END IF;
  UPDATE public.influencer_earnings SET status='payable', approved_by=auth.uid(), approved_at=now() WHERE id=p_earning_id AND status IN ('pending','approved') RETURNING * INTO e;
  IF NOT FOUND THEN RAISE EXCEPTION 'Earning is not pending approval'; END IF;
  INSERT INTO public.influencer_audit_logs(actor_user_id,entity_type,entity_id,action,after_data) VALUES(auth.uid(),'earning',e.id,'approved',to_jsonb(e));
  RETURN to_jsonb(e);
END $$;


--
-- Name: assist_audit(text, uuid, text, jsonb, jsonb, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.assist_audit(p_action text, p_session_id uuid DEFAULT NULL::uuid, p_target text DEFAULT NULL::text, p_old jsonb DEFAULT NULL::jsonb, p_new jsonb DEFAULT NULL::jsonb, p_reason text DEFAULT NULL::text, p_severity text DEFAULT 'info'::text, p_result text DEFAULT 'success'::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_id uuid; v_email text; v_role text; v_code text; v_target uuid;
begin
  select u.email into v_email from auth.users u where u.id = auth.uid();
  select ur.role::text into v_role from public.user_roles ur where ur.user_id = auth.uid() limit 1;
  select session_code, target_user_id into v_code, v_target
    from public.assist_sessions where id = p_session_id;

  insert into public.assist_audit_logs
    (session_id, session_code, actor, actor_user_id, actor_role, action,
     target, target_user_id, old_state, new_state, reason, severity, result)
  values
    (p_session_id, v_code,
     coalesce(v_email, case when auth.uid() is null then 'system' else 'account' end),
     auth.uid(), coalesce(v_role, 'system'), p_action,
     p_target, v_target, p_old, p_new, p_reason, p_severity, p_result)
  returning id into v_id;
  return v_id;
end;
$$;


--
-- Name: assist_audit_is_append_only(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.assist_audit_is_append_only() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  raise exception 'the assist audit log is append-only; % is not permitted', tg_op
    using errcode = 'insufficient_privilege';
end;
$$;


--
-- Name: assist_can_see_session(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.assist_can_see_session(p_session_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select exists (
    select 1 from public.assist_sessions s
    where s.id = p_session_id
      and (
        public.assist_is_operator()
        or s.operator_user_id = auth.uid()
        or s.target_user_id = auth.uid()
        or s.created_by = auth.uid()
        or exists (select 1 from public.assist_agents a
                   where a.id = s.agent_id and a.user_id = auth.uid())
        or exists (select 1 from public.assist_end_users e
                   where e.id = s.end_user_id and e.user_id = auth.uid())
      )
  );
$$;


--
-- Name: assist_decide_approval(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.assist_decide_approval(p_approval_id uuid, p_decision text, p_note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare a public.assist_approvals%rowtype;
begin
  if p_decision not in ('approved', 'rejected') then
    return jsonb_build_object('ok', false, 'reason', 'unknown_decision');
  end if;
  if not public.assist_is_operator() then
    return jsonb_build_object('ok', false, 'reason', 'not_permitted');
  end if;

  select * into a from public.assist_approvals where id = p_approval_id;
  if not found then return jsonb_build_object('ok', false, 'reason', 'no_such_approval'); end if;
  if a.status <> 'pending' then
    return jsonb_build_object('ok', false, 'reason', 'already_decided');
  end if;

  -- Section 10: an expired request is not approvable. It is marked expired
  -- rather than silently accepted late.
  if a.expires_at < now() then
    update public.assist_approvals set status = 'expired', decided_at = now() where id = p_approval_id;
    perform public.assist_audit('Approval Expired', a.session_id, 'approval',
      jsonb_build_object('status', 'pending'), jsonb_build_object('status', 'expired'),
      'the approval window closed before a decision was made', 'warning');
    return jsonb_build_object('ok', false, 'reason', 'expired');
  end if;

  update public.assist_approvals
     set status = p_decision, decided_at = now(), decided_by = auth.uid(),
         decision_note = p_note
   where id = p_approval_id;

  if p_decision = 'rejected' and a.session_id is not null then
    update public.assist_sessions
       set status = 'blocked', ended_at = now(),
           end_reason = coalesce(p_note, 'approval refused')
     where id = a.session_id and status in ('pending','active','paused');
  end if;

  perform public.assist_audit(
    case when p_decision = 'approved' then 'Approval Granted' else 'Approval Refused' end,
    a.session_id, 'approval',
    jsonb_build_object('status', 'pending'), jsonb_build_object('status', p_decision),
    p_note, case when p_decision = 'approved' then 'info' else 'warning' end);

  return jsonb_build_object('ok', true, 'decision', p_decision);
end;
$$;


--
-- Name: assist_emergency_stop(uuid, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.assist_emergency_stop(p_session_id uuid, p_reason text, p_all boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_codes text[];
  v_count integer := 0;
  v_stop  text;
  r       record;
begin
  -- Anybody inside the session may stop it, and any operator may stop any of
  -- them. Making this harder than it needs to be is how a stop fails to happen.
  if not (public.assist_is_operator()
          or (p_session_id is not null and public.assist_can_see_session(p_session_id))) then
    return jsonb_build_object('ok', false, 'reason', 'not_permitted');
  end if;
  if p_all and not public.assist_is_operator() then
    return jsonb_build_object('ok', false, 'reason', 'stopping every session needs an operator');
  end if;

  for r in
    select id, session_code from public.assist_sessions
    where status in ('pending','active','paused')
      and (p_all or id = p_session_id)
  loop
    -- The session itself.
    update public.assist_sessions
       set status = 'terminated', ended_at = now(), end_reason = p_reason,
           permissions = array[]::text[],
           restrictions = array['Emergency stop - all access revoked'],
           consent_granted = false, consent_revoked_at = now()
     where id = r.id;

    -- Screen, cursor, keyboard and voice.
    update public.assist_control_state
       set control_mode = 'freeze', cursor_control = false, keyboard_control = false,
           is_paused = true, voice_active = false, microphone_enabled = false,
           speaker_enabled = false
     where session_id = r.id;

    -- Anything still moving is stopped rather than left in flight.
    update public.assist_file_transfers
       set status = 'failed', deleted_at = now()
     where session_id = r.id and status in ('pending','in_progress');

    -- The AI layer loses the session with everyone else.
    update public.assist_ai_suggestions
       set status = 'dismissed', acted_at = now()
     where session_id = r.id and status = 'open';

    -- Device access: no window remains shared.
    update public.assist_session_windows set is_visible = false where session_id = r.id;

    -- Any approval still open cannot later be used to revive it.
    update public.assist_approvals
       set status = 'expired', decided_at = now(),
           decision_note = coalesce(decision_note, 'emergency stop')
     where session_id = r.id and status = 'pending';

    v_codes := v_codes || r.session_code;
    v_count := v_count + 1;

    perform public.assist_audit('Emergency Stop', r.id, 'session',
      jsonb_build_object('status', 'live'),
      jsonb_build_object('status', 'terminated', 'access', 'revoked'),
      p_reason, 'critical');
  end loop;

  if v_count = 0 then
    return jsonb_build_object('ok', true, 'sessions_stopped', 0,
                              'note', 'nothing was running');
  end if;

  v_stop := 'STOP-' || upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 8));
  insert into public.assist_emergency_stops
    (stop_code, session_code, reason, stopped_by, stopped_by_user_id, stop_type, sessions_affected)
  values (v_stop, array_to_string(v_codes, ', '), p_reason,
          coalesce((select email from auth.users where id = auth.uid()), 'system'),
          auth.uid(),
          case when p_all then 'force_all' else 'force_single' end, v_count);

  return jsonb_build_object('ok', true, 'stop_code', v_stop,
                            'sessions_stopped', v_count, 'sessions', v_codes);
end;
$$;


--
-- Name: assist_grant_consent(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.assist_grant_consent(p_session_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare s public.assist_sessions%rowtype;
begin
  select * into s from public.assist_sessions where id = p_session_id;
  if not found then return jsonb_build_object('ok', false, 'reason', 'no_such_session'); end if;

  if s.target_user_id is null or s.target_user_id <> auth.uid() then
    return jsonb_build_object('ok', false, 'reason', 'only_the_target_may_consent');
  end if;
  if s.status not in ('pending', 'active', 'paused') then
    return jsonb_build_object('ok', false, 'reason', 'session_is_closed');
  end if;

  update public.assist_sessions
     set consent_granted = true, consent_at = now(), consent_by = auth.uid(),
         consent_revoked_at = null
   where id = p_session_id;

  perform public.assist_audit('Consent Granted', p_session_id, 'session',
    jsonb_build_object('consent', false), jsonb_build_object('consent', true));
  return jsonb_build_object('ok', true);
end;
$$;


--
-- Name: assist_is_agent(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.assist_is_agent() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  -- Staff who may run an assist session, as distinct from staff who may
  -- authorise one.
  select exists (
    select 1 from public.user_roles ur
    where ur.user_id = auth.uid()
      and ur.role in ('admin','boss','founder','super_admin','boss_owner',
                      'support','developer','employee','sales_support_manager')
  );
$$;


--
-- Name: assist_is_operator(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.assist_is_operator() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select exists (
    select 1 from public.user_roles ur
    where ur.user_id = auth.uid()
      and ur.role in ('admin','boss','founder','super_admin','boss_owner')
  );
$$;


--
-- Name: assist_request_from(text, uuid, uuid, text, text, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.assist_request_from(p_source_module text, p_source_id uuid, p_target_user_id uuid, p_purpose text, p_scope text DEFAULT 'view_only'::text, p_duration_minutes integer DEFAULT 30, p_priority text DEFAULT 'normal'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_code    text;
  v_request uuid;
  v_end_user uuid;
  v_email   text;
begin
  if not public.assist_is_agent() then
    return jsonb_build_object('ok', false, 'reason', 'not_permitted');
  end if;
  if p_source_module not in ('support', 'task_manager', 'developer_manager',
                             'promise_tracker', 'reseller', 'franchise', 'control_panel') then
    return jsonb_build_object('ok', false, 'reason', 'unknown_source_module');
  end if;
  if p_target_user_id is null then
    -- Section 22B: there is no such thing as an assist session without somebody
    -- whose device it is.
    return jsonb_build_object('ok', false, 'reason', 'a target account is required');
  end if;

  -- Reuse the directory row for this person rather than making another.
  select id into v_end_user from public.assist_end_users where user_id = p_target_user_id limit 1;
  if v_end_user is null then
    select email into v_email from auth.users where id = p_target_user_id;
    insert into public.assist_end_users (user_code, role, user_id)
    values ('USR-' || upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 6)),
            'client', p_target_user_id)
    returning id into v_end_user;
  end if;

  v_code := 'REQ-' || upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 8));

  insert into public.assist_session_requests
    (request_code, end_user_id, assist_type, purpose, requested_scope,
     requested_duration_minutes, priority, status, requested_by, target_user_id,
     support_ticket_id, task_id)
  values
    (v_code, v_end_user, p_source_module, p_purpose, p_scope,
     p_duration_minutes, p_priority, 'pending', auth.uid(), p_target_user_id,
     case when p_source_module = 'support' then p_source_id end,
     case when p_source_module in ('task_manager', 'developer_manager') then p_source_id end)
  returning id into v_request;

  perform public.assist_audit('Assist Requested', null, p_source_module,
    null, jsonb_build_object('request_code', v_code, 'source_id', p_source_id),
    p_purpose);

  -- Section 22I: the platform's own notification table, never a second one.
  insert into public.notifications (user_id, title, body, kind, data)
  select u.id,
         'Assist requested - ' || v_code,
         coalesce(p_purpose, 'A remote assistance session has been requested.'),
         'assist_request',
         jsonb_build_object('module', 'assist_manager', 'request_code', v_code,
                            'source_module', p_source_module)
  from auth.users u
  where u.id = p_target_user_id
     or exists (select 1 from public.user_roles ur
                where ur.user_id = u.id
                  and ur.role in ('admin','boss','founder','super_admin','boss_owner'));

  return jsonb_build_object('ok', true, 'request_code', v_code, 'request_id', v_request);
end;
$$;


--
-- Name: assist_reset_privacy_after_session(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.assist_reset_privacy_after_session() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if new.status in ('completed','terminated','blocked')
     and old.status not in ('completed','terminated','blocked') then
    update public.assist_privacy_controls set enabled = true where enabled = false;
    update public.assist_control_state
       set control_mode = 'view', cursor_control = false, keyboard_control = false,
           voice_active = false
     where session_id = new.id;
  end if;
  return null;
end;
$$;


--
-- Name: assist_revoke_consent(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.assist_revoke_consent(p_session_id uuid, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare s public.assist_sessions%rowtype;
begin
  select * into s from public.assist_sessions where id = p_session_id;
  if not found then return jsonb_build_object('ok', false, 'reason', 'no_such_session'); end if;
  if s.target_user_id is null or s.target_user_id <> auth.uid() then
    return jsonb_build_object('ok', false, 'reason', 'only_the_target_may_revoke');
  end if;

  update public.assist_sessions
     set consent_granted = false, consent_revoked_at = now(),
         status = case when status in ('pending','active','paused') then 'terminated' else status end,
         ended_at = coalesce(ended_at, now()),
         end_reason = coalesce(p_reason, 'consent withdrawn by the target')
   where id = p_session_id;

  update public.assist_control_state
     set control_mode = 'view', cursor_control = false, keyboard_control = false,
         is_paused = true, voice_active = false
   where session_id = p_session_id;

  perform public.assist_audit('Consent Revoked', p_session_id, 'session',
    jsonb_build_object('consent', true), jsonb_build_object('consent', false),
    p_reason, 'warning');
  return jsonb_build_object('ok', true);
end;
$$;


--
-- Name: assist_session_is_live(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.assist_session_is_live(p_session_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select exists (
    select 1 from public.assist_sessions s
    where s.id = p_session_id
      and s.status in ('active','paused')
      and s.consent_granted
      and s.consent_revoked_at is null
      and exists (
        select 1 from public.assist_approvals a
        where a.session_id = s.id and a.status = 'approved')
  );
$$;


--
-- Name: assist_start_session(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.assist_start_session(p_session_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare s public.assist_sessions%rowtype; v_approved boolean;
begin
  select * into s from public.assist_sessions where id = p_session_id;
  if not found then return jsonb_build_object('ok', false, 'reason', 'no_such_session'); end if;

  if not (public.assist_is_operator() or s.operator_user_id = auth.uid()) then
    return jsonb_build_object('ok', false, 'reason', 'not_permitted');
  end if;
  if s.status <> 'pending' then
    return jsonb_build_object('ok', false, 'reason', 'session_is_not_pending');
  end if;
  if not s.consent_granted or s.consent_revoked_at is not null then
    return jsonb_build_object('ok', false, 'reason', 'the target has not consented');
  end if;

  select exists (select 1 from public.assist_approvals
                 where session_id = p_session_id and status = 'approved')
    into v_approved;
  if not v_approved then
    return jsonb_build_object('ok', false, 'reason', 'no approval has been granted');
  end if;

  update public.assist_sessions
     set status = 'active', started_at = coalesce(started_at, now())
   where id = p_session_id;

  insert into public.assist_control_state (session_id, control_mode)
  values (p_session_id, 'view')
  on conflict (session_id) do nothing;

  perform public.assist_audit('Session Started', p_session_id, 'session',
    jsonb_build_object('status', 'pending'), jsonb_build_object('status', 'active'));

  return jsonb_build_object('ok', true, 'session_code', s.session_code);
end;
$$;


--
-- Name: assist_status_for(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.assist_status_for(p_module text, p_record_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  with sessions as (
    select s.* from public.assist_sessions s
    where (p_module = 'support'         and s.support_ticket_id = p_record_id)
       or (p_module = 'task_manager'    and s.task_id = p_record_id)
       or (p_module = 'promise_tracker' and s.promise_id = p_record_id)
  ),
  requests as (
    select r.* from public.assist_session_requests r
    where (p_module = 'support'      and r.support_ticket_id = p_record_id)
       or (p_module = 'task_manager' and r.task_id = p_record_id)
  )
  select jsonb_build_object(
    'module', p_module,
    'record_id', p_record_id,
    -- The vocabulary section 22F asks the Task Manager to show.
    'assist_status', case
      when exists (select 1 from sessions where status in ('active','paused')) then 'assist_active'
      when exists (select 1 from sessions where status = 'terminated')          then 'assist_terminated'
      when exists (select 1 from sessions where status = 'completed')           then 'assist_completed'
      when exists (select 1 from sessions where status = 'pending')             then 'assist_pending'
      when exists (select 1 from requests where status = 'pending')             then 'assist_requested'
      else 'no_assist' end,
    'sessions', coalesce((
      select jsonb_agg(jsonb_build_object(
        'session_id', id, 'session_code', session_code, 'status', status,
        'access_mode', access_mode, 'started_at', started_at, 'ended_at', ended_at,
        'end_reason', end_reason))
      from sessions), '[]'::jsonb),
    'open_requests', (select count(*) from requests where status = 'pending')
  );
$$;


--
-- Name: assist_touch_updated_at(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.assist_touch_updated_at() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin new.updated_at = now(); return new; end; $$;


--
-- Name: bootstrap_first_admin(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bootstrap_first_admin() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ BEGIN IF EXISTS (SELECT 1 FROM public.user_roles LIMIT 1) THEN RETURN NEW; END IF; IF (SELECT count(*) FROM auth.users) > 1 THEN RETURN NEW; END IF; INSERT INTO public.user_roles (user_id, role) VALUES (NEW.id, 'admin') ON CONFLICT DO NOTHING; RETURN NEW; END; $$;


--
-- Name: bump_chat_conversation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bump_chat_conversation() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  UPDATE public.chat_conversations SET updated_at = now() WHERE id = NEW.conversation_id;
  RETURN NEW;
END; $$;


--
-- Name: calculate_influencer_earning(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calculate_influencer_earning(p_activity_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE a public.influencer_activity%ROWTYPE; r public.influencer_compensation_rules%ROWTYPE; p public.influencer_profiles%ROWTYPE; e public.influencer_earnings%ROWTYPE; v_amount numeric;
BEGIN
  IF NOT public.influencer_manager_access() THEN RAISE EXCEPTION 'Manager access required'; END IF;
  SELECT * INTO a FROM public.influencer_activity WHERE id = p_activity_id FOR UPDATE;
  IF NOT FOUND OR a.verification_status <> 'verified' THEN RAISE EXCEPTION 'Activity must be verified before calculation'; END IF;
  SELECT * INTO r FROM public.influencer_compensation_rules WHERE campaign_id = (SELECT campaign_id FROM public.influencer_campaign_assignments WHERE id=a.assignment_id) AND metric=a.metric AND active=true LIMIT 1;
  IF NOT FOUND THEN RAISE EXCEPTION 'No active compensation rule for activity'; END IF;
  SELECT * INTO p FROM public.influencer_profiles WHERE id=(SELECT profile_id FROM public.influencer_campaign_assignments WHERE id=a.assignment_id);
  v_amount := a.quantity * r.rate;
  INSERT INTO public.influencer_earnings(profile_id,activity_id,campaign_id,gross_amount,currency,status) VALUES(p.id,a.id,r.campaign_id,v_amount,r.currency,'pending') ON CONFLICT(activity_id) DO UPDATE SET gross_amount=EXCLUDED.gross_amount,currency=EXCLUDED.currency RETURNING * INTO e;
  INSERT INTO public.influencer_audit_logs(actor_user_id,entity_type,entity_id,action,after_data) VALUES(auth.uid(),'earning',e.id,'calculated',jsonb_build_object('activity_id',a.id,'quantity',a.quantity,'rate',r.rate,'amount',v_amount));
  RETURN to_jsonb(e);
END $$;


--
-- Name: can_post_in_chat(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.can_post_in_chat(_conv uuid, _user uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1
    FROM public.chat_participants p
    JOIN public.chat_conversations c ON c.id = p.conversation_id
    WHERE p.conversation_id = _conv
      AND p.user_id = _user
      AND (
        p.role = ANY (c.allowed_roles)
        OR public.is_admin(_user)
      )
  );
$$;


--
-- Name: create_influencer_payout(uuid, numeric, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_influencer_payout(p_profile_id uuid, p_amount numeric, p_currency text, p_idempotency_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE p public.influencer_payouts%ROWTYPE; v_balance numeric;
BEGIN
  IF NOT public.influencer_manager_access() THEN RAISE EXCEPTION 'Manager access required'; END IF;
  SELECT coalesce(sum(net_amount),0) INTO v_balance FROM public.influencer_earnings WHERE profile_id=p_profile_id AND status='payable';
  IF p_amount <= 0 OR p_amount > v_balance THEN RAISE EXCEPTION 'Payout exceeds payable balance'; END IF;
  INSERT INTO public.influencer_payouts(profile_id,idempotency_key,amount,currency,status,processed_by) VALUES(p_profile_id,p_idempotency_key,p_amount,p_currency,'approved',auth.uid()) ON CONFLICT(idempotency_key) DO UPDATE SET idempotency_key=EXCLUDED.idempotency_key RETURNING * INTO p;
  INSERT INTO public.influencer_audit_logs(actor_user_id,entity_type,entity_id,action,after_data) VALUES(auth.uid(),'payout',p.id,'approved',to_jsonb(p));
  RETURN to_jsonb(p);
END $$;


--
-- Name: create_payment_intent(text, text, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_payment_intent(p_item_id text, p_item_type text, p_amount numeric, p_currency text DEFAULT 'USD'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_user uuid := auth.uid();
  v_currency text := upper(trim(p_currency));
  v_rate numeric := CASE WHEN v_currency = 'INR' THEN 1 ELSE 83.00 END;
  v_intent public.payment_intents%ROWTYPE;
BEGIN
  IF v_user IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  IF p_item_type NOT IN ('product','plan','subscription','wallet_topup') THEN RAISE EXCEPTION 'Invalid payment item type'; END IF;
  IF p_amount IS NULL OR p_amount <= 0 THEN RAISE EXCEPTION 'Payment amount must be positive'; END IF;
  IF v_currency !~ '^[A-Z]{3}$' THEN RAISE EXCEPTION 'Invalid currency'; END IF;

  UPDATE public.payment_intents SET status = 'expired', updated_at = now()
  WHERE user_id = v_user AND status IN ('initiated','pending','partial') AND expires_at <= now();
  SELECT * INTO v_intent FROM public.payment_intents
  WHERE user_id = v_user AND item_id = trim(p_item_id) AND item_type = p_item_type
    AND status IN ('initiated','pending','partial') AND expires_at > now()
  ORDER BY created_at DESC LIMIT 1;
  IF FOUND THEN RETURN to_jsonb(v_intent); END IF;

  INSERT INTO public.payment_intents (order_id, user_id, item_id, item_type, amount, currency, exchange_rate, base_amount)
  VALUES ('ORDER-' || upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 6)), v_user, trim(p_item_id), p_item_type, round(p_amount, 2), v_currency, v_rate, round(p_amount * v_rate, 2))
  RETURNING * INTO v_intent;
  RETURN to_jsonb(v_intent);
END; $_$;


--
-- Name: create_payment_intent_secure(text, text, numeric, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_payment_intent_secure(p_item_id text, p_item_type text, p_amount numeric, p_currency text, p_idempotency_key text, p_device_id text, p_session_id text, p_source_ip text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_user uuid := auth.uid();
  v_intent public.payment_intents%ROWTYPE;
  v_currency text := upper(trim(p_currency));
  v_rate numeric := CASE WHEN v_currency = 'INR' THEN 1 ELSE 83.00 END;
BEGIN
  IF v_user IS NULL OR nullif(trim(p_idempotency_key), '') IS NULL OR nullif(trim(p_device_id), '') IS NULL OR nullif(trim(p_session_id), '') IS NULL THEN RAISE EXCEPTION 'Secure payment session required'; END IF;
  IF p_item_type NOT IN ('product','plan','subscription','wallet_topup') OR p_amount IS NULL OR p_amount <= 0 OR v_currency !~ '^[A-Z]{3}$' THEN RAISE EXCEPTION 'Invalid payment request'; END IF;
  IF (SELECT count(*) FROM public.payment_intents WHERE user_id = v_user AND created_at > now() - interval '10 minutes') >= 10 THEN RAISE EXCEPTION 'Payment attempt limit reached'; END IF;
  SELECT * INTO v_intent FROM public.payment_intents WHERE user_id = v_user AND idempotency_key = trim(p_idempotency_key) FOR UPDATE;
  IF FOUND THEN
    IF v_intent.device_id <> p_device_id OR v_intent.session_id <> p_session_id THEN RAISE EXCEPTION 'Payment session mismatch'; END IF;
    RETURN to_jsonb(v_intent);
  END IF;
  UPDATE public.payment_intents SET status = 'expired', updated_at = now() WHERE user_id = v_user AND status IN ('initiated','pending','partial') AND expires_at <= now();
  SELECT * INTO v_intent FROM public.payment_intents WHERE user_id = v_user AND item_id = trim(p_item_id) AND item_type = p_item_type AND status IN ('initiated','pending','partial') AND expires_at > now() FOR UPDATE;
  IF FOUND THEN RAISE EXCEPTION 'An active payment already exists for this order'; END IF;
  INSERT INTO public.payment_intents (order_id, user_id, item_id, item_type, amount, currency, exchange_rate, base_amount, idempotency_key, device_id, session_id, source_ip, transaction_hash)
  VALUES ('ORDER-' || upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 6)), v_user, trim(p_item_id), p_item_type, round(p_amount, 2), v_currency, v_rate, round(p_amount * v_rate, 2), trim(p_idempotency_key), trim(p_device_id), trim(p_session_id), nullif(p_source_ip, '')::inet, encode(digest(trim(p_idempotency_key) || ':' || v_user::text, 'sha256'), 'hex'))
  RETURNING * INTO v_intent;
  RETURN to_jsonb(v_intent);
END; $_$;


--
-- Name: create_remote_assist_session(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_remote_assist_session() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_session_id UUID;
  v_session_code TEXT;
  v_user_role public.app_role;
  v_user_code VARCHAR(6);
BEGIN
  SELECT role INTO v_user_role FROM public.user_roles WHERE user_id = auth.uid() LIMIT 1;

  IF EXISTS (
    SELECT 1 FROM public.safe_assist_sessions
    WHERE user_id = auth.uid() AND status IN ('pending','connected','active')
  ) THEN
    RETURN jsonb_build_object('success', false, 'error', 'You already have an active support session');
  END IF;

  LOOP
    v_session_code := public.generate_session_code();
    EXIT WHEN NOT EXISTS (SELECT 1 FROM public.safe_assist_sessions WHERE session_code = v_session_code);
  END LOOP;

  v_user_code := public.generate_verification_code();

  INSERT INTO public.safe_assist_sessions (session_code, user_id, user_role, mode, expires_at, user_verification_code)
  VALUES (v_session_code, auth.uid(), v_user_role, 'guided_cursor', now() + interval '5 minutes', v_user_code)
  RETURNING id INTO v_session_id;

  INSERT INTO public.audit_logs (user_id, action, module, role, meta_json)
  VALUES (auth.uid(), 'safe_assist_session_created', 'safe_assist', v_user_role,
          jsonb_build_object('session_id', v_session_id));

  RETURN jsonb_build_object('success', true, 'session_id', v_session_id, 'session_code', v_session_code,
                            'verification_code', v_user_code, 'expires_at', now() + interval '5 minutes');
END; $$;


--
-- Name: create_reseller_membership_order(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_reseller_membership_order(p_plan_code text, p_idempotency_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_user uuid := auth.uid();
  v_reseller public.resellers%rowtype;
  v_plan public.reseller_membership_plans%rowtype;
  v_order public.reseller_membership_orders%rowtype;
  v_invoice public.finance_invoices%rowtype;
  v_intent public.finance_payment_intents%rowtype;
  v_rail public.finance_payment_rails%rowtype;
  v_key text := trim(p_idempotency_key);
begin
  if v_user is null then raise exception 'Authentication required'; end if;
  if nullif(v_key, '') is null then raise exception 'Idempotency key required'; end if;
  select * into v_reseller from public.resellers where user_id = v_user and status = 'active' for update;
  if not found then raise exception 'Active reseller account required'; end if;
  -- The price comes from the plan, never from the caller.
  select * into v_plan from public.reseller_membership_plans where code = lower(trim(p_plan_code)) and enabled for share;
  if not found then raise exception 'Invalid membership plan'; end if;
  -- A retried request returns the same order, and only this reseller's.
  select * into v_order from public.reseller_membership_orders
   where idempotency_key = v_key and reseller_id = v_reseller.id;
  if found then
    return jsonb_build_object('order', to_jsonb(v_order),
      'invoice', (select to_jsonb(i) from public.finance_invoices i where i.id = v_order.finance_invoice_id),
      'payment_intent', (select to_jsonb(pi) from public.finance_payment_intents pi where pi.id = v_order.finance_intent_id),
      'duplicate', true);
  end if;
  if exists (select 1 from public.reseller_membership_orders where idempotency_key = v_key) then
    raise exception 'Idempotency key already used';
  end if;
  -- Still open for this plan: the same order, not a second one.
  select * into v_order from public.reseller_membership_orders
   where reseller_id = v_reseller.id and plan_id = v_plan.id and status in ('pending','processing')
   order by created_at desc limit 1;
  if found then
    return jsonb_build_object('order', to_jsonb(v_order),
      'invoice', (select to_jsonb(i) from public.finance_invoices i where i.id = v_order.finance_invoice_id),
      'payment_intent', (select to_jsonb(pi) from public.finance_payment_intents pi where pi.id = v_order.finance_intent_id),
      'duplicate', true);
  end if;
  select * into v_rail from public.finance_payment_rails where code = 'bank_transfer' limit 1;
  if not found then raise exception 'Allowed payment rails are not configured'; end if;
  insert into public.finance_invoices (invoice_no, doc_type, client_name, client_type, subtotal, tax_amount, total, status, auto_generated, issue_date, due_date, line_items)
  values ('RMI-' || upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 12)), 'invoice', v_reseller.name, 'reseller', v_plan.price_usd, 0, v_plan.price_usd, 'unpaid', true, current_date, current_date,
          jsonb_build_array(jsonb_build_object('kind', 'reseller_membership', 'plan_code', v_plan.code, 'description', v_plan.name, 'quantity', 1, 'unit_amount', v_plan.price_usd)))
  returning * into v_invoice;
  insert into public.finance_invoice_items (invoice_id, description, quantity, unit_amount, tax_amount, discount_amount)
  values (v_invoice.id, v_plan.name || ' annual reseller membership', 1, v_plan.price_usd, 0, 0);
  insert into public.reseller_membership_orders (order_number, reseller_id, plan_id, amount_usd, currency, status, idempotency_key, approval_status, finance_invoice_id, payment_status, proof_metadata)
  values ('RMO-' || upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 12)), v_reseller.id, v_plan.id, v_plan.price_usd, 'USD', 'pending', v_key, 'pending', v_invoice.id, 'pending', '{}'::jsonb)
  returning * into v_order;
  insert into public.finance_payment_intents (invoice_id, rail_id, idempotency_key, amount, currency, status, client_reference)
  values (v_invoice.id, v_rail.id, 'membership-' || v_key, v_plan.price_usd, 'USD', 'pending', v_order.order_number)
  returning * into v_intent;
  update public.reseller_membership_orders set finance_intent_id = v_intent.id where id = v_order.id returning * into v_order;
  insert into public.reseller_membership_events (reseller_id, order_id, event_key, event_type, payload)
  values (v_reseller.id, v_order.id, 'order-created:' || v_order.id::text, 'order.created', jsonb_build_object('plan_code', v_plan.code, 'amount_usd', v_plan.price_usd));
  insert into public.reseller_notifications (title, type, audience, status, body, reseller_id)
  values ('Membership order created', 'order.created', 'reseller', 'sent', 'Your membership invoice is ready for payment.', v_reseller.id);
  return jsonb_build_object('order', to_jsonb(v_order), 'invoice', to_jsonb(v_invoice), 'payment_intent', to_jsonb(v_intent), 'duplicate', false);
end;
$$;


--
-- Name: dev_manager_is_operator(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dev_manager_is_operator() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  -- There is no dev-manager role in user_roles; developer operations sit with
  -- the platform operator roles the Control Panel already uses.
  SELECT EXISTS (
    SELECT 1 FROM public.user_roles ur
    WHERE ur.user_id = auth.uid()
      AND ur.role IN ('admin','boss','founder','super_admin','boss_owner')
  );
$$;


--
-- Name: end_remote_assist_session(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.end_remote_assist_session(p_session_id uuid, p_reason text DEFAULT 'User ended session'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_session RECORD;
BEGIN
  SELECT * INTO v_session FROM public.safe_assist_sessions
  WHERE id = p_session_id AND (user_id = auth.uid() OR support_agent_id = auth.uid()) FOR UPDATE;

  IF v_session IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Session not found or access denied');
  END IF;

  UPDATE public.safe_assist_sessions
  SET status = 'ended', ended_at = now(), ended_by = auth.uid(), end_reason = p_reason
  WHERE id = p_session_id;

  INSERT INTO public.safe_assist_events (session_id, event_type, event_data, actor_type)
  VALUES (p_session_id, 'session_ended', jsonb_build_object('reason', p_reason, 'ended_by', auth.uid()), 'system');

  INSERT INTO public.safe_assist_alerts (session_id, alert_type, recipients, message)
  VALUES (p_session_id, 'session_ended', ARRAY['super_admin','admin'],
          'Safe Assist session ended: ' || v_session.session_code || ' - ' || p_reason);

  RETURN jsonb_build_object('success', true, 'session_id', p_session_id);
END; $$;


--
-- Name: enqueue_payment_success(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enqueue_payment_success() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.status IN ('approved','completed') AND (TG_OP = 'INSERT' OR OLD.status IS DISTINCT FROM NEW.status) THEN
    INSERT INTO public.payment_event_outbox (event_type, payment_id, payload)
    VALUES ('PAYMENT_SUCCESS', NEW.id, jsonb_build_object('payment_id', NEW.id, 'order_id', NEW.order_id, 'amount', NEW.amount, 'currency', NEW.currency))
    ON CONFLICT (event_type, payment_id) DO NOTHING;
  END IF;
  RETURN NEW;
END; $$;


