--
-- Name: generate_lead_alerts(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.generate_lead_alerts() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    INSERT INTO public.lead_alerts (lead_id, alert_type, message, severity)
    VALUES (NEW.id, 'new_lead', 'New lead captured: ' || NEW.name, CASE WHEN NEW.priority IN ('critical', 'high') THEN 'high' ELSE 'medium' END);
  END IF;

  IF NEW.deal_value >= 500000 AND (TG_OP = 'INSERT' OR OLD.deal_value IS DISTINCT FROM NEW.deal_value) THEN
    IF NOT EXISTS (
      SELECT 1 FROM public.lead_alerts
      WHERE lead_id = NEW.id AND alert_type = 'high_value' AND is_active
    ) THEN
      INSERT INTO public.lead_alerts (lead_id, alert_type, message, severity)
      VALUES (NEW.id, 'high_value', 'High-value opportunity: ' || NEW.name, 'high');
    END IF;
  END IF;

  IF (NEW.is_duplicate OR NEW.duplicate_score >= 70) AND
     (TG_OP = 'INSERT' OR OLD.is_duplicate IS DISTINCT FROM NEW.is_duplicate OR OLD.duplicate_score IS DISTINCT FROM NEW.duplicate_score) THEN
    IF NOT EXISTS (
      SELECT 1 FROM public.lead_alerts
      WHERE lead_id = NEW.id AND alert_type = 'duplicate' AND is_active
    ) THEN
      INSERT INTO public.lead_alerts (lead_id, alert_type, message, severity)
      VALUES (NEW.id, 'duplicate', 'Possible duplicate detected: ' || NEW.name, 'medium');
    END IF;
  END IF;

  IF NEW.fraud_score >= 70 AND (TG_OP = 'INSERT' OR OLD.fraud_score IS DISTINCT FROM NEW.fraud_score) THEN
    IF NOT EXISTS (
      SELECT 1 FROM public.lead_alerts
      WHERE lead_id = NEW.id AND alert_type = 'fraud' AND is_active
    ) THEN
      INSERT INTO public.lead_alerts (lead_id, alert_type, message, severity)
      VALUES (NEW.id, 'fraud', 'Fraud-risk lead detected: ' || NEW.name, 'high');
    END IF;
  END IF;

  IF TG_OP = 'UPDATE' AND NEW.status IS DISTINCT FROM OLD.status AND NEW.status IN ('won', 'lost', 'spam') THEN
    UPDATE public.lead_alerts
    SET is_active = false, acknowledged_at = COALESCE(acknowledged_at, now())
    WHERE lead_id = NEW.id AND is_active AND alert_type IN ('new_lead', 'idle', 'sla_breach');
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: generate_session_code(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.generate_session_code() RETURNS text
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  chars TEXT := 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
  result TEXT := '';
  i INTEGER;
BEGIN
  FOR i IN 1..8 LOOP
    result := result || substr(chars, floor(random() * length(chars) + 1)::INTEGER, 1);
  END LOOP;
  RETURN result;
END; $$;


--
-- Name: generate_verification_code(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.generate_verification_code() RETURNS character varying
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN UPPER(SUBSTRING(MD5(RANDOM()::TEXT || NOW()::TEXT) FROM 1 FOR 6));
END; $$;


--
-- Name: give_remote_assist_consent(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.give_remote_assist_consent(p_session_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_session RECORD;
BEGIN
  SELECT * INTO v_session FROM public.safe_assist_sessions
  WHERE id = p_session_id AND user_id = auth.uid() FOR UPDATE;

  IF v_session IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Session not found');
  END IF;

  IF v_session.support_agent_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'No support agent has joined yet');
  END IF;

  UPDATE public.safe_assist_sessions
  SET user_consent_given = true, user_consent_at = now(), status = 'active', started_at = now(),
      expires_at = now() + (max_duration_minutes || ' minutes')::interval
  WHERE id = p_session_id;

  INSERT INTO public.safe_assist_events (session_id, event_type, event_data, actor_type)
  VALUES (p_session_id, 'consent_given', jsonb_build_object('timestamp', now()), 'user');

  INSERT INTO public.safe_assist_alerts (session_id, alert_type, recipients, message)
  VALUES (p_session_id, 'session_started', ARRAY['super_admin','admin'],
          'Safe Assist session started: ' || v_session.session_code);

  RETURN jsonb_build_object('success', true, 'session_id', p_session_id,
                            'expires_at', now() + (v_session.max_duration_minutes || ' minutes')::interval);
END; $$;


--
-- Name: guard_partner_privileges(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_partner_privileges() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  actor uuid := auth.uid();
  is_operator boolean;
begin
  if actor is null then return new; end if; -- service role and database jobs
  select exists (
    select 1 from public.user_roles ur
    where ur.user_id = actor
      and ur.role::text in ('admin','boss','founder','boss_owner','super_admin','finance')
  ) into is_operator;
  if is_operator then return new; end if;

  if tg_table_name = 'resellers' then
    if tg_op = 'INSERT' then
      -- A partner creates only their own record, and only as an application.
      if new.user_id is distinct from actor then
        raise exception 'A reseller record can only be created for your own account';
      end if;
      new.status := 'pending';
      new.tier := 'bronze';
      new.kyc_status := 'unverified';
      new.approved_at := null;
      new.approved_by := null;
      new.plan_code := null;
      return new;
    end if;
    if new.tier is distinct from old.tier or new.status is distinct from old.status
       or new.approved_at is distinct from old.approved_at or new.approved_by is distinct from old.approved_by
       or new.kyc_status is distinct from old.kyc_status or new.plan_code is distinct from old.plan_code
       or new.user_id is distinct from old.user_id or new.code is distinct from old.code then
      raise exception 'Tier, status, plan and approval are set by the Control Panel, not by the partner';
    end if;
  end if;

  if tg_table_name = 'franchises' and tg_op = 'UPDATE' then
    if new.status is distinct from old.status or new.territory is distinct from old.territory
       or new.territory_id is distinct from old.territory_id or new.commission_rate is distinct from old.commission_rate
       or new.royalty_rate is distinct from old.royalty_rate or new.pricing_variation is distinct from old.pricing_variation then
      raise exception 'Territory, status and commercial terms are set by the Control Panel, not by the franchise';
    end if;
  end if;
  return new;
end;
$$;


--
-- Name: handle_new_user(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.handle_new_user() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  INSERT INTO public.profiles (id, email, full_name, username, phone)
  VALUES (
    NEW.id,
    NEW.email,
    NEW.raw_user_meta_data ->> 'full_name',
    COALESCE(NEW.raw_user_meta_data ->> 'username', split_part(COALESCE(NEW.email, ''), '@', 1)),
    NEW.phone
  )
  ON CONFLICT (id) DO NOTHING;
  RETURN NEW;
END; $$;


