$$;


--
-- Name: i18n_translation_jobs; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.i18n_translation_jobs (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    source_hash text NOT NULL,
    source_text text NOT NULL,
    source_language text DEFAULT 'en'::text NOT NULL,
    target_language text NOT NULL,
    namespace text DEFAULT 'ui'::text NOT NULL,
    context text,
    context_hash text NOT NULL,
    refresh boolean DEFAULT false NOT NULL,
    priority smallint DEFAULT 100 NOT NULL,
    status text DEFAULT 'queued'::text NOT NULL,
    attempts smallint DEFAULT 0 NOT NULL,
    max_attempts smallint DEFAULT 3 NOT NULL,
    run_after timestamp with time zone DEFAULT now() NOT NULL,
    locked_at timestamp with time zone,
    locked_by text,
    result_status text,
    quality_score numeric(4,3),
    last_error text,
    requested_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    finished_at timestamp with time zone,
    CONSTRAINT i18n_translation_jobs_context_check CHECK (((context IS NULL) OR (char_length(context) <= 500))),
    CONSTRAINT i18n_translation_jobs_context_hash_check CHECK ((context_hash ~ '^[0-9a-f]{32}$'::text)),
    CONSTRAINT i18n_translation_jobs_namespace_check CHECK ((namespace ~ '^[a-z0-9][a-z0-9._-]{0,47}$'::text)),
    CONSTRAINT i18n_translation_jobs_source_hash_check CHECK ((source_hash ~ '^[0-9a-f]{32}$'::text)),
    CONSTRAINT i18n_translation_jobs_source_text_check CHECK (((char_length(source_text) >= 1) AND (char_length(source_text) <= 5000))),
    CONSTRAINT i18n_translation_jobs_status_check CHECK ((status = ANY (ARRAY['queued'::text, 'running'::text, 'done'::text, 'failed'::text, 'cancelled'::text])))
);


--
-- Name: i18n_claim_translation_jobs(text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.i18n_claim_translation_jobs(p_worker text, p_limit integer, p_lease_seconds integer DEFAULT 600) RETURNS SETOF public.i18n_translation_jobs
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  update public.i18n_translation_jobs
     set status = 'queued', locked_at = null, locked_by = null, updated_at = now()
   where status = 'running'
     and locked_at < now() - make_interval(secs => greatest(p_lease_seconds, 60));

  return query
  with picked as (
    select id
      from public.i18n_translation_jobs
     where status = 'queued' and run_after <= now()
     order by priority, created_at
     limit greatest(1, least(p_limit, 200))
     for update skip locked
  )
  update public.i18n_translation_jobs j
     set status = 'running', locked_at = now(), locked_by = p_worker,
         attempts = j.attempts + 1, updated_at = now()
    from picked
   where j.id = picked.id
  returning j.*;
end;
$$;


--
-- Name: i18n_consume_quota(text, integer, bigint, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.i18n_consume_quota(p_subject text, p_units integer, p_limit bigint, p_window_seconds integer) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_window timestamptz;
  v_units  bigint;
begin
  if p_subject is null or length(p_subject) > 200 or p_units < 0 or p_limit < 0
     or p_window_seconds < 1 then
    raise exception 'invalid quota request';
  end if;

  v_window := to_timestamp(floor(extract(epoch from now()) / p_window_seconds) * p_window_seconds);

  insert into public.i18n_request_quota as q (subject, window_start, units)
  values (p_subject, v_window, p_units)
  on conflict (subject, window_start) do update set units = q.units + excluded.units
  returning q.units into v_units;

  if random() < 0.01 then
    delete from public.i18n_request_quota where window_start < now() - interval '2 days';
  end if;

  return v_units <= p_limit;
end;
$$;


--
-- Name: i18n_enqueue_translation_jobs(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.i18n_enqueue_translation_jobs(p_jobs jsonb) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_count integer;
begin
  if jsonb_typeof(p_jobs) <> 'array' or jsonb_array_length(p_jobs) > 20000 then
    raise exception 'p_jobs must be an array of at most 20000 jobs';
  end if;

  with incoming as (
    select distinct on (j.source_hash, coalesce(j.source_language, 'en'), j.target_language, j.context_hash)
           j.source_hash, j.source_text, coalesce(j.source_language, 'en') as source_language,
           j.target_language, coalesce(j.namespace, 'ui') as namespace, j.context, j.context_hash,
           coalesce(j.refresh, false) as refresh, coalesce(j.priority, 100)::smallint as priority,
           j.requested_by
      from jsonb_to_recordset(p_jobs) as j(
             source_hash text, source_text text, source_language text, target_language text,
             namespace text, context text, context_hash text, refresh boolean, priority integer,
             requested_by uuid)
  ), inserted as (
    insert into public.i18n_translation_jobs
      (source_hash, source_text, source_language, target_language, namespace, context,
       context_hash, refresh, priority, requested_by)
    select i.source_hash, i.source_text, i.source_language, i.target_language, i.namespace,
           i.context, i.context_hash, i.refresh, i.priority, i.requested_by
      from incoming i
     where i.refresh
        or not exists (
             select 1 from public.marketplace_translations m
              where m.source_hash = i.source_hash
                and m.source_language = i.source_language
                and m.target_language = i.target_language
                and m.context_hash = i.context_hash
                and m.status in ('machine', 'verified', 'needs_review', 'rejected'))
    on conflict (source_hash, source_language, target_language, context_hash)
      where status in ('queued', 'running')
      do nothing
    returning 1
  )
  select count(*) into v_count from inserted;
  return v_count;
end;
$$;


--
-- Name: i18n_finish_translation_job(uuid, text, boolean, text, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.i18n_finish_translation_job(p_id uuid, p_worker text, p_ok boolean, p_result_status text, p_quality numeric, p_error text) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  update public.i18n_translation_jobs
     set status = case
                    when p_ok then 'done'
                    when attempts >= max_attempts then 'failed'
                    else 'queued'
                  end,
         run_after = case
                       when p_ok then run_after
                       else now() + make_interval(secs => 60 * power(2, attempts)::integer)
                     end,
         result_status = p_result_status,
         quality_score = p_quality,
         last_error = left(p_error, 1000),
         locked_at = null,
         locked_by = null,
         finished_at = case when p_ok then now() else finished_at end,
         updated_at = now()
   where id = p_id and locked_by = p_worker and status = 'running';
$$;


--
-- Name: i18n_job_summary(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.i18n_job_summary() RETURNS TABLE(status text, target_language text, jobs bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select j.status, j.target_language, count(*)
    from public.i18n_translation_jobs j
   where j.status in ('queued', 'running', 'failed')
      or j.updated_at > now() - interval '1 day'
   group by j.status, j.target_language;
$$;


--
-- Name: i18n_mark_stale(text, text, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.i18n_mark_stale(p_namespace text, p_context text, p_current_hashes text[]) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_count integer;
begin
  if p_context is null or length(p_context) = 0 then
    raise exception 'p_context is required: rows without a context are page text, not keyed messages';
  end if;
  update public.marketplace_translations
     set status = 'stale'
   where namespace = p_namespace
     and context = p_context
     and status in ('machine', 'needs_review')
     and not (source_hash = any (coalesce(p_current_hashes, '{}')));
  get diagnostics v_count = row_count;
  return v_count;
end;
$$;


--
-- Name: i18n_prune(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.i18n_prune(p_job_days integer DEFAULT 7, p_quota_hours integer DEFAULT 48) RETURNS TABLE(jobs_deleted bigint, quota_windows_deleted bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_jobs bigint;
  v_quota bigint;
begin
  delete from public.i18n_translation_jobs
   where status in ('done', 'failed', 'cancelled')
     and coalesce(finished_at, updated_at) < now() - make_interval(days => greatest(p_job_days, 1));
  get diagnostics v_jobs = row_count;

  -- The longest window in use is a day; anything older than two is history.
  delete from public.i18n_request_quota
   where window_start < now() - make_interval(hours => greatest(p_quota_hours, 25));
  get diagnostics v_quota = row_count;

  return query select v_jobs, v_quota;
end;
$$;


--
-- Name: i18n_resolve_language(text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.i18n_resolve_language(p_input text, p_legacy boolean DEFAULT false) RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  with v as (
    select nullif(btrim(p_input), '') as raw,
           lower(replace(btrim(p_input), '_', '-')) as tag
  )
  select coalesce(r.replaced_by, r.code)
  from (
  select coalesce(
    (select l.code from public.i18n_languages l, v
      where p_legacy and l.legacy_code = upper(v.raw) limit 1),
    (select l.code from public.i18n_languages l, v
      where lower(l.code) = v.tag limit 1),
    (select l.code from public.i18n_languages l, v
      where v.tag = any (l.aliases) order by l.sort_order limit 1),
    (select l.code from public.i18n_languages l, v
      where lower(l.code) = split_part(v.tag, '-', 1) limit 1),
    (select l.code from public.i18n_languages l, v
      where split_part(v.tag, '-', 1) = any (l.aliases) order by l.sort_order limit 1),
    (select l.code from public.i18n_languages l, v
      where lower(l.name) = lower(v.raw) or l.native_name = v.raw
      order by l.sort_order limit 1)
  ) as code
  from v
  where v.raw is not null
  ) x
  join public.i18n_languages r on r.code = x.code;
$$;


--
-- Name: i18n_touch_updated_at(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.i18n_touch_updated_at() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  new.updated_at := now();
  return new;
end;
$$;


--
-- Name: i18n_translation_coverage(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.i18n_translation_coverage() RETURNS TABLE(target_language text, verified bigint, machine bigint, needs_review bigint, rejected bigint, legacy bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select m.target_language,
         count(*) filter (where m.status = 'verified'),
         count(*) filter (where m.status = 'machine'),
         count(*) filter (where m.status = 'needs_review'),
         count(*) filter (where m.status = 'rejected'),
         count(*) filter (where m.status in ('legacy', 'stale'))
    from public.marketplace_translations m
   where m.target_language is not null
   group by m.target_language;
$$;


--
-- Name: i18n_translation_memory_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.i18n_translation_memory_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if tg_op = 'UPDATE' then
    -- An automatic write never replaces a decision a person made. A person
    -- reopening a row sets review_note, which automatic writes never touch.
    if old.status in ('verified', 'rejected')
       and new.status in ('machine', 'needs_review')
       and new.review_note is not distinct from old.review_note then
      return old;
    end if;
    if new.translated_text is distinct from old.translated_text
       or new.status is distinct from old.status then
      insert into public.i18n_translation_revisions
        (translation_id, version, translated_text, status, quality_score, engine, engine_version, changed_by)
      values
        (old.id, old.version, old.translated_text, old.status, old.quality_score, old.engine,
         old.engine_version, auth.uid());
      new.version := old.version + 1;
    end if;
    new.updated_at := now();
  end if;

  if new.status = 'verified' and new.reviewed_at is null then
    new.reviewed_at := now();
    new.reviewed_by := coalesce(new.reviewed_by, auth.uid());
  end if;
  new.locale := coalesce(new.target_language, new.locale);
  return new;
end;
$$;


