--
-- Name: legal_pending_acceptances(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.legal_pending_acceptances(p_user_id uuid DEFAULT NULL::uuid) RETURNS TABLE(agreement_id uuid, agreement_ref text, agreement_name text, version_id uuid, version text, body text, body_sha256 text, reason text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  with me as (select coalesce(p_user_id, auth.uid()) as uid),
  my_roles as (
    select ur.role::text as role from public.user_roles ur, me where ur.user_id = me.uid
  )
  select a.id, a.ref_code, a.name, v.id, v.version, v.body, v.body_sha256,
         case
           when exists (
             select 1 from public.legal_acceptances acc, me
             where acc.agreement_id = a.id and acc.user_id = me.uid and acc.decision = 'accepted')
           then 're_accept_required'
           else 'never_accepted'
         end
  from public.legal_agreements a
  join public.legal_agreement_versions v
    on v.id = a.current_version_id and v.status = 'published'
  , me
  where a.gate_on_login
    and a.requires_acceptance
    and a.status = 'published'
    -- Either it applies to everyone, or to a role this person holds.
    and (a.applies_to_role is null
         or a.applies_to_role in (select role from my_roles))
    -- And they have not accepted this exact version.
    and not exists (
      select 1 from public.legal_acceptances acc
      where acc.version_id = v.id and acc.user_id = me.uid and acc.decision = 'accepted')
  order by a.ref_code;
$$;


--
-- Name: legal_publish_version(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.legal_publish_version(p_version_id uuid, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v public.legal_agreement_versions%rowtype;
  a public.legal_agreements%rowtype;
  v_hash text;
begin
  if not public.legal_is_operator() then
    return jsonb_build_object('ok', false, 'reason', 'not_permitted');
  end if;

  select * into v from public.legal_agreement_versions where id = p_version_id;
  if not found then return jsonb_build_object('ok', false, 'reason', 'no_such_version'); end if;
  if v.status = 'published' then
    return jsonb_build_object('ok', false, 'reason', 'already_published');
  end if;
  -- Section 7 and 28: an AI draft is a draft. It is approved by a person before
  -- it can be published, and the approver is not optional.
  if v.approved_by is null then
    return jsonb_build_object('ok', false, 'reason', 'a version must be approved before it is published');
  end if;

  select * into a from public.legal_agreements where id = v.agreement_id;
  v_hash := encode(extensions.digest(v.body, 'sha256'), 'hex');

  -- Everything published before this is superseded, never deleted: an
  -- acceptance recorded against it still has to resolve.
  update public.legal_agreement_versions
     set status = 'superseded', superseded_at = now()
   where agreement_id = v.agreement_id and status = 'published' and id <> p_version_id;

  update public.legal_agreement_versions
     set status = 'published', published_by = auth.uid(), published_at = now(),
         body_sha256 = v_hash, reason = coalesce(p_reason, reason)
   where id = p_version_id;

  update public.legal_agreements
     set status = 'published', current_version_id = p_version_id
   where id = v.agreement_id;

  perform public.legal_log('Agreement Version Published', 'legal_agreement_version',
    p_version_id::text,
    jsonb_build_object('status', v.status),
    jsonb_build_object('status', 'published', 'version', v.version, 'sha256', v_hash),
    p_reason, 'warning');

  return jsonb_build_object('ok', true, 'version', v.version, 'sha256', v_hash,
                            'agreement', a.ref_code);
end;
$$;


--
-- Name: legal_record_acceptance(uuid, text, boolean, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.legal_record_acceptance(p_version_id uuid, p_decision text DEFAULT 'accepted'::text, p_scrolled_to_end boolean DEFAULT false, p_ip text DEFAULT NULL::text, p_user_agent text DEFAULT NULL::text, p_session_reference text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v public.legal_agreement_versions%rowtype;
  a public.legal_agreements%rowtype;
  v_email text; v_role text; v_id uuid;
begin
  if auth.uid() is null then
    return jsonb_build_object('ok', false, 'reason', 'sign_in_required');
  end if;
  if p_decision not in ('accepted', 'rejected') then
    return jsonb_build_object('ok', false, 'reason', 'unknown_decision');
  end if;

  select * into v from public.legal_agreement_versions where id = p_version_id;
  if not found then return jsonb_build_object('ok', false, 'reason', 'no_such_version'); end if;
  -- Only a published version can be accepted. Accepting a draft would bind
  -- somebody to text that is still being edited.
  if v.status <> 'published' then
    return jsonb_build_object('ok', false, 'reason', 'that version is not published');
  end if;

  -- Section 14: the server will not accept a claim of acceptance that skipped
  -- the review it required.
  if p_decision = 'accepted' and not p_scrolled_to_end then
    return jsonb_build_object('ok', false, 'reason', 'the agreement must be read to the end before it can be accepted');
  end if;

  select * into a from public.legal_agreements where id = v.agreement_id;
  select u.email into v_email from auth.users u where u.id = auth.uid();
  select ur.role::text into v_role from public.user_roles ur where ur.user_id = auth.uid() limit 1;

  insert into public.legal_acceptances
    (agreement_id, version_id, version_label, body_sha256, user_id, user_email,
     user_role, decision, method, ip_address, user_agent, session_reference,
     scrolled_to_end)
  values
    (v.agreement_id, p_version_id, v.version, v.body_sha256, auth.uid(), v_email,
     v_role, p_decision, 'login_gate', p_ip, p_user_agent, p_session_reference,
     p_scrolled_to_end)
  on conflict (version_id, user_id, decision) do nothing
  returning id into v_id;

  perform public.legal_log(
    case when p_decision = 'accepted' then 'Agreement Accepted' else 'Agreement Rejected' end,
    'legal_agreement_version', p_version_id::text, null,
    jsonb_build_object('decision', p_decision, 'version', v.version,
                       'agreement', a.ref_code),
    null, case when p_decision = 'rejected' then 'warning' else 'info' end);

  return jsonb_build_object('ok', true, 'decision', p_decision,
                            'acceptance_id', v_id, 'agreement', a.ref_code);
end;
$$;


--
-- Name: legal_touch_updated_at(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.legal_touch_updated_at() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin new.updated_at = now(); return new; end; $$;


--
-- Name: legal_version_body_is_frozen(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.legal_version_body_is_frozen() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if old.status in ('published','superseded','archived')
     and new.body is distinct from old.body then
    raise exception
      'the text of a published agreement version cannot be changed; publish a new version instead'
      using errcode = 'insufficient_privilege';
  end if;
  return new;
end;
$$;


--
-- Name: uuid_v7(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.uuid_v7() RETURNS uuid
    LANGUAGE plpgsql
    AS $$
DECLARE
  timestamp_hex text := lpad(to_hex(floor(extract(epoch FROM clock_timestamp()) * 1000)::bigint), 12, '0');
  random_uuid text := gen_random_uuid()::text;
BEGIN
  RETURN (
    substr(timestamp_hex, 1, 8) || '-' ||
    substr(timestamp_hex, 9, 4) || '-' ||
    '7' || substr(random_uuid, 16, 3) || '-' ||
    substr(random_uuid, 20, 4) || '-' ||
    substr(random_uuid, 25, 12)
  )::uuid;
END; $$;


--
-- Name: payments; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.payments (
    id uuid DEFAULT public.uuid_v7() NOT NULL,
    user_id uuid NOT NULL,
    item_id text NOT NULL,
    item_type text NOT NULL,
    amount numeric(20,2) NOT NULL,
    payment_type text NOT NULL,
    status text DEFAULT 'pending'::text NOT NULL,
    reference_id text NOT NULL,
    screenshot text,
    retry_count integer DEFAULT 0 NOT NULL,
    last_checked_at timestamp with time zone,
    mismatch_flag boolean DEFAULT false NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    intent_id uuid,
    order_id text,
    currency text,
    submitted_amount numeric(20,2),
    country text,
    auto_verified boolean DEFAULT false NOT NULL,
    tags text[] DEFAULT '{}'::text[] NOT NULL,
    gateway text,
    payment_id text,
    last4 text,
    brand text,
    source_ip inet,
    device_id text,
    transaction_hash text,
    deleted_at timestamp with time zone,
    CONSTRAINT payments_amount_check CHECK ((amount > (0)::numeric)),
    CONSTRAINT payments_item_type_check CHECK ((item_type = ANY (ARRAY['product'::text, 'plan'::text, 'subscription'::text, 'wallet_topup'::text]))),
    CONSTRAINT payments_payment_type_check CHECK ((payment_type = ANY (ARRAY['wise'::text, 'card'::text, 'remitly'::text, 'western_union'::text, 'moneygram'::text, 'payoneer'::text, 'skrill'::text, 'neteller'::text, 'binance'::text, 'upi'::text, 'bank_manual'::text]))),
    CONSTRAINT payments_retry_count_check CHECK ((retry_count >= 0)),
    CONSTRAINT payments_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'partial'::text, 'approved'::text, 'rejected'::text, 'completed'::text, 'expired'::text, 'refunded'::text])))
);


--
-- Name: list_my_payments(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_my_payments() RETURNS SETOF public.payments
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT p FROM public.payments p WHERE p.user_id = auth.uid() ORDER BY p.created_at DESC;
$$;


--
-- Name: log_safe_assist_ai_event(uuid, character varying, character varying, jsonb, character varying, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_safe_assist_ai_event(p_session_id uuid, p_event_type character varying, p_risk_level character varying, p_analysis jsonb, p_recommended_action character varying, p_auto_handle boolean DEFAULT false) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_log_id UUID;
  v_session RECORD;
BEGIN
  SELECT * INTO v_session FROM public.safe_assist_sessions WHERE id = p_session_id;

  INSERT INTO public.safe_assist_ai_logs (session_id, event_type, risk_level, ai_analysis, action_recommended, auto_handled)
  VALUES (p_session_id, p_event_type, p_risk_level, p_analysis, p_recommended_action, p_auto_handle)
  RETURNING id INTO v_log_id;

  UPDATE public.safe_assist_sessions
  SET ai_risk_score = ai_risk_score + CASE
        WHEN p_risk_level = 'critical' THEN 50
        WHEN p_risk_level = 'high' THEN 30
        WHEN p_risk_level = 'medium' THEN 15
        ELSE 5 END,
      ai_flags = ai_flags || jsonb_build_array(jsonb_build_object('type', p_event_type, 'risk', p_risk_level, 'time', now()))
  WHERE id = p_session_id;

  IF p_risk_level = 'critical' AND p_auto_handle THEN
    UPDATE public.safe_assist_sessions SET status = 'terminated', ended_at = now() WHERE id = p_session_id;
    INSERT INTO public.safe_assist_notifications (session_id, user_id, notification_type, title, message, severity)
    VALUES (p_session_id, v_session.user_id, 'session_terminated', 'Safe Assist Terminated',
            'Session was automatically terminated due to security concerns. Our team will contact you.', 'error');
  ELSIF p_risk_level IN ('high','critical') THEN
    INSERT INTO public.safe_assist_notifications (session_id, user_id, notification_type, title, message, severity)
    VALUES (p_session_id, v_session.user_id, 'security_alert', 'Security Alert',
            'Unusual activity detected. AI is monitoring closely. Click to review.', 'warning');
  END IF;

  RETURN v_log_id;
END; $$;


--
-- Name: log_seo_activity(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_seo_activity() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  changed_id uuid;
  change_context jsonb;
BEGIN
  changed_id := CASE WHEN TG_OP = 'DELETE' THEN OLD.id ELSE NEW.id END;
  change_context := jsonb_build_object(
    'operation', TG_OP,
    'table', TG_TABLE_NAME
  );

  INSERT INTO public.seo_activity_log (table_name, record_id, action, context)
  VALUES (TG_TABLE_NAME, changed_id, TG_OP, change_context);

  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END;
$$;


--
-- Name: marketing_audit(text, text, text, text, jsonb, jsonb, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.marketing_audit(p_action text, p_entity_type text, p_entity_id text DEFAULT NULL::text, p_module text DEFAULT 'marketing'::text, p_before jsonb DEFAULT NULL::jsonb, p_after jsonb DEFAULT NULL::jsonb, p_severity text DEFAULT 'info'::text, p_result text DEFAULT 'success'::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_id    uuid;
  v_email text;
  v_role  text;
begin
  select u.email into v_email from auth.users u where u.id = auth.uid();
  select ur.role::text into v_role from public.user_roles ur
   where ur.user_id = auth.uid() limit 1;

  insert into public.marketing_audit_logs
    (action, entity_type, entity_id, module, actor, actor_id, actor_role,
     before_state, after_state, severity, result)
  values
    (p_action, p_entity_type, p_entity_id, p_module,
     coalesce(v_email, case when auth.uid() is null then 'system' else 'account' end),
     auth.uid(),
     coalesce(v_role, 'system'),
     p_before, p_after, p_severity, p_result)
  returning id into v_id;

  return v_id;
end;
$$;


--
-- Name: marketing_audit_is_append_only(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.marketing_audit_is_append_only() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  raise exception 'the marketing audit log is append-only; % is not permitted', tg_op
    using errcode = 'insufficient_privilege';
end;
$$;


--
-- Name: marketing_is_operator(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.marketing_is_operator() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select
    public.has_role(auth.uid(), 'admin'::app_role)
    or public.has_role(auth.uid(), 'boss'::app_role)
    or public.has_role(auth.uid(), 'founder'::app_role)
    or public.has_role(auth.uid(), 'super_admin'::app_role)
    or public.has_role(auth.uid(), 'boss_owner'::app_role)
    or public.has_role(auth.uid(), 'marketing'::app_role)
    or public.has_role(auth.uid(), 'influencer'::app_role)
    or public.has_role(auth.uid(), 'developer'::app_role);
$$;


--
-- Name: marketing_make_promise(text, uuid, text, text, timestamp with time zone, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.marketing_make_promise(p_entity_type text, p_entity_id uuid, p_title text, p_receiver text, p_deadline timestamp with time zone, p_priority text DEFAULT 'high'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_code    text;
  v_promise uuid;
  v_email   text;
begin
  if not public.marketing_is_operator() then
    return jsonb_build_object('ok', false, 'reason', 'not_permitted');
  end if;
  if p_deadline is null then
    return jsonb_build_object('ok', false, 'reason', 'a promise needs a hard deadline');
  end if;

  select u.email into v_email from auth.users u where u.id = auth.uid();
  v_code := public.pt_next_code();

  insert into public.promises (code, title, owner, receiver, owner_user_id,
                               deadline, priority, status, linked_module,
                               linked_record_id, created_by)
  values (v_code, p_title, coalesce(v_email, 'Marketing'), p_receiver, auth.uid(),
          p_deadline, p_priority, 'active', 'marketing_manager',
          p_entity_id::text, auth.uid())
  returning id into v_promise;

  insert into public.promise_links (promise_id, module, record_id, relation, label, created_by)
  values (v_promise, 'marketing_manager', p_entity_id::text, 'committed_by', p_entity_type, auth.uid())
  on conflict do nothing;

  if p_entity_type = 'campaign' then
    update public.marketing_campaigns set promise_id = v_promise where id = p_entity_id;
  elsif p_entity_type = 'report' then
    update public.marketing_reports set promise_id = v_promise where id = p_entity_id;
  end if;

  perform public.marketing_audit('Promise Created', p_entity_type, p_entity_id::text,
    'marketing', null, jsonb_build_object('promise_id', v_promise, 'code', v_code));

  return jsonb_build_object('ok', true, 'promise_id', v_promise, 'code', v_code);
end;
$$;


--
-- Name: marketing_notify(text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.marketing_notify(p_audience text, p_title text, p_body text, p_kind text DEFAULT 'marketing'::text, p_entity_id text DEFAULT NULL::text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_count integer := 0;
begin
  with targets as (
    select distinct u.id as user_id
    from auth.users u
    where exists (
      select 1 from public.user_roles ur
      where ur.user_id = u.id
        and ur.role::text = any (
          case p_audience
            when 'marketing' then array['admin','boss','founder','super_admin','boss_owner','marketing']
            when 'admin'     then array['admin','boss','founder','super_admin','boss_owner']
            else array['admin','boss','founder','super_admin','boss_owner','marketing']
          end)
    )
  )
  insert into public.notifications (user_id, title, body, kind, data)
  select t.user_id, p_title, p_body, p_kind,
         jsonb_build_object('module', 'marketing_manager', 'entity_id', p_entity_id)
  from targets t;

  get diagnostics v_count = row_count;
  return v_count;
end;
$$;


--
-- Name: marketing_open_task(text, uuid, text, text, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.marketing_open_task(p_entity_type text, p_entity_id uuid, p_title text, p_description text DEFAULT ''::text, p_priority text DEFAULT 'medium'::text, p_deadline timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_code   text;
  v_task   uuid;
  v_member uuid;
begin
  if not public.marketing_is_operator() then
    return jsonb_build_object('ok', false, 'reason', 'not_permitted');
  end if;
  if p_entity_type not in ('campaign', 'creative', 'content', 'seo', 'approval') then
    return jsonb_build_object('ok', false, 'reason', 'unknown_entity_type');
  end if;

  v_code := 'MKT-' || upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 8));
  select id into v_member from public.tm_members where user_id = auth.uid() limit 1;

  insert into public.tm_tasks (code, title, description, module, source_reference,
                               status, priority, deadline, category, created_by)
  values (v_code, p_title, coalesce(p_description, ''), 'marketing_manager',
          p_entity_id::text, 'new', p_priority, p_deadline, p_entity_type, v_member)
  returning id into v_task;

  -- The reference is stored on the marketing row; the task itself lives in the
  -- Task Manager and is never copied here.
  case p_entity_type
    when 'campaign' then update public.marketing_campaigns    set task_id = v_task where id = p_entity_id;
    when 'creative' then update public.marketing_creatives    set task_id = v_task where id = p_entity_id;
    when 'content'  then update public.marketing_content_items set task_id = v_task where id = p_entity_id;
    when 'approval' then update public.marketing_approvals    set task_id = v_task where id = p_entity_id;
    else null;
  end case;

  perform public.marketing_audit('Task Opened', p_entity_type, p_entity_id::text,
    'marketing', null, jsonb_build_object('task_id', v_task, 'code', v_code));

  return jsonb_build_object('ok', true, 'task_id', v_task, 'code', v_code);
end;
$$;


--
-- Name: marketing_seed_summary(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.marketing_seed_summary() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  -- Deliberately counts rather than trusts: a screen asking "is any of this
  -- demonstration data?" gets the answer from the rows themselves.
  select jsonb_build_object(
    'seed_campaigns',      (select count(*) from public.marketing_campaigns where is_seed),
    'real_campaigns',      (select count(*) from public.marketing_campaigns where not is_seed),
    'seed_revenue',        (select coalesce(sum(revenue), 0) from public.marketing_campaigns where is_seed),
    'real_revenue',        (select coalesce(sum(revenue), 0) from public.marketing_campaigns where not is_seed),
    'seed_spend',          (select coalesce(sum(spend), 0) from public.marketing_campaigns where is_seed),
    'real_spend',          (select coalesce(sum(spend), 0) from public.marketing_campaigns where not is_seed),
    'seed_leads',          (select coalesce(sum(leads), 0) from public.marketing_campaigns where is_seed),
    'real_leads',          (select coalesce(sum(leads), 0) from public.marketing_campaigns where not is_seed),
    'lead_records',        (select count(*) from public.marketing_leads),
    'any_seed_present',    (select exists (select 1 from public.marketing_campaigns where is_seed))
  );
$$;


--
-- Name: marketplace_add_to_cart(uuid, integer, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.marketplace_add_to_cart(p_product_id uuid, p_quantity integer DEFAULT 1, p_variant_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_cart uuid; v_product public.marketplace_products%ROWTYPE;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'authentication required'; END IF;
  IF p_quantity IS NULL OR p_quantity <= 0 OR p_quantity > 1000 THEN RAISE EXCEPTION 'invalid quantity'; END IF;
  SELECT * INTO v_product FROM public.marketplace_products WHERE id = p_product_id AND visible = true AND moderation_status = 'approved' AND (publish_at IS NULL OR publish_at <= now()) AND (unpublish_at IS NULL OR unpublish_at > now());
  IF v_product.id IS NULL THEN RAISE EXCEPTION 'product unavailable'; END IF;
  v_cart := public.marketplace_get_or_create_cart();
  INSERT INTO public.marketplace_cart_items (cart_id, product_id, variant_id, quantity) VALUES (v_cart, p_product_id, p_variant_id, p_quantity)
  ON CONFLICT (cart_id, product_id, variant_id) DO UPDATE SET quantity = public.marketplace_cart_items.quantity + EXCLUDED.quantity, updated_at = now();
  UPDATE public.marketplace_carts SET updated_at = now() WHERE id = v_cart;
  RETURN jsonb_build_object('cart_id', v_cart);
END;
$$;


--
-- Name: marketplace_cart_quote(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.marketplace_cart_quote() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_pricing jsonb;
  v_lines jsonb;
  v_subtotal numeric;
  v_currency text;
  v_discount numeric;
begin
  if auth.uid() is null then raise exception 'authentication required'; end if;
  select coalesce(jsonb_agg(jsonb_build_object(
           'cart_item_id', ci.id, 'product_id', ci.product_id, 'name', p.name,
           'quantity', ci.quantity, 'unit_amount', pp.amount, 'currency', pp.currency,
           'line_total', pp.amount * ci.quantity) order by ci.created_at), '[]'::jsonb),
         coalesce(sum(pp.amount * ci.quantity), 0),
         min(c.currency)
    into v_lines, v_subtotal, v_currency
    from public.marketplace_carts c
    join public.marketplace_cart_items ci on ci.cart_id = c.id
    join public.marketplace_products p on p.id = ci.product_id
    join public.marketplace_product_pricing pp on pp.product_id = ci.product_id
         and (pp.variant_id is not distinct from ci.variant_id) and pp.active
   where c.buyer_id = auth.uid() and c.status = 'active'
     and p.visible and p.moderation_status = 'approved';
  v_pricing := public.reseller_pricing_for(auth.uid());
  v_discount := public.reseller_discount_amount(v_subtotal, (v_pricing->>'percent')::numeric);
  return jsonb_build_object(
    'lines', v_lines,
    'currency', v_currency,
    'subtotal', v_subtotal,
    'discount_percent', (v_pricing->>'percent')::numeric,
    'discount_total', v_discount,
    'total', v_subtotal - v_discount,
    'pricing', v_pricing - 'reseller_id');
end;
$$;


--
-- Name: marketplace_countries(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.marketplace_countries() RETURNS TABLE(country text, product_count bigint)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  select replace(k, 'country:', '') as country, count(*)::bigint as product_count
  from public.marketplace_products p, unnest(p.search_keywords) k
  where k like 'country:%'
    and p.visible
    and p.content_status = 'published'
  group by 1
  order by 1
$$;


--
-- Name: marketplace_country_categories(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.marketplace_country_categories(target text) RETURNS TABLE(category_id uuid, category_name text, category_slug text, product_count bigint)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  select c.id, c.name, c.slug, count(*)::bigint
  from public.marketplace_products p
  join public.marketplace_categories c on c.id = p.category_id
  where p.visible
    and p.content_status = 'published'
    and p.search_keywords @> array['country:' || target]
    and not c.is_hidden
  group by c.id, c.name, c.slug
  order by count(*) desc, c.name
$$;


--
-- Name: marketplace_create_checkout(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.marketplace_create_checkout(p_idempotency_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_cart public.marketplace_carts%rowtype;
  v_order public.marketplace_orders%rowtype;
  v_item record;
  v_subtotal numeric(20,2) := 0;
  v_count integer := 0;
  v_pricing jsonb;
  v_discount numeric(20,2) := 0;
begin
  if auth.uid() is null then raise exception 'authentication required'; end if;
  if p_idempotency_key is null or length(trim(p_idempotency_key)) < 16 then raise exception 'valid idempotency key required'; end if;
  select * into v_order from public.marketplace_orders where idempotency_key = p_idempotency_key and buyer_id = auth.uid();
  if v_order.id is not null then
    return jsonb_build_object('order_id', v_order.id, 'order_number', v_order.order_number, 'status', v_order.status,
      'subtotal', v_order.subtotal, 'discount_total', v_order.discount_total, 'total', v_order.total, 'duplicate', true);
  end if;
  select * into v_cart from public.marketplace_carts where buyer_id = auth.uid() and status = 'active' for update;
  if v_cart.id is null then raise exception 'cart is empty'; end if;
  for v_item in
    select ci.product_id, ci.variant_id, ci.quantity, p.name, p.seller_id, pp.amount, pp.currency
      from public.marketplace_cart_items ci
      join public.marketplace_products p on p.id = ci.product_id
      join public.marketplace_product_pricing pp on pp.product_id = ci.product_id and (pp.variant_id is not distinct from ci.variant_id) and pp.active = true
     where ci.cart_id = v_cart.id and p.visible = true and p.moderation_status = 'approved'
     for update of ci
  loop
    v_count := v_count + 1;
    v_subtotal := v_subtotal + (v_item.amount * v_item.quantity);
  end loop;
  if v_count = 0 then raise exception 'cart has no priced products'; end if;

  -- The partner rule, read from the database for the signed-in user only.
  v_pricing := public.reseller_pricing_for(auth.uid());
  v_discount := public.reseller_discount_amount(v_subtotal, (v_pricing->>'percent')::numeric);

  insert into public.marketplace_orders (buyer_id, currency, subtotal, discount_total, total, idempotency_key, metadata)
    values (auth.uid(), v_cart.currency, v_subtotal, v_discount, v_subtotal - v_discount, p_idempotency_key,
            jsonb_build_object('pricing', v_pricing || jsonb_build_object('list_subtotal', v_subtotal, 'discount_total', v_discount)))
    returning * into v_order;
  for v_item in
    select ci.product_id, ci.variant_id, ci.quantity, p.name, p.seller_id, pp.amount, pp.currency
      from public.marketplace_cart_items ci
      join public.marketplace_products p on p.id = ci.product_id
      join public.marketplace_product_pricing pp on pp.product_id = ci.product_id and (pp.variant_id is not distinct from ci.variant_id) and pp.active = true
     where ci.cart_id = v_cart.id and p.visible = true and p.moderation_status = 'approved'
  loop
    insert into public.marketplace_order_items (order_id, product_id, variant_id, seller_id, product_name, quantity, unit_amount, line_total, currency)
      values (v_order.id, v_item.product_id, v_item.variant_id, v_item.seller_id, v_item.name, v_item.quantity, v_item.amount, v_item.amount * v_item.quantity, v_item.currency);
  end loop;
  insert into public.marketplace_payment_intents (order_id, provider, status, amount, currency, idempotency_key)
    values (v_order.id, 'unconfigured', 'pending', v_order.total, v_order.currency, 'pi-' || p_idempotency_key);
  insert into public.marketplace_order_status_history (order_id, to_status, actor_id, metadata)
    values (v_order.id, v_order.status, auth.uid(), jsonb_build_object('source', 'checkout'));
  update public.marketplace_carts set status = 'checked_out', updated_at = now() where id = v_cart.id;
  insert into public.marketplace_audit_logs (actor_id, action, entity_type, entity_id, metadata)
    values (auth.uid(), 'checkout.created', 'marketplace_order', v_order.id,
            jsonb_build_object('subtotal', v_order.subtotal, 'discount_total', v_order.discount_total,
                               'total', v_order.total, 'currency', v_order.currency, 'pricing', v_pricing));
  return jsonb_build_object('order_id', v_order.id, 'order_number', v_order.order_number, 'status', v_order.status,
    'subtotal', v_order.subtotal, 'discount_total', v_order.discount_total, 'total', v_order.total,
    'payment_status', 'pending', 'duplicate', false);
exception when unique_violation then
  select * into v_order from public.marketplace_orders where idempotency_key = p_idempotency_key and buyer_id = auth.uid();
  if v_order.id is not null then
    return jsonb_build_object('order_id', v_order.id, 'order_number', v_order.order_number, 'status', v_order.status,
      'subtotal', v_order.subtotal, 'discount_total', v_order.discount_total, 'total', v_order.total, 'duplicate', true);
  end if;
  raise;
end;
$$;


--
-- Name: marketplace_get_or_create_cart(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.marketplace_get_or_create_cart() RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_cart uuid;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'authentication required'; END IF;
  SELECT id INTO v_cart FROM public.marketplace_carts WHERE buyer_id = auth.uid() AND status = 'active' FOR UPDATE;
  IF v_cart IS NULL THEN
    INSERT INTO public.marketplace_carts (buyer_id) VALUES (auth.uid()) RETURNING id INTO v_cart;
  END IF;
  RETURN v_cart;
END;
$$;


--
-- Name: marketplace_is_admin(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.marketplace_is_admin() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT public.has_role(auth.uid(), 'admin') OR public.has_role(auth.uid(), 'boss') OR public.has_role(auth.uid(), 'super_admin');
$$;


--
-- Name: marketplace_is_finance(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.marketplace_is_finance() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT public.marketplace_is_admin() OR public.has_role(auth.uid(), 'finance');
$$;


--
-- Name: marketplace_is_seller_member(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.marketplace_is_seller_member(p_seller_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT public.marketplace_is_admin() OR EXISTS (
    SELECT 1 FROM public.marketplace_seller_users su
    WHERE su.seller_id = p_seller_id AND su.user_id = auth.uid()
  );
$$;


--
-- Name: marketplace_order_paid_ledger(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.marketplace_order_paid_ledger() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if new.status = 'paid' and coalesce(old.status, '') <> 'paid' and coalesce(new.total, 0) > 0
     and not exists (select 1 from public.marketplace_ledger_entries
                      where order_id = new.id and entry_type = 'payment') then
    begin
      insert into public.marketplace_ledger_entries (order_id, entry_type, amount, currency, reseller_id, immutable_metadata)
      values (new.id, 'payment', new.total, new.currency,
              case when (new.metadata->'pricing'->>'eligible')::boolean
                   then nullif(new.metadata->'pricing'->>'reseller_id', '')::uuid end,
              jsonb_build_object('order_number', new.order_number, 'subtotal', new.subtotal,
                                 'discount_total', new.discount_total, 'total', new.total,
                                 'pricing', new.metadata->'pricing',
                                 'provider', new.payment_gateway, 'provider_txn', new.payu_txn_id,
                                 'recorded_at', now()));
    exception when others then
      -- Never block a payment being recorded; leave a trace to settle by hand.
      perform public.mm_audit('ledger.payment_failed', 'marketplace_order', new.id::text, null,
                              jsonb_build_object('error', sqlerrm), null);
    end;
  end if;
  return new;
end;
$$;


--
-- Name: marketplace_quote_product(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.marketplace_quote_product(p_product uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_pricing jsonb;
  v_product record;
  v_discount numeric;
begin
  if auth.uid() is null then raise exception 'authentication required'; end if;
  select p.id, p.slug, p.name, pp.amount, pp.currency into v_product
    from public.marketplace_products p
    join public.marketplace_product_pricing pp on pp.product_id = p.id and pp.variant_id is null and pp.active
   where p.id = p_product and p.visible and p.moderation_status = 'approved'
   limit 1;
  if not found then
    return jsonb_build_object('ok', false, 'reason', 'no_published_price');
  end if;
  v_pricing := public.reseller_pricing_for(auth.uid());
  v_discount := public.reseller_discount_amount(v_product.amount, (v_pricing->>'percent')::numeric);
  return jsonb_build_object('ok', true,
    'product', jsonb_build_object('id', v_product.id, 'slug', v_product.slug, 'name', v_product.name),
    'currency', v_product.currency,
    'list_price', v_product.amount,
    'discount_percent', (v_pricing->>'percent')::numeric,
    'discount', v_discount,
    'final_price', v_product.amount - v_discount,
    'pricing', v_pricing - 'reseller_id');
end;
$$;


--
-- Name: marketplace_record_commission_reversal(uuid, uuid, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.marketplace_record_commission_reversal(p_commission_id uuid, p_refund_id uuid, p_amount numeric, p_reason text DEFAULT ''::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
                                                                                                              DECLARE v_id uuid;
                                                                                                              BEGIN
                                                                                                                IF NOT public.marketplace_is_finance() THEN RAISE EXCEPTION 'finance authorization required'; END IF;
                                                                                                                  IF p_amount IS NULL OR p_amount <= 0 THEN RAISE EXCEPTION 'reversal amount must be positive'; END IF;
                                                                                                                    INSERT INTO public.marketplace_commission_reversals (commission_id, refund_id, amount, reason)
                                                                                                                        VALUES (p_commission_id, p_refund_id, p_amount, left(coalesce(p_reason, ''), 500))
                                                                                                                            ON CONFLICT (commission_id, refund_id) DO UPDATE SET amount = EXCLUDED.amount, reason = EXCLUDED.reason
                                                                                                                                RETURNING id INTO v_id;
                                                                                                                                  UPDATE public.marketplace_commissions SET status = 'reversed' WHERE id = p_commission_id AND status <> 'reversed';
                                                                                                                                    RETURN v_id;
                                                                                                                                    END;
                                                                                                                                    $$;


--
-- Name: marketplace_record_payment_event(text, text, uuid, text, boolean, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.marketplace_record_payment_event(p_provider text, p_provider_event_id text, p_payment_intent_id uuid, p_event_type text, p_signature_verified boolean, p_payload jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_event public.marketplace_payment_events%ROWTYPE;
BEGIN
  IF NOT public.marketplace_is_finance() THEN RAISE EXCEPTION 'finance authorization required'; END IF;
  IF NOT p_signature_verified THEN RAISE EXCEPTION 'verified provider signature required'; END IF;
  INSERT INTO public.marketplace_payment_events (provider, provider_event_id, payment_intent_id, event_type, signature_verified, payload)
    VALUES (p_provider, p_provider_event_id, p_payment_intent_id, p_event_type, true, p_payload)
    ON CONFLICT (provider, provider_event_id) DO NOTHING
    RETURNING * INTO v_event;
  IF v_event.id IS NULL THEN SELECT * INTO v_event FROM public.marketplace_payment_events WHERE provider = p_provider AND provider_event_id = p_provider_event_id; END IF;
  RETURN jsonb_build_object('event_id', v_event.id, 'duplicate', v_event.created_at < now() - interval '1 second');
END;
$$;


--
-- Name: marketplace_validate_attribution(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.marketplace_validate_attribution() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_code public.marketplace_referral_codes%rowtype;
  v_session public.marketplace_referral_sessions%rowtype;
begin
  if new.referral_code_id is not null then
    select * into v_code from public.marketplace_referral_codes where id = new.referral_code_id;
    if v_code.id is null or not v_code.active then
      raise exception 'referral code is not active';
    end if;
    if v_code.affiliate_partner_id is not null
       and new.affiliate_partner_id is distinct from v_code.affiliate_partner_id then
      raise exception 'affiliate does not match referral code';
    end if;
    if v_code.influencer_profile_id is not null
       and new.influencer_profile_id is distinct from v_code.influencer_profile_id then
      raise exception 'influencer does not match referral code';
    end if;
    if v_code.reseller_id is not null
       and new.reseller_id is distinct from v_code.reseller_id then
      raise exception 'reseller does not match referral code';
    end if;
  end if;

  if new.session_id is not null then
    select * into v_session from public.marketplace_referral_sessions where id = new.session_id;
    if v_session.id is null then
      raise exception 'referral session does not exist';
    end if;
    if v_session.affiliate_partner_id is not null
       and new.affiliate_partner_id is distinct from v_session.affiliate_partner_id then
      raise exception 'affiliate does not match referral session';
    end if;
    if v_session.influencer_profile_id is not null
       and new.influencer_profile_id is distinct from v_session.influencer_profile_id then
      raise exception 'influencer does not match referral session';
    end if;
    if v_session.reseller_id is not null
       and new.reseller_id is distinct from v_session.reseller_id then
      raise exception 'reseller does not match referral session';
    end if;
  end if;

  return new;
end;
$$;


--
-- Name: mm_active_rows(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_active_rows(p_surface text DEFAULT 'desktop'::text) RETURNS TABLE(id uuid, key text, title text, subtitle text, row_type text, source text, category_id uuid, collection_key text, manual_product_ids uuid[], sort_by text, item_limit integer, cta_label text, cta_href text, sort_order integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select s.id, s.key, s.title, s.subtitle, s.row_type, s.source, s.category_id,
         s.collection_key, s.manual_product_ids, s.sort_by, s.item_limit,
         s.cta_label, s.cta_href, s.sort_order
  from public.marketplace_homepage_sections s
  where s.status = 'published'
    and s.enabled
    and (s.starts_at is null or s.starts_at <= now())
    and (s.ends_at is null or s.ends_at > now())
    and case when p_surface = 'mobile' then s.visible_mobile else s.visible_desktop end
  order by s.sort_order, s.priority desc;
$$;


--
-- Name: mm_ai_bulk_cancel(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_ai_bulk_cancel(p_job uuid, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if not public.mm_is_operator() then
    return jsonb_build_object('ok', false, 'reason','not_authorized');
  end if;
  update public.ai_content_job_items set status = 'SKIPPED',
         skip_reason = coalesce(p_reason,'The job was cancelled.'), updated_at = now()
   where job_id = p_job and status in ('QUEUED','PROCESSING');
  update public.ai_content_jobs set status = 'CANCELLED', finished_at = now(),
         last_error = p_reason where id = p_job;
  perform public.mm_audit('ai_content.bulk.cancel', 'ai_content_job', p_job::text, null, null, p_reason);
  return jsonb_build_object('ok', true);
end;
$$;


--
-- Name: mm_ai_bulk_claim(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_ai_bulk_claim(p_job uuid, p_limit integer DEFAULT NULL::integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare s record; j record; v_rows jsonb; v_limit integer;
begin
  if not public.mm_is_operator() then
    return jsonb_build_object('ok', false, 'reason','not_authorized');
  end if;
  select * into s from public.ai_content_settings where id;
  select * into j from public.ai_content_jobs where id = p_job;
  if not found then return jsonb_build_object('ok', false, 'reason','job_not_found'); end if;
  if j.status in ('CANCELLED','COMPLETED') then
    return jsonb_build_object('ok', true, 'done', true, 'status', j.status, 'products', '[]'::jsonb);
  end if;

  v_limit := least(coalesce(p_limit, s.bulk_batch_size), 100);

  update public.ai_content_jobs
     set status = 'PROCESSING', started_at = coalesce(started_at, now())
   where id = p_job;

  with picked as (
    select ji.id from public.ai_content_job_items ji
     where ji.job_id = p_job and ji.status = 'QUEUED'
     order by ji.id
     limit v_limit
     -- Two workers on the same job never take the same product.
     for update skip locked)
  update public.ai_content_job_items ji
     set status = 'PROCESSING', attempts = ji.attempts + 1, updated_at = now()
    from picked
   where ji.id = picked.id;

  select coalesce(jsonb_agg(jsonb_build_object(
           'product_id', ji.product_id, 'product', p.name, 'slug', p.slug,
           'attempts', ji.attempts)), '[]'::jsonb)
    into v_rows
    from public.ai_content_job_items ji
    join public.marketplace_products p on p.id = ji.product_id
   where ji.job_id = p_job and ji.status = 'PROCESSING';

  return jsonb_build_object('ok', true, 'job_id', p_job,
    'types', to_jsonb(j.content_types), 'language', j.language,
    'products', v_rows,
    'done', jsonb_array_length(v_rows) = 0,
    'remaining', (select count(*) from public.ai_content_job_items
                   where job_id = p_job and status in ('QUEUED','PROCESSING')));
end;
$$;


--
-- Name: mm_ai_bulk_create(text, text[], jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_ai_bulk_create(p_scope text, p_types text[], p_filters jsonb DEFAULT '{}'::jsonb, p_language text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  s record;
  v_job uuid;
  v_lang text;
  v_types text[] := '{}';
  v_type text;
  v_total integer;
begin
  if not public.mm_is_operator() then
    return jsonb_build_object('ok', false, 'reason','not_authorized');
  end if;
  select * into s from public.ai_content_settings where id;
  v_lang := coalesce(p_language, s.default_language);

  foreach v_type in array coalesce(p_types, array[]::text[]) loop
    if coalesce((s.blocks ->> v_type)::boolean, false) then v_types := v_types || v_type; end if;
  end loop;
  if array_length(v_types, 1) is null then
    return jsonb_build_object('ok', false, 'reason','no_enabled_blocks');
  end if;

  insert into public.ai_content_jobs (scope, filters, content_types, language, created_by)
  values (p_scope, coalesce(p_filters,'{}'::jsonb), v_types, v_lang, auth.uid())
  returning id into v_job;

  -- The product set, resolved once and written down. Every scope excludes
  -- deleted and hidden products: there is no point writing copy for a page
  -- nobody can reach.
  insert into public.ai_content_job_items (job_id, product_id)
  select v_job, p.id
    from public.marketplace_products p
   where p.deleted_at is null
     and p.visible
     and case p_scope
           when 'selected' then p.id = any (
             coalesce((select array_agg(x::uuid) from jsonb_array_elements_text(p_filters -> 'ids') x),
                      array[]::uuid[]))
           when 'category' then p.category_id = nullif(p_filters ->> 'category_id','')::uuid
           when 'missing_description' then coalesce(p.description,'') = ''
           when 'missing_seo' then not exists (
             select 1 from public.seo_pages sp
              where sp.product_id = p.id and coalesce(sp.meta_description,'') <> '')
           when 'rejected_content' then exists (
             select 1 from public.ai_content_items i
              where i.product_id = p.id and i.status = 'REJECTED')
           when 'stale' then exists (
             select 1 from public.ai_content_items i
              where i.product_id = p.id and i.stale)
           when 'all_eligible' then p.moderation_status = 'approved'
           else false
         end
     -- 29. A product whose requested blocks are all already published is not
     -- queued at all, rather than queued and then skipped.
     and not (
       select bool_and(exists (
         select 1 from public.ai_content_items i
          where i.product_id = p.id and i.content_type = t and i.language = v_lang
            and i.status = 'PUBLISHED' and not i.stale))
         from unnest(v_types) t)
  on conflict (job_id, product_id) do nothing;

  select count(*) into v_total from public.ai_content_job_items where job_id = v_job;
  update public.ai_content_jobs set total = v_total,
         status = case when v_total = 0 then 'COMPLETED' else 'QUEUED' end,
         finished_at = case when v_total = 0 then now() else null end
   where id = v_job;

  perform public.mm_audit('ai_content.bulk.create', 'ai_content_job', v_job::text, null,
    jsonb_build_object('scope', p_scope, 'types', to_jsonb(v_types), 'total', v_total,
                       'language', v_lang),
    format('Bulk generation queued for %s products', v_total));

  return jsonb_build_object('ok', true, 'job_id', v_job, 'total', v_total,
    'types', to_jsonb(v_types), 'language', v_lang,
    'batch_size', s.bulk_batch_size,
    'detail', case when v_total = 0
                   then 'Nothing matched, or every match already has this content published.'
                   else null end);
end;
$$;


--
-- Name: mm_ai_bulk_mark(uuid, uuid, text, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_ai_bulk_mark(p_job uuid, p_product uuid, p_status text, p_generation uuid DEFAULT NULL::uuid, p_error text DEFAULT NULL::text, p_skip_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare j record;
begin
  if not public.mm_is_operator() then
    return jsonb_build_object('ok', false, 'reason','not_authorized');
  end if;
  if p_status not in ('COMPLETED','FAILED','SKIPPED','NEEDS_REVIEW') then
    return jsonb_build_object('ok', false, 'reason','bad_status');
  end if;

  update public.ai_content_job_items
     set status = p_status, generation_id = p_generation,
         error = left(p_error, 1000), skip_reason = p_skip_reason, updated_at = now()
   where job_id = p_job and product_id = p_product;

  -- The counters are recomputed from the items rather than incremented, so a
  -- retry or a double call cannot drift them away from the truth.
  -- The alias is deliberately not j: a plpgsql record of that name is in scope
  -- and would shadow the table inside the SET clause.
  update public.ai_content_jobs t set
    completed = c.completed, failed = c.failed, skipped = c.skipped, needs_review = c.needs_review,
    last_error = coalesce(left(p_error, 500), t.last_error),
    status = case when c.pending = 0 then
                    case when c.completed + c.needs_review = 0 then 'FAILED' else 'COMPLETED' end
                  else 'PROCESSING' end,
    finished_at = case when c.pending = 0 then now() else null end
  from (
    select count(*) filter (where status = 'COMPLETED') completed,
           count(*) filter (where status = 'FAILED') failed,
           count(*) filter (where status = 'SKIPPED') skipped,
           count(*) filter (where status = 'NEEDS_REVIEW') needs_review,
           count(*) filter (where status in ('QUEUED','PROCESSING')) pending
      from public.ai_content_job_items where job_id = p_job) c
  where t.id = p_job;

  select * into j from public.ai_content_jobs where id = p_job;
  return jsonb_build_object('ok', true, 'status', j.status, 'completed', j.completed,
    'failed', j.failed, 'skipped', j.skipped, 'needs_review', j.needs_review,
    'remaining', j.total - (j.completed + j.failed + j.skipped + j.needs_review));
end;
$$;


--
-- Name: mm_ai_bulk_retry(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_ai_bulk_retry(p_job uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_count integer;
begin
  if not public.mm_is_operator() then
    return jsonb_build_object('ok', false, 'reason','not_authorized');
  end if;
  update public.ai_content_job_items
     set status = 'QUEUED', error = null, updated_at = now()
   where job_id = p_job and status = 'FAILED';
  get diagnostics v_count = row_count;

  update public.ai_content_jobs
     set status = case when v_count > 0 then 'QUEUED' else status end,
         finished_at = case when v_count > 0 then null else finished_at end,
         failed = greatest(failed - v_count, 0)
   where id = p_job;

  perform public.mm_audit('ai_content.bulk.retry', 'ai_content_job', p_job::text, null,
    jsonb_build_object('requeued', v_count), 'Failed items requeued');

  return jsonb_build_object('ok', true, 'requeued', v_count);
end;
$$;


--
-- Name: mm_ai_can_approve(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_ai_can_approve() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select public.mm_is_operator() and (
    -- A service-role or migration context is already trusted by mm_is_operator.
    auth.uid() is null
    or exists (select 1 from public.user_roles ur
                where ur.user_id = auth.uid()
                  and ur.role in ('admin','boss','founder','super_admin','boss_owner'))
  );
$$;


--
-- Name: mm_ai_content_console(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_ai_content_console(p_query jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  s record;
  v_limit integer := least(greatest(coalesce((p_query ->> 'limit')::int, 25), 1), 200);
  v_offset integer := greatest(coalesce((p_query ->> 'offset')::int, 0), 0);
  v_search text := nullif(btrim(coalesce(p_query ->> 'search','')), '');
  v_product uuid := nullif(p_query ->> 'product_id','')::uuid;
  v_type text := nullif(p_query ->> 'content_type','');
  v_status text := nullif(p_query ->> 'status','');
  v_lang text := nullif(p_query ->> 'language','');
  v_legal text := nullif(p_query ->> 'legal_state','');
  v_from timestamptz := nullif(p_query ->> 'from','')::timestamptz;
  v_to timestamptz := nullif(p_query ->> 'to','')::timestamptz;
  v_total integer;
  v_rows jsonb;
begin
  if not public.mm_is_operator() then
    return jsonb_build_object('ok', false, 'reason','not_authorized');
  end if;
  select * into s from public.ai_content_settings where id;

  -- 47/48. Filtering and paging happen here, in the database. The browser never
  -- receives the catalogue.
  select count(*) into v_total
    from public.ai_content_items i
    join public.marketplace_products p on p.id = i.product_id
   where (v_product is null or i.product_id = v_product)
     and (v_type is null or i.content_type = v_type)
     and (v_status is null or i.status = v_status)
     and (v_lang is null or i.language = v_lang)
     and (v_legal is null or i.legal_state = v_legal)
     and (v_from is null or i.updated_at >= v_from)
     and (v_to is null or i.updated_at <= v_to)
     and (v_search is null or p.name ilike '%' || v_search || '%' or p.slug ilike '%' || v_search || '%');

  select coalesce(jsonb_agg(r order by r ->> 'updated_at' desc), '[]'::jsonb) into v_rows from (
    select jsonb_build_object(
      'id', i.id, 'product_id', i.product_id, 'product', p.name, 'slug', p.slug,
      'content_type', i.content_type, 'language', i.language, 'status', i.status,
      'provenance', i.provenance, 'human_edited', i.human_edited,
      'version', i.current_version,
      'content', left(coalesce(i.content,''), 4000),
      'items', i.content_json,
      'ai_original', left(coalesce(i.ai_original,''), 4000),
      'ai_original_items', i.ai_original_json,
      'validation_state', i.validation_state, 'validation', i.validation,
      'legal_state', i.legal_state, 'legal_findings', i.legal_findings,
      'duplicate_state', i.duplicate_state, 'duplicate_score', i.duplicate_score,
      'duplicate_of', (select mp.name from public.marketplace_products mp where mp.id = i.duplicate_of),
      'stale', i.stale, 'stale_reason', i.stale_reason,
      'rejection_code', i.rejection_code, 'rejection_reason', i.rejection_reason,
      'publish_state', i.publish_state, 'publish_targets', i.publish_targets,
      'generated_at', i.generated_at, 'approved_at', i.approved_at, 'published_at', i.published_at,
      'updated_at', i.updated_at,
      'versions', (select count(*) from public.ai_content_versions v where v.item_id = i.id)) as r
      from public.ai_content_items i
      join public.marketplace_products p on p.id = i.product_id
     where (v_product is null or i.product_id = v_product)
       and (v_type is null or i.content_type = v_type)
       and (v_status is null or i.status = v_status)
       and (v_lang is null or i.language = v_lang)
       and (v_legal is null or i.legal_state = v_legal)
       and (v_from is null or i.updated_at >= v_from)
       and (v_to is null or i.updated_at <= v_to)
       and (v_search is null or p.name ilike '%' || v_search || '%' or p.slug ilike '%' || v_search || '%')
     order by i.updated_at desc
     limit v_limit offset v_offset) q;

  return jsonb_build_object(
    'ok', true,
    'settings', to_jsonb(s),
    'binding', public.mm_ai_provider_binding(),
    'can_approve', public.mm_ai_can_approve(),

    -- 18. Every one of these is a count of rows, not a number in the markup.
    'stats', jsonb_build_object(
      'generated_today', (select count(*) from public.ai_content_generations
                           where status = 'SUCCEEDED' and created_at >= date_trunc('day', now())),
      'failed_today', (select count(*) from public.ai_content_generations
                        where status in ('FAILED','REJECTED_OUTPUT','NOT_CONFIGURED')
                          and created_at >= date_trunc('day', now())),
      'awaiting_review', (select count(*) from public.ai_content_items where status = 'IN_REVIEW'),
      'approved_waiting_publish', (select count(*) from public.ai_content_items where status = 'APPROVED'),
      'auto_published', (select count(*) from public.ai_content_reviews r
                          where r.decision = 'APPROVED'
                            and r.reason = 'Approved automatically under the AUTO_PUBLISH policy.'),
      'published', (select count(*) from public.ai_content_items where status = 'PUBLISHED'),
      'rejected', (select count(*) from public.ai_content_items where status = 'REJECTED'),
      'failed', (select count(*) from public.ai_content_items where status = 'FAILED'),
      'archived', (select count(*) from public.ai_content_items where status = 'ARCHIVED'),
      'stale', (select count(*) from public.ai_content_items where stale and status <> 'ARCHIVED'),
      'legal_blocked', (select count(*) from public.ai_content_items where legal_state = 'BLOCKED'),
      'legal_review', (select count(*) from public.ai_content_items where legal_state = 'REVIEW_REQUIRED'),
      'duplicates', (select count(*) from public.ai_content_items where duplicate_state = 'DUPLICATE'),
      'products_total', (select count(*) from public.marketplace_products
                          where visible and deleted_at is null),
      'products_with_content', (select count(distinct product_id) from public.ai_content_items),
      'products_missing_description', (select count(*) from public.marketplace_products
                                        where visible and deleted_at is null
                                          and coalesce(description,'') = ''),
      'products_missing_seo', (select count(*) from public.marketplace_products p
                                where p.visible and p.deleted_at is null
                                  and not exists (select 1 from public.seo_pages sp
                                                   where sp.product_id = p.id
                                                     and coalesce(sp.meta_description,'') <> ''))),

    -- 17. The status breakdown the dashboard draws from.
    'by_status', (select coalesce(jsonb_object_agg(status, n), '{}'::jsonb)
                    from (select status, count(*) n from public.ai_content_items group by status) x),
    'by_type', (select coalesce(jsonb_object_agg(content_type, n), '{}'::jsonb)
                  from (select content_type, count(*) n from public.ai_content_items group by content_type) x),

    'total', v_total,
    'rows', v_rows,

    -- 54. The approval queue, oldest first, because that is the order it should
    -- be worked in.
    'queue', (select coalesce(jsonb_agg(jsonb_build_object(
                'id', i.id, 'product', p.name, 'slug', p.slug,
                'content_type', i.content_type, 'language', i.language,
                'version', i.current_version, 'human_edited', i.human_edited,
                'validation_state', i.validation_state,
                'legal_state', i.legal_state,
                'duplicate_state', i.duplicate_state,
                'stale', i.stale,
                'submitted_at', i.submitted_at,
                'preview', left(coalesce(i.content, i.content_json::text, ''), 240)) order by i.submitted_at), '[]'::jsonb)
                from public.ai_content_items i
                join public.marketplace_products p on p.id = i.product_id
               where i.status = 'IN_REVIEW' limit 100),

    -- 29. Bulk jobs with their real item counts.
    'jobs', (select coalesce(jsonb_agg(jsonb_build_object(
               'id', j.id, 'scope', j.scope, 'status', j.status,
               'types', to_jsonb(j.content_types), 'language', j.language,
               'total', j.total, 'completed', j.completed, 'failed', j.failed,
               'skipped', j.skipped, 'needs_review', j.needs_review,
               'queued', (select count(*) from public.ai_content_job_items ji
                           where ji.job_id = j.id and ji.status = 'QUEUED'),
               'processing', (select count(*) from public.ai_content_job_items ji
                               where ji.job_id = j.id and ji.status = 'PROCESSING'),
               'last_error', j.last_error,
               'created_at', j.created_at, 'finished_at', j.finished_at) order by j.created_at desc), '[]'::jsonb)
               from (select * from public.ai_content_jobs order by created_at desc limit 10) j),

    -- 27. Usage exactly as the provider reported it, and a flag saying whether
    -- it reported anything at all.
    'usage', jsonb_build_object(
      'today', (select coalesce(jsonb_agg(to_jsonb(u)), '[]'::jsonb)
                  from public.ai_content_usage u where u.usage_date = current_date),
      'last_30_days', (select jsonb_build_object(
          'requests', coalesce(sum(requests),0), 'succeeded', coalesce(sum(succeeded),0),
          'failed', coalesce(sum(failed),0), 'not_configured', coalesce(sum(not_configured),0),
          'tokens_in', coalesce(sum(tokens_in),0), 'tokens_out', coalesce(sum(tokens_out),0),
          'cost_usd', coalesce(sum(cost_usd),0),
          'usage_available', coalesce(bool_or(usage_available), false),
          'cost_available', coalesce(bool_or(cost_available), false))
        from public.ai_content_usage where usage_date >= current_date - 30)),

    -- 26. The generation record, which is the only place a failure explains
    -- itself.
    'generations', (select coalesce(jsonb_agg(jsonb_build_object(
        'id', g.id, 'product', p.name, 'types', to_jsonb(g.content_types),
        'status', g.status, 'provider', g.provider_slug, 'model', g.model_id,
        'prompt_key', g.prompt_key, 'prompt_version', g.prompt_version,
        'error_code', g.error_code, 'error_detail', left(coalesce(g.error_detail,''), 400),
        'http_status', g.http_status,
        'tokens_in', g.tokens_in, 'tokens_out', g.tokens_out,
        'usage_available', g.usage_available, 'cost_available', g.cost_available,
        'latency_ms', g.latency_ms,
        'context_fields', to_jsonb(g.context_fields), 'missing_fields', to_jsonb(g.missing_fields),
        'blocks_returned', to_jsonb(g.blocks_returned),
        'created_at', g.created_at) order by g.created_at desc), '[]'::jsonb)
      from (select * from public.ai_content_generations order by created_at desc limit 25) g
      join public.marketplace_products p on p.id = g.product_id),

    'templates', (select coalesce(jsonb_agg(jsonb_build_object(
        'key', key, 'label', label, 'active', active,
        'sections', structure -> 'long_sections', 'guidance', guidance) order by key), '[]'::jsonb)
      from public.ai_content_templates),

    'legal_rules', (select coalesce(jsonb_agg(jsonb_build_object(
        'code', code, 'label', label, 'category', category, 'severity', severity,
        'action', action, 'active', active) order by severity desc, code), '[]'::jsonb)
      from public.ai_content_legal_rules),

    -- 39. The audit trail, through the module's own window onto it.
    'audit', (select coalesce(jsonb_agg(jsonb_build_object(
        'at', created_at, 'action', action, 'actor', actor, 'role', actor_role,
        'entity', entity_type, 'reason', reason) order by created_at desc), '[]'::jsonb)
      from (select * from public.ai_content_audit_logs order by created_at desc limit 40) a));
end;
$$;


--
-- Name: mm_ai_context(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_ai_context(p_product uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  p record;
  v_category text;
  v_facts jsonb := '{}'::jsonb;
  v_present text[] := '{}';
  v_missing text[] := '{}';
  v_demo boolean;
  v_template record;
  v_terms text;
begin
  if not public.mm_is_operator() then
    return jsonb_build_object('ok', false, 'reason', 'not_authorized');
  end if;

  select * into p from public.marketplace_products where id = p_product;
  if not found then
    return jsonb_build_object('ok', false, 'reason', 'product_not_found');
  end if;

  select c.name into v_category from public.marketplace_categories c where c.id = p.category_id;

  -- A demo is a fact about the product, so the copy may mention that one
  -- exists. The URL itself is not given to the model.
  select exists (
    select 1 from public.product_demo_urls d
     where d.product_id = p.id and d.status = 'active'
  ) into v_demo;

  -- Each fact is added only when the product actually carries it. A null field
  -- becomes an entry in missing_fields, which the prompt turns into a
  -- "not available" instruction rather than an invitation to invent.
  v_facts := jsonb_build_object('name', p.name, 'slug', p.slug);
  v_present := array['name'];

  if v_category is not null then
    v_facts := v_facts || jsonb_build_object('category', v_category);
    v_present := v_present || 'category'::text;
  else v_missing := v_missing || 'category'::text; end if;

  if coalesce(p.industry_label,'') <> '' then
    v_facts := v_facts || jsonb_build_object('industry', p.industry_label);
    v_present := v_present || 'industry'::text;
  else v_missing := v_missing || 'industry'::text; end if;

  if coalesce(p.subcategory,'') <> '' then
    v_facts := v_facts || jsonb_build_object('subcategory', p.subcategory);
    v_present := v_present || 'subcategory'::text;
  else v_missing := v_missing || 'subcategory'::text; end if;

  if coalesce(p.description,'') <> '' then
    v_facts := v_facts || jsonb_build_object('existing_description', p.description);
    v_present := v_present || 'existing_description'::text;
  else v_missing := v_missing || 'existing_description'::text; end if;

  if jsonb_typeof(p.features) = 'array' and jsonb_array_length(p.features) > 0 then
    v_facts := v_facts || jsonb_build_object('verified_features', p.features);
    v_present := v_present || 'verified_features'::text;
  else v_missing := v_missing || 'verified_features'::text; end if;

  if coalesce(p.benefits,'') <> '' then
    v_facts := v_facts || jsonb_build_object('verified_benefits', p.benefits);
    v_present := v_present || 'verified_benefits'::text;
  else v_missing := v_missing || 'verified_benefits'::text; end if;

  if coalesce(p.modules,'') <> '' then
    v_facts := v_facts || jsonb_build_object('modules', p.modules);
    v_present := v_present || 'modules'::text;
  else v_missing := v_missing || 'modules'::text; end if;

  if coalesce(p.integrations,'') <> '' then
    v_facts := v_facts || jsonb_build_object('integrations', p.integrations);
    v_present := v_present || 'integrations'::text;
  else v_missing := v_missing || 'integrations'::text; end if;

  if coalesce(p.target_audience,'') <> '' then
    v_facts := v_facts || jsonb_build_object('target_audience', p.target_audience);
    v_present := v_present || 'target_audience'::text;
  else v_missing := v_missing || 'target_audience'::text; end if;

  if coalesce(p.price_label,'') <> '' and lower(p.price_label) <> 'custom' then
    v_facts := v_facts || jsonb_build_object('price', p.price_label,
                                             'price_period', coalesce(p.price_period,'one-time'));
    v_present := v_present || 'price'::text;
  else v_missing := v_missing || 'price'::text; end if;

  if coalesce(p.license,'') <> '' then
    v_facts := v_facts || jsonb_build_object('licence', p.license);
    v_present := v_present || 'licence'::text;
  else v_missing := v_missing || 'licence'::text; end if;

  if coalesce(p.deployment,'') <> '' then
    v_facts := v_facts || jsonb_build_object('deployment', p.deployment);
    v_present := v_present || 'deployment'::text;
  else v_missing := v_missing || 'deployment'::text; end if;

  if array_length(p.tech_stack, 1) > 0 then
    v_facts := v_facts || jsonb_build_object('technology', to_jsonb(p.tech_stack));
    v_present := v_present || 'technology'::text;
  else v_missing := v_missing || 'technology'::text; end if;

  -- The platform columns, collapsed into one list of what the record confirms.
  v_terms := nullif(concat_ws(', ',
    nullif(p.frontend,''), nullif(p.backend,''), nullif(p.database,''),
    nullif(p.mobile,''), nullif(p.pwa,''), nullif(p.cloud,''), nullif(p.offline,'')), '');
  if v_terms is not null then
    v_facts := v_facts || jsonb_build_object('platform', v_terms);
    v_present := v_present || 'platform'::text;
  else v_missing := v_missing || 'platform'::text; end if;

  if array_length(p.tags, 1) > 0 then
    v_facts := v_facts || jsonb_build_object('tags', to_jsonb(p.tags));
    v_present := v_present || 'tags'::text;
  end if;

  if array_length(p.search_keywords, 1) > 0 then
    -- The country markers are routing data, not product facts.
    v_facts := v_facts || jsonb_build_object('existing_keywords',
      to_jsonb((select array_agg(k) from unnest(p.search_keywords) k where k not like 'country:%')));
    v_present := v_present || 'existing_keywords'::text;
  end if;

  v_facts := v_facts || jsonb_build_object('has_live_demo', v_demo);
  if not v_demo then v_missing := v_missing || 'live_demo'::text; end if;

  -- 37. Which template's structure suits this product. Structure only: a
  -- template never contributes a fact.
  -- The template with the most matching terms wins. Picking the first match
  -- alphabetically chose 'mobile' for a madrasa platform, because its tech
  -- stack reads "Web Application"; a count settles it in favour of the
  -- template that actually fits.
  select t.*, x.hits into v_template
    from public.ai_content_templates t
    join lateral (
      select count(*) as hits from unnest(t.match_terms) m
       where lower(coalesce(v_category,'') || ' ' || coalesce(p.industry_label,'') || ' ' ||
                   coalesce(p.subcategory,'') || ' ' || coalesce(array_to_string(p.tags,' '),'') || ' ' ||
                   coalesce(array_to_string(p.tech_stack,' '),'') || ' ' || p.name) like '%' || m || '%'
    ) x on x.hits > 0
   where t.active
   order by x.hits desc, t.key limit 1;

  return jsonb_build_object(
    'ok', true,
    'product_id', p.id,
    'product_name', p.name,
    'slug', p.slug,
    'visible', p.visible,
    'moderation_status', p.moderation_status,
    'deleted', p.deleted_at is not null,
    'facts', v_facts,
    'present_fields', to_jsonb(v_present),
    'missing_fields', to_jsonb(v_missing),
    'template_key', v_template.key,
    'template_label', v_template.label,
    'template_structure', coalesce(v_template.structure, '{}'::jsonb),
    'template_guidance', coalesce(v_template.guidance, ''),
    -- 45. The fingerprint. Recomputed whenever the product changes; content
    -- generated against a different fingerprint is stale by definition.
    'context_hash', md5(v_facts::text)
  );
end;
$$;


--
-- Name: mm_ai_context_hash(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_ai_context_hash(p_product uuid) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select md5((
    jsonb_build_object('name', p.name, 'slug', p.slug)
    || case when c.name is not null then jsonb_build_object('category', c.name) else '{}'::jsonb end
    || case when coalesce(p.industry_label,'') <> '' then jsonb_build_object('industry', p.industry_label) else '{}'::jsonb end
    || case when coalesce(p.subcategory,'') <> '' then jsonb_build_object('subcategory', p.subcategory) else '{}'::jsonb end
    || case when coalesce(p.description,'') <> '' then jsonb_build_object('existing_description', p.description) else '{}'::jsonb end
    || case when jsonb_typeof(p.features) = 'array' and jsonb_array_length(p.features) > 0 then jsonb_build_object('verified_features', p.features) else '{}'::jsonb end
    || case when coalesce(p.benefits,'') <> '' then jsonb_build_object('verified_benefits', p.benefits) else '{}'::jsonb end
    || case when coalesce(p.modules,'') <> '' then jsonb_build_object('modules', p.modules) else '{}'::jsonb end
    || case when coalesce(p.integrations,'') <> '' then jsonb_build_object('integrations', p.integrations) else '{}'::jsonb end
    || case when coalesce(p.target_audience,'') <> '' then jsonb_build_object('target_audience', p.target_audience) else '{}'::jsonb end
    || case when coalesce(p.price_label,'') <> '' and lower(p.price_label) <> 'custom'
             then jsonb_build_object('price', p.price_label, 'price_period', coalesce(p.price_period,'one-time')) else '{}'::jsonb end
    || case when coalesce(p.license,'') <> '' then jsonb_build_object('licence', p.license) else '{}'::jsonb end
    || case when coalesce(p.deployment,'') <> '' then jsonb_build_object('deployment', p.deployment) else '{}'::jsonb end
    || case when array_length(p.tech_stack,1) > 0 then jsonb_build_object('technology', to_jsonb(p.tech_stack)) else '{}'::jsonb end
    || case when nullif(concat_ws(', ', nullif(p.frontend,''), nullif(p.backend,''), nullif(p.database,''),
                                  nullif(p.mobile,''), nullif(p.pwa,''), nullif(p.cloud,''), nullif(p.offline,'')),'') is not null
             then jsonb_build_object('platform', concat_ws(', ', nullif(p.frontend,''), nullif(p.backend,''), nullif(p.database,''),
                                                           nullif(p.mobile,''), nullif(p.pwa,''), nullif(p.cloud,''), nullif(p.offline,'')))
             else '{}'::jsonb end
    || case when array_length(p.tags,1) > 0 then jsonb_build_object('tags', to_jsonb(p.tags)) else '{}'::jsonb end
    || case when array_length(p.search_keywords,1) > 0 then jsonb_build_object('existing_keywords',
              to_jsonb((select array_agg(k) from unnest(p.search_keywords) k where k not like 'country:%'))) else '{}'::jsonb end
    || jsonb_build_object('has_live_demo', exists (
         select 1 from public.product_demo_urls d where d.product_id = p.id and d.status = 'active'))
  )::text)
  from public.marketplace_products p
  left join public.marketplace_categories c on c.id = p.category_id
  where p.id = p_product;
$$;


--
-- Name: mm_ai_duplicate_check(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_ai_duplicate_check(p_product uuid, p_text text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  s record;
  v_best record;
begin
  select duplicate_threshold, high_similarity_threshold into s
    from public.ai_content_settings where id;

  if coalesce(p_text,'') = '' or length(p_text) < 40 then
    return jsonb_build_object('state','UNCHECKED','score',null,'product',null,
                              'reason','too short to compare');
  end if;

  select x.product_id, x.name, x.score into v_best from (
    select p.id as product_id, p.name,
           similarity(left(p.description, 1200), left(p_text, 1200)) as score
      from public.marketplace_products p
     where p.id <> p_product
       and p.deleted_at is null
       and coalesce(p.description,'') <> ''
       and length(p.description) >= 40
       -- The trigram index does the narrowing; similarity() then ranks.
       and left(p.description, 1200) % left(p_text, 1200)
    union all
    select i.product_id, mp.name,
           similarity(left(i.content, 1200), left(p_text, 1200)) as score
      from public.ai_content_items i
      join public.marketplace_products mp on mp.id = i.product_id
     where i.product_id <> p_product
       and i.status = 'PUBLISHED'
       and i.content_type in ('short_description','long_description','summary')
       and coalesce(i.content,'') <> ''
       and left(i.content, 1200) % left(p_text, 1200)
  ) x
  order by x.score desc
  limit 1;

  if v_best.score is null then
    return jsonb_build_object('state','UNIQUE','score',0,'product',null,'product_name',null);
  end if;

  return jsonb_build_object(
    'state', case
               when v_best.score >= s.duplicate_threshold then 'DUPLICATE'
               when v_best.score >= s.high_similarity_threshold then 'HIGH_SIMILARITY'
               else 'UNIQUE' end,
    'score', round(v_best.score::numeric, 4),
    'product', v_best.product_id,
    'product_name', v_best.name);
end;
$$;


--
-- Name: mm_ai_generation_finish(uuid, text, jsonb, jsonb, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_ai_generation_finish(p_generation uuid, p_status text, p_parsed jsonb DEFAULT NULL::jsonb, p_raw jsonb DEFAULT NULL::jsonb, p_usage jsonb DEFAULT NULL::jsonb, p_error jsonb DEFAULT NULL::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  g record;
  s record;
  v_type text;
  v_item record;
  v_key text;
  v_value jsonb;
  v_content text;
  v_json jsonb;
  v_written text[] := '{}';
  v_empty text[] := '{}';
  v_version integer;
  v_policy text;
  v_next text;
  v_validation jsonb;
  v_results jsonb := '[]'::jsonb;
begin
  if not public.mm_is_operator() then
    return jsonb_build_object('ok', false, 'reason', 'not_authorized');
  end if;

  select * into g from public.ai_content_generations where id = p_generation;
  if not found then return jsonb_build_object('ok', false, 'reason','generation_not_found'); end if;
  if g.status <> 'RUNNING' then
    return jsonb_build_object('ok', false, 'reason','generation_not_running', 'status', g.status);
  end if;
  select * into s from public.ai_content_settings where id;

  -- 43. Anything that is not a success ends here, recorded with its cause.
  if p_status <> 'SUCCEEDED' then
    update public.ai_content_generations
       set status = p_status,
           error_code = p_error ->> 'code',
           error_detail = left(coalesce(p_error ->> 'detail',''), 2000),
           http_status = (p_error ->> 'http_status')::int,
           raw_output = p_raw,
           latency_ms = (p_usage ->> 'latency_ms')::int,
           finished_at = now()
     where id = p_generation;

    update public.ai_content_items
       set status = 'FAILED',
           validation_state = 'FAILED',
           validation = jsonb_build_object('checked_at', now(), 'errors',
             jsonb_build_array(jsonb_build_object(
               'code', coalesce(p_error ->> 'code','generation_failed'),
               'detail', coalesce(p_error ->> 'detail','The provider did not return content.'))))
     where product_id = g.product_id
       and language = g.language
       and content_type = any (g.content_types)
       and status = 'GENERATING';

    perform public.mm_ai_usage_record(g.provider_slug, g.model_id, p_status, p_usage);
    perform public.mm_audit('ai_content.generate.failed', 'ai_content_generation', p_generation::text,
      null, jsonb_build_object('status', p_status, 'code', p_error ->> 'code'),
      left(coalesce(p_error ->> 'detail',''), 400));

    return jsonb_build_object('ok', false, 'reason', coalesce(p_error ->> 'code', p_status),
      'detail', p_error ->> 'detail', 'generation_id', p_generation);
  end if;

  -- 24. A success with nothing usable in it is not a success.
  if p_parsed is null or jsonb_typeof(p_parsed) <> 'object' then
    return public.mm_ai_generation_finish(p_generation, 'REJECTED_OUTPUT', null, p_raw, p_usage,
      jsonb_build_object('code','malformed_response',
                         'detail','The response was not a JSON object matching the requested shape.'));
  end if;

  v_policy := s.publish_policy;

  foreach v_type in array g.content_types loop
    -- The JSON key each content type arrives under.
    v_key := case v_type
      when 'summary' then 'summary'
      when 'short_description' then 'shortDescription'
      when 'long_description' then 'longDescription'
      when 'seo_description' then 'seoDescription'
      when 'meta_keywords' then 'keywords'
      when 'faq' then 'faq'
      when 'features' then 'features'
      when 'benefits' then 'benefits'
      when 'use_cases' then 'useCases' end;

    v_value := p_parsed -> v_key;
    v_content := null; v_json := null;

    if v_value is null or v_value = 'null'::jsonb then
      v_empty := v_empty || v_type;
      continue;
    end if;

    if v_type in ('summary','short_description','long_description','seo_description') then
      if jsonb_typeof(v_value) <> 'string' then v_empty := v_empty || v_type; continue; end if;
      v_content := btrim(v_value #>> '{}');
      if v_content = '' then v_empty := v_empty || v_type; continue; end if;
    else
      if jsonb_typeof(v_value) <> 'array' or jsonb_array_length(v_value) = 0 then
        v_empty := v_empty || v_type; continue;
      end if;
      v_json := v_value;
    end if;

    select * into v_item from public.ai_content_items
     where product_id = g.product_id and content_type = v_type and language = g.language;

    v_version := v_item.current_version + 1;

    -- 15/32. The version that is about to be replaced is written down before it
    -- is replaced, with what it was, so nothing is ever lost to a regeneration.
    insert into public.ai_content_versions (
      item_id, version, kind, content, content_json,
      previous_content, previous_content_json, status_before, status_after,
      generation_id, context_hash, actor, actor_role, note)
    values (
      v_item.id, v_version,
      case when v_item.current_version = 0 then 'AI_DRAFT' else 'REGENERATED' end,
      v_content, v_json,
      v_item.content, v_item.content_json, v_item.status, 'GENERATED',
      p_generation, g.context_hash, auth.uid(),
      (select ur.role::text from public.user_roles ur where ur.user_id = auth.uid() limit 1),
      case when v_item.current_version = 0 then 'First AI draft.'
           else format('Regenerated over version %s.', v_item.current_version) end);

    update public.ai_content_items
       set content = v_content,
           content_json = v_json,
           -- 33. The model's own words, kept separately and never overwritten
           -- by an edit.
           ai_original = v_content,
           ai_original_json = v_json,
           human_edited = false,
           edited_by = null,
           edited_at = null,
           provenance = 'AI_GENERATED',
           status = 'GENERATED',
           current_version = v_version,
           context_hash = g.context_hash,
           stale = false, stale_reason = null, stale_since = null,
           validation_state = 'PENDING',
           -- New text, so any legal decision about the old text no longer
           -- applies and the question is asked again.
           legal_reviewed_at = null, legal_reviewed_by = null,
           rejection_code = null, rejection_reason = null,
           generated_at = now(),
           submitted_at = null, approved_at = null, approved_by = null
     where id = v_item.id;

    -- 30. Validation runs immediately, so nothing sits in the queue without a
    -- verdict and nothing invalid can be approved by accident.
    v_validation := public.mm_ai_validate(v_item.id);

    -- 16/19/20. The policy decides what happens next, and a legal block
    -- overrides every policy including AUTO_PUBLISH.
    select legal_state into v_next from public.ai_content_items where id = v_item.id;
    if v_next = 'BLOCKED' then
      update public.ai_content_items set status = 'IN_REVIEW', submitted_at = now()
       where id = v_item.id;
      insert into public.ai_content_reviews (item_id, version, decision, reason_code, reason, reviewer)
      values (v_item.id, v_version, 'LEGAL_BLOCKED', 'legal_concern',
              'The legal scan blocked this content. It cannot publish until a reviewer clears it.', auth.uid());
      v_next := 'IN_REVIEW';
    elsif v_policy = 'AUTO_PUBLISH'
      and (v_validation ->> 'ok')::boolean
      and v_next not in ('REVIEW_REQUIRED','PENDING')
      and not (v_type = any (s.legal_review_types)) then
      -- Auto-publish still goes through approval and publication properly; it
      -- simply does not wait for a person.
      update public.ai_content_items
         set status = 'APPROVED', approved_at = now(), approved_by = auth.uid(),
             submitted_at = now(), provenance = 'AI_GENERATED'
       where id = v_item.id;
      insert into public.ai_content_reviews (item_id, version, decision, reason, reviewer)
      values (v_item.id, v_version, 'APPROVED', 'Approved automatically under the AUTO_PUBLISH policy.', auth.uid());
      perform public.mm_ai_item_publish(v_item.id, true);
      select status into v_next from public.ai_content_items where id = v_item.id;
    else
      update public.ai_content_items set status = 'IN_REVIEW', submitted_at = now()
       where id = v_item.id;
      insert into public.ai_content_reviews (item_id, version, decision, reason, reviewer)
      values (v_item.id, v_version, 'SUBMITTED', 'Submitted for review after generation.', auth.uid());
      v_next := 'IN_REVIEW';
    end if;

    v_written := v_written || v_type;
    v_results := v_results || jsonb_build_object(
      'content_type', v_type, 'item_id', v_item.id, 'version', v_version,
      'status', v_next, 'validation', v_validation);
  end loop;

  -- 24. The provider answered, but with none of the blocks that were asked for.
  if array_length(v_written, 1) is null then
    return public.mm_ai_generation_finish(p_generation, 'REJECTED_OUTPUT', null, p_raw, p_usage,
      jsonb_build_object('code','no_blocks_returned',
        'detail','The response carried none of the requested content blocks.'));
  end if;

  update public.ai_content_generations
     set status = 'SUCCEEDED',
         parsed_output = p_parsed,
         raw_output = p_raw,
         blocks_returned = v_written,
         usage_available = coalesce((p_usage ->> 'usage_available')::boolean, false),
         tokens_in = (p_usage ->> 'tokens_in')::int,
         tokens_out = (p_usage ->> 'tokens_out')::int,
         cost_usd = (p_usage ->> 'cost_usd')::numeric,
         cost_available = coalesce((p_usage ->> 'cost_available')::boolean, false),
         latency_ms = (p_usage ->> 'latency_ms')::int,
         finished_at = now()
   where id = p_generation;

  -- Any requested block the provider did not return goes back to a draft state
  -- rather than sitting on GENERATING for ever.
  if array_length(v_empty, 1) > 0 then
    update public.ai_content_items
       set status = 'DRAFT',
           validation_state = 'FAILED',
           validation = jsonb_build_object('checked_at', now(), 'errors',
             jsonb_build_array(jsonb_build_object('code','not_returned',
               'detail','The provider did not return this block.')))
     where product_id = g.product_id and language = g.language
       and content_type = any (v_empty) and status = 'GENERATING';
  end if;

  perform public.mm_ai_usage_record(g.provider_slug, g.model_id, 'SUCCEEDED', p_usage);
  perform public.mm_audit('ai_content.generate.succeeded', 'ai_content_generation', p_generation::text,
    null, jsonb_build_object('product', g.product_id, 'written', to_jsonb(v_written),
                             'not_returned', to_jsonb(v_empty), 'policy', v_policy),
    'AI content generated');

  return jsonb_build_object('ok', true, 'generation_id', p_generation,
    'written', to_jsonb(v_written), 'not_returned', to_jsonb(v_empty),
    'policy', v_policy, 'results', v_results);
end;
$$;


--
-- Name: mm_ai_generation_start(uuid, text[], text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_ai_generation_start(p_product uuid, p_types text[], p_language text DEFAULT NULL::text, p_job uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  s record;
  ctx jsonb;
  pr record;
  binding jsonb;
  v_types text[];
  v_lang text;
  v_gen uuid;
  v_today integer;
  v_type text;
  v_item uuid;
  v_enabled text[] := '{}';
  v_skipped text[] := '{}';
begin
  if not public.mm_is_operator() then
    return jsonb_build_object('ok', false, 'reason', 'not_authorized');
  end if;

  select * into s from public.ai_content_settings where id;
  v_lang := coalesce(p_language, s.default_language);
  if not (v_lang = any (s.allowed_languages)) then
    return jsonb_build_object('ok', false, 'reason', 'language_not_allowed',
      'detail', format('%s is not in the allowed languages.', v_lang));
  end if;

  ctx := public.mm_ai_context(p_product);
  if not (ctx ->> 'ok')::boolean then return ctx; end if;
  if (ctx ->> 'deleted')::boolean then
    return jsonb_build_object('ok', false, 'reason', 'product_deleted');
  end if;

  -- 4. Only blocks that are switched on are generated, whatever was asked for.
  foreach v_type in array coalesce(p_types, array[]::text[]) loop
    if coalesce((s.blocks ->> v_type)::boolean, false) then
      v_enabled := v_enabled || v_type;
    else
      v_skipped := v_skipped || v_type;
    end if;
  end loop;
  if array_length(v_enabled, 1) is null then
    return jsonb_build_object('ok', false, 'reason', 'no_enabled_blocks',
      'skipped', to_jsonb(v_skipped),
      'detail', 'Every requested block is switched off in the settings.');
  end if;
  v_types := v_enabled;

  -- 27. The daily ceiling, counted from the real generation records.
  select count(*) into v_today from public.ai_content_generations
   where created_at >= date_trunc('day', now())
     and status in ('SUCCEEDED','FAILED','RUNNING','REJECTED_OUTPUT');
  if s.daily_request_cap > 0 and v_today >= s.daily_request_cap then
    return jsonb_build_object('ok', false, 'reason', 'daily_cap_reached',
      'detail', format('%s requests already made today, cap is %s.', v_today, s.daily_request_cap));
  end if;

  binding := public.mm_ai_provider_binding();
  select * into pr from public.ai_prompts where key = 'marketplace.product.content.v1';

  insert into public.ai_content_generations (
    product_id, content_types, language, provider_slug, model_id, api_kind,
    prompt_key, prompt_version, prompt_hash, template_key,
    context_hash, context_fields, missing_fields, status, job_id, actor)
  values (
    p_product, v_types, v_lang,
    binding ->> 'provider_slug', binding ->> 'model_id', binding ->> 'api_kind',
    pr.key, coalesce((pr.config ->> 'version')::int, 1), md5(coalesce(pr.prompt,'')),
    ctx ->> 'template_key',
    ctx ->> 'context_hash',
    array(select jsonb_array_elements_text(ctx -> 'present_fields')),
    array(select jsonb_array_elements_text(ctx -> 'missing_fields')),
    'RUNNING', p_job, auth.uid())
  returning id into v_gen;

  -- 17. Every requested block moves to GENERATING now, so the console shows
  -- work in progress rather than a stale draft.
  foreach v_type in array v_types loop
    insert into public.ai_content_items (product_id, content_type, language, status, created_by)
    values (p_product, v_type, v_lang, 'GENERATING', auth.uid())
    on conflict (product_id, content_type, language) do update
      set status = case
            -- Published content stays published until the new draft replaces it.
            when ai_content_items.status = 'PUBLISHED' then 'PUBLISHED'
            else 'GENERATING' end
    returning id into v_item;
  end loop;

  perform public.mm_audit('ai_content.generate.start', 'ai_content_generation', v_gen::text,
    null,
    jsonb_build_object('product', p_product, 'types', to_jsonb(v_types), 'language', v_lang,
                       'provider', binding ->> 'provider_slug', 'model', binding ->> 'model_id',
                       'context_hash', ctx ->> 'context_hash'),
    'AI content generation requested');

  return jsonb_build_object(
    'ok', true,
    'generation_id', v_gen,
    'product_id', p_product,
    'product_name', ctx ->> 'product_name',
    'types', to_jsonb(v_types),
    'skipped_disabled', to_jsonb(v_skipped),
    'language', v_lang,
    'context', ctx,
    'binding', binding,
    -- 49. The prompt travels to the server only. No route returns it to a
    -- browser; the console shows the prompt key and version instead.
    'system_prompt', pr.prompt,
    'brand_voice', s.brand_voice,
    'limits', s.limits,
    'requests_today', v_today,
    'daily_cap', s.daily_request_cap);
end;
$$;


--
-- Name: mm_ai_item_approve(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_ai_item_approve(p_item uuid, p_note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare i record; s record; v_validation jsonb;
begin
  if not public.mm_is_operator() then
    return jsonb_build_object('ok', false, 'reason','not_authorized');
  end if;
  select * into s from public.ai_content_settings where id;
  if s.publish_policy = 'ROLE_BASED_APPROVAL' and not public.mm_ai_can_approve() then
    return jsonb_build_object('ok', false, 'reason','not_authorized',
      'detail','The policy is ROLE_BASED_APPROVAL and your role may generate and edit but not approve.');
  end if;

  select * into i from public.ai_content_items where id = p_item;
  if not found then return jsonb_build_object('ok', false, 'reason','item_not_found'); end if;
  if i.status not in ('IN_REVIEW','GENERATED') then
    return jsonb_build_object('ok', false, 'reason','not_approvable', 'status', i.status);
  end if;

  -- 30. Validation is re-run at the moment of approval, not trusted from
  -- whenever it last happened; the catalogue may have changed underneath.
  v_validation := public.mm_ai_validate(p_item);
  select * into i from public.ai_content_items where id = p_item;

  if i.validation_state <> 'PASSED' then
    return jsonb_build_object('ok', false, 'reason','validation_failed',
      'validation', i.validation, 'detail','Only valid content can be approved.');
  end if;
  -- 50. A legal block is absolute. No policy and no role gets past it; it has
  -- to be cleared by a legal decision first, which is its own recorded act.
  if i.legal_state = 'BLOCKED' then
    return jsonb_build_object('ok', false, 'reason','legal_blocked',
      'findings', i.legal_findings,
      'detail','The legal scan blocked this content. Clear it in the legal review before approving.');
  end if;
  if i.legal_state = 'REVIEW_REQUIRED' then
    return jsonb_build_object('ok', false, 'reason','legal_review_required',
      'findings', i.legal_findings,
      'detail','This content type requires a legal decision before approval.');
  end if;

  update public.ai_content_items
     set status = 'APPROVED', approved_at = now(), approved_by = auth.uid()
   where id = p_item;
  insert into public.ai_content_reviews (item_id, version, decision, reason, reviewer, reviewer_role)
  values (p_item, i.current_version, 'APPROVED', p_note, auth.uid(),
          (select ur.role::text from public.user_roles ur where ur.user_id = auth.uid() limit 1));

  perform public.mm_audit('ai_content.approve', 'ai_content_item', p_item::text,
    jsonb_build_object('status', i.status), jsonb_build_object('status','APPROVED'), p_note);

  return jsonb_build_object('ok', true, 'status','APPROVED', 'validation', v_validation);
end;
$$;


--
-- Name: mm_ai_item_archive(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_ai_item_archive(p_item uuid, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare i record;
begin
  if not public.mm_is_operator() then
    return jsonb_build_object('ok', false, 'reason','not_authorized');
  end if;
  select * into i from public.ai_content_items where id = p_item;
  if not found then return jsonb_build_object('ok', false, 'reason','item_not_found'); end if;
  if i.status = 'PUBLISHED' then
    perform public.mm_ai_item_unpublish(p_item, coalesce(p_reason, 'Archived.'));
    select * into i from public.ai_content_items where id = p_item;
  end if;

  insert into public.ai_content_versions (
    item_id, version, kind, content, content_json, previous_content, previous_content_json,
    status_before, status_after, actor, note)
  values (p_item, i.current_version + 1, 'ARCHIVED', i.content, i.content_json,
          i.content, i.content_json, i.status, 'ARCHIVED', auth.uid(),
          coalesce(p_reason, 'Archived.'));

  update public.ai_content_items
     set status = 'ARCHIVED', archived_at = now(), current_version = i.current_version + 1
   where id = p_item;

  perform public.mm_audit('ai_content.archive', 'ai_content_item', p_item::text,
    jsonb_build_object('status', i.status), jsonb_build_object('status','ARCHIVED'), p_reason);

  return jsonb_build_object('ok', true, 'status','ARCHIVED');
end;
$$;


--
-- Name: mm_ai_item_edit(uuid, text, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_ai_item_edit(p_item uuid, p_content text DEFAULT NULL::text, p_json jsonb DEFAULT NULL::jsonb, p_note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare i record; v_version integer; v_validation jsonb;
begin
  if not public.mm_is_operator() then
    return jsonb_build_object('ok', false, 'reason','not_authorized');
  end if;
  select * into i from public.ai_content_items where id = p_item;
  if not found then return jsonb_build_object('ok', false, 'reason','item_not_found'); end if;
  if i.status in ('GENERATING','ARCHIVED') then
    return jsonb_build_object('ok', false, 'reason','not_editable', 'status', i.status);
  end if;
  if p_content is null and p_json is null then
    return jsonb_build_object('ok', false, 'reason','nothing_to_save');
  end if;

  v_version := i.current_version + 1;

  insert into public.ai_content_versions (
    item_id, version, kind, content, content_json,
    previous_content, previous_content_json, status_before, status_after,
    context_hash, actor, actor_role, note)
  values (p_item, v_version, 'HUMAN_EDIT', coalesce(p_content, i.content), coalesce(p_json, i.content_json),
          i.content, i.content_json, i.status, 'IN_REVIEW', i.context_hash, auth.uid(),
          (select ur.role::text from public.user_roles ur where ur.user_id = auth.uid() limit 1),
          coalesce(p_note, 'Edited by hand.'));

  update public.ai_content_items
     set content = coalesce(p_content, content),
         content_json = coalesce(p_json, content_json),
         human_edited = true,
         edited_by = auth.uid(),
         edited_at = now(),
         provenance = 'HUMAN_EDITED',
         current_version = v_version,
         -- An edit re-opens the question, so an approval given to the previous
         -- text does not carry over to this one.
         status = case when status = 'PUBLISHED' then 'PUBLISHED' else 'IN_REVIEW' end,
         approved_at = null, approved_by = null,
         validation_state = 'PENDING',
         -- The text changed, so a legal clearance given to the old text is
         -- withdrawn and the question is put again.
         legal_reviewed_at = null, legal_reviewed_by = null,
         rejection_code = null, rejection_reason = null
   where id = p_item;

  v_validation := public.mm_ai_validate(p_item);

  perform public.mm_audit('ai_content.edit', 'ai_content_item', p_item::text,
    jsonb_build_object('version', i.current_version, 'content', left(coalesce(i.content,''), 500)),
    jsonb_build_object('version', v_version, 'content', left(coalesce(p_content, i.content, ''), 500)),
    coalesce(p_note, 'Human edit'));

  return jsonb_build_object('ok', true, 'version', v_version, 'validation', v_validation);
end;
$$;


--
-- Name: mm_ai_item_publish(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_ai_item_publish(p_item uuid, p_auto boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  i record;
  s record;
  p record;
  v_targets jsonb := '{}'::jsonb;
  v_written integer := 0;
  v_failed integer := 0;
  v_state text;
  v_url text;
  v_country text[];
  v_generated text[];
  v_keywords text[];
  v_slug text;
  v_faq jsonb;
  v_faq_count integer := 0;
  v_existing text;
  v_seo_desc text;
  v_detail text;
begin
  if not public.mm_is_operator() then
    return jsonb_build_object('ok', false, 'reason','not_authorized');
  end if;

  select * into s from public.ai_content_settings where id;
  select * into i from public.ai_content_items where id = p_item;
  if not found then return jsonb_build_object('ok', false, 'reason','item_not_found'); end if;

  if i.status <> 'APPROVED' then
    return jsonb_build_object('ok', false, 'reason','not_approved', 'status', i.status,
      'detail','Content must be approved before it can be published.');
  end if;
  -- 50. Restated at the point of publication, because this is the act that
  -- makes content public and it must not depend on an earlier check.
  if i.legal_state = 'BLOCKED' then
    return jsonb_build_object('ok', false, 'reason','legal_blocked',
      'detail','Blocked content cannot be published.');
  end if;
  if i.validation_state <> 'PASSED' then
    return jsonb_build_object('ok', false, 'reason','validation_failed', 'validation', i.validation);
  end if;

  select * into p from public.marketplace_products where id = i.product_id;
  if p.deleted_at is not null then
    return jsonb_build_object('ok', false, 'reason','product_deleted',
      'detail','A deleted product does not get published content.');
  end if;

  v_url := '/marketplace/product/' || p.slug;

  -- Each target is attempted on its own and reports its own outcome, so a
  -- failure in one does not silently take the others down with it.

  if i.content_type = 'short_description' then
    begin
      v_existing := coalesce(p.description, '');
      if v_existing <> '' and not s.overwrite_existing_product_copy then
        v_targets := v_targets || jsonb_build_object('marketplace_products.description',
          jsonb_build_object('state','skipped',
            'detail','The product already has a description and overwriting is switched off.'));
      else
        update public.marketplace_products set description = i.content, updated_at = now()
         where id = p.id;
        v_written := v_written + 1;
        v_targets := v_targets || jsonb_build_object('marketplace_products.description',
          jsonb_build_object('state','written', 'detail','Used by the product page head and the sitemap.'));
      end if;
    exception when others then
      v_failed := v_failed + 1;
      v_targets := v_targets || jsonb_build_object('marketplace_products.description',
        jsonb_build_object('state','failed','detail', left(sqlerrm, 300)));
    end;
  end if;

  if i.content_type = 'seo_description' then
    -- 8/22. The SEO Manager owns the metadata; this writes the description into
    -- its record and regenerates the structured data alongside it, rather than
    -- keeping a second copy anywhere.
    begin
      v_seo_desc := left(i.content, 320);
      insert into public.seo_pages (url, product_id, title, meta_title, meta_description,
                                    canonical_url, page_type, index_status, schema_json, updated_at)
      values (v_url, p.id, p.name, p.name || ' | Software Vala', v_seo_desc,
              'https://softwarevala.net' || v_url, 'product', 'indexable',
              jsonb_build_object(
                '@context','https://schema.org', '@type','SoftwareApplication',
                'name', p.name, 'applicationCategory','BusinessApplication',
                'operatingSystem', coalesce(nullif(p.deployment,''),'Web'),
                'description', v_seo_desc,
                'url', 'https://softwarevala.net' || v_url,
                'brand', jsonb_build_object('@type','Brand','name','Software Vala')),
              now())
      on conflict (url) do update set
        product_id = excluded.product_id,
        meta_description = excluded.meta_description,
        meta_title = coalesce(nullif(public.seo_pages.meta_title,''), excluded.meta_title),
        canonical_url = coalesce(nullif(public.seo_pages.canonical_url,''), excluded.canonical_url),
        schema_json = excluded.schema_json,
        page_type = 'product',
        updated_at = now();
      v_written := v_written + 1;
      v_targets := v_targets || jsonb_build_object('seo_pages',
        jsonb_build_object('state','written','url', v_url,
          'detail','Meta description and SoftwareApplication structured data regenerated.'));
    exception when others then
      v_failed := v_failed + 1;
      v_targets := v_targets || jsonb_build_object('seo_pages',
        jsonb_build_object('state','failed','detail', left(sqlerrm, 300)));
    end;
  end if;

  if i.content_type = 'meta_keywords' then
    begin
      -- 9. The country markers are routing data the SEO work depends on and are
      -- carried through untouched; only the descriptive keywords are replaced.
      select array_agg(k) into v_country
        from unnest(coalesce(p.search_keywords, '{}')) k where k like 'country:%';
      select array_agg(distinct btrim(x)) into v_generated
        from jsonb_array_elements_text(i.content_json) x
       where btrim(x) <> '' and length(btrim(x)) <= 120;

      -- Generated keywords are added to what the product already ranks for,
      -- never swapped in for it. Replacing the list cost the test product 45 of
      -- its 51 existing keywords, which is exactly the silent overwrite that
      -- section 31 forbids. Only an explicit overwrite setting replaces them.
      select array_agg(distinct k) into v_keywords from (
        select unnest(coalesce(v_country, '{}'::text[])) as k
        union
        select unnest(coalesce(v_generated, '{}'::text[]))
        union
        select unnest(case when s.overwrite_existing_product_copy then '{}'::text[]
                           else coalesce(p.search_keywords, '{}'::text[]) end)) u
       where btrim(k) <> '';

      update public.marketplace_products
         set search_keywords = coalesce(v_keywords, '{}'), updated_at = now()
       where id = p.id;
      v_written := v_written + 1;
      v_targets := v_targets || jsonb_build_object('marketplace_products.search_keywords',
        jsonb_build_object('state','written',
          'kept_existing', coalesce(array_length(p.search_keywords, 1), 0),
          'added', coalesce(array_length(v_generated, 1), 0),
          'total_now', coalesce(array_length(v_keywords, 1), 0),
          'detail','Merged into the product keywords, which the page renders as its keywords meta tag.'));
    exception when others then
      v_failed := v_failed + 1;
      v_targets := v_targets || jsonb_build_object('marketplace_products.search_keywords',
        jsonb_build_object('state','failed','detail', left(sqlerrm, 300)));
    end;
  end if;

  if i.content_type = 'faq' then
    -- 10/21. The FAQ Manager's own table, so a published FAQ is managed there
    -- from then on like any other and is not a private copy.
    begin
      for v_faq in select * from jsonb_array_elements(i.content_json) loop
        v_slug := left(regexp_replace(lower(coalesce(v_faq ->> 'question','')),
                                      '[^a-z0-9]+', '-', 'g'), 90);
        v_slug := btrim(v_slug, '-');
        if v_slug = '' then continue; end if;
        v_slug := p.slug || '-' || v_slug;

        insert into public.faqs (question, answer, slug, language, related_product_ids,
                                 status, ai_generated, ai_sources, published_at, author_id, keywords)
        values (btrim(v_faq ->> 'question'), btrim(v_faq ->> 'answer'), v_slug, i.language,
                array[p.id], 'published', true,
                jsonb_build_array(jsonb_build_object(
                  'source','ai_content_generator', 'item', p_item, 'product', p.id,
                  'context_hash', i.context_hash)),
                now(), auth.uid(), '{}')
        on conflict (slug) do update set
          question = excluded.question, answer = excluded.answer,
          related_product_ids = excluded.related_product_ids,
          status = 'published', published_at = now(), updated_at = now();
        v_faq_count := v_faq_count + 1;
      end loop;
      v_written := v_written + 1;
      v_targets := v_targets || jsonb_build_object('faqs',
        jsonb_build_object('state','written','entries', v_faq_count,
          'detail','Published into the FAQ Manager against this product.'));
    exception when others then
      v_failed := v_failed + 1;
      v_targets := v_targets || jsonb_build_object('faqs',
        jsonb_build_object('state','failed','detail', left(sqlerrm, 300)));
    end;
  end if;

  if i.content_type in ('summary','long_description','features','benefits','use_cases') then
    -- No other store holds these, so the published row is the store, and the
    -- product page reads it directly.
    v_written := v_written + 1;
    v_targets := v_targets || jsonb_build_object('ai_content_items',
      jsonb_build_object('state','written',
        'detail','Served to the product page from this module''s published row.'));
  end if;

  -- 22. Publishing anything that changes what a search engine sees invalidates
  -- the page's SEO record, so it is stamped rather than left looking fresh.
  if i.content_type in ('short_description','seo_description','meta_keywords') then
    begin
      update public.seo_pages set updated_at = now(), last_crawled_at = null
       where product_id = p.id;
      -- seo_activity_log constrains action to INSERT/UPDATE/DELETE, so what
      -- happened is carried in the context rather than bent into the action.
      insert into public.seo_activity_log (table_name, record_id, action, actor, context)
      values ('seo_pages', p_item, 'UPDATE',
              coalesce((select u.email from auth.users u where u.id = auth.uid()), 'system'),
              jsonb_build_object('event','seo_invalidated_by_content_publish',
                                 'product', p.id, 'url', v_url, 'content_type', i.content_type));
      v_targets := v_targets || jsonb_build_object('seo_invalidation',
        jsonb_build_object('state','written',
          'detail','SEO record marked for recrawl. sitemap-products reads the product row directly, so the sitemap is current without a rebuild.'));
    exception when others then
      -- Failing to log the invalidation must not undo a correct publication.
      v_targets := v_targets || jsonb_build_object('seo_invalidation',
        jsonb_build_object('state','failed','detail', left(sqlerrm, 300)));
    end;
  end if;

  -- A publication that wrote nothing because policy told it not to is not a
  -- failure and must not be reported as one. It is not a success either, so it
  -- keeps its own name, and the content stays approved and retryable.
  v_state := case when v_failed = 0 and v_written > 0 then 'COMPLETE'
                  when v_written > 0 then 'PARTIAL'
                  when v_failed = 0 then 'SKIPPED'
                  else 'FAILED' end;

  insert into public.ai_content_versions (
    item_id, version, kind, content, content_json, previous_content, previous_content_json,
    status_before, status_after, context_hash, actor, actor_role, note)
  values (p_item, i.current_version + 1, 'PUBLISHED', i.content, i.content_json,
          i.content, i.content_json, i.status,
          case when v_state in ('FAILED','SKIPPED') then 'APPROVED' else 'PUBLISHED' end,
          i.context_hash, auth.uid(),
          (select ur.role::text from public.user_roles ur where ur.user_id = auth.uid() limit 1),
          case when p_auto then 'Published automatically under the AUTO_PUBLISH policy.'
               else 'Published.' end);

  update public.ai_content_items
     set status = case when v_state in ('FAILED','SKIPPED') then 'APPROVED' else 'PUBLISHED' end,
         provenance = case when v_state in ('FAILED','SKIPPED') then provenance else 'PUBLISHED' end,
         published_at = case when v_state in ('FAILED','SKIPPED') then null else now() end,
         published_by = case when v_state in ('FAILED','SKIPPED') then null else auth.uid() end,
         current_version = i.current_version + 1,
         publish_targets = v_targets,
         publish_state = v_state
   where id = p_item;

  insert into public.ai_content_reviews (item_id, version, decision, reason, reviewer, reviewer_role)
  values (p_item, i.current_version + 1, 'PUBLISHED',
          case when v_state = 'COMPLETE' then 'Published to every target.'
               when v_state = 'PARTIAL' then 'Published, but at least one target failed. Retry is available.'
               when v_state = 'SKIPPED' then 'Nothing was written: the target already holds copy and overwriting is switched off.'
               else 'Publication failed. The content stays approved and can be retried.' end,
          auth.uid(),
          (select ur.role::text from public.user_roles ur where ur.user_id = auth.uid() limit 1));

  perform public.mm_audit('ai_content.publish', 'ai_content_item', p_item::text,
    jsonb_build_object('status', i.status),
    jsonb_build_object('publish_state', v_state, 'targets', v_targets),
    case when p_auto then 'Auto-published' else 'Published' end);

  -- 43/55. A partial or failed publication never reports success.
  return jsonb_build_object(
    'ok', v_state in ('COMPLETE','PARTIAL'),
    'publish_state', v_state,
    'status', case when v_state in ('FAILED','SKIPPED') then 'APPROVED' else 'PUBLISHED' end,
    'targets', v_targets,
    'detail', case when v_state = 'SKIPPED'
                   then 'Nothing was written. The target already holds copy and "overwrite existing product copy" is off.'
                   else null end,
    'retryable', v_state in ('PARTIAL','FAILED','SKIPPED'));
end;
$$;


--
-- Name: mm_ai_item_reject(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_ai_item_reject(p_item uuid, p_code text, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare i record;
begin
  if not public.mm_is_operator() then
    return jsonb_build_object('ok', false, 'reason','not_authorized');
  end if;
  if p_code is null or p_code = '' then
    return jsonb_build_object('ok', false, 'reason','reason_required',
      'detail','A rejection must say why.');
  end if;
  select * into i from public.ai_content_items where id = p_item;
  if not found then return jsonb_build_object('ok', false, 'reason','item_not_found'); end if;
  if i.status in ('ARCHIVED','GENERATING') then
    return jsonb_build_object('ok', false, 'reason','not_rejectable', 'status', i.status);
  end if;

  insert into public.ai_content_versions (
    item_id, version, kind, content, content_json, previous_content, previous_content_json,
    status_before, status_after, context_hash, actor, actor_role, note)
  values (p_item, i.current_version + 1, 'REJECTED', i.content, i.content_json,
          i.content, i.content_json, i.status, 'REJECTED', i.context_hash, auth.uid(),
          (select ur.role::text from public.user_roles ur where ur.user_id = auth.uid() limit 1),
          coalesce(p_reason, p_code));

  update public.ai_content_items
     set status = 'REJECTED', rejection_code = p_code, rejection_reason = p_reason,
         current_version = i.current_version + 1,
         approved_at = null, approved_by = null
   where id = p_item;

  insert into public.ai_content_reviews (item_id, version, decision, reason_code, reason, reviewer, reviewer_role)
  values (p_item, i.current_version, 'REJECTED', p_code, p_reason, auth.uid(),
          (select ur.role::text from public.user_roles ur where ur.user_id = auth.uid() limit 1));

  perform public.mm_audit('ai_content.reject', 'ai_content_item', p_item::text,
    jsonb_build_object('status', i.status), jsonb_build_object('status','REJECTED','code',p_code), p_reason);

  return jsonb_build_object('ok', true, 'status','REJECTED');
end;
$$;


--
-- Name: mm_ai_item_submit(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_ai_item_submit(p_item uuid, p_note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare i record; v_validation jsonb;
begin
  if not public.mm_is_operator() then
    return jsonb_build_object('ok', false, 'reason','not_authorized');
  end if;
  select * into i from public.ai_content_items where id = p_item;
  if not found then return jsonb_build_object('ok', false, 'reason','item_not_found'); end if;
  if i.status not in ('DRAFT','GENERATED','REJECTED') then
    return jsonb_build_object('ok', false, 'reason','not_submittable', 'status', i.status);
  end if;

  v_validation := public.mm_ai_validate(p_item);
  update public.ai_content_items set status = 'IN_REVIEW', submitted_at = now() where id = p_item;
  insert into public.ai_content_reviews (item_id, version, decision, reason, reviewer, reviewer_role)
  values (p_item, i.current_version, 'SUBMITTED', p_note, auth.uid(),
          (select ur.role::text from public.user_roles ur where ur.user_id = auth.uid() limit 1));

  perform public.mm_audit('ai_content.submit', 'ai_content_item', p_item::text,
    jsonb_build_object('status', i.status), jsonb_build_object('status','IN_REVIEW'), p_note);

  return jsonb_build_object('ok', true, 'status','IN_REVIEW', 'validation', v_validation);
end;
$$;


--
-- Name: mm_ai_item_unpublish(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_ai_item_unpublish(p_item uuid, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare i record;
begin
  if not public.mm_is_operator() then
    return jsonb_build_object('ok', false, 'reason','not_authorized');
  end if;
  select * into i from public.ai_content_items where id = p_item;
  if not found then return jsonb_build_object('ok', false, 'reason','item_not_found'); end if;
  if i.status <> 'PUBLISHED' then
    return jsonb_build_object('ok', false, 'reason','not_published','status', i.status);
  end if;

  -- 10/46. An FAQ published from here is archived rather than deleted, so the
  -- FAQ Manager keeps its history and no orphan stays live on the site.
  if i.content_type = 'faq' then
    update public.faqs set status = 'archived', updated_at = now()
     where status = 'published'
       and ai_generated
       and ai_sources @> jsonb_build_array(jsonb_build_object('item', p_item));
  end if;

  insert into public.ai_content_versions (
    item_id, version, kind, content, content_json, previous_content, previous_content_json,
    status_before, status_after, context_hash, actor, note)
  values (p_item, i.current_version + 1, 'UNPUBLISHED', i.content, i.content_json,
          i.content, i.content_json, 'PUBLISHED', 'APPROVED', i.context_hash, auth.uid(),
          coalesce(p_reason, 'Unpublished.'));

  update public.ai_content_items
     set status = 'APPROVED', published_at = null, published_by = null,
         publish_state = 'NONE', provenance = 'LEGAL_APPROVED',
         current_version = i.current_version + 1
   where id = p_item;

  insert into public.ai_content_reviews (item_id, version, decision, reason, reviewer)
  values (p_item, i.current_version + 1, 'UNPUBLISHED', p_reason, auth.uid());

  perform public.mm_audit('ai_content.unpublish', 'ai_content_item', p_item::text,
    jsonb_build_object('status','PUBLISHED'), jsonb_build_object('status','APPROVED'), p_reason);

  return jsonb_build_object('ok', true, 'status','APPROVED');
end;
$$;


--
-- Name: mm_ai_item_versions(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_ai_item_versions(p_item uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if not public.mm_is_operator() then
    return jsonb_build_object('ok', false, 'reason','not_authorized');
  end if;
  return jsonb_build_object('ok', true,
    'versions', (select coalesce(jsonb_agg(jsonb_build_object(
        'version', v.version, 'kind', v.kind,
        'content', left(coalesce(v.content,''), 6000), 'items', v.content_json,
        'status_before', v.status_before, 'status_after', v.status_after,
        'note', v.note, 'actor_role', v.actor_role,
        'actor', (select u.email from auth.users u where u.id = v.actor),
        'created_at', v.created_at) order by v.version desc), '[]'::jsonb)
      from public.ai_content_versions v where v.item_id = p_item),
    'reviews', (select coalesce(jsonb_agg(jsonb_build_object(
        'decision', r.decision, 'reason_code', r.reason_code, 'reason', r.reason,
        'version', r.version, 'role', r.reviewer_role,
        'reviewer', (select u.email from auth.users u where u.id = r.reviewer),
        'created_at', r.created_at) order by r.created_at desc), '[]'::jsonb)
      from public.ai_content_reviews r where r.item_id = p_item));
end;
$$;


--
-- Name: mm_ai_legal_decide(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_ai_legal_decide(p_item uuid, p_to text, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare i record;
begin
  if not public.mm_ai_can_approve() then
    return jsonb_build_object('ok', false, 'reason','not_authorized',
      'detail','A legal decision requires an approving role.');
  end if;
  if p_to not in ('CLEARED','BLOCKED') then
    return jsonb_build_object('ok', false, 'reason','bad_decision');
  end if;
  select * into i from public.ai_content_items where id = p_item;
  if not found then return jsonb_build_object('ok', false, 'reason','item_not_found'); end if;

  update public.ai_content_items
     set legal_state = p_to,
         legal_reviewed_by = auth.uid(),
         legal_reviewed_at = now(),
         provenance = case when p_to = 'CLEARED' and provenance <> 'PUBLISHED'
                           then 'LEGAL_APPROVED' else provenance end
   where id = p_item;

  insert into public.ai_content_reviews (item_id, version, decision, reason_code, reason, reviewer, reviewer_role)
  values (p_item, i.current_version,
          case when p_to = 'CLEARED' then 'LEGAL_CLEARED' else 'LEGAL_BLOCKED' end,
          'legal_concern', p_reason, auth.uid(),
          (select ur.role::text from public.user_roles ur where ur.user_id = auth.uid() limit 1));

  -- A block on content that is already live takes it down; leaving it up while
  -- recording that it is blocked would be the worst of both.
  if p_to = 'BLOCKED' and i.status = 'PUBLISHED' then
    perform public.mm_ai_item_unpublish(p_item, coalesce(p_reason, 'Blocked by legal review.'));
  end if;

  perform public.mm_audit('ai_content.legal_decision', 'ai_content_item', p_item::text,
    jsonb_build_object('legal_state', i.legal_state), jsonb_build_object('legal_state', p_to), p_reason);

  return jsonb_build_object('ok', true, 'legal_state', p_to);
end;
$$;


--
-- Name: mm_ai_legal_scan(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_ai_legal_scan(p_text text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select coalesce(jsonb_agg(jsonb_build_object(
           'code', r.code, 'label', r.label, 'category', r.category,
           'severity', r.severity, 'action', r.action, 'note', r.note,
           'match', substring(p_text from r.pattern))), '[]'::jsonb)
    from public.ai_content_legal_rules r
   where r.active
     and coalesce(p_text,'') <> ''
     and p_text ~* r.pattern;
$$;


--
-- Name: mm_ai_products(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_ai_products(p_query jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_search text := nullif(btrim(coalesce(p_query ->> 'search','')), '');
  v_category uuid := nullif(p_query ->> 'category_id','')::uuid;
  v_filter text := coalesce(p_query ->> 'filter', 'all');
  v_limit integer := least(greatest(coalesce((p_query ->> 'limit')::int, 20), 1), 100);
  v_offset integer := greatest(coalesce((p_query ->> 'offset')::int, 0), 0);
  v_total integer;
begin
  if not public.mm_is_operator() then
    return jsonb_build_object('ok', false, 'reason','not_authorized');
  end if;

  select count(*) into v_total from public.marketplace_products p
   where p.deleted_at is null and p.visible
     and (v_search is null or p.name ilike '%'||v_search||'%' or p.slug ilike '%'||v_search||'%')
     and (v_category is null or p.category_id = v_category)
     and case v_filter
           when 'missing_description' then coalesce(p.description,'') = ''
           when 'has_content' then exists (select 1 from public.ai_content_items i where i.product_id = p.id)
           when 'no_content' then not exists (select 1 from public.ai_content_items i where i.product_id = p.id)
           when 'stale' then exists (select 1 from public.ai_content_items i where i.product_id = p.id and i.stale)
           else true end;

  return jsonb_build_object('ok', true, 'total', v_total,
    'rows', (select coalesce(jsonb_agg(jsonb_build_object(
        'id', p.id, 'name', p.name, 'slug', p.slug,
        'category', c.name, 'industry', p.industry_label,
        'has_description', coalesce(p.description,'') <> '',
        'feature_count', case when jsonb_typeof(p.features)='array' then jsonb_array_length(p.features) else 0 end,
        'content_items', (select count(*) from public.ai_content_items i where i.product_id = p.id),
        'published_items', (select count(*) from public.ai_content_items i
                             where i.product_id = p.id and i.status = 'PUBLISHED'),
        'stale_items', (select count(*) from public.ai_content_items i
                         where i.product_id = p.id and i.stale)) order by p.name), '[]'::jsonb)
      from (select * from public.marketplace_products p
             where p.deleted_at is null and p.visible
               and (v_search is null or p.name ilike '%'||v_search||'%' or p.slug ilike '%'||v_search||'%')
               and (v_category is null or p.category_id = v_category)
               and case v_filter
                     when 'missing_description' then coalesce(p.description,'') = ''
                     when 'has_content' then exists (select 1 from public.ai_content_items i where i.product_id = p.id)
                     when 'no_content' then not exists (select 1 from public.ai_content_items i where i.product_id = p.id)
                     when 'stale' then exists (select 1 from public.ai_content_items i where i.product_id = p.id and i.stale)
                     else true end
             order by p.name limit v_limit offset v_offset) p
      left join public.marketplace_categories c on c.id = p.category_id));
end;
$$;


--
-- Name: mm_ai_provider_binding(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_ai_provider_binding() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare s record; p record; m record;
begin
  if not public.mm_is_operator() then
    return jsonb_build_object('ok', false, 'reason', 'not_authorized');
  end if;
  select * into s from public.ai_content_settings where id;
  select * into p from public.ai_providers where slug = s.provider_slug;

  if not found then
    return jsonb_build_object('ok', false, 'reason', 'provider_not_registered',
                              'provider_slug', s.provider_slug);
  end if;

  select * into m from public.ai_models
   where provider_id = p.id and (model_id = s.model_id or s.model_id is null)
   order by (model_id = s.model_id) desc, is_default desc limit 1;

  return jsonb_build_object(
    'ok', true,
    'provider_slug', p.slug,
    'provider_name', p.name,
    'provider_status', p.status,
    'content_generation_enabled', p.content_generation_enabled,
    'base_url', p.base_url,
    'api_kind', p.api_kind,
    -- The NAME of the variable, never its value.
    'credential_env', p.credential_env,
    'model_id', coalesce(s.model_id, m.model_id),
    'model_name', m.name,
    'context_window', m.context_window,
    'input_cost_per_1k', m.input_cost_per_1k,
    'output_cost_per_1k', m.output_cost_per_1k,
    'temperature', s.temperature,
    'max_output_tokens', s.max_output_tokens,
    'timeout_ms', s.request_timeout_ms,
    -- 41/49. Whether the AI API Manager holds a stored key for this provider.
    -- Presence only; no prefix, no fingerprint, no value.
    'stored_key_present', exists (
      select 1 from public.api_keys k
       where k.provider_id = p.id and k.status = 'active'
         and coalesce(length(k.secret_encrypted), 0) >= 20));
end;
$$;


--
-- Name: mm_ai_settings_set(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_ai_settings_set(p_patch jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare before record; after record; v_provider record;
begin
  if not public.mm_is_operator() then
    return jsonb_build_object('ok', false, 'reason','not_authorized');
  end if;
  select * into before from public.ai_content_settings where id;

  -- 19/50. Only an approving role may loosen the governance policy. Anyone who
  -- may run the module can tighten it.
  if p_patch ? 'publish_policy'
     and (p_patch ->> 'publish_policy') = 'AUTO_PUBLISH'
     and not public.mm_ai_can_approve() then
    return jsonb_build_object('ok', false, 'reason','not_authorized',
      'detail','Switching to AUTO_PUBLISH requires an approving role.');
  end if;

  if p_patch ? 'provider_slug' then
    select * into v_provider from public.ai_providers where slug = p_patch ->> 'provider_slug';
    if not found then
      return jsonb_build_object('ok', false, 'reason','provider_not_registered',
        'detail','Add the provider in the AI API Manager first.',
        'available', (select jsonb_agg(slug order by slug) from public.ai_providers
                       where content_generation_enabled));
    end if;
    if not v_provider.content_generation_enabled then
      return jsonb_build_object('ok', false, 'reason','provider_not_enabled',
        'detail', format('%s is registered but is not enabled for content generation.', v_provider.name));
    end if;
  end if;

  update public.ai_content_settings set
    blocks = coalesce(p_patch -> 'blocks', blocks),
    limits = coalesce(p_patch -> 'limits', limits),
    publish_policy = coalesce(p_patch ->> 'publish_policy', publish_policy),
    legal_review_types = coalesce(
      (select array_agg(x) from jsonb_array_elements_text(p_patch -> 'legal_review_types') x),
      legal_review_types),
    brand_voice = coalesce(p_patch -> 'brand_voice', brand_voice),
    default_language = coalesce(p_patch ->> 'default_language', default_language),
    allowed_languages = coalesce(
      (select array_agg(x) from jsonb_array_elements_text(p_patch -> 'allowed_languages') x),
      allowed_languages),
    provider_slug = coalesce(p_patch ->> 'provider_slug', provider_slug),
    model_id = coalesce(p_patch ->> 'model_id', model_id),
    temperature = coalesce((p_patch ->> 'temperature')::numeric, temperature),
    max_output_tokens = coalesce((p_patch ->> 'max_output_tokens')::int, max_output_tokens),
    request_timeout_ms = coalesce((p_patch ->> 'request_timeout_ms')::int, request_timeout_ms),
    daily_request_cap = coalesce((p_patch ->> 'daily_request_cap')::int, daily_request_cap),
    bulk_batch_size = coalesce((p_patch ->> 'bulk_batch_size')::int, bulk_batch_size),
    duplicate_threshold = coalesce((p_patch ->> 'duplicate_threshold')::numeric, duplicate_threshold),
    high_similarity_threshold = coalesce((p_patch ->> 'high_similarity_threshold')::numeric, high_similarity_threshold),
    overwrite_existing_product_copy = coalesce((p_patch ->> 'overwrite_existing_product_copy')::boolean,
                                               overwrite_existing_product_copy),
    updated_by = auth.uid()
  where id;

  select * into after from public.ai_content_settings where id;
  perform public.mm_audit('ai_content.settings', 'ai_content_settings', 'singleton',
    to_jsonb(before), to_jsonb(after), p_patch ->> 'reason');

  return jsonb_build_object('ok', true, 'settings', to_jsonb(after));
end;
$$;


--
-- Name: mm_ai_usage_record(text, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_ai_usage_record(p_provider text, p_model text, p_status text, p_usage jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  insert into public.ai_content_usage (
    usage_date, provider_slug, model_id, requests, succeeded, failed, not_configured,
    tokens_in, tokens_out, cost_usd, usage_available, cost_available)
  values (
    current_date, coalesce(p_provider,'unconfigured'), coalesce(p_model,'unconfigured'),
    1,
    case when p_status = 'SUCCEEDED' then 1 else 0 end,
    case when p_status in ('FAILED','REJECTED_OUTPUT') then 1 else 0 end,
    case when p_status = 'NOT_CONFIGURED' then 1 else 0 end,
    coalesce((p_usage ->> 'tokens_in')::bigint, 0),
    coalesce((p_usage ->> 'tokens_out')::bigint, 0),
    coalesce((p_usage ->> 'cost_usd')::numeric, 0),
    coalesce((p_usage ->> 'usage_available')::boolean, false),
    coalesce((p_usage ->> 'cost_available')::boolean, false))
  on conflict (usage_date, provider_slug, model_id) do update set
    requests = ai_content_usage.requests + 1,
    succeeded = ai_content_usage.succeeded + excluded.succeeded,
    failed = ai_content_usage.failed + excluded.failed,
    not_configured = ai_content_usage.not_configured + excluded.not_configured,
    tokens_in = ai_content_usage.tokens_in + excluded.tokens_in,
    tokens_out = ai_content_usage.tokens_out + excluded.tokens_out,
    cost_usd = ai_content_usage.cost_usd + excluded.cost_usd,
    -- Once true it stays true for the day: some responses carry usage and some
    -- do not, and the console needs to know figures were reported at all.
    usage_available = ai_content_usage.usage_available or excluded.usage_available,
    cost_available = ai_content_usage.cost_available or excluded.cost_available,
    updated_at = now();
end;
$$;


--
-- Name: mm_ai_validate(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_ai_validate(p_item uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  i record;
  s record;
  v_limits jsonb;
  v_min integer; v_max integer;
  v_errors jsonb := '[]'::jsonb;
  v_warnings jsonb := '[]'::jsonb;
  v_len integer;
  v_count integer;
  v_text text;
  v_legal jsonb;
  v_dup jsonb;
  v_blocked boolean := false;
  v_review boolean := false;
  v_phrase text;
  v_element jsonb;
  v_grounding numeric := 1;
  v_completeness numeric := 1;
begin
  if not public.mm_is_operator() then
    return jsonb_build_object('ok', false, 'reason', 'not_authorized');
  end if;

  select * into i from public.ai_content_items where id = p_item;
  if not found then return jsonb_build_object('ok', false, 'reason','item_not_found'); end if;
  select * into s from public.ai_content_settings where id;

  v_limits := coalesce(s.limits -> i.content_type, '{}'::jsonb);
  v_min := coalesce((v_limits ->> 'min')::int, 0);
  v_max := coalesce((v_limits ->> 'max')::int, 100000);

  -- The text this content type is actually judged on.
  if i.content_type in ('summary','short_description','long_description','seo_description') then
    v_text := coalesce(i.content, '');
    v_len := length(v_text);
    if v_len = 0 then
      v_errors := v_errors || jsonb_build_object('code','empty','detail','No content was produced.');
    else
      if v_len < v_min then
        v_errors := v_errors || jsonb_build_object('code','too_short',
          'detail', format('%s characters, minimum %s.', v_len, v_min));
      end if;
      if v_len > v_max then
        v_errors := v_errors || jsonb_build_object('code','too_long',
          'detail', format('%s characters, maximum %s.', v_len, v_max));
      end if;
    end if;
  else
    -- The structured blocks. Shape is checked, not just presence.
    if jsonb_typeof(i.content_json) <> 'array' then
      v_errors := v_errors || jsonb_build_object('code','malformed',
        'detail','Expected a list and did not get one.');
      v_count := 0;
    else
      v_count := jsonb_array_length(i.content_json);
      if v_count < v_min then
        v_errors := v_errors || jsonb_build_object('code','too_few',
          'detail', format('%s entries, minimum %s.', v_count, v_min));
      end if;
      if v_count > v_max then
        v_warnings := v_warnings || jsonb_build_object('code','too_many',
          'detail', format('%s entries, maximum %s. The surplus will not be published.', v_count, v_max));
      end if;

      if i.content_type = 'faq' then
        for v_element in select * from jsonb_array_elements(i.content_json) loop
          if coalesce(v_element ->> 'question','') = '' or coalesce(v_element ->> 'answer','') = '' then
            v_errors := v_errors || jsonb_build_object('code','malformed_faq',
              'detail','An entry is missing its question or its answer.');
            exit;
          end if;
        end loop;
      elsif i.content_type = 'features' then
        for v_element in select * from jsonb_array_elements(i.content_json) loop
          if coalesce(v_element ->> 'text','') = '' then
            v_errors := v_errors || jsonb_build_object('code','malformed_feature',
              'detail','A feature has no text.');
            exit;
          end if;
          -- 11/38. A feature with no stated source is treated as a suggestion,
          -- never as verified product data.
          if coalesce(v_element ->> 'source','') not in ('PRODUCT_DATA','MANUAL','AI_SUGGESTION') then
            v_warnings := v_warnings || jsonb_build_object('code','unsourced_feature',
              'detail','A feature carries no source and is being treated as an AI suggestion.');
          end if;
        end loop;
      elsif i.content_type = 'use_cases' then
        for v_element in select * from jsonb_array_elements(i.content_json) loop
          if coalesce(v_element ->> 'title','') = '' then
            v_errors := v_errors || jsonb_build_object('code','malformed_use_case',
              'detail','A use case has no title.');
            exit;
          end if;
        end loop;
      end if;
    end if;
    -- The structured blocks are scanned as their flattened text, so a legal
    -- claim hidden inside an FAQ answer is caught exactly as one in a
    -- paragraph would be.
    if jsonb_typeof(i.content_json) = 'array' then
      select coalesce(string_agg(t.v, ' '), '') into v_text
        from jsonb_array_elements(i.content_json) e,
             lateral (select case
                        when jsonb_typeof(e.value) = 'string' then e.value #>> '{}'
                        when jsonb_typeof(e.value) = 'object' then
                          (select string_agg(x.value, ' ') from jsonb_each_text(e.value) x)
                        else e.value::text end as v) t;
    else
      v_text := coalesce(i.content_json::text, '');
    end if;
  end if;

  -- 35. Brand voice: a prohibited phrase is a hard failure, not a suggestion.
  for v_phrase in select jsonb_array_elements_text(s.brand_voice -> 'prohibited_phrases') loop
    if v_text ilike '%' || v_phrase || '%' then
      v_errors := v_errors || jsonb_build_object('code','prohibited_phrase',
        'detail', format('Contains the prohibited phrase "%s".', v_phrase));
    end if;
  end loop;

  -- 20. The legal scan.
  v_legal := public.mm_ai_legal_scan(v_text);
  if jsonb_array_length(v_legal) > 0 then
    v_blocked := exists (select 1 from jsonb_array_elements(v_legal) f where f ->> 'action' = 'block');
    v_review  := not v_blocked;
  end if;

  -- 31. Duplicate standing, for the prose types only.
  if i.content_type in ('summary','short_description','long_description') then
    v_dup := public.mm_ai_duplicate_check(i.product_id, coalesce(i.content,''));
  else
    v_dup := jsonb_build_object('state','UNCHECKED','score',null,'product',null);
  end if;
  if v_dup ->> 'state' = 'DUPLICATE' then
    v_errors := v_errors || jsonb_build_object('code','duplicate',
      'detail', format('Reads as a duplicate of "%s" (similarity %s).',
                       coalesce(v_dup ->> 'product_name','another product'), v_dup ->> 'score'));
  elsif v_dup ->> 'state' = 'HIGH_SIMILARITY' then
    v_warnings := v_warnings || jsonb_build_object('code','high_similarity',
      'detail', format('Similar to "%s" (similarity %s).',
                       coalesce(v_dup ->> 'product_name','another product'), v_dup ->> 'score'));
  end if;

  -- 53. Measured quantities, and each one is a measurement of the text or of
  -- the record — never a model's opinion about whether the copy is true.
  -- Grounding is the share of the fact fields that the product record actually
  -- supplied when this was generated: copy written from eight facts is better
  -- grounded than copy written from two, and that is all the number says.
  select case when coalesce(array_length(g.context_fields, 1), 0)
                 + coalesce(array_length(g.missing_fields, 1), 0) = 0
              then null
              else round(coalesce(array_length(g.context_fields, 1), 0)::numeric
                   / (coalesce(array_length(g.context_fields, 1), 0)
                      + coalesce(array_length(g.missing_fields, 1), 0)), 2)
         end
    into v_grounding
    from public.ai_content_generations g
   where g.product_id = i.product_id and g.status = 'SUCCEEDED'
   order by g.created_at desc limit 1;

  v_completeness := case when jsonb_array_length(v_errors) > 0 then 0.4
                         when jsonb_array_length(v_warnings) > 0 then 0.75
                         else 1.0 end;

  update public.ai_content_items
     set validation = jsonb_build_object(
           'checked_at', now(),
           'errors', v_errors,
           'warnings', v_warnings,
           'length', v_len,
           'entries', v_count,
           'scores', jsonb_build_object(
             'label','AI evaluation, not an independent verification',
             'completeness', v_completeness,
             'grounding', v_grounding,
             'duplicate_risk', coalesce((v_dup ->> 'score')::numeric, 0),
             'legal_risk', case when v_blocked then 1 when v_review then 0.5 else 0 end)),
         validation_state = case when jsonb_array_length(v_errors) > 0 then 'FAILED' else 'PASSED' end,
         legal_findings = v_legal,
         legal_state = case
           -- A new blocking finding always wins, whatever was decided before.
           when v_blocked then 'BLOCKED'
           when v_review then 'REVIEW_REQUIRED'
           -- A decision a reviewer already made about this text stands.
           -- Re-validation used to overturn it, so content could be cleared and
           -- then refused approval a moment later for want of the very
           -- clearance it had just been given. Every path that changes the text
           -- clears legal_reviewed_at, so this can only preserve a decision
           -- about the text actually in front of the reviewer.
           when i.legal_reviewed_at is not null and i.legal_state = 'CLEARED' then 'CLEARED'
           when i.content_type = any (s.legal_review_types) then 'REVIEW_REQUIRED'
           else 'CLEARED' end,
         duplicate_state = coalesce(v_dup ->> 'state', 'UNCHECKED'),
         duplicate_score = (v_dup ->> 'score')::numeric,
         duplicate_of = nullif(v_dup ->> 'product','')::uuid
   where id = p_item;

  return jsonb_build_object(
    'ok', jsonb_array_length(v_errors) = 0,
    'errors', v_errors,
    'warnings', v_warnings,
    'legal', v_legal,
    'legal_blocked', v_blocked,
    'duplicate', v_dup);
end;
$$;


--
-- Name: mm_ai_version_rollback(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_ai_version_rollback(p_item uuid, p_version integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare i record; v record;
begin
  if not public.mm_is_operator() then
    return jsonb_build_object('ok', false, 'reason','not_authorized');
  end if;
  select * into i from public.ai_content_items where id = p_item;
  if not found then return jsonb_build_object('ok', false, 'reason','item_not_found'); end if;
  select * into v from public.ai_content_versions where item_id = p_item and version = p_version;
  if not found then return jsonb_build_object('ok', false, 'reason','version_not_found'); end if;

  -- A rollback is itself a new version. The trail only ever grows.
  insert into public.ai_content_versions (
    item_id, version, kind, content, content_json, previous_content, previous_content_json,
    status_before, status_after, context_hash, actor, note)
  values (p_item, i.current_version + 1, 'ROLLBACK', v.content, v.content_json,
          i.content, i.content_json, i.status, 'IN_REVIEW', v.context_hash, auth.uid(),
          format('Restored version %s.', p_version));

  update public.ai_content_items
     set content = v.content, content_json = v.content_json,
         current_version = i.current_version + 1,
         status = case when status = 'PUBLISHED' then 'PUBLISHED' else 'IN_REVIEW' end,
         approved_at = null, approved_by = null, validation_state = 'PENDING',
         legal_reviewed_at = null, legal_reviewed_by = null
   where id = p_item;

  perform public.mm_ai_validate(p_item);
  perform public.mm_audit('ai_content.rollback', 'ai_content_item', p_item::text,
    jsonb_build_object('version', i.current_version), jsonb_build_object('restored', p_version),
    format('Rolled back to version %s', p_version));

  return jsonb_build_object('ok', true, 'restored_from', p_version, 'version', i.current_version + 1);
end;
$$;


--
-- Name: mm_approval_rule_set(text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_approval_rule_set(p_key text, p_patch jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_before jsonb; v_after jsonb;
begin
  if not public.mm_is_operator() then
    return jsonb_build_object('ok', false, 'reason', 'not_permitted');
  end if;
  select to_jsonb(r) into v_before from public.author_approval_rules r where r.key = p_key;
  if v_before is null then
    return jsonb_build_object('ok', false, 'reason', 'unknown_rule');
  end if;

  update public.author_approval_rules set
    enabled = coalesce((p_patch->>'enabled')::boolean, enabled),
    config = coalesce(p_patch->'config', config),
    updated_by = auth.uid(), updated_at = now()
  where key = p_key returning to_jsonb(author_approval_rules) into v_after;

  perform public.mm_audit('approval.rule_changed','author_approval_rule', p_key,
                          v_before, v_after, nullif(p_patch->>'reason',''));
  return jsonb_build_object('ok', true, 'rule', v_after);
end;
$$;


--
-- Name: mm_approval_sla_run(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_approval_sla_run() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_sla record; v_due integer := 0; v_breached integer := 0; v_stale integer := 0; r record;
begin
  if not public.mm_reseller_operator() and not public.mm_is_operator() then
    return jsonb_build_object('ok', false, 'reason', 'not_permitted');
  end if;
  select * into v_sla from public.author_approval_sla where id;

  -- Approaching: a reminder, not an alarm.
  select count(*) into v_due from public.author_submissions
   where status in ('pending_review','verifying')
     and sla_due_at between now() and now() + interval '4 hours';

  for r in
    select * from public.author_submissions
     where status in ('pending_review','verifying')
       and escalate_at <= now() and escalated_at is null
  loop
    v_breached := v_breached + 1;
    update public.author_submissions set escalated_at = now(), updated_at = now()
     where id = r.id;

    perform public.mm_notify(
      'submission.sla_breached',
      format('%s has passed its escalation window', r.submission_no),
      format('Submitted %s and still %s. The %s hour escalation window has passed.',
             to_char(r.submitted_at,'DD Mon HH24:MI'), r.status, v_sla.escalate_hours),
      null, array['admin','boss'], '/marketplace-manager', 'Review', 60, 'danger');

    insert into public.author_approval_history
      (submission_id, revision, action, from_status, to_status, actor_role, reason)
    values (r.id, r.revision, 'sla_escalated', r.status, r.status, 'system',
            format('No decision within the configured %s hour escalation window.',
                   v_sla.escalate_hours));
  end loop;

  -- Stale drafts are reported, never auto-rejected. Section 8 says a score may
  -- not decide anything on its own, and neither should a clock.
  select count(*) into v_stale from public.author_submissions
   where status = 'draft'
     and created_at <= now() - (v_sla.stale_draft_days || ' days')::interval;

  return jsonb_build_object('ok', true,
    'response_hours', v_sla.response_hours,
    'escalate_hours', v_sla.escalate_hours,
    'stale_draft_days', v_sla.stale_draft_days,
    'due_soon', v_due, 'escalated', v_breached, 'stale_drafts', v_stale,
    'note','Stale drafts are reported for a person to decide on; nothing is auto-rejected.');
end;
$$;


--
-- Name: mm_approval_sla_set(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_approval_sla_set(p_patch jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_before jsonb; v_after jsonb;
begin
  if not public.mm_is_operator() then
    return jsonb_build_object('ok', false, 'reason', 'not_permitted');
  end if;
  select to_jsonb(s) into v_before from public.author_approval_sla s where s.id;

  update public.author_approval_sla set
    response_hours = coalesce((p_patch->>'response_hours')::int, response_hours),
    escalate_hours = coalesce((p_patch->>'escalate_hours')::int, escalate_hours),
    stale_draft_days = coalesce((p_patch->>'stale_draft_days')::int, stale_draft_days),
    updated_by = auth.uid(), updated_at = now()
  where id returning to_jsonb(author_approval_sla) into v_after;

  perform public.mm_audit('approval.sla_changed','author_approval_sla','sla',
                          v_before, v_after, null);
  return jsonb_build_object('ok', true, 'sla', v_after);
end;
$$;


--
-- Name: mm_attention_center(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_attention_center() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select jsonb_build_object(
    'generated_at', now(),
    'items', coalesce((
      select jsonb_agg(item order by weight desc)
      from (
        -- Catalogue problems, from the health checks so the two can never
        -- disagree with one another.
        select jsonb_build_object(
                 'key', check_key, 'label', label, 'count', affected,
                 'severity', severity, 'destination', destination) as item,
               case severity when 'critical' then 4 when 'high' then 3
                             when 'medium' then 2 else 1 end as weight
        from public.mm_health_checks()
        where affected > 0

        union all
        -- Legal Manager is the source of truth for compliance; this only asks.
        select jsonb_build_object(
                 'key', 'legal_pending_review', 'label', 'AI legal output awaiting review',
                 'count', count(*), 'severity', 'medium',
                 'destination', '/legal-manager'), 2
        from public.legal_ai_requests where review_status = 'unreviewed'
        having count(*) > 0

        union all
        -- Task Manager owns the work; this counts what marketing and
        -- marketplace raised and nobody has picked up.
        select jsonb_build_object(
                 'key', 'tasks_unclaimed', 'label', 'Marketplace tasks nobody has taken',
                 'count', count(*), 'severity', 'high',
                 'destination', '/task-manager'), 3
        from public.tm_tasks
        where module in ('marketplace_manager','marketing_manager')
          and assigned_to is null
          and status in ('new','routed','available_for_claim','assigned')
        having count(*) > 0

        union all
        -- Promise Tracker owns commitments; this counts the ones already late.
        select jsonb_build_object(
                 'key', 'promises_overdue', 'label', 'Marketplace commitments past their deadline',
                 'count', count(*), 'severity', 'critical',
                 'destination', '/promise-tracker/delayed'), 4
        from public.promises
        where linked_module in ('marketplace_manager','marketing_manager')
          and status in ('delayed','broken')
        having count(*) > 0

        union all
        -- Server Manager owns infrastructure; this surfaces an unhealthy host.
        select jsonb_build_object(
                 'key', 'infrastructure_degraded', 'label', 'A server is not healthy',
                 'count', count(*), 'severity', 'critical',
                 'destination', '/server-manager'), 4
        from public.server_instances
        where health_status <> 'healthy'
        having count(*) > 0

        union all
        select jsonb_build_object(
                 'key', 'orders_refunded', 'label', 'Refunds recorded against orders',
                 'count', count(*), 'severity', 'medium',
                 'destination', '/marketplace-manager?section=orders&filter=refunded'), 2
        from public.marketplace_order_refunds
        having count(*) > 0
      ) signals), '[]'::jsonb));
$$;


--
-- Name: mm_audience(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_audience(p_segment text DEFAULT 'all'::text, p_channel text DEFAULT 'email'::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_total integer; v_reachable integer;
begin
  if not public.mm_is_operator() then
    return jsonb_build_object('ok', false, 'reason', 'not_permitted');
  end if;

  with base as (
    select u.id,
           (select count(*) from public.marketplace_orders o
             where o.buyer_id = u.id and o.status::text = 'paid') as paid_orders,
           coalesce((select sum(o.total) from public.marketplace_orders o
                      where o.buyer_id = u.id and o.status::text = 'paid'), 0) as lifetime_value,
           u.last_sign_in_at
      from auth.users u
  ),
  segmented as (
    select b.* from base b
     where case p_segment
             when 'all'         then true
             when 'customers'   then b.paid_orders > 0
             when 'registered'  then b.paid_orders = 0
             when 'vip'         then b.paid_orders > 1 or b.lifetime_value > 249
             when 'inactive_30d' then b.last_sign_in_at is null
                                    or b.last_sign_in_at < now() - interval '30 days'
             else true
           end
  )
  select count(*),
         count(*) filter (where exists (
           select 1 from public.marketing_consents mc
            where mc.user_id = segmented.id and mc.channel = p_channel and mc.granted))
    into v_total, v_reachable
    from segmented;

  return jsonb_build_object(
    'ok', true,
    'segment', p_segment,
    'channel', p_channel,
    'in_segment', v_total,
    -- Consent is the gate. Nobody is reachable until they have agreed.
    'reachable', v_reachable,
    'blocked_by_consent', v_total - v_reachable,
    'consent_records', (select count(*) from public.marketing_consents),
    'note', case when v_reachable = 0
                 then 'No customer has recorded consent for this channel, so nothing may be sent to any of them.'
                 else null end);
end;
$$;


--
-- Name: mm_audit(text, text, text, jsonb, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_audit(p_action text, p_entity_type text, p_entity_id text DEFAULT NULL::text, p_before jsonb DEFAULT NULL::jsonb, p_after jsonb DEFAULT NULL::jsonb, p_reason text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_id uuid; v_email text; v_role text; v_entity uuid;
begin
  select u.email into v_email from auth.users u where u.id = auth.uid();
  select ur.role::text into v_role from public.user_roles ur where ur.user_id = auth.uid() limit 1;

  -- entity_id on this table is a uuid. Callers pass text because not every
  -- entity in the marketplace is keyed by one; anything that is not a uuid is
  -- kept in the metadata rather than dropped.
  begin
    v_entity := p_entity_id::uuid;
  exception when others then
    v_entity := null;
  end;

  insert into public.marketplace_audit_logs
    (action, entity_type, entity_id, actor, actor_id, actor_role,
     before_state, after_state, reason, module, metadata)
  values
    (p_action, p_entity_type, v_entity,
     coalesce(v_email, case when auth.uid() is null then 'system' else 'account' end),
     auth.uid(), coalesce(v_role, 'system'),
     p_before, p_after, p_reason, 'marketplace_manager',
     jsonb_build_object('entity', p_entity_type, 'entity_ref', p_entity_id))
  returning id into v_id;
  return v_id;
end;
$$;


--
-- Name: mm_audit_is_append_only(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_audit_is_append_only() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  raise exception 'the marketplace audit log is append-only; % is not permitted', tg_op
    using errcode = 'insufficient_privilege';
end;
$$;


--
-- Name: mm_brand_asset_verify(text, text, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_brand_asset_verify(p_key text, p_observed_sha text, p_observed_bytes bigint DEFAULT NULL::bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_a record;
begin
  if not public.mm_is_operator() then
    return jsonb_build_object('ok', false, 'reason','not_permitted');
  end if;
  select * into v_a from public.brand_assets where key = p_key;
  if not found then return jsonb_build_object('ok', false, 'reason','unknown_asset'); end if;

  if v_a.sha256 is null then
    return jsonb_build_object('ok', true, 'state','no_baseline',
      'message','This asset has no recorded hash, so nothing can be compared.');
  end if;

  if v_a.sha256 = p_observed_sha then
    return jsonb_build_object('ok', true, 'state','intact', 'sha256', v_a.sha256);
  end if;

  -- A canonical asset that changed unexpectedly is a security event.
  insert into public.brand_protection_events (event, actor_id, previous_state, new_state, reason, detail)
  values ('asset.integrity_failed', auth.uid(), v_a.sha256, p_observed_sha,
          format('The canonical asset %s no longer matches its recorded hash.', p_key),
          jsonb_build_object('asset', p_key, 'expected', v_a.sha256,
                             'observed', p_observed_sha, 'observed_bytes', p_observed_bytes));

  perform public.mm_notify('brand.integrity',
    'A canonical brand asset changed unexpectedly',
    format('%s no longer matches its recorded SHA-256. Enforcement using it should be paused until this is explained.', p_key),
    null, array['admin','boss'], '/marketplace-manager', 'Review', 5, 'danger');

  return jsonb_build_object('ok', false, 'state','mismatch',
    'expected', v_a.sha256, 'observed', p_observed_sha,
    'message','The canonical asset does not match its recorded hash. A security event was raised.');
end;
$$;


--
-- Name: mm_brand_case_escalate(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_brand_case_escalate(p_case uuid, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_c record; v_ref text; v_after jsonb;
begin
  if not public.mm_is_operator() then
    return jsonb_build_object('ok', false, 'reason','not_permitted');
  end if;
  if coalesce(btrim(p_reason),'') = '' then
    return jsonb_build_object('ok', false, 'reason','reason_required');
  end if;
  select * into v_c from public.brand_violation_cases where id = p_case;
  if not found then return jsonb_build_object('ok', false, 'reason','unknown_case'); end if;

  v_ref := 'LEGAL-BR-' || upper(substr(md5(p_case::text),1,8));

  update public.brand_violation_cases
     set status='escalated', legal_reference = v_ref
   where id = p_case returning to_jsonb(brand_violation_cases) into v_after;

  insert into public.brand_protection_events
    (product_id, case_id, event, actor_id, previous_state, new_state, reason)
  values (v_c.product_id, p_case, 'legal.escalated', auth.uid(), v_c.status, 'escalated', btrim(p_reason));

  perform public.mm_notify('brand.legal_escalation',
    format('Branding case %s raised with Legal', v_c.case_no),
    btrim(p_reason), null, array['admin','boss'], '/legal-manager', 'Open', 5, 'warning');

  return jsonb_build_object('ok', true, 'case', v_after, 'legal_reference', v_ref,
    'note','The reference is recorded here. The legal record itself belongs to Legal Manager and must be raised there; legal_trademark_assets and legal_violations are not written by brand protection.');
end;
$$;


--
-- Name: mm_brand_detect(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_brand_detect(p_product uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare
  v_p record; v_findings jsonb := '[]'::jsonb; r record;
  v_ref text; v_canonical record; v_class text; v_whitelisted boolean;
begin
  select * into v_p from public.marketplace_products where id = p_product;
  if not found then
    return jsonb_build_object('ok', false, 'reason','unknown_product');
  end if;

  for r in select * from public.brand_enforcement_rules where enabled order by key loop
    v_ref := case r.target
      when 'product_favicon'  then nullif(btrim(coalesce(v_p.favicon,'')),'')
      when 'product_logo'     then nullif(btrim(coalesce(v_p.logo,'')),'')
      when 'product_og_image' then nullif(btrim(coalesce(v_p.cover_image,'')),'')
      when 'demo_favicon'     then nullif(btrim(coalesce(v_p.demo_url,'')),'')
      else null end;

    select * into v_canonical from public.brand_assets
     where key = r.canonical_asset_key;

    -- An active exception is honoured, and recorded as such rather than
    -- silently skipping the check.
    select exists (
      select 1 from public.brand_whitelist_exceptions w
       where w.product_id = p_product and w.rule_key = r.key
         and w.status = 'active'
         and (w.expires_at is null or w.expires_at > now()))
      into v_whitelisted;

    v_class := case
      when v_ref is null then 'approved'
      when v_canonical.public_path is not null and v_ref = v_canonical.public_path then 'approved'
      when v_whitelisted then 'whitelisted'
      -- A reference to this application's own origin is ours; anything else is
      -- external and unknown until somebody classifies it.
      when v_ref ~ '^/' then 'unknown'
      when v_ref ~* '^https?://(www\.)?softwarevala\.net(/|$)' then 'approved'
      else 'unknown' end;

    v_findings := v_findings || jsonb_build_object(
      'rule', r.key, 'label', r.label, 'target', r.target,
      'action', r.action, 'severity', r.severity,
      'reference', v_ref,
      'classification', v_class,
      'whitelisted', v_whitelisted,
      'compliant', v_ref is null or v_class in ('approved','whitelisted'),
      'canonical', case when v_canonical.active
                        then jsonb_build_object('key', v_canonical.key,
                               'path', v_canonical.public_path, 'sha256', v_canonical.sha256)
                        else null end,
      -- A rule whose canonical asset does not exist cannot replace anything,
      -- and says so instead of pretending.
      'enforceable', v_canonical.active is true,
      'why', case
        when v_ref is null then 'Nothing is set, so the Software Vala default applies.'
        when v_class = 'approved' then 'Already the canonical Software Vala asset.'
        when v_whitelisted then 'An approved whitelist exception is in force for this product and rule.'
        when v_canonical.active is not true then
          format('Non-compliant, but no approved canonical asset exists for %s, so nothing can be substituted.',
                 r.canonical_asset_key)
        else 'Points at branding that is not the canonical Software Vala asset.' end);
  end loop;

  return jsonb_build_object(
    'ok', true, 'product_id', p_product, 'product', v_p.name,
    'findings', v_findings,
    'non_compliant', (select count(*) from jsonb_array_elements(v_findings) f
                       where not (f->>'compliant')::boolean),
    -- Named explicitly, because it is the rule most easily broken by accident.
    'scope_note','Only marketplace surface branding is inspected. The contents of a downloadable software package are never read or rewritten by brand protection.');
end;
$_$;


--
-- Name: mm_brand_enforce(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_brand_enforce(p_product uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 500) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_s record; v_run uuid; v_p record; v_det jsonb; f jsonb;
  v_scanned integer := 0; v_compliant integer := 0; v_replaced integer := 0;
  v_blocked integer := 0; v_flagged integer := 0; v_white integer := 0;
  v_failed integer := 0;
  v_case uuid; v_no text; v_canonical record; v_before text; v_after text;
  v_verified boolean; v_seller uuid;
begin
  if not public.mm_is_operator() then
    return jsonb_build_object('ok', false, 'reason','not_permitted');
  end if;
  select * into v_s from public.brand_protection_settings where id;

  if v_s.policy_state = 'disabled' then
    return jsonb_build_object('ok', false, 'reason','protection_disabled',
      'message','Brand protection is disabled. An admin has to switch it back to monitor or enforce.');
  end if;

  insert into public.brand_enforcement_runs (scope, policy_state, started_by)
  values (coalesce(p_product::text,'all'), v_s.policy_state, auth.uid())
  returning id into v_run;

  for v_p in
    select * from public.marketplace_products
     where (p_product is null or id = p_product)
       and deleted_at is null
     order by updated_at desc
     limit greatest(least(p_limit, 5000), 1)
  loop
    v_scanned := v_scanned + 1;
    v_det := public.mm_brand_detect(v_p.id);

    for f in select * from jsonb_array_elements(v_det->'findings') loop
      if (f->>'compliant')::boolean then
        if (f->>'whitelisted')::boolean then v_white := v_white + 1;
        else v_compliant := v_compliant + 1; end if;
        continue;
      end if;

      v_no := 'BR-' || lpad(((select count(*) from public.brand_violation_cases) + 1)::text, 6, '0');

      insert into public.brand_violation_cases
        (case_no, product_id, seller_id, rule_key, surface, asset_reference,
         classification, severity, evidence, status)
      values (v_no, v_p.id, v_p.seller_id, f->>'rule',
              f->>'target', f->>'reference',
              f->>'classification', f->>'severity',
              jsonb_build_array(jsonb_build_object(
                'reference', f->>'reference',
                'why', f->>'why',
                'enforceable', (f->>'enforceable')::boolean)),
              'open')
      returning id into v_case;

      -- MONITOR records and changes nothing.
      if v_s.policy_state = 'monitor' then
        v_flagged := v_flagged + 1;
        update public.brand_violation_cases set status='open' where id=v_case;
        insert into public.brand_protection_events (product_id, case_id, event, actor_id, detail)
        values (v_p.id, v_case, 'violation.detected', auth.uid(),
                jsonb_build_object('policy','monitor','rule', f->>'rule'));
        continue;
      end if;

      -- ENFORCE. Only a rule with an approved canonical asset and the replace
      -- action can substitute anything.
      if (f->>'action') = 'replace' and (f->>'enforceable')::boolean then
        select * into v_canonical from public.brand_assets
         where key = (f->'canonical'->>'key');

        v_before := f->>'reference';

        if (f->>'target') = 'product_favicon' then
          update public.marketplace_products
             set favicon = v_canonical.public_path, updated_at = now()
           where id = v_p.id;
          select favicon into v_after from public.marketplace_products where id = v_p.id;
        elsif (f->>'target') = 'product_logo' then
          update public.marketplace_products
             set logo = v_canonical.public_path, updated_at = now()
           where id = v_p.id;
          select logo into v_after from public.marketplace_products where id = v_p.id;
        else
          v_after := null;
        end if;

        -- 23. Read back. A replacement is only a replacement if it took.
        v_verified := v_after is not null and v_after = v_canonical.public_path;

        insert into public.brand_replacement_history
          (case_id, product_id, rule_key, surface, original_reference,
           replacement_asset_key, replacement_reference, replacement_sha256,
           actor_id, actor_kind, reason, verified, verification_detail)
        values (v_case, v_p.id, f->>'rule', f->>'target', v_before,
                v_canonical.key, v_canonical.public_path, v_canonical.sha256,
                auth.uid(), 'system',
                'Automatic enforcement of the canonical Software Vala asset.',
                v_verified,
                case when v_verified then 'Read back and matches the canonical path.'
                     else format('Read back as %s, expected %s.',
                                 coalesce(v_after,'null'), v_canonical.public_path) end);

        if v_verified then
          v_replaced := v_replaced + 1;
          update public.brand_violation_cases set status='replaced',
                 resolved_by = auth.uid(), resolved_at = now() where id=v_case;
          insert into public.brand_protection_events
            (product_id, case_id, event, actor_id, previous_state, new_state, reason)
          values (v_p.id, v_case, 'asset.replaced', auth.uid(), v_before,
                  v_canonical.public_path, 'Canonical asset enforced.');
        else
          v_failed := v_failed + 1;
          update public.brand_violation_cases set status='failed' where id=v_case;
          insert into public.brand_protection_events
            (product_id, case_id, event, actor_id, new_state, reason)
          values (v_p.id, v_case, 'enforcement.failed', auth.uid(), 'ENFORCEMENT_FAILED',
                  'The replacement did not read back as the canonical asset.');
        end if;

      elsif (f->>'action') = 'block' then
        v_blocked := v_blocked + 1;
        update public.brand_violation_cases set status='blocked' where id=v_case;
        insert into public.brand_protection_events (product_id, case_id, event, actor_id, new_state)
        values (v_p.id, v_case, 'violation.blocked', auth.uid(), 'blocked');

      else
        -- Flag or monitor, or a replace rule with no canonical asset to use.
        v_flagged := v_flagged + 1;
        insert into public.brand_protection_events (product_id, case_id, event, actor_id, reason)
        values (v_p.id, v_case, 'violation.flagged', auth.uid(), f->>'why');
      end if;

      -- 15/16. A repeated or trademark-shaped violation is raised to the people
      -- who decide, through the notification engine.
      select seller_id into v_seller from public.marketplace_products where id = v_p.id;
      if (f->>'severity') in ('high','critical') then
        perform public.mm_notify('brand.violation',
          format('Branding violation on %s', v_p.name),
          format('%s — %s', f->>'label', f->>'why'),
          null, array['admin','boss'], '/marketplace-manager', 'Review', 60, 'warning');
      end if;
    end loop;
  end loop;

  update public.brand_enforcement_runs
     set scanned = v_scanned, compliant = v_compliant, replaced = v_replaced,
         blocked = v_blocked, flagged = v_flagged, whitelisted = v_white,
         failed = v_failed, completed_at = now(),
         detail = jsonb_build_object(
           'policy', v_s.policy_state,
           'note', case when v_s.policy_state='monitor'
             then 'Monitor mode: every non-compliant asset was recorded and nothing was changed.'
             else 'Enforce mode: replacements were applied only where an approved canonical asset exists, and each was read back.' end)
   where id = v_run;

  perform public.mm_audit('brand.enforcement_run','brand_enforcement_run', v_run::text, null,
    jsonb_build_object('scanned',v_scanned,'replaced',v_replaced,'failed',v_failed), null);

  return jsonb_build_object('ok', true, 'run_id', v_run,
    'policy', v_s.policy_state,
    'scanned', v_scanned, 'compliant', v_compliant, 'replaced', v_replaced,
    'blocked', v_blocked, 'flagged', v_flagged, 'whitelisted', v_white,
    'failed', v_failed,
    'note', case when v_s.policy_state='monitor'
      then 'Monitor mode. Nothing was changed; every non-compliant asset is recorded as a case.'
      else null end);
end;
$$;


--
-- Name: mm_brand_policy_set(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_brand_policy_set(p_patch jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_before jsonb; v_after jsonb; v_to text := nullif(p_patch->>'policy_state','');
begin
  if not public.mm_is_operator() then
    return jsonb_build_object('ok', false, 'reason','not_permitted');
  end if;

  -- Turning protection off entirely needs elevated permission. An ordinary
  -- manager can move between monitor and enforce, and no further.
  if v_to = 'disabled'
     and not (public.has_role(auth.uid(),'admin') or public.has_role(auth.uid(),'boss')
              or public.has_role(auth.uid(),'super_admin')) then
    return jsonb_build_object('ok', false, 'reason','elevated_permission_required',
      'message','Only an admin or the boss can disable brand protection.');
  end if;
  if v_to = 'disabled' and coalesce(btrim(p_patch->>'reason'),'') = '' then
    return jsonb_build_object('ok', false, 'reason','reason_required',
      'message','Disabling brand protection has to say why. It is recorded permanently.');
  end if;

  select to_jsonb(s) into v_before from public.brand_protection_settings s where s.id;

  update public.brand_protection_settings set
    policy_state = coalesce(v_to, policy_state),
    block_third_party_favicons = coalesce((p_patch->>'block_third_party_favicons')::boolean, block_third_party_favicons),
    block_third_party_manifest = coalesce((p_patch->>'block_third_party_manifest')::boolean, block_third_party_manifest),
    block_external_logo_overrides = coalesce((p_patch->>'block_external_logo_overrides')::boolean, block_external_logo_overrides),
    replace_on_upload = coalesce((p_patch->>'replace_on_upload')::boolean, replace_on_upload),
    allow_whitelist_exceptions = coalesce((p_patch->>'allow_whitelist_exceptions')::boolean, allow_whitelist_exceptions),
    updated_by = auth.uid(), updated_at = now()
  where id returning to_jsonb(brand_protection_settings) into v_after;

  insert into public.brand_protection_events (event, actor_id, previous_state, new_state, reason)
  values ('policy.changed', auth.uid(), v_before->>'policy_state',
          v_after->>'policy_state', nullif(p_patch->>'reason',''));

  perform public.mm_audit('brand.policy_changed','brand_protection_settings','policy',
                          v_before, v_after, nullif(p_patch->>'reason',''));
  return jsonb_build_object('ok', true, 'settings', v_after);
end;
$$;


--
-- Name: mm_brand_protection(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_brand_protection(p_query jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_tab text := coalesce(p_query->>'tab','cases');
  v_search text := nullif(btrim(coalesce(p_query->>'search','')),'');
  v_status text := nullif(p_query->>'status','');
  v_limit integer := least(greatest(coalesce((p_query->>'limit')::int,50),1),200);
  v_settings record; v_vision text;
begin
  if not public.mm_is_operator() then
    return jsonb_build_object('ok', false, 'reason','not_permitted');
  end if;
  select * into v_settings from public.brand_protection_settings where id;

  -- 21. Vision analysis, stated honestly. No provider is configured in this
  -- environment, so no similarity percentage is ever produced.
  select case when exists (
    select 1 from public.security_provider_configs
     where kind='ai' and enabled and verified)
    then 'CONNECTED' else 'VISION_ANALYSIS_NOT_CONFIGURED' end into v_vision;

  return jsonb_build_object(
    'ok', true, 'tab', v_tab,
    'settings', to_jsonb(v_settings),
    'vision_analysis', v_vision,
    'vision_note', case when v_vision <> 'CONNECTED'
      then 'No vision-capable provider is configured, so logo and favicon images are not compared for similarity. Detection below is exact-reference matching only, and no confidence figure is produced.'
      else null end,

    -- The four metric cards. Every one counted.
    'protected_assets', (select count(*) from public.brand_assets where approved and active),
    'replaced_today', (select count(*) from public.brand_replacement_history
                        where verified and created_at >= date_trunc('day', now())),
    'violations_open', (select count(*) from public.brand_violation_cases
                         where status in ('open','escalated','failed')),
    'whitelist_active', (select count(*) from public.brand_whitelist_exceptions
                          where status='active' and (expires_at is null or expires_at > now())),

    -- The surfaces this actually governs, counted from the catalogue.
    'surfaces', jsonb_build_object(
      'products', (select count(*) from public.marketplace_products where deleted_at is null),
      'products_with_own_favicon', (select count(*) from public.marketplace_products
                                     where coalesce(btrim(favicon),'') <> ''),
      'products_with_own_logo', (select count(*) from public.marketplace_products
                                  where coalesce(btrim(logo),'') <> ''),
      'demos', (select count(*) from public.marketplace_products
                 where coalesce(btrim(demo_url),'') <> '')),

    'assets', coalesce((select jsonb_agg(jsonb_build_object(
                 'key', a.key, 'name', a.name, 'type', a.asset_type,
                 'path', a.public_path, 'sha256', a.sha256,
                 'width', a.width, 'height', a.height, 'bytes', a.size_bytes,
                 'version', a.version, 'approved', a.approved, 'active', a.active,
                 'usable', a.active,
                 'note', case when a.active then null
                              else 'No file is registered for this asset, so no rule can use it to replace anything.' end)
               order by a.asset_type, a.key)
                 from public.brand_assets a), '[]'::jsonb),

    'rules', coalesce((select jsonb_agg(jsonb_build_object(
                'key', r.key, 'label', r.label, 'target', r.target,
                'action', r.action, 'severity', r.severity, 'enabled', r.enabled,
                'canonical', r.canonical_asset_key, 'notes', r.notes,
                'enforceable', exists (select 1 from public.brand_assets a
                                        where a.key = r.canonical_asset_key and a.active))
              order by r.key) from public.brand_enforcement_rules r), '[]'::jsonb),

    'last_run', (select to_jsonb(x) from (select * from public.brand_enforcement_runs
                   order by started_at desc limit 1) x),

    'cases', case when v_tab <> 'cases' then '[]'::jsonb else coalesce((
      select jsonb_agg(jsonb_build_object(
               'id', c.id, 'case_no', c.case_no, 'rule', c.rule_key,
               'surface', c.surface, 'reference', c.asset_reference,
               'classification', c.classification, 'severity', c.severity,
               'status', c.status, 'evidence', c.evidence,
               'legal_reference', c.legal_reference, 'created_at', c.created_at,
               'product_id', c.product_id,
               'product', (select name from public.marketplace_products where id=c.product_id),
               'owner', (select display_name from public.marketplace_sellers where id=c.seller_id))
             order by c.created_at desc)
        from (select * from public.brand_violation_cases
               where (v_status is null or status = v_status)
               order by created_at desc limit v_limit) c), '[]'::jsonb) end,

    'whitelist', case when v_tab <> 'whitelist' then '[]'::jsonb else coalesce((
      select jsonb_agg(jsonb_build_object(
               'id', w.id, 'rule', w.rule_key, 'reason', w.reason,
               'status', w.status, 'expires_at', w.expires_at,
               'approved_by', w.approved_by, 'created_at', w.created_at,
               'product', (select name from public.marketplace_products where id=w.product_id))
             order by w.created_at desc)
        from (select * from public.brand_whitelist_exceptions
               order by created_at desc limit v_limit) w), '[]'::jsonb) end,

    'history', case when v_tab <> 'history' then '[]'::jsonb else coalesce((
      select jsonb_agg(jsonb_build_object(
               'id', h.id, 'surface', h.surface, 'rule', h.rule_key,
               'from', h.original_reference, 'to', h.replacement_reference,
               'sha256', h.replacement_sha256, 'verified', h.verified,
               'detail', h.verification_detail, 'at', h.created_at,
               'product', (select name from public.marketplace_products where id=h.product_id))
             order by h.created_at desc)
        from (select * from public.brand_replacement_history
               order by created_at desc limit v_limit) h), '[]'::jsonb) end,

    'events', coalesce((select jsonb_agg(jsonb_build_object(
                 'event', e.event, 'at', e.created_at, 'reason', e.reason,
                 'from', e.previous_state, 'to', e.new_state)
               order by e.created_at desc)
                 from (select * from public.brand_protection_events
                        order by created_at desc limit 25) e), '[]'::jsonb),

    'scope_note','Brand protection governs Software Vala marketplace surfaces only. It never reads or rewrites the contents of a downloadable software package, so a customer''s software keeps its own branding.');
end;
$$;


--
-- Name: mm_brand_whitelist_decide(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_brand_whitelist_decide(p_id uuid, p_to text, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_before jsonb; v_after jsonb; v_settings record;
begin
  if not (public.has_role(auth.uid(),'admin') or public.has_role(auth.uid(),'boss')
          or public.has_role(auth.uid(),'super_admin')) then
    return jsonb_build_object('ok', false, 'reason','not_permitted',
      'message','Only an admin or the boss can approve or revoke a branding exception.');
  end if;
  if p_to not in ('active','revoked','expired') then
    return jsonb_build_object('ok', false, 'reason','unknown_state');
  end if;
  if p_to = 'revoked' and coalesce(btrim(p_reason),'') = '' then
    return jsonb_build_object('ok', false, 'reason','reason_required');
  end if;

  select * into v_settings from public.brand_protection_settings where id;
  if p_to = 'active' and not v_settings.allow_whitelist_exceptions then
    return jsonb_build_object('ok', false, 'reason','exceptions_disabled',
      'message','Whitelist exceptions are switched off in the global policy.');
  end if;

  select to_jsonb(w) into v_before from public.brand_whitelist_exceptions w where w.id = p_id;
  if v_before is null then return jsonb_build_object('ok', false, 'reason','unknown_exception'); end if;

  update public.brand_whitelist_exceptions
     set status = p_to,
         approved_by = case when p_to='active' then auth.uid() else approved_by end,
         approved_at = case when p_to='active' then now() else approved_at end,
         revoked_by = case when p_to='revoked' then auth.uid() else revoked_by end,
         revoked_reason = case when p_to='revoked' then btrim(p_reason) else revoked_reason end
   where id = p_id returning to_jsonb(brand_whitelist_exceptions) into v_after;

  insert into public.brand_protection_events
    (product_id, event, actor_id, previous_state, new_state, reason)
  values ((v_after->>'product_id')::uuid, 'whitelist.'||p_to, auth.uid(),
          v_before->>'status', p_to, p_reason);

  perform public.mm_audit('brand.whitelist_'||p_to,'brand_whitelist', p_id::text,
                          v_before, v_after, p_reason);

  return jsonb_build_object('ok', true, 'exception', v_after,
    'note','An exception never bypasses security scanning or a legal restriction; it only suspends the branding rule it names.');
end;
$$;


--
-- Name: mm_brand_whitelist_expire(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_brand_whitelist_expire() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_n integer;
begin
  if not public.mm_is_operator() then
    return jsonb_build_object('ok', false, 'reason','not_permitted');
  end if;

  with due as (
    select id, product_id from public.brand_whitelist_exceptions
     where status='active' and expires_at is not null and expires_at <= now())
  update public.brand_whitelist_exceptions w
     set status='expired' from due where w.id = due.id;
  get diagnostics v_n = row_count;

  if v_n > 0 then
    insert into public.brand_protection_events (event, actor_id, new_state, reason, detail)
    values ('whitelist.expired', auth.uid(), 'expired',
            'The exception window closed; protection resumed.',
            jsonb_build_object('expired', v_n));
  end if;

  return jsonb_build_object('ok', true, 'expired', v_n);
end;
$$;


--
-- Name: mm_brand_whitelist_request(uuid, text, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_brand_whitelist_request(p_product uuid, p_rule text, p_reason text, p_expires timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_row jsonb; v_seller uuid;
begin
  if auth.uid() is null then
    return jsonb_build_object('ok', false, 'reason','sign_in_required');
  end if;
  if coalesce(btrim(p_reason),'') = '' then
    return jsonb_build_object('ok', false, 'reason','reason_required',
      'message','An exception to brand protection has to say why it is needed.');
  end if;
  if not exists (select 1 from public.brand_enforcement_rules where key = p_rule) then
    return jsonb_build_object('ok', false, 'reason','unknown_rule');
  end if;

  select seller_id into v_seller from public.marketplace_products where id = p_product;
  if not found then return jsonb_build_object('ok', false, 'reason','unknown_product'); end if;

  -- Only an operator or somebody who acts for the seller may ask.
  if not (public.mm_is_operator() or public.marketplace_is_seller_member(v_seller)) then
    return jsonb_build_object('ok', false, 'reason','not_permitted');
  end if;

  insert into public.brand_whitelist_exceptions
    (product_id, seller_id, rule_key, reason, created_by, expires_at, status)
  values (p_product, v_seller, p_rule, btrim(p_reason), auth.uid(), p_expires, 'pending')
  returning to_jsonb(brand_whitelist_exceptions) into v_row;

  insert into public.brand_protection_events (product_id, event, actor_id, new_state, reason)
  values (p_product, 'whitelist.requested', auth.uid(), 'pending', btrim(p_reason));

  return jsonb_build_object('ok', true, 'exception', v_row,
    'note','Requested only. It has no effect until an authorised approver activates it.');
end;
$$;


--
-- Name: mm_campaign_allowed(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_campaign_allowed(p_from text, p_to text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    AS $$
  select case p_from
    when 'draft'     then p_to in ('review','cancelled','archived')
    when 'review'    then p_to in ('approved','draft','cancelled')
    when 'approved'  then p_to in ('scheduled','running','draft','cancelled')
    when 'scheduled' then p_to in ('running','paused','cancelled','draft')
    when 'running'   then p_to in ('paused','completed','cancelled')
    when 'active'    then p_to in ('paused','completed','cancelled')
    when 'paused'    then p_to in ('running','completed','cancelled')
    when 'completed' then p_to in ('archived')
    when 'cancelled' then p_to in ('archived','draft')
    when 'archived'  then false
    else false
  end;
$$;


--
-- Name: mm_campaign_transition(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_campaign_transition(p_id uuid, p_to text, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare c record; v_before jsonb; v_after jsonb; v_problems text[] := '{}';
begin
  if not public.mm_is_operator() then
    return jsonb_build_object('ok', false, 'reason', 'not_permitted');
  end if;

  select * into c from public.marketing_campaigns where id = p_id;
  if not found then
    return jsonb_build_object('ok', false, 'reason', 'unknown_campaign');
  end if;
  v_before := to_jsonb(c);

  if not public.mm_campaign_allowed(coalesce(c.status,'draft'), p_to) then
    return jsonb_build_object('ok', false, 'reason', 'invalid_transition',
      'message', format('A campaign cannot go from %s to %s.',
                        coalesce(c.status,'draft'), p_to));
  end if;

  -- Going live is the transition that would spend money and contact people, so
  -- it is the one that is validated.
  if p_to in ('running','scheduled') then
    if coalesce(c.is_seed, false) then
      v_problems := v_problems || 'This is demonstration data and cannot be run.'::text;
    end if;
    if coalesce(btrim(c.name), '') = '' then
      v_problems := v_problems || 'The campaign needs a name.'::text;
    end if;
    if coalesce(btrim(c.channel), '') = '' then
      v_problems := v_problems || 'The campaign needs a channel.'::text;
    end if;
    if c.end_date is not null and c.end_date < current_date then
      v_problems := v_problems || 'The campaign window has already closed.'::text;
    end if;
    if coalesce(c.budget, 0) > 0 and coalesce(c.spend, 0) > c.budget then
      v_problems := v_problems || 'Spend already exceeds the budget.'::text;
    end if;
    -- The approval gate. A campaign reaches 'approved' only through review.
    if coalesce(c.status,'draft') not in ('approved','scheduled','paused') then
      v_problems := v_problems || 'The campaign must be approved before it can run.'::text;
    end if;
  end if;

  if array_length(v_problems, 1) > 0 then
    return jsonb_build_object('ok', false, 'reason', 'validation_failed',
                              'problems', to_jsonb(v_problems));
  end if;

  update public.marketing_campaigns set
    status       = p_to,
    submitted_at = case when p_to = 'review'    then coalesce(submitted_at, now()) else submitted_at end,
    approved_at  = case when p_to = 'approved'  then now() else approved_at end,
    approved_by  = case when p_to = 'approved'  then auth.uid() else approved_by end,
    updated_by   = auth.uid(), updated_at = now()
  where id = p_id
  returning to_jsonb(marketing_campaigns) into v_after;

  -- Submitting for review raises a real approval record, which is what the
  -- Approvals screen reads.
  if p_to = 'review' then
    insert into public.marketing_approvals
      (item_type, item_name, requested_by, requested_at, status, priority, is_seed)
    values ('campaign', c.name,
            coalesce((select email from auth.users where id = auth.uid()), 'operator'),
            now(), 'pending', 'normal', false);
  end if;

  if p_to in ('approved','cancelled') then
    update public.marketing_approvals
       set status = case when p_to = 'approved' then 'approved' else 'rejected' end,
           decided_at = now(), decided_by = auth.uid(),
           approver = coalesce((select email from auth.users where id = auth.uid()), 'operator'),
           notes = coalesce(p_reason, notes)
     where item_type = 'campaign' and item_name = c.name and status = 'pending';
  end if;

  perform public.mm_audit('campaign.' || p_to, 'marketing_campaign', p_id::text,
                          v_before, v_after, p_reason);

  return jsonb_build_object('ok', true, 'campaign', v_after);
end;
$$;


--
-- Name: mm_card_coverage(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_card_coverage() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_total integer;
  v_out   jsonb := '[]'::jsonb;
  r       record;
  v_have  integer;
begin
  if not public.mm_is_operator() then
    return jsonb_build_object('ok', false, 'reason', 'not_permitted');
  end if;

  select count(*) into v_total from public.marketplace_products
   where visible and content_status = 'published';

  for r in select * from public.marketplace_card_fields order by kind, position
  loop
    v_have := null;

    if r.requires = 'demo' then
      select count(distinct d.product_id) into v_have
        from public.product_demo_urls d
        join public.marketplace_products p on p.id = d.product_id
       where p.visible and p.content_status = 'published'
         and coalesce(btrim(d.url), '') <> '';

    elsif r.requires = 'reviews' then
      select count(distinct product_id) into v_have from public.marketplace_reviews;

    elsif r.requires = 'views' then
      select count(distinct product_id) into v_have
        from public.marketplace_events where event_type = 'product_view';

    elsif r.requires = 'cart' then
      -- The store exists; what matters is that it is reachable, not how many
      -- rows happen to be in it today.
      select count(*) into v_have from public.marketplace_carts;

    elsif r.requires in ('is_featured','is_trending','is_new_release','is_best_seller','is_ai') then
      execute format(
        'select count(*) from public.marketplace_products
          where visible and content_status = ''published'' and %I', r.requires)
      into v_have;

    elsif r.requires = 'verified' then
      select count(*) into v_have from public.marketplace_products
       where visible and content_status = 'published'
         and moderation_status::text = 'approved';

    elsif r.requires = 'rating' then
      select count(*) into v_have from public.marketplace_products
       where visible and content_status = 'published' and coalesce(rating, 0) > 0;

    elsif r.requires = 'downloads' then
      select count(*) into v_have from public.marketplace_products
       where visible and content_status = 'published' and coalesce(downloads, 0) > 0;

    elsif r.requires = 'updated_at' then
      select count(*) into v_have from public.marketplace_products
       where visible and content_status = 'published' and updated_at is not null;

    elsif r.requires = 'tags' then
      select count(*) into v_have from public.marketplace_products
       where visible and content_status = 'published'
         and tags is not null and array_length(tags, 1) > 0;

    elsif r.requires in ('thumbnail_url','logo','cover_image','description','price_label',
                         'license','version','deployment','content_status','benefits',
                         'badge','mobile','cloud','offline') then
      execute format(
        'select count(*) from public.marketplace_products
          where visible and content_status = ''published''
            and coalesce(btrim(%I::text), '''') <> ''''', r.requires)
      into v_have;
    end if;
    -- Anything else - gallery, video, 3D, brochure, checkout, quick view,
    -- collections, notify, per-platform flags - has no store in this database,
    -- so it stays null and is reported as "no store" rather than as zero.

    v_out := v_out || jsonb_build_object(
      'kind', r.kind, 'key', r.key, 'label', r.label,
      'enabled', r.enabled, 'position', r.position, 'priority', r.priority,
      'hint', r.hint, 'requires', r.requires, 'data_column', r.data_column,
      'have', v_have, 'total', v_total,
      'pct', case when v_have is null or v_total = 0 then null
                  else round(100.0 * v_have / v_total) end);
  end loop;

  return jsonb_build_object('ok', true, 'total_products', v_total, 'fields', v_out);
end;
$$;


--
-- Name: mm_card_field_set(text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_card_field_set(p_key text, p_enabled boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_before jsonb; v_after jsonb;
begin
  if not public.mm_is_operator() then
    return jsonb_build_object('ok', false, 'reason', 'not_permitted');
  end if;

  select to_jsonb(f) into v_before from public.marketplace_card_fields f where f.key = p_key;
  if v_before is null then
    return jsonb_build_object('ok', false, 'reason', 'unknown_field');
  end if;

  update public.marketplace_card_fields
     set enabled = p_enabled, updated_by = auth.uid(), updated_at = now()
   where key = p_key
  returning to_jsonb(marketplace_card_fields) into v_after;

  perform public.mm_audit(
    case when p_enabled then 'card.field.enable' else 'card.field.disable' end,
    'product_card', p_key, v_before, v_after, null);

  return jsonb_build_object('ok', true, 'field', v_after);
end;
$$;


--
-- Name: mm_card_fields(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_card_fields() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select coalesce(jsonb_object_agg(kind, keys), '{}'::jsonb)
    from (
      select kind, jsonb_agg(key order by position) as keys
        from public.marketplace_card_fields
       where enabled
       group by kind
    ) t;
$$;


--
-- Name: mm_card_reorder(text, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_card_reorder(p_kind text, p_keys text[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_before jsonb; v_after jsonb; v_n integer;
begin
  if not public.mm_is_operator() then
    return jsonb_build_object('ok', false, 'reason', 'not_permitted');
  end if;

  select count(*) into v_n from public.marketplace_card_fields where key = any(p_keys);
  if v_n <> coalesce(array_length(p_keys, 1), 0) then
    return jsonb_build_object('ok', false, 'reason', 'unknown_field');
  end if;

  select jsonb_agg(jsonb_build_object('key', key, 'position', position) order by position)
    into v_before from public.marketplace_card_fields where key = any(p_keys);

  update public.marketplace_card_fields f
     set position = array_position(p_keys, f.key),
         -- Badges are drawn in priority order, so the two move together.
         priority = case when f.kind = 'badge'
                         then array_position(p_keys, f.key) * 10 else f.priority end,
         updated_by = auth.uid(), updated_at = now()
   where f.key = any(p_keys);

  select jsonb_agg(jsonb_build_object('key', key, 'position', position) order by position)
    into v_after from public.marketplace_card_fields where key = any(p_keys);

  perform public.mm_audit('card.reorder', 'product_card', p_kind, v_before, v_after, null);
  return jsonb_build_object('ok', true, 'order', v_after);
end;
$$;


--
-- Name: mm_catalog_audit(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_catalog_audit(p_limit integer DEFAULT 25) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_total integer;
begin
  if not public.mm_is_operator() then
    return jsonb_build_object('ok', false, 'reason','not_permitted');
  end if;
  select count(*) into v_total from public.marketplace_products where deleted_at is null;

  return jsonb_build_object(
    'ok', true, 'scanned', v_total, 'read_only', true,
    'findings', jsonb_build_array(
      jsonb_build_object('key','missing_description','severity','high',
        'label','No usable description',
        'count', (select count(*) from public.marketplace_products
                   where deleted_at is null and length(coalesce(btrim(description),'')) < 40),
        'examples', coalesce((select jsonb_agg(jsonb_build_object('id',id,'name',name))
                                from (select id,name from public.marketplace_products
                                       where deleted_at is null
                                         and length(coalesce(btrim(description),'')) < 40
                                       limit p_limit) t), '[]'::jsonb)),
      jsonb_build_object('key','no_category','severity','high',
        'label','No category assigned',
        'count', (select count(*) from public.marketplace_products
                   where deleted_at is null and category_id is null),
        'examples', coalesce((select jsonb_agg(jsonb_build_object('id',id,'name',name))
                                from (select id,name from public.marketplace_products
                                       where deleted_at is null and category_id is null
                                       limit p_limit) t), '[]'::jsonb)),
      jsonb_build_object('key','invalid_category','severity','critical',
        'label','Points at a category that does not exist',
        'count', (select count(*) from public.marketplace_products p
                   where p.deleted_at is null and p.category_id is not null
                     and not exists (select 1 from public.marketplace_categories c where c.id=p.category_id)),
        'examples','[]'::jsonb),
      jsonb_build_object('key','no_license','severity','high',
        'label','No licence stated',
        'count', (select count(*) from public.marketplace_products
                   where deleted_at is null and coalesce(btrim(license),'') = ''),
        'examples','[]'::jsonb),
      jsonb_build_object('key','no_media','severity','medium',
        'label','No thumbnail or cover image',
        'count', (select count(*) from public.marketplace_products
                   where deleted_at is null and coalesce(btrim(thumbnail_url),'')=''
                     and coalesce(btrim(cover_image),'')=''),
        'examples','[]'::jsonb),
      jsonb_build_object('key','no_demo','severity','medium',
        'label','No live demo',
        'count', (select count(*) from public.marketplace_products
                   where deleted_at is null and coalesce(btrim(demo_url),'')=''),
        'examples','[]'::jsonb),
      jsonb_build_object('key','published_unapproved','severity','critical',
        'label','Publicly visible without an approved moderation status',
        'count', (select count(*) from public.marketplace_products
                   where visible and moderation_status <> 'approved'),
        'examples', coalesce((select jsonb_agg(jsonb_build_object('id',id,'name',name,'status',moderation_status))
                                from (select id,name,moderation_status from public.marketplace_products
                                       where visible and moderation_status <> 'approved'
                                       limit p_limit) t), '[]'::jsonb)),
      jsonb_build_object('key','suspended_owner','severity','critical',
        'label','Visible but the owner is not approved',
        'count', (select count(*) from public.marketplace_products p
                   join public.marketplace_sellers s on s.id = p.seller_id
                  where p.visible and s.status <> 'approved'),
        'examples','[]'::jsonb),
      jsonb_build_object('key','legal_block','severity','critical',
        'label','Visible with an unresolved record in Legal Manager',
        'count', (select count(*) from public.marketplace_products p
                  where p.visible and exists (
                    select 1 from public.legal_violations v
                     where v.violator_id = p.id::text
                       and coalesce(v.status,'open') not in ('resolved','dismissed'))),
        'examples','[]'::jsonb),
      jsonb_build_object('key','open_duplicates','severity','medium',
        'label','Duplicate pairs waiting on a decision',
        'count', (select count(*) from public.product_duplicate_candidates where status='open'),
        'examples', coalesce((select jsonb_agg(jsonb_build_object(
                                 'a',(select name from public.marketplace_products where id=d.product_a),
                                 'b',(select name from public.marketplace_products where id=d.product_b),
                                 'match', d.match_percent))
                                from (select * from public.product_duplicate_candidates
                                       where status='open' order by match_percent desc
                                       limit p_limit) d), '[]'::jsonb)),
      jsonb_build_object('key','open_reports','severity','high',
        'label','Reports still open',
        'count', (select count(*) from public.product_reports
                   where status in ('reported','under_review','action_required')),
        'examples','[]'::jsonb),
      jsonb_build_object('key','orphan_merged','severity','medium',
        'label','Merged listings still marked visible',
        'count', (select count(*) from public.marketplace_products
                   where merged_into is not null and visible),
        'examples','[]'::jsonb),
      jsonb_build_object('key','purge_due','severity','medium',
        'label','Soft-deleted past the recovery window',
        'count', (select count(*) from public.marketplace_products
                   where moderation_status='soft_deleted' and purge_after is not null
                     and purge_after <= now()),
        'examples','[]'::jsonb)),
    'note','This audit only reports. It changes nothing, and no product is deleted, published or unpublished by running it.');
end;
$$;


--
-- Name: mm_consent_set(uuid, text, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_consent_set(p_user uuid, p_channel text, p_granted boolean, p_source text DEFAULT 'manager'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_before jsonb; v_after jsonb;
begin
  if not (public.mm_is_operator() or p_user = auth.uid()) then
    return jsonb_build_object('ok', false, 'reason', 'not_permitted');
  end if;
  if not exists (select 1 from auth.users where id = p_user) then
    return jsonb_build_object('ok', false, 'reason', 'unknown_user');
  end if;

  select to_jsonb(c) into v_before from public.marketing_consents c
   where c.user_id = p_user and c.channel = p_channel;

  insert into public.marketing_consents
    (user_id, channel, granted, source, granted_at, revoked_at)
  values (p_user, p_channel, p_granted, p_source,
          case when p_granted then now() end,
          case when not p_granted then now() end)
  on conflict (user_id, channel) do update set
    granted    = excluded.granted,
    source     = excluded.source,
    granted_at = case when excluded.granted then now() else public.marketing_consents.granted_at end,
    revoked_at = case when not excluded.granted then now() else null end,
    updated_at = now()
  returning to_jsonb(marketing_consents) into v_after;

  perform public.mm_audit(
    case when p_granted then 'consent.granted' else 'consent.revoked' end,
    'marketing_consent', p_user::text, v_before, v_after, p_channel);

  return jsonb_build_object('ok', true, 'consent', v_after);
end;
$$;


--
-- Name: mm_customer_profile(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_customer_profile(p_user uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_user record;
begin
  if not public.mm_is_operator() then
    return jsonb_build_object('ok', false, 'reason', 'not_permitted');
  end if;

  select u.id, u.email, u.created_at, u.last_sign_in_at, p.full_name, p.phone
    into v_user
    from auth.users u left join public.profiles p on p.id = u.id
   where u.id = p_user;

  if v_user.id is null then
    return jsonb_build_object('ok', false, 'reason', 'unknown_customer');
  end if;

  -- Reading a customer record is itself a sensitive act and is recorded.
  perform public.mm_audit('customer.viewed', 'marketplace_customer', p_user::text,
                          null, jsonb_build_object('email', v_user.email), null);

  return jsonb_build_object(
    'ok', true,
    'customer', jsonb_build_object(
      'id', v_user.id, 'email', v_user.email, 'full_name', v_user.full_name,
      'phone', v_user.phone, 'registered_at', v_user.created_at,
      'last_sign_in_at', v_user.last_sign_in_at),
    'orders', coalesce((
      select jsonb_agg(jsonb_build_object(
               'id', o.id, 'order_number', o.order_number, 'status', o.status,
               'total', o.total, 'currency', o.currency, 'created_at', o.created_at)
             order by o.created_at desc)
        from public.marketplace_orders o where o.buyer_id = p_user), '[]'::jsonb),
    'licences', coalesce((
      select jsonb_agg(jsonb_build_object(
               'license_key', l.license_key, 'model', l.license_model,
               'status', l.status, 'product', pr.name, 'created_at', l.created_at)
             order by l.created_at desc)
        from public.marketplace_licenses l
        left join public.marketplace_products pr on pr.id = l.product_id
       where l.buyer_id = p_user), '[]'::jsonb),
    'entitlements', coalesce((
      select jsonb_agg(jsonb_build_object(
               'product', pr.name, 'status', e.status, 'starts_at', e.starts_at)
             order by e.created_at desc)
        from public.marketplace_entitlements e
        left join public.marketplace_products pr on pr.id = e.product_id
       where e.buyer_id = p_user), '[]'::jsonb),
    'lifetime_value', (select coalesce(sum(total),0) from public.marketplace_orders
                        where buyer_id = p_user and status::text='paid'));
end;
$$;


--
-- Name: mm_customers(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_customers(p_query jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_search text := nullif(btrim(coalesce(p_query->>'search','')), '');
  v_filter text := coalesce(p_query->>'filter', 'all');
  v_limit  integer := least(greatest(coalesce((p_query->>'limit')::int, 25), 1), 100);
  v_offset integer := greatest(coalesce((p_query->>'offset')::int, 0), 0);
  v_rows   jsonb;
  v_total  integer;
begin
  if not public.mm_is_operator() then
    return jsonb_build_object('ok', false, 'reason', 'not_permitted');
  end if;

  with base as (
    select u.id,
           u.email,
           p.full_name,
           p.phone,
           u.created_at as registered_at,
           u.last_sign_in_at,
           (select count(*) from public.marketplace_orders o where o.buyer_id = u.id) as orders,
           (select count(*) from public.marketplace_orders o
             where o.buyer_id = u.id and o.status::text = 'paid') as paid_orders,
           coalesce((select sum(o.total) from public.marketplace_orders o
                      where o.buyer_id = u.id and o.status::text = 'paid'), 0) as lifetime_value,
           (select count(*) from public.marketplace_licenses l where l.buyer_id = u.id) as licences,
           (select count(*) from public.marketplace_entitlements e where e.buyer_id = u.id) as entitlements,
           (select max(o.created_at) from public.marketplace_orders o where o.buyer_id = u.id) as last_order_at
      from auth.users u
      left join public.profiles p on p.id = u.id
  ),
  -- A customer is someone who has bought. Everyone else is a registered
  -- account, and the two are counted separately rather than blended.
  typed as (
    select b.*,
           case when b.paid_orders > 0 then 'customer' else 'registered' end as customer_type,
           -- VIP is earned, not stored: more than one paid order, or lifetime
           -- value above the standard single-product price. There is no VIP
           -- column in this database and inventing one would be a second
           -- source of truth.
           (b.paid_orders > 1 or b.lifetime_value > 249) as vip
      from base b
  ),
  filtered as (
    select * from typed t
     where (v_search is null
            or t.email ilike '%' || v_search || '%'
            or coalesce(t.full_name,'') ilike '%' || v_search || '%'
            or coalesce(t.phone,'') ilike '%' || v_search || '%'
            or t.id::text = v_search)
       and (v_filter = 'all'
            or (v_filter = 'customers'  and t.customer_type = 'customer')
            or (v_filter = 'registered' and t.customer_type = 'registered')
            or (v_filter = 'vip'        and t.vip))
  )
  select count(*) into v_total from filtered;

  with base as (
    select u.id, u.email, p.full_name, p.phone, u.created_at as registered_at,
           u.last_sign_in_at,
           (select count(*) from public.marketplace_orders o where o.buyer_id = u.id) as orders,
           (select count(*) from public.marketplace_orders o
             where o.buyer_id = u.id and o.status::text = 'paid') as paid_orders,
           coalesce((select sum(o.total) from public.marketplace_orders o
                      where o.buyer_id = u.id and o.status::text = 'paid'), 0) as lifetime_value,
           (select count(*) from public.marketplace_licenses l where l.buyer_id = u.id) as licences,
           (select count(*) from public.marketplace_entitlements e where e.buyer_id = u.id) as entitlements,
           (select max(o.created_at) from public.marketplace_orders o where o.buyer_id = u.id) as last_order_at
      from auth.users u
      left join public.profiles p on p.id = u.id
  ),
  typed as (
    select b.*, case when b.paid_orders > 0 then 'customer' else 'registered' end as customer_type,
           (b.paid_orders > 1 or b.lifetime_value > 249) as vip
      from base b
  ),
  filtered as (
    select * from typed t
     where (v_search is null
            or t.email ilike '%' || v_search || '%'
            or coalesce(t.full_name,'') ilike '%' || v_search || '%'
            or coalesce(t.phone,'') ilike '%' || v_search || '%'
            or t.id::text = v_search)
       and (v_filter = 'all'
            or (v_filter = 'customers'  and t.customer_type = 'customer')
            or (v_filter = 'registered' and t.customer_type = 'registered')
            or (v_filter = 'vip'        and t.vip))
  )
  select coalesce(jsonb_agg(to_jsonb(f) order by f.lifetime_value desc, f.registered_at desc), '[]'::jsonb)
    into v_rows
    from (select * from filtered order by lifetime_value desc, registered_at desc
           limit v_limit offset v_offset) f;

  return jsonb_build_object(
    'ok', true, 'total', v_total, 'limit', v_limit, 'offset', v_offset,
    'customers', v_rows);
end;
$$;


--
-- Name: mm_customers_overview(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_customers_overview() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if not public.mm_is_operator() then
    return jsonb_build_object('ok', false, 'reason', 'not_permitted');
  end if;

  return jsonb_build_object(
    'ok', true,
    'accounts',        (select count(*) from auth.users),
    'customers',       (select count(distinct buyer_id) from public.marketplace_orders
                         where buyer_id is not null and status::text = 'paid'),
    'with_any_order',  (select count(distinct buyer_id) from public.marketplace_orders
                         where buyer_id is not null),
    'vip',             (select count(*) from (
                          select o.buyer_id,
                                 count(*) filter (where o.status::text='paid') pd,
                                 coalesce(sum(o.total) filter (where o.status::text='paid'),0) lv
                            from public.marketplace_orders o
                           where o.buyer_id is not null group by o.buyer_id) t
                         where t.pd > 1 or t.lv > 249),
    'orders',          (select count(*) from public.marketplace_orders),
    'paid_orders',     (select count(*) from public.marketplace_orders where status::text='paid'),
    'licences',        (select count(*) from public.marketplace_licenses),
    'entitlements',    (select count(*) from public.marketplace_entitlements),
    'lifetime_value',  (select coalesce(sum(total),0) from public.marketplace_orders
                         where status::text='paid'),
    'signed_in_30d',   (select count(*) from auth.users
                         where last_sign_in_at > now() - interval '30 days'),
    -- Everything below is unavailable, and says why instead of showing a zero
    -- that would read as "no tickets" rather than "not connected".
    'unavailable', jsonb_build_object(
      'support_tickets', 'support_tickets.customer_id matches no auth.users id — those 11 tickets belong to another customer system',
      'subscriptions',   'finance_subscriptions has no user column, only customer_name, so it cannot be attributed to an account',
      'activity',        'activity_logs is empty — there is no timeline data yet',
      'wishlist',        'no wishlist table exists in this database',
      'reviews',         'marketplace_reviews holds no rows',
      'downloads',       'marketplace_downloads holds no rows and no product files are stored'));
end;
$$;


--
-- Name: mm_dashboard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_dashboard() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_products    jsonb;
  v_commerce    jsonb;
  v_revenue     jsonb;
  v_queues      jsonb;
  v_activity    jsonb;
  v_has_downloads boolean;
begin
  if not public.mm_is_operator() then
    return jsonb_build_object('ok', false, 'reason', 'not_permitted');
  end if;

  select exists (
    select 1 from information_schema.tables
    where table_schema='public' and table_name='downloads'
  ) into v_has_downloads;

  -- ---- Catalogue -----------------------------------------------------------
  select jsonb_build_object(
    'total',      count(*),
    'published',  count(*) filter (where visible and content_status='published'),
    'draft',      count(*) filter (where content_status='draft'),
    'archived',   count(*) filter (where content_status='archived'),
    'hidden',     count(*) filter (where not visible),
    'with_demo',  count(*) filter (where coalesce(demo_url,'') <> ''),
    'with_image', count(*) filter (where coalesce(thumbnail_url,'') <> ''),
    'sellers',    count(distinct seller_id) filter (where seller_id is not null),
    'categories', (select count(*) from public.marketplace_categories)
  ) into v_products
  from public.marketplace_products;

  -- ---- Orders --------------------------------------------------------------
  select jsonb_build_object(
    'orders',        count(*),
    'paid',          count(*) filter (where status::text = 'paid'),
    'pending',       count(*) filter (where status::text <> 'paid'),
    'refunds',       (select count(*) from public.marketplace_order_refunds),
    -- Nothing has ever been downloaded here because the table does not exist;
    -- null says that, 0 would imply it was measured.
    'downloads',     case when v_has_downloads
                          then (select count(*) from public.marketplace_orders) else null end
  ) into v_commerce
  from public.marketplace_orders;

  -- ---- Revenue, reconciled against the order lines -------------------------
  select jsonb_build_object(
    'today',      coalesce(sum(oi.line_total) filter (where o.created_at >= date_trunc('day', now())), 0),
    'this_week',  coalesce(sum(oi.line_total) filter (where o.created_at >= date_trunc('week', now())), 0),
    'this_month', coalesce(sum(oi.line_total) filter (where o.created_at >= date_trunc('month', now())), 0),
    'this_year',  coalesce(sum(oi.line_total) filter (where o.created_at >= date_trunc('year', now())), 0),
    'all_time',   coalesce(sum(oi.line_total), 0),
    'refunded',   coalesce((select sum(amount) from public.marketplace_order_refunds), 0),
    'net',        coalesce(sum(oi.line_total), 0)
                  - coalesce((select sum(amount) from public.marketplace_order_refunds), 0),
    'currency',   coalesce(max(o.currency::text), 'INR'),
    -- The dashboard must be able to say "no transactions yet" rather than 0.
    'has_transactions', count(*) > 0
  ) into v_revenue
  from public.marketplace_orders o
  join public.marketplace_order_items oi on oi.order_id = o.id
  where o.status::text = 'paid';

  -- ---- Approval queues — section 13 ---------------------------------------
  -- Each queue names the destination that actually lists those records, so a
  -- card can open the exact set it counted.
  select jsonb_agg(q) into v_queues from (
    select jsonb_build_object(
      'key', 'pending_products', 'label', 'Pending Products',
      'count', (select count(*) from public.marketplace_products
                 where moderation_status::text in ('pending','pending_review','in_review','submitted')),
      'destination', '/marketplace-manager?section=catalog&moderation=pending') q
    union all
    select jsonb_build_object(
      'key', 'unpublished_products', 'label', 'Draft & Unpublished',
      'count', (select count(*) from public.marketplace_products
                 where content_status='draft' or not visible),
      'destination', '/marketplace-manager?section=catalog&status=draft')
    union all
    select jsonb_build_object(
      'key', 'products_without_demo', 'label', 'Products Without a Demo',
      'count', (select count(*) from public.marketplace_products
                 where visible and content_status='published' and coalesce(demo_url,'')=''),
      'destination', '/marketplace-manager?section=demo-urls')
    union all
    select jsonb_build_object(
      'key', 'products_without_image', 'label', 'Products Without an Image',
      'count', (select count(*) from public.marketplace_products
                 where visible and content_status='published' and coalesce(thumbnail_url,'')=''),
      'destination', '/marketplace-manager?section=catalog&missing=image')
    union all
    select jsonb_build_object(
      'key', 'pending_orders', 'label', 'Orders Awaiting Payment',
      'count', (select count(*) from public.marketplace_orders where status::text <> 'paid'),
      'destination', '/marketplace-manager?section=commerce&status=pending')
    union all
    select jsonb_build_object(
      'key', 'draft_rows', 'label', 'Homepage Rows Not Published',
      'count', (select count(*) from public.marketplace_row_config
                 where status <> 'published'),
      'destination', '/marketplace-manager?section=homepage-rows')
  ) qs;

  -- ---- Activity — section 15 ----------------------------------------------
  -- Real events and real audit entries, merged newest first. No placeholder
  -- "connecting to live stream" state: if there is nothing, the list is empty
  -- and the UI says so.
  select coalesce(jsonb_agg(a order by a->>'at' desc), '[]'::jsonb) into v_activity
  from (
    select jsonb_build_object(
      'at', e.created_at, 'kind', e.event_type::text, 'source', 'marketplace_events',
      'label', coalesce(p.name, 'a product'),
      'detail', coalesce(e.source_page, '')) a
    from public.marketplace_events e
    left join public.marketplace_products p on p.id = e.product_id
    order by e.created_at desc limit 15
  ) x;

  select v_activity || coalesce((
    select jsonb_agg(jsonb_build_object(
      'at', l.created_at, 'kind', l.action, 'source', 'audit',
      'label', coalesce(l.actor, 'system'),
      'detail', coalesce(l.reason, '')))
    from (select * from public.marketplace_audit_logs
          order by created_at desc limit 15) l
  ), '[]'::jsonb) into v_activity;

  return jsonb_build_object(
    'ok', true,
    'generated_at', now(),
    'products', v_products,
    'commerce', v_commerce,
    'revenue', v_revenue,
    'queues', coalesce(v_queues, '[]'::jsonb),
    'activity', v_activity,
    -- Reused wholesale. These already exist and are already correct; building
    -- a second version of them would be exactly the duplication rule 3 forbids.
    'score', public.mm_marketplace_score(),
    'attention', public.mm_attention_center(),
    'health', (select coalesce(jsonb_agg(to_jsonb(h)), '[]'::jsonb)
               from public.mm_health_checks() h)
  );
end $$;


--
-- Name: mm_demo_domains(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_demo_domains(p_query jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_tab text := coalesce(p_query->>'tab','all');
  v_search text := nullif(btrim(coalesce(p_query->>'search','')),'');
  v_limit integer := least(greatest(coalesce((p_query->>'limit')::int,50),1),200);
  v_offset integer := greatest(coalesce((p_query->>'offset')::int,0),0);
  v_s record; v_prov jsonb;
begin
  if not public.mm_is_operator() then
    return jsonb_build_object('ok', false, 'reason','not_permitted');
  end if;
  select * into v_s from public.demo_access_settings where id;
  v_prov := public.mm_demo_provider_status();

  return jsonb_build_object(
    'ok', true, 'tab', v_tab,
    'settings', to_jsonb(v_s),
    'providers', v_prov,

    'counts', jsonb_build_object(
      'total',      (select count(*) from public.demo_domains),
      'live',       (select count(*) from public.demo_domains where status='live'),
      'provisioning',(select count(*) from public.demo_domains
                       where status in ('provisioning','dns_pending','ssl_pending','deploying','health_check')),
      'resetting',  (select count(*) from public.demo_domains where status='resetting'),
      'disabled',   (select count(*) from public.demo_domains where status='disabled'),
      'expired',    (select count(*) from public.demo_domains where status='expired'),
      'failed',     (select count(*) from public.demo_domains where status='failed')),

    -- The demos this marketplace actually has today, and where they live. All
    -- thirteen are hosted by a third party, which is a different thing from a
    -- provisioned Software Vala demo.
    'external_demos', jsonb_build_object(
      'count', (select count(*) from public.product_demo_urls where status='active'),
      'hosts', coalesce((select jsonb_object_agg(host, n) from (
                 select split_part(split_part(url,'//',2),'/',1) host, count(*) n
                   from public.product_demo_urls where status='active'
                  group by 1 order by 2 desc limit 10) t), '{}'::jsonb),
      'note','These are the live demos the marketplace links to today. They are hosted elsewhere, not provisioned on Software Vala infrastructure, and this module does not control their DNS, certificates or branding.'),

    -- Health comes from the monitor that already runs every fifteen minutes.
    'health', jsonb_build_object(
      'checks_recorded', (select count(*) from public.demo_health),
      'last_check', (select max(checked_at) from public.demo_health),
      'working', (select count(*) from public.product_demo_urls where last_result='working'),
      'slow', (select count(*) from public.product_demo_urls where last_result='slow'),
      'offline', (select count(*) from public.product_demo_urls where last_result='offline'),
      'unknown', (select count(*) from public.product_demo_urls
                   where last_result is null or last_result='unknown')),

    -- Server Manager is the infrastructure source of truth; this reads it.
    'infrastructure', jsonb_build_object(
      'server_instances', (select count(*) from public.server_instances),
      'regions', (select count(*) from public.server_regions),
      'deployments', (select count(*) from public.server_deployments),
      'note','Read from Server Manager. This module keeps no server inventory of its own.'),

    'total', (select count(*) from public.demo_domains d
               where case v_tab
                 when 'live' then d.status='live'
                 when 'resetting' then d.status='resetting'
                 when 'disabled' then d.status='disabled'
                 when 'expired' then d.status='expired'
                 else true end),

    'demos', coalesce((
      select jsonb_agg(jsonb_build_object(
               'id', d.id, 'demo_ref', d.demo_ref,
               'product_id', d.product_id,
               'product', (select name from public.marketplace_products where id=d.product_id),
               'owner', (select s.display_name from public.marketplace_products p
                          join public.marketplace_sellers s on s.id=p.seller_id
                         where p.id=d.product_id),
               'slug', d.slug, 'hostname', d.hostname,
               'url', 'https://' || d.hostname,
               'status', d.status, 'failure_reason', d.failure_reason,
               'dns_status', d.dns_status, 'ssl_status', d.ssl_status,
               'ssl_expires_at', d.ssl_expires_at,
               'health', d.health, 'last_health_at', d.last_health_at,
               'password_protected', d.password_protected,
               'allow_indexing', d.allow_indexing,
               'expires_at', d.expires_at, 'grace_until', d.grace_until,
               'days_remaining', case when d.expires_at is null then null
                                      else greatest(0, extract(day from d.expires_at - now())::int) end,
               'created_at', d.created_at, 'updated_at', d.updated_at,
               'qr', (select jsonb_build_object('target', q.target_url,
                        'scan_count', q.scan_count,
                        'analytics','not tracked')
                        from public.demo_qr_codes q
                       where q.demo_id = d.id and q.active limit 1),
               'jobs', (select count(*) from public.demo_provision_jobs j where j.demo_id = d.id),
               'last_job', (select jsonb_build_object('operation', j.operation,
                              'status', j.status, 'error', j.error_detail)
                              from public.demo_provision_jobs j
                             where j.demo_id = d.id order by j.created_at desc limit 1))
             order by d.updated_at desc)
        from (select * from public.demo_domains d2
               where case v_tab
                 when 'live' then d2.status='live'
                 when 'resetting' then d2.status='resetting'
                 when 'disabled' then d2.status='disabled'
                 when 'expired' then d2.status='expired'
                 else true end
                 and (v_search is null
                      or d2.hostname ilike '%'||v_search||'%'
                      or d2.slug ilike '%'||v_search||'%'
                      or d2.demo_ref ilike '%'||v_search||'%')
               order by d2.updated_at desc limit v_limit offset v_offset) d), '[]'::jsonb),

    'events', coalesce((select jsonb_agg(jsonb_build_object(
                 'event', e.event, 'at', e.created_at, 'reason', e.reason,
                 'from', e.previous_state, 'to', e.new_state)
               order by e.created_at desc)
                 from (select * from public.demo_domain_events
                        order by created_at desc limit 25) e), '[]'::jsonb));
end;
$$;


--
-- Name: mm_demo_eligibility(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_demo_eligibility(p_product uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_p record; v_gates jsonb; v_blocked integer; v_brand integer;
begin
  select * into v_p from public.marketplace_products where id = p_product;
  if not found then
    return jsonb_build_object('ok', false, 'reason','unknown_product');
  end if;

  select count(*) into v_blocked from public.security_assets
   where product_id = p_product and status in ('blocked','quarantined');

  select count(*) into v_brand from public.brand_violation_cases
   where product_id = p_product and status in ('open','escalated','failed');

  v_gates := jsonb_build_array(
    jsonb_build_object('key','moderation','label','Product Moderation',
      'passed', v_p.moderation_status = 'approved' and v_p.visible,
      'detail', format('moderation_status is %s, visible is %s',
                       v_p.moderation_status, v_p.visible),
      'owner','Product Moderation Center'),
    jsonb_build_object('key','not_deleted','label','Not deleted or merged',
      'passed', v_p.deleted_at is null and v_p.merged_into is null,
      'detail', case when v_p.deleted_at is not null then 'this listing is deleted'
                     when v_p.merged_into is not null then 'this listing was merged into another'
                     else 'standalone and present' end,
      'owner','Product Moderation Center'),
    jsonb_build_object('key','security','label','No blocked or quarantined asset',
      'passed', v_blocked = 0,
      'detail', format('%s asset(s) blocked or quarantined', v_blocked),
      'owner','Upload Security Scanner'),
    jsonb_build_object('key','branding','label','No open branding violation',
      'passed', v_brand = 0,
      'detail', format('%s open branding case(s)', v_brand),
      'owner','Favicon & Branding Protection'),
    jsonb_build_object('key','legal','label','No unresolved legal record',
      'passed', not exists (select 1 from public.legal_violations v
                             where v.violator_id = p_product::text
                               and coalesce(v.status,'open') not in ('resolved','dismissed')),
      'detail','read from Legal Manager', 'owner','Legal Manager'));

  return jsonb_build_object(
    'ok', true, 'product_id', p_product,
    'gates', v_gates,
    'eligible', not exists (select 1 from jsonb_array_elements(v_gates) g
                             where not (g->>'passed')::boolean),
    'blocked_by', coalesce((select jsonb_agg(g->>'key') from jsonb_array_elements(v_gates) g
                             where not (g->>'passed')::boolean), '[]'::jsonb));
end;
$$;


--
-- Name: mm_demo_expiry_run(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_demo_expiry_run() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_s record; d integer; r record;
  v_reminded integer := 0; v_grace integer := 0; v_expired integer := 0;
begin
  if not public.mm_is_operator() then
    return jsonb_build_object('ok', false, 'reason','not_permitted');
  end if;
  select * into v_s from public.demo_access_settings where id;

  -- Reminders, at each configured threshold.
  foreach d in array v_s.reminder_days loop
    for r in
      select * from public.demo_domains
       where status in ('live','disabled')
         and expires_at is not null
         and expires_at between now() and now() + (d || ' days')::interval
         and not exists (select 1 from public.demo_expiry_events e
                          where e.demo_id = demo_domains.id
                            and e.kind='reminder' and e.days_out = d)
    loop
      insert into public.demo_expiry_events (demo_id, kind, days_out, notified)
      values (r.id, 'reminder', d, true) on conflict do nothing;
      v_reminded := v_reminded + 1;

      perform public.mm_notify('demo.expiring',
        format('%s expires in %s day(s)', r.hostname, d),
        format('The demo for this product expires on %s. Renew it or it will be disabled.',
               to_char(r.expires_at, 'DD Mon YYYY')),
        null, array['admin','boss'], '/marketplace-manager', 'Open',
        60 * 24, case when d <= 3 then 'warning' else 'info' end);
    end loop;
  end loop;

  -- Past expiry but inside grace: recorded, still reachable.
  for r in
    select * from public.demo_domains
     where status = 'live' and expires_at is not null and expires_at <= now()
       and (grace_until is null or grace_until > now())
  loop
    insert into public.demo_expiry_events (demo_id, kind, days_out)
    values (r.id, 'grace_started', 0) on conflict do nothing;
    v_grace := v_grace + 1;
  end loop;

  -- Past grace: disabled, never deleted.
  for r in
    select * from public.demo_domains
     where status in ('live','disabled')
       and expires_at is not null and expires_at <= now()
       and grace_until is not null and grace_until <= now()
       and status <> 'expired'
  loop
    update public.demo_domains
       set status='expired', updated_at=now() where id = r.id;
    insert into public.demo_expiry_events (demo_id, kind, days_out)
    values (r.id, 'expired', 0) on conflict do nothing;
    insert into public.demo_domain_events
      (demo_id, product_id, event, actor_id, previous_state, new_state, reason)
    values (r.id, r.product_id, 'demo.expired', auth.uid(), r.status, 'expired',
            'The grace period ended. The demo was disabled; nothing was deleted.');
    v_expired := v_expired + 1;
  end loop;

  return jsonb_build_object('ok', true,
    'thresholds', to_jsonb(v_s.reminder_days),
    'reminded', v_reminded, 'entered_grace', v_grace, 'expired', v_expired,
    'note','An expired demo is disabled and kept. Its DNS record, certificate and deployment history are preserved for an authorised renewal.');
end;
$$;


--
-- Name: mm_demo_operation(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_demo_operation(p_demo uuid, p_op text, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_d record; v_after jsonb; v_prov jsonb; v_allowed boolean;
  v_job uuid; v_key text; v_owner uuid; v_to text;
begin
  if not public.mm_is_operator() then
    return jsonb_build_object('ok', false, 'reason','not_permitted');
  end if;
  if p_op not in ('enable','disable','reset','regenerate','renew','destroy') then
    return jsonb_build_object('ok', false, 'reason','unknown_operation');
  end if;

  select * into v_d from public.demo_domains where id = p_demo for update;
  if not found then return jsonb_build_object('ok', false, 'reason','unknown_demo'); end if;
  v_prov := public.mm_demo_provider_status();

  if p_op in ('disable','reset','regenerate','destroy')
     and coalesce(btrim(p_reason),'') = '' then
    return jsonb_build_object('ok', false, 'reason','reason_required',
      'message','This changes live infrastructure. Say why; it is recorded permanently.');
  end if;

  -- 11. Disabling never destroys DNS or the deployment.
  v_allowed := case p_op
    when 'disable'    then v_d.status not in ('disabled')
    when 'enable'     then v_d.status in ('disabled','expired')
    when 'reset'      then v_d.status in ('live','disabled','degraded')
    -- A prepared draft is the commonest thing to regenerate: it is the retry
    -- after provisioning could not start.
    when 'regenerate' then v_d.status in ('draft','live','disabled','failed','expired')
    when 'renew'      then v_d.status in ('live','disabled','expired')
    when 'destroy'    then true
    else false end;
  if not v_allowed then
    return jsonb_build_object('ok', false, 'reason','invalid_operation',
      'message', format('A %s demo cannot be %sd.', v_d.status, p_op));
  end if;

  -- Enable, reset and regenerate all need infrastructure. Without a provider
  -- they are refused rather than reported as done.
  if p_op in ('enable','reset','regenerate') and not (v_prov->>'can_provision')::boolean then
    v_key := 'demo_'||p_op||':'||p_demo::text||':'||extract(epoch from now())::bigint::text;
    insert into public.demo_provision_jobs
      (demo_id, operation, status, idempotency_key, actor_id, started_at, finished_at,
       error_category, error_detail)
    values (p_demo, case p_op when 'enable' then 'enable' when 'reset' then 'reset'
                              else 'regenerate' end,
            'blocked', v_key, auth.uid(), now(), now(), 'provider_not_configured',
            'DNS, SSL and a deployment runtime must all authenticate first.');

    insert into public.demo_domain_events
      (demo_id, job_id, product_id, event, actor_id, reason, detail)
    values (p_demo, null, v_d.product_id, 'operation.blocked', auth.uid(),
            format('%s was refused: no provider is configured.', p_op), v_prov);

    return jsonb_build_object('ok', false, 'reason','provider_not_configured',
      'message', format('%s needs DNS, SSL and a deployment runtime. None of them authenticates, so nothing was changed.', initcap(p_op)),
      'providers', v_prov);
  end if;

  v_to := case p_op
    when 'disable' then 'disabled'
    when 'enable' then 'health_check'
    when 'reset' then 'resetting'
    when 'regenerate' then 'provisioning'
    when 'renew' then v_d.status
    when 'destroy' then 'disabled'
    else v_d.status end;

  update public.demo_domains
     set status = v_to,
         -- 16. Renewing pushes the dates out from the settings, never silently.
         expires_at = case when p_op='renew'
                           then now() + ((select default_ttl_days from public.demo_access_settings where id) || ' days')::interval
                           else expires_at end,
         grace_until = case when p_op='renew'
                            then now() + (((select default_ttl_days from public.demo_access_settings where id)
                                         + (select grace_days from public.demo_access_settings where id)) || ' days')::interval
                            else grace_until end,
         failure_reason = case when p_op in ('enable','reset','regenerate') then null
                               else failure_reason end,
         updated_at = now()
   where id = p_demo returning to_jsonb(demo_domains) into v_after;

  if p_op = 'renew' then
    insert into public.demo_expiry_events (demo_id, kind, days_out)
    values (p_demo, 'renewed', null) on conflict do nothing;
  end if;

  insert into public.demo_domain_events
    (demo_id, product_id, event, actor_id, previous_state, new_state, reason)
  values (p_demo, v_d.product_id, 'demo.'||p_op, auth.uid(), v_d.status, v_to, p_reason);

  perform public.mm_audit('demo.'||p_op,'demo_domain', p_demo::text,
                          to_jsonb(v_d), v_after, p_reason);

  select s.owner_user_id into v_owner
    from public.marketplace_products p
    join public.marketplace_sellers s on s.id = p.seller_id
   where p.id = v_d.product_id;
  if v_owner is not null and p_op in ('disable','destroy') then
    perform public.mm_notify('demo.'||p_op,
      format('Your demo at %s was %sd', v_d.hostname, p_op),
      coalesce(p_reason,''), v_owner, null, '/author-manager', 'Open', 5, 'warning');
  end if;

  return jsonb_build_object('ok', true, 'demo', v_after,
    'note', case when p_op='disable'
      then 'The demo is unavailable. DNS, the certificate and the deployment were left in place, so enabling it again does not rebuild anything.'
      else null end);
end;
$$;


--
-- Name: mm_demo_password_set(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_demo_password_set(p_demo uuid, p_password text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp', 'extensions'
    AS $$
declare v_d record;
begin
  if not public.mm_is_operator() then
    return jsonb_build_object('ok', false, 'reason','not_permitted');
  end if;
  select * into v_d from public.demo_domains where id = p_demo;
  if not found then return jsonb_build_object('ok', false, 'reason','unknown_demo'); end if;

  if p_password is null or btrim(p_password) = '' then
    update public.demo_domains
       set password_hash = null, password_set_at = null,
           password_protected = false, updated_at = now()
     where id = p_demo;
    insert into public.demo_domain_events (demo_id, product_id, event, actor_id, new_state, reason)
    values (p_demo, v_d.product_id, 'demo.password_cleared', auth.uid(), 'open',
            'Password protection removed.');
    return jsonb_build_object('ok', true, 'password_protected', false);
  end if;

  if length(p_password) < 8 then
    return jsonb_build_object('ok', false, 'reason','password_too_short',
      'message','A demo password needs at least eight characters.');
  end if;

  update public.demo_domains
     set password_hash = crypt(p_password, gen_salt('bf', 10)),
         password_set_at = now(), password_protected = true, updated_at = now()
   where id = p_demo;

  insert into public.demo_domain_events (demo_id, product_id, event, actor_id, new_state, reason)
  values (p_demo, v_d.product_id, 'demo.password_set', auth.uid(), 'protected',
          'Password set. Only the hash is stored.');

  perform public.mm_audit('demo.password_set','demo_domain', p_demo::text, null,
                          jsonb_build_object('password_protected', true), null);

  -- The plaintext is deliberately not returned. Whoever set it already has it.
  return jsonb_build_object('ok', true, 'password_protected', true,
    'note','Only a bcrypt hash is stored. The password itself is not kept and is not returned here.');
end;
$$;


--
-- Name: mm_demo_provider_status(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_demo_provider_status() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_dns integer; v_ssl integer; v_dep integer;
begin
  select count(*) into v_dns from public.demo_provider_configs
   where kind='dns' and enabled and verified;
  select count(*) into v_ssl from public.demo_provider_configs
   where kind='ssl' and enabled and verified;
  select count(*) into v_dep from public.demo_provider_configs
   where kind='deployment' and enabled and verified;

  return jsonb_build_object(
    'dns', case when v_dns > 0 then 'CONNECTED' else 'REQUIRES_CONFIGURATION' end,
    'ssl', case when v_ssl > 0 then 'CONNECTED' else 'REQUIRES_CONFIGURATION' end,
    'deployment', case when v_dep > 0 then 'CONNECTED' else 'DEPLOYMENT_PROVIDER_NOT_CONFIGURED' end,
    'can_provision', v_dns > 0 and v_ssl > 0 and v_dep > 0,
    'providers', coalesce((select jsonb_agg(jsonb_build_object(
                   'slug', slug, 'label', label, 'kind', kind,
                   'enabled', enabled, 'verified', verified,
                   'credential_env', credential_env, 'last_error', last_error,
                   'state', case when enabled and verified then 'CONNECTED'
                                 when enabled then 'REQUIRES_CONFIGURATION'
                                 else 'NOT_CONFIGURED' end)
                 order by kind, slug) from public.demo_provider_configs), '[]'::jsonb),
    'note', case when v_dns > 0 and v_ssl > 0 and v_dep > 0 then null
      else 'No demo can be provisioned until DNS, SSL and a deployment runtime all authenticate. '
        || 'A demo record can be prepared and its hostname reserved, but it cannot reach LIVE.' end);
end;
$$;


--
-- Name: mm_demo_provision(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_demo_provision(p_product uuid, p_pattern text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_s record; v_slug jsonb; v_elig jsonb; v_prov jsonb;
  v_host text; v_ref text; v_demo jsonb; v_job uuid; v_key text; v_existing record;
begin
  if not public.mm_is_operator() then
    return jsonb_build_object('ok', false, 'reason','not_permitted');
  end if;
  select * into v_s from public.demo_access_settings where id;
  v_prov := public.mm_demo_provider_status();

  -- 22. Publication eligibility first. Nothing is reserved for a product that
  -- may not have a demo.
  v_elig := public.mm_demo_eligibility(p_product);
  if not (v_elig->>'ok')::boolean then return v_elig; end if;
  if not (v_elig->>'eligible')::boolean then
    return jsonb_build_object('ok', false, 'reason','not_eligible',
      'message','This product cannot have a demo yet.',
      'blocked_by', v_elig->'blocked_by', 'gates', v_elig->'gates');
  end if;

  -- 29. One active demo per product; asking twice does not build two.
  select * into v_existing from public.demo_domains
   where product_id = p_product and status <> 'expired';
  if found then
    return jsonb_build_object('ok', false, 'reason','already_provisioned',
      'message', format('This product already has a demo at %s (%s).',
                        v_existing.hostname, v_existing.status),
      'demo_id', v_existing.id);
  end if;

  v_slug := public.mm_demo_slug(p_product);
  if not (v_slug->>'ok')::boolean then return v_slug; end if;

  v_host := case coalesce(p_pattern, v_s.default_pattern)
              when 'shared' then v_s.base_domain
              else (v_slug->>'slug') || '.' || v_s.base_domain end;
  -- Unique per demo, not per product-and-transaction. Deriving it from
  -- md5(product || now()) collided when a failed demo was provisioned again,
  -- because now() is the transaction timestamp and does not move.
  v_ref := 'DEMO-' || upper(substr(replace(gen_random_uuid()::text,'-',''), 1, 10));

  insert into public.demo_domains
    (product_id, demo_ref, slug, hostname, pattern, environment,
     password_protected, allow_indexing, expires_at, grace_until,
     status, dns_status, ssl_status, created_by)
  values (p_product, v_ref, v_slug->>'slug', v_host,
          coalesce(p_pattern, v_s.default_pattern), 'demo',
          v_s.password_protect_by_default, not v_s.block_search_indexing,
          now() + (v_s.default_ttl_days || ' days')::interval,
          now() + ((v_s.default_ttl_days + v_s.grace_days) || ' days')::interval,
          -- The state the pipeline actually reaches. With no DNS provider
          -- nothing is attempted, so this is a prepared draft rather than a
          -- failure — and its hostname is reserved either way.
          case when (v_prov->>'dns') = 'CONNECTED' then 'provisioning' else 'draft' end,
          'dns_pending', 'pending', auth.uid())
  returning to_jsonb(demo_domains) into v_demo;

  if (v_prov->>'dns') <> 'CONNECTED' then
    update public.demo_domains
       set failure_reason = format('DNS is %s. %s',
             v_prov->>'dns',
             (select last_error from public.demo_provider_configs where slug='cloudflare_dns'))
     where id = (v_demo->>'id')::uuid
    returning to_jsonb(demo_domains) into v_demo;
  end if;

  v_key := 'demo_provision:' || p_product::text || ':' || v_ref;
  insert into public.demo_provision_jobs
    (demo_id, operation, status, idempotency_key, actor_id, started_at, finished_at,
     error_category, error_detail, provider)
  values ((v_demo->>'id')::uuid, 'provision',
          case when (v_prov->>'dns')='CONNECTED' then 'queued' else 'blocked' end,
          v_key, auth.uid(), now(),
          case when (v_prov->>'dns')='CONNECTED' then null else now() end,
          case when (v_prov->>'dns')='CONNECTED' then null else 'provider_not_configured' end,
          case when (v_prov->>'dns')='CONNECTED' then null
               else 'DNS, SSL and a deployment runtime must all authenticate before a demo can be provisioned.' end,
          'cloudflare')
  returning id into v_job;

  -- 17. The QR target is the real hostname, whatever state it is in.
  insert into public.demo_qr_codes (demo_id, target_url)
  values ((v_demo->>'id')::uuid, 'https://' || v_host);

  insert into public.demo_domain_events
    (demo_id, job_id, product_id, event, actor_id, new_state, reason, detail)
  values ((v_demo->>'id')::uuid, v_job, p_product, 'demo.prepared', auth.uid(),
          v_demo->>'status',
          case when (v_prov->>'dns')='CONNECTED' then 'Provisioning started.'
               else 'Hostname reserved; provisioning cannot start without a DNS provider.' end,
          jsonb_build_object('hostname', v_host, 'providers', v_prov));

  perform public.mm_audit('demo.prepared','demo_domain', (v_demo->>'id'), null, v_demo, null);

  return jsonb_build_object('ok', true, 'demo', v_demo, 'job_id', v_job,
    'hostname', v_host, 'url', 'https://' || v_host,
    'providers', v_prov,
    'provisioned', (v_prov->>'dns') = 'CONNECTED',
    'note', case when (v_prov->>'dns') = 'CONNECTED' then null
      else 'The hostname is reserved and nobody else can take it, but nothing was provisioned: '
        || 'no DNS, SSL or deployment provider authenticates. The demo is recorded as failed with the reason.' end);
end;
$$;


--
-- Name: mm_demo_settings_set(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_demo_settings_set(p_patch jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_before jsonb; v_after jsonb;
begin
  if not public.mm_is_operator() then
    return jsonb_build_object('ok', false, 'reason','not_permitted');
  end if;
  select to_jsonb(s) into v_before from public.demo_access_settings s where s.id;

  update public.demo_access_settings set
    base_domain = coalesce(nullif(p_patch->>'base_domain',''), base_domain),
    default_pattern = coalesce(nullif(p_patch->>'default_pattern',''), default_pattern),
    auto_provision_on_publish = coalesce((p_patch->>'auto_provision_on_publish')::boolean, auto_provision_on_publish),
    password_protect_by_default = coalesce((p_patch->>'password_protect_by_default')::boolean, password_protect_by_default),
    block_search_indexing = coalesce((p_patch->>'block_search_indexing')::boolean, block_search_indexing),
    default_ttl_days = coalesce((p_patch->>'default_ttl_days')::int, default_ttl_days),
    grace_days = coalesce((p_patch->>'grace_days')::int, grace_days),
    updated_by = auth.uid(), updated_at = now()
  where id returning to_jsonb(demo_access_settings) into v_after;

  insert into public.demo_domain_events (event, actor_id, reason, detail)
  values ('settings.changed', auth.uid(), nullif(p_patch->>'reason',''),
          jsonb_build_object('before', v_before, 'after', v_after));

  perform public.mm_audit('demo.settings_changed','demo_access_settings','settings',
                          v_before, v_after, nullif(p_patch->>'reason',''));
  return jsonb_build_object('ok', true, 'settings', v_after);
end;
$$;


--
-- Name: mm_demo_slug(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_demo_slug(p_product uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare v_name text; v_base text; v_try text; i integer := 1;
begin
  select name into v_name from public.marketplace_products where id = p_product;
  if v_name is null then
    return jsonb_build_object('ok', false, 'reason','unknown_product');
  end if;

  v_base := lower(btrim(v_name));
  v_base := regexp_replace(v_base, '[^a-z0-9]+', '-', 'g');
  v_base := regexp_replace(v_base, '(^-+|-+$)', '', 'g');
  v_base := regexp_replace(v_base, '-{2,}', '-', 'g');
  v_base := left(v_base, 48);
  v_base := regexp_replace(v_base, '-+$', '', 'g');

  if coalesce(v_base,'') = '' then
    v_base := 'product-' || left(replace(p_product::text,'-',''), 10);
  end if;
  -- A label may not begin with a digit or a hyphen.
  if v_base ~ '^[0-9-]' then v_base := 'p-' || v_base; end if;

  v_try := v_base;
  loop
    exit when not exists (select 1 from public.demo_reserved_slugs where slug = v_try)
          and not exists (select 1 from public.demo_domains
                           where slug = v_try
                             and status not in ('disabled','expired','failed'));
    i := i + 1;
    if i > 50 then
      return jsonb_build_object('ok', false, 'reason','could_not_generate');
    end if;
    v_try := left(v_base, 45) || '-' || i::text;
  end loop;

  return jsonb_build_object('ok', true, 'slug', v_try, 'base', v_base,
    'collisions', i - 1);
end;
$_$;


--
-- Name: mm_dispute_open(uuid, text, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_dispute_open(p_order_id uuid, p_reason text, p_amount numeric DEFAULT NULL::numeric) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare o record; v_id uuid; v_no text;
begin
  if not public.mm_is_operator() then
    return jsonb_build_object('ok', false, 'reason', 'not_permitted');
  end if;
  select * into o from public.marketplace_orders where id = p_order_id;
  if o.id is null then
    return jsonb_build_object('ok', false, 'reason', 'unknown_order');
  end if;
  if coalesce(trim(p_reason),'') = '' then
    return jsonb_build_object('ok', false, 'reason', 'reason_required');
  end if;

  insert into public.marketplace_disputes
    (order_id, buyer_id, payment_reference, amount, currency, reason, created_by)
  values (p_order_id, o.buyer_id, coalesce(o.payu_txn_id, o.txnid),
          coalesce(p_amount, o.total), o.currency::text, p_reason, auth.uid())
  returning id, dispute_no into v_id, v_no;

  perform public.mm_audit('order_dispute_opened', 'marketplace_order', p_order_id::text,
    '{}'::jsonb, jsonb_build_object('dispute_no', v_no, 'amount', coalesce(p_amount, o.total)),
    p_reason);

  return jsonb_build_object('ok', true, 'dispute_id', v_id, 'dispute_no', v_no,
    'message', 'Dispute ' || v_no || ' opened.');
end $$;


--
-- Name: mm_dispute_resolve(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_dispute_resolve(p_dispute_id uuid, p_status text, p_resolution text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare d record;
begin
  if not public.mm_is_operator() then
    return jsonb_build_object('ok', false, 'reason', 'not_permitted');
  end if;
  select * into d from public.marketplace_disputes where id = p_dispute_id;
  if d.id is null then return jsonb_build_object('ok', false, 'reason', 'unknown_dispute'); end if;

  update public.marketplace_disputes
     set status = p_status, resolution = p_resolution,
         resolved_at = case when p_status in ('won','lost','withdrawn','resolved')
                            then now() else null end,
         updated_at = now()
   where id = p_dispute_id;

  perform public.mm_audit('order_dispute_resolved', 'marketplace_order', d.order_id::text,
    jsonb_build_object('status', d.status),
    jsonb_build_object('status', p_status), p_resolution);

  return jsonb_build_object('ok', true, 'dispute_no', d.dispute_no, 'status', p_status);
end $$;


--
-- Name: mm_duplicate_decide(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_duplicate_decide(p_candidate uuid, p_decision text, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_row jsonb;
begin
  if not public.mm_is_operator() then
    return jsonb_build_object('ok', false, 'reason', 'not_permitted');
  end if;
  if p_decision not in ('not_duplicate','dismissed') then
    return jsonb_build_object('ok', false, 'reason', 'unknown_decision',
      'message','Merging is done through mm_product_merge, which needs a canonical product.');
  end if;

  update public.product_duplicate_candidates
     set status = p_decision, decided_by = auth.uid(), decided_at = now(),
         decision_reason = nullif(btrim(p_reason),'')
   where id = p_candidate and status = 'open'
  returning to_jsonb(product_duplicate_candidates) into v_row;

  if v_row is null then
    return jsonb_build_object('ok', false, 'reason','not_open',
      'message','That pair has already been decided.');
  end if;

  perform public.mm_audit('product.duplicate_'||p_decision,'product_duplicate',
                          p_candidate::text, null, v_row, p_reason);
  return jsonb_build_object('ok', true, 'candidate', v_row);
end;
$$;


--
-- Name: mm_duplicate_scan(numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_duplicate_scan(p_threshold numeric DEFAULT 60) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp', 'extensions'
    AS $$
declare v_found integer := 0; v_new integer := 0; r record; v_pct numeric; v_reasons jsonb;
begin
  if not public.mm_is_operator() then
    return jsonb_build_object('ok', false, 'reason', 'not_permitted');
  end if;

  for r in
    select a.id a_id, a.name a_name, a.description a_desc, a.category_id a_cat,
           a.seller_id a_seller, a.demo_url a_demo, a.public_repo_url a_repo,
           b.id b_id, b.name b_name, b.description b_desc, b.category_id b_cat,
           b.seller_id b_seller, b.demo_url b_demo, b.public_repo_url b_repo,
           similarity(a.name, b.name) name_sim,
           case when a.description is null or b.description is null then 0
                else similarity(left(a.description,1000), left(b.description,1000)) end desc_sim
      from public.marketplace_products a
      join public.marketplace_products b
        on b.id > a.id
       and a.deleted_at is null and b.deleted_at is null
       and a.merged_into is null and b.merged_into is null
       -- The trigram index does the work; only close names are considered.
       and a.name % b.name
     where similarity(a.name, b.name) >= 0.45
     -- Ordered before the cut. Taking an arbitrary 500 rows meant the closest
     -- pair in the catalogue could be missed entirely while weaker ones were
     -- recorded, which is exactly what a duplicate scan must not do.
     order by similarity(a.name, b.name) desc,
              case when a.description is null or b.description is null then 0
                   else similarity(left(a.description,1000), left(b.description,1000)) end desc
     limit 500
  loop
    -- Name similarity carries most of the weight, description the rest, with
    -- shared attributes adding confidence.
    v_pct := round((r.name_sim * 60 + r.desc_sim * 25)::numeric, 2);
    v_reasons := jsonb_build_array(
      jsonb_build_object('factor','name_similarity','weight', round((r.name_sim*60)::numeric,1),
        'evidence', format('"%s" and "%s" are %s%% alike.', r.a_name, r.b_name,
                           round((r.name_sim*100)::numeric,0))),
      jsonb_build_object('factor','description_similarity','weight', round((r.desc_sim*25)::numeric,1),
        'evidence', case when r.desc_sim = 0 then 'One of them has no description to compare.'
                         else format('Descriptions are %s%% alike.', round((r.desc_sim*100)::numeric,0)) end));

    if r.a_cat is not null and r.a_cat = r.b_cat then
      v_pct := v_pct + 5;
      v_reasons := v_reasons || jsonb_build_object('factor','same_category','weight',5,
        'evidence','Both are in the same category.');
    end if;
    if r.a_seller is not null and r.a_seller = r.b_seller then
      v_pct := v_pct + 5;
      v_reasons := v_reasons || jsonb_build_object('factor','same_owner','weight',5,
        'evidence','Both belong to the same seller.');
    end if;
    if coalesce(r.a_demo,'') <> '' and r.a_demo = r.b_demo then
      v_pct := v_pct + 3;
      v_reasons := v_reasons || jsonb_build_object('factor','same_demo','weight',3,
        'evidence', format('Both point at the same demo: %s', r.a_demo));
    end if;
    if coalesce(r.a_repo,'') <> '' and r.a_repo = r.b_repo then
      v_pct := v_pct + 2;
      v_reasons := v_reasons || jsonb_build_object('factor','same_repository','weight',2,
        'evidence','Both point at the same repository.');
    end if;

    v_pct := least(v_pct, 100);
    if v_pct < p_threshold then continue; end if;
    v_found := v_found + 1;

    insert into public.product_duplicate_candidates
      (product_a, product_b, match_percent, reasons)
    values (r.a_id, r.b_id, v_pct, v_reasons)
    on conflict (product_a, product_b) do update
      set match_percent = excluded.match_percent,
          reasons = excluded.reasons,
          scanned_at = now()
      -- A pair somebody has already ruled on is not reopened by a rescan.
      where public.product_duplicate_candidates.status = 'open';
    if found then v_new := v_new + 1; end if;
  end loop;

  perform public.mm_audit('product.duplicate_scan','marketplace_product', null, null,
    jsonb_build_object('threshold', p_threshold, 'matches', v_found), null);

  return jsonb_build_object('ok', true, 'threshold', p_threshold,
    'matches', v_found, 'recorded', v_new,
    'open', (select count(*) from public.product_duplicate_candidates where status='open'),
    'note','Advisory. Nothing is merged by a scan; every pair needs a person to decide.');
end;
$$;


--
-- Name: mm_faq_facts(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_faq_facts() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare v_plans jsonb;
begin
  if not public.mm_is_operator() then
    return jsonb_build_object('ok', false, 'reason', 'not_permitted');
  end if;

  select jsonb_agg(jsonb_build_object(
           'name', name, 'price_usd', price_usd,
           'margin_percent', profit_percent, 'validity_days', validity_days)
         order by sort_order)
    into v_plans from public.reseller_membership_plans where enabled;

  return jsonb_build_object(
    'ok', true,
    'facts', jsonb_build_array(
      jsonb_build_object(
        'key','catalogue_size',
        'statement', format('%s software products are published on the marketplace.',
                            (select count(*) from public.marketplace_products where visible)),
        'source','marketplace_products'),
      jsonb_build_object(
        'key','categories',
        'statement', format('The catalogue is organised into %s categories.',
                            (select count(*) from public.marketplace_categories)),
        'source','marketplace_categories'),
      jsonb_build_object(
        'key','reseller_plans',
        'statement', format('Reseller plans: %s.',
          (select string_agg(format('%s at $%s for %s days, %s%% margin',
                                    p->>'name', p->>'price_usd', p->>'validity_days',
                                    p->>'margin_percent'), '; ')
             from jsonb_array_elements(coalesce(v_plans,'[]'::jsonb)) p)),
        'source','reseller_membership_plans'),
      jsonb_build_object(
        'key','demos',
        'statement', format('%s products have a live demo URL a buyer can open before paying.',
                            (select count(*) from public.marketplace_products
                              where visible and coalesce(btrim(demo_url),'') <> '')),
        'source','marketplace_products.demo_url'),
      jsonb_build_object(
        'key','payment_rails',
        'statement', format('Payment is taken through: %s.',
          coalesce((select string_agg(name, ', ' order by position)
                      from public.storefront_trust_items where kind='payment'), 'no rail configured')),
        'source','storefront_trust_items'),
      jsonb_build_object(
        'key','reviews',
        'statement', format('%s published customer review(s), every one tied to a real order line.',
                            (select count(*) from public.marketplace_reviews where status='published')),
        'source','marketplace_reviews')),

    -- Named so a draft cannot quietly assert them. Section 28's list, checked
    -- against what this database can actually evidence.
    'unverifiable', jsonb_build_array(
      jsonb_build_object('key','pricing',
        'note','Product prices are stored as free-text labels on marketplace_products, not as a single figure this function can assert. Source information required before an FAQ states a price.'),
      jsonb_build_object('key','delivery_time',
        'note','No delivery-time configuration exists in the database. Any delivery promise must come from a person, not from a count.'),
      jsonb_build_object('key','refunds_and_guarantees',
        'note','Refund terms live in the Legal Manager, not here. An FAQ must quote the published policy rather than paraphrase it.'),
      jsonb_build_object('key','certifications',
        'note','No compliance certification is recorded anywhere in this system.')));
end;
$_$;


--
-- Name: mm_faq_rollback(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_faq_rollback(p_id uuid, p_version integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_v record; v_before record; v_after jsonb;
begin
  if not public.mm_is_operator() then
    return jsonb_build_object('ok', false, 'reason', 'not_permitted');
  end if;

  select * into v_v from public.faq_versions where faq_id = p_id and version = p_version;
  if not found then
    return jsonb_build_object('ok', false, 'reason', 'unknown_version');
  end if;
  select * into v_before from public.faqs where id = p_id;

  insert into public.faq_versions
    (faq_id, version, question, answer, status, change_summary, changed_by, snapshot)
  values (p_id, v_before.version, v_before.question, v_before.answer, v_before.status,
          format('replaced by a rollback to version %s', p_version), auth.uid(),
          to_jsonb(v_before))
  on conflict (faq_id, version) do nothing;

  update public.faqs
     set question = v_v.question, answer = v_v.answer,
         version = v_before.version + 1, updated_at = now()
   where id = p_id returning to_jsonb(faqs) into v_after;

  perform public.mm_audit('faq.rolled_back','faq', p_id::text,
                          to_jsonb(v_before), v_after,
                          format('rolled back to version %s', p_version));
  return jsonb_build_object('ok', true, 'faq', v_after);
end;
$$;


--
-- Name: mm_faq_save(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_faq_save(p_patch jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_id uuid := nullif(p_patch->>'id','')::uuid; v_before record; v_after jsonb;
begin
  if not public.mm_is_operator() then
    return jsonb_build_object('ok', false, 'reason', 'not_permitted');
  end if;
  if coalesce(btrim(p_patch->>'question'),'') = '' then
    return jsonb_build_object('ok', false, 'reason', 'question_required');
  end if;
  if coalesce(btrim(p_patch->>'answer'),'') = '' then
    return jsonb_build_object('ok', false, 'reason', 'answer_required',
      'message', 'An FAQ without an answer cannot be saved. Source information required.');
  end if;

  if v_id is not null then
    select * into v_before from public.faqs where id = v_id;
    if not found then
      return jsonb_build_object('ok', false, 'reason', 'unknown_faq');
    end if;

    insert into public.faq_versions
      (faq_id, version, question, answer, status, change_summary, changed_by, snapshot)
    values (v_id, v_before.version, v_before.question, v_before.answer, v_before.status,
            nullif(p_patch->>'change_summary',''), auth.uid(), to_jsonb(v_before))
    on conflict (faq_id, version) do nothing;

    update public.faqs set
      question = btrim(p_patch->>'question'),
      answer = btrim(p_patch->>'answer'),
      category_id = coalesce(nullif(p_patch->>'category_id','')::uuid, category_id),
      tags = coalesce((select array_agg(x)::text[] from jsonb_array_elements_text(p_patch->'tags') x), tags),
      seo_title = coalesce(nullif(p_patch->>'seo_title',''), seo_title),
      seo_description = coalesce(nullif(p_patch->>'seo_description',''), seo_description),
      related_product_ids = coalesce(
        (select array_agg(x::uuid) from jsonb_array_elements_text(p_patch->'related_product_ids') x),
        related_product_ids),
      language = coalesce(nullif(p_patch->>'language',''), language),
      position = coalesce((p_patch->>'position')::int, position),
      version = version + 1,
      updated_at = now()
    where id = v_id returning to_jsonb(faqs) into v_after;

    perform public.mm_audit('faq.edited','faq', v_id::text,
                            to_jsonb(v_before), v_after, nullif(p_patch->>'change_summary',''));
  else
    insert into public.faqs
      (question, answer, category_id, tags, language, status, ai_generated, ai_sources,
       seo_title, seo_description, author_id, position)
    values (btrim(p_patch->>'question'), btrim(p_patch->>'answer'),
            nullif(p_patch->>'category_id','')::uuid,
            coalesce((select array_agg(x)::text[] from jsonb_array_elements_text(p_patch->'tags') x), '{}'),
            coalesce(nullif(p_patch->>'language',''),'en'),
            'draft',
            coalesce((p_patch->>'ai_generated')::boolean, false),
            coalesce(p_patch->'ai_sources','[]'::jsonb),
            nullif(p_patch->>'seo_title',''), nullif(p_patch->>'seo_description',''),
            auth.uid(),
            coalesce((p_patch->>'position')::int,
                     (select coalesce(max(position),0)+1 from public.faqs)))
    returning to_jsonb(faqs) into v_after;

    perform public.mm_audit('faq.created','faq', v_after->>'id', null, v_after, null);
  end if;

  return jsonb_build_object('ok', true, 'faq', v_after);
end;
$$;


--
-- Name: mm_faq_transition(uuid, text, timestamp with time zone, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_faq_transition(p_id uuid, p_to text, p_when timestamp with time zone DEFAULT NULL::timestamp with time zone, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_before jsonb; v_after jsonb;
begin
  if not public.mm_is_operator() then
    return jsonb_build_object('ok', false, 'reason', 'not_permitted');
  end if;
  if p_to not in ('draft','pending_review','scheduled','published','archived') then
    return jsonb_build_object('ok', false, 'reason', 'unknown_status');
  end if;
  if p_to = 'scheduled' and p_when is null then
    return jsonb_build_object('ok', false, 'reason', 'schedule_time_required',
      'message', 'A scheduled FAQ needs a time, or it would never publish.');
  end if;

  select to_jsonb(f) into v_before from public.faqs f where f.id = p_id;
  if v_before is null then
    return jsonb_build_object('ok', false, 'reason', 'unknown_faq');
  end if;

  -- An AI draft stops being marked as AI-generated when a person publishes it:
  -- at that point a human has taken responsibility for what it says.
  update public.faqs set
    status = p_to,
    scheduled_for = case when p_to='scheduled' then p_when else scheduled_for end,
    published_at = case when p_to='published' then coalesce(published_at, now()) else published_at end,
    ai_generated = case when p_to='published' then false else ai_generated end,
    updated_at = now()
  where id = p_id returning to_jsonb(faqs) into v_after;

  perform public.mm_audit('faq.'||p_to, 'faq', p_id::text, v_before, v_after, p_reason);
  return jsonb_build_object('ok', true, 'faq', v_after);
end;
$$;


--
-- Name: mm_faqs(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_faqs(p_query jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_search text := nullif(btrim(coalesce(p_query->>'search','')),'');
  v_status text := nullif(p_query->>'status','');
  v_cat    text := nullif(p_query->>'category','');
  v_limit  integer := least(greatest(coalesce((p_query->>'limit')::int,200),1),500);
begin
  if not public.mm_is_operator() then
    return jsonb_build_object('ok', false, 'reason', 'not_permitted');
  end if;

  return jsonb_build_object(
    'ok', true,
    'total',        (select count(*) from public.faqs),
    'published',    (select count(*) from public.faqs where status='published'),
    'drafts',       (select count(*) from public.faqs where status='draft'),
    'pending',      (select count(*) from public.faqs where status='pending_review'),
    'scheduled',    (select count(*) from public.faqs where status='scheduled'),
    'archived',     (select count(*) from public.faqs where status='archived'),
    'ai_generated', (select count(*) from public.faqs where ai_generated),
    'categories',   (select count(*) from public.faq_categories where enabled),
    'recently_updated', (select count(*) from public.faqs
                          where updated_at > now() - interval '7 days'),
    'languages', coalesce((select jsonb_agg(distinct language) from public.faqs), '[]'::jsonb),

    'category_rows', coalesce((
      select jsonb_agg(jsonb_build_object(
               'id', c.id, 'slug', c.slug, 'name', c.name, 'position', c.position,
               'enabled', c.enabled,
               'faqs', (select count(*) from public.faqs f where f.category_id = c.id))
             order by c.position)
        from public.faq_categories c), '[]'::jsonb),

    'faqs', coalesce((
      select jsonb_agg(jsonb_build_object(
               'id', f.id, 'question', f.question, 'answer', f.answer,
               'category_id', f.category_id,
               'category', (select c.name from public.faq_categories c where c.id = f.category_id),
               'slug', f.slug, 'tags', f.tags, 'language', f.language,
               'status', f.status, 'ai_generated', f.ai_generated,
               'ai_sources', f.ai_sources,
               'seo_title', f.seo_title, 'seo_description', f.seo_description,
               'related_product_ids', f.related_product_ids,
               'scheduled_for', f.scheduled_for, 'published_at', f.published_at,
               'version', f.version, 'position', f.position,
               'updated_at', f.updated_at,
               'versions', (select count(*) from public.faq_versions v where v.faq_id = f.id))
             order by f.position, f.created_at)
        from (select * from public.faqs f2
               where (v_status is null or f2.status = v_status)
                 and (v_cat is null or f2.category_id = v_cat::uuid)
                 and (v_search is null
                      or f2.question ilike '%'||v_search||'%'
                      or f2.answer ilike '%'||v_search||'%'
                      or v_search = any(f2.tags))
               order by f2.position, f2.created_at limit v_limit) f), '[]'::jsonb));
end;
$$;


--
-- Name: mm_filter_set(text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_filter_set(p_key text, p_patch jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_before jsonb; v_after jsonb;
begin
  if not public.mm_is_operator() then
    return jsonb_build_object('ok', false, 'reason', 'not_permitted');
  end if;

  select to_jsonb(g) into v_before from public.marketplace_filter_groups g where g.key = p_key;
  if v_before is null then
    return jsonb_build_object('ok', false, 'reason', 'unknown_group');
  end if;

  update public.marketplace_filter_groups g set
    enabled         = coalesce((p_patch->>'enabled')::boolean, g.enabled),
    label           = coalesce(nullif(btrim(p_patch->>'label'),''), g.label),
    position        = coalesce((p_patch->>'position')::int, g.position),
    select_mode     = coalesce(p_patch->>'select_mode', g.select_mode),
    combine         = coalesce(p_patch->>'combine', g.combine),
    visible_desktop = coalesce((p_patch->>'visible_desktop')::boolean, g.visible_desktop),
    visible_mobile  = coalesce((p_patch->>'visible_mobile')::boolean, g.visible_mobile),
    updated_by = auth.uid(), updated_at = now()
  where g.key = p_key
  returning to_jsonb(g) into v_after;

  perform public.mm_audit('filter.configure', 'storefront_filter', p_key,
                          v_before, v_after, null);
  return jsonb_build_object('ok', true, 'group', v_after);
end;
$$;


--
-- Name: mm_filter_values(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_filter_values(p_key text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare v_source text; v_out jsonb;
begin
  select source into v_source from public.marketplace_filter_groups where key = p_key;
  if v_source is null then
    return jsonb_build_object('ok', false, 'reason', 'unknown_group');
  end if;

  if v_source = 'category' then
    select coalesce(jsonb_agg(jsonb_build_object('value', c.slug, 'label', c.name, 'count', n)
                    order by n desc, c.name), '[]'::jsonb)
      into v_out
      from public.marketplace_categories c
      join lateral (
        select count(*) as n from public.marketplace_products p
         where p.category_id = c.id and p.visible and p.content_status = 'published'
      ) k on true
     where not c.is_hidden;

  elsif v_source = 'industry' then
    select coalesce(jsonb_agg(jsonb_build_object('value', industry_label,
                                                 'label', industry_label, 'count', n)
                    order by n desc, industry_label), '[]'::jsonb)
      into v_out
      from (select industry_label, count(*) n from public.marketplace_products
             where visible and content_status = 'published'
               and coalesce(btrim(industry_label), '') <> ''
             group by industry_label) t;

  elsif v_source = 'deployment' then
    select coalesce(jsonb_agg(jsonb_build_object('value', deployment,
                                                 'label', deployment, 'count', n)
                    order by n desc, deployment), '[]'::jsonb)
      into v_out
      from (select deployment, count(*) n from public.marketplace_products
             where visible and content_status = 'published'
               and coalesce(btrim(deployment), '') <> ''
             group by deployment) t;

  elsif v_source = 'license' then
    select coalesce(jsonb_agg(jsonb_build_object('value', license,
                                                 'label', license, 'count', n)
                    order by n desc, license), '[]'::jsonb)
      into v_out
      from (select license, count(*) n from public.marketplace_products
             where visible and content_status = 'published'
               and coalesce(btrim(license), '') <> ''
             group by license) t;

  elsif v_source = 'platform' then
    -- The catalogue records deployment as free text and a mobile field; there
    -- is no per-platform flag, so the values are what the data can actually
    -- distinguish rather than the four the screen used to name.
    select coalesce(jsonb_agg(jsonb_build_object('value', v, 'label', v, 'count', n)
                    order by n desc), '[]'::jsonb)
      into v_out
      from (
        select 'Cloud' as v, count(*) n from public.marketplace_products
          where visible and content_status='published' and deployment ilike '%cloud%'
        union all
        select 'On-premise', count(*) from public.marketplace_products
          where visible and content_status='published' and deployment ilike '%premise%'
        union all
        select 'Mobile', count(*) from public.marketplace_products
          where visible and content_status='published' and coalesce(btrim(mobile),'') <> ''
      ) t where n > 0;

  elsif v_source = 'tag' then
    -- The same flags the Product Card Manager's badges read. One source, so
    -- badge and filter can never disagree.
    select jsonb_build_array(
      jsonb_build_object('value','new','label','New','count',
        (select count(*) from public.marketplace_products where visible and content_status='published' and is_new_release)),
      jsonb_build_object('value','trending','label','Trending','count',
        (select count(*) from public.marketplace_products where visible and content_status='published' and is_trending)),
      jsonb_build_object('value','featured','label','Featured','count',
        (select count(*) from public.marketplace_products where visible and content_status='published' and is_featured)),
      jsonb_build_object('value','best_seller','label','Best Seller','count',
        (select count(*) from public.marketplace_products where visible and content_status='published' and is_best_seller)),
      jsonb_build_object('value','ai_ready','label','AI Ready','count',
        (select count(*) from public.marketplace_products where visible and content_status='published' and is_ai))
    ) into v_out;

  elsif v_source = 'price' then
    -- Buckets over the real price label. The catalogue prices in four distinct
    -- ways today, so these are the bands that actually separate anything.
    select jsonb_build_array(
      jsonb_build_object('value','lifetime_249','label','$249 lifetime','count',
        (select count(*) from public.marketplace_products where visible and content_status='published' and price_label = '$249')),
      jsonb_build_object('value','custom','label','Custom','count',
        (select count(*) from public.marketplace_products where visible and content_status='published' and price_label = 'Custom')),
      jsonb_build_object('value','contact','label','Contact for pricing','count',
        (select count(*) from public.marketplace_products where visible and content_status='published' and price_label = 'Contact'))
    ) into v_out;

  elsif v_source = 'rating' then
    select jsonb_build_array(
      jsonb_build_object('value','5','label','5 stars','count',
        (select count(*) from public.marketplace_products where visible and content_status='published' and rating >= 5)),
      jsonb_build_object('value','4','label','4 and up','count',
        (select count(*) from public.marketplace_products where visible and content_status='published' and rating >= 4)),
      jsonb_build_object('value','3','label','3 and up','count',
        (select count(*) from public.marketplace_products where visible and content_status='published' and rating >= 3))
    ) into v_out;
  else
    v_out := '[]'::jsonb;
  end if;

  return jsonb_build_object('ok', true, 'group', p_key, 'source', v_source,
                            'values', coalesce(v_out, '[]'::jsonb));
end;
$_$;


--
-- Name: mm_filters(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_filters() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_out jsonb := '[]'::jsonb; g record;
begin
  if not public.mm_is_operator() then
    return jsonb_build_object('ok', false, 'reason', 'not_permitted');
  end if;

  for g in select * from public.marketplace_filter_groups order by position loop
    v_out := v_out || jsonb_build_object(
      'key', g.key, 'label', g.label, 'source', g.source,
      'enabled', g.enabled, 'position', g.position,
      'select_mode', g.select_mode, 'combine', g.combine,
      'visible_desktop', g.visible_desktop, 'visible_mobile', g.visible_mobile,
      'values', public.mm_filter_values(g.key)->'values');
  end loop;

  return jsonb_build_object('ok', true, 'groups', v_out);
end;
$$;


--
-- Name: mm_health_checks(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_health_checks() RETURNS TABLE(check_key text, label text, severity text, affected bigint, destination text, sample_ids uuid[])
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  with
  live as (
    select id, category_id, demo_url, description, thumbnail_url
    from public.marketplace_products
    where content_status = 'published'
      and visible
      and (publish_at is null or publish_at <= now())
      and (unpublish_at is null or unpublish_at > now())
  ),
  -- The full sets, uncapped: the count has to be the real count. Only the
  -- sample handed back to the screen is limited, because a console does not
  -- need five thousand identifiers to link to the first few.
  no_category    as (select id from live where category_id is null),
  no_price       as (select l.id from live l
                     where not exists (select 1 from public.marketplace_product_pricing pr
                                       where pr.product_id = l.id)),
  no_demo        as (select id from live where coalesce(demo_url, '') = ''),
  no_description as (select id from live where coalesce(length(description), 0) < 40),
  pending        as (select id from public.marketplace_products
                     where moderation_status not in ('approved','archived')),
  no_media       as (select id from live where coalesce(thumbnail_url, '') = '')
  select 'products_without_category', 'Published products with no category', 'high',
         (select count(*) from no_category), '/marketplace-manager?section=catalog&filter=no_category',
         (select coalesce(array_agg(id), '{}') from (select id from no_category limit 50) t)
  union all
  select 'products_without_price', 'Published products with no price', 'critical',
         (select count(*) from no_price), '/marketplace-manager?section=catalog&filter=no_price',
         (select coalesce(array_agg(id), '{}') from (select id from no_price limit 50) t)
  union all
  select 'products_without_demo', 'Published products with no demo link', 'medium',
         (select count(*) from no_demo), '/marketplace-manager?section=demo-urls',
         (select coalesce(array_agg(id), '{}') from (select id from no_demo limit 50) t)
  union all
  select 'products_thin_description', 'Published products with a thin description', 'medium',
         (select count(*) from no_description), '/marketplace-manager?section=catalog&filter=thin',
         (select coalesce(array_agg(id), '{}') from (select id from no_description limit 50) t)
  union all
  select 'products_without_media', 'Published products with no image', 'high',
         (select count(*) from no_media), '/marketplace-manager?section=catalog&filter=no_media',
         (select coalesce(array_agg(id), '{}') from (select id from no_media limit 50) t)
  union all
  select 'products_pending_approval', 'Products waiting for approval', 'medium',
         (select count(*) from pending), '/marketplace-manager?section=catalog&filter=pending',
         (select coalesce(array_agg(id), '{}') from (select id from pending limit 50) t)
  union all
  -- Section 12 names a scheduling gap explicitly: rows that are scheduled but
  -- whose window has already closed leave a hole on the page.
  select 'homepage_rows_expired', 'Homepage rows whose schedule has run out', 'high',
         (select count(*) from public.marketplace_homepage_sections
          where status = 'published' and ends_at is not null and ends_at <= now()),
         '/marketplace-manager?section=homepage-rows', '{}'::uuid[]
  union all
  select 'homepage_no_rows', 'No published homepage rows configured', 'low',
         (select case when count(*) = 0 then 1 else 0 end
          from public.marketplace_homepage_sections where status = 'published'),
         '/marketplace-manager?section=homepage-rows', '{}'::uuid[];
$$;


--
-- Name: mm_homepage_sections(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_homepage_sections() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select coalesce(jsonb_agg(r order by (r->>'sort_order')::int), '[]'::jsonb)
  from (
    select jsonb_build_object(
      'key', s.key,
      'title', s.title,
      'row_type', s.row_type,
      'source', s.source,
      'sort_order', s.sort_order,
      'status', s.status,
      'enabled', s.enabled,
      'visible_desktop', s.visible_desktop,
      'visible_mobile', s.visible_mobile,
      'starts_at', s.starts_at,
      'ends_at', s.ends_at,
      'component', s.config->>'component',
      'file', s.config->>'file',
      -- Which module owns this section's content. Marketplace Manager controls
      -- placement and publication; the owner controls what is inside.
      'owner', coalesce(s.config->>'owner', 'marketplace-manager'),
      'data_source', s.config->>'data_source',
      'archived_reason', s.config->>'archived_reason',
      -- Live means it would render right now: published, enabled and inside
      -- its schedule.
      'live_now', (s.status = 'published' and coalesce(s.enabled,false)
                   and (s.starts_at is null or s.starts_at <= now())
                   and (s.ends_at is null or s.ends_at > now())),
      -- For the one section that expands into many, say how many.
      'child_rows', case when s.key = 'catalog-rows'
                         then (select count(*) from public.marketplace_categories where not is_hidden)
                         else null end
    ) r
    from public.marketplace_homepage_sections s
  ) x;
$$;


--
-- Name: mm_influencer_code_create(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_influencer_code_create(p_profile uuid, p_code text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp', 'extensions'
    AS $$
declare
  v_alphabet constant text := 'ABCDEFGHJKMNPQRSTUVWXYZ23456789';
  v_name text;
  v_code text;
  v_bytes bytea;
  i integer;
  v_row jsonb;
begin
  if not public.mm_is_operator() then
    return jsonb_build_object('ok', false, 'reason', 'not_permitted');
  end if;

  select full_name into v_name from public.influencer_profiles where id = p_profile;
  if v_name is null then
    return jsonb_build_object('ok', false, 'reason', 'unknown_influencer');
  end if;

  if p_code is not null and btrim(p_code) <> '' then
    v_code := upper(regexp_replace(btrim(p_code), '[^A-Za-z0-9-]', '', 'g'));
    if length(v_code) < 3 then
      return jsonb_build_object('ok', false, 'reason', 'code_too_short');
    end if;
    if exists (select 1 from public.marketplace_referral_codes where upper(code) = v_code) then
      return jsonb_build_object('ok', false, 'reason', 'code_taken',
        'message', 'Another referral code already uses that word.');
    end if;
  else
    -- Eight characters over an alphabet with no I, L, O, 0 or 1, so a creator
    -- can read it out on camera without it being mistyped.
    for attempt in 1..10 loop
      v_code := '';
      v_bytes := gen_random_bytes(8);
      for i in 0..7 loop
        v_code := v_code || substr(v_alphabet, (get_byte(v_bytes, i) % length(v_alphabet)) + 1, 1);
      end loop;
      exit when not exists (
        select 1 from public.marketplace_referral_codes where upper(code) = v_code);
      v_code := null;
    end loop;
    if v_code is null then
      return jsonb_build_object('ok', false, 'reason', 'could_not_generate');
    end if;
  end if;

  insert into public.marketplace_referral_codes (influencer_profile_id, code, active)
  values (p_profile, v_code, true)
  returning to_jsonb(marketplace_referral_codes) into v_row;

  perform public.mm_audit('influencer.code_created', 'influencer_profile',
                          p_profile::text, null,
                          jsonb_build_object('code', v_code, 'influencer', v_name), null);

  return jsonb_build_object('ok', true, 'code', v_code, 'row', v_row,
    -- The link a creator actually shares.
    'share_url', 'https://softwarevala.net/?ref=' || v_code);
end;
$$;


--
-- Name: mm_influencer_status(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_influencer_status(p_profile uuid, p_to text, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_before jsonb; v_after jsonb;
begin
  if not public.mm_is_operator() then
    return jsonb_build_object('ok', false, 'reason', 'not_permitted');
  end if;
  -- These four are what influencer_profiles_status_check permits.
  if p_to not in ('pending','active','suspended','inactive') then
    return jsonb_build_object('ok', false, 'reason', 'unknown_status');
  end if;

  select to_jsonb(p) into v_before from public.influencer_profiles p where p.id = p_profile;
  if v_before is null then
    return jsonb_build_object('ok', false, 'reason', 'unknown_influencer');
  end if;

  update public.influencer_profiles
     set status = p_to, updated_at = now()
   where id = p_profile
  returning to_jsonb(influencer_profiles) into v_after;

  -- A suspended or terminated creator's codes stop working, or the tracking
  -- would keep crediting somebody who is no longer active.
  if p_to in ('suspended','inactive') then
    update public.marketplace_referral_codes
       set active = false, updated_at = now()
     where influencer_profile_id = p_profile and active;
  elsif p_to = 'active' then
    update public.marketplace_referral_codes
       set active = true, updated_at = now()
     where influencer_profile_id = p_profile and not active;
  end if;

  perform public.mm_audit('influencer.' || p_to, 'influencer_profile',
                          p_profile::text, v_before, v_after, p_reason);

  -- The creator is told, through the notification engine rather than a second
  -- one. It reaches their bell if they have an account.
  if (v_after->>'user_id') is not null then
    perform public.mm_notify(
      'influencer.' || p_to,
      case p_to when 'active' then 'Your creator account is approved'
                when 'suspended' then 'Your creator account is suspended'
                when 'inactive' then 'Your creator account is now inactive'
                else 'Your creator account status changed' end,
      coalesce(p_reason, ''),
      (v_after->>'user_id')::uuid, null, '/influencer-manager', 'Open',
      5,
      case p_to when 'active' then 'success'
                when 'suspended' then 'danger'
                when 'inactive' then 'warning' else 'info' end);
  end if;

  return jsonb_build_object('ok', true, 'influencer', v_after);
end;
$$;


--
-- Name: mm_influencers(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_influencers(p_query jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_search text := nullif(btrim(coalesce(p_query->>'search','')), '');
  v_status text := nullif(p_query->>'status','');
  v_limit  integer := least(greatest(coalesce((p_query->>'limit')::int, 50), 1), 200);
begin
  if not public.mm_is_operator() then
    return jsonb_build_object('ok', false, 'reason', 'not_permitted');
  end if;

  return jsonb_build_object(
    'ok', true,
    'creators',      (select count(*) from public.influencer_profiles),
    'by_status', coalesce((
      select jsonb_object_agg(coalesce(status,'unknown'), n)
        from (select status, count(*) n from public.influencer_profiles group by status) t),
      '{}'::jsonb),
    'applications',  (select count(*) from public.influencer_applications),
    'social_accounts', (select count(*) from public.influencer_social_accounts),
    'declared_followers', (select coalesce(sum(followers),0)
                             from public.influencer_social_accounts),
    'verified_accounts', (select count(*) from public.influencer_social_accounts
                           where verification_status = 'verified'),
    'agreements',    (select count(*) from public.influencer_agreements),
    'assignments',   (select count(*) from public.influencer_campaign_assignments),

    'earnings_gross', (select coalesce(sum(gross_amount),0) from public.influencer_earnings),
    'earnings_net',   (select coalesce(sum(net_amount),0) from public.influencer_earnings),
    'payouts_total',  (select coalesce(sum(amount),0) from public.influencer_payouts),
    'payouts_paid',   (select coalesce(sum(amount),0) from public.influencer_payouts
                        where status = 'paid'),
    'payouts_pending',(select coalesce(sum(amount),0) from public.influencer_payouts
                        where status in ('pending','approved','processing')),

    'referral_codes', (select count(*) from public.marketplace_referral_codes
                        where influencer_profile_id is not null),
    'sessions',       (select count(*) from public.marketplace_referral_sessions
                        where influencer_profile_id is not null),
    'conversions',    (select count(*) from public.marketplace_order_attributions
                        where influencer_profile_id is not null),

    'unavailable', jsonb_build_object(
      'verified_reach', 'Follower and engagement figures are the creator''s own declaration from their application. No social platform API is connected, so none of them has been confirmed or refreshed since.',
      'roi',            'ROI compares attributed revenue against recorded spend. Attribution now runs at checkout, so this fills in once a referred order is paid.'),

    'profiles', coalesce((
      select jsonb_agg(jsonb_build_object(
               'id', p.id, 'name', p.full_name, 'email', p.email,
               'country', p.country, 'region', p.region, 'niche', p.niche,
               'status', p.status, 'created_at', p.created_at,
               'social_accounts', (select count(*) from public.influencer_social_accounts s
                                    where s.profile_id = p.id),
               'referral_codes', (select count(*) from public.marketplace_referral_codes c
                                   where c.influencer_profile_id = p.id),
               'earnings_net', (select coalesce(sum(e.net_amount),0)
                                  from public.influencer_earnings e where e.profile_id = p.id),
               'payouts_paid', (select coalesce(sum(o.amount),0)
                                  from public.influencer_payouts o
                                 where o.profile_id = p.id and o.status='paid'))
             order by p.created_at desc)
        from (select * from public.influencer_profiles p2
               where (v_status is null or p2.status = v_status)
                 and (v_search is null
                      or p2.full_name ilike '%'||v_search||'%'
                      or coalesce(p2.email,'') ilike '%'||v_search||'%'
                      or coalesce(p2.niche,'') ilike '%'||v_search||'%')
               order by p2.created_at desc limit v_limit) p), '[]'::jsonb));
end;
$$;


--
-- Name: mm_is_operator(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_is_operator() RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_claims text := current_setting('request.jwt.claims', true);
  v_role   text;
begin
  -- A malformed or absent claim must not raise; it simply means "no JWT".
  begin
    v_role := (nullif(v_claims, '')::jsonb) ->> 'role';
  exception when others then
    v_role := null;
  end;

  -- A server-side call with the service key.
  if v_role = 'service_role' then
    return true;
  end if;

  -- A direct database session with no request context: a migration, psql, the
  -- Management API. Anything arriving through PostgREST connects as
  -- 'authenticator' and is excluded here, so a browser can never take this
  -- branch no matter what it sends.
  if nullif(v_claims, '') is null
     and session_user not in ('authenticator', 'anon', 'authenticated') then
    return true;
  end if;

  -- Otherwise this is a person, and the role they actually hold decides.
  return exists (
    select 1
      from public.user_roles ur
     where ur.user_id = auth.uid()
       and ur.role in ('admin','boss','founder','super_admin','boss_owner','marketing','seo')
  );
end;
$$;


--
-- Name: mm_issue_for_order(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_issue_for_order(p_order_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  o           record;
  item        record;
  v_ent       uuid;
  v_key       text;
  v_created   integer := 0;
  v_skipped   integer := 0;
  v_model     text;
begin
  select * into o from public.marketplace_orders where id = p_order_id;
  if not found then
    return jsonb_build_object('ok', false, 'reason', 'unknown_order');
  end if;
  if o.status::text <> 'paid' then
    return jsonb_build_object('ok', false, 'reason', 'order_not_paid',
                              'status', o.status::text);
  end if;
  if o.buyer_id is null then
    -- An order with no buyer cannot own a licence. Reported rather than
    -- guessed at.
    return jsonb_build_object('ok', false, 'reason', 'order_has_no_buyer');
  end if;

  for item in
    select oi.id, oi.product_id
      from public.marketplace_order_items oi
     where oi.order_id = p_order_id
  loop
    if exists (select 1 from public.marketplace_entitlements
                where order_item_id = item.id) then
      v_skipped := v_skipped + 1;
      continue;
    end if;

    insert into public.marketplace_entitlements
      (order_item_id, buyer_id, product_id, status, starts_at)
    values (item.id, o.buyer_id, item.product_id, 'active', now())
    returning id into v_ent;

    -- The licence model follows the product's own licence field rather than a
    -- value invented here, mapped onto the five the table permits:
    -- single_user, team, subscription, lifetime, trial. The catalogue records
    -- 'Lifetime' for 3,659 products and 'SaaS' for one.
    select case
             when p.license ilike '%saas%' or p.license ilike '%subscription%'
               then 'subscription'
             when p.license ilike '%trial%' then 'trial'
             when p.license ilike '%team%' or p.license ilike '%multi%' then 'team'
             when p.license ilike '%single%' then 'single_user'
             else 'lifetime'
           end
      into v_model
      from public.marketplace_products p where p.id = item.product_id;

    v_key := public.mm_new_license_key();

    insert into public.marketplace_licenses
      (order_item_id, buyer_id, product_id, license_key, license_model, status)
    values (item.id, o.buyer_id, item.product_id, v_key,
            coalesce(v_model, 'lifetime'), 'active');

    v_created := v_created + 1;

    perform public.mm_audit(
      'license.issued', 'marketplace_license', item.id::text,
      null,
      jsonb_build_object('order_id', p_order_id, 'product_id', item.product_id,
                         'license_model', v_model, 'entitlement_id', v_ent),
      'issued on payment');
  end loop;

  return jsonb_build_object('ok', true, 'order', p_order_id,
                            'issued', v_created, 'already_had', v_skipped);
end;
$$;


--
-- Name: mm_license_overview(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_license_overview(p_window text DEFAULT '30d'::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_since timestamptz;
begin
  if not public.mm_is_operator() then
    return jsonb_build_object('ok', false, 'reason', 'not_permitted');
  end if;

  v_since := case p_window
               when 'today' then date_trunc('day', now())
               when '7d'    then now() - interval '7 days'
               when '30d'   then now() - interval '30 days'
               when '90d'   then now() - interval '90 days'
               else now() - interval '30 days'
             end;

  return jsonb_build_object(
    'ok', true,
    'window', p_window,
    'active_keys',   (select count(*) from public.marketplace_licenses where status = 'active'),
    -- A trial is a licence model here, not a status: the status column permits
    -- only issued, active, revoked and expired.
    'in_trial',      (select count(*) from public.marketplace_licenses
                       where license_model = 'trial' and status in ('issued','active')),
    'expiring_30d',  (select count(*) from public.marketplace_licenses
                       where status = 'active' and expires_at is not null
                         and expires_at between now() and now() + interval '30 days'),
    'revoked',       (select count(*) from public.marketplace_licenses where status = 'revoked'),
    'total',         (select count(*) from public.marketplace_licenses),
    'issued_in_window', (select count(*) from public.marketplace_licenses where created_at >= v_since),
    'entitlements',  (select count(*) from public.marketplace_entitlements),
    'entitlements_active', (select count(*) from public.marketplace_entitlements where status = 'active'),
    -- Counted, not asserted. There is no activation endpoint in this project
    -- yet, so this is zero and says so rather than showing a number.
    'activations',   0,
    'activations_available', false,
    'downloads',     (select count(*) from public.marketplace_downloads),
    'paid_orders',   (select count(*) from public.marketplace_orders where status::text = 'paid'),
    'paid_order_items', (select count(*) from public.marketplace_order_items oi
                          join public.marketplace_orders o on o.id = oi.order_id
                         where o.status::text = 'paid'),
    'product_versions', (select count(*) from public.marketplace_product_versions),
    'by_model', coalesce((
      select jsonb_agg(jsonb_build_object('model', license_model, 'count', n) order by n desc)
        from (select license_model, count(*) n from public.marketplace_licenses
               group by license_model) t), '[]'::jsonb),
    'by_status', coalesce((
      select jsonb_agg(jsonb_build_object('status', status, 'count', n) order by n desc)
        from (select status, count(*) n from public.marketplace_licenses
               group by status) t), '[]'::jsonb));
end;
$$;


--
-- Name: mm_marketing_summary(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_marketing_summary() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_seed jsonb;
begin
  if not public.mm_is_operator() then
    return jsonb_build_object('ok', false, 'reason', 'not_permitted');
  end if;

  v_seed := public.marketing_seed_summary();

  return jsonb_build_object(
    'ok', true,
    'real_campaigns',    coalesce((v_seed->>'real_campaigns')::int, 0),
    'seed_campaigns',    coalesce((v_seed->>'seed_campaigns')::int, 0),
    'seed_revenue',      coalesce((v_seed->>'seed_revenue')::numeric, 0),
    'real_revenue',      coalesce((v_seed->>'real_revenue')::numeric, 0),
    'seed_leads',        coalesce((v_seed->>'seed_leads')::int, 0),
    'lead_records',      coalesce((v_seed->>'lead_records')::int, 0),
    'templates',         (select count(*) from public.marketing_templates),
    'automations',       (select count(*) from public.marketing_automations),
    'approvals_pending', (select count(*) from public.marketing_approvals
                           where coalesce(status,'') in ('pending','submitted','review')),
    'creatives',         (select count(*) from public.marketing_creatives),
    'messages',          (select count(*) from public.marketing_messages),
    -- Nothing has been delivered, because nothing can be: no provider is
    -- configured. Counted from the queue rather than asserted.
    'email_queued',      (select count(*) from public.email_queue));
end;
$$;


--
-- Name: mm_marketplace_score(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_marketplace_score() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_published bigint;
  v_total     bigint;
  v_factors   jsonb := '[]'::jsonb;
  v_score     numeric := 0;
  v_weighted  numeric := 0;
  r           record;
  v_ratio     numeric;
  v_weight    numeric;
begin
  select count(*) filter (
           where content_status = 'published' and visible
             and (publish_at is null or publish_at <= now())
             and (unpublish_at is null or unpublish_at > now())),
         count(*)
    into v_published, v_total
  from public.marketplace_products;

  if v_published = 0 then
    -- No catalogue, no score. Reporting 100% for an empty marketplace would be
    -- the exact decoration section 31 forbids.
    return jsonb_build_object(
      'score', null,
      'reason', 'no published products to assess',
      'published_products', 0,
      'factors', '[]'::jsonb);
  end if;

  -- Each health check becomes a factor: the share of the catalogue that is
  -- clean on that dimension, weighted by how much it matters.
  for r in
    select * from public.mm_health_checks()
    where check_key like 'products_%'
  loop
    v_weight := case r.severity
      when 'critical' then 3.0
      when 'high'     then 2.0
      when 'medium'   then 1.0
      else 0.5 end;
    v_ratio := greatest(0, 1 - (r.affected::numeric / nullif(v_published, 0)));
    v_weighted := v_weighted + v_weight;
    v_score := v_score + (v_ratio * v_weight);

    v_factors := v_factors || jsonb_build_object(
      'key', r.check_key,
      'label', r.label,
      'severity', r.severity,
      'weight', v_weight,
      'affected', r.affected,
      'clean_ratio', round(v_ratio * 100, 1),
      'destination', r.destination);
  end loop;

  return jsonb_build_object(
    'score', case when v_weighted = 0 then null
                  else round((v_score / v_weighted) * 100, 1) end,
    'published_products', v_published,
    'total_products', v_total,
    'computed_at', now(),
    'method', 'weighted share of published products passing each catalogue check',
    'factors', v_factors);
end;
$$;


--
-- Name: mm_moderation(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_moderation(p_query jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_tab    text := coalesce(p_query->>'tab','queue');
  v_search text := nullif(btrim(coalesce(p_query->>'search','')),'');
  v_status text := nullif(p_query->>'status','');
  v_cat    text := nullif(p_query->>'category','');
  v_limit  integer := least(greatest(coalesce((p_query->>'limit')::int,50),1),200);
  v_offset integer := greatest(coalesce((p_query->>'offset')::int,0),0);
  v_policy record;
begin
  if not public.mm_is_operator() then
    return jsonb_build_object('ok', false, 'reason','not_permitted');
  end if;
  select * into v_policy from public.product_moderation_policy where id;

  return jsonb_build_object(
    'ok', true, 'tab', v_tab,

    -- The four metric cards, every one counted.
    'awaiting', (select count(*) from public.marketplace_products
                  where moderation_status in ('submitted','under_review','changes_requested')),
    'duplicates', (select count(*) from public.product_duplicate_candidates where status='open'),
    'reported_this_week', (select count(*) from public.product_reports
                            where created_at >= now() - interval '7 days'),
    'clean', (select count(*) from public.marketplace_products p
               where p.deleted_at is null and p.moderation_status='approved'
                 and not exists (select 1 from public.product_reports r
                                  where r.product_id=p.id
                                    and r.status in ('reported','under_review','action_required'))
                 and not exists (select 1 from public.product_duplicate_candidates d
                                  where (d.product_a=p.id or d.product_b=p.id) and d.status='open')),

    'by_status', coalesce((select jsonb_object_agg(moderation_status, n)
                             from (select moderation_status, count(*) n
                                     from public.marketplace_products group by moderation_status) t),
                          '{}'::jsonb),
    'total_catalog', (select count(*) from public.marketplace_products),
    'policy', to_jsonb(v_policy),

    -- Moderation analytics, from the audit log rather than a counter.
    'analytics', jsonb_build_object(
      'approved_30d', (select count(*) from public.marketplace_audit_logs
                        where action='product.approved' and created_at >= now()-interval '30 days'),
      'rejected_30d', (select count(*) from public.marketplace_audit_logs
                        where action='product.rejected' and created_at >= now()-interval '30 days'),
      'suspended_30d', (select count(*) from public.marketplace_audit_logs
                         where action='product.suspended' and created_at >= now()-interval '30 days'),
      'reports_open', (select count(*) from public.product_reports
                        where status in ('reported','under_review','action_required')),
      'reports_resolved_30d', (select count(*) from public.product_reports
                                where status in ('resolved','dismissed')
                                  and resolved_at >= now()-interval '30 days'),
      'merges_30d', (select count(*) from public.product_merge_operations
                      where performed_at >= now()-interval '30 days')),

    'total', (select count(*) from public.marketplace_products p
               where case v_tab
                 when 'queue'     then p.moderation_status in ('draft','submitted','under_review','changes_requested')
                 when 'archived'  then p.moderation_status = 'archived'
                 when 'deleted'   then p.moderation_status = 'soft_deleted'
                 when 'trash'     then p.moderation_status = 'trash'
                 else true end),

    'products', case when v_tab in ('duplicates','reports') then '[]'::jsonb else coalesce((
      select jsonb_agg(jsonb_build_object(
               'id', p.id, 'name', p.name, 'slug', p.slug,
               'status', p.moderation_status, 'content_status', p.content_status,
               'visible', p.visible, 'lock', p.moderation_lock,
               'seller_id', p.seller_id,
               'owner', (select s.display_name from public.marketplace_sellers s where s.id=p.seller_id),
               'owner_status', (select s.status from public.marketplace_sellers s where s.id=p.seller_id),
               'category', (select c.name from public.marketplace_categories c where c.id=p.category_id),
               'created_at', p.created_at, 'updated_at', p.updated_at,
               'approved_at', p.approved_at,
               'deleted_at', p.deleted_at, 'delete_reason', p.delete_reason,
               'purge_after', p.purge_after,
               'merged_into', p.merged_into,
               'reports', (select count(*) from public.product_reports r
                            where r.product_id=p.id
                              and r.status in ('reported','under_review','action_required')),
               'duplicate_of', (select count(*) from public.product_duplicate_candidates d
                                 where (d.product_a=p.id or d.product_b=p.id) and d.status='open'),
               'checks_failing', (public.mm_product_checks(p.id)->>'mandatory_failed')::int)
             order by p.updated_at desc)
        from (select * from public.marketplace_products p2
               where case v_tab
                 when 'queue'    then p2.moderation_status in ('draft','submitted','under_review','changes_requested')
                 when 'archived' then p2.moderation_status = 'archived'
                 when 'deleted'  then p2.moderation_status = 'soft_deleted'
                 when 'trash'    then p2.moderation_status = 'trash'
                 else true end
                 and (v_status is null or p2.moderation_status = v_status)
                 and (v_cat is null or p2.category_id = v_cat::uuid)
                 and (v_search is null
                      or p2.name ilike '%'||v_search||'%'
                      or p2.slug ilike '%'||v_search||'%'
                      or p2.id::text = v_search)
               order by p2.updated_at desc
               limit v_limit offset v_offset) p), '[]'::jsonb) end,

    'duplicate_pairs', case when v_tab <> 'duplicates' then '[]'::jsonb else coalesce((
      select jsonb_agg(jsonb_build_object(
               'id', d.id, 'match', d.match_percent, 'reasons', d.reasons,
               'status', d.status, 'scanned_at', d.scanned_at,
               'a', jsonb_build_object('id', a.id, 'name', a.name, 'status', a.moderation_status,
                      'owner', (select s.display_name from public.marketplace_sellers s where s.id=a.seller_id),
                      'orders', (select count(*) from public.marketplace_order_items i where i.product_id=a.id),
                      'reviews', (select count(*) from public.marketplace_reviews r where r.product_id=a.id),
                      'rating', a.rating, 'downloads', a.downloads, 'price', a.price_label),
               'b', jsonb_build_object('id', b.id, 'name', b.name, 'status', b.moderation_status,
                      'owner', (select s.display_name from public.marketplace_sellers s where s.id=b.seller_id),
                      'orders', (select count(*) from public.marketplace_order_items i where i.product_id=b.id),
                      'reviews', (select count(*) from public.marketplace_reviews r where r.product_id=b.id),
                      'rating', b.rating, 'downloads', b.downloads, 'price', b.price_label))
             order by d.match_percent desc)
        from (select * from public.product_duplicate_candidates
               where status='open' order by match_percent desc limit v_limit) d
        join public.marketplace_products a on a.id = d.product_a
        join public.marketplace_products b on b.id = d.product_b), '[]'::jsonb) end,

    'reports', case when v_tab <> 'reports' then '[]'::jsonb else coalesce((
      select jsonb_agg(jsonb_build_object(
               'id', r.id, 'report_no', r.report_no, 'reason', r.reason,
               'detail', r.detail, 'severity', r.severity, 'status', r.status,
               'created_at', r.created_at, 'resolution', r.resolution,
               'legal_reference', r.legal_reference,
               'product_id', r.product_id,
               'product', (select name from public.marketplace_products where id=r.product_id))
             order by r.created_at desc)
        from (select * from public.product_reports order by created_at desc limit v_limit) r),
      '[]'::jsonb) end);
end;
$$;


--
-- Name: mm_moderation_policy_set(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_moderation_policy_set(p_patch jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_before jsonb; v_after jsonb;
begin
  if not public.mm_is_operator() then
    return jsonb_build_object('ok', false, 'reason','not_permitted');
  end if;
  select to_jsonb(p) into v_before from public.product_moderation_policy p where p.id;

  update public.product_moderation_policy set
    recovery_days = coalesce((p_patch->>'recovery_days')::int, recovery_days),
    dual_approval = coalesce((p_patch->>'dual_approval')::boolean, dual_approval),
    auto_purge = coalesce((p_patch->>'auto_purge')::boolean, auto_purge),
    preserve_orders = coalesce((p_patch->>'preserve_orders')::boolean, preserve_orders),
    preserve_licenses = coalesce((p_patch->>'preserve_licenses')::boolean, preserve_licenses),
    preserve_reviews = coalesce((p_patch->>'preserve_reviews')::boolean, preserve_reviews),
    updated_by = auth.uid(), updated_at = now()
  where id returning to_jsonb(product_moderation_policy) into v_after;

  perform public.mm_audit('product.policy_changed','product_moderation_policy','policy',
                          v_before, v_after, nullif(p_patch->>'reason',''));
  return jsonb_build_object('ok', true, 'policy', v_after);
end;
$$;


--
-- Name: mm_new_license_key(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_new_license_key() RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp', 'extensions'
    AS $$
declare
  v_alphabet constant text := 'ABCDEFGHJKMNPQRSTUVWXYZ23456789'; -- no I, L, O, 0, 1
  v_bytes bytea;
  v_key   text := '';
  i       integer;
  v_full  text;
begin
  for attempt in 1..10 loop
    v_key := '';
    v_bytes := gen_random_bytes(16);
    for i in 0..15 loop
      v_key := v_key || substr(v_alphabet, (get_byte(v_bytes, i) % length(v_alphabet)) + 1, 1);
    end loop;

    v_full := 'SV-' || substr(v_key,1,4) || '-' || substr(v_key,5,4)
                    || '-' || substr(v_key,9,4) || '-' || substr(v_key,13,4);

    -- Collision-checked against every key already issued.
    if not exists (select 1 from public.marketplace_licenses where license_key = v_full) then
      return v_full;
    end if;
  end loop;

  raise exception 'could not generate a unique licence key after 10 attempts';
end;
$$;


--
-- Name: mm_notification_channels(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_notification_channels() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if not public.mm_is_operator() then
    return jsonb_build_object('ok', false, 'reason', 'not_permitted');
  end if;

  return jsonb_build_object(
    'ok', true,
    'channels', jsonb_build_array(
      jsonb_build_object(
        'channel', 'in_app', 'label', 'In-app bell', 'configured', true,
        'delivered', (select count(*) from public.user_notifications),
        'unread', (select count(*) from public.user_notifications
                    where not coalesce(is_read,false) and not coalesce(is_dismissed,false)),
        'last_delivery', (select max(created_at) from public.user_notifications),
        'note', 'Needs no external provider. This is the fallback every other channel falls back to.'),
      jsonb_build_object('channel','email','label','Email','configured',false,'delivered',0,
        'note','No SMTP, SendGrid, Resend or Postmark setting is present. Nothing can be delivered.'),
      jsonb_build_object('channel','whatsapp','label','WhatsApp','configured',false,'delivered',0,
        'note','No WhatsApp Business provider is configured. Templates also require approval before any send.'),
      jsonb_build_object('channel','sms','label','SMS','configured',false,'delivered',0,
        'note','SMS PROVIDER NOT CONNECTED.'),
      jsonb_build_object('channel','web_push','label','Web push','configured',false,'delivered',0,
        'note','No VAPID key pair is configured, and no device subscriptions are stored.'),
      jsonb_build_object('channel','telegram','label','Telegram','configured',false,'delivered',0,
        'note','No Bot API token is configured.')),
    'templates', (select count(*) from public.notification_templates),
    'rules',     (select count(*) from public.notification_rules));
end;
$$;


--
-- Name: mm_notification_read(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_notification_read(p_id uuid, p_dismiss boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_roles text[]; v_ok boolean;
begin
  if auth.uid() is null then
    return jsonb_build_object('ok', false, 'reason', 'not_signed_in');
  end if;
  select array_agg(role::text) into v_roles from public.user_roles where user_id = auth.uid();

  -- Only your own, or one addressed to a role you hold.
  select exists (
    select 1 from public.user_notifications n
     where n.id = p_id
       and (n.user_id = auth.uid()
            or (n.user_id is null and n.role_target && coalesce(v_roles, '{}'))))
    into v_ok;
  if not v_ok then
    return jsonb_build_object('ok', false, 'reason', 'not_yours');
  end if;

  update public.user_notifications
     set is_read = true, read_at = coalesce(read_at, now()),
         is_dismissed = case when p_dismiss then true else is_dismissed end,
         dismissed_at = case when p_dismiss then now() else dismissed_at end
   where id = p_id;

  return jsonb_build_object('ok', true);
end;
$$;


--
-- Name: mm_notifications(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_notifications(p_limit integer DEFAULT 25) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_roles text[];
begin
  if auth.uid() is null then
    return jsonb_build_object('ok', false, 'reason', 'not_signed_in');
  end if;

  select array_agg(role::text) into v_roles
    from public.user_roles where user_id = auth.uid();

  return jsonb_build_object(
    'ok', true,
    'unread', (
      select count(*) from public.user_notifications n
       where not coalesce(n.is_read, false) and not coalesce(n.is_dismissed, false)
         and (n.user_id = auth.uid()
              or (n.user_id is null and n.role_target && coalesce(v_roles, '{}')))),
    'notifications', coalesce((
      select jsonb_agg(jsonb_build_object(
               'id', n.id, 'severity', n.type, 'message', n.message,
               'event', n.event_type, 'action_url', n.action_url,
               'action_label', n.action_label, 'buzzer', n.is_buzzer,
               'read', n.is_read, 'created_at', n.created_at)
             order by n.created_at desc)
        from (select * from public.user_notifications n2
               where not coalesce(n2.is_dismissed, false)
                 and (n2.user_id = auth.uid()
                      or (n2.user_id is null and n2.role_target && coalesce(v_roles, '{}')))
               order by n2.created_at desc
               limit least(greatest(p_limit, 1), 100)) n), '[]'::jsonb));
end;
$$;


--
-- Name: mm_notify(text, text, text, uuid, text[], text, text, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_notify(p_event text, p_title text, p_message text, p_user uuid DEFAULT NULL::uuid, p_role_target text[] DEFAULT NULL::text[], p_action_url text DEFAULT NULL::text, p_action_label text DEFAULT NULL::text, p_dedupe_minutes integer DEFAULT 60, p_severity text DEFAULT 'info'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_id uuid;
  v_targets uuid[];
  v_target uuid;
  v_sent integer := 0;
  v_skipped integer := 0;
begin
  if coalesce(btrim(p_title), '') = '' then
    return jsonb_build_object('ok', false, 'reason', 'title_required');
  end if;
  if p_user is null and p_role_target is null then
    return jsonb_build_object('ok', false, 'reason', 'no_recipient');
  end if;

  -- user_id is NOT NULL on this table, so a role broadcast is fanned out to
  -- the people who hold the role rather than stored as one row with no owner.
  -- That is the better shape anyway: read and dismissed are per person, so one
  -- operator clearing an alert does not clear it for everybody else.
  if p_user is not null then
    v_targets := array[p_user];
  else
    select coalesce(array_agg(distinct ur.user_id), '{}')
      into v_targets
      from public.user_roles ur
     where ur.role::text = any(p_role_target);
  end if;

  if coalesce(array_length(v_targets, 1), 0) = 0 then
    return jsonb_build_object('ok', true, 'delivered', 0,
                              'reason', 'no_recipient_holds_that_role');
  end if;

  foreach v_target in array v_targets loop
    -- Deduplicated per person, so a demo that stays offline does not produce
    -- ninety-six identical rows a day for each operator.
    if exists (
      select 1 from public.user_notifications n
       where n.event_type = p_event
         and n.user_id = v_target
         and n.created_at > now() - make_interval(mins => greatest(p_dedupe_minutes, 0))
         and not coalesce(n.is_dismissed, false))
    then
      v_skipped := v_skipped + 1;
      continue;
    end if;

    insert into public.user_notifications
      (user_id, type, message, event_type, action_label, action_url,
       is_buzzer, is_read, is_dismissed, role_target)
    values (v_target,
            case when p_severity in ('info','success','warning','danger','priority')
                 then p_severity else 'info' end,
            case when coalesce(btrim(p_message), '') = '' then p_title
                 else p_title || ' - ' || p_message end,
            p_event, p_action_label, p_action_url,
            -- A buzzer is for the things somebody has to act on.
            p_event in ('demo.offline', 'seo.page_broken', 'license.issue_failed'),
            false, false, p_role_target)
    returning id into v_id;
    v_sent := v_sent + 1;
  end loop;

  return jsonb_build_object('ok', true, 'delivered', v_sent,
                            'deduplicated', v_skipped > 0 and v_sent = 0,
                            'suppressed', v_skipped, 'id', v_id);
end;
$$;


--
-- Name: mm_notify_demo_alert(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_notify_demo_alert() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if not coalesce(new.is_resolved, false) then
    perform public.mm_notify(
      'demo.offline',
      case new.severity when 'critical' then 'A demo is unreachable' else 'Demo warning' end,
      new.message,
      null, array['admin','boss','founder','super_admin'],
      '/marketplace-manager', 'Open Demo URL Manager',
      360,
      case new.severity when 'critical' then 'danger' else 'warning' end);
  end if;
  return new;
end;
$$;


--
-- Name: mm_notify_license_issued(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_notify_license_issued() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_product text;
begin
  select name into v_product from public.marketplace_products where id = new.product_id;
  perform public.mm_notify(
    'license.issued',
    'Your licence is ready',
    format('Licence %s for %s is active.', new.license_key, coalesce(v_product, 'your purchase')),
    new.buyer_id, null, '/account/purchases', 'View purchases', 5, 'success');
  return new;
end;
$$;


--
-- Name: mm_offer_is_live(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_offer_is_live(p_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select coalesce((
    select o.status = 'active'
       and coalesce(o.is_seed, false) = false
       and (o.start_date is null or o.start_date <= current_date)
       and (o.end_date   is null or o.end_date   >= current_date)
      from public.marketing_offers o where o.id = p_id), false);
$$;


--
-- Name: mm_offer_save(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_offer_save(p_patch jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_id uuid := nullif(p_patch->>'id','')::uuid; v_before jsonb; v_after jsonb;
begin
  if not public.mm_is_operator() then
    return jsonb_build_object('ok', false, 'reason', 'not_permitted');
  end if;

  if v_id is not null then
    select to_jsonb(o) into v_before from public.marketing_offers o where o.id = v_id;
    if v_before is null then
      return jsonb_build_object('ok', false, 'reason', 'unknown_offer');
    end if;
  end if;

  if v_id is null then
    insert into public.marketing_offers
      (title, festival, offer_type, discount_percent, code, start_date, end_date,
       status, regions, is_seed, priority, landing_url, updated_by, updated_at)
    values (
      coalesce(nullif(btrim(p_patch->>'title'),''), 'Untitled offer'),
      nullif(p_patch->>'festival',''),
      coalesce(nullif(p_patch->>'offer_type',''), 'discount'),
      nullif(p_patch->>'discount_percent','')::numeric,
      nullif(upper(btrim(coalesce(p_patch->>'code',''))), ''),
      -- start_date is NOT NULL; an offer created without one starts today.
      coalesce(nullif(p_patch->>'start_date','')::date, current_date),
      -- end_date is NOT NULL. An offer created without one runs 30 days;
      -- a promotion that never expires is the wrong default.
      coalesce(nullif(p_patch->>'end_date','')::date, current_date + 30),
      -- A new offer is always a draft. Creating one must not put a promotion
      -- in front of customers before anybody has looked at it.
      'draft',
      -- regions is text[] and NOT NULL, so a JSON array in the patch becomes
      -- one and anything else becomes an empty array: targeted nowhere in
      -- particular rather than unknown.
      case when jsonb_typeof(p_patch->'regions') = 'array'
           then array(select jsonb_array_elements_text(p_patch->'regions'))
           else '{}'::text[] end,
      -- Anything created here is real, never seed.
      false,
      coalesce((p_patch->>'priority')::int, 50),
      nullif(p_patch->>'landing_url',''),
      auth.uid(), now())
    returning to_jsonb(marketing_offers) into v_after;
  else
    update public.marketing_offers o set
      title            = coalesce(nullif(btrim(p_patch->>'title'),''), o.title),
      festival         = case when p_patch ? 'festival' then nullif(p_patch->>'festival','') else o.festival end,
      offer_type       = coalesce(nullif(p_patch->>'offer_type',''), o.offer_type),
      discount_percent = coalesce(nullif(p_patch->>'discount_percent','')::numeric, o.discount_percent),
      code             = case when p_patch ? 'code'
                              then nullif(upper(btrim(p_patch->>'code')),'') else o.code end,
      start_date       = case when p_patch ? 'start_date' then nullif(p_patch->>'start_date','')::date else o.start_date end,
      end_date         = case when p_patch ? 'end_date' then nullif(p_patch->>'end_date','')::date else o.end_date end,
      regions          = case when jsonb_typeof(p_patch->'regions') = 'array'
                              then array(select jsonb_array_elements_text(p_patch->'regions'))
                              else o.regions end,
      priority         = coalesce((p_patch->>'priority')::int, o.priority),
      landing_url      = case when p_patch ? 'landing_url' then nullif(p_patch->>'landing_url','') else o.landing_url end,
      updated_by = auth.uid(), updated_at = now()
    where o.id = v_id
    returning to_jsonb(o) into v_after;
  end if;

  perform public.mm_audit(
    case when v_id is null then 'offer.created' else 'offer.updated' end,
    'marketplace_offer', coalesce(v_id::text, v_after->>'id'), v_before, v_after, null);

  return jsonb_build_object('ok', true, 'offer', v_after);
end;
$$;


--
-- Name: mm_offer_transition(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_offer_transition(p_id uuid, p_to text, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare o record; v_before jsonb; v_after jsonb; v_problems text[] := '{}';
begin
  if not public.mm_is_operator() then
    return jsonb_build_object('ok', false, 'reason', 'not_permitted');
  end if;
  if p_to not in ('draft','scheduled','active','paused','expired','archived') then
    return jsonb_build_object('ok', false, 'reason', 'unknown_status');
  end if;

  select * into o from public.marketing_offers where id = p_id;
  if not found then
    return jsonb_build_object('ok', false, 'reason', 'unknown_offer');
  end if;
  v_before := to_jsonb(o);

  -- Going live is the transition that reaches customers, so it is the one
  -- that gets validated.
  if p_to = 'active' then
    if coalesce(o.is_seed, false) then
      v_problems := v_problems || 'This is seed data and cannot be shown to customers.'::text;
    end if;
    if coalesce(btrim(o.title), '') = '' then
      v_problems := v_problems || 'The offer needs a title.'::text;
    end if;
    if o.discount_percent is null or o.discount_percent <= 0 then
      v_problems := v_problems || 'The discount must be greater than zero.'::text;
    end if;
    if o.discount_percent > 100 then
      v_problems := v_problems || 'A percentage discount cannot exceed 100.'::text;
    end if;
    if o.end_date is not null and o.end_date < current_date then
      v_problems := v_problems || 'The offer window has already closed.'::text;
    end if;
    -- Two live offers sharing a code would make the code ambiguous at checkout.
    if o.code is not null and exists (
      select 1 from public.marketing_offers x
       where x.id <> o.id and x.code = o.code and x.status = 'active')
    then
      v_problems := v_problems || 'Another live offer already uses that code.'::text;
    end if;

    if array_length(v_problems, 1) > 0 then
      return jsonb_build_object('ok', false, 'reason', 'validation_failed',
                                'problems', to_jsonb(v_problems));
    end if;
  end if;

  update public.marketing_offers set
    status = p_to,
    published_at = case when p_to = 'active' then coalesce(published_at, now()) else published_at end,
    published_by = case when p_to = 'active' then auth.uid() else published_by end,
    updated_by = auth.uid(), updated_at = now()
  where id = p_id
  returning to_jsonb(marketing_offers) into v_after;

  perform public.mm_audit('offer.' || p_to, 'marketplace_offer', p_id::text,
                          v_before, v_after, p_reason);

  return jsonb_build_object('ok', true, 'offer', v_after,
                            'live_now', public.mm_offer_is_live(p_id));
end;
$$;


--
-- Name: mm_offers(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_offers(p_query jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_status text := nullif(p_query->>'status','');
  v_search text := nullif(btrim(coalesce(p_query->>'search','')), '');
  v_limit  integer := least(greatest(coalesce((p_query->>'limit')::int, 50), 1), 200);
begin
  if not public.mm_is_operator() then
    return jsonb_build_object('ok', false, 'reason', 'not_permitted');
  end if;

  return jsonb_build_object(
    'ok', true,
    -- Seed and real are counted apart, always.
    'total',      (select count(*) from public.marketing_offers),
    'seed',       (select count(*) from public.marketing_offers where coalesce(is_seed,false)),
    'real',       (select count(*) from public.marketing_offers where not coalesce(is_seed,false)),
    'live_now',   (select count(*) from public.marketing_offers o where public.mm_offer_is_live(o.id)),
    'by_status', coalesce((
      select jsonb_agg(jsonb_build_object('status', status, 'count', n) order by n desc)
        from (select status, count(*) n from public.marketing_offers group by status) t), '[]'::jsonb),
    -- Real redemptions, counted from the table that records them. The
    -- redemptions column on marketing_offers is a seed value and is reported
    -- separately, never as a measurement.
    'real_redemptions', (select count(*) from public.marketplace_coupon_redemptions),
    'coupons',          (select count(*) from public.marketplace_coupons),
    'offers', coalesce((
      select jsonb_agg(to_jsonb(o) || jsonb_build_object(
               'live_now', public.mm_offer_is_live(o.id),
               'is_seed', coalesce(o.is_seed, false))
             order by o.created_at desc)
        from (select * from public.marketing_offers o2
               where (v_status is null or o2.status = v_status)
                 and (v_search is null or o2.title ilike '%'||v_search||'%'
                      or coalesce(o2.code,'') ilike '%'||v_search||'%')
               order by created_at desc limit v_limit) o), '[]'::jsonb));
end;
$$;


--
-- Name: mm_order_detail(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_order_detail(p_order_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare o record; v_timeline jsonb;
begin
  if not public.mm_is_operator() then
    return jsonb_build_object('ok', false, 'reason', 'not_permitted');
  end if;

  select * into o from public.marketplace_orders where id = p_order_id;
  if o.id is null then
    return jsonb_build_object('ok', false, 'reason', 'unknown_order');
  end if;

  select coalesce(jsonb_agg(t order by t->>'at'), '[]'::jsonb) into v_timeline from (
    select jsonb_build_object('at', o.created_at, 'stage', 'Order created',
      'detail', o.order_number, 'source', 'marketplace_orders') t
    union all
    select jsonb_build_object('at', h.created_at, 'stage', 'Status changed',
      'detail', coalesce(h.from_status::text,'—') || ' to ' || coalesce(h.to_status::text,'—'),
      'source', 'marketplace_order_status_history')
    from public.marketplace_order_status_history h where h.order_id = o.id
    union all
    select jsonb_build_object('at', fi.issue_date::timestamptz, 'stage', 'Invoice issued',
      'detail', fi.invoice_no, 'source', 'finance_invoices')
    from public.finance_invoices fi
    where fi.line_items::text like '%' || o.id::text || '%'
    union all
    select jsonb_build_object('at', r.created_at, 'stage', 'Refund ' || r.status,
      'detail', r.amount::text || ' ' || coalesce(r.currency,''), 'source', 'marketplace_order_refunds')
    from public.marketplace_order_refunds r where r.order_id = o.id
    union all
    select jsonb_build_object('at', d.opened_at, 'stage', 'Dispute ' || d.status,
      'detail', d.dispute_no || ' — ' || d.reason, 'source', 'marketplace_disputes')
    from public.marketplace_disputes d where d.order_id = o.id
  ) x;

  return jsonb_build_object(
    'ok', true,
    'order', jsonb_build_object(
      'id', o.id, 'order_number', o.order_number, 'status', o.status::text,
      'payment_status', coalesce(o.payu_status, o.status::text),
      'payment_gateway', o.payment_gateway,
      'payment_reference', coalesce(o.payu_txn_id, o.txnid),
      'currency', o.currency::text, 'subtotal', o.subtotal, 'tax_total', o.tax_total,
      'total', o.total, 'amount_usd', o.amount_usd, 'amount_inr', o.amount_inr,
      'fx_rate', o.fx_rate, 'created_at', o.created_at, 'updated_at', o.updated_at),
    'customer', jsonb_build_object('id', o.buyer_id,
      'email', (select u.email from auth.users u where u.id = o.buyer_id)),
    'items', (select coalesce(jsonb_agg(jsonb_build_object(
                'product_id', i.product_id, 'name', i.product_name,
                'seller_id', i.seller_id, 'quantity', i.quantity,
                'unit_amount', i.unit_amount, 'line_total', i.line_total,
                -- Section 19: the product may since have been unpublished. The
                -- line keeps the name it was bought under either way.
                'still_published', exists (select 1 from public.marketplace_products p
                                           where p.id = i.product_id and p.visible
                                             and p.content_status='published'))), '[]'::jsonb)
              from public.marketplace_order_items i where i.order_id = o.id),
    'invoice', (select jsonb_build_object('invoice_no', fi.invoice_no, 'status', fi.status,
                  'total', fi.total, 'issue_date', fi.issue_date, 'doc_type', fi.doc_type)
                from public.finance_invoices fi
                where fi.line_items::text like '%' || o.id::text || '%' limit 1),
    'refunds', (select coalesce(jsonb_agg(jsonb_build_object(
                  'id', r.id, 'amount', r.amount, 'status', r.status, 'reason', r.reason,
                  'provider', r.provider, 'created_at', r.created_at,
                  'processed_at', r.processed_at)), '[]'::jsonb)
                from public.marketplace_order_refunds r where r.order_id = o.id),
    'disputes', (select coalesce(jsonb_agg(jsonb_build_object(
                   'id', d.id, 'dispute_no', d.dispute_no, 'status', d.status,
                   'reason', d.reason, 'amount', d.amount, 'opened_at', d.opened_at,
                   'resolution', d.resolution)), '[]'::jsonb)
                 from public.marketplace_disputes d where d.order_id = o.id),
    'timeline', v_timeline);
end $$;


--
-- Name: mm_order_docs(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_order_docs(p_tab text, p_limit integer DEFAULT 50) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v jsonb; v_total bigint;
begin
  if not public.mm_is_operator() then
    return jsonb_build_object('ok', false, 'reason', 'not_permitted');
  end if;

  if p_tab in ('invoices','proforma','credit_notes') then
    -- All three are finance_invoices rows distinguished by doc_type. That
    -- column already existed and already carried credit_note rows, so this
    -- reuses it rather than adding tables that would only differ by a label.
    select count(*) into v_total from public.finance_invoices fi
     where fi.doc_type = case p_tab when 'invoices' then 'invoice'
                                    when 'proforma' then 'proforma'
                                    else 'credit_note' end;
    select coalesce(jsonb_agg(r order by r->>'issue_date' desc), '[]'::jsonb) into v
    from (
      select jsonb_build_object(
        'id', fi.id, 'number', fi.invoice_no, 'doc_type', fi.doc_type,
        'client', fi.client_name, 'subtotal', fi.subtotal, 'tax', fi.tax_amount,
        'total', fi.total, 'status', fi.status, 'issue_date', fi.issue_date,
        'due_date', fi.due_date, 'paid_at', fi.paid_at,
        -- Section 16: a credit note must be traceable to its transaction.
        'order_id', fi.line_items #>> '{meta,order_id}',
        'linked_order', (select o.order_number from public.marketplace_orders o
                         where o.id::text = fi.line_items #>> '{meta,order_id}')) r
      from public.finance_invoices fi
      where fi.doc_type = case p_tab when 'invoices' then 'invoice'
                                     when 'proforma' then 'proforma'
                                     else 'credit_note' end
      order by fi.issue_date desc nulls last
      limit p_limit
    ) x;

  elsif p_tab = 'refunds' then
    select count(*) into v_total from public.marketplace_order_refunds;
    select coalesce(jsonb_agg(r order by r->>'created_at' desc), '[]'::jsonb) into v
    from (
      select jsonb_build_object(
        'id', rf.id, 'order_id', rf.order_id,
        'order_number', (select o.order_number from public.marketplace_orders o where o.id = rf.order_id),
        'amount', rf.amount, 'currency', rf.currency, 'status', rf.status,
        'reason', rf.reason, 'provider', rf.provider,
        'provider_refund_id', rf.provider_refund_id,
        'created_at', rf.created_at, 'processed_at', rf.processed_at) r
      from public.marketplace_order_refunds rf
      order by rf.created_at desc limit p_limit
    ) x;

  elsif p_tab = 'disputes' then
    select count(*) into v_total from public.marketplace_disputes;
    select coalesce(jsonb_agg(r order by r->>'opened_at' desc), '[]'::jsonb) into v
    from (
      select jsonb_build_object(
        'id', d.id, 'dispute_no', d.dispute_no, 'order_id', d.order_id,
        'order_number', (select o.order_number from public.marketplace_orders o where o.id = d.order_id),
        'amount', d.amount, 'currency', d.currency, 'status', d.status,
        'reason', d.reason, 'evidence_count', jsonb_array_length(d.evidence),
        'assigned_to', d.assigned_to, 'resolution', d.resolution,
        'opened_at', d.opened_at, 'resolved_at', d.resolved_at) r
      from public.marketplace_disputes d
      order by d.opened_at desc limit p_limit
    ) x;
  else
    return jsonb_build_object('ok', false, 'reason', 'unknown_tab');
  end if;

  return jsonb_build_object('ok', true, 'tab', p_tab, 'total', v_total,
                            'rows', coalesce(v, '[]'::jsonb));
end $$;


--
-- Name: mm_order_paid_issue(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_order_paid_issue() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if new.status::text = 'paid'
     and (tg_op = 'INSERT' or coalesce(old.status::text, '') <> 'paid') then
    -- A failure here must not roll back the payment itself. The order being
    -- paid is the fact; the licence can be reissued.
    begin
      perform public.mm_issue_for_order(new.id);
    exception when others then
      perform public.mm_audit(
        'license.issue_failed', 'marketplace_order', new.id::text, null,
        jsonb_build_object('error', sqlerrm), 'licence issuance failed on payment');
    end;
  end if;
  return new;
end;
$$;


--
-- Name: mm_orders_list(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_orders_list(p_query jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_search  text := nullif(trim(coalesce(p_query->>'search','')), '');
  v_status  text := nullif(p_query->>'status','');
  v_pay     text := nullif(p_query->>'payment_status','');
  v_gateway text := nullif(p_query->>'gateway','');
  v_currency text := nullif(p_query->>'currency','');
  v_from    timestamptz := nullif(p_query->>'from','')::timestamptz;
  v_to      timestamptz := nullif(p_query->>'to','')::timestamptz;
  v_min     numeric := nullif(p_query->>'min_amount','')::numeric;
  v_max     numeric := nullif(p_query->>'max_amount','')::numeric;
  v_product uuid := nullif(p_query->>'product_id','')::uuid;
  v_sort    text := coalesce(p_query->>'sort','newest');
  v_limit   int  := least(coalesce((p_query->>'limit')::int, 25), 100);
  v_offset  int  := greatest(coalesce((p_query->>'offset')::int, 0), 0);
  v_total   bigint;
  v_rows    jsonb;
begin
  if not public.mm_is_operator() then
    return jsonb_build_object('ok', false, 'reason', 'not_permitted');
  end if;

  with scoped as (
    select o.id
    from public.marketplace_orders o
    where (v_status is null or o.status::text = v_status)
      and (v_currency is null or o.currency::text = v_currency)
      and (v_gateway is null or coalesce(o.payment_gateway,'') = v_gateway)
      and (v_from is null or o.created_at >= v_from)
      and (v_to   is null or o.created_at <  v_to)
      and (v_min  is null or o.total >= v_min)
      and (v_max  is null or o.total <= v_max)
      and (v_pay  is null or coalesce(o.payu_status, o.status::text) = v_pay)
      and (v_product is null or exists (
             select 1 from public.marketplace_order_items i
             where i.order_id = o.id and i.product_id = v_product))
      -- Section 3: order number, customer email, product name and the payment
      -- reference are all searchable, in the database rather than the browser.
      and (v_search is null
           or o.order_number ilike '%' || v_search || '%'
           or coalesce(o.txnid,'') ilike '%' || v_search || '%'
           or coalesce(o.payu_txn_id,'') ilike '%' || v_search || '%'
           or exists (select 1 from auth.users u
                      where u.id = o.buyer_id and u.email ilike '%' || v_search || '%')
           or exists (select 1 from public.marketplace_order_items i
                      where i.order_id = o.id
                        and coalesce(i.product_name,'') ilike '%' || v_search || '%'))
  )
  select count(*) into v_total from scoped;

  select coalesce(jsonb_agg(r), '[]'::jsonb) into v_rows from (
    select jsonb_build_object(
      'id', o.id,
      'order_number', o.order_number,
      'status', o.status::text,
      'payment_status', coalesce(o.payu_status, o.status::text),
      'payment_gateway', o.payment_gateway,
      'payment_reference', coalesce(o.payu_txn_id, o.txnid),
      'currency', o.currency::text,
      'subtotal', o.subtotal, 'tax_total', o.tax_total,
      'total', o.total,
      'amount_usd', o.amount_usd, 'amount_inr', o.amount_inr, 'fx_rate', o.fx_rate,
      'created_at', o.created_at, 'updated_at', o.updated_at,
      'customer', jsonb_build_object(
        'id', o.buyer_id,
        'email', (select u.email from auth.users u where u.id = o.buyer_id)),
      'items', (select coalesce(jsonb_agg(jsonb_build_object(
                   'product_id', i.product_id, 'name', i.product_name,
                   'seller_id', i.seller_id, 'quantity', i.quantity,
                   'unit_amount', i.unit_amount, 'line_total', i.line_total)), '[]'::jsonb)
                from public.marketplace_order_items i where i.order_id = o.id),
      -- Section 19: an order keeps its own snapshot of what was bought, so an
      -- unpublished product cannot rewrite history.
      'item_count', (select count(*) from public.marketplace_order_items i where i.order_id = o.id),
      'refund_status', (select r2.status from public.marketplace_order_refunds r2
                        where r2.order_id = o.id order by r2.created_at desc limit 1),
      'dispute_status', (select d.status from public.marketplace_disputes d
                         where d.order_id = o.id order by d.opened_at desc limit 1),
      'invoice_no', (select fi.invoice_no from public.finance_invoices fi
                     where fi.line_items::text like '%' || o.id::text || '%' limit 1)
    ) r
    from public.marketplace_orders o
    where (v_status is null or o.status::text = v_status)
      and (v_currency is null or o.currency::text = v_currency)
      and (v_gateway is null or coalesce(o.payment_gateway,'') = v_gateway)
      and (v_from is null or o.created_at >= v_from)
      and (v_to   is null or o.created_at <  v_to)
      and (v_min  is null or o.total >= v_min)
      and (v_max  is null or o.total <= v_max)
      and (v_pay  is null or coalesce(o.payu_status, o.status::text) = v_pay)
      and (v_product is null or exists (
             select 1 from public.marketplace_order_items i
             where i.order_id = o.id and i.product_id = v_product))
      and (v_search is null
           or o.order_number ilike '%' || v_search || '%'
           or coalesce(o.txnid,'') ilike '%' || v_search || '%'
           or coalesce(o.payu_txn_id,'') ilike '%' || v_search || '%'
           or exists (select 1 from auth.users u
                      where u.id = o.buyer_id and u.email ilike '%' || v_search || '%')
           or exists (select 1 from public.marketplace_order_items i
                      where i.order_id = o.id
                        and coalesce(i.product_name,'') ilike '%' || v_search || '%'))
    order by
      case when v_sort = 'newest'      then o.created_at end desc nulls last,
      case when v_sort = 'oldest'      then o.created_at end asc  nulls last,
      case when v_sort = 'amount_high' then o.total end desc nulls last,
      case when v_sort = 'amount_low'  then o.total end asc  nulls last,
      case when v_sort = 'status'      then o.status::text end asc nulls last,
      o.created_at desc
    limit v_limit offset v_offset
  ) x;

  return jsonb_build_object(
    'ok', true, 'total', v_total, 'limit', v_limit, 'offset', v_offset,
    'orders', v_rows);
end $$;


--
-- Name: mm_product_checks(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_product_checks(p_product uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_p record; v_seller record; v_checks jsonb;
begin
  select * into v_p from public.marketplace_products where id = p_product;
  if not found then
    return jsonb_build_object('ok', false, 'reason','unknown_product','blocking', true);
  end if;
  select * into v_seller from public.marketplace_sellers where id = v_p.seller_id;

  v_checks := jsonb_build_array(
    jsonb_build_object('key','name','label','Product name','mandatory',true,
      'passed', coalesce(btrim(v_p.name),'') <> '', 'detail', coalesce(v_p.name,'missing')),
    jsonb_build_object('key','description','label','Description','mandatory',true,
      'passed', length(coalesce(btrim(v_p.description),'')) >= 40,
      'detail', case when coalesce(btrim(v_p.description),'')='' then 'missing'
                     else format('%s characters', length(btrim(v_p.description))) end),
    jsonb_build_object('key','category','label','Category','mandatory',true,
      'passed', v_p.category_id is not null,
      'detail', coalesce((select name from public.marketplace_categories c where c.id=v_p.category_id),'no category')),
    jsonb_build_object('key','pricing','label','Price','mandatory',true,
      'passed', coalesce(btrim(v_p.price_label),'') <> '',
      'detail', coalesce(nullif(btrim(v_p.price_label),''),'missing')),
    jsonb_build_object('key','license','label','Licence','mandatory',true,
      'passed', coalesce(btrim(v_p.license),'') <> '',
      'detail', coalesce(nullif(btrim(v_p.license),''),'missing')),
    jsonb_build_object('key','demo','label','Live demo','mandatory',false,
      'passed', coalesce(btrim(v_p.demo_url),'') <> '',
      'detail', coalesce(nullif(btrim(v_p.demo_url),''),'no demo URL')),
    jsonb_build_object('key','media','label','Imagery','mandatory',false,
      'passed', coalesce(btrim(v_p.thumbnail_url),'') <> '' or coalesce(btrim(v_p.cover_image),'') <> '',
      'detail', case when coalesce(btrim(v_p.thumbnail_url),'') <> ''
                       or coalesce(btrim(v_p.cover_image),'') <> '' then 'present'
                     else 'no thumbnail or cover image' end),
    -- Author Manager and Vendor Manager decide this, not moderation.
    jsonb_build_object('key','owner','label','Owner is in good standing','mandatory', v_seller.id is not null,
      'passed', v_seller.id is null or v_seller.status = 'approved',
      'detail', case when v_seller.id is null then 'first-party product, no seller'
                     else format('%s is %s', v_seller.display_name, v_seller.status) end),
    -- Legal Manager's record, read only.
    jsonb_build_object('key','legal','label','No blocking legal record','mandatory',true,
      'passed', not exists (select 1 from public.legal_violations v
                             where v.violator_id = p_product::text
                               and coalesce(v.status,'open') not in ('resolved','dismissed')),
      'detail', case when exists (select 1 from public.legal_violations v
                                   where v.violator_id = p_product::text
                                     and coalesce(v.status,'open') not in ('resolved','dismissed'))
                     then 'Legal Manager has an unresolved violation against this product.'
                     else 'No unresolved violation in Legal Manager.' end),
    -- An unresolved serious report stops publication until somebody closes it.
    jsonb_build_object('key','reports','label','No unresolved serious report','mandatory',true,
      'passed', not exists (select 1 from public.product_reports r
                             where r.product_id = p_product
                               and r.status in ('reported','under_review','action_required')
                               and r.severity in ('high','critical')),
      'detail', format('%s open report(s), %s of them serious',
        (select count(*) from public.product_reports r where r.product_id=p_product
          and r.status in ('reported','under_review','action_required')),
        (select count(*) from public.product_reports r where r.product_id=p_product
          and r.status in ('reported','under_review','action_required')
          and r.severity in ('high','critical')))),
    jsonb_build_object('key','not_merged','label','Not merged into another product','mandatory',true,
      'passed', v_p.merged_into is null,
      'detail', case when v_p.merged_into is null then 'standalone'
                     else 'this listing was merged into another and should not be republished' end));

  return jsonb_build_object('ok', true, 'checks', v_checks,
    'mandatory_failed', (select count(*) from jsonb_array_elements(v_checks) c
                          where (c->>'mandatory')::boolean and not (c->>'passed')::boolean),
    'blocking', (select count(*) from jsonb_array_elements(v_checks) c
                  where (c->>'mandatory')::boolean and not (c->>'passed')::boolean) > 0);
end;
$$;


--
-- Name: mm_product_clone(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_product_clone(p_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_new uuid; v_slug text; v_p record;
begin
  if not public.mm_is_operator() then
    return jsonb_build_object('ok', false, 'reason', 'not_permitted');
  end if;
  select * into v_p from public.marketplace_products where id = p_id;
  if not found then
    return jsonb_build_object('ok', false, 'reason', 'unknown_product');
  end if;

  v_slug := left(v_p.slug, 60) || '-copy-' || substr(md5(random()::text), 1, 6);

  insert into public.marketplace_products (
    slug, name, industry_label, icon, price_label, price_period,
    badge, category_id, sort_order, description, thumbnail_url, cover_image,
    tags, tech_stack, features, software_type, deployment, license, version,
    technology, frontend, backend, database, authentication, api, mobile, pwa,
    cloud, offline, roles, languages, currency, tax, reports, dashboard,
    analytics, ai, whatsapp, email, sms, payment_gateway, integrations, modules,
    benefits, target_audience, search_keywords, logo, favicon, subcategory,
    seller_id,
    -- A clone starts as an unapproved draft. It has never been reviewed.
    moderation_status, content_status, visible,
    -- And it carries none of the original's standing.
    rating, downloads, is_featured, is_trending, is_new_release, is_best_seller)
  select
    v_slug, v_p.name || ' (copy)', industry_label, icon, price_label, price_period,
    badge, category_id, sort_order, description, thumbnail_url, cover_image,
    tags, tech_stack, features, software_type, deployment, license, version,
    technology, frontend, backend, database, authentication, api, mobile, pwa,
    cloud, offline, roles, languages, currency, tax, reports, dashboard,
    analytics, ai, whatsapp, email, sms, payment_gateway, integrations, modules,
    benefits, target_audience, search_keywords, logo, favicon, subcategory,
    seller_id,
    'draft', 'draft', false,
    0, 0, false, false, false, false
  from public.marketplace_products where id = p_id
  returning id into v_new;

  perform public.mm_audit('product.cloned','marketplace_product', v_new::text, null,
    jsonb_build_object('cloned_from', p_id, 'new_product', v_new, 'slug', v_slug),
    'Cloned as an unreviewed draft. No orders, licences, reviews or history were copied.');

  return jsonb_build_object('ok', true, 'product_id', v_new, 'slug', v_slug,
    'note','A clone starts as an unapproved draft with no rating, downloads, orders, licences, reviews or moderation history.');
end;
$$;


--
-- Name: mm_product_content(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_product_content(p_slug text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select coalesce(jsonb_object_agg(i.content_type, jsonb_build_object(
           'content', i.content,
           'items', i.content_json,
           'provenance', i.provenance,
           'human_edited', i.human_edited,
           'published_at', i.published_at)), '{}'::jsonb)
    from public.ai_content_items i
    join public.marketplace_products p on p.id = i.product_id
   where p.slug = p_slug
     and p.visible
     and p.deleted_at is null
     and i.status = 'PUBLISHED'
     and i.language = 'en';
$$;


--
-- Name: mm_product_is_public(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_product_is_public(p_product uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select exists (
    select 1 from public.marketplace_products p
     where p.id = p_product
       and p.visible
       and p.deleted_at is null);
$$;


--
-- Name: mm_product_merge(uuid, uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_product_merge(p_canonical uuid, p_duplicate uuid, p_reason text, p_candidate uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_c record; v_d record; v_moved jsonb; v_op jsonb;
  v_items integer; v_reviews integer; v_licences integer; v_commissions integer;
begin
  if not public.mm_is_operator() then
    return jsonb_build_object('ok', false, 'reason', 'not_permitted');
  end if;
  if coalesce(btrim(p_reason),'') = '' then
    return jsonb_build_object('ok', false, 'reason', 'reason_required',
      'message','A merge changes which product owns real orders and reviews. Say why.');
  end if;
  if p_canonical = p_duplicate then
    return jsonb_build_object('ok', false, 'reason', 'same_product');
  end if;

  select * into v_c from public.marketplace_products where id = p_canonical for update;
  if not found then return jsonb_build_object('ok', false, 'reason','unknown_canonical'); end if;
  select * into v_d from public.marketplace_products where id = p_duplicate for update;
  if not found then return jsonb_build_object('ok', false, 'reason','unknown_duplicate'); end if;

  if v_d.merged_into is not null then
    return jsonb_build_object('ok', false, 'reason','already_merged',
      'message','That listing has already been merged into another product.');
  end if;
  if v_c.merged_into is not null then
    return jsonb_build_object('ok', false, 'reason','canonical_is_merged',
      'message','The canonical product you chose was itself merged into another one.');
  end if;

  -- Move the history that belongs to the buyer, not to the listing.
  update public.marketplace_order_items set product_id = p_canonical
   where product_id = p_duplicate;
  get diagnostics v_items = row_count;

  update public.marketplace_reviews set product_id = p_canonical, updated_at = now()
   where product_id = p_duplicate;
  get diagnostics v_reviews = row_count;

  update public.marketplace_licenses set product_id = p_canonical
   where product_id = p_duplicate;
  get diagnostics v_licences = row_count;

  select count(*) into v_commissions from public.marketplace_commissions c
    join public.marketplace_order_items i on i.id = c.order_item_id
   where i.product_id = p_canonical;

  -- The duplicate stays, pointing home, and comes off the storefront.
  update public.marketplace_products
     set merged_into = p_canonical,
         moderation_status = 'archived', content_status = 'archived',
         visible = false, moderation_lock = moderation_lock + 1, updated_at = now()
   where id = p_duplicate;

  -- The canonical product's rating is recomputed from the reviews it now holds.
  perform public.mm_product_rating_refresh(p_canonical);

  v_moved := jsonb_build_object(
    'order_items', v_items, 'reviews', v_reviews, 'licenses', v_licences,
    'commissions_now_on_canonical', v_commissions);

  insert into public.product_merge_operations
    (candidate_id, canonical_id, merged_id, moved, reason, performed_by)
  values (p_candidate, p_canonical, p_duplicate, v_moved, btrim(p_reason), auth.uid())
  returning to_jsonb(product_merge_operations) into v_op;

  if p_candidate is not null then
    update public.product_duplicate_candidates
       set status='merged', decided_by=auth.uid(), decided_at=now(),
           decision_reason=btrim(p_reason)
     where id = p_candidate;
  end if;

  perform public.mm_audit('product.merged','marketplace_product', p_duplicate::text,
    to_jsonb(v_d), jsonb_build_object('merged_into', p_canonical, 'moved', v_moved),
    btrim(p_reason));

  return jsonb_build_object('ok', true, 'operation', v_op, 'moved', v_moved,
    'note','The duplicate row was kept and now points at the canonical product, so existing links and order references still resolve.');
end;
$$;


--
-- Name: mm_product_moderate(uuid, text, text, integer, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_product_moderate(p_id uuid, p_to text, p_reason text DEFAULT NULL::text, p_lock integer DEFAULT NULL::integer, p_evidence jsonb DEFAULT '[]'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_p record; v_after jsonb; v_allowed boolean; v_checks jsonb;
  v_owner uuid; v_policy record; v_sub uuid;
begin
  if not public.mm_is_operator() then
    return jsonb_build_object('ok', false, 'reason', 'not_permitted');
  end if;
  if p_to not in ('draft','submitted','under_review','changes_requested',
                  'approved','rejected','suspended','archived','soft_deleted','trash') then
    return jsonb_build_object('ok', false, 'reason', 'unknown_status');
  end if;

  select * into v_p from public.marketplace_products where id = p_id for update;
  if not found then
    return jsonb_build_object('ok', false, 'reason', 'unknown_product');
  end if;

  if p_lock is not null and p_lock <> v_p.moderation_lock then
    return jsonb_build_object('ok', false, 'reason', 'stale',
      'message', 'Product changed by another reviewer. Refresh before continuing.',
      'current_status', v_p.moderation_status, 'current_lock', v_p.moderation_lock);
  end if;

  v_allowed := case v_p.moderation_status
    when 'draft'             then p_to in ('submitted','archived','soft_deleted')
    when 'submitted'         then p_to in ('under_review','approved','rejected','changes_requested','archived','soft_deleted')
    when 'under_review'      then p_to in ('approved','rejected','changes_requested','suspended','archived','soft_deleted')
    when 'changes_requested' then p_to in ('submitted','rejected','archived','soft_deleted')
    when 'approved'          then p_to in ('suspended','archived','soft_deleted','under_review')
    when 'rejected'          then p_to in ('draft','archived','soft_deleted')
    when 'suspended'         then p_to in ('approved','archived','soft_deleted','under_review')
    when 'archived'          then p_to in ('approved','draft','soft_deleted')
    when 'soft_deleted'      then p_to in ('trash','draft','archived','approved')
    when 'trash'             then p_to in ('soft_deleted')
    else false end;

  if not v_allowed then
    return jsonb_build_object('ok', false, 'reason', 'invalid_transition',
      'message', format('A %s product cannot become %s.', v_p.moderation_status, p_to));
  end if;

  if p_to in ('rejected','suspended','soft_deleted','trash','changes_requested')
     and coalesce(btrim(p_reason),'') = '' then
    return jsonb_build_object('ok', false, 'reason', 'reason_required',
      'message', 'Say why. The owner is told and this is recorded permanently.');
  end if;

  -- Restoring is not blind. A product coming back out of deletion, archive or
  -- suspension has to be publishable before it can be approved again.
  if p_to = 'approved' then
    v_checks := public.mm_product_checks(p_id);
    if (v_checks->>'blocking')::boolean then
      return jsonb_build_object('ok', false, 'reason', 'checks_failed',
        'message', format('%s mandatory check(s) are failing. This product cannot be published.',
                          v_checks->>'mandatory_failed'),
        'checks', v_checks->'checks');
    end if;
  end if;

  select * into v_policy from public.product_moderation_policy where id;

  update public.marketplace_products
     set moderation_status = p_to,
         -- Public visibility follows the decision, never the other way round.
         visible = (p_to = 'approved'),
         content_status = case p_to
           when 'approved' then 'published'
           when 'archived' then 'archived'
           else 'draft' end,
         approved_at = case when p_to='approved' then now() else approved_at end,
         approved_by = case when p_to='approved' then auth.uid() else approved_by end,
         deleted_at = case when p_to in ('soft_deleted','trash') then coalesce(deleted_at, now())
                           when p_to in ('draft','approved','archived') then null
                           else deleted_at end,
         deleted_by = case when p_to in ('soft_deleted','trash') then coalesce(deleted_by, auth.uid())
                           when p_to in ('draft','approved','archived') then null
                           else deleted_by end,
         delete_reason = case when p_to in ('soft_deleted','trash') then coalesce(nullif(btrim(p_reason),''), delete_reason)
                              when p_to in ('draft','approved','archived') then null
                              else delete_reason end,
         purge_after = case when p_to = 'soft_deleted'
                            then coalesce(deleted_at, now()) + (v_policy.recovery_days || ' days')::interval
                            when p_to in ('draft','approved','archived') then null
                            else purge_after end,
         moderation_lock = moderation_lock + 1,
         updated_at = now()
   where id = p_id returning to_jsonb(marketplace_products) into v_after;

  -- An open submission follows the product, so the two consoles never disagree.
  select id into v_sub from public.author_submissions
   where product_id = p_id
     and status in ('draft','pending_review','verifying','changes_requested')
   limit 1;
  if v_sub is not null and p_to in ('rejected','suspended','archived','soft_deleted','trash') then
    update public.author_submissions
       set status = case p_to when 'rejected' then 'rejected' else 'archived' end,
           last_action = p_to, last_reason = p_reason,
           lock_version = lock_version + 1, updated_at = now()
     where id = v_sub;
    insert into public.author_approval_history
      (submission_id, revision, action, from_status, to_status, actor_id, actor_role, reason)
    select v_sub, revision, 'moderation:'||p_to, status,
           case p_to when 'rejected' then 'rejected' else 'archived' end,
           auth.uid(), 'marketplace_manager',
           coalesce(p_reason,'Closed by the Product Moderation Center.')
      from public.author_submissions where id = v_sub;
  end if;

  perform public.mm_audit('product.'||p_to, 'marketplace_product', p_id::text,
                          to_jsonb(v_p), v_after,
                          coalesce(p_reason, format('Moderation: %s.', p_to)));

  select s.owner_user_id into v_owner
    from public.marketplace_sellers s where s.id = v_p.seller_id;
  if v_owner is not null then
    perform public.mm_notify('product.'||p_to,
      case p_to
        when 'approved' then 'Your product is approved and live'
        when 'rejected' then 'Your product was rejected'
        when 'suspended' then 'Your product has been suspended'
        when 'archived' then 'Your product has been archived'
        when 'soft_deleted' then 'Your product has been removed'
        else format('Your product is now %s', replace(p_to,'_',' ')) end,
      coalesce(p_reason, v_p.name),
      v_owner, null, '/author-manager', 'Open', 5,
      case p_to when 'approved' then 'success'
                when 'rejected' then 'warning'
                when 'suspended' then 'danger'
                when 'soft_deleted' then 'danger'
                when 'trash' then 'danger' else 'info' end);
  end if;

  return jsonb_build_object('ok', true, 'product', v_after,
    'public', p_to = 'approved',
    'recoverable_until', v_after->>'purge_after');
end;
$$;


--
-- Name: mm_product_moderation_detail(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_product_moderation_detail(p_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_p record;
begin
  if not public.mm_is_operator() then
    return jsonb_build_object('ok', false, 'reason','not_permitted');
  end if;
  select * into v_p from public.marketplace_products where id = p_id;
  if not found then return jsonb_build_object('ok', false, 'reason','unknown_product'); end if;

  return jsonb_build_object(
    'ok', true,
    'product', to_jsonb(v_p),
    'checks', public.mm_product_checks(p_id),
    'owner', (select jsonb_build_object('id', s.id, 'name', s.display_name,
                'status', s.status, 'kind', s.seller_kind,
                'violations', (select count(*) from public.legal_violations v
                                where v.violator_id = s.id::text
                                  and coalesce(v.status,'open') not in ('resolved','dismissed')))
                from public.marketplace_sellers s where s.id = v_p.seller_id),
    'category', (select jsonb_build_object('id', c.id, 'name', c.name)
                   from public.marketplace_categories c where c.id = v_p.category_id),

    -- Read from Review Manager. Never altered here: archiving a product does
    -- not delete its reviews.
    'reviews', jsonb_build_object(
      'published', (select count(*) from public.marketplace_reviews
                     where product_id=p_id and status='published'),
      'total', (select count(*) from public.marketplace_reviews where product_id=p_id),
      'rating', v_p.rating),

    'commerce', jsonb_build_object(
      'order_items', (select count(*) from public.marketplace_order_items where product_id=p_id),
      'licenses', (select count(*) from public.marketplace_licenses where product_id=p_id)),

    'versions', coalesce((select jsonb_agg(jsonb_build_object(
                            'version', v.version, 'status', v.status,
                            'published_at', v.published_at) order by v.created_at desc)
                            from public.marketplace_product_versions v
                           where v.product_id = p_id), '[]'::jsonb),

    'reports', coalesce((select jsonb_agg(jsonb_build_object(
                           'id', r.id, 'report_no', r.report_no, 'reason', r.reason,
                           'severity', r.severity, 'status', r.status,
                           'detail', r.detail, 'created_at', r.created_at)
                         order by r.created_at desc)
                          from public.product_reports r where r.product_id = p_id), '[]'::jsonb),

    'duplicates', coalesce((select jsonb_agg(jsonb_build_object(
                              'id', d.id, 'match', d.match_percent, 'status', d.status,
                              'reasons', d.reasons,
                              'other', (select name from public.marketplace_products
                                         where id = case when d.product_a=p_id then d.product_b
                                                         else d.product_a end)))
                             from public.product_duplicate_candidates d
                            where d.product_a=p_id or d.product_b=p_id), '[]'::jsonb),

    -- Legal Manager's own records, read only.
    'legal', coalesce((select jsonb_agg(jsonb_build_object(
                          'ref', v.ref_code, 'type', v.violation_type,
                          'severity', v.severity, 'status', v.status))
                         from public.legal_violations v
                        where v.violator_id = p_id::text), '[]'::jsonb),

    'history', coalesce((select jsonb_agg(jsonb_build_object(
                           'action', a.action, 'at', a.created_at, 'actor', a.actor_id,
                           'reason', a.reason)
                         order by a.created_at desc)
                          from (select * from public.marketplace_audit_logs
                                 where entity_id = p_id order by created_at desc limit 50) a),
                        '[]'::jsonb));
end;
$$;


--
-- Name: mm_product_purge_execute(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_product_purge_execute(p_request uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_r record; v_p record; v_policy record; v_outcome jsonb;
  v_orders integer; v_licences integer; v_reviews integer; v_merges integer;
  v_must_keep boolean;
begin
  if not (public.has_role(auth.uid(),'admin') or public.has_role(auth.uid(),'boss')
          or public.has_role(auth.uid(),'super_admin')) then
    return jsonb_build_object('ok', false, 'reason','not_permitted');
  end if;

  select * into v_r from public.product_purge_requests where id = p_request for update;
  if not found then return jsonb_build_object('ok', false, 'reason','unknown_request'); end if;
  if v_r.status = 'executed' then
    return jsonb_build_object('ok', false, 'reason','already_executed');
  end if;

  select * into v_policy from public.product_moderation_policy where id;

  if v_policy.dual_approval and v_r.status = 'pending' then
    if v_r.requested_by = auth.uid() then
      return jsonb_build_object('ok', false, 'reason','second_approver_required',
        'message','Dual approval is on. A different admin has to confirm this deletion.');
    end if;
    update public.product_purge_requests
       set status='approved', approved_by=auth.uid(), approved_at=now()
     where id = p_request;
    select * into v_r from public.product_purge_requests where id = p_request;
  end if;

  select * into v_p from public.marketplace_products where id = v_r.product_id for update;
  if not found then return jsonb_build_object('ok', false, 'reason','unknown_product'); end if;

  select count(*) into v_orders   from public.marketplace_order_items where product_id = v_p.id;
  select count(*) into v_licences from public.marketplace_licenses   where product_id = v_p.id;
  select count(*) into v_reviews  from public.marketplace_reviews    where product_id = v_p.id;
  select count(*) into v_merges   from public.product_merge_operations
   where canonical_id = v_p.id or merged_id = v_p.id;

  -- Anything that has to outlive the product keeps its row alive.
  v_must_keep :=
       (v_orders   > 0 and v_policy.preserve_orders)
    or (v_licences > 0 and v_policy.preserve_licenses)
    or (v_reviews  > 0 and v_policy.preserve_reviews)
    or v_merges > 0
    or exists (select 1 from public.marketplace_products x where x.merged_into = v_p.id);

  if v_must_keep then
    update public.marketplace_products
       set name = '[removed product ' || left(id::text,8) || ']',
           description = null, thumbnail_url = null, cover_image = null,
           demo_url = null, public_repo_url = null, logo = null, favicon = null,
           features = '{}'::jsonb, tags = '{}', tech_stack = '{}',
           search_keywords = '{}', search_text = null,
           visible = false, content_status = 'archived', moderation_status = 'trash',
           moderation_lock = moderation_lock + 1, updated_at = now()
     where id = v_p.id;

    v_outcome := jsonb_build_object(
      'mode','anonymised',
      'why', concat_ws(' ',
        'The listing content was removed and the record kept, because',
        case when v_orders > 0 or v_licences > 0
             then format('%s order line(s) and %s licence(s) depend on it;', v_orders, v_licences) end,
        case when v_reviews > 0 then format('%s review(s) reference it;', v_reviews) end,
        case when v_merges > 0 then format('%s merge record(s) reference it;', v_merges) end,
        'removing the row would have destroyed records that must be preserved.'),
      'orders_kept', v_orders, 'licences_kept', v_licences,
      'reviews_kept', v_reviews, 'merge_records_kept', v_merges);
  else
    delete from public.marketplace_products where id = v_p.id;
    v_outcome := jsonb_build_object(
      'mode','deleted',
      'why','Nothing referenced this product — no order, licence, review or merge record — so the row was removed outright.',
      'orders_kept', 0, 'licences_kept', 0, 'reviews_kept', 0, 'merge_records_kept', 0);
  end if;

  update public.product_purge_requests
     set status='executed', executed_at=now(), outcome=v_outcome
   where id = p_request;

  perform public.mm_audit('product.purged','marketplace_product', v_p.id::text,
                          to_jsonb(v_p), v_outcome, v_r.reason);

  return jsonb_build_object('ok', true, 'outcome', v_outcome);
end;
$$;


--
-- Name: mm_product_purge_request(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_product_purge_request(p_id uuid, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_p record; v_row jsonb; v_policy record;
begin
  if not (public.has_role(auth.uid(),'admin') or public.has_role(auth.uid(),'boss')
          or public.has_role(auth.uid(),'super_admin')) then
    return jsonb_build_object('ok', false, 'reason','not_permitted',
      'message','Permanent deletion is restricted to an admin or the boss.');
  end if;
  if coalesce(btrim(p_reason),'') = '' then
    return jsonb_build_object('ok', false, 'reason','reason_required');
  end if;

  select * into v_p from public.marketplace_products where id = p_id;
  if not found then return jsonb_build_object('ok', false, 'reason','unknown_product'); end if;
  if v_p.moderation_status <> 'trash' then
    return jsonb_build_object('ok', false, 'reason','not_in_trash',
      'message','Only a product already in the trash can be permanently deleted.');
  end if;

  select * into v_policy from public.product_moderation_policy where id;
  if v_p.purge_after is not null and v_p.purge_after > now() then
    return jsonb_build_object('ok', false, 'reason','recovery_window_open',
      'message', format('The %s day recovery window closes %s. It cannot be purged before then.',
                        v_policy.recovery_days, to_char(v_p.purge_after,'DD Mon YYYY')));
  end if;

  insert into public.product_purge_requests (product_id, reason, requested_by, status)
  values (p_id, btrim(p_reason), auth.uid(),
          case when v_policy.dual_approval then 'pending' else 'approved' end)
  returning to_jsonb(product_purge_requests) into v_row;

  if not v_policy.dual_approval then
    update public.product_purge_requests set approved_by = auth.uid(), approved_at = now()
     where id = (v_row->>'id')::uuid returning to_jsonb(product_purge_requests) into v_row;
  end if;

  perform public.mm_audit('product.purge_requested','marketplace_product', p_id::text,
                          null, v_row, btrim(p_reason));

  return jsonb_build_object('ok', true, 'request', v_row,
    'dual_approval_required', v_policy.dual_approval);
end;
$$;


--
-- Name: mm_product_rating_refresh(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_product_rating_refresh(p_product uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_avg numeric; v_n integer;
begin
  if p_product is null then
    return jsonb_build_object('ok', false, 'reason', 'no_product');
  end if;

  select round(avg(rating)::numeric,2), count(*) into v_avg, v_n
    from public.marketplace_reviews
   where product_id = p_product and status = 'published';

  update public.marketplace_products
     set rating = coalesce(v_avg, 0), updated_at = now()
   where id = p_product;

  return jsonb_build_object('ok', true, 'rating', coalesce(v_avg,0), 'reviews', v_n);
end;
$$;


--
-- Name: mm_product_report(uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_product_report(p_product uuid, p_reason text, p_detail text DEFAULT NULL::text, p_severity text DEFAULT 'normal'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_no text; v_row jsonb; v_name text;
begin
  if auth.uid() is null then
    return jsonb_build_object('ok', false, 'reason','sign_in_required');
  end if;
  if p_reason not in ('copyright','trademark','fraudulent_claims','misleading','security',
                      'malware','duplicate','policy_violation','broken_product',
                      'illegal_content','other') then
    return jsonb_build_object('ok', false, 'reason','unknown_reason');
  end if;
  select name into v_name from public.marketplace_products where id = p_product;
  if v_name is null then
    return jsonb_build_object('ok', false, 'reason','unknown_product');
  end if;

  v_no := 'PR-' || lpad(((select count(*) from public.product_reports) + 1)::text, 5, '0');

  insert into public.product_reports
    (report_no, product_id, reporter_id, reason, detail, severity,
     reporter_kind, status)
  values (v_no, p_product, auth.uid(), p_reason, nullif(btrim(p_detail),''),
          case when p_reason in ('malware','illegal_content','security') then 'critical'
               when p_reason in ('copyright','trademark') then 'high'
               else coalesce(nullif(p_severity,''),'normal') end,
          case when public.mm_is_operator() then 'manager' else 'user' end,
          'reported')
  returning to_jsonb(product_reports) into v_row;

  perform public.mm_audit('product.reported','marketplace_product', p_product::text,
                          null, v_row, p_reason);

  -- A serious report reaches the operators immediately.
  if (v_row->>'severity') in ('high','critical') then
    perform public.mm_notify('product.reported',
      format('%s reported: %s', v_no, replace(p_reason,'_',' ')),
      format('%s — %s', v_name, coalesce(nullif(btrim(p_detail),''),'no detail given')),
      null, array['admin','boss'], '/marketplace-manager', 'Review', 5, 'danger');
  end if;

  return jsonb_build_object('ok', true, 'report', v_row);
end;
$$;


--
-- Name: mm_product_share(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_product_share(p_product uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_p record; v_s record; v_url text; v_short text; v_qr record; v_enc text;
begin
  select * into v_p from public.marketplace_products where id = p_product;
  if not found then return jsonb_build_object('ok', false, 'reason','unknown_product'); end if;
  select * into v_s from public.product_url_settings where id;

  select v_s.site_url || path into v_url from public.product_urls
   where product_id = p_product and is_canonical and status='active';
  if v_url is null then
    return jsonb_build_object('ok', false, 'reason','no_canonical_url',
      'message','This product has no canonical URL yet, so there is nothing to share.');
  end if;

  select public.mm_short_link_url(code) into v_short from public.product_short_links
   where product_id = p_product and status='active' order by created_at limit 1;

  select * into v_qr from public.product_qr_codes where product_id=p_product and active;

  v_enc := replace(replace(coalesce(v_short, v_url), ':', '%3A'), '/', '%2F');

  return jsonb_build_object(
    'ok', true,
    'canonical_url', v_url,
    'short_url', v_short,
    'qr_code', v_qr.qr_code,
    'qr_target', v_qr.target_url,
    -- Text built from the product's own name and description. Nothing invented.
    'share_text', format('%s — %s', v_p.name,
      left(coalesce(nullif(btrim(v_p.description),''), 'on the Software Vala marketplace'), 120)),
    'whatsapp', 'https://wa.me/?text=' ||
      replace(replace(v_p.name || ' ' || coalesce(v_short, v_url), ' ', '%20'), ':', '%3A'),
    'facebook', 'https://www.facebook.com/sharer/sharer.php?u=' || v_enc,
    'x', 'https://twitter.com/intent/tweet?url=' || v_enc ||
         '&text=' || replace(v_p.name, ' ', '%20'),
    'linkedin', 'https://www.linkedin.com/sharing/share-offsite/?url=' || v_enc,
    'email', 'mailto:?subject=' || replace(v_p.name, ' ', '%20') ||
             '&body=' || replace(coalesce(v_short, v_url), ':', '%3A'));
end;
$$;


--
-- Name: mm_product_urls(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_product_urls(p_query jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_search text := nullif(btrim(coalesce(p_query->>'search','')),'');
  v_limit integer := least(greatest(coalesce((p_query->>'limit')::int,50),1),200);
  v_offset integer := greatest(coalesce((p_query->>'offset')::int,0),0);
  v_s record;
begin
  if not public.mm_is_operator() then
    return jsonb_build_object('ok', false, 'reason','not_permitted');
  end if;
  select * into v_s from public.product_url_settings where id;

  return jsonb_build_object(
    'ok', true,
    'settings', to_jsonb(v_s),

    -- 47. Where short links actually live, stated rather than assumed.
    'short_domain', jsonb_build_object(
      'configured', v_s.short_link_domain is not null and v_s.short_link_domain_verified,
      'state', case when v_s.short_link_domain is null then 'REQUIRES_CONFIGURATION'
                    when not v_s.short_link_domain_verified then 'REQUIRES_CONFIGURATION'
                    else 'CONNECTED' end,
      'serving_from', case when v_s.short_link_domain is not null and v_s.short_link_domain_verified
                           then v_s.short_link_domain else v_s.site_url || '/s/' end,
      'note', case when v_s.short_link_domain is null or not v_s.short_link_domain_verified
        then 'No vanity short domain is configured, so short links are served from /s/ on the main site. They resolve and record clicks today; a vanity host would only shorten them further.'
        else null end),

    'routes', coalesce((select jsonb_agg(jsonb_build_object(
                 'prefix', prefix, 'note', note, 'verified_at', verified_at))
                 from public.product_url_route_prefixes), '[]'::jsonb),

    -- Counted, never asserted.
    'counts', jsonb_build_object(
      'products', (select count(*) from public.marketplace_products where deleted_at is null),
      'with_canonical', (select count(distinct product_id) from public.product_urls
                          where is_canonical and status='active'),
      'redirects', (select count(*) from public.product_urls where status='redirect'),
      'short_links', (select count(*) from public.product_short_links where status='active'),
      'qr_codes', (select count(*) from public.product_qr_codes where active)),

    'analytics', jsonb_build_object(
      'clicks_total', (select count(*) from public.product_short_link_events),
      'clicks_today', (select count(*) from public.product_short_link_events
                        where created_at >= date_trunc('day', now())),
      'unique_visitors', (select count(distinct visitor_hash) from public.product_short_link_events
                           where visitor_hash is not null),
      'scans_total', (select count(*) from public.product_qr_events),
      'scans_today', (select count(*) from public.product_qr_events
                       where created_at >= date_trunc('day', now())),
      'shares', (select count(*) from public.product_share_events),
      'top_products', coalesce((select jsonb_agg(jsonb_build_object(
                        'product', (select name from public.marketplace_products where id=t.product_id),
                        'clicks', t.n) order by t.n desc)
                        from (select product_id, count(*) n
                                from public.product_short_link_events
                               group by product_id order by n desc limit 10) t), '[]'::jsonb),
      'top_campaigns', coalesce((select jsonb_object_agg(c, n) from (
                        select coalesce(utm_campaign,'(none)') c, count(*) n
                          from public.product_short_link_events
                         group by 1 order by 2 desc limit 10) t), '{}'::jsonb),
      'top_referrers', coalesce((select jsonb_object_agg(r, n) from (
                        select coalesce(nullif(referrer,''),'(direct)') r, count(*) n
                          from public.product_short_link_events
                         group by 1 order by 2 desc limit 10) t), '{}'::jsonb),
      'devices', coalesce((select jsonb_object_agg(d, n) from (
                        select coalesce(device_type,'unknown') d, count(*) n
                          from public.product_short_link_events group by 1) t), '{}'::jsonb),
      'countries', coalesce((select jsonb_object_agg(c, n) from (
                        select coalesce(country,'unknown') c, count(*) n
                          from public.product_short_link_events
                         group by 1 order by 2 desc limit 12) t), '{}'::jsonb)),

    'last_job', (select to_jsonb(j) from (select * from public.product_url_jobs
                   order by started_at desc limit 1) j),

    'total', (select count(*) from public.marketplace_products p where p.deleted_at is null
               and (v_search is null or p.name ilike '%'||v_search||'%' or p.slug ilike '%'||v_search||'%')),

    'rows', coalesce((
      select jsonb_agg(jsonb_build_object(
               'product_id', p.id, 'product', p.name, 'visible', p.visible,
               'moderation_status', p.moderation_status,
               'canonical', (select v_s.site_url || u.path from public.product_urls u
                              where u.product_id=p.id and u.is_canonical and u.status='active'),
               'canonical_path', (select u.path from public.product_urls u
                                   where u.product_id=p.id and u.is_canonical and u.status='active'),
               'redirects', (select count(*) from public.product_urls u
                              where u.product_id=p.id and u.status='redirect'),
               'short_code', (select l.code from public.product_short_links l
                               where l.product_id=p.id and l.status='active' order by l.created_at limit 1),
               'short_url', (select public.mm_short_link_url(l.code) from public.product_short_links l
                              where l.product_id=p.id and l.status='active' order by l.created_at limit 1),
               'clicks', (select coalesce(sum(l.click_count),0) from public.product_short_links l
                           where l.product_id=p.id),
               'qr_code', (select q.qr_code from public.product_qr_codes q
                            where q.product_id=p.id and q.active),
               'scans', (select coalesce(q.scan_count,0) from public.product_qr_codes q
                          where q.product_id=p.id and q.active))
             order by p.updated_at desc)
        from (select * from public.marketplace_products p2
               where p2.deleted_at is null
                 and (v_search is null or p2.name ilike '%'||v_search||'%'
                      or p2.slug ilike '%'||v_search||'%')
               order by p2.updated_at desc limit v_limit offset v_offset) p), '[]'::jsonb));
end;
$$;


--
-- Name: mm_products_bulk(uuid[], text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_products_bulk(p_ids uuid[], p_op text, p_reason text DEFAULT NULL::text, p_target uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_id uuid; v_res jsonb; v_out jsonb := '[]'::jsonb;
  v_done integer := 0; v_skipped integer := 0;
  v_p record; v_checks jsonb; v_before jsonb;
begin
  if not public.mm_is_operator() then
    return jsonb_build_object('ok', false, 'reason','not_permitted');
  end if;
  if p_ids is null or array_length(p_ids,1) is null then
    return jsonb_build_object('ok', false, 'reason','nothing_selected');
  end if;
  if array_length(p_ids,1) > 200 then
    return jsonb_build_object('ok', false, 'reason','too_many',
      'message','Bulk operations are limited to 200 products at a time.');
  end if;
  if p_op not in ('approved','rejected','suspended','archived','soft_deleted',
                  'publish','unpublish','category','author') then
    return jsonb_build_object('ok', false, 'reason','unknown_operation');
  end if;

  -- Reassignment is never silent: it needs a reason and a real target.
  if p_op in ('category','author') then
    if p_target is null then
      return jsonb_build_object('ok', false, 'reason','target_required');
    end if;
    if coalesce(btrim(p_reason),'') = '' then
      return jsonb_build_object('ok', false, 'reason','reason_required',
        'message','Changing the category or the owner of a listing has to say why.');
    end if;
    if p_op='category' and not exists (select 1 from public.marketplace_categories where id=p_target) then
      return jsonb_build_object('ok', false, 'reason','unknown_category');
    end if;
    if p_op='author' and not exists (select 1 from public.marketplace_sellers
                                      where id=p_target and status='approved') then
      return jsonb_build_object('ok', false, 'reason','unknown_or_unapproved_owner',
        'message','A listing can only be reassigned to an approved seller.');
    end if;
  end if;

  foreach v_id in array p_ids loop
    select * into v_p from public.marketplace_products where id = v_id;
    if not found then
      v_skipped := v_skipped + 1;
      v_out := v_out || jsonb_build_object('id', v_id, 'ok', false, 'reason','unknown_product');
      continue;
    end if;
    v_before := to_jsonb(v_p);

    if p_op in ('approved','rejected','suspended','archived','soft_deleted') then
      v_res := public.mm_product_moderate(v_id, p_op, p_reason, null);
      if (v_res->>'ok')::boolean then v_done := v_done + 1; else v_skipped := v_skipped + 1; end if;
      v_out := v_out || jsonb_build_object('id', v_id, 'product', v_p.name,
        'ok', (v_res->>'ok')::boolean, 'reason', v_res->>'reason', 'message', v_res->>'message');

    elsif p_op = 'publish' then
      -- Publication is only allowed where the product would pass on its own.
      v_checks := public.mm_product_checks(v_id);
      if v_p.moderation_status <> 'approved' then
        v_skipped := v_skipped + 1;
        v_out := v_out || jsonb_build_object('id', v_id, 'product', v_p.name, 'ok', false,
          'reason','not_approved',
          'message', format('This product is %s. Only an approved product can be published.',
                            v_p.moderation_status));
      elsif (v_checks->>'blocking')::boolean then
        v_skipped := v_skipped + 1;
        v_out := v_out || jsonb_build_object('id', v_id, 'product', v_p.name, 'ok', false,
          'reason','checks_failed',
          'message', format('%s mandatory check(s) failing.', v_checks->>'mandatory_failed'));
      else
        update public.marketplace_products
           set visible = true, content_status='published',
               moderation_lock = moderation_lock + 1, updated_at = now()
         where id = v_id;
        v_done := v_done + 1;
        perform public.mm_audit('product.published','marketplace_product', v_id::text,
                                v_before, jsonb_build_object('visible', true), p_reason);
        v_out := v_out || jsonb_build_object('id', v_id, 'product', v_p.name, 'ok', true);
      end if;

    elsif p_op = 'unpublish' then
      update public.marketplace_products
         set visible = false, content_status='draft',
             moderation_lock = moderation_lock + 1, updated_at = now()
       where id = v_id;
      v_done := v_done + 1;
      perform public.mm_audit('product.unpublished','marketplace_product', v_id::text,
                              v_before, jsonb_build_object('visible', false), p_reason);
      v_out := v_out || jsonb_build_object('id', v_id, 'product', v_p.name, 'ok', true);

    elsif p_op = 'category' then
      update public.marketplace_products
         set category_id = p_target, moderation_lock = moderation_lock + 1, updated_at = now()
       where id = v_id;
      v_done := v_done + 1;
      perform public.mm_audit('product.category_changed','marketplace_product', v_id::text,
        jsonb_build_object('category_id', v_p.category_id),
        jsonb_build_object('category_id', p_target), p_reason);
      v_out := v_out || jsonb_build_object('id', v_id, 'product', v_p.name, 'ok', true,
        'from', v_p.category_id, 'to', p_target);

    elsif p_op = 'author' then
      update public.marketplace_products
         set seller_id = p_target, moderation_lock = moderation_lock + 1, updated_at = now()
       where id = v_id;
      v_done := v_done + 1;
      perform public.mm_audit('product.owner_changed','marketplace_product', v_id::text,
        jsonb_build_object('seller_id', v_p.seller_id),
        jsonb_build_object('seller_id', p_target), p_reason);
      v_out := v_out || jsonb_build_object('id', v_id, 'product', v_p.name, 'ok', true,
        'from', v_p.seller_id, 'to', p_target);
    end if;
  end loop;

  perform public.mm_audit('product.bulk_'||p_op,'marketplace_product', null, null,
    jsonb_build_object('selected', array_length(p_ids,1), 'applied', v_done, 'skipped', v_skipped),
    p_reason);

  return jsonb_build_object('ok', true, 'operation', p_op,
    'selected', array_length(p_ids,1), 'applied', v_done, 'skipped', v_skipped,
    'results', v_out);
end;
$$;


--
-- Name: mm_qr_create(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_qr_create(p_product uuid, p_short_link uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp', 'extensions'
    AS $$
declare
  v_s record; v_alphabet constant text :=
    'ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz23456789';
  v_code text; v_bytes bytea; i integer; v_target text; v_row jsonb;
  v_link_id uuid; v_link_code text;
begin
  if not public.mm_is_operator() then
    return jsonb_build_object('ok', false, 'reason','not_permitted');
  end if;
  select * into v_s from public.product_url_settings where id;

  -- A QR must encode something that resolves. If there is no canonical URL yet
  -- there is nothing to point at, and inventing one would produce a QR that
  -- goes nowhere.
  if not exists (select 1 from public.product_urls
                  where product_id = p_product and is_canonical and status='active') then
    return jsonb_build_object('ok', false, 'reason','no_canonical_url',
      'message','Generate the canonical URL first. A QR that encodes nothing is worse than no QR.');
  end if;

  -- Tracked with its own variable: reading a field off a record that was never
  -- assigned raises "record is not assigned yet" rather than returning null.
  if p_short_link is not null then
    select id, code into v_link_id, v_link_code from public.product_short_links
     where id = p_short_link and status='active';
  end if;
  if v_link_id is null then
    select id, code into v_link_id, v_link_code from public.product_short_links
     where product_id = p_product and status='active' order by created_at limit 1;
  end if;

  -- Prefer the short link, so a scan is attributable; fall back to canonical.
  v_target := case when v_link_id is not null then public.mm_short_link_url(v_link_code)
                   else v_s.site_url || (select path from public.product_urls
                                          where product_id=p_product and is_canonical and status='active') end;

  for attempt in 1..12 loop
    v_code := '';
    v_bytes := gen_random_bytes(8);
    for i in 0..7 loop
      v_code := v_code || substr(v_alphabet, (get_byte(v_bytes, i) % length(v_alphabet)) + 1, 1);
    end loop;
    exit when not exists (select 1 from public.product_qr_codes where qr_code = v_code);
    v_code := null;
  end loop;
  if v_code is null then
    return jsonb_build_object('ok', false, 'reason','could_not_generate');
  end if;

  -- One active QR per product; a new one supersedes the old.
  update public.product_qr_codes set active=false where product_id = p_product and active;

  insert into public.product_qr_codes
    (product_id, short_link_id, qr_code, target_url, foreground, background,
     size, error_correction, quiet_zone,
     version, created_by)
  values (p_product, v_link_id, v_code, v_target,
          v_s.qr_foreground, v_s.qr_background, v_s.qr_size,
          v_s.qr_error_correction, v_s.qr_quiet_zone,
          coalesce((select max(version)+1 from public.product_qr_codes where product_id=p_product), 1),
          auth.uid())
  returning to_jsonb(product_qr_codes) into v_row;

  perform public.mm_audit('url.qr_created','product_qr', (v_row->>'id'), null, v_row, null);

  return jsonb_build_object('ok', true, 'qr', v_row, 'target', v_target);
end;
$$;


--
-- Name: mm_qr_scan(text, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_qr_scan(p_qr_code text, p_country text DEFAULT NULL::text, p_device text DEFAULT NULL::text, p_browser text DEFAULT NULL::text, p_visitor_hash text DEFAULT NULL::text, p_campaign text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_q record; v_s record;
begin
  select * into v_q from public.product_qr_codes where qr_code = p_qr_code and active;
  if not found then
    return jsonb_build_object('ok', false, 'status', 404, 'reason','unknown_qr');
  end if;
  select * into v_s from public.product_url_settings where id;

  begin
    insert into public.product_qr_events
      (qr_id, product_id, campaign, country, device_type, browser, visitor_hash, purge_after)
    values (v_q.id, v_q.product_id, p_campaign, p_country, p_device, p_browser,
            p_visitor_hash, now() + (v_s.analytics_retention_days || ' days')::interval);
    update public.product_qr_codes
       set scan_count = scan_count + 1, last_scan_at = now() where id = v_q.id;
  exception when others then
    null;
  end;

  return jsonb_build_object('ok', true, 'status', 302, 'destination', v_q.target_url);
end;
$$;


--
-- Name: mm_recommend(text, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_recommend(p_key text, p_product_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT NULL::integer) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  cfg    record;
  -- Plain variables rather than a record: plpgsql resolves a record's structure
  -- even inside a CASE that never runs, so an unassigned `seed` broke the
  -- popularity strategy, which has no seed product by definition.
  v_seed_cat uuid;
  v_seed_sub text;
  v_seed_ind text;
  v_lim  int;
  v_rows jsonb;
  v_why  text;
begin
  select * into cfg from public.marketplace_recommendation_configs where key = p_key;
  if cfg.key is null then
    return jsonb_build_object('ok', false, 'reason', 'unknown_engine');
  end if;

  -- Section 9: the toggle is the real switch.
  if not cfg.enabled then
    return jsonb_build_object('ok', true, 'engine', p_key, 'enabled', false,
      'products', '[]'::jsonb, 'count', 0,
      'reason', coalesce(cfg.blocked_reason, 'This engine is switched off.'));
  end if;

  -- Section 20 and 33: a personal engine with no signal returns an honest
  -- empty state naming the reason, never a filled-in guess.
  if cfg.strategy = 'personal' then
    return jsonb_build_object('ok', true, 'engine', p_key, 'enabled', true,
      'products', '[]'::jsonb, 'count', 0,
      'reason', coalesce(cfg.blocked_reason,
                'Not enough signal yet to personalise recommendations.'));
  end if;

  v_lim := least(coalesce(p_limit, cfg.max_results), 60);

  if cfg.strategy = 'similarity' then
    if p_product_id is null then
      return jsonb_build_object('ok', false, 'reason', 'product_required',
        'message', 'Similar Products needs a product to be similar to.');
    end if;
    select category_id, subcategory, industry_label
      into v_seed_cat, v_seed_sub, v_seed_ind
    from public.marketplace_products where id = p_product_id;
    if not found then
      return jsonb_build_object('ok', false, 'reason', 'unknown_product');
    end if;
    v_why := 'Similar to the product you are viewing';
  else
    v_why := 'Most viewed in the last ' || cfg.recency_days || ' days';
  end if;

  with events as (
    select e.product_id,
           count(*) filter (where e.event_type::text = 'product_view') views,
           count(*) filter (where e.event_type::text = 'demo_click')   demos
    from public.marketplace_events e
    where e.created_at > now() - make_interval(days => cfg.recency_days)
      and e.product_id is not null
    group by e.product_id
  ),
  candidates as (
    select p.id, p.name, p.slug, p.thumbnail_url, p.category_id,
           p.subcategory, p.industry_label, p.rating,
           coalesce(ev.views, 0) views, coalesce(ev.demos, 0) demos,
           -- Section 11: scoring, from the weights the manager actually set.
           ( case when cfg.strategy = 'similarity' and p.category_id = v_seed_cat
                  then (cfg.weights->>'category')::numeric else 0 end
           + case when cfg.strategy = 'similarity'
                       and p.subcategory is not distinct from v_seed_sub
                       and p.subcategory is not null
                  then (cfg.weights->>'subcategory')::numeric else 0 end
           + case when cfg.strategy = 'similarity'
                       and p.industry_label is not distinct from v_seed_ind
                       and p.industry_label is not null
                  then (cfg.weights->>'industry')::numeric else 0 end
           + (cfg.weights->>'popularity')::numeric
             * least(coalesce(ev.views,0) + coalesce(ev.demos,0), 10) / 10.0
           + (cfg.weights->>'rating')::numeric * coalesce(p.rating,0) / 5.0
           ) as score
    from public.marketplace_products p
    left join events ev on ev.product_id = p.id
    where p.visible
      and p.content_status = 'published'
      and (p_product_id is null or p.id <> p_product_id)
      -- Popularity means popular. Without this a "Popular Now" row pads itself
      -- with products nobody has viewed, which is a claim the data does not
      -- support; with it the row returns however many genuinely have a signal,
      -- which today is 3.
      and (cfg.strategy <> 'popularity' or coalesce(ev.views,0) + coalesce(ev.demos,0) > 0)
      -- Section 15: never recommend something already bought.
      and (not cfg.exclude_purchased or not exists (
            select 1 from public.marketplace_order_items oi
            join public.marketplace_orders o on o.id = oi.order_id
             and o.status::text = 'paid' and o.buyer_id = auth.uid()
            where oi.product_id = p.id))
  ),
  ranked as (
    select *, row_number() over (partition by category_id order by score desc, name) rn
    from candidates
    where score >= cfg.min_confidence
  )
  select coalesce(jsonb_agg(r order by (r->>'score')::numeric desc), '[]'::jsonb) into v_rows
  from (
    select jsonb_build_object(
      'product_id', id, 'name', name, 'slug', slug,
      'thumbnail_url', thumbnail_url, 'category_id', category_id,
      'score', round(score, 4), 'views', views,
      'href', '/marketplace/product/' || slug) r
    from ranked
    -- Section 14: diversity, so one category cannot fill the row.
    where rn <= greatest(cfg.diversity_per_category, 1)
    order by score desc, name
    limit v_lim
  ) x;

  return jsonb_build_object(
    'ok', true, 'engine', p_key, 'enabled', true,
    'strategy', cfg.strategy,
    'count', jsonb_array_length(v_rows),
    'requested', v_lim,
    -- Section 21: the explanation names the signal actually used.
    'reason', v_why,
    'signal_strength', (select count(*) from public.marketplace_events
                        where created_at > now() - make_interval(days => cfg.recency_days)),
    'products', v_rows);
end $$;


--
-- Name: mm_recommendation_configure(text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_recommendation_configure(p_key text, p_patch jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_before jsonb; cfg record;
begin
  if not public.mm_is_operator() then
    return jsonb_build_object('ok', false, 'reason', 'not_permitted');
  end if;
  select * into cfg from public.marketplace_recommendation_configs where key = p_key;
  if cfg.key is null then
    return jsonb_build_object('ok', false, 'reason', 'unknown_engine');
  end if;

  -- An engine with no signal cannot be switched on, because switching it on
  -- would only produce an empty row that looks broken.
  if coalesce((p_patch->>'enabled')::boolean, false) and cfg.blocked_reason is not null then
    return jsonb_build_object('ok', false, 'reason', 'blocked',
      'message', cfg.blocked_reason);
  end if;

  select to_jsonb(c) into v_before from public.marketplace_recommendation_configs c where c.key = p_key;

  update public.marketplace_recommendation_configs set
    enabled                = coalesce((p_patch->>'enabled')::boolean, enabled),
    max_results            = coalesce((p_patch->>'max_results')::int, max_results),
    weights                = coalesce(p_patch->'weights', weights),
    recency_days           = coalesce((p_patch->>'recency_days')::int, recency_days),
    min_confidence         = coalesce((p_patch->>'min_confidence')::numeric, min_confidence),
    exclude_purchased      = coalesce((p_patch->>'exclude_purchased')::boolean, exclude_purchased),
    diversity_per_category = coalesce((p_patch->>'diversity_per_category')::int, diversity_per_category),
    updated_by = auth.uid(), updated_at = now()
  where key = p_key;

  perform public.mm_audit('recommendation_configure', 'recommendation_engine', p_key,
    coalesce(v_before, '{}'::jsonb), p_patch, 'engine tuning changed');

  return jsonb_build_object('ok', true, 'engine', p_key);
end $$;


--
-- Name: mm_recommendation_engines(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_recommendation_engines() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select coalesce(jsonb_agg(jsonb_build_object(
    'key', c.key, 'title', c.title, 'description', c.description,
    'enabled', c.enabled, 'strategy', c.strategy, 'max_results', c.max_results,
    'weights', c.weights, 'recency_days', c.recency_days,
    'min_confidence', c.min_confidence, 'exclude_purchased', c.exclude_purchased,
    'diversity_per_category', c.diversity_per_category,
    'blocked_reason', c.blocked_reason,
    'can_run', (c.blocked_reason is null),
    'updated_at', c.updated_at) order by c.key), '[]'::jsonb)
  from public.marketplace_recommendation_configs c;
$$;


--
-- Name: mm_refund_request(uuid, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_refund_request(p_order_id uuid, p_amount numeric, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare o record; v_id uuid; v_provider text; v_configured boolean;
begin
  if not public.mm_is_operator() then
    return jsonb_build_object('ok', false, 'reason', 'not_permitted');
  end if;

  select * into o from public.marketplace_orders where id = p_order_id;
  if o.id is null then
    return jsonb_build_object('ok', false, 'reason', 'unknown_order');
  end if;
  if o.status::text <> 'paid' then
    return jsonb_build_object('ok', false, 'reason', 'not_paid',
      'message', 'Only a paid order can be refunded. This one is ' || o.status::text || '.');
  end if;
  if coalesce(p_amount, 0) <= 0 or p_amount > o.total then
    return jsonb_build_object('ok', false, 'reason', 'bad_amount',
      'message', 'A refund must be more than zero and no more than the order total.');
  end if;

  v_provider := coalesce(o.payment_gateway, 'unconfigured');
  -- A real provider reference is the only evidence money actually moved.
  v_configured := coalesce(o.payu_txn_id, o.txnid) is not null;

  -- The table's own vocabulary is pending / approved / processed / failed /
  -- cancelled, so a refund nobody has confirmed is 'pending' and processed_at
  -- stays null. Inventing a 'blocked' status would have meant widening a
  -- constraint to describe something 'pending' already says correctly; the
  -- reason it is stuck is recorded in payload instead.
  insert into public.marketplace_order_refunds
    (order_id, provider, amount, currency, status, reason, payload)
  values (p_order_id, v_provider, p_amount, o.currency::text, 'pending', p_reason,
          jsonb_build_object('provider_configured', v_configured,
                             'blocked_reason', case when v_configured then null
                               else 'no payment provider is configured for this order' end))
  returning id into v_id;

  perform public.mm_audit('order_refund_requested', 'marketplace_order', p_order_id::text,
    jsonb_build_object('status', o.status::text, 'total', o.total),
    jsonb_build_object('refund_id', v_id, 'amount', p_amount, 'provider', v_provider),
    coalesce(p_reason, 'refund requested'));

  if not v_configured then
    return jsonb_build_object('ok', true, 'refund_id', v_id,
      'status', 'pending', 'provider_configured', false,
      'message', 'Refund recorded, but no payment provider is configured for this order, '
                 'so no money has moved. The order status is unchanged.');
  end if;

  return jsonb_build_object('ok', true, 'refund_id', v_id, 'status', 'pending',
    'provider_configured', true,
    'message', 'Refund requested. The order stays paid until the provider confirms it.');
end $$;


--
-- Name: mm_release_overview(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_release_overview() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if not public.mm_is_operator() then
    return jsonb_build_object('ok', false, 'reason', 'not_permitted');
  end if;

  return jsonb_build_object(
    'ok', true,
    'total',       (select count(*) from public.marketplace_product_versions),
    'published',   (select count(*) from public.marketplace_product_versions
                     where published_at is not null),
    'draft',       (select count(*) from public.marketplace_product_versions
                     where published_at is null),
    'by_status', coalesce((
      select jsonb_agg(jsonb_build_object('status', status, 'count', n) order by n desc)
        from (select coalesce(status,'(none)') status, count(*) n
                from public.marketplace_product_versions group by 1) t), '[]'::jsonb),
    'products_with_versions', (select count(distinct product_id)
                                from public.marketplace_product_versions),
    'downloads',   (select count(*) from public.marketplace_downloads),
    'unavailable', jsonb_build_object(
      'channels',     'no release channel table exists (stable/beta/deprecated)',
      'branches',     'no branch table exists',
      'changelogs',   'no changelog table — marketplace_product_versions.release_notes is the only field',
      'roadmap',      'no roadmap table exists',
      'deprecations', 'no deprecation table exists',
      'files',        'no product file storage: no bucket, and download_path holds no rows'));
end;
$$;


--
-- Name: mm_report_transition(uuid, text, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_report_transition(p_report uuid, p_to text, p_resolution text DEFAULT NULL::text, p_escalate_legal boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_r record; v_after jsonb; v_allowed boolean; v_ref text;
begin
  if not public.mm_is_operator() then
    return jsonb_build_object('ok', false, 'reason','not_permitted');
  end if;
  if p_to not in ('under_review','action_required','resolved','dismissed') then
    return jsonb_build_object('ok', false, 'reason','unknown_status');
  end if;

  select * into v_r from public.product_reports where id = p_report for update;
  if not found then return jsonb_build_object('ok', false, 'reason','unknown_report'); end if;

  v_allowed := case v_r.status
    when 'reported'        then p_to in ('under_review','dismissed')
    when 'under_review'    then p_to in ('action_required','resolved','dismissed')
    when 'action_required' then p_to in ('resolved','dismissed')
    else false end;
  if not v_allowed then
    return jsonb_build_object('ok', false, 'reason','invalid_transition',
      'message', format('A %s report cannot become %s.', v_r.status, p_to));
  end if;

  if p_to in ('resolved','dismissed') and coalesce(btrim(p_resolution),'') = '' then
    return jsonb_build_object('ok', false, 'reason','resolution_required',
      'message','Record the finding. A report is closed with a reason, not silently.');
  end if;

  -- Escalation to Legal Manager records the reference here; the legal record
  -- itself is created and owned there.
  if p_escalate_legal then
    v_ref := 'LEGAL-' || upper(substr(md5(p_report::text), 1, 8));
  end if;

  update public.product_reports
     set status = p_to,
         resolution = coalesce(nullif(btrim(p_resolution),''), resolution),
         assigned_to = case when p_to='under_review' then coalesce(assigned_to, auth.uid())
                            else assigned_to end,
         resolved_by = case when p_to in ('resolved','dismissed') then auth.uid() else resolved_by end,
         resolved_at = case when p_to in ('resolved','dismissed') then now() else resolved_at end,
         legal_reference = coalesce(v_ref, legal_reference),
         updated_at = now()
   where id = p_report returning to_jsonb(product_reports) into v_after;

  perform public.mm_audit('product.report_'||p_to,'product_report', p_report::text,
                          to_jsonb(v_r), v_after, p_resolution);

  return jsonb_build_object('ok', true, 'report', v_after,
    'legal_reference', v_ref,
    'note', case when p_escalate_legal
      then 'A legal reference was recorded here. The legal record itself belongs to Legal Manager and must be raised there.'
      else null end);
end;
$$;


--
-- Name: mm_reseller_attention(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_reseller_attention() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if not public.mm_reseller_operator() then
    return jsonb_build_object('ok', false, 'reason', 'not_permitted');
  end if;
  return jsonb_build_object(
    'ok', true,
    'as_of', now(),
    'applications_pending', (select count(*) from public.resellers where status = 'pending'),
    'applications_kyc_unverified', (select count(*) from public.resellers
                                     where status = 'pending' and coalesce(kyc_status, 'unverified') <> 'verified'),
    'oldest_application_at', (select min(coalesce(applied_at, created_at)) from public.resellers where status = 'pending'),
    'membership_payments_to_verify', (select count(*) from public.reseller_membership_orders where status = 'processing'),
    'membership_orders_awaiting_payment', (select count(*) from public.reseller_membership_orders where status = 'pending'),
    'memberships_expiring_30d', (select count(*) from public.reseller_memberships
                                  where status = 'active' and expires_at between now() and now() + interval '30 days'),
    'commission_available', coalesce((
      select jsonb_agg(jsonb_build_object('currency', currency, 'amount', amount, 'resellers', resellers) order by currency)
        from (select currency, sum(commission_amount) as amount, count(distinct reseller_id) as resellers
                from public.reseller_commissions
               where status = 'available' and payout_id is null
               group by currency) c), '[]'::jsonb),
    'payouts_awaiting_action', (select count(*) from public.reseller_payouts where status in ('pending', 'approved', 'processing')),
    'suspended', (select count(*) from public.resellers where status in ('paused', 'suspended'))
  );
end;
$$;


--
-- Name: mm_reseller_code_create(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_reseller_code_create(p_id uuid, p_code text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp', 'extensions'
    AS $$
declare
  v_alphabet constant text := 'ABCDEFGHJKMNPQRSTUVWXYZ23456789';
  v_name text; v_status text; v_code text; v_bytes bytea; i integer; v_row jsonb;
begin
  if not public.mm_reseller_operator() then
    return jsonb_build_object('ok', false, 'reason', 'not_permitted');
  end if;

  select name, status into v_name, v_status from public.resellers where id = p_id;
  if v_name is null then
    return jsonb_build_object('ok', false, 'reason', 'unknown_reseller');
  end if;
  if v_status <> 'active' then
    return jsonb_build_object('ok', false, 'reason', 'not_active',
      'message', 'Only an active reseller can be given a working referral link.');
  end if;

  if p_code is not null and btrim(p_code) <> '' then
    v_code := upper(regexp_replace(btrim(p_code), '[^A-Za-z0-9-]', '', 'g'));
    if length(v_code) < 3 then
      return jsonb_build_object('ok', false, 'reason', 'code_too_short');
    end if;
    if exists (select 1 from public.marketplace_referral_codes where upper(code) = v_code) then
      return jsonb_build_object('ok', false, 'reason', 'code_taken',
        'message', 'Another referral code already uses that word.');
    end if;
  else
    for attempt in 1..10 loop
      v_code := '';
      v_bytes := gen_random_bytes(8);
      for i in 0..7 loop
        v_code := v_code || substr(v_alphabet, (get_byte(v_bytes, i) % length(v_alphabet)) + 1, 1);
      end loop;
      exit when not exists (
        select 1 from public.marketplace_referral_codes where upper(code) = v_code);
      v_code := null;
    end loop;
    if v_code is null then
      return jsonb_build_object('ok', false, 'reason', 'could_not_generate');
    end if;
  end if;

  insert into public.marketplace_referral_codes (reseller_id, code, active)
  values (p_id, v_code, true)
  returning to_jsonb(marketplace_referral_codes) into v_row;

  perform public.mm_audit('reseller.code_created', 'reseller', p_id::text, null,
                          jsonb_build_object('code', v_code), null);

  return jsonb_build_object('ok', true, 'code', v_code, 'row', v_row,
    'share_url', 'https://softwarevala.net/?ref=' || v_code);
end;
$$;


--
-- Name: mm_reseller_detail(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_reseller_detail(p_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_r jsonb;
begin
  if not public.mm_reseller_operator() then
    return jsonb_build_object('ok', false, 'reason', 'not_permitted');
  end if;
  select to_jsonb(r) into v_r from public.resellers r where r.id = p_id;
  if v_r is null then
    return jsonb_build_object('ok', false, 'reason', 'unknown_reseller');
  end if;

  return jsonb_build_object(
    'ok', true,
    'reseller', v_r,
    'plan', (select to_jsonb(p) from public.reseller_membership_plans p
              where p.code = (v_r->>'plan_code')),
    'schedule', coalesce(
      (select to_jsonb(s) from public.reseller_payout_schedules s where s.reseller_id = p_id),
      jsonb_build_object('reseller_id', p_id, 'cadence','monthly', 'holding_days',14,
                         'minimum_amount',50, 'currency','USD', 'requires_approval',true,
                         'defaulted',true)),

    'codes', coalesce((
      select jsonb_agg(jsonb_build_object(
               'id', c.id, 'code', c.code, 'active', c.active,
               'url', 'https://softwarevala.net/?ref=' || c.code,
               'clicks', (select count(*) from public.marketplace_referral_sessions s
                           where s.referral_code_id = c.id),
               'conversions', (select count(*) from public.marketplace_order_attributions a
                                where a.referral_code_id = c.id))
             order by c.created_at desc)
        from public.marketplace_referral_codes c where c.reseller_id = p_id), '[]'::jsonb),

    'commissions', coalesce((
      select jsonb_agg(jsonb_build_object(
               'id', c.id, 'order_id', c.order_id, 'gross', c.gross_amount,
               'commission', c.commission_amount, 'currency', c.currency,
               'status', c.status, 'payout_id', c.payout_id,
               'created_at', c.created_at,
               -- The reason this line paid what it paid, kept from the moment
               -- of the sale.
               'rate', c.rule_snapshot)
             order by c.created_at desc)
        from public.reseller_commissions c where c.reseller_id = p_id), '[]'::jsonb),

    'payouts', coalesce((
      select jsonb_agg(jsonb_build_object(
               'id', o.id, 'amount', o.amount, 'currency', o.currency,
               'status', o.status, 'method', o.payment_method,
               'provider_reference', o.provider_reference,
               'failure_reason', o.failure_reason,
               'requested_at', o.requested_at, 'approved_at', o.approved_at,
               'processed_at', o.processed_at, 'completed_at', o.completed_at,
               'lines', (select count(*) from public.reseller_commissions c
                          where c.payout_id = o.id))
             order by o.requested_at desc)
        from public.reseller_payouts o where o.reseller_id = p_id), '[]'::jsonb),

    'rules', coalesce((
      select jsonb_agg(to_jsonb(x) order by x.priority desc)
        from public.reseller_commission_rules x where x.reseller_id = p_id), '[]'::jsonb),

    'ledger', coalesce((
      select jsonb_agg(to_jsonb(l) order by l.created_at desc)
        from public.marketplace_ledger_entries l where l.reseller_id = p_id), '[]'::jsonb),

    'memberships', coalesce((
      select jsonb_agg(to_jsonb(m) order by m.created_at desc)
        from public.reseller_memberships m where m.reseller_id = p_id), '[]'::jsonb),

    'audit', coalesce((
      select jsonb_agg(jsonb_build_object(
               'action', a.action, 'at', a.created_at, 'actor', a.actor_id,
               'reason', a.reason, 'before', a.before_state, 'after', a.after_state)
             order by a.created_at desc)
        from public.marketplace_audit_logs a
       where a.entity_id = p_id and a.created_at > now() - interval '180 days'), '[]'::jsonb));
end;
$$;


--
-- Name: mm_reseller_earnings_release(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_reseller_earnings_release(p_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_n integer;
begin
  if not public.mm_reseller_operator() then
    return jsonb_build_object('ok', false, 'reason', 'not_permitted');
  end if;

  with due as (
    select c.id from public.reseller_commissions c
      left join public.reseller_payout_schedules s on s.reseller_id = c.reseller_id
     where c.status = 'pending'
       and (p_id is null or c.reseller_id = p_id)
       and c.created_at <= now() - (coalesce(s.holding_days,14) || ' days')::interval
       -- A line whose order was refunded never becomes payable, which is the
       -- whole reason the holding period exists.
       and not exists (select 1 from public.marketplace_orders o
                        where o.id = c.order_id and o.status in ('refunded','cancelled'))
  )
  update public.reseller_commissions c set status='available', updated_at=now()
    from due where c.id = due.id;
  get diagnostics v_n = row_count;

  if v_n > 0 then
    perform public.mm_audit('reseller.earnings_released', 'reseller',
                            coalesce(p_id::text,'all'), null,
                            jsonb_build_object('released', v_n), null);
  end if;
  return jsonb_build_object('ok', true, 'released', v_n);
end;
$$;


--
-- Name: mm_reseller_operator(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_reseller_operator() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select public.reseller_is_finance() or public.mm_is_operator();
$$;


--
-- Name: mm_reseller_payout_create(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_reseller_payout_create(p_id uuid, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_ids uuid[]; v_amount numeric; v_min numeric; v_currency text; v_method text;
  v_key text; v_attempt integer; v_payout jsonb; v_user uuid;
begin
  if not public.mm_reseller_operator() then
    return jsonb_build_object('ok', false, 'reason', 'not_permitted');
  end if;

  select r.user_id into v_user from public.resellers r where r.id = p_id;
  if not found then
    return jsonb_build_object('ok', false, 'reason', 'unknown_reseller');
  end if;

  select coalesce(s.minimum_amount,50), coalesce(s.currency,'USD'), s.payment_method
    into v_min, v_currency, v_method
    from public.resellers r
    left join public.reseller_payout_schedules s on s.reseller_id = r.id
   where r.id = p_id;

  select array_agg(c.id order by c.id), coalesce(sum(c.commission_amount),0)
    into v_ids, v_amount
    from public.reseller_commissions c
   where c.reseller_id = p_id and c.status = 'available' and c.payout_id is null;

  if v_ids is null or array_length(v_ids,1) = 0 then
    return jsonb_build_object('ok', false, 'reason', 'nothing_available',
      'message', 'This reseller has no released commission waiting. Release the holding period first.');
  end if;
  if v_amount < v_min then
    return jsonb_build_object('ok', false, 'reason', 'below_minimum',
      'message', format('Available %s is under the %s minimum for this reseller.',
                        round(v_amount,2), round(v_min,2)),
      'available', v_amount, 'minimum', v_min);
  end if;

  -- The attempt count is part of the key so that a failed transfer can be
  -- retried, while re-running the same request still collides and refuses.
  select count(*) into v_attempt from public.reseller_payouts
   where reseller_id = p_id and status in ('failed','cancelled','reversed');

  v_key := 'reseller_payout:' || p_id::text || ':'
           || md5(array_to_string(v_ids, ',')) || ':' || v_attempt::text;

  if exists (select 1 from public.reseller_payouts where idempotency_key = v_key) then
    return jsonb_build_object('ok', false, 'reason', 'already_created',
      'message', 'A payout for exactly this commission already exists.');
  end if;

  insert into public.reseller_payouts
    (reseller_id, amount, currency, status, payment_method, idempotency_key)
  values (p_id, v_amount, v_currency, 'pending', v_method, v_key)
  returning to_jsonb(reseller_payouts) into v_payout;

  update public.reseller_commissions
     set payout_id = (v_payout->>'id')::uuid, updated_at = now()
   where id = any(v_ids);

  perform public.mm_audit('reseller.payout_requested', 'reseller_payout',
                          (v_payout->>'id'), null,
                          v_payout || jsonb_build_object('lines', array_length(v_ids,1)),
                          p_reason);

  if v_user is not null then
    perform public.mm_notify('reseller.payout_requested', 'A payout has been prepared',
      format('%s %s covering %s sale(s) is awaiting approval.',
             round(v_amount,2), v_currency, array_length(v_ids,1)),
      v_user, null, '/reseller-manager', 'View', 60, 'info');
  end if;

  return jsonb_build_object('ok', true, 'payout', v_payout,
                            'lines', array_length(v_ids,1));
end;
$$;


--
-- Name: mm_reseller_payout_status(uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_reseller_payout_status(p_payout uuid, p_to text, p_reference text DEFAULT NULL::text, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_before jsonb; v_after jsonb; v_reseller uuid; v_user uuid; v_allowed boolean;
begin
  if not public.mm_reseller_operator() then
    return jsonb_build_object('ok', false, 'reason', 'not_permitted');
  end if;
  if p_to not in ('pending','approved','processing','paid','failed','reversed','cancelled') then
    return jsonb_build_object('ok', false, 'reason', 'unknown_status');
  end if;

  select to_jsonb(o), o.reseller_id into v_before, v_reseller
    from public.reseller_payouts o where o.id = p_payout;
  if v_before is null then
    return jsonb_build_object('ok', false, 'reason', 'unknown_payout');
  end if;

  -- Reversing a paid payout is a real event, so it is allowed; reopening one to
  -- any other state is not, because the commission would be payable twice.
  if (v_before->>'status') = 'paid' and p_to <> 'reversed' then
    return jsonb_build_object('ok', false, 'reason', 'already_paid',
      'message', 'This payout is settled. It can only be reversed, not reopened.');
  end if;

  v_allowed := case (v_before->>'status')
    when 'pending'    then p_to in ('approved','cancelled','failed')
    when 'approved'   then p_to in ('processing','cancelled','failed')
    when 'processing' then p_to in ('paid','failed')
    when 'failed'     then p_to in ('pending','cancelled')
    when 'cancelled'  then p_to in ('pending')
    when 'paid'       then p_to = 'reversed'
    else false end;
  if not v_allowed then
    return jsonb_build_object('ok', false, 'reason', 'invalid_transition',
      'message', format('A %s payout cannot become %s.', v_before->>'status', p_to));
  end if;

  -- Nothing is recorded as paid on somebody's say-so.
  if p_to = 'paid' and coalesce(btrim(p_reference),'') = '' then
    return jsonb_build_object('ok', false, 'reason', 'reference_required',
      'message', 'A payout is only paid once the provider has paid it. Enter the '
                 'bank or provider transaction reference.');
  end if;
  if p_to in ('failed','reversed') and coalesce(btrim(p_reason),'') = '' then
    return jsonb_build_object('ok', false, 'reason', 'reason_required',
      'message', 'Record why this payout failed or was reversed.');
  end if;

  update public.reseller_payouts
     set status = p_to,
         provider_reference = coalesce(nullif(btrim(p_reference),''), provider_reference),
         failure_reason = case when p_to in ('failed','reversed') then p_reason
                               else failure_reason end,
         approved_at   = case when p_to='approved'   then now() else approved_at end,
         processed_at  = case when p_to='processing' then now() else processed_at end,
         completed_at  = case when p_to='paid'       then now() else completed_at end,
         updated_at = now()
   where id = p_payout returning to_jsonb(reseller_payouts) into v_after;

  if p_to = 'paid' then
    update public.reseller_commissions
       set status='paid', updated_at=now() where payout_id = p_payout;

    insert into public.marketplace_ledger_entries
      (reseller_id, entry_type, amount, currency, immutable_metadata)
    values (v_reseller, 'payout', (v_after->>'amount')::numeric, v_after->>'currency',
            jsonb_build_object(
              'payout_id', p_payout,
              'idempotency_key', v_after->>'idempotency_key',
              'provider_reference', v_after->>'provider_reference',
              'commission_ids', (select coalesce(jsonb_agg(c.id),'[]'::jsonb)
                                   from public.reseller_commissions c
                                  where c.payout_id = p_payout),
              'settled_at', now(),
              'audit_reference', 'reseller.payout_paid'));

  elsif p_to in ('failed','cancelled') then
    -- The commission goes back in the queue rather than being lost.
    update public.reseller_commissions
       set payout_id = null, updated_at = now() where payout_id = p_payout;

  elsif p_to = 'reversed' then
    -- Money that went out and came back. The lines return to available and the
    -- ledger carries the counter-entry rather than the original being edited.
    update public.reseller_commissions
       set status='available', payout_id=null, updated_at=now() where payout_id = p_payout;

    insert into public.marketplace_ledger_entries
      (reseller_id, entry_type, amount, currency, immutable_metadata)
    values (v_reseller, 'adjustment', -1 * (v_after->>'amount')::numeric,
            v_after->>'currency',
            jsonb_build_object('payout_id', p_payout, 'reason', p_reason,
                               'reverses', v_after->>'idempotency_key',
                               'audit_reference', 'reseller.payout_reversed'));
  end if;

  perform public.mm_audit('reseller.payout_' || p_to, 'reseller_payout',
                          p_payout::text, v_before, v_after, p_reason);

  select user_id into v_user from public.resellers where id = v_reseller;
  if v_user is not null and p_to in ('approved','paid','failed','reversed') then
    perform public.mm_notify('reseller.payout_' || p_to,
      case p_to when 'paid' then 'Your payout has been sent'
                when 'approved' then 'Your payout is approved'
                when 'reversed' then 'A payout has been reversed'
                else 'Your payout could not be sent' end,
      case p_to when 'paid'
        then format('%s %s, reference %s.', round((v_after->>'amount')::numeric,2),
                    v_after->>'currency', coalesce(v_after->>'provider_reference','—'))
        else coalesce(p_reason, 'Your commission is back in the queue.') end,
      v_user, null, '/reseller-manager', 'View', 5,
      case p_to when 'paid' then 'success' when 'approved' then 'info' else 'danger' end);
  end if;

  return jsonb_build_object('ok', true, 'payout', v_after);
end;
$$;


--
-- Name: mm_reseller_plan(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_reseller_plan(p_id uuid, p_plan text, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_before jsonb; v_after jsonb;
begin
  if not public.mm_reseller_operator() then
    return jsonb_build_object('ok', false, 'reason', 'not_permitted');
  end if;
  if p_plan is not null and not exists (
    select 1 from public.reseller_membership_plans where code = p_plan and enabled) then
    return jsonb_build_object('ok', false, 'reason', 'unknown_plan',
      'message', 'That is not an enabled reseller plan.');
  end if;

  select to_jsonb(r) into v_before from public.resellers r where r.id = p_id;
  if v_before is null then
    return jsonb_build_object('ok', false, 'reason', 'unknown_reseller');
  end if;

  update public.resellers set plan_code = p_plan, updated_at = now()
   where id = p_id returning to_jsonb(resellers) into v_after;

  perform public.mm_audit('reseller.plan', 'reseller', p_id::text,
                          v_before, v_after, p_reason);
  return jsonb_build_object('ok', true, 'reseller', v_after,
    'note', 'This sets the margin for future sales. Commission already earned keeps '
            'the rate recorded on it at the time.');
end;
$$;


--
-- Name: mm_reseller_schedule_set(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_reseller_schedule_set(p_patch jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_id uuid := (p_patch->>'reseller_id')::uuid; v_before jsonb; v_after jsonb;
begin
  if not public.mm_reseller_operator() then
    return jsonb_build_object('ok', false, 'reason', 'not_permitted');
  end if;
  if v_id is null or not exists (select 1 from public.resellers where id = v_id) then
    return jsonb_build_object('ok', false, 'reason', 'unknown_reseller');
  end if;

  select to_jsonb(x) into v_before
    from public.reseller_payout_schedules x where x.reseller_id = v_id;

  insert into public.reseller_payout_schedules as s
    (reseller_id, cadence, holding_days, minimum_amount, currency,
     requires_approval, payment_method)
  values (v_id,
          coalesce(p_patch->>'cadence','monthly'),
          coalesce((p_patch->>'holding_days')::int, 14),
          coalesce((p_patch->>'minimum_amount')::numeric, 50),
          upper(coalesce(p_patch->>'currency','USD')),
          coalesce((p_patch->>'requires_approval')::boolean, true),
          nullif(p_patch->>'payment_method',''))
  on conflict (reseller_id) do update set
    cadence = coalesce(excluded.cadence, s.cadence),
    holding_days = coalesce(excluded.holding_days, s.holding_days),
    minimum_amount = coalesce(excluded.minimum_amount, s.minimum_amount),
    currency = coalesce(excluded.currency, s.currency),
    requires_approval = coalesce(excluded.requires_approval, s.requires_approval),
    payment_method = coalesce(excluded.payment_method, s.payment_method),
    updated_at = now()
  returning to_jsonb(s) into v_after;

  perform public.mm_audit('reseller.payout_schedule', 'reseller', v_id::text,
                          v_before, v_after, null);
  return jsonb_build_object('ok', true, 'schedule', v_after);
end;
$$;


--
-- Name: mm_reseller_status(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_reseller_status(p_id uuid, p_to text, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_before jsonb; v_after jsonb; v_user uuid; v_status text;
begin
  if not public.mm_reseller_operator() then
    return jsonb_build_object('ok', false, 'reason', 'not_permitted');
  end if;
  if p_to not in ('pending','active','paused','suspended','rejected','terminated') then
    return jsonb_build_object('ok', false, 'reason', 'unknown_status');
  end if;

  select to_jsonb(r), r.user_id, r.status into v_before, v_user, v_status from public.resellers r where r.id = p_id;
  if v_before is null then
    return jsonb_build_object('ok', false, 'reason', 'unknown_reseller');
  end if;
  -- Terminated is final. Returning means a new application, approved afresh.
  if v_status = 'terminated' then
    return jsonb_build_object('ok', false, 'reason', 'terminated_final',
      'message', 'This reseller is terminated. Termination is final; the person must submit a new application, which is approved on its own.');
  end if;
  -- Nobody decides on their own reseller account.
  if v_user is not null and v_user = auth.uid() then
    return jsonb_build_object('ok', false, 'reason', 'self_action',
      'message', 'You cannot change the status of your own reseller account.');
  end if;

  if p_to in ('suspended','rejected','terminated') and coalesce(btrim(p_reason),'') = '' then
    return jsonb_build_object('ok', false, 'reason', 'reason_required',
      'message', 'Say why. This stops the reseller earning and is recorded permanently.');
  end if;

  update public.resellers
     set status = p_to,
         approved_at = case when p_to='active' then coalesce(approved_at, now()) else approved_at end,
         approved_by = case when p_to='active' then coalesce(approved_by, auth.uid()) else approved_by end,
         updated_at = now()
   where id = p_id returning to_jsonb(resellers) into v_after;

  -- The account behind the reseller gets (or loses) the reseller role, which
  -- is what opens the reseller dashboard.
  if v_user is not null then
    if p_to = 'active' then
      insert into public.user_roles (user_id, role) values (v_user, 'reseller')
      on conflict do nothing;
    elsif p_to in ('rejected','terminated') then
      delete from public.user_roles where user_id = v_user and role = 'reseller';
    end if;
  end if;

  if p_to in ('paused','suspended','rejected','terminated') then
    update public.marketplace_referral_codes set active = false, updated_at = now()
     where reseller_id = p_id and active;
  elsif p_to = 'active' then
    update public.marketplace_referral_codes set active = true, updated_at = now()
     where reseller_id = p_id and not active;
  end if;

  perform public.mm_audit('reseller.' || p_to, 'reseller', p_id::text, v_before, v_after, p_reason);

  if v_user is not null then
    perform public.mm_notify('reseller.' || p_to,
      case p_to when 'active' then 'Your reseller account is approved'
                when 'rejected' then 'Your reseller application was not accepted'
                when 'suspended' then 'Your reseller account is suspended'
                when 'paused' then 'Your reseller account is paused'
                when 'terminated' then 'Your reseller account is closed'
                else 'Your reseller account status changed' end,
      coalesce(p_reason,''), v_user, null, '/dashboard/reseller', 'Open', 5,
      case p_to when 'active' then 'success'
                when 'rejected' then 'warning'
                when 'paused' then 'warning' else 'danger' end);
  end if;

  return jsonb_build_object('ok', true, 'reseller', v_after);
end;
$$;


--
-- Name: mm_resellers(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_resellers(p_query jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_search text := nullif(btrim(coalesce(p_query->>'search','')), '');
  v_status text := nullif(p_query->>'status','');
  v_plan   text := nullif(p_query->>'plan','');
  v_limit  integer := least(greatest(coalesce((p_query->>'limit')::int, 100), 1), 500);
begin
  if not public.mm_reseller_operator() then
    return jsonb_build_object('ok', false, 'reason', 'not_permitted');
  end if;

  return jsonb_build_object(
    'ok', true,

    'total',      (select count(*) from public.resellers),
    'active',     (select count(*) from public.resellers where status='active'),
    'pending',    (select count(*) from public.resellers where status='pending'),
    'suspended',  (select count(*) from public.resellers
                    where status in ('suspended','paused','rejected','terminated')),
    'unplanned',  (select count(*) from public.resellers where plan_code is null),

    -- Tracking, through the canonical referral tables rather than a second set.
    'referral_codes', (select count(*) from public.marketplace_referral_codes
                        where reseller_id is not null),
    'clicks',     (select count(*) from public.marketplace_referral_sessions
                    where reseller_id is not null),
    'conversions',(select count(*) from public.marketplace_order_attributions
                    where reseller_id is not null),

    'sales',      (select count(*) from public.reseller_commissions where status <> 'reversed'),
    'revenue',    (select coalesce(sum(gross_amount),0) from public.reseller_commissions
                    where status <> 'reversed'),
    'commission_total', (select coalesce(sum(commission_amount),0)
                           from public.reseller_commissions where status <> 'reversed'),
    'commission_pending', (select coalesce(sum(commission_amount),0)
                             from public.reseller_commissions where status = 'pending'),
    'commission_available', (select coalesce(sum(commission_amount),0)
                               from public.reseller_commissions
                              where status = 'available' and payout_id is null),
    'commission_paid', (select coalesce(sum(commission_amount),0)
                          from public.reseller_commissions where status = 'paid'),
    'commission_reversed', (select coalesce(sum(commission_amount),0)
                              from public.reseller_commissions where status = 'reversed'),

    'payouts_total',   (select coalesce(sum(amount),0) from public.reseller_payouts),
    'payouts_paid',    (select coalesce(sum(amount),0) from public.reseller_payouts
                         where status='paid'),
    'payouts_pending', (select coalesce(sum(amount),0) from public.reseller_payouts
                         where status in ('pending','approved','processing')),

    'plans', coalesce((
      select jsonb_agg(jsonb_build_object(
               'code', p.code, 'name', p.name, 'price_usd', p.price_usd,
               'profit_percent', p.profit_percent, 'validity_days', p.validity_days,
               'enabled', p.enabled,
               'resellers', (select count(*) from public.resellers r where r.plan_code = p.code),
               'memberships', (select count(*) from public.reseller_memberships m
                                where m.plan_code = p.code))
             order by p.sort_order)
        from public.reseller_membership_plans p), '[]'::jsonb),

    -- Said plainly rather than shown as a zero that would look like an answer.
    'unavailable', jsonb_build_object(
      'plan_revenue', 'No reseller has bought a plan yet: reseller_memberships and '
                      'reseller_membership_orders are both empty, so there is no plan revenue to report.',
      'finance_tables', 'finance_commissions and finance_payouts are not used here. They hold '
                        'eighty identical rows for one invented partner and seventy payouts to a '
                        'single name that matches no reseller — seeded demo data, deliberately not '
                        'presented as reseller earnings.'),

    'resellers', coalesce((
      select jsonb_agg(jsonb_build_object(
               'id', r.id, 'name', r.name, 'code', r.code, 'email', r.email,
               'phone', r.phone, 'region', r.region, 'tier', r.tier,
               'status', r.status, 'kyc_status', r.kyc_status,
               'company_name', r.company_name, 'plan_code', r.plan_code,
               'user_id', r.user_id,
               'created_at', r.created_at, 'last_active_at', r.last_active_at,
               'plan', (select jsonb_build_object('name', p.name, 'profit_percent', p.profit_percent)
                          from public.reseller_membership_plans p where p.code = r.plan_code),
               'referral_codes', (select coalesce(jsonb_agg(c.code), '[]'::jsonb)
                                    from public.marketplace_referral_codes c
                                   where c.reseller_id = r.id and c.active),
               'clicks', (select count(*) from public.marketplace_referral_sessions s
                           where s.reseller_id = r.id),
               'conversions', (select count(*) from public.marketplace_order_attributions a
                                where a.reseller_id = r.id),
               'sales', (select count(*) from public.reseller_commissions c2
                          where c2.reseller_id = r.id and c2.status <> 'reversed'),
               'revenue', (select coalesce(sum(c2.gross_amount),0) from public.reseller_commissions c2
                            where c2.reseller_id = r.id and c2.status <> 'reversed'),
               'commission', (select coalesce(sum(c2.commission_amount),0)
                                from public.reseller_commissions c2
                               where c2.reseller_id = r.id and c2.status <> 'reversed'),
               'available', (select coalesce(sum(c2.commission_amount),0)
                               from public.reseller_commissions c2
                              where c2.reseller_id = r.id and c2.status = 'available'
                                and c2.payout_id is null),
               'paid_out', (select coalesce(sum(o.amount),0) from public.reseller_payouts o
                             where o.reseller_id = r.id and o.status = 'paid'))
             order by r.created_at desc)
        from (select * from public.resellers r2
               where (v_status is null or r2.status = v_status)
                 and (v_plan is null or r2.plan_code = v_plan)
                 and (v_search is null
                      or r2.name ilike '%'||v_search||'%'
                      or r2.email ilike '%'||v_search||'%'
                      or r2.code ilike '%'||v_search||'%'
                      or coalesce(r2.company_name,'') ilike '%'||v_search||'%'
                      or coalesce(r2.region,'') ilike '%'||v_search||'%')
               order by r2.created_at desc limit v_limit) r), '[]'::jsonb));
end;
$$;


--
-- Name: mm_review_analytics(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_review_analytics(p_days integer DEFAULT 30) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_from timestamptz; v_published integer; v_decided integer; v_total integer;
begin
  if not public.mm_is_operator() then
    return jsonb_build_object('ok', false, 'reason', 'not_permitted');
  end if;
  v_from := now() - (greatest(least(coalesce(p_days,30), 3650), 1) || ' days')::interval;

  select count(*) filter (where status='published'),
         count(*) filter (where status in ('published','rejected')),
         count(*)
    into v_published, v_decided, v_total
    from public.marketplace_reviews where created_at >= v_from;

  return jsonb_build_object(
    'ok', true, 'days', p_days, 'from', v_from,
    'volume', v_total,
    'published', v_published,
    'average_rating', (select round(avg(rating)::numeric,2) from public.marketplace_reviews
                        where status='published' and created_at >= v_from),
    'distribution', coalesce((
      select jsonb_object_agg(rating::text, n)
        from (select rating, count(*) n from public.marketplace_reviews
               where status='published' and created_at >= v_from group by rating) t), '{}'::jsonb),

    -- Every review is bound to an order line, so this is always 100 when there
    -- are any. It is computed rather than asserted so it stays true if that
    -- constraint ever changes.
    'verified_percent', case when v_total = 0 then null
      else round(100.0 * (select count(*) from public.marketplace_reviews
                           where created_at >= v_from and order_item_id is not null) / v_total, 1) end,

    'approval_rate', case when v_decided = 0 then null
      else round(100.0 * v_published / v_decided, 1) end,
    'rejection_rate', case when v_decided = 0 then null
      else round(100.0 * (v_decided - v_published) / v_decided, 1) end,
    'report_rate', case when v_total = 0 then null
      else round(100.0 * (select count(distinct review_id) from public.review_reports
                           where created_at >= v_from) / v_total, 1) end,
    'response_rate', case when v_published = 0 then null
      else round(100.0 * (select count(distinct rp.review_id)
                            from public.review_replies rp
                            join public.marketplace_reviews r on r.id = rp.review_id
                           where rp.status='published' and r.created_at >= v_from) / v_published, 1) end,

    'by_day', coalesce((
      select jsonb_agg(jsonb_build_object('day', d, 'reviews', n, 'average', avg_r) order by d)
        from (select date_trunc('day', created_at)::date d, count(*) n,
                     round(avg(rating)::numeric,2) avg_r
                from public.marketplace_reviews
               where created_at >= v_from group by 1) t), '[]'::jsonb),

    'by_product', coalesce((
      select jsonb_agg(jsonb_build_object(
               'product_id', t.product_id,
               'product', (select name from public.marketplace_products p where p.id = t.product_id),
               'reviews', t.n, 'average', t.avg_r) order by t.n desc)
        from (select product_id, count(*) n, round(avg(rating)::numeric,2) avg_r
                from public.marketplace_reviews
               where status='published' and created_at >= v_from
               group by product_id limit 20) t), '[]'::jsonb),

    -- Seller-side ratings, joined through the product's owner. Empty while the
    -- catalogue is first-party, which is the honest answer rather than a zero.
    'by_seller', coalesce((
      select jsonb_agg(jsonb_build_object(
               'seller_id', t.seller_id, 'seller', t.display_name, 'kind', t.seller_kind,
               'reviews', t.n, 'average', t.avg_r) order by t.n desc)
        from (select s.id seller_id, s.display_name, s.seller_kind,
                     count(*) n, round(avg(r.rating)::numeric,2) avg_r
                from public.marketplace_reviews r
                join public.marketplace_products p on p.id = r.product_id
                join public.marketplace_sellers s on s.id = p.seller_id
               where r.status='published' and r.created_at >= v_from
               group by s.id, s.display_name, s.seller_kind) t), '[]'::jsonb));
end;
$$;


--
-- Name: mm_review_moderate(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_review_moderate(p_id uuid, p_to text, p_note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_before jsonb; v_after jsonb; v_product uuid; v_buyer uuid;
begin
  if not public.mm_is_operator() then
    return jsonb_build_object('ok', false, 'reason', 'not_permitted');
  end if;
  if p_to not in ('pending','published','rejected','removed','hidden','archived') then
    return jsonb_build_object('ok', false, 'reason', 'unknown_status');
  end if;

  select to_jsonb(r), r.product_id, r.buyer_id into v_before, v_product, v_buyer
    from public.marketplace_reviews r where r.id = p_id;
  if v_before is null then
    return jsonb_build_object('ok', false, 'reason', 'unknown_review');
  end if;

  -- Rejecting or hiding someone's words is a decision that needs a reason on
  -- the record, not a silent disappearance.
  if p_to in ('rejected','hidden') and coalesce(btrim(p_note),'') = '' then
    return jsonb_build_object('ok', false, 'reason', 'note_required',
      'message', 'Say why this review is being rejected or hidden. It is recorded and the author is told.');
  end if;

  update public.marketplace_reviews
     set status = p_to,
         moderated_by = auth.uid(), moderated_at = now(),
         moderation_note = coalesce(nullif(btrim(p_note),''), moderation_note),
         published_at = case when p_to='published' then coalesce(published_at, now())
                             else published_at end,
         updated_at = now()
   where id = p_id returning to_jsonb(marketplace_reviews) into v_after;

  perform public.mm_product_rating_refresh(v_product);
  perform public.mm_audit('review.'||p_to, 'marketplace_review', p_id::text,
                          v_before, v_after, p_note);

  if v_buyer is not null and p_to in ('published','rejected') then
    perform public.mm_notify('review.'||p_to,
      case p_to when 'published' then 'Your review is live'
                else 'Your review was not published' end,
      coalesce(p_note,''), v_buyer, null, '/account/reviews', 'View', 5,
      case p_to when 'published' then 'success' else 'warning' end);
  end if;

  return jsonb_build_object('ok', true, 'review', v_after);
end;
$$;


--
-- Name: mm_review_reply(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_review_reply(p_review uuid, p_content text, p_role text DEFAULT 'official'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_row jsonb; v_buyer uuid;
begin
  if not public.mm_is_operator() then
    return jsonb_build_object('ok', false, 'reason', 'not_permitted');
  end if;
  if p_role not in ('official','vendor','author','reseller') then
    return jsonb_build_object('ok', false, 'reason', 'unknown_role');
  end if;
  if coalesce(btrim(p_content),'') = '' then
    return jsonb_build_object('ok', false, 'reason', 'empty_reply');
  end if;

  select buyer_id into v_buyer from public.marketplace_reviews where id = p_review;
  if not found then
    return jsonb_build_object('ok', false, 'reason', 'unknown_review');
  end if;

  insert into public.review_replies (review_id, author_id, author_role, content, status)
  values (p_review, auth.uid(), p_role, btrim(p_content), 'published')
  returning to_jsonb(review_replies) into v_row;

  perform public.mm_audit('review.replied', 'marketplace_review', p_review::text,
                          null, v_row, null);

  if v_buyer is not null then
    perform public.mm_notify('review.reply', 'Someone replied to your review',
      left(btrim(p_content), 160), v_buyer, null, '/account/reviews', 'Read', 5, 'info');
  end if;

  return jsonb_build_object('ok', true, 'reply', v_row);
end;
$$;


--
-- Name: mm_review_report_resolve(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_review_report_resolve(p_report uuid, p_to text, p_resolution text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_before jsonb; v_after jsonb;
begin
  if not public.mm_is_operator() then
    return jsonb_build_object('ok', false, 'reason', 'not_permitted');
  end if;
  if p_to not in ('investigating','upheld','dismissed') then
    return jsonb_build_object('ok', false, 'reason', 'unknown_status');
  end if;
  if p_to in ('upheld','dismissed') and coalesce(btrim(p_resolution),'') = '' then
    return jsonb_build_object('ok', false, 'reason', 'resolution_required',
      'message', 'Record the finding. A report is closed with a reason, not silently.');
  end if;

  select to_jsonb(r) into v_before from public.review_reports r where r.id = p_report;
  if v_before is null then
    return jsonb_build_object('ok', false, 'reason', 'unknown_report');
  end if;

  update public.review_reports
     set status = p_to, resolution = p_resolution,
         resolved_by = case when p_to in ('upheld','dismissed') then auth.uid() else resolved_by end,
         resolved_at = case when p_to in ('upheld','dismissed') then now() else resolved_at end
   where id = p_report returning to_jsonb(review_reports) into v_after;

  perform public.mm_audit('review.report_'||p_to, 'review_report', p_report::text,
                          v_before, v_after, p_resolution);
  return jsonb_build_object('ok', true, 'report', v_after);
end;
$$;


--
-- Name: mm_reviews(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_reviews(p_query jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_tab    text := coalesce(p_query->>'tab','queue');
  v_search text := nullif(btrim(coalesce(p_query->>'search','')),'');
  v_limit  integer := least(greatest(coalesce((p_query->>'limit')::int,50),1),200);
begin
  if not public.mm_is_operator() then
    return jsonb_build_object('ok', false, 'reason', 'not_permitted');
  end if;

  return jsonb_build_object(
    'ok', true, 'tab', v_tab,

    -- Every figure counted, none stored.
    'total',      (select count(*) from public.marketplace_reviews),
    'pending',    (select count(*) from public.marketplace_reviews where status='pending'),
    'published',  (select count(*) from public.marketplace_reviews where status='published'),
    'rejected',   (select count(*) from public.marketplace_reviews where status='rejected'),
    'hidden',     (select count(*) from public.marketplace_reviews where status='hidden'),
    'reported',   (select count(*) from public.review_reports where status in ('open','investigating')),
    'replies',    (select count(*) from public.review_replies where status='published'),
    'video',      (select count(*) from public.marketplace_reviews where review_type='video'),

    'average_rating', (select round(avg(rating)::numeric,2) from public.marketplace_reviews
                        where status='published'),
    'distribution', coalesce((
      select jsonb_object_agg(rating::text, n)
        from (select rating, count(*) n from public.marketplace_reviews
               where status='published' group by rating) t), '{}'::jsonb),

    -- Every review is bound to an order line by the schema, so the verified
    -- share is always the whole of it. Stated rather than computed to look busy.
    'verified_note', 'marketplace_reviews.order_item_id is NOT NULL, so a review '
                     'cannot exist without the purchase behind it. Every review here '
                     'is a verified purchase by construction.',

    'response_rate', case
      when (select count(*) from public.marketplace_reviews where status='published') = 0 then null
      else round(100.0 * (select count(distinct review_id) from public.review_replies
                           where status='published')
                 / (select count(*) from public.marketplace_reviews where status='published'), 1)
      end,
    'approval_rate', case
      when (select count(*) from public.marketplace_reviews
             where status in ('published','rejected')) = 0 then null
      else round(100.0 * (select count(*) from public.marketplace_reviews where status='published')
                 / (select count(*) from public.marketplace_reviews
                     where status in ('published','rejected')), 1)
      end,

    'reviews', coalesce((
      select jsonb_agg(jsonb_build_object(
               'id', r.id, 'rating', r.rating, 'title', r.title, 'content', r.comment,
               'status', r.status, 'type', r.review_type,
               'helpful', r.helpful_count, 'reports', r.report_count,
               'created_at', r.created_at, 'published_at', r.published_at,
               'moderation_note', r.moderation_note,
               'buyer_id', r.buyer_id, 'product_id', r.product_id,
               'order_item_id', r.order_item_id,
               'verified_purchase', true,
               'product_name', (select p.name from public.marketplace_products p
                                 where p.id = r.product_id),
               'buyer', (select coalesce(pr.full_name, pr.email)
                           from public.profiles pr where pr.id = r.buyer_id),
               'replies', coalesce((select jsonb_agg(jsonb_build_object(
                                      'id', rp.id, 'role', rp.author_role,
                                      'content', rp.content, 'status', rp.status,
                                      'created_at', rp.created_at) order by rp.created_at)
                                     from public.review_replies rp
                                    where rp.review_id = r.id), '[]'::jsonb),
               'open_reports', coalesce((select jsonb_agg(jsonb_build_object(
                                      'id', rr.id, 'reason', rr.reason, 'detail', rr.detail,
                                      'status', rr.status, 'created_at', rr.created_at))
                                     from public.review_reports rr
                                    where rr.review_id = r.id
                                      and rr.status in ('open','investigating')), '[]'::jsonb),
               'media', coalesce((select jsonb_agg(jsonb_build_object(
                                      'id', m.id, 'kind', m.kind,
                                      'processing', m.processing_status,
                                      'moderation', m.moderation_status))
                                     from public.review_media m
                                    where m.review_id = r.id), '[]'::jsonb))
             order by r.created_at desc)
        from (select * from public.marketplace_reviews r2
               where (v_search is null
                      or coalesce(r2.title,'') ilike '%'||v_search||'%'
                      or r2.comment ilike '%'||v_search||'%')
                 and case v_tab
                       when 'queue'    then r2.status = 'pending'
                       when 'latest'   then true
                       when 'top'      then r2.status='published' and r2.rating >= 4
                       when 'video'    then r2.review_type = 'video'
                       when 'reported' then exists (select 1 from public.review_reports x
                                                     where x.review_id = r2.id
                                                       and x.status in ('open','investigating'))
                       when 'replies'  then exists (select 1 from public.review_replies x
                                                     where x.review_id = r2.id)
                       else true end
               order by case when v_tab='top' then r2.rating else 0 end desc,
                        r2.created_at desc
               limit v_limit) r), '[]'::jsonb));
end;
$$;


--
-- Name: mm_row_analytics(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_row_analytics(p_key text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_cat uuid; v_views bigint; v_demo bigint; v_cta bigint; v_orders bigint; v_rev numeric;
begin
  select id into v_cat from public.marketplace_categories where slug = p_key;
  if v_cat is null then return jsonb_build_object('ok', false, 'reason', 'unknown_row'); end if;

  select count(*) filter (where event_type::text = 'product_view'),
         count(*) filter (where event_type::text = 'demo_click'),
         count(*) filter (where event_type::text = 'cta_click')
    into v_views, v_demo, v_cta
  from public.marketplace_events where category_id = v_cat;

  select count(distinct o.id), coalesce(sum(oi.line_total),0)
    into v_orders, v_rev
  from public.marketplace_order_items oi
  join public.marketplace_orders o on o.id = oi.order_id and o.status::text = 'paid'
  join public.marketplace_products p on p.id = oi.product_id
  where p.category_id = v_cat;

  return jsonb_build_object(
    'ok', true, 'row', p_key,
    'product_views', v_views, 'demo_opens', v_demo, 'cta_clicks', v_cta,
    'orders', v_orders, 'revenue', v_rev,
    -- Returned as null rather than 0 when there is nothing to divide by, so
    -- the UI shows "not measured yet" instead of a confident 0.0%.
    'ctr', case when coalesce(v_views,0) > 0
                then round((coalesce(v_demo,0) + coalesce(v_cta,0))::numeric * 100 / v_views, 2)
                else null end,
    'conversion', case when coalesce(v_views,0) > 0
                       then round(coalesce(v_orders,0)::numeric * 100 / v_views, 2)
                       else null end,
    'measured_from', (select min(created_at) from public.marketplace_events where category_id = v_cat));
end $$;


--
-- Name: mm_row_configure(text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_row_configure(p_key text, p_patch jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare rw record; v_before jsonb; v_id uuid;
begin
  if not public.mm_is_operator() then
    return jsonb_build_object('ok', false, 'reason', 'not_permitted');
  end if;
  select * into rw from public.mm_row_resolve(p_key);
  if rw.category_id is null and rw.row_id is null then
    return jsonb_build_object('ok', false, 'reason', 'unknown_row');
  end if;

  select to_jsonb(cfg) into v_before from public.marketplace_row_config cfg
   where cfg.id = rw.row_id;

  if rw.row_id is null then
    insert into public.marketplace_row_config
      (category_id, row_kind, updated_by, updated_at)
    values (rw.category_id, 'category', auth.uid(), now())
    on conflict (category_id) where category_id is not null do nothing;
  end if;

  select coalesce(rw.row_id, (select id from public.marketplace_row_config
                              where category_id = rw.category_id and row_kind='category'))
    into v_id;

  update public.marketplace_row_config set
    source_mode          = coalesce(p_patch->>'source_mode', source_mode),
    auto_rule            = coalesce(p_patch->>'auto_rule', auto_rule),
    max_products         = coalesce((p_patch->>'max_products')::int, max_products),
    allow_cross_category = coalesce((p_patch->>'allow_cross_category')::boolean, allow_cross_category),
    allow_duplicates     = coalesce((p_patch->>'allow_duplicates')::boolean, allow_duplicates),
    visible_desktop      = coalesce((p_patch->>'visible_desktop')::boolean, visible_desktop),
    visible_tablet       = coalesce((p_patch->>'visible_tablet')::boolean, visible_tablet),
    visible_mobile       = coalesce((p_patch->>'visible_mobile')::boolean, visible_mobile),
    starts_at            = case when p_patch ? 'starts_at'
                                then nullif(p_patch->>'starts_at','')::timestamptz else starts_at end,
    ends_at              = case when p_patch ? 'ends_at'
                                then nullif(p_patch->>'ends_at','')::timestamptz else ends_at end,
    cta_label            = coalesce(p_patch->>'cta_label', cta_label),
    cta_href             = coalesce(p_patch->>'cta_href', cta_href),
    title                = coalesce(p_patch->>'title', title),
    sort_order           = coalesce((p_patch->>'sort_order')::int, sort_order),
    status               = coalesce(p_patch->>'status', status),
    updated_by = auth.uid(), updated_at = now()
  where id = v_id;

  -- Visibility stays on the category, because that is the column the homepage
  -- filters on.
  if p_patch ? 'hidden' and rw.category_id is not null then
    update public.marketplace_categories
       set is_hidden = (p_patch->>'hidden')::boolean, updated_at = now()
     where id = rw.category_id;
  end if;

  perform public.mm_audit('row_configure', 'homepage_row',
    coalesce(rw.category_id, v_id)::text,
    coalesce(v_before, '{}'::jsonb), p_patch, 'row settings changed');
  return jsonb_build_object('ok', true, 'row', p_key);
end $$;


--
-- Name: mm_row_create(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_row_create(p_spec jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_key text; v_kind text; v_cat uuid; v_id uuid; v_order int;
begin
  if not public.mm_is_operator() then
    return jsonb_build_object('ok', false, 'reason', 'not_permitted');
  end if;

  v_key  := nullif(trim(coalesce(p_spec->>'key','')), '');
  v_kind := coalesce(p_spec->>'row_kind', 'curated');

  if v_key is null then
    return jsonb_build_object('ok', false, 'reason', 'key_required',
      'message', 'A stable row key is required. Display names can change; keys cannot.');
  end if;
  if v_key !~ '^[a-z0-9]+(-[a-z0-9]+)*$' then
    return jsonb_build_object('ok', false, 'reason', 'bad_key',
      'message', 'Use a lowercase slug such as featured-software.');
  end if;

  -- Section 1: never create a second row with a key the homepage already has.
  if exists (select 1 from public.marketplace_categories where slug = v_key)
     or exists (select 1 from public.marketplace_row_config where key = v_key) then
    return jsonb_build_object('ok', false, 'reason', 'row_exists',
      'message', 'A homepage row with that key already exists — manage it instead of creating another.',
      'key', v_key);
  end if;

  if v_kind = 'category' then
    v_cat := nullif(p_spec->>'category_id','')::uuid;
    if v_cat is null then
      return jsonb_build_object('ok', false, 'reason', 'category_required');
    end if;
  end if;

  select coalesce(max(sort_order), (select coalesce(max(sort_order),0)
                                    from public.marketplace_categories)) + 1
    into v_order from public.marketplace_row_config;

  insert into public.marketplace_row_config (
    key, title, row_kind, category_id, subcategory, sort_order,
    source_mode, auto_rule, max_products,
    visible_desktop, visible_tablet, visible_mobile,
    starts_at, ends_at, cta_label, cta_href, status, created_by, updated_by)
  values (
    v_key,
    coalesce(nullif(p_spec->>'title',''), initcap(replace(v_key,'-',' '))),
    v_kind, v_cat, nullif(p_spec->>'subcategory',''),
    coalesce((p_spec->>'sort_order')::int, v_order),
    coalesce(p_spec->>'source_mode','auto'),
    coalesce(p_spec->>'auto_rule','featured'),
    least(coalesce((p_spec->>'max_products')::int, 60), 60),
    coalesce((p_spec->>'visible_desktop')::boolean, true),
    coalesce((p_spec->>'visible_tablet')::boolean, true),
    coalesce((p_spec->>'visible_mobile')::boolean, true),
    nullif(p_spec->>'starts_at','')::timestamptz,
    nullif(p_spec->>'ends_at','')::timestamptz,
    nullif(p_spec->>'cta_label',''), nullif(p_spec->>'cta_href',''),
    -- New rows start as drafts. Creating a row must not put something on the
    -- front page before anyone has looked at it.
    coalesce(p_spec->>'status','draft'),
    auth.uid(), auth.uid())
  returning id into v_id;

  perform public.mm_audit('row_create', 'homepage_row', v_id::text,
    '{}'::jsonb, p_spec, 'row created as a draft');

  return jsonb_build_object('ok', true, 'row_id', v_id, 'key', v_key,
    'status', coalesce(p_spec->>'status','draft'),
    'message', 'Row created as a draft. Publish it when it is ready to appear.');
end $_$;


--
-- Name: mm_row_duplicate(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_row_duplicate(p_row_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  r public.marketplace_homepage_sections%rowtype;
  v_new uuid;
  v_key text;
begin
  if not public.mm_is_operator() then
    return jsonb_build_object('ok', false, 'reason', 'not_permitted');
  end if;

  select * into r from public.marketplace_homepage_sections where id = p_row_id;
  if not found then return jsonb_build_object('ok', false, 'reason', 'no_such_row'); end if;

  v_key := r.key || '-copy-' || substr(replace(gen_random_uuid()::text, '-', ''), 1, 6);

  insert into public.marketplace_homepage_sections
    (key, title, subtitle, description, row_type, source, category_id, collection_key,
     product_filter, manual_product_ids, sort_by, item_limit, visible_desktop,
     visible_mobile, priority, cta_label, cta_href, config, sort_order,
     -- A duplicate always starts as a draft. Copying a live row straight onto
     -- the homepage is how a page ends up showing the same shelf twice.
     status, enabled, created_by, updated_by, duplicated_from)
  values
    (v_key, r.title || ' (copy)', r.subtitle, r.description, r.row_type, r.source,
     r.category_id, r.collection_key, r.product_filter, r.manual_product_ids,
     r.sort_by, r.item_limit, r.visible_desktop, r.visible_mobile, r.priority,
     r.cta_label, r.cta_href, r.config,
     coalesce((select max(sort_order) + 1 from public.marketplace_homepage_sections), 1),
     'draft', false, auth.uid(), auth.uid(), p_row_id)
  returning id into v_new;

  perform public.mm_audit('Homepage Row Duplicated', 'homepage_row', v_new::text,
    jsonb_build_object('from', r.key), jsonb_build_object('key', v_key));

  return jsonb_build_object('ok', true, 'row_id', v_new, 'key', v_key);
end;
$$;


--
-- Name: mm_row_is_live(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_row_is_live(p_key text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select coalesce((
    select r.status = 'published'
       and not coalesce(r.hidden, false)
       and (r.starts_at is null or r.starts_at <= now())
       and (r.ends_at   is null or r.ends_at   >  now())
    from public.mm_row_resolve(p_key) r
  ), false);
$$;


--
-- Name: mm_row_products(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_row_products(p_key text) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    AS $$
declare
  rw record; v_out jsonb := '[]'::jsonb; v_taken uuid[]; r record; i int;
begin
  select * into rw from public.mm_row_resolve(p_key);
  if rw.row_id is null and rw.category_id is null then
    return jsonb_build_object('ok', false, 'reason', 'unknown_row');
  end if;

  -- Placed products, whichever way the slot is keyed.
  if rw.source_mode in ('manual','hybrid') then
    for r in
      select s.position, s.product_id, s.pinned, p.name, p.slug, p.thumbnail_url,
             p.visible, p.content_status
      from public.marketplace_row_slots s
      join public.marketplace_products p on p.id = s.product_id
      where (s.row_id = rw.row_id or (rw.category_id is not null and s.category_id = rw.category_id))
        and s.position <= rw.max_products
      order by s.position
    loop
      v_out := v_out || jsonb_build_object(
        'position', r.position, 'product_id', r.product_id, 'name', r.name,
        'slug', r.slug, 'thumbnail_url', r.thumbnail_url, 'pinned', r.pinned,
        'source', 'manual',
        'live', (r.visible and r.content_status = 'published'));
      v_taken := array_append(v_taken, r.product_id);
    end loop;
  end if;

  if rw.source_mode in ('auto','hybrid') then
    i := 1;
    for r in
      select p.id, p.name, p.slug, p.thumbnail_url
      from public.marketplace_products p
      left join (
        select oi.product_id, count(*) sold
        from public.marketplace_order_items oi
        join public.marketplace_orders o on o.id = oi.order_id and o.status::text='paid'
        group by oi.product_id) s on s.product_id = p.id
      left join (
        select e.product_id, count(*) views
        from public.marketplace_events e
        where e.created_at > now() - interval '30 days'
        group by e.product_id) v on v.product_id = p.id
      where p.visible and p.content_status = 'published'
        -- A category row draws from its category; a curated row draws from the
        -- whole catalogue, narrowed by its rule.
        and (rw.category_id is null or p.category_id = rw.category_id)
        and (rw.kind = 'category' or case rw.auto_rule
               when 'featured'     then p.is_featured
               when 'trending'     then p.is_trending
               -- Sold for real, or flagged by an editor. The flag alone
               -- matched nothing.
               when 'best_selling' then (coalesce(s.sold, 0) > 0 or p.is_best_seller)
               when 'new_release'  then p.is_new_release
               else true end)
        and (v_taken is null or not (p.id = any(v_taken)))
      order by
        case rw.auto_rule when 'newest' then extract(epoch from p.created_at) end desc nulls last,
        case rw.auto_rule when 'new_release' then extract(epoch from p.created_at) end desc nulls last,
        case rw.auto_rule when 'best_selling' then coalesce(s.sold,0) end desc nulls last,
        case rw.auto_rule when 'trending' then coalesce(v.views,0) end desc nulls last,
        case rw.auto_rule when 'rating' then p.rating end desc nulls last,
        p.sort_order asc nulls last, p.name asc
      limit rw.max_products
    loop
      while exists (
        select 1 from public.marketplace_row_slots s2
        where (s2.row_id = rw.row_id
               or (rw.category_id is not null and s2.category_id = rw.category_id))
          and s2.position = i)
        and rw.source_mode = 'hybrid' loop
        i := i + 1;
      end loop;
      exit when i > rw.max_products;
      v_out := v_out || jsonb_build_object(
        'position', i, 'product_id', r.id, 'name', r.name, 'slug', r.slug,
        'thumbnail_url', r.thumbnail_url, 'pinned', false,
        'source', 'auto', 'live', true);
      i := i + 1;
    end loop;
  end if;

  return jsonb_build_object(
    'ok', true, 'row', p_key, 'row_kind', rw.kind,
    'source_mode', rw.source_mode, 'auto_rule', rw.auto_rule,
    'max_products', rw.max_products,
    'live_now', public.mm_row_is_live(p_key),
    'filled', jsonb_array_length(v_out),
    'empty', greatest(rw.max_products - jsonb_array_length(v_out), 0),
    'eligible_total', (
      select count(*) from public.marketplace_products p
      left join (
        select oi.product_id, count(*) sold
        from public.marketplace_order_items oi
        join public.marketplace_orders o on o.id = oi.order_id and o.status::text='paid'
        group by oi.product_id) s on s.product_id = p.id
      where p.visible and p.content_status='published'
        and (rw.category_id is null or p.category_id = rw.category_id)
        and (rw.kind = 'category' or case rw.auto_rule
               when 'featured'     then p.is_featured
               when 'trending'     then p.is_trending
               when 'best_selling' then (coalesce(s.sold, 0) > 0 or p.is_best_seller)
               when 'new_release'  then p.is_new_release
               else true end)),
    'products', v_out);
end
$$;


--
-- Name: mm_row_reorder(uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_row_reorder(p_ordered_ids uuid[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare i integer;
begin
  if not public.mm_is_operator() then
    return jsonb_build_object('ok', false, 'reason', 'not_permitted');
  end if;

  for i in 1 .. coalesce(array_length(p_ordered_ids, 1), 0) loop
    update public.marketplace_homepage_sections
       set sort_order = i, updated_by = auth.uid()
     where id = p_ordered_ids[i];
  end loop;

  perform public.mm_audit('Homepage Rows Reordered', 'homepage_row', null, null,
    jsonb_build_object('order', p_ordered_ids));

  return jsonb_build_object('ok', true, 'rows', coalesce(array_length(p_ordered_ids, 1), 0));
end;
$$;


--
-- Name: mm_row_resolve(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_row_resolve(p_key text) RETURNS TABLE(row_id uuid, kind text, category_id uuid, title text, max_products integer, source_mode text, auto_rule text, allow_cross boolean, allow_dupes boolean, status text, starts_at timestamp with time zone, ends_at timestamp with time zone, hidden boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  -- A curated row: keyed directly.
  select cfg.id, cfg.row_kind, cfg.category_id, cfg.title, cfg.max_products,
         cfg.source_mode, cfg.auto_rule, cfg.allow_cross_category,
         cfg.allow_duplicates, cfg.status, cfg.starts_at, cfg.ends_at, false
  from public.marketplace_row_config cfg
  where cfg.key = p_key and cfg.row_kind = 'curated'
  union all
  -- A category row: keyed by the category slug, config optional.
  select cfg.id, 'category', c.id, c.name, coalesce(cfg.max_products, 60),
         coalesce(cfg.source_mode, 'auto'), coalesce(cfg.auto_rule, 'sort_order'),
         coalesce(cfg.allow_cross_category, false), coalesce(cfg.allow_duplicates, false),
         coalesce(cfg.status, 'published'), cfg.starts_at, cfg.ends_at, c.is_hidden
  from public.marketplace_categories c
  left join public.marketplace_row_config cfg
    on cfg.category_id = c.id and cfg.row_kind = 'category'
  where c.slug = p_key
  limit 1;
$$;


--
-- Name: mm_row_set_status(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_row_set_status(p_row_id uuid, p_status text, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  r public.marketplace_homepage_sections%rowtype;
begin
  if not public.mm_is_operator() then
    return jsonb_build_object('ok', false, 'reason', 'not_permitted');
  end if;
  if p_status not in ('draft','review','scheduled','published','unpublished','archived') then
    return jsonb_build_object('ok', false, 'reason', 'unknown_status');
  end if;

  select * into r from public.marketplace_homepage_sections where id = p_row_id;
  if not found then return jsonb_build_object('ok', false, 'reason', 'no_such_row'); end if;

  -- A scheduled row needs a window, or "scheduled" means nothing.
  if p_status = 'scheduled' and r.starts_at is null then
    return jsonb_build_object('ok', false, 'reason', 'a scheduled row needs a start time');
  end if;

  update public.marketplace_homepage_sections
     set status = p_status,
         enabled = (p_status = 'published'),
         published_at = case when p_status = 'published' then now() else published_at end,
         published_by = case when p_status = 'published' then auth.uid() else published_by end,
         archived_at = case when p_status = 'archived' then now() else null end,
         updated_by = auth.uid()
   where id = p_row_id;

  perform public.mm_audit(
    case p_status
      when 'published' then 'Homepage Row Published'
      when 'unpublished' then 'Homepage Row Unpublished'
      when 'archived' then 'Homepage Row Archived'
      when 'scheduled' then 'Homepage Row Scheduled'
      else 'Homepage Row Status Changed' end,
    'homepage_row', p_row_id::text,
    jsonb_build_object('status', r.status),
    jsonb_build_object('status', p_status), p_reason);

  return jsonb_build_object('ok', true, 'status', p_status, 'row', r.key);
end;
$$;


--
-- Name: mm_rows_list(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_rows_list() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select coalesce(jsonb_agg(r order by (r->>'effective_order')::int,
                                       r->>'title'), '[]'::jsonb)
  from (
    -- Category rows.
    select jsonb_build_object(
      'key', c.slug, 'row_id', cfg.id, 'row_kind', 'category',
      'category_id', c.id, 'title', c.name, 'icon', c.icon,
      'effective_order', coalesce(cfg.sort_order, c.sort_order, 9999),
      'hidden', c.is_hidden, 'featured', c.is_featured,
      'source_mode', coalesce(cfg.source_mode,'auto'),
      'auto_rule', coalesce(cfg.auto_rule,'sort_order'),
      'max_products', coalesce(cfg.max_products,60),
      'status', coalesce(cfg.status,'published'),
      'visible_desktop', coalesce(cfg.visible_desktop,true),
      'visible_tablet', coalesce(cfg.visible_tablet,true),
      'visible_mobile', coalesce(cfg.visible_mobile,true),
      'starts_at', cfg.starts_at, 'ends_at', cfg.ends_at,
      'cta_label', cfg.cta_label, 'cta_href', cfg.cta_href,
      'allow_cross_category', coalesce(cfg.allow_cross_category,false),
      'allow_duplicates', coalesce(cfg.allow_duplicates,false),
      'configured', (cfg.id is not null),
      'live_now', public.mm_row_is_live(c.slug),
      'filled_slots', (select count(*) from public.marketplace_row_slots s
                        where s.category_id = c.id or s.row_id = cfg.id),
      'eligible_products', (select count(*) from public.marketplace_products p
                             where p.category_id = c.id and p.visible
                               and p.content_status='published'),
      'updated_at', cfg.updated_at
    ) r
    from public.marketplace_categories c
    left join public.marketplace_row_config cfg
      on cfg.category_id = c.id and cfg.row_kind = 'category'

    union all

    -- Curated rows.
    select jsonb_build_object(
      'key', cfg.key, 'row_id', cfg.id, 'row_kind', 'curated',
      'category_id', null, 'title', cfg.title, 'icon', null,
      'effective_order', coalesce(cfg.sort_order, 9999),
      'hidden', false, 'featured', false,
      'source_mode', cfg.source_mode, 'auto_rule', cfg.auto_rule,
      'max_products', cfg.max_products, 'status', cfg.status,
      'visible_desktop', cfg.visible_desktop,
      'visible_tablet', cfg.visible_tablet,
      'visible_mobile', cfg.visible_mobile,
      'starts_at', cfg.starts_at, 'ends_at', cfg.ends_at,
      'cta_label', cfg.cta_label, 'cta_href', cfg.cta_href,
      'allow_cross_category', cfg.allow_cross_category,
      'allow_duplicates', cfg.allow_duplicates,
      'configured', true,
      'live_now', public.mm_row_is_live(cfg.key),
      'filled_slots', (select count(*) from public.marketplace_row_slots s
                        where s.row_id = cfg.id),
      'eligible_products', (
        select count(*) from public.marketplace_products p
        where p.visible and p.content_status='published'
          and case cfg.auto_rule
                when 'featured'     then p.is_featured
                when 'trending'     then p.is_trending
                when 'best_selling' then p.is_best_seller
                when 'new_release'  then p.is_new_release
                else true end),
      'updated_at', cfg.updated_at
    ) r
    from public.marketplace_row_config cfg
    where cfg.row_kind = 'curated'
  ) x;
$$;


--
-- Name: mm_rows_reorder(text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_rows_reorder(p_keys text[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare i int := 0; k text; n int := 0;
begin
  if not public.mm_is_operator() then
    return jsonb_build_object('ok', false, 'reason', 'not_permitted');
  end if;
  foreach k in array p_keys loop
    i := i + 1;
    update public.marketplace_categories
       set sort_order = i, updated_at = now()
     where slug = k;
    if found then n := n + 1; end if;
  end loop;
  perform public.mm_audit('rows_reorder', 'homepage_row',
    '00000000-0000-0000-0000-000000000000',
    '{}'::jsonb, jsonb_build_object('ordered', to_jsonb(p_keys)),
    'homepage row order changed');
  return jsonb_build_object('ok', true, 'rows', n);
end $$;


--
-- Name: mm_sandbox_activity(uuid, text, text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_sandbox_activity(p_sandbox uuid, p_kind text DEFAULT 'http'::text, p_path text DEFAULT NULL::text, p_status integer DEFAULT NULL::integer, p_latency integer DEFAULT NULL::integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_s record; v_set record; v_q boolean;
begin
  select * into v_s from public.demo_sandboxes where id = p_sandbox;
  if not found then return jsonb_build_object('ok', false, 'reason','unknown_sandbox'); end if;
  select * into v_set from public.demo_sandbox_settings where id;

  v_q := p_kind <> 'heartbeat';

  insert into public.demo_sandbox_activity
    (sandbox_id, kind, qualifies, path, status_code, latency_ms)
  values (p_sandbox, p_kind, v_q, p_path, p_status, p_latency);

  if v_q then
    update public.demo_sandboxes
       set last_activity_at = now(),
           expires_at = now() + (v_set.expire_after_idle_hours || ' hours')::interval,
           cleanup_after = now() + ((v_set.expire_after_idle_hours + v_set.grace_hours) || ' hours')::interval,
           -- A hit on an expiring sandbox brings it back.
           status = case when status='expiring' then 'active' else status end,
           updated_at = now()
     where id = p_sandbox;
  end if;

  return jsonb_build_object('ok', true, 'qualifies', v_q,
    'note', case when v_q then null
      else 'A heartbeat was recorded but does not extend the sandbox. Only a real request, an authenticated action or an interaction does.' end);
end;
$$;


--
-- Name: mm_sandbox_capabilities(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_sandbox_capabilities() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_dep jsonb;
begin
  v_dep := public.mm_demo_provider_status();

  return jsonb_build_object(
    'isolation', jsonb_build_object(
      'state','NOT_IMPLEMENTED',
      'detail','No sandbox container, schema or tenant is created, because no deployment runtime exists. Section 4 forbids claiming isolation that has not been implemented, so no sandbox records one.'),
    'database_reset', jsonb_build_object(
      'state','BLOCKED',
      'detail','A real database reset needs the sandbox runtime that would own the sandbox database. Reset jobs are recorded as blocked, never as done.'),
    'uploads_reset', jsonb_build_object(
      'state','BLOCKED',
      'detail','Same runtime. No sandbox-scoped storage exists to clear.'),
    'infrastructure_cleanup', jsonb_build_object(
      'state','BLOCKED',
      'detail','Temporary deployments, servers and DNS records cannot be released because none are created.'),
    'credential_rotation', jsonb_build_object(
      'state','CONNECTED',
      'detail','Generation, hashing, invalidation of the previous credential and the audit entry are all real and run here. Applying a credential to a running demo needs the runtime.'),
    'activity_tracking', jsonb_build_object('state','CONNECTED',
      'detail','Hits are recorded against the sandbox and drive the idle expiry.'),
    'expiry_engine', jsonb_build_object('state','CONNECTED',
      'detail','Warnings and expiry are computed from each sandbox''s own timestamps.'),
    'record_cleanup', jsonb_build_object('state','CONNECTED',
      'detail','Expired sessions and stale jobs are cleared. Audit, product, legal and deployment history are never touched.'),
    'health_checks', jsonb_build_object('state','PARTIALLY_CONNECTED',
      'detail','Domain and HTTPS reachability come from the demo monitor that already runs. Application, database and authentication checks need the runtime and are recorded as skipped rather than passed.'),
    'deployment_provider', v_dep->'deployment',
    'can_operate_infrastructure', false);
end;
$$;


--
-- Name: mm_sandbox_cleanup_run(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_sandbox_cleanup_run() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_set record; v_job uuid; r record;
  v_sessions integer := 0; v_jobs integer := 0; v_creds integer := 0;
  v_sandboxes integer := 0; v_removed jsonb; v_preserved jsonb;
begin
  if not public.mm_is_operator() then
    return jsonb_build_object('ok', false, 'reason','not_permitted');
  end if;
  select * into v_set from public.demo_sandbox_settings where id;

  insert into public.demo_sandbox_cleanup_jobs (scope, status)
  values ('expired', 'running') returning id into v_job;

  -- 11. Session logs, under the configured retention policy.
  if v_set.keep_session_logs then
    delete from public.demo_sandbox_sessions
     where last_seen_at < now() - (v_set.session_log_retention_days || ' days')::interval;
    get diagnostics v_sessions = row_count;
  else
    delete from public.demo_sandbox_sessions where ended_at is not null;
    get diagnostics v_sessions = row_count;
  end if;

  -- Abandoned provisioning jobs: queued for over a day and never started.
  update public.demo_sandbox_jobs
     set status='cancelled', finished_at=now(),
         error_category='abandoned',
         error_detail='Queued for more than a day without starting; cancelled by the cleanup.'
   where status='queued' and created_at < now() - interval '1 day';
  get diagnostics v_jobs = row_count;

  -- Expired credentials stop working.
  update public.demo_sandbox_credentials
     set active=false
   where active and expires_at is not null and expires_at <= now();
  get diagnostics v_creds = row_count;

  -- Sandboxes past their cleanup window are marked cleaned. The row stays.
  for r in
    select * from public.demo_sandboxes
     where status='expired' and cleanup_status='pending'
  loop
    update public.demo_sandboxes
       set cleanup_status='done', status='cleaned', updated_at=now()
     where id = r.id;
    insert into public.demo_sandbox_expiry_events (sandbox_id, kind, hours_out)
    values (r.id, 'cleanup', 0) on conflict do nothing;
    v_sandboxes := v_sandboxes + 1;
  end loop;

  v_removed := jsonb_build_object(
    'session_rows', v_sessions, 'abandoned_jobs', v_jobs,
    'credentials_expired', v_creds, 'sandboxes_marked_cleaned', v_sandboxes,
    'temporary_deployments', 0, 'temporary_servers', 0, 'temporary_dns', 0);

  v_preserved := jsonb_build_object(
    'products','never touched',
    'audit_logs','never touched',
    'legal_records','never touched',
    'deployment_history','never touched',
    'sandbox_rows','kept and marked cleaned rather than deleted',
    'note','Temporary deployments, servers and DNS records show zero because none were ever created — there is no runtime. Recording a release that did not happen would put a false entry in the audit trail.');

  update public.demo_sandbox_cleanup_jobs
     set status='partial', removed=v_removed, preserved=v_preserved, finished_at=now(),
         error_detail='Record cleanup ran. Infrastructure cleanup is blocked: no deployment runtime exists.'
   where id = v_job;

  perform public.mm_audit('sandbox.cleanup','demo_sandbox_cleanup', v_job::text, null,
                          jsonb_build_object('removed', v_removed), null);

  return jsonb_build_object('ok', true, 'job_id', v_job, 'status','partial',
    'removed', v_removed, 'preserved', v_preserved);
end;
$$;


--
-- Name: mm_sandbox_create(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_sandbox_create(p_demo uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_d record; v_s record; v_ref text; v_row jsonb; v_job uuid; v_cap jsonb;
begin
  if not public.mm_is_operator() then
    return jsonb_build_object('ok', false, 'reason','not_permitted');
  end if;
  select * into v_d from public.demo_domains where id = p_demo;
  if not found then return jsonb_build_object('ok', false, 'reason','unknown_demo'); end if;

  -- 20. Product Moderation decides whether a sandbox may exist at all.
  if not exists (select 1 from public.marketplace_products
                  where id = v_d.product_id and moderation_status='approved' and visible) then
    return jsonb_build_object('ok', false, 'reason','product_not_published',
      'message','Only an approved, published product may have a sandbox.');
  end if;

  if exists (select 1 from public.demo_sandboxes
              where demo_id = p_demo and status not in ('cleaned','failed')) then
    return jsonb_build_object('ok', false, 'reason','already_exists',
      'message','This demo already has a sandbox.');
  end if;

  select * into v_s from public.demo_sandbox_settings where id;
  v_cap := public.mm_sandbox_capabilities();
  v_ref := 'SBX-' || upper(substr(replace(gen_random_uuid()::text,'-',''), 1, 10));

  insert into public.demo_sandboxes
    (sandbox_ref, demo_id, product_id, server_instance_id,
     status, isolation_strategy, next_reset_at, expires_at, cleanup_after,
     failure_reason, created_by)
  values (v_ref, p_demo, v_d.product_id, v_d.server_instance_id,
          -- Without a runtime the sandbox is a record, not an environment.
          'provisioning', 'none',
          now() + (v_s.auto_reset_hours || ' hours')::interval,
          now() + (v_s.expire_after_idle_hours || ' hours')::interval,
          now() + ((v_s.expire_after_idle_hours + v_s.grace_hours) || ' hours')::interval,
          'No deployment runtime exists, so no sandbox environment was created. '
          || 'The record, its credentials, activity tracking and expiry are real; the environment is not.',
          auth.uid())
  returning to_jsonb(demo_sandboxes) into v_row;

  insert into public.demo_sandbox_jobs
    (sandbox_id, operation, status, idempotency_key, actor_id,
     started_at, finished_at, error_category, error_detail)
  values ((v_row->>'id')::uuid, 'create', 'blocked',
          'sandbox_create:' || v_ref, auth.uid(), now(), now(),
          'runtime_not_configured',
          'A sandbox environment needs a deployment runtime. None is configured.')
  returning id into v_job;

  -- 23. The baseline is recorded but explicitly not captured: there is nothing
  -- to capture from.
  insert into public.demo_sandbox_snapshots
    (sandbox_id, version, captured, note)
  values ((v_row->>'id')::uuid, 'baseline-1', false,
          'No baseline has been captured. A reset cannot restore a baseline that was never taken, which is why reset is blocked rather than reported as done.');

  insert into public.demo_domain_events
    (demo_id, product_id, event, actor_id, new_state, reason, detail)
  values (p_demo, v_d.product_id, 'sandbox.created', auth.uid(), 'provisioning',
          'Sandbox record created; no environment was provisioned.', v_cap);

  perform public.mm_audit('sandbox.created','demo_sandbox', (v_row->>'id'), null, v_row, null);

  return jsonb_build_object('ok', true, 'sandbox', v_row, 'job_id', v_job,
    'capabilities', v_cap,
    'note','The sandbox record exists and its lifecycle is real. No environment was created, so it is not active and cannot be.');
end;
$$;


--
-- Name: mm_sandbox_expiry_run(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_sandbox_expiry_run() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_set record; h integer; r record;
  v_warned integer := 0; v_expiring integer := 0; v_expired integer := 0;
begin
  if not public.mm_is_operator() then
    return jsonb_build_object('ok', false, 'reason','not_permitted');
  end if;
  select * into v_set from public.demo_sandbox_settings where id;

  -- Warnings at each configured threshold, once each.
  foreach h in array v_set.warning_hours loop
    for r in
      select * from public.demo_sandboxes
       where status in ('active','expiring') and expires_at is not null
         and expires_at between now() and now() + (h || ' hours')::interval
         and not exists (select 1 from public.demo_sandbox_expiry_events e
                          where e.sandbox_id = demo_sandboxes.id
                            and e.kind='warning' and e.hours_out = h)
    loop
      insert into public.demo_sandbox_expiry_events (sandbox_id, kind, hours_out, notified)
      values (r.id, 'warning', h, true) on conflict do nothing;
      v_warned := v_warned + 1;

      perform public.mm_notify('sandbox.expiring',
        format('Sandbox %s expires in %s hour(s)', r.sandbox_ref, h),
        format('No qualifying activity since %s. It expires at %s unless it is used or extended.',
               coalesce(to_char(r.last_activity_at,'DD Mon HH24:MI'),'never'),
               to_char(r.expires_at,'DD Mon HH24:MI')),
        null, array['admin','boss'], '/marketplace-manager', 'Open',
        60 * 6, case when h <= 6 then 'warning' else 'info' end);
    end loop;
  end loop;

  -- Idle past its window: expiring, still reachable during grace.
  for r in
    select * from public.demo_sandboxes
     where status = 'active' and expires_at is not null and expires_at <= now()
  loop
    update public.demo_sandboxes set status='expiring', updated_at=now() where id=r.id;
    insert into public.demo_sandbox_expiry_events (sandbox_id, kind, hours_out)
    values (r.id, 'expiring', 0) on conflict do nothing;
    v_expiring := v_expiring + 1;
  end loop;

  -- Past grace: expired and queued for cleanup. Never deleted here.
  for r in
    select * from public.demo_sandboxes
     where status = 'expiring' and cleanup_after is not null and cleanup_after <= now()
  loop
    update public.demo_sandboxes
       set status='expired', cleanup_status='pending', updated_at=now() where id=r.id;
    insert into public.demo_sandbox_expiry_events (sandbox_id, kind, hours_out)
    values (r.id, 'expired', 0) on conflict do nothing;
    v_expired := v_expired + 1;
  end loop;

  return jsonb_build_object('ok', true,
    'thresholds', to_jsonb(v_set.warning_hours),
    'warned', v_warned, 'entered_expiring', v_expiring, 'expired', v_expired,
    'note','An expired sandbox is queued for cleanup, not removed. Its product, audit trail and deployment history are never touched.');
end;
$$;


--
-- Name: mm_sandbox_extend(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_sandbox_extend(p_sandbox uuid, p_hours integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_s record; v_after jsonb; v_set record;
begin
  if not public.mm_is_operator() then
    return jsonb_build_object('ok', false, 'reason','not_permitted');
  end if;
  if p_hours is null or p_hours < 1 or p_hours > 8760 then
    return jsonb_build_object('ok', false, 'reason','bad_extension');
  end if;
  select * into v_s from public.demo_sandboxes where id = p_sandbox;
  if not found then return jsonb_build_object('ok', false, 'reason','unknown_sandbox'); end if;
  select * into v_set from public.demo_sandbox_settings where id;

  update public.demo_sandboxes
     set expires_at = greatest(coalesce(expires_at, now()), now()) + (p_hours || ' hours')::interval,
         cleanup_after = greatest(coalesce(expires_at, now()), now())
                       + ((p_hours + v_set.grace_hours) || ' hours')::interval,
         status = case when status in ('expiring','expired') then 'active' else status end,
         cleanup_status = case when status in ('expiring','expired') then 'none' else cleanup_status end,
         updated_at = now()
   where id = p_sandbox returning to_jsonb(demo_sandboxes) into v_after;

  insert into public.demo_sandbox_expiry_events (sandbox_id, kind, hours_out)
  values (p_sandbox, 'extended', p_hours) on conflict do nothing;

  perform public.mm_audit('sandbox.extended','demo_sandbox', p_sandbox::text,
                          to_jsonb(v_s), v_after, format('extended by %s hours', p_hours));

  return jsonb_build_object('ok', true, 'sandbox', v_after);
end;
$$;


--
-- Name: mm_sandbox_reset(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_sandbox_reset(p_sandbox uuid, p_trigger text DEFAULT 'manual'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_s record; v_set record; v_cap jsonb; v_job uuid; v_reset uuid;
  v_snapshot record; v_stages jsonb; v_outcome text; v_brand jsonb;
begin
  if not public.mm_is_operator() then
    return jsonb_build_object('ok', false, 'reason','not_permitted');
  end if;
  select * into v_s from public.demo_sandboxes where id = p_sandbox for update;
  if not found then return jsonb_build_object('ok', false, 'reason','unknown_sandbox'); end if;

  -- 24. One job at a time. A second click finds the lock held.
  if exists (select 1 from public.demo_sandbox_jobs
              where sandbox_id = p_sandbox and holds_lock) then
    return jsonb_build_object('ok', false, 'reason','locked',
      'message','Another operation is already running on this sandbox. Wait for it to finish.');
  end if;

  select * into v_set from public.demo_sandbox_settings where id;
  v_cap := public.mm_sandbox_capabilities();

  insert into public.demo_sandbox_jobs
    (sandbox_id, operation, status, idempotency_key, actor_id, started_at, holds_lock)
  values (p_sandbox, 'reset', 'running',
          'sandbox_reset:' || p_sandbox::text || ':' || extract(epoch from clock_timestamp())::bigint::text,
          auth.uid(), now(), true)
  returning id into v_job;

  update public.demo_sandboxes set status='resetting', updated_at=now() where id=p_sandbox;

  select * into v_snapshot from public.demo_sandbox_snapshots
   where sandbox_id = p_sandbox order by created_at desc limit 1;

  -- 22. Branding is the one stage that can genuinely run: it operates on the
  -- product's listing branding, which lives in this database.
  v_brand := public.mm_brand_detect(v_s.product_id);

  v_stages := jsonb_build_object(
    'lock', 'acquired',
    'baseline', case when v_snapshot.captured then 'restored'
                     else 'unavailable — no baseline has ever been captured' end,
    'database_reset', case when v_set.auto_reset_db then 'blocked — no sandbox runtime' else 'disabled by policy' end,
    'uploads_reset', case when v_set.auto_reset_uploads then 'blocked — no sandbox runtime' else 'disabled by policy' end,
    'branding', case when (v_brand->>'non_compliant')::int = 0
                     then 'verified compliant' else 'non-compliant listing branding found' end,
    'health_check', 'skipped — nothing is deployed to check');

  v_outcome := 'blocked';

  insert into public.demo_sandbox_resets
    (sandbox_id, job_id, trigger, stages, database_reset, uploads_reset,
     branding_reapplied, health_passed, outcome, failure_reason, finished_at)
  values (p_sandbox, v_job, p_trigger, v_stages, false, false,
          (v_brand->>'non_compliant')::int = 0, false, v_outcome,
          'No deployment runtime exists, so nothing could be reset. The sandbox was not changed.',
          now())
  returning id into v_reset;

  -- 28. A blocked or partial reset never leaves the sandbox looking active.
  update public.demo_sandboxes
     set status = case when v_outcome = 'succeeded' then 'active' else 'failed' end,
         last_reset_at = case when v_outcome='succeeded' then now() else last_reset_at end,
         next_reset_at = now() + (v_set.auto_reset_hours || ' hours')::interval,
         failure_reason = case when v_outcome='succeeded' then null
                               else 'The last reset could not run: no deployment runtime exists.' end,
         updated_at = now()
   where id = p_sandbox;

  update public.demo_sandbox_jobs
     set status = case when v_outcome='succeeded' then 'succeeded' else 'blocked' end,
         holds_lock = false, finished_at = now(),
         error_category = case when v_outcome='succeeded' then null else 'runtime_not_configured' end,
         error_detail = case when v_outcome='succeeded' then null
                             else 'A sandbox reset needs the runtime that owns the sandbox database and storage.' end
   where id = v_job;

  perform public.mm_audit('sandbox.reset_'||v_outcome,'demo_sandbox', p_sandbox::text,
                          to_jsonb(v_s), jsonb_build_object('stages', v_stages), p_trigger);

  return jsonb_build_object('ok', v_outcome = 'succeeded',
    'outcome', v_outcome, 'reset_id', v_reset, 'job_id', v_job,
    'stages', v_stages,
    'reason', case when v_outcome='succeeded' then null else 'runtime_not_configured' end,
    'message','Nothing was reset. The stages above record exactly what ran and what could not, and the sandbox is marked failed rather than active.');
end;
$$;


--
-- Name: mm_sandbox_rotate_credential(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_sandbox_rotate_credential(p_sandbox uuid, p_role text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp', 'extensions'
    AS $$
declare
  v_s record; v_set record; v_alphabet constant text :=
    'ABCDEFGHJKMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz23456789';
  v_pw text := ''; v_bytes bytea; i integer; v_user text; v_prev integer := 0;
  v_row jsonb; v_cap jsonb;
begin
  if not public.mm_is_operator() then
    return jsonb_build_object('ok', false, 'reason','not_permitted');
  end if;
  if p_role not in ('demo_user','demo_admin') then
    return jsonb_build_object('ok', false, 'reason','unknown_role');
  end if;
  select * into v_s from public.demo_sandboxes where id = p_sandbox for update;
  if not found then return jsonb_build_object('ok', false, 'reason','unknown_sandbox'); end if;
  select * into v_set from public.demo_sandbox_settings where id;

  -- 20 characters over a mixed alphabet with no look-alike glyphs.
  v_bytes := gen_random_bytes(20);
  for i in 0..19 loop
    v_pw := v_pw || substr(v_alphabet, (get_byte(v_bytes, i) % length(v_alphabet)) + 1, 1);
  end loop;

  v_user := case p_role when 'demo_admin' then 'admin' else 'demo' end
            || '@' || lower(left(v_s.sandbox_ref, 14));

  select coalesce(max(version),0) into v_prev
    from public.demo_sandbox_credentials where sandbox_id = p_sandbox and role_type = p_role;

  -- The previous credential stops working in the same statement that creates
  -- the new one, so there is never a window where both are valid.
  update public.demo_sandbox_credentials
     set active = false, rotated_at = now(), rotated_by = auth.uid()
   where sandbox_id = p_sandbox and role_type = p_role and active;

  insert into public.demo_sandbox_credentials
    (sandbox_id, role_type, username, password_hash, version, active, expires_at)
  values (p_sandbox, p_role, v_user, crypt(v_pw, gen_salt('bf', 10)),
          v_prev + 1, true,
          case when v_set.rotate_credentials
               then now() + (v_set.rotate_credentials_days || ' days')::interval
               else null end)
  returning to_jsonb(demo_sandbox_credentials) into v_row;

  insert into public.demo_sandbox_jobs
    (sandbox_id, operation, status, idempotency_key, actor_id, started_at, finished_at,
     error_category, error_detail)
  values (p_sandbox, 'rotate_credentials', 'succeeded',
          'sandbox_rotate:' || p_sandbox::text || ':' || p_role || ':' || (v_prev + 1)::text,
          auth.uid(), now(), now(), null, null);

  -- The audit records that a rotation happened, never what was generated.
  perform public.mm_audit('sandbox.credential_rotated','demo_sandbox', p_sandbox::text,
    jsonb_build_object('role', p_role, 'previous_version', v_prev),
    jsonb_build_object('role', p_role, 'version', v_prev + 1, 'username', v_user),
    null);

  v_cap := public.mm_sandbox_capabilities();

  return jsonb_build_object('ok', true,
    'username', v_user,
    -- Shown once. Nothing stores it and no read returns it again.
    'password', v_pw,
    'version', v_prev + 1,
    'previous_invalidated', v_prev > 0,
    'applied_to_demo', false,
    'note','Copy this now: only a bcrypt hash is stored and this password is never shown again. '
        || 'The credential is recorded and the previous one is already invalid, but it has not been applied to a running demo — no deployment runtime exists to apply it to.');
end;
$$;


--
-- Name: mm_sandbox_settings_set(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_sandbox_settings_set(p_patch jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_before jsonb; v_after jsonb;
begin
  if not public.mm_is_operator() then
    return jsonb_build_object('ok', false, 'reason','not_permitted');
  end if;
  select to_jsonb(s) into v_before from public.demo_sandbox_settings s where s.id;

  update public.demo_sandbox_settings set
    auto_reset_hours = coalesce((p_patch->>'auto_reset_hours')::int, auto_reset_hours),
    expire_after_idle_hours = coalesce((p_patch->>'expire_after_idle_hours')::int, expire_after_idle_hours),
    cleanup_at = coalesce((p_patch->>'cleanup_at')::time, cleanup_at),
    cleanup_timezone = coalesce(nullif(p_patch->>'cleanup_timezone',''), cleanup_timezone),
    grace_hours = coalesce((p_patch->>'grace_hours')::int, grace_hours),
    auto_reset_db = coalesce((p_patch->>'auto_reset_db')::boolean, auto_reset_db),
    auto_reset_uploads = coalesce((p_patch->>'auto_reset_uploads')::boolean, auto_reset_uploads),
    rotate_credentials = coalesce((p_patch->>'rotate_credentials')::boolean, rotate_credentials),
    rotate_credentials_days = coalesce((p_patch->>'rotate_credentials_days')::int, rotate_credentials_days),
    keep_session_logs = coalesce((p_patch->>'keep_session_logs')::boolean, keep_session_logs),
    session_log_retention_days = coalesce((p_patch->>'session_log_retention_days')::int, session_log_retention_days),
    updated_by = auth.uid(), updated_at = now()
  where id returning to_jsonb(demo_sandbox_settings) into v_after;

  perform public.mm_audit('sandbox.settings_changed','demo_sandbox_settings','settings',
                          v_before, v_after, nullif(p_patch->>'reason',''));
  return jsonb_build_object('ok', true, 'settings', v_after);
end;
$$;


--
-- Name: mm_sandbox_sync(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_sandbox_sync(p_demo uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_d record; v_s record; v_to text;
begin
  if not public.mm_is_operator() then
    return jsonb_build_object('ok', false, 'reason','not_permitted');
  end if;
  select * into v_d from public.demo_domains where id = p_demo;
  if not found then return jsonb_build_object('ok', false, 'reason','unknown_demo'); end if;
  select * into v_s from public.demo_sandboxes
   where demo_id = p_demo and status not in ('cleaned','failed');
  if not found then
    return jsonb_build_object('ok', true, 'changed', false,
      'note','This demo has no live sandbox to keep in step.');
  end if;

  v_to := case v_d.status
    when 'disabled' then 'disabled'
    when 'expired'  then 'expired'
    when 'live'     then 'active'
    when 'resetting' then 'resetting'
    else v_s.status end;

  if v_to = v_s.status then
    return jsonb_build_object('ok', true, 'changed', false, 'status', v_s.status);
  end if;

  update public.demo_sandboxes
     set status = v_to,
         cleanup_status = case when v_to='expired' then 'pending' else cleanup_status end,
         updated_at = now()
   where id = v_s.id;

  insert into public.demo_domain_events
    (demo_id, product_id, event, actor_id, previous_state, new_state, reason)
  values (p_demo, v_d.product_id, 'sandbox.synced', auth.uid(), v_s.status, v_to,
          format('Followed the demo, which is %s.', v_d.status));

  return jsonb_build_object('ok', true, 'changed', true,
    'from', v_s.status, 'to', v_to);
end;
$$;


--
-- Name: mm_sandboxes(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_sandboxes(p_query jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_status text := nullif(p_query->>'status','');
  v_search text := nullif(btrim(coalesce(p_query->>'search','')),'');
  v_limit integer := least(greatest(coalesce((p_query->>'limit')::int,50),1),200);
  v_set record;
begin
  if not public.mm_is_operator() then
    return jsonb_build_object('ok', false, 'reason','not_permitted');
  end if;
  select * into v_set from public.demo_sandbox_settings where id;

  return jsonb_build_object(
    'ok', true,
    'settings', to_jsonb(v_set),
    'capabilities', public.mm_sandbox_capabilities(),

    -- The four metric cards. Counted, never asserted.
    'active', (select count(*) from public.demo_sandboxes where status='active'),
    'resetting', (select count(*) from public.demo_sandboxes where status='resetting'),
    'expiring_24h', (select count(*) from public.demo_sandboxes
                      where status in ('active','expiring') and expires_at is not null
                        and expires_at <= now() + interval '24 hours'),
    'cleanups_today', (select count(*) from public.demo_sandbox_cleanup_jobs
                        where started_at >= date_trunc('day', now())),

    'by_status', coalesce((select jsonb_object_agg(status, n)
                             from (select status, count(*) n from public.demo_sandboxes
                                    group by status) t), '{}'::jsonb),
    'total', (select count(*) from public.demo_sandboxes),

    -- Read from Server Manager, never duplicated.
    'infrastructure', jsonb_build_object(
      'server_instances', (select count(*) from public.server_instances),
      'unhealthy_servers', (select count(*) from public.server_instances
                             where coalesce(status,'') not in ('running','active','healthy')),
      'note','Server Manager remains the infrastructure source of truth.'),

    'sandboxes', coalesce((
      select jsonb_agg(jsonb_build_object(
               'id', s.id, 'sandbox_ref', s.sandbox_ref,
               'demo_id', s.demo_id,
               'hostname', (select hostname from public.demo_domains where id=s.demo_id),
               'demo_status', (select status from public.demo_domains where id=s.demo_id),
               'product_id', s.product_id,
               'product', (select name from public.marketplace_products where id=s.product_id),
               'owner', (select sel.display_name from public.marketplace_products p
                          join public.marketplace_sellers sel on sel.id=p.seller_id
                         where p.id=s.product_id),
               'status', s.status, 'failure_reason', s.failure_reason,
               'isolation', s.isolation_strategy,
               'health', s.health, 'last_health_at', s.last_health_at,
               'last_activity_at', s.last_activity_at,
               'last_reset_at', s.last_reset_at, 'next_reset_at', s.next_reset_at,
               'expires_at', s.expires_at, 'cleanup_after', s.cleanup_after,
               'cleanup_status', s.cleanup_status,
               'hours_remaining', case when s.expires_at is null then null
                 else greatest(0, round(extract(epoch from s.expires_at - now())/3600)::int) end,
               'qualifying_hits', (select count(*) from public.demo_sandbox_activity a
                                    where a.sandbox_id = s.id and a.qualifies),
               'credentials', coalesce((select jsonb_agg(jsonb_build_object(
                                 'role', c.role_type, 'username', c.username,
                                 'version', c.version, 'expires_at', c.expires_at)
                                 order by c.role_type)
                                 from public.demo_sandbox_credentials c
                                where c.sandbox_id = s.id and c.active), '[]'::jsonb),
               'baseline_captured', (select captured from public.demo_sandbox_snapshots sn
                                      where sn.sandbox_id = s.id
                                      order by sn.created_at desc limit 1),
               'last_reset', (select jsonb_build_object('outcome', r.outcome,
                                'stages', r.stages, 'at', r.finished_at)
                                from public.demo_sandbox_resets r
                               where r.sandbox_id = s.id order by r.started_at desc limit 1),
               'locked', exists (select 1 from public.demo_sandbox_jobs j
                                  where j.sandbox_id = s.id and j.holds_lock),
               'created_at', s.created_at)
             order by s.updated_at desc)
        from (select * from public.demo_sandboxes s2
               where (v_status is null or s2.status = v_status)
                 and (v_search is null
                      or s2.sandbox_ref ilike '%'||v_search||'%'
                      or exists (select 1 from public.marketplace_products p
                                  where p.id = s2.product_id
                                    and p.name ilike '%'||v_search||'%'))
               order by s2.updated_at desc limit v_limit) s), '[]'::jsonb));
end;
$$;


--
-- Name: mm_section_set_enabled(text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_section_set_enabled(p_key text, p_enabled boolean) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
declare
  v_before jsonb;
  v_after  jsonb;
begin
  if not public.has_role(auth.uid(), 'admin'::public.app_role) then
    raise exception 'Not permitted to change the homepage layout'
      using errcode = '42501';
  end if;

  select to_jsonb(s) into v_before
    from public.marketplace_homepage_sections s
   where s.key = p_key;

  if v_before is null then
    raise exception 'Unknown homepage section: %', p_key
      using errcode = 'P0002';
  end if;

  update public.marketplace_homepage_sections s
     set enabled = p_enabled,
         -- Switching a section on has to mean it appears. live_now folds
         -- status into the answer, so enabling a draft while leaving it a
         -- draft would move the toggle and change nothing on the page.
         status = case
                    when p_enabled and s.status = 'draft' then 'published'
                    else s.status
                  end,
         published_at = case
                          when p_enabled and s.published_at is null then now()
                          else s.published_at
                        end,
         updated_at = now()
   where s.key = p_key
  returning to_jsonb(s) into v_after;

  if v_after is null then
    raise exception 'Homepage section % could not be updated', p_key
      using errcode = '42501';
  end if;

  perform public.mm_audit(
    case when p_enabled then 'section.enable' else 'section.disable' end,
    'homepage_section', p_key, v_before, v_after, null
  );

  return v_after;
end;
$$;


--
-- Name: mm_sections_reorder(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_sections_reorder(p_order jsonb) RETURNS integer
    LANGUAGE plpgsql
    AS $$
declare
  v_before  jsonb;
  v_after   jsonb;
  v_changed integer;
  v_known   integer;
  v_asked   integer;
begin
  if not public.has_role(auth.uid(), 'admin'::public.app_role) then
    raise exception 'Not permitted to change the homepage layout'
      using errcode = '42501';
  end if;

  if p_order is null or jsonb_typeof(p_order) <> 'array' then
    raise exception 'mm_sections_reorder expects an array of {key, sort_order}'
      using errcode = '22023';
  end if;

  select count(*), count(distinct e->>'key')
    into v_asked, v_known
    from jsonb_array_elements(p_order) e
   where e->>'key' is not null;

  -- A key listed twice would make the update below pick one of the two
  -- positions arbitrarily, so the request is rejected rather than guessed at.
  if v_asked <> v_known then
    raise exception 'Reorder lists the same section more than once'
      using errcode = '22023';
  end if;

  -- Every key in the request must be a section that exists. A typo silently
  -- doing nothing is how an order ends up half applied without anyone noticing.
  select count(*) into v_known
    from jsonb_array_elements(p_order) e
    join public.marketplace_homepage_sections s on s.key = e->>'key';

  if v_known <> v_asked then
    raise exception 'Reorder names % section(s) that do not exist', v_asked - v_known
      using errcode = 'P0002';
  end if;

  select jsonb_agg(jsonb_build_object('key', key, 'sort_order', sort_order)
                   order by sort_order, key)
    into v_before
    from public.marketplace_homepage_sections;

  -- One statement, so the whole order lands or none of it does.
  update public.marketplace_homepage_sections s
     set sort_order = w.sort_order,
         updated_at = now()
    from (
      select e->>'key' as key, (e->>'sort_order')::int as sort_order
        from jsonb_array_elements(p_order) e
       where e->>'key' is not null
    ) w
   where s.key = w.key
     and s.sort_order is distinct from w.sort_order;

  get diagnostics v_changed = row_count;

  -- Reordering to the order it is already in is a legitimate no-op, so zero
  -- rows is not an error here. The authorisation check above is what
  -- distinguishes that from a refused write.
  if v_changed > 0 then
    select jsonb_agg(jsonb_build_object('key', key, 'sort_order', sort_order)
                     order by sort_order, key)
      into v_after
      from public.marketplace_homepage_sections;

    perform public.mm_audit(
      'section.reorder', 'homepage_section', null, v_before, v_after, null
    );
  end if;

  return v_changed;
end;
$$;


--
-- Name: mm_security_finding_add(uuid, text, text, text, jsonb, text, text, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_security_finding_add(p_job uuid, p_category text, p_result text, p_title text, p_evidence jsonb DEFAULT '[]'::jsonb, p_severity text DEFAULT 'low'::text, p_source text DEFAULT 'static'::text, p_confidence numeric DEFAULT NULL::numeric) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_job record; v_row jsonb;
begin
  if not public.mm_is_operator() then
    return jsonb_build_object('ok', false, 'reason','not_permitted');
  end if;
  select * into v_job from public.security_scan_jobs where id = p_job;
  if not found then return jsonb_build_object('ok', false, 'reason','unknown_job'); end if;

  -- A finding that claims something was detected has to say what was seen.
  if p_result in ('flagged','blocked')
     and (p_evidence is null or jsonb_array_length(p_evidence) = 0) then
    return jsonb_build_object('ok', false, 'reason','evidence_required',
      'message','A flagged or blocked finding must carry the evidence for it.');
  end if;

  -- AI may describe and may recommend; it may not deliver a scanner verdict.
  if p_source = 'ai' and p_result = 'blocked' then
    return jsonb_build_object('ok', false, 'reason','ai_cannot_block',
      'message','AI is advisory. It can flag for human review but cannot block an asset on its own.');
  end if;

  insert into public.security_findings
    (job_id, asset_id, category, result, severity, title, evidence, source, confidence)
  values (p_job, v_job.asset_id, p_category, p_result, p_severity, p_title,
          coalesce(p_evidence,'[]'::jsonb), p_source, p_confidence)
  returning to_jsonb(security_findings) into v_row;

  insert into public.security_events (asset_id, job_id, event, actor_id, detail)
  values (v_job.asset_id, p_job, 'finding.'||p_category, auth.uid(),
          jsonb_build_object('result', p_result, 'severity', p_severity, 'source', p_source));

  return jsonb_build_object('ok', true, 'finding', v_row);
end;
$$;


--
-- Name: mm_security_provider_status(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_security_provider_status() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_ready integer;
begin
  select count(*) into v_ready from public.security_provider_configs
   where kind='malware' and enabled and verified;

  return jsonb_build_object(
    'malware_scanning', case when v_ready > 0 then 'CONNECTED' else 'SCANNER_NOT_CONFIGURED' end,
    'ready_providers', v_ready,
    -- Static analysis needs no third party and runs regardless.
    'static_analysis', 'CONNECTED',
    'providers', coalesce((select jsonb_agg(jsonb_build_object(
                   'slug', slug, 'label', label, 'kind', kind,
                   'enabled', enabled, 'verified', verified,
                   'credential_env', credential_env,
                   'last_error', last_error,
                   'state', case when enabled and verified then 'CONNECTED'
                                 when enabled and not verified then 'REQUIRES_CONFIGURATION'
                                 else 'DISABLED' end)
                 order by kind, slug) from public.security_provider_configs), '[]'::jsonb),
    'note', case when v_ready > 0 then null
      else 'No malware engine is configured, so no file has been scanned for malware. '
        || 'Uploads still go through file validation, hashing, static analysis and '
        || 'duplicate detection, and a malware verdict is reported as pending rather than clean.' end);
end;
$$;


--
-- Name: mm_security_quarantine_decide(uuid, text, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_security_quarantine_decide(p_asset uuid, p_to text, p_reason text, p_discard_payload boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_q record; v_after jsonb;
begin
  if not public.mm_is_operator() then
    return jsonb_build_object('ok', false, 'reason','not_permitted');
  end if;
  if p_to not in ('under_review','released','rejected','purged') then
    return jsonb_build_object('ok', false, 'reason','unknown_state');
  end if;
  if coalesce(btrim(p_reason),'') = '' then
    return jsonb_build_object('ok', false, 'reason','reason_required',
      'message','Releasing or rejecting a quarantined file is a security decision. Say why.');
  end if;

  select * into v_q from public.security_quarantine
   where asset_id = p_asset and state in ('quarantined','under_review')
   order by quarantined_at desc limit 1 for update;
  if not found then
    return jsonb_build_object('ok', false, 'reason','not_quarantined');
  end if;

  -- Releasing a file that a provider blocked is refused. A human may overrule a
  -- flag, not a malware detection.
  if p_to = 'released' and exists (
      select 1 from public.security_findings f
       where f.asset_id = p_asset and f.category='malware'
         and f.result='blocked' and f.source='provider') then
    return jsonb_build_object('ok', false, 'reason','malware_cannot_be_released',
      'message','A malware engine blocked this file. It cannot be released back into the marketplace.');
  end if;

  update public.security_quarantine
     set state = p_to, decided_by = auth.uid(), decided_at = now(),
         decision_reason = btrim(p_reason),
         payload_retained = case when p_to='purged' or p_discard_payload then false
                                 else payload_retained end
   where id = v_q.id returning to_jsonb(security_quarantine) into v_after;

  update public.security_assets
     set status = case p_to when 'released' then 'released'
                            when 'rejected' then 'rejected'
                            when 'purged' then 'purged'
                            else 'quarantined' end,
         -- 14. The payload is discarded while the hash and the evidence stay.
         storage_path = case when p_to='purged' or p_discard_payload then null else storage_path end,
         updated_at = now()
   where id = p_asset;

  insert into public.security_events (asset_id, job_id, event, actor_id,
                                      previous_state, new_state, reason)
  values (p_asset, v_q.job_id, 'quarantine.'||p_to, auth.uid(), v_q.state, p_to, btrim(p_reason));

  return jsonb_build_object('ok', true, 'quarantine', v_after,
    'note', case when p_to='purged' or p_discard_payload
      then 'The file itself was discarded. Its hash, findings and evidence are kept.'
      else null end);
end;
$$;


--
-- Name: mm_security_scan_error(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_security_scan_error(p_job uuid, p_category text, p_detail text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_job record; v_after jsonb;
begin
  if not public.mm_is_operator() then
    return jsonb_build_object('ok', false, 'reason','not_permitted');
  end if;
  select * into v_job from public.security_scan_jobs where id = p_job;
  if not found then return jsonb_build_object('ok', false, 'reason','unknown_job'); end if;

  update public.security_scan_jobs
     set status='error', error_category = p_category, error_detail = p_detail,
         completed_at = now()
   where id = p_job returning to_jsonb(security_scan_jobs) into v_after;

  -- The asset goes to scan_error, never to clean.
  update public.security_assets set status='scan_error', updated_at=now()
   where id = v_job.asset_id;

  insert into public.security_events (asset_id, job_id, event, actor_id, new_state, reason)
  values (v_job.asset_id, p_job, 'scan.error', auth.uid(), 'scan_error', p_detail);

  return jsonb_build_object('ok', true, 'job', v_after,
    'note','The asset is marked scan_error and is not publishable. An authorised retry can run the scan again.');
end;
$$;


--
-- Name: mm_security_scan_finish(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_security_scan_finish(p_job uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_job record; v_a record; v_settings record; v_provider jsonb;
  v_score integer := 0; v_level text; v_status text; v_asset_status text;
  v_blocked integer; v_flagged integer; v_malware_verdict text; v_after jsonb;
  v_owner uuid; v_categories jsonb;
begin
  if not public.mm_is_operator() then
    return jsonb_build_object('ok', false, 'reason','not_permitted');
  end if;
  select * into v_job from public.security_scan_jobs where id = p_job for update;
  if not found then return jsonb_build_object('ok', false, 'reason','unknown_job'); end if;
  select * into v_a from public.security_assets where id = v_job.asset_id;
  select * into v_settings from public.security_scanner_settings where id;
  v_provider := public.mm_security_provider_status();

  select count(*) filter (where result='blocked'),
         count(*) filter (where result='flagged')
    into v_blocked, v_flagged
    from public.security_findings where job_id = p_job;

  -- Weighted from the real findings.
  select coalesce(sum(case
           when result = 'blocked' then case severity
             when 'critical' then 60 when 'high' then 40 when 'medium' then 25 else 15 end
           when result = 'flagged' then case severity
             when 'critical' then 40 when 'high' then 25 when 'medium' then 15 else 8 end
           else 0 end), 0)::int
    into v_score from public.security_findings where job_id = p_job;
  v_score := least(v_score, 100);

  -- The malware category, stated honestly.
  select f.result into v_malware_verdict
    from public.security_findings f
   where f.job_id = p_job and f.category='malware' and f.source='provider'
   order by f.created_at desc limit 1;

  if v_malware_verdict is null then
    v_malware_verdict := 'pending';
    -- Record it as pending rather than leaving the category silently absent.
    insert into public.security_findings
      (job_id, asset_id, category, result, severity, title, evidence, source)
    values (p_job, v_job.asset_id, 'malware', 'pending', 'low',
            'Not scanned for malware',
            jsonb_build_array(jsonb_build_object('note', v_provider->>'note')), 'static')
    on conflict do nothing;
  end if;

  v_level := case when v_score >= 70 then 'critical'
                  when v_score >= 45 then 'high'
                  when v_score >= 20 then 'medium' else 'low' end;

  v_status := case when v_blocked > 0 then 'blocked'
                   when v_flagged > 0 then 'flagged'
                   else 'completed' end;

  -- The rule that matters. A job with no provider verdict may complete, but the
  -- asset is never called clean — it is left awaiting the malware stage.
  v_asset_status := case
    when v_blocked > 0 then 'blocked'
    when v_flagged > 0 then 'flagged'
    when v_malware_verdict = 'pass' then 'clean'
    else 'scanning' end;

  update public.security_scan_jobs
     set status = v_status, completed_at = now(),
         risk_score = v_score, risk_level = v_level,
         provider = coalesce(provider, 'sv-static'),
         stages = jsonb_build_object(
           'validation','ran', 'hashing', case when v_a.sha256 is not null then 'ran' else 'skipped' end,
           'static_analysis','ran',
           'malware', case when v_malware_verdict='pending' then 'not_configured' else 'ran' end,
           'duplicate','ran')
   where id = p_job returning to_jsonb(security_scan_jobs) into v_after;

  update public.security_assets set status = v_asset_status, updated_at = now()
   where id = v_job.asset_id;

  -- 13/14. A blocked asset is isolated, and a flagged one too when the setting
  -- says so.
  if v_blocked > 0 or (v_flagged > 0 and v_settings.auto_quarantine_flagged) then
    insert into public.security_quarantine (asset_id, job_id, reason, quarantined_by)
    values (v_job.asset_id, p_job,
            format('%s blocking and %s flagged finding(s) on scan %s.',
                   v_blocked, v_flagged, left(p_job::text,8)),
            auth.uid())
    on conflict do nothing;
    update public.security_assets set status='quarantined', updated_at=now()
     where id = v_job.asset_id;

    insert into public.security_events (asset_id, job_id, product_id, event, actor_id, new_state, reason)
    values (v_job.asset_id, p_job, v_a.product_id, 'quarantined', auth.uid(), 'quarantined',
            'Automatic isolation after the scan.');
  end if;

  -- 16. A copyright finding reaches the DMCA queue when enabled.
  if v_settings.send_copyright_to_dmca then
    insert into public.security_dmca_queue (asset_id, product_id, finding_id, sha256, evidence)
    select v_job.asset_id, v_a.product_id, f.id, v_a.sha256, f.evidence
      from public.security_findings f
     where f.job_id = p_job and f.category='copyright' and f.result in ('flagged','blocked');
  end if;

  select jsonb_object_agg(category, result) into v_categories
    from (select distinct on (category) category, result
            from public.security_findings where job_id = p_job
           order by category, created_at desc) t;

  insert into public.security_events (asset_id, job_id, product_id, event, actor_id, new_state, detail)
  values (v_job.asset_id, p_job, v_a.product_id, 'scan.completed', auth.uid(), v_status,
          jsonb_build_object('risk', v_score, 'level', v_level, 'categories', v_categories));

  -- 40. The uploader is told when their file is rejected, if that is configured.
  select s.owner_user_id into v_owner
    from public.marketplace_sellers s where s.id = v_a.seller_id;
  if v_owner is not null and v_blocked > 0 and v_settings.notify_author_on_rejection then
    perform public.mm_notify('security.blocked','An upload was blocked',
      format('%s did not pass the security scan and has been quarantined.', v_a.file_name),
      v_owner, null, '/author-manager', 'Open', 5, 'danger');
  end if;

  return jsonb_build_object('ok', true, 'job', v_after,
    'categories', coalesce(v_categories,'{}'::jsonb),
    'asset_status', v_asset_status,
    'malware', v_malware_verdict,
    'provider_status', v_provider->>'malware_scanning',
    'note', case when v_asset_status = 'scanning'
      then 'This asset is not marked clean. Nothing scanned it for malware, so the malware stage is pending rather than passed.'
      else null end);
end;
$$;


--
-- Name: mm_security_scan_start(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_security_scan_start(p_asset uuid, p_reuse boolean DEFAULT true) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_a record; v_settings record; v_job jsonb; v_prev record; v_attempt integer;
begin
  if not public.mm_is_operator() then
    return jsonb_build_object('ok', false, 'reason','not_permitted');
  end if;
  select * into v_a from public.security_assets where id = p_asset;
  if not found then return jsonb_build_object('ok', false, 'reason','unknown_asset'); end if;

  select * into v_settings from public.security_scanner_settings where id;

  -- 35. An identical, immutable file already scanned inside the freshness
  -- window does not need scanning again.
  if p_reuse and v_a.sha256 is not null and v_settings.result_freshness_days > 0 then
    select j.* into v_prev
      from public.security_scan_jobs j
      join public.security_assets a2 on a2.id = j.asset_id
     where a2.sha256 = v_a.sha256 and a2.id <> p_asset
       and j.status in ('completed','flagged','blocked')
       and j.completed_at >= now() - (v_settings.result_freshness_days || ' days')::interval
     order by j.completed_at desc limit 1;
    if found then
      return jsonb_build_object('ok', true, 'reused', true,
        'job_id', v_prev.id, 'status', v_prev.status,
        'risk_score', v_prev.risk_score, 'risk_level', v_prev.risk_level,
        'note', format('An identical file (same SHA-256) was scanned within the last %s days; that verdict was reused.',
                       v_settings.result_freshness_days));
    end if;
  end if;

  select coalesce(max(attempt),0)+1 into v_attempt
    from public.security_scan_jobs where asset_id = p_asset;

  insert into public.security_scan_jobs (asset_id, status, attempt, started_at)
  values (p_asset, 'scanning', v_attempt, now())
  returning to_jsonb(security_scan_jobs) into v_job;

  update public.security_assets set status='scanning', updated_at=now() where id = p_asset;

  insert into public.security_events (asset_id, job_id, product_id, event, actor_id, new_state)
  values (p_asset, (v_job->>'id')::uuid, v_a.product_id, 'scan.started', auth.uid(), 'scanning');

  return jsonb_build_object('ok', true, 'reused', false, 'job', v_job);
end;
$$;


--
-- Name: mm_seller_commission_set(uuid, numeric, numeric, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_seller_commission_set(p_seller uuid, p_rate numeric, p_fixed numeric DEFAULT 0, p_currency text DEFAULT 'USD'::text, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_before jsonb; v_after jsonb;
begin
  if not public.mm_seller_operator() then
    return jsonb_build_object('ok', false, 'reason', 'not_permitted');
  end if;
  if p_rate is null or p_rate < 0 or p_rate > 100 then
    return jsonb_build_object('ok', false, 'reason', 'rate_out_of_range',
      'message', 'The marketplace share must be between 0 and 100 percent.');
  end if;
  if not exists (select 1 from public.marketplace_sellers where id = p_seller) then
    return jsonb_build_object('ok', false, 'reason', 'unknown_seller');
  end if;

  select to_jsonb(r) into v_before
    from public.marketplace_commission_rules r
   where r.seller_id = p_seller and r.product_id is null and r.category_id is null
   order by r.priority desc limit 1;

  if v_before is null then
    insert into public.marketplace_commission_rules
      (seller_id, rate_percent, fixed_amount, currency, active, priority)
    values (p_seller, p_rate, coalesce(p_fixed,0), upper(p_currency), true, 10)
    returning to_jsonb(marketplace_commission_rules) into v_after;
  else
    update public.marketplace_commission_rules
       set rate_percent = p_rate, fixed_amount = coalesce(p_fixed,0),
           currency = upper(p_currency), active = true
     where id = (v_before->>'id')::uuid
    returning to_jsonb(marketplace_commission_rules) into v_after;
  end if;

  perform public.mm_audit('seller.commission_rate', 'marketplace_seller',
                          p_seller::text, v_before, v_after, p_reason);
  return jsonb_build_object('ok', true, 'rule', v_after);
end;
$$;


--
-- Name: mm_seller_detail(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_seller_detail(p_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_seller jsonb;
begin
  if not public.mm_seller_operator() then
    return jsonb_build_object('ok', false, 'reason', 'not_permitted');
  end if;

  select to_jsonb(s) into v_seller from public.marketplace_sellers s where s.id = p_id;
  if v_seller is null then
    return jsonb_build_object('ok', false, 'reason', 'unknown_seller');
  end if;

  return jsonb_build_object(
    'ok', true,
    'seller', v_seller,

    'schedule', coalesce(
      (select to_jsonb(x) from public.marketplace_payout_schedules x where x.seller_id = p_id),
      jsonb_build_object('seller_id', p_id, 'cadence','monthly', 'holding_days',14,
                         'minimum_amount',50, 'currency','USD', 'requires_approval',true,
                         'active',true, 'defaulted',true)),

    -- The catalogue rows themselves, read from the one product table. No
    -- second catalogue is kept here.
    'products', coalesce((
      select jsonb_agg(jsonb_build_object(
               'id', p.id, 'name', p.name, 'slug', p.slug, 'version', p.version,
               'category_id', p.category_id, 'visible', p.visible,
               'moderation_status', p.moderation_status,
               'published_at', p.publish_at, 'created_at', p.created_at,
               'sales', (select count(*) from public.marketplace_order_items i
                          where i.product_id = p.id),
               'revenue', (select coalesce(sum(i.line_total),0)
                             from public.marketplace_order_items i
                            where i.product_id = p.id))
             order by p.created_at desc)
        from public.marketplace_products p where p.seller_id = p_id), '[]'::jsonb),

    'earnings', jsonb_build_object(
      'gross',     (select coalesce(sum(gross_amount),0) from public.marketplace_commissions
                     where seller_id = p_id and status <> 'reversed'),
      'marketplace_share', (select coalesce(sum(commission_amount),0)
                              from public.marketplace_commissions
                             where seller_id = p_id and status <> 'reversed'),
      'seller_share', (select coalesce(sum(seller_amount),0)
                         from public.marketplace_commissions
                        where seller_id = p_id and status <> 'reversed'),
      'reversed',  (select coalesce(sum(seller_amount),0) from public.marketplace_commissions
                     where seller_id = p_id and status = 'reversed'),
      'pending',   (select coalesce(sum(seller_amount),0) from public.marketplace_commissions
                     where seller_id = p_id and status = 'pending'),
      'available', (select coalesce(sum(seller_amount),0) from public.marketplace_commissions
                     where seller_id = p_id and status = 'available' and payout_id is null),
      'paid',      (select coalesce(sum(seller_amount),0) from public.marketplace_commissions
                     where seller_id = p_id and status = 'paid')),

    'commissions', coalesce((
      select jsonb_agg(jsonb_build_object(
               'id', c.id, 'order_item_id', c.order_item_id,
               'gross', c.gross_amount, 'marketplace_share', c.commission_amount,
               'seller_share', c.seller_amount, 'status', c.status,
               'payout_id', c.payout_id, 'created_at', c.created_at,
               'rule', c.rule_snapshot)
             order by c.created_at desc)
        from public.marketplace_commissions c where c.seller_id = p_id), '[]'::jsonb),

    'rules', coalesce((
      select jsonb_agg(to_jsonb(r) order by r.priority desc)
        from public.marketplace_commission_rules r where r.seller_id = p_id), '[]'::jsonb),

    'payouts', coalesce((
      select jsonb_agg(jsonb_build_object(
               'id', o.id, 'amount', o.amount, 'currency', o.currency,
               'status', o.status, 'provider_reference', o.provider_reference,
               'created_at', o.created_at, 'updated_at', o.updated_at,
               'lines', (select count(*) from public.marketplace_commissions c
                          where c.payout_id = o.id))
             order by o.created_at desc)
        from public.marketplace_payouts o where o.seller_id = p_id), '[]'::jsonb),

    'ledger', coalesce((
      select jsonb_agg(to_jsonb(l) order by l.created_at desc)
        from public.marketplace_ledger_entries l where l.seller_id = p_id), '[]'::jsonb),

    'members', coalesce((
      select jsonb_agg(jsonb_build_object('user_id', u.user_id, 'role', u.member_role))
        from public.marketplace_seller_users u where u.seller_id = p_id), '[]'::jsonb),

    'audit', coalesce((
      select jsonb_agg(jsonb_build_object(
               'action', a.action, 'actor', a.actor_id, 'at', a.created_at,
               'before', a.before_state, 'after', a.after_state, 'reason', a.reason)
             order by a.created_at desc)
        from public.marketplace_audit_logs a
       where a.entity_id = p_id and a.created_at > now() - interval '180 days'), '[]'::jsonb));
end;
$$;


--
-- Name: mm_seller_earnings_release(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_seller_earnings_release(p_seller uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_released integer;
begin
  if not public.mm_seller_operator() then
    return jsonb_build_object('ok', false, 'reason', 'not_permitted');
  end if;

  with due as (
    select c.id
      from public.marketplace_commissions c
      left join public.marketplace_payout_schedules s on s.seller_id = c.seller_id
     where c.status = 'pending'
       and c.seller_id is not null
       and (p_seller is null or c.seller_id = p_seller)
       and c.created_at <= now() - (coalesce(s.holding_days, 14) || ' days')::interval
       -- A line whose order was later refunded is not eligible, even if the
       -- reversal has not yet flipped this row.
       and not exists (select 1 from public.marketplace_commission_reversals r
                        where r.commission_id = c.id)
  )
  update public.marketplace_commissions c
     set status = 'available'
    from due where c.id = due.id;
  get diagnostics v_released = row_count;

  if v_released > 0 then
    perform public.mm_audit('seller.earnings_released', 'marketplace_seller',
                            coalesce(p_seller::text, 'all'), null,
                            jsonb_build_object('released', v_released), null);
  end if;

  return jsonb_build_object('ok', true, 'released', v_released);
end;
$$;


--
-- Name: mm_seller_kind(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_seller_kind(p_id uuid, p_kind text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_before jsonb; v_after jsonb;
begin
  if not public.mm_seller_operator() then
    return jsonb_build_object('ok', false, 'reason', 'not_permitted');
  end if;
  if p_kind is not null and p_kind not in ('author','vendor') then
    return jsonb_build_object('ok', false, 'reason', 'unknown_kind');
  end if;

  select to_jsonb(s) into v_before from public.marketplace_sellers s where s.id = p_id;
  if v_before is null then
    return jsonb_build_object('ok', false, 'reason', 'unknown_seller');
  end if;

  update public.marketplace_sellers set seller_kind = p_kind, updated_at = now()
   where id = p_id returning to_jsonb(marketplace_sellers) into v_after;

  perform public.mm_audit('seller.kind', 'marketplace_seller', p_id::text,
                          v_before, v_after, null);
  return jsonb_build_object('ok', true, 'seller', v_after);
end;
$$;


--
-- Name: mm_seller_operator(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_seller_operator() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select public.marketplace_is_finance() or public.mm_is_operator();
$$;


--
-- Name: mm_seller_payout_create(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_seller_payout_create(p_seller uuid, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_ids uuid[]; v_amount numeric; v_currency text; v_min numeric;
  v_key text; v_payout jsonb; v_owner uuid; v_attempt integer;
begin
  if not public.mm_seller_operator() then
    return jsonb_build_object('ok', false, 'reason', 'not_permitted');
  end if;

  select s.owner_user_id, s.payout_currency into v_owner, v_currency
    from public.marketplace_sellers s where s.id = p_seller;
  if not found then
    return jsonb_build_object('ok', false, 'reason', 'unknown_seller');
  end if;

  select coalesce(sch.minimum_amount, 50) into v_min
    from public.marketplace_sellers s
    left join public.marketplace_payout_schedules sch on sch.seller_id = s.id
   where s.id = p_seller;

  select array_agg(c.id order by c.id), coalesce(sum(c.seller_amount),0)
    into v_ids, v_amount
    from public.marketplace_commissions c
   where c.seller_id = p_seller and c.status = 'available' and c.payout_id is null;

  if v_ids is null or array_length(v_ids,1) = 0 then
    return jsonb_build_object('ok', false, 'reason', 'nothing_available',
      'message', 'This seller has no released earnings waiting. Release the holding period first.');
  end if;
  if v_amount < v_min then
    return jsonb_build_object('ok', false, 'reason', 'below_minimum',
      'message', format('Available %s is under the %s minimum for this seller.',
                        round(v_amount,2), round(v_min,2)),
      'available', v_amount, 'minimum', v_min);
  end if;

  select count(*) into v_attempt from public.marketplace_payouts
   where seller_id = p_seller and status in ('failed','cancelled');

  v_key := 'payout:' || p_seller::text || ':' || md5(array_to_string(v_ids, ','))
           || ':' || v_attempt::text;

  if exists (select 1 from public.marketplace_payouts where idempotency_key = v_key) then
    return jsonb_build_object('ok', false, 'reason', 'already_created',
      'message', 'A payout for exactly these earnings already exists.');
  end if;

  insert into public.marketplace_payouts
    (seller_id, amount, currency, status, idempotency_key)
  values (p_seller, v_amount, coalesce(v_currency,'USD'), 'pending', v_key)
  returning to_jsonb(marketplace_payouts) into v_payout;

  update public.marketplace_commissions
     set payout_id = (v_payout->>'id')::uuid
   where id = any(v_ids);

  perform public.mm_audit('seller.payout_created', 'marketplace_payout',
                          (v_payout->>'id'), null,
                          v_payout || jsonb_build_object('lines', array_length(v_ids,1)),
                          p_reason);

  if v_owner is not null then
    perform public.mm_notify('payout.created', 'A payout has been prepared',
      format('%s %s covering %s sale(s) is awaiting approval.',
             round(v_amount,2), coalesce(v_currency,'USD'), array_length(v_ids,1)),
      v_owner, null, '/vendor-manager', 'View', 60, 'info');
  end if;

  return jsonb_build_object('ok', true, 'payout', v_payout,
                            'lines', array_length(v_ids,1));
end;
$$;


--
-- Name: mm_seller_payout_status(uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_seller_payout_status(p_id uuid, p_to text, p_reference text DEFAULT NULL::text, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_before jsonb; v_after jsonb; v_owner uuid; v_seller uuid; v_allowed boolean;
begin
  if not public.mm_seller_operator() then
    return jsonb_build_object('ok', false, 'reason', 'not_permitted');
  end if;
  if p_to not in ('pending','approved','processing','completed','failed','cancelled') then
    return jsonb_build_object('ok', false, 'reason', 'unknown_status');
  end if;

  select to_jsonb(o), o.seller_id into v_before, v_seller
    from public.marketplace_payouts o where o.id = p_id;
  if v_before is null then
    return jsonb_build_object('ok', false, 'reason', 'unknown_payout');
  end if;

  -- A settled payout is final. Reopening one would let the same earnings be
  -- paid a second time.
  if (v_before->>'status') = 'completed' then
    return jsonb_build_object('ok', false, 'reason', 'already_completed',
      'message', 'This payout is already settled and cannot be changed.');
  end if;

  v_allowed := case (v_before->>'status')
    when 'pending'    then p_to in ('approved','cancelled','failed')
    when 'approved'   then p_to in ('processing','cancelled','failed')
    when 'processing' then p_to in ('completed','failed')
    when 'failed'     then p_to in ('pending','cancelled')
    when 'cancelled'  then p_to in ('pending')
    else false end;
  if not v_allowed then
    return jsonb_build_object('ok', false, 'reason', 'invalid_transition',
      'message', format('A %s payout cannot become %s.', v_before->>'status', p_to));
  end if;

  if p_to = 'completed' and coalesce(btrim(p_reference),'') = '' then
    return jsonb_build_object('ok', false, 'reason', 'reference_required',
      'message', 'A payout is only paid once the provider has paid it. Enter the '
                 'bank or provider reference for the transfer.');
  end if;

  update public.marketplace_payouts
     set status = p_to,
         provider_reference = coalesce(nullif(btrim(p_reference),''), provider_reference),
         updated_at = now()
   where id = p_id returning to_jsonb(marketplace_payouts) into v_after;

  if p_to = 'completed' then
    -- Now, and only now, the earnings are paid.
    update public.marketplace_commissions set status = 'paid' where payout_id = p_id;

    -- And the ledger records the money leaving. This is the auditable entry
    -- section 35 asks for, carrying its own idempotency key and reference.
    insert into public.marketplace_ledger_entries
      (seller_id, entry_type, amount, currency, immutable_metadata)
    values (v_seller, 'payout', (v_after->>'amount')::numeric,
            v_after->>'currency',
            jsonb_build_object(
              'payout_id', p_id,
              'idempotency_key', v_after->>'idempotency_key',
              'provider_reference', v_after->>'provider_reference',
              'settled_at', now(),
              'lines', (select count(*) from public.marketplace_commissions
                         where payout_id = p_id),
              'audit_reference', 'seller.payout_completed'));

  elsif p_to in ('failed','cancelled') then
    -- Release the lines so they can be paid on the next run. Nothing is lost.
    update public.marketplace_commissions set payout_id = null where payout_id = p_id;
  end if;

  perform public.mm_audit('seller.payout_' || p_to, 'marketplace_payout',
                          p_id::text, v_before, v_after, p_reason);

  select owner_user_id into v_owner from public.marketplace_sellers where id = v_seller;
  if v_owner is not null and p_to in ('completed','failed') then
    perform public.mm_notify(
      'payout.' || p_to,
      case p_to when 'completed' then 'Your payout has been sent'
                else 'Your payout could not be sent' end,
      case p_to when 'completed'
        then format('%s %s, reference %s.', round((v_after->>'amount')::numeric,2),
                    v_after->>'currency', coalesce(v_after->>'provider_reference','—'))
        else coalesce(p_reason, 'The transfer failed. Your earnings are back in the queue.') end,
      v_owner, null, '/vendor-manager', 'View', 5,
      case p_to when 'completed' then 'success' else 'danger' end);
  end if;

  return jsonb_build_object('ok', true, 'payout', v_after);
end;
$$;


--
-- Name: mm_seller_schedule_set(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_seller_schedule_set(p_patch jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_seller uuid := (p_patch->>'seller_id')::uuid; v_before jsonb; v_after jsonb;
begin
  if not public.mm_seller_operator() then
    return jsonb_build_object('ok', false, 'reason', 'not_permitted');
  end if;
  if v_seller is null or not exists (select 1 from public.marketplace_sellers where id = v_seller) then
    return jsonb_build_object('ok', false, 'reason', 'unknown_seller');
  end if;

  select to_jsonb(x) into v_before
    from public.marketplace_payout_schedules x where x.seller_id = v_seller;

  insert into public.marketplace_payout_schedules as s
    (seller_id, cadence, holding_days, minimum_amount, currency,
     requires_approval, payment_method, active)
  values (
    v_seller,
    coalesce(p_patch->>'cadence','monthly'),
    coalesce((p_patch->>'holding_days')::int, 14),
    coalesce((p_patch->>'minimum_amount')::numeric, 50),
    upper(coalesce(p_patch->>'currency','USD')),
    coalesce((p_patch->>'requires_approval')::boolean, true),
    nullif(p_patch->>'payment_method',''),
    coalesce((p_patch->>'active')::boolean, true))
  on conflict (seller_id) do update set
    cadence = coalesce(excluded.cadence, s.cadence),
    holding_days = coalesce(excluded.holding_days, s.holding_days),
    minimum_amount = coalesce(excluded.minimum_amount, s.minimum_amount),
    currency = coalesce(excluded.currency, s.currency),
    requires_approval = coalesce(excluded.requires_approval, s.requires_approval),
    payment_method = coalesce(excluded.payment_method, s.payment_method),
    active = coalesce(excluded.active, s.active),
    updated_at = now()
  returning to_jsonb(s) into v_after;

  perform public.mm_audit('seller.payout_schedule', 'marketplace_seller',
                          v_seller::text, v_before, v_after, null);
  return jsonb_build_object('ok', true, 'schedule', v_after);
end;
$$;


--
-- Name: mm_seller_status(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_seller_status(p_id uuid, p_to text, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_before jsonb; v_after jsonb; v_owner uuid;
begin
  if not public.mm_seller_operator() then
    return jsonb_build_object('ok', false, 'reason', 'not_permitted');
  end if;
  if p_to not in ('pending','approved','rejected','suspended','deactivated') then
    return jsonb_build_object('ok', false, 'reason', 'unknown_status');
  end if;

  select to_jsonb(s), s.owner_user_id into v_before, v_owner
    from public.marketplace_sellers s where s.id = p_id;
  if v_before is null then
    return jsonb_build_object('ok', false, 'reason', 'unknown_seller');
  end if;

  -- A rejection or suspension needs a stated reason. This is a decision that
  -- stops someone earning, and the audit trail should say why.
  if p_to in ('rejected','suspended','deactivated')
     and coalesce(btrim(p_reason),'') = '' then
    return jsonb_build_object('ok', false, 'reason', 'reason_required',
      'message', 'Say why. This decision stops the seller earning and is recorded.');
  end if;

  update public.marketplace_sellers
     set status = p_to,
         approved_at = case when p_to = 'approved' then coalesce(approved_at, now())
                            else approved_at end,
         approved_by = case when p_to = 'approved' then coalesce(approved_by, auth.uid())
                            else approved_by end,
         updated_at = now()
   where id = p_id
  returning to_jsonb(marketplace_sellers) into v_after;

  -- A seller who is no longer approved should not keep their products on the
  -- storefront. Their rows are hidden, never deleted, so reinstating them is
  -- one status change away.
  if p_to in ('rejected','suspended','deactivated') then
    update public.marketplace_products
       set visible = false, updated_at = now()
     where seller_id = p_id and visible;
  end if;

  perform public.mm_audit('seller.' || p_to, 'marketplace_seller', p_id::text,
                          v_before, v_after, p_reason);

  if v_owner is not null then
    perform public.mm_notify(
      'seller.' || p_to,
      case p_to
        when 'approved' then 'Your seller account is approved'
        when 'rejected' then 'Your seller application was not accepted'
        when 'suspended' then 'Your seller account is suspended'
        when 'deactivated' then 'Your seller account is closed'
        else 'Your seller account status changed' end,
      coalesce(p_reason, ''),
      v_owner, null, '/vendor-manager', 'Open', 5,
      case p_to when 'approved' then 'success'
                when 'rejected' then 'warning'
                when 'suspended' then 'danger'
                when 'deactivated' then 'danger' else 'info' end);
  end if;

  return jsonb_build_object('ok', true, 'seller', v_after);
end;
$$;


--
-- Name: mm_sellers(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_sellers(p_query jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_kind   text := nullif(p_query->>'kind','');
  v_search text := nullif(btrim(coalesce(p_query->>'search','')), '');
  v_status text := nullif(p_query->>'status','');
  v_limit  integer := least(greatest(coalesce((p_query->>'limit')::int, 100), 1), 500);
begin
  if not public.mm_seller_operator() then
    return jsonb_build_object('ok', false, 'reason', 'not_permitted');
  end if;
  if v_kind is not null and v_kind not in ('author','vendor') then
    return jsonb_build_object('ok', false, 'reason', 'unknown_kind');
  end if;

  return jsonb_build_object(
    'ok', true,
    'kind', v_kind,

    -- The dashboard. Every figure is counted, none is stored.
    'total',      (select count(*) from public.marketplace_sellers s
                    where v_kind is null or s.seller_kind is not distinct from v_kind),
    'approved',   (select count(*) from public.marketplace_sellers s
                    where s.status = 'approved'
                      and (v_kind is null or s.seller_kind is not distinct from v_kind)),
    'pending',    (select count(*) from public.marketplace_sellers s
                    where s.status = 'pending'
                      and (v_kind is null or s.seller_kind is not distinct from v_kind)),
    'suspended',  (select count(*) from public.marketplace_sellers s
                    where s.status in ('suspended','rejected','deactivated')
                      and (v_kind is null or s.seller_kind is not distinct from v_kind)),
    'unclassified', (select count(*) from public.marketplace_sellers
                      where seller_kind is null),

    'products',   (select count(*) from public.marketplace_products p
                    join public.marketplace_sellers s on s.id = p.seller_id
                   where v_kind is null or s.seller_kind is not distinct from v_kind),
    'published',  (select count(*) from public.marketplace_products p
                    join public.marketplace_sellers s on s.id = p.seller_id
                   where p.visible
                     and (v_kind is null or s.seller_kind is not distinct from v_kind)),
    'sales',      (select count(*) from public.marketplace_commissions c
                    join public.marketplace_sellers s on s.id = c.seller_id
                   where c.status <> 'reversed'
                     and (v_kind is null or s.seller_kind is not distinct from v_kind)),

    -- Money, split the way the brief asks: what the sale was worth, what the
    -- marketplace kept, and what the seller is owed.
    'gross',      (select coalesce(sum(c.gross_amount),0) from public.marketplace_commissions c
                    join public.marketplace_sellers s on s.id = c.seller_id
                   where c.status <> 'reversed'
                     and (v_kind is null or s.seller_kind is not distinct from v_kind)),
    'marketplace_share', (select coalesce(sum(c.commission_amount),0)
                            from public.marketplace_commissions c
                            join public.marketplace_sellers s on s.id = c.seller_id
                           where c.status <> 'reversed'
                             and (v_kind is null or s.seller_kind is not distinct from v_kind)),
    'seller_share', (select coalesce(sum(c.seller_amount),0)
                       from public.marketplace_commissions c
                       join public.marketplace_sellers s on s.id = c.seller_id
                      where c.status <> 'reversed'
                        and (v_kind is null or s.seller_kind is not distinct from v_kind)),
    'reversed',   (select coalesce(sum(c.seller_amount),0)
                     from public.marketplace_commissions c
                     join public.marketplace_sellers s on s.id = c.seller_id
                    where c.status = 'reversed'
                      and (v_kind is null or s.seller_kind is not distinct from v_kind)),
    'pending_earnings', (select coalesce(sum(c.seller_amount),0)
                           from public.marketplace_commissions c
                           join public.marketplace_sellers s on s.id = c.seller_id
                          where c.status = 'pending'
                            and (v_kind is null or s.seller_kind is not distinct from v_kind)),
    'available_earnings', (select coalesce(sum(c.seller_amount),0)
                             from public.marketplace_commissions c
                             join public.marketplace_sellers s on s.id = c.seller_id
                            where c.status = 'available' and c.payout_id is null
                              and (v_kind is null or s.seller_kind is not distinct from v_kind)),
    'paid_earnings', (select coalesce(sum(c.seller_amount),0)
                        from public.marketplace_commissions c
                        join public.marketplace_sellers s on s.id = c.seller_id
                       where c.status = 'paid'
                         and (v_kind is null or s.seller_kind is not distinct from v_kind)),

    'payouts_total', (select coalesce(sum(o.amount),0) from public.marketplace_payouts o
                       join public.marketplace_sellers s on s.id = o.seller_id
                      where v_kind is null or s.seller_kind is not distinct from v_kind),
    'payouts_paid', (select coalesce(sum(o.amount),0) from public.marketplace_payouts o
                      join public.marketplace_sellers s on s.id = o.seller_id
                     where o.status = 'completed'
                       and (v_kind is null or s.seller_kind is not distinct from v_kind)),
    'payouts_pending', (select coalesce(sum(o.amount),0) from public.marketplace_payouts o
                         join public.marketplace_sellers s on s.id = o.seller_id
                        where o.status in ('pending','approved','processing')
                          and (v_kind is null or s.seller_kind is not distinct from v_kind)),

    -- What the catalogue actually looks like, which matters here: almost every
    -- product on this marketplace is first-party and has no seller at all.
    'unassigned_products', (select count(*) from public.marketplace_products
                             where seller_id is null),

    'sellers', coalesce((
      select jsonb_agg(jsonb_build_object(
               'id', s.id, 'name', s.display_name, 'slug', s.slug,
               'status', s.status, 'kind', s.seller_kind,
               'owner_user_id', s.owner_user_id,
               'payout_currency', s.payout_currency,
               'created_at', s.created_at, 'approved_at', s.approved_at,
               'products', (select count(*) from public.marketplace_products p
                             where p.seller_id = s.id),
               'published', (select count(*) from public.marketplace_products p
                              where p.seller_id = s.id and p.visible),
               'sales', (select count(*) from public.marketplace_commissions c
                          where c.seller_id = s.id and c.status <> 'reversed'),
               'gross', (select coalesce(sum(c.gross_amount),0)
                           from public.marketplace_commissions c
                          where c.seller_id = s.id and c.status <> 'reversed'),
               'earned', (select coalesce(sum(c.seller_amount),0)
                            from public.marketplace_commissions c
                           where c.seller_id = s.id and c.status <> 'reversed'),
               'available', (select coalesce(sum(c.seller_amount),0)
                               from public.marketplace_commissions c
                              where c.seller_id = s.id and c.status = 'available'
                                and c.payout_id is null),
               'paid_out', (select coalesce(sum(o.amount),0)
                              from public.marketplace_payouts o
                             where o.seller_id = s.id and o.status = 'completed'),
               'commission_rate', (select r.rate_percent
                                     from public.marketplace_commission_rules r
                                    where r.seller_id = s.id and r.active
                                    order by r.priority desc limit 1),
               'members', (select count(*) from public.marketplace_seller_users u
                            where u.seller_id = s.id))
             order by s.created_at desc)
        from (select * from public.marketplace_sellers s2
               -- An unclassified seller appears in both consoles rather than
               -- falling between them.
               where (v_kind is null or s2.seller_kind is not distinct from v_kind
                      or s2.seller_kind is null)
                 and (v_status is null or s2.status = v_status)
                 and (v_search is null
                      or s2.display_name ilike '%'||v_search||'%'
                      or s2.slug ilike '%'||v_search||'%')
               order by s2.created_at desc limit v_limit) s), '[]'::jsonb));
end;
$$;


--
-- Name: mm_seo_health(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_seo_health() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_last timestamptz; v_pages integer; v_open integer; v_score integer;
begin
  if not public.mm_is_operator() then
    return jsonb_build_object('ok', false, 'reason', 'not_permitted');
  end if;

  select max(last_crawled_at) into v_last from public.seo_pages;
  select count(*) into v_pages from public.seo_pages
   where last_crawled_at is not null;
  select count(*) into v_open from public.seo_issues where status = 'open';

  -- The average of the per-page scores the crawler recorded. No constant.
  select round(avg(seo_score))::int into v_score from public.seo_pages
   where last_crawled_at is not null and seo_score is not null;

  return jsonb_build_object(
    'ok', true,
    'crawled_pages',   v_pages,
    'last_crawl_at',   v_last,
    'seo_score',       coalesce(v_score, 0),
    'score_basis',     'mean of per-page scores from the last crawl',
    'open_issues',     v_open,
    -- Split, because the two are not the same kind of thing. The crawl's
    -- findings are each verifiable by opening the page; the rest predate this
    -- crawler and their source is not recorded, so they are counted apart
    -- rather than folded into one confident total.
    'issues_from_last_crawl', (
      select count(*) from public.seo_issues i
       where i.status = 'open'
         and i.detected_at >= (select max(last_crawled_at) - interval '10 minutes'
                                 from public.seo_pages)),
    'issues_predating_crawler', (
      select count(*) from public.seo_issues i
       where i.status = 'open'
         and i.detected_at < (select max(last_crawled_at) - interval '10 minutes'
                                from public.seo_pages)),
    'by_severity', coalesce((
      select jsonb_object_agg(severity, n) from (
        select severity, count(*) n from public.seo_issues
         where status='open' group by severity) t), '{}'::jsonb),
    'by_type', coalesce((
      select jsonb_agg(jsonb_build_object('type', issue_type, 'count', n) order by n desc)
        from (select issue_type, count(*) n from public.seo_issues
               where status='open' group by issue_type) t), '[]'::jsonb),
    'pages_without_h1',   (select count(*) from public.seo_pages
                            where h1 is null and last_crawled_at is not null),
    'pages_without_meta', (select count(*) from public.seo_pages
                            where coalesce(btrim(meta_description),'') = ''
                              and last_crawled_at is not null),
    'pages_without_canonical', (select count(*) from public.seo_pages
                                 where canonical_url is null and last_crawled_at is not null),
    'thin_pages',         (select count(*) from public.seo_pages
                            where coalesce(word_count,0) < 250 and last_crawled_at is not null),
    'resolved_issues',    (select count(*) from public.seo_issues where status='resolved'),

    -- Named, not hidden. Every one of these needs a provider that is not
    -- connected, and the figures already in those tables cannot be refreshed.
    'unavailable', jsonb_build_object(
      'rankings',    'Search Console and Semrush are disconnected. The 2,160 ranking rows were bulk-imported in a single minute and cannot be refreshed.',
      'keywords',    'The 3,689 keyword rows came with the module; no provider is connected to update volume, CPC or position.',
      'traffic',     'Google Analytics is disconnected — there are no clicks, impressions or CTR to report.',
      'backlinks',   'No backlink provider is connected.',
      'competitors', 'No competitor data source is connected.',
      'core_web_vitals', 'No field-data source is connected; the crawl measures server response time only.'),
    'providers', coalesce((
      select jsonb_agg(jsonb_build_object('provider', provider, 'status', status,
                                          'last_sync', last_sync_at) order by provider)
        from public.seo_integrations), '[]'::jsonb));
end;
$$;


--
-- Name: mm_share_record(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_share_record(p_product uuid, p_channel text, p_kind text DEFAULT 'canonical'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if p_channel not in ('copy','native','whatsapp','facebook','x','linkedin','email','qr_download') then
    return jsonb_build_object('ok', false, 'reason','unknown_channel');
  end if;
  insert into public.product_share_events (product_id, channel, url_kind, actor_id)
  values (p_product, p_channel, p_kind, auth.uid());
  return jsonb_build_object('ok', true);
end;
$$;


--
-- Name: mm_short_link_create(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_short_link_create(p_product uuid, p_campaign text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp', 'extensions'
    AS $$
declare
  v_s record; v_alphabet constant text :=
    'ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz23456789';
  v_code text; v_bytes bytea; i integer; v_row jsonb; v_existing record;
begin
  if not public.mm_is_operator() then
    return jsonb_build_object('ok', false, 'reason','not_permitted');
  end if;
  if not exists (select 1 from public.marketplace_products where id = p_product) then
    return jsonb_build_object('ok', false, 'reason','unknown_product');
  end if;
  select * into v_s from public.product_url_settings where id;

  -- One active short link per product per campaign; asking twice returns the
  -- one that already exists rather than minting another.
  select * into v_existing from public.product_short_links
   where product_id = p_product and status='active'
     and coalesce(campaign,'') = coalesce(p_campaign,'');
  if found then
    return jsonb_build_object('ok', true, 'existing', true, 'code', v_existing.code,
      'url', public.mm_short_link_url(v_existing.code));
  end if;

  for attempt in 1..12 loop
    v_code := '';
    v_bytes := gen_random_bytes(v_s.short_code_length);
    for i in 0..(v_s.short_code_length - 1) loop
      v_code := v_code || substr(v_alphabet, (get_byte(v_bytes, i) % length(v_alphabet)) + 1, 1);
    end loop;
    exit when not exists (select 1 from public.product_short_links where code = v_code);
    v_code := null;
  end loop;
  if v_code is null then
    return jsonb_build_object('ok', false, 'reason','could_not_generate');
  end if;

  insert into public.product_short_links (product_id, code, campaign, created_by)
  values (p_product, v_code, nullif(btrim(p_campaign),''), auth.uid())
  returning to_jsonb(product_short_links) into v_row;

  perform public.mm_audit('url.short_link_created','product_short_link', (v_row->>'id'),
                          null, v_row, null);

  return jsonb_build_object('ok', true, 'existing', false, 'code', v_code,
    'url', public.mm_short_link_url(v_code), 'row', v_row);
end;
$$;


--
-- Name: mm_short_link_resolve(text, text, text, text, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_short_link_resolve(p_code text, p_referrer text DEFAULT NULL::text, p_country text DEFAULT NULL::text, p_device text DEFAULT NULL::text, p_browser text DEFAULT NULL::text, p_visitor_hash text DEFAULT NULL::text, p_utm jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_l record; v_p record; v_u record; v_s record;
begin
  select * into v_l from public.product_short_links where code = p_code;
  if not found then
    return jsonb_build_object('ok', false, 'status', 404, 'reason','unknown_code');
  end if;

  if v_l.status <> 'active' then
    return jsonb_build_object('ok', false,
      'status', case v_l.status when 'disabled' then 410 when 'expired' then 410 else 404 end,
      'reason', v_l.status);
  end if;
  if v_l.expires_at is not null and v_l.expires_at <= now() then
    update public.product_short_links set status='expired' where id = v_l.id;
    return jsonb_build_object('ok', false, 'status', 410, 'reason','expired');
  end if;

  select * into v_p from public.marketplace_products where id = v_l.product_id;
  if not found then
    return jsonb_build_object('ok', false, 'status', 410, 'reason','product_gone');
  end if;

  -- 24. Visibility rules decide, not the link.
  if v_p.deleted_at is not null then
    return jsonb_build_object('ok', false, 'status', 410, 'reason','product_deleted');
  end if;
  if not v_p.visible or v_p.moderation_status <> 'approved' then
    return jsonb_build_object('ok', false, 'status', 404,
      'reason', 'product_unavailable',
      'detail', format('The product is %s and not publicly visible.', v_p.moderation_status));
  end if;

  select * into v_u from public.product_urls
   where product_id = v_l.product_id and language='en' and is_canonical and status='active';
  if not found then
    return jsonb_build_object('ok', false, 'status', 404, 'reason','no_canonical_url');
  end if;

  select * into v_s from public.product_url_settings where id;

  -- 40. Analytics must never stop a valid link working, so the event is written
  -- inside its own block.
  if v_s.track_short_link_clicks then
    begin
      insert into public.product_short_link_events
        (short_link_id, product_id, referrer, country, device_type, browser,
         visitor_hash, utm_source, utm_medium, utm_campaign, utm_content, utm_term,
         purge_after)
      values (v_l.id, v_l.product_id, left(p_referrer, 500), p_country, p_device, p_browser,
              p_visitor_hash,
              p_utm->>'utm_source', p_utm->>'utm_medium',
              coalesce(p_utm->>'utm_campaign', v_l.campaign),
              p_utm->>'utm_content', p_utm->>'utm_term',
              now() + (v_s.analytics_retention_days || ' days')::interval);

      update public.product_short_links
         set click_count = click_count + 1, last_click_at = now()
       where id = v_l.id;
    exception when others then
      null;
    end;
  end if;

  return jsonb_build_object('ok', true, 'status', 302,
    'destination', v_s.site_url || v_u.path,
    'path', v_u.path, 'product_id', v_l.product_id);
end;
$$;


--
-- Name: mm_short_link_url(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_short_link_url(p_code text) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select case
    when s.short_link_domain is not null and s.short_link_domain_verified
      then 'https://' || s.short_link_domain || '/' || p_code
    else s.site_url || '/s/' || p_code end
  from public.product_url_settings s where s.id;
$$;


--
-- Name: mm_slot_assign(text, integer, uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_slot_assign(p_key text, p_position integer, p_product_id uuid, p_override boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  rw record; v_pcat uuid; v_pname text; v_pcatname text;
  v_live boolean; v_mod text; v_license text;
begin
  if not public.mm_is_operator() then
    return jsonb_build_object('ok', false, 'reason', 'not_permitted');
  end if;

  select * into rw from public.mm_row_resolve(p_key);
  if rw.category_id is null and rw.row_id is null then
    return jsonb_build_object('ok', false, 'reason', 'unknown_row');
  end if;

  if p_position < 1 or p_position > rw.max_products then
    return jsonb_build_object('ok', false, 'reason', 'position_out_of_range',
                              'max', rw.max_products);
  end if;

  select p.category_id, p.name, (p.visible and p.content_status='published'),
         p.moderation_status::text, p.license
    into v_pcat, v_pname, v_live, v_mod, v_license
  from public.marketplace_products p where p.id = p_product_id;
  if v_pname is null then
    return jsonb_build_object('ok', false, 'reason', 'unknown_product');
  end if;

  -- Section 6. A curated row has no category of its own, so the check applies
  -- only where the row actually belongs to one.
  if rw.category_id is not null
     and v_pcat is distinct from rw.category_id
     and not (p_override and rw.allow_cross) then
    select c.name into v_pcatname from public.marketplace_categories c where c.id = v_pcat;
    return jsonb_build_object(
      'ok', false, 'reason', 'category_mismatch',
      'message', 'Product category mismatch',
      'product', v_pname,
      'product_category', coalesce(v_pcatname, 'none'),
      'row_category', rw.title,
      'override_allowed', rw.allow_cross);
  end if;

  if not rw.allow_dupes and exists (
    select 1 from public.marketplace_row_slots s
    where (s.row_id = rw.row_id
           or (rw.category_id is not null and s.category_id = rw.category_id))
      and s.product_id = p_product_id and s.position <> p_position)
  then
    return jsonb_build_object('ok', false, 'reason', 'duplicate_product',
      'message', 'This product already occupies another slot in this row.');
  end if;

  -- Slots are keyed by row for curated rows and by category for category rows,
  -- so the delete-then-insert covers both without two code paths.
  delete from public.marketplace_row_slots
  where (row_id = rw.row_id or (rw.category_id is not null and category_id = rw.category_id))
    and position = p_position;

  insert into public.marketplace_row_slots
    (category_id, row_id, position, product_id, added_by)
  values (rw.category_id, rw.row_id, p_position, p_product_id, auth.uid());

  -- Placing anything makes a purely automatic row curated, or it would ignore
  -- the placement and the manager would see nothing happen.
  if rw.category_id is not null then
    insert into public.marketplace_row_config
      (category_id, row_kind, source_mode, updated_by, updated_at)
    values (rw.category_id, 'category', 'hybrid', auth.uid(), now())
    on conflict (category_id) where category_id is not null do update
      set source_mode = case when public.marketplace_row_config.source_mode = 'auto'
                             then 'hybrid' else public.marketplace_row_config.source_mode end,
          updated_by = auth.uid(), updated_at = now();
  else
    update public.marketplace_row_config
       set source_mode = case when source_mode = 'auto' then 'hybrid' else source_mode end,
           updated_by = auth.uid(), updated_at = now()
     where id = rw.row_id;
  end if;

  perform public.mm_audit('row_slot_assign', 'homepage_row',
    coalesce(rw.category_id, rw.row_id)::text,
    jsonb_build_object('row', p_key, 'position', p_position),
    jsonb_build_object('product', v_pname, 'live', v_live,
                       'moderation', v_mod, 'license', v_license),
    'assigned to slot ' || p_position);

  return jsonb_build_object('ok', true, 'row', p_key, 'position', p_position,
    'product', v_pname, 'live', v_live, 'license', v_license);
end $$;


--
-- Name: mm_slot_move(text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_slot_move(p_key text, p_from integer, p_to integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare rw record; v_a uuid; v_b uuid; v_ap boolean; v_bp boolean;
begin
  if not public.mm_is_operator() then
    return jsonb_build_object('ok', false, 'reason', 'not_permitted');
  end if;
  select * into rw from public.mm_row_resolve(p_key);
  if rw.category_id is null and rw.row_id is null then
    return jsonb_build_object('ok', false, 'reason', 'unknown_row');
  end if;

  select product_id, pinned into v_a, v_ap from public.marketplace_row_slots
   where (row_id = rw.row_id or (rw.category_id is not null and category_id = rw.category_id))
     and position = p_from;
  if v_a is null then return jsonb_build_object('ok', false, 'reason', 'empty_source'); end if;

  select product_id, pinned into v_b, v_bp from public.marketplace_row_slots
   where (row_id = rw.row_id or (rw.category_id is not null and category_id = rw.category_id))
     and position = p_to;

  delete from public.marketplace_row_slots
  where (row_id = rw.row_id or (rw.category_id is not null and category_id = rw.category_id))
    and position in (p_from, p_to);

  insert into public.marketplace_row_slots (category_id, row_id, position, product_id, pinned, added_by)
  values (rw.category_id, rw.row_id, p_to, v_a, coalesce(v_ap, true), auth.uid());
  if v_b is not null then
    insert into public.marketplace_row_slots (category_id, row_id, position, product_id, pinned, added_by)
    values (rw.category_id, rw.row_id, p_from, v_b, coalesce(v_bp, true), auth.uid());
  end if;

  perform public.mm_audit('row_slot_move', 'homepage_row',
    coalesce(rw.category_id, rw.row_id)::text,
    jsonb_build_object('row', p_key, 'from', p_from),
    jsonb_build_object('to', p_to), 'moved ' || p_from || ' to ' || p_to);
  return jsonb_build_object('ok', true, 'from', p_from, 'to', p_to, 'swapped', v_b is not null);
end $$;


--
-- Name: mm_slot_pin(text, integer, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_slot_pin(p_key text, p_position integer, p_pinned boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_cat uuid;
begin
  if not public.mm_is_operator() then
    return jsonb_build_object('ok', false, 'reason', 'not_permitted');
  end if;
  select id into v_cat from public.marketplace_categories where slug = p_key;
  if v_cat is null then return jsonb_build_object('ok', false, 'reason', 'unknown_row'); end if;
  update public.marketplace_row_slots set pinned = p_pinned
   where category_id = v_cat and position = p_position;
  return jsonb_build_object('ok', true, 'position', p_position, 'pinned', p_pinned);
end $$;


--
-- Name: mm_slot_remove(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_slot_remove(p_key text, p_position integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare rw record; n int;
begin
  if not public.mm_is_operator() then
    return jsonb_build_object('ok', false, 'reason', 'not_permitted');
  end if;
  select * into rw from public.mm_row_resolve(p_key);
  if rw.category_id is null and rw.row_id is null then
    return jsonb_build_object('ok', false, 'reason', 'unknown_row');
  end if;

  delete from public.marketplace_row_slots
  where (row_id = rw.row_id or (rw.category_id is not null and category_id = rw.category_id))
    and position = p_position;
  get diagnostics n = row_count;

  perform public.mm_audit('row_slot_remove', 'homepage_row',
    coalesce(rw.category_id, rw.row_id)::text,
    jsonb_build_object('row', p_key, 'position', p_position), '{}'::jsonb,
    'cleared slot ' || p_position);
  return jsonb_build_object('ok', true, 'removed', n);
end $$;


--
-- Name: mm_submission_checks(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_submission_checks(p_submission uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_s record; v_p record; v_checks jsonb := '[]'::jsonb; v_seller record;
begin
  select * into v_s from public.author_submissions where id = p_submission;
  if not found then
    return jsonb_build_object('ok', false, 'reason', 'unknown_submission');
  end if;
  select * into v_p from public.marketplace_products where id = v_s.product_id;
  if not found then
    return jsonb_build_object('ok', false, 'reason', 'product_missing',
      'blocking', true,
      'checks', jsonb_build_array(jsonb_build_object(
        'key','product_exists','label','The product still exists',
        'mandatory', true, 'passed', false,
        'detail','The product this submission refers to has been deleted.')));
  end if;

  select * into v_seller from public.marketplace_sellers where id = v_s.seller_id;

  v_checks := jsonb_build_array(
    jsonb_build_object('key','product_exists','label','Product record exists',
      'mandatory', true, 'passed', true, 'detail', v_p.name),

    jsonb_build_object('key','name','label','Product name',
      'mandatory', true, 'passed', coalesce(btrim(v_p.name),'') <> '',
      'detail', coalesce(v_p.name,'missing')),

    jsonb_build_object('key','description','label','Description',
      'mandatory', true, 'passed', length(coalesce(btrim(v_p.description),'')) >= 40,
      'detail', case when coalesce(btrim(v_p.description),'') = '' then 'missing'
                     else format('%s characters', length(btrim(v_p.description))) end),

    jsonb_build_object('key','category','label','Category assigned',
      'mandatory', true, 'passed', v_p.category_id is not null,
      'detail', coalesce((select name from public.marketplace_categories c
                           where c.id = v_p.category_id), 'no category')),

    jsonb_build_object('key','pricing','label','Price set',
      'mandatory', true, 'passed', coalesce(btrim(v_p.price_label),'') <> '',
      'detail', coalesce(nullif(btrim(v_p.price_label),''),'missing')),

    jsonb_build_object('key','license','label','Licence stated',
      'mandatory', true, 'passed', coalesce(btrim(v_p.license),'') <> '',
      'detail', coalesce(nullif(btrim(v_p.license),''),'missing')),

    jsonb_build_object('key','demo','label','Live demo',
      'mandatory', false, 'passed', coalesce(btrim(v_p.demo_url),'') <> '',
      'detail', coalesce(nullif(btrim(v_p.demo_url),''),'no demo URL')),

    jsonb_build_object('key','media','label','Product imagery',
      'mandatory', false,
      'passed', coalesce(btrim(v_p.thumbnail_url),'') <> ''
             or coalesce(btrim(v_p.cover_image),'') <> '',
      'detail', case when coalesce(btrim(v_p.thumbnail_url),'') <> ''
                       or coalesce(btrim(v_p.cover_image),'') <> ''
                     then 'present' else 'no thumbnail or cover image' end),

    -- Author Manager is the source of truth. This reads it; it never copies it.
    jsonb_build_object('key','author','label','Author record',
      'mandatory', false,
      'passed', v_seller.id is not null,
      'detail', case when v_seller.id is null
                     then 'No seller is attached — this is a first-party product.'
                     else format('%s (%s)', v_seller.display_name, v_seller.status) end),

    jsonb_build_object('key','author_approved','label','Author is approved',
      'mandatory', v_seller.id is not null,
      'passed', v_seller.id is null or v_seller.status = 'approved',
      'detail', case when v_seller.id is null then 'not applicable to a first-party product'
                     else format('seller status is %s', v_seller.status) end),

    -- Legal Manager decides this, not us. An unresolved violation or a failed
    -- binding blocks approval; both tables are read, never written.
    jsonb_build_object('key','legal','label','No blocking legal record',
      'mandatory', true,
      'passed', not exists (
        select 1 from public.legal_violations v
         where v.violator_id = v_p.id::text
           and coalesce(v.status,'open') not in ('resolved','dismissed')),
      'detail', case when exists (
          select 1 from public.legal_violations v
           where v.violator_id = v_p.id::text
             and coalesce(v.status,'open') not in ('resolved','dismissed'))
        then 'Legal Manager has an unresolved violation against this product.'
        else 'No unresolved violation recorded in Legal Manager.' end)
  );

  return jsonb_build_object(
    'ok', true,
    'checks', v_checks,
    'mandatory_failed', (select count(*) from jsonb_array_elements(v_checks) c
                          where (c->>'mandatory')::boolean and not (c->>'passed')::boolean),
    'advisory_failed', (select count(*) from jsonb_array_elements(v_checks) c
                         where not (c->>'mandatory')::boolean and not (c->>'passed')::boolean),
    'blocking', (select count(*) from jsonb_array_elements(v_checks) c
                  where (c->>'mandatory')::boolean and not (c->>'passed')::boolean) > 0);
end;
$$;


--
-- Name: mm_submission_create(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_submission_create(p_product uuid, p_type text DEFAULT 'new'::text, p_version uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_p record; v_no text; v_sla record; v_row jsonb; v_rules jsonb; v_start text;
begin
  if not public.mm_is_operator() then
    return jsonb_build_object('ok', false, 'reason', 'not_permitted');
  end if;
  if p_type not in ('new','update') then
    return jsonb_build_object('ok', false, 'reason', 'unknown_type');
  end if;

  select * into v_p from public.marketplace_products where id = p_product;
  if not found then
    return jsonb_build_object('ok', false, 'reason', 'unknown_product');
  end if;

  if exists (select 1 from public.author_submissions
              where product_id = p_product
                and status in ('draft','pending_review','verifying','changes_requested')) then
    return jsonb_build_object('ok', false, 'reason', 'already_open',
      'message', 'This product already has an open submission. Finish or archive it first.');
  end if;

  select * into v_sla from public.author_approval_sla where id;
  v_no := 'SVA-' || lpad(((select count(*) from public.author_submissions) + 1)::text, 4, '0');

  -- The rules decide where a submission starts. Each is read from the table,
  -- never assumed, and the reason is written to the history below.
  v_start := 'pending_review';
  select jsonb_object_agg(key, jsonb_build_object('enabled', enabled, 'config', config))
    into v_rules from public.author_approval_rules;

  if p_type = 'update'
     and coalesce((v_rules->'auto_verify_trusted_updates'->>'enabled')::boolean, false)
     and v_p.seller_id is not null
     and (select count(*) from public.author_submissions
           where seller_id = v_p.seller_id and status = 'approved')
         >= coalesce((v_rules->'auto_verify_trusted_updates'->'config'->>'min_approved')::int, 3)
     and not exists (select 1 from public.legal_violations
                      where violator_id = v_p.seller_id::text
                        and coalesce(status,'open') not in ('resolved','dismissed'))
  then
    v_start := 'verifying';
  end if;

  insert into public.author_submissions
    (submission_no, product_id, seller_id, version_id, submission_type,
     status, submitted_at, sla_due_at, escalate_at, created_by)
  values (v_no, p_product, v_p.seller_id, p_version, p_type,
          v_start, now(),
          now() + (v_sla.response_hours || ' hours')::interval,
          now() + (v_sla.escalate_hours || ' hours')::interval,
          auth.uid())
  returning to_jsonb(author_submissions) into v_row;

  -- The product enters the workflow. It is not publicly visible again until a
  -- decision says so.
  update public.marketplace_products
     set moderation_status = 'submitted', updated_at = now()
   where id = p_product;

  perform public.mm_submission_risk_refresh((v_row->>'id')::uuid);

  insert into public.author_approval_history
    (submission_id, revision, action, from_status, to_status, actor_id, actor_role, reason)
  values ((v_row->>'id')::uuid, 1, 'submitted', null, v_start, auth.uid(), 'operator',
          case when v_start = 'verifying'
               then 'Trusted-author rule sent this update straight to verification.'
               else 'Submitted for review.' end);

  perform public.mm_audit('submission.created','author_submission', v_row->>'id',
                          null, v_row, null);

  return jsonb_build_object('ok', true,
    'submission', (select to_jsonb(s) from public.author_submissions s
                    where s.id = (v_row->>'id')::uuid));
end;
$$;


--
-- Name: mm_submission_detail(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_submission_detail(p_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_s record; v_p jsonb; v_seller jsonb;
begin
  if not public.mm_is_operator() then
    return jsonb_build_object('ok', false, 'reason', 'not_permitted');
  end if;
  select * into v_s from public.author_submissions where id = p_id;
  if not found then
    return jsonb_build_object('ok', false, 'reason', 'unknown_submission');
  end if;

  select jsonb_build_object(
           'id', p.id, 'name', p.name, 'slug', p.slug, 'version', p.version,
           'description', p.description, 'price_label', p.price_label,
           'license', p.license, 'demo_url', p.demo_url,
           'thumbnail_url', p.thumbnail_url, 'cover_image', p.cover_image,
           'tech_stack', p.tech_stack, 'features', p.features,
           'category', (select c.name from public.marketplace_categories c
                         where c.id = p.category_id),
           'moderation_status', p.moderation_status, 'content_status', p.content_status,
           'visible', p.visible, 'public_repo_url', p.public_repo_url)
    into v_p from public.marketplace_products p where p.id = v_s.product_id;

  -- Read from Author Manager. Never copied here.
  select jsonb_build_object(
           'id', s.id, 'name', s.display_name, 'slug', s.slug,
           'status', s.status, 'kind', s.seller_kind,
           'approved_at', s.approved_at, 'owner_user_id', s.owner_user_id,
           'previous_approved', (select count(*) from public.author_submissions x
                                  where x.seller_id = s.id and x.status='approved'),
           'previous_rejected', (select count(*) from public.author_submissions x
                                  where x.seller_id = s.id and x.status='rejected'),
           'open_violations', (select count(*) from public.legal_violations v
                                where v.violator_id = s.id::text
                                  and coalesce(v.status,'open') not in ('resolved','dismissed')))
    into v_seller from public.marketplace_sellers s where s.id = v_s.seller_id;

  return jsonb_build_object(
    'ok', true,
    'submission', to_jsonb(v_s),
    'product', v_p,
    'author', v_seller,
    'checks', public.mm_submission_checks(p_id),
    'risk', public.mm_submission_risk(p_id),

    'versions', coalesce((
      select jsonb_agg(jsonb_build_object(
               'id', v.id, 'version', v.version, 'status', v.status,
               'release_notes', v.release_notes, 'published_at', v.published_at)
             order by v.created_at desc)
        from public.marketplace_product_versions v
       where v.product_id = v_s.product_id), '[]'::jsonb),

    'evidence', coalesce((
      select jsonb_agg(jsonb_build_object(
               'id', e.id, 'kind', e.kind, 'label', e.label,
               'url', e.url, 'has_file', e.storage_path is not null,
               'detail', e.detail, 'created_at', e.created_at)
             order by e.created_at desc)
        from public.author_approval_evidence e where e.submission_id = p_id), '[]'::jsonb),

    'history', coalesce((
      select jsonb_agg(jsonb_build_object(
               'revision', h.revision, 'action', h.action,
               'from', h.from_status, 'to', h.to_status,
               'actor', h.actor_id, 'role', h.actor_role,
               'reason', h.reason, 'comment', h.comment,
               'ai', h.ai_recommendation, 'at', h.created_at)
             order by h.created_at desc)
        from public.author_approval_history h where h.submission_id = p_id), '[]'::jsonb));
end;
$$;


--
-- Name: mm_submission_evidence_add(uuid, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_submission_evidence_add(p_submission uuid, p_kind text, p_label text, p_url text DEFAULT NULL::text, p_detail text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_row jsonb;
begin
  if not public.mm_is_operator() then
    return jsonb_build_object('ok', false, 'reason', 'not_permitted');
  end if;
  if not exists (select 1 from public.author_submissions where id = p_submission) then
    return jsonb_build_object('ok', false, 'reason', 'unknown_submission');
  end if;
  if coalesce(btrim(p_label),'') = '' then
    return jsonb_build_object('ok', false, 'reason', 'label_required');
  end if;
  if coalesce(btrim(p_url),'') = '' and coalesce(btrim(p_detail),'') = '' then
    return jsonb_build_object('ok', false, 'reason', 'nothing_to_record',
      'message', 'Evidence needs a link or a note. An empty entry proves nothing.');
  end if;

  insert into public.author_approval_evidence
    (submission_id, kind, label, url, detail, added_by)
  values (p_submission, p_kind, btrim(p_label),
          nullif(btrim(p_url),''), nullif(btrim(p_detail),''), auth.uid())
  returning to_jsonb(author_approval_evidence) into v_row;

  perform public.mm_audit('submission.evidence_added','author_submission',
                          p_submission::text, null, v_row, null);
  return jsonb_build_object('ok', true, 'evidence', v_row);
end;
$$;


--
-- Name: mm_submission_risk(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_submission_risk(p_submission uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_s record; v_p record; v_seller record;
  v_score integer := 0; v_reasons jsonb := '[]'::jsonb;
  v_approved integer := 0; v_rejected integer := 0; v_violations integer := 0;
  v_checks jsonb;
begin
  select * into v_s from public.author_submissions where id = p_submission;
  if not found then return jsonb_build_object('ok', false, 'reason','unknown_submission'); end if;
  select * into v_p from public.marketplace_products where id = v_s.product_id;
  select * into v_seller from public.marketplace_sellers where id = v_s.seller_id;

  if v_s.seller_id is not null then
    select count(*) filter (where status='approved'),
           count(*) filter (where status='rejected')
      into v_approved, v_rejected
      from public.author_submissions where seller_id = v_s.seller_id and id <> p_submission;
    select count(*) into v_violations from public.legal_violations
     where violator_id = v_s.seller_id::text
       and coalesce(status,'open') not in ('resolved','dismissed');
  end if;

  if v_s.seller_id is not null and v_approved = 0 then
    v_score := v_score + 25;
    v_reasons := v_reasons || jsonb_build_object('factor','new_author','weight',25,
      'evidence','This seller has no previously approved submission.',
      'source','author_submissions');
  end if;

  if v_seller.id is not null and v_seller.status <> 'approved' then
    v_score := v_score + 30;
    v_reasons := v_reasons || jsonb_build_object('factor','author_not_verified','weight',30,
      'evidence', format('Author Manager has this seller as %s.', v_seller.status),
      'source','marketplace_sellers');
  end if;

  if v_rejected > 0 then
    v_score := v_score + least(v_rejected * 10, 25);
    v_reasons := v_reasons || jsonb_build_object('factor','previous_rejections',
      'weight', least(v_rejected * 10, 25),
      'evidence', format('%s previous submission(s) from this seller were rejected.', v_rejected),
      'source','author_submissions');
  end if;

  if v_violations > 0 then
    v_score := v_score + 30;
    v_reasons := v_reasons || jsonb_build_object('factor','open_violations','weight',30,
      'evidence', format('%s unresolved legal violation(s) against this seller.', v_violations),
      'source','legal_violations');
  end if;

  v_checks := public.mm_submission_checks(p_submission);
  if (v_checks->>'mandatory_failed')::int > 0 then
    v_score := v_score + 20;
    v_reasons := v_reasons || jsonb_build_object('factor','incomplete_submission','weight',20,
      'evidence', format('%s mandatory check(s) are failing.', v_checks->>'mandatory_failed'),
      'source','mm_submission_checks');
  end if;

  if coalesce(btrim(v_p.demo_url),'') = '' then
    v_score := v_score + 10;
    v_reasons := v_reasons || jsonb_build_object('factor','no_demo','weight',10,
      'evidence','No live demo, so the product cannot be inspected before approval.',
      'source','marketplace_products.demo_url');
  end if;

  -- Claims a reviewer should look at rather than take on trust.
  if v_p.description ~* '(guaranteed|100% secure|unlimited free|no risk|certified by)' then
    v_score := v_score + 15;
    v_reasons := v_reasons || jsonb_build_object('factor','unsupported_claims','weight',15,
      'evidence','The description contains an absolute claim that needs evidence.',
      'source','marketplace_products.description');
  end if;

  -- The same product text under a different name is a duplicate-listing signal.
  if v_p.description is not null and length(btrim(v_p.description)) > 40
     and exists (select 1 from public.marketplace_products x
                  where x.id <> v_p.id and x.description = v_p.description) then
    v_score := v_score + 15;
    v_reasons := v_reasons || jsonb_build_object('factor','duplicate_description','weight',15,
      'evidence','Another listing carries exactly this description.',
      'source','marketplace_products');
  end if;

  v_score := least(v_score, 100);

  return jsonb_build_object(
    'ok', true,
    'score', v_score,
    'level', case when v_score >= 70 then 'critical'
                  when v_score >= 45 then 'high'
                  when v_score >= 20 then 'medium' else 'low' end,
    'reasons', v_reasons,
    'author_history', jsonb_build_object(
      'approved', v_approved, 'rejected', v_rejected, 'open_violations', v_violations),
    'advisory', true,
    'note','Advisory only. Nothing in this workflow approves or rejects because of this score.');
end;
$$;


--
-- Name: mm_submission_risk_refresh(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_submission_risk_refresh(p_submission uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_r jsonb;
begin
  v_r := public.mm_submission_risk(p_submission);
  if not (v_r->>'ok')::boolean then return v_r; end if;
  update public.author_submissions
     set risk_score = (v_r->>'score')::int,
         risk_level = v_r->>'level',
         risk_reasons = v_r->'reasons',
         updated_at = now()
   where id = p_submission;
  return v_r;
end;
$$;


--
-- Name: mm_submission_transition(uuid, text, text, integer, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_submission_transition(p_id uuid, p_to text, p_reason text DEFAULT NULL::text, p_lock integer DEFAULT NULL::integer, p_comment text DEFAULT NULL::text, p_override boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_s record; v_after jsonb; v_allowed boolean; v_checks jsonb;
  v_owner uuid; v_rules jsonb; v_notify boolean; v_role text;
begin
  if not public.mm_is_operator() then
    return jsonb_build_object('ok', false, 'reason', 'not_permitted');
  end if;
  if p_to not in ('draft','pending_review','verifying','changes_requested',
                  'approved','rejected','suspended','archived') then
    return jsonb_build_object('ok', false, 'reason', 'unknown_status');
  end if;

  select * into v_s from public.author_submissions where id = p_id for update;
  if not found then
    return jsonb_build_object('ok', false, 'reason', 'unknown_submission');
  end if;

  -- Optimistic concurrency. Two reviewers cannot both act on what they read.
  if p_lock is not null and p_lock <> v_s.lock_version then
    return jsonb_build_object('ok', false, 'reason', 'stale',
      'message', 'Submission changed by another reviewer. Refresh before continuing.',
      'current_status', v_s.status, 'current_lock', v_s.lock_version);
  end if;

  v_allowed := case v_s.status
    when 'draft'              then p_to in ('pending_review','archived')
    when 'pending_review'     then p_to in ('verifying','changes_requested','rejected','archived')
    when 'verifying'          then p_to in ('approved','rejected','changes_requested')
    when 'changes_requested'  then p_to in ('pending_review','rejected','archived')
    when 'approved'           then p_to in ('suspended','archived')
    when 'rejected'           then p_to in ('archived')
    when 'suspended'          then p_to in ('approved','archived')
    when 'archived'           then false
    else false end;

  -- The boss override in section 34. It never skips the reason, the actor or
  -- the history — it only widens which transitions are legal.
  if not v_allowed and p_override then
    if not (public.has_role(auth.uid(),'admin') or public.has_role(auth.uid(),'boss')
            or public.has_role(auth.uid(),'super_admin')) then
      return jsonb_build_object('ok', false, 'reason', 'override_not_permitted',
        'message', 'Only the boss or an admin can override the workflow.');
    end if;
    if coalesce(btrim(p_reason),'') = '' then
      return jsonb_build_object('ok', false, 'reason', 'override_reason_required',
        'message', 'An override has to say why. It is recorded permanently.');
    end if;
    v_allowed := true;
  end if;

  if not v_allowed then
    return jsonb_build_object('ok', false, 'reason', 'invalid_transition',
      'message', format('A %s submission cannot become %s.', v_s.status, p_to));
  end if;

  -- Decisions that stop or change someone's work need a stated reason.
  if p_to in ('changes_requested','rejected','suspended')
     and coalesce(btrim(p_reason),'') = '' then
    return jsonb_build_object('ok', false, 'reason', 'reason_required',
      'message', 'Say why. The author is told, and this is recorded permanently.');
  end if;

  -- The publishing gate. Approval is refused outright while a mandatory check
  -- is failing, override or not: an unapproved product must never be public.
  if p_to = 'approved' then
    v_checks := public.mm_submission_checks(p_id);
    if (v_checks->>'blocking')::boolean then
      return jsonb_build_object('ok', false, 'reason', 'checks_failed',
        'message', format('%s mandatory check(s) are failing. Approval is blocked until they pass.',
                          v_checks->>'mandatory_failed'),
        'checks', v_checks->'checks');
    end if;
  end if;

  update public.author_submissions
     set status = p_to,
         reviewer_id = case when p_to = 'verifying' then coalesce(reviewer_id, auth.uid())
                            else reviewer_id end,
         review_started_at = case when p_to = 'verifying' then coalesce(review_started_at, now())
                                  else review_started_at end,
         -- A resubmission is a new revision. The previous one stays in history.
         revision = case when p_to = 'pending_review' and v_s.status = 'changes_requested'
                         then revision + 1 else revision end,
         decided_at = case when p_to in ('approved','rejected') then now() else decided_at end,
         decided_by = case when p_to in ('approved','rejected') then auth.uid() else decided_by end,
         last_action = p_to,
         last_reason = nullif(btrim(p_reason),''),
         lock_version = lock_version + 1,
         updated_at = now()
   where id = p_id returning to_jsonb(author_submissions) into v_after;

  /* ------------------------------------------------- the publishing gate */
  -- The product's public state follows the decision, never the other way round.
  if p_to = 'approved' then
    update public.marketplace_products
       set moderation_status = 'approved', content_status = 'published',
           visible = true, approved_at = now(), approved_by = auth.uid(),
           updated_at = now()
     where id = v_s.product_id;

    if v_s.version_id is not null then
      update public.marketplace_product_versions
         set status = 'published', published_at = now()
       where id = v_s.version_id;
    end if;

  elsif p_to = 'rejected' then
    update public.marketplace_products
       set moderation_status = 'rejected', content_status = 'draft',
           visible = false, updated_at = now()
     where id = v_s.product_id;

  elsif p_to = 'suspended' then
    update public.marketplace_products
       set moderation_status = 'suspended', content_status = 'draft',
           visible = false, updated_at = now()
     where id = v_s.product_id;

  elsif p_to = 'changes_requested' then
    update public.marketplace_products
       set moderation_status = 'changes_requested', updated_at = now()
     where id = v_s.product_id;

  elsif p_to = 'verifying' then
    update public.marketplace_products
       set moderation_status = 'under_review', updated_at = now()
     where id = v_s.product_id;

  elsif p_to = 'archived' then
    update public.marketplace_products
       set moderation_status = 'archived', content_status = 'archived',
           visible = false, updated_at = now()
     where id = v_s.product_id;
  end if;

  perform public.mm_submission_risk_refresh(p_id);

  v_role := case when public.has_role(auth.uid(),'boss') then 'boss'
                 when public.has_role(auth.uid(),'admin') then 'admin'
                 else 'marketplace_manager' end;

  insert into public.author_approval_history
    (submission_id, revision, action, from_status, to_status,
     actor_id, actor_role, reason, comment)
  values (p_id, (v_after->>'revision')::int,
          case when p_override then 'override:' || p_to else p_to end,
          v_s.status, p_to, auth.uid(), v_role,
          nullif(btrim(p_reason),''), nullif(btrim(p_comment),''));

  perform public.mm_audit(
    case when p_override then 'submission.override' else 'submission.' || p_to end,
    'author_submission', p_id::text, to_jsonb(v_s), v_after, p_reason);

  -- The author is told, through the notification engine, if the rule says so.
  select coalesce((select enabled from public.author_approval_rules
                    where key='notify_author_on_change'), true) into v_notify;
  select s.owner_user_id into v_owner
    from public.marketplace_sellers s where s.id = v_s.seller_id;

  if v_owner is not null and (v_notify or p_to in ('approved','rejected','suspended')) then
    perform public.mm_notify(
      'submission.' || p_to,
      case p_to
        when 'approved' then 'Your product has been approved and is live'
        when 'rejected' then 'Your submission was not accepted'
        when 'changes_requested' then 'Changes are needed before approval'
        when 'verifying' then 'Verification has started on your submission'
        when 'suspended' then 'Your product has been suspended'
        when 'archived' then 'Your submission has been archived'
        else 'Your submission status changed' end,
      coalesce(p_reason, format('%s is now %s.', v_after->>'submission_no', p_to)),
      v_owner, null, '/author-manager', 'Open', 5,
      case p_to when 'approved' then 'success'
                when 'rejected' then 'warning'
                when 'changes_requested' then 'warning'
                when 'suspended' then 'danger' else 'info' end);
  end if;

  return jsonb_build_object('ok', true, 'submission', v_after,
    'published', p_to = 'approved');
end;
$$;


--
-- Name: mm_submissions(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_submissions(p_query jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_status text := nullif(p_query->>'status','');
  v_search text := nullif(btrim(coalesce(p_query->>'search','')),'');
  v_risk   text := nullif(p_query->>'risk','');
  v_type   text := nullif(p_query->>'type','');
  v_sort   text := coalesce(p_query->>'sort','newest');
  v_limit  integer := least(greatest(coalesce((p_query->>'limit')::int,100),1),500);
  v_sla record;
begin
  if not public.mm_is_operator() then
    return jsonb_build_object('ok', false, 'reason', 'not_permitted');
  end if;
  select * into v_sla from public.author_approval_sla where id;

  return jsonb_build_object(
    'ok', true,

    -- The metric cards. Counted, never stored.
    'counts', jsonb_build_object(
      'draft',             (select count(*) from public.author_submissions where status='draft'),
      'pending_review',    (select count(*) from public.author_submissions where status='pending_review'),
      'verifying',         (select count(*) from public.author_submissions where status='verifying'),
      'changes_requested', (select count(*) from public.author_submissions where status='changes_requested'),
      'approved',          (select count(*) from public.author_submissions where status='approved'),
      'rejected',          (select count(*) from public.author_submissions where status='rejected'),
      'suspended',         (select count(*) from public.author_submissions where status='suspended'),
      'archived',          (select count(*) from public.author_submissions where status='archived')),

    'sla', jsonb_build_object(
      'response_hours', v_sla.response_hours,
      'escalate_hours', v_sla.escalate_hours,
      'stale_draft_days', v_sla.stale_draft_days,
      'breached', (select count(*) from public.author_submissions
                    where status in ('pending_review','verifying') and escalate_at <= now()),
      'due_soon', (select count(*) from public.author_submissions
                    where status in ('pending_review','verifying')
                      and sla_due_at between now() and now() + interval '4 hours')),

    'rules', coalesce((select jsonb_agg(to_jsonb(r) order by r.key)
                         from public.author_approval_rules r), '[]'::jsonb),

    -- Trusted authors, derived from what actually happened rather than a
    -- toggle. Author Manager stays the source of truth for status and identity.
    'trusted_authors', coalesce((
      select jsonb_agg(jsonb_build_object(
               'seller_id', s.id, 'name', s.display_name, 'kind', s.seller_kind,
               'status', s.status,
               'approved', (select count(*) from public.author_submissions x
                             where x.seller_id = s.id and x.status='approved'),
               'rejected', (select count(*) from public.author_submissions x
                             where x.seller_id = s.id and x.status='rejected'),
               'violations', (select count(*) from public.legal_violations v
                               where v.violator_id = s.id::text
                                 and coalesce(v.status,'open') not in ('resolved','dismissed')),
               'last_review', (select max(x.decided_at) from public.author_submissions x
                                where x.seller_id = s.id),
               'trust_level', case
                 when s.status <> 'approved' then 'untrusted'
                 when exists (select 1 from public.legal_violations v
                               where v.violator_id = s.id::text
                                 and coalesce(v.status,'open') not in ('resolved','dismissed'))
                   then 'flagged'
                 when (select count(*) from public.author_submissions x
                        where x.seller_id = s.id and x.status='approved') >= 3 then 'trusted'
                 when (select count(*) from public.author_submissions x
                        where x.seller_id = s.id and x.status='approved') >= 1 then 'known'
                 else 'new' end)
             order by s.display_name)
        from public.marketplace_sellers s), '[]'::jsonb),

    'total', (select count(*) from public.author_submissions),

    'submissions', coalesce((
      select jsonb_agg(jsonb_build_object(
               'id', q.id, 'submission_no', q.submission_no,
               'product_id', q.product_id, 'product', q.product_name,
               'seller_id', q.seller_id, 'author', q.author_name,
               'type', q.submission_type, 'status', q.status,
               'revision', q.revision,
               'risk_score', q.risk_score, 'risk_level', q.risk_level,
               'risk_reasons', q.risk_reasons,
               'reviewer_id', q.reviewer_id,
               'submitted_at', q.submitted_at, 'decided_at', q.decided_at,
               'sla_due_at', q.sla_due_at, 'escalate_at', q.escalate_at,
               'escalated_at', q.escalated_at,
               'sla_state', case
                 when q.status not in ('pending_review','verifying') then 'n/a'
                 when q.escalate_at <= now() then 'breached'
                 when q.sla_due_at <= now() then 'overdue'
                 when q.sla_due_at <= now() + interval '4 hours' then 'due_soon'
                 else 'on_track' end,
               'last_action', q.last_action, 'last_reason', q.last_reason,
               'lock_version', q.lock_version,
               'history', (select count(*) from public.author_approval_history h
                            where h.submission_id = q.id))
             order by q.ord)
        from (
          select s.*, p.name as product_name, sel.display_name as author_name,
                 row_number() over (order by
                   case when v_sort='oldest' then s.submitted_at end asc,
                   case when v_sort='risk' then s.risk_score end desc,
                   case when v_sort='sla' then s.escalate_at end asc,
                   s.submitted_at desc) ord
            from public.author_submissions s
            left join public.marketplace_products p on p.id = s.product_id
            left join public.marketplace_sellers sel on sel.id = s.seller_id
           where (v_status is null or s.status = v_status)
             and (v_risk is null or s.risk_level = v_risk)
             and (v_type is null or s.submission_type = v_type)
             and (v_search is null
                  or s.submission_no ilike '%'||v_search||'%'
                  or coalesce(p.name,'') ilike '%'||v_search||'%'
                  or coalesce(sel.display_name,'') ilike '%'||v_search||'%'
                  or s.seller_id::text = v_search
                  or s.product_id::text = v_search)
           limit v_limit) q), '[]'::jsonb));
end;
$$;


--
-- Name: mm_submissions_bulk(uuid[], text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_submissions_bulk(p_ids uuid[], p_to text, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_id uuid; v_res jsonb; v_out jsonb := '[]'::jsonb;
        v_done integer := 0; v_skipped integer := 0;
begin
  if not public.mm_is_operator() then
    return jsonb_build_object('ok', false, 'reason', 'not_permitted');
  end if;
  if p_ids is null or array_length(p_ids,1) is null then
    return jsonb_build_object('ok', false, 'reason', 'nothing_selected');
  end if;
  if array_length(p_ids,1) > 100 then
    return jsonb_build_object('ok', false, 'reason', 'too_many',
      'message','Bulk actions are limited to 100 submissions at a time.');
  end if;

  foreach v_id in array p_ids loop
    -- No lock is passed: a bulk action reads and acts in one statement, so
    -- there is nothing stale to guard against here.
    v_res := public.mm_submission_transition(v_id, p_to, p_reason, null, null, false);
    if (v_res->>'ok')::boolean then v_done := v_done + 1;
    else v_skipped := v_skipped + 1; end if;
    v_out := v_out || jsonb_build_object(
      'id', v_id, 'ok', (v_res->>'ok')::boolean,
      'reason', v_res->>'reason', 'message', v_res->>'message');
  end loop;

  perform public.mm_audit('submission.bulk_'||p_to,'author_submission', null, null,
                          jsonb_build_object('applied', v_done, 'skipped', v_skipped),
                          p_reason);

  return jsonb_build_object('ok', true, 'applied', v_done, 'skipped', v_skipped,
                            'results', v_out);
end;
$$;


--
-- Name: mm_topbar_configure(text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_topbar_configure(p_key text, p_patch jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_before jsonb; v_component text; v_planned boolean;
begin
  if not public.mm_is_operator() then
    return jsonb_build_object('ok', false, 'reason', 'not_permitted');
  end if;

  select to_jsonb(m), m.component, coalesce((m.config->>'planned')::boolean,false)
    into v_before, v_component, v_planned
  from public.marketplace_topbar_modules m where m.module_key = p_key;
  if v_before is null then
    return jsonb_build_object('ok', false, 'reason', 'unknown_module');
  end if;

  if p_patch->>'status' = 'live' and v_component is null then
    return jsonb_build_object('ok', false, 'reason', 'not_rendered',
      'message', 'Nothing in the header renders this module yet, so making it '
                 'live would not put it on the storefront. '
                 || coalesce(v_before->'config'->>'needs', ''));
  end if;

  update public.marketplace_topbar_modules set
    name            = coalesce(p_patch->>'name', name),
    status          = coalesce(p_patch->>'status', status),
    sort_order      = coalesce((p_patch->>'sort_order')::int, sort_order),
    desktop_enabled = coalesce((p_patch->>'desktop_enabled')::boolean, desktop_enabled),
    tablet_enabled  = coalesce((p_patch->>'tablet_enabled')::boolean, tablet_enabled),
    mobile_enabled  = coalesce((p_patch->>'mobile_enabled')::boolean, mobile_enabled),
    sticky_enabled  = coalesce((p_patch->>'sticky_enabled')::boolean, sticky_enabled),
    featured        = coalesce((p_patch->>'featured')::boolean, featured),
    config          = coalesce(p_patch->'config', config),
    updated_by = auth.uid(), updated_at = now()
  where module_key = p_key;

  perform public.mm_audit('topbar_configure', 'topbar_module', p_key,
    v_before, p_patch, 'top bar module changed');

  return jsonb_build_object('ok', true, 'module', p_key);
end $$;


--
-- Name: mm_topbar_modules(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_topbar_modules() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select coalesce(jsonb_agg(jsonb_build_object(
    'module_key', m.module_key, 'name', m.name, 'category', m.category,
    'description', m.description, 'component', m.component,
    'sort_order', m.sort_order, 'status', m.status,
    'desktop_enabled', m.desktop_enabled,
    'tablet_enabled', m.tablet_enabled,
    'mobile_enabled', m.mobile_enabled,
    'sticky_enabled', m.sticky_enabled,
    'featured', m.featured,
    'config', m.config,
    'live', (m.status = 'live'),
    -- True only when a component in TopUtilityBar actually renders it. A
    -- planned module can be configured, but the manager must not imply it is
    -- on the storefront.
    'rendered', (m.component is not null),
    'planned', coalesce((m.config->>'planned')::boolean, false),
    'blocked_reason', m.config->>'reason',
    'updated_at', m.updated_at) order by m.sort_order, m.module_key), '[]'::jsonb)
  from public.marketplace_topbar_modules m
  where m.status <> 'archived';
$$;


--
-- Name: mm_topbar_reorder(text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_topbar_reorder(p_keys text[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare i int := 0; k text; n int := 0;
begin
  if not public.mm_is_operator() then
    return jsonb_build_object('ok', false, 'reason', 'not_permitted');
  end if;
  foreach k in array p_keys loop
    i := i + 1;
    update public.marketplace_topbar_modules
       set sort_order = i, updated_by = auth.uid(), updated_at = now()
     where module_key = k;
    if found then n := n + 1; end if;
  end loop;
  perform public.mm_audit('topbar_reorder', 'topbar_module', 'all',
    '{}'::jsonb, jsonb_build_object('order', to_jsonb(p_keys)), 'top bar reordered');
  return jsonb_build_object('ok', true, 'modules', n);
end $$;


--
-- Name: mm_trust_badge_set(text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_trust_badge_set(p_key text, p_patch jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_before jsonb; v_after jsonb;
begin
  if not public.mm_is_operator() then
    return jsonb_build_object('ok', false, 'reason', 'not_permitted');
  end if;
  select to_jsonb(b) into v_before from public.trust_badges b where b.key = p_key;
  if v_before is null then
    return jsonb_build_object('ok', false, 'reason', 'unknown_badge');
  end if;

  update public.trust_badges set
    enabled = coalesce((p_patch->>'enabled')::boolean, enabled),
    label = coalesce(nullif(p_patch->>'label',''), label),
    description = coalesce(nullif(p_patch->>'description',''), description),
    priority = coalesce((p_patch->>'priority')::int, priority),
    display_locations = coalesce(
      (select array_agg(x)::text[] from jsonb_array_elements_text(p_patch->'display_locations') x),
      display_locations),
    updated_at = now()
  where key = p_key returning to_jsonb(trust_badges) into v_after;

  insert into public.trust_audit_logs (badge_key, action, actor_id, before_state, after_state, reason)
  values (p_key,
          case when (v_after->>'enabled')::boolean is distinct from (v_before->>'enabled')::boolean
               then (case when (v_after->>'enabled')::boolean then 'badge.enabled' else 'badge.disabled' end)
               else 'badge.rule_changed' end,
          auth.uid(), v_before, v_after, nullif(p_patch->>'reason',''));

  perform public.mm_audit('trust.badge_changed', 'trust_badge', p_key, v_before, v_after, null);
  return jsonb_build_object('ok', true, 'badge', v_after);
end;
$$;


--
-- Name: mm_trust_badges(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_trust_badges() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if not public.mm_is_operator() then
    return jsonb_build_object('ok', false, 'reason', 'not_permitted');
  end if;
  return jsonb_build_object(
    'ok', true,
    'badges', coalesce((select jsonb_agg(to_jsonb(b) order by b.priority)
                          from public.trust_badges b), '[]'::jsonb),
    'audit', coalesce((select jsonb_agg(jsonb_build_object(
                          'badge', a.badge_key, 'action', a.action,
                          'at', a.created_at, 'reason', a.reason) order by a.created_at desc)
                         from (select * from public.trust_audit_logs
                                order by created_at desc limit 40) a), '[]'::jsonb),
    -- What each badge would look like on a real product right now, so an
    -- operator can see the rule working rather than trust the description.
    'sample', (select public.trust_evaluate(p.id, 'product_detail')
                 from public.marketplace_products p
                where p.visible order by p.updated_at desc limit 1));
end;
$$;


--
-- Name: mm_url_bulk(text, integer, uuid, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_url_bulk(p_scope text DEFAULT 'published'::text, p_batch integer DEFAULT 200, p_job uuid DEFAULT NULL::uuid, p_ids uuid[] DEFAULT NULL::uuid[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_job uuid := p_job; v_r record; v_res jsonb;
  v_done integer := 0; v_ok integer := 0; v_fail integer := 0;
  v_skip integer := 0; v_conf integer := 0; v_total integer; v_remaining integer;
begin
  if not public.mm_is_operator() then
    return jsonb_build_object('ok', false, 'reason','not_permitted');
  end if;
  if p_scope not in ('all','selected','category','published','unpublished') then
    return jsonb_build_object('ok', false, 'reason','unknown_scope');
  end if;

  if v_job is null then
    select count(*) into v_total from public.marketplace_products p
     where p.deleted_at is null
       and case p_scope
             when 'published' then p.visible
             when 'unpublished' then not p.visible
             when 'selected' then p.id = any(coalesce(p_ids, '{}'::uuid[]))
             else true end;

    insert into public.product_url_jobs (scope, operation, status, total, actor_id)
    values (p_scope, 'generate', 'running', v_total, auth.uid())
    returning id into v_job;
  end if;

  for v_r in
    select p.id from public.marketplace_products p
     where p.deleted_at is null
       and case p_scope
             when 'published' then p.visible
             when 'unpublished' then not p.visible
             when 'selected' then p.id = any(coalesce(p_ids, '{}'::uuid[]))
             else true end
       -- Only what has not been done yet, so the job is resumable and a retry
       -- cannot double-process anything.
       and not exists (select 1 from public.product_urls u
                        where u.product_id = p.id and u.is_canonical and u.status='active')
     order by p.updated_at desc
     limit greatest(least(p_batch, 1000), 1)
  loop
    v_done := v_done + 1;
    v_res := public.mm_url_generate(v_r.id, 'Bulk generation', v_job);
    if (v_res->>'ok')::boolean then
      v_ok := v_ok + 1;
      if coalesce((v_res->>'collision_handled')::boolean, false) then v_conf := v_conf + 1; end if;
    elsif v_res->>'reason' = 'no_route' then
      v_fail := v_fail + 1;
    else
      v_skip := v_skip + 1;
    end if;
  end loop;

  update public.product_url_jobs
     set processed = processed + v_done, succeeded = succeeded + v_ok,
         failed = failed + v_fail, skipped = skipped + v_skip,
         conflicts = conflicts + v_conf
   where id = v_job;

  select total - processed into v_remaining from public.product_url_jobs where id = v_job;

  if v_done = 0 or v_remaining <= 0 then
    update public.product_url_jobs
       set status = case when failed > 0 then 'partial' else 'succeeded' end,
           finished_at = now()
     where id = v_job;
  end if;

  return jsonb_build_object('ok', true, 'job_id', v_job,
    'batch_processed', v_done, 'succeeded', v_ok, 'failed', v_fail,
    'skipped', v_skip, 'conflicts', v_conf,
    'remaining', greatest(coalesce(v_remaining,0), 0),
    'done', v_done = 0);
end;
$$;


--
-- Name: mm_url_generate(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_url_generate(p_product uuid, p_reason text DEFAULT NULL::text, p_correlation uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_p record; v_slug jsonb; v_path jsonb; v_base text; v_try text; v_p2 jsonb;
  v_existing record; v_old record; i integer := 1; v_row jsonb; v_conflict boolean := false;
begin
  if not public.mm_is_operator() then
    return jsonb_build_object('ok', false, 'reason','not_permitted');
  end if;
  select * into v_p from public.marketplace_products where id = p_product;
  if not found then return jsonb_build_object('ok', false, 'reason','unknown_product'); end if;

  v_slug := public.mm_url_slugify(v_p.name, p_product);
  v_base := v_slug->>'slug';
  v_try := v_base;

  -- 7. Find a path nobody else holds.
  loop
    v_path := public.mm_url_path(p_product, v_try);
    if not (v_path->>'ok')::boolean then return v_path; end if;

    select * into v_existing from public.product_urls
     where path = (v_path->>'path') and language = 'en'
       and product_id <> p_product and status <> 'purged';
    exit when not found;

    v_conflict := true;
    i := i + 1;
    if i > 60 then
      return jsonb_build_object('ok', false, 'reason','could_not_generate');
    end if;
    v_try := left(v_base, 84) || '-' || i::text;
  end loop;

  -- The product's current canonical, if it has one.
  select * into v_old from public.product_urls
   where product_id = p_product and language='en' and is_canonical and status='active';

  if found and v_old.path = (v_path->>'path') then
    return jsonb_build_object('ok', true, 'changed', false,
      'path', v_old.path, 'url', (select site_url from public.product_url_settings where id) || v_old.path,
      'note','Already correct; nothing was changed.');
  end if;

  -- 8. The old URL becomes a redirect rather than disappearing.
  if found then
    update public.product_urls
       set is_canonical = false, status = 'redirect', updated_at = now()
     where id = v_old.id;
  end if;

  insert into public.product_urls
    (product_id, slug, path, language, status, is_canonical, generated_by, created_by)
  values (p_product, v_try, v_path->>'path', 'en', 'active', true,
          case when p_correlation is null then 'system' else 'bulk' end, auth.uid())
  returning to_jsonb(product_urls) into v_row;

  if v_old.id is not null then
    update public.product_urls set redirect_to = (v_row->>'id')::uuid where id = v_old.id;
    insert into public.product_url_history
      (product_id, old_path, new_path, changed_by, reason, correlation_id)
    values (p_product, v_old.path, v_path->>'path', auth.uid(),
            coalesce(p_reason, 'Canonical URL regenerated.'), p_correlation);
  end if;

  -- The product's own slug follows its canonical URL, so the storefront route
  -- and the URL table cannot disagree.
  update public.marketplace_products set slug = v_try, updated_at = now()
   where id = p_product and slug is distinct from v_try;

  perform public.mm_audit('url.generated','product_url', (v_row->>'id'),
    case when v_old.id is null then null else jsonb_build_object('path', v_old.path) end,
    v_row, p_reason);

  return jsonb_build_object('ok', true, 'changed', true,
    'path', v_path->>'path',
    'url', (select site_url from public.product_url_settings where id) || (v_path->>'path'),
    'slug', v_try, 'collision_handled', v_conflict,
    'previous_path', v_old.path,
    'note', case when v_old.path is null then null
      else 'The previous URL now redirects here, so links already shared keep working.' end);
end;
$$;


--
-- Name: mm_url_path(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_url_path(p_product uuid, p_slug text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_s record; v_p record; v_path text; v_cat text; v_prefix text;
begin
  select * into v_s from public.product_url_settings where id;
  select p.*, c.slug as category_slug into v_p
    from public.marketplace_products p
    left join public.marketplace_categories c on c.id = p.category_id
   where p.id = p_product;
  if not found then return jsonb_build_object('ok', false, 'reason','unknown_product'); end if;

  v_cat := coalesce(nullif(v_p.category_slug,''), 'uncategorised');

  v_path := v_s.canonical_pattern;
  v_path := replace(v_path, '{product-name}', p_slug);
  v_path := replace(v_path, '{category}', v_cat);
  v_path := replace(v_path, '{product-id}', left(replace(p_product::text,'-',''), 8));
  v_path := replace(v_path, '{brand}', 'softwarevala');
  v_path := replace(v_path, '{language}', 'en');
  v_path := regexp_replace(v_path, '/{2,}', '/', 'g');

  -- The pattern must land on a path this application actually serves.
  select prefix into v_prefix from public.product_url_route_prefixes
   where v_path like prefix || '/%' order by length(prefix) desc limit 1;

  return jsonb_build_object('ok', v_prefix is not null, 'path', v_path,
    'served_by', v_prefix,
    'reason', case when v_prefix is null then 'no_route' else null end,
    'message', case when v_prefix is null then
      format('Nothing serves %s. A canonical URL built from this pattern would be a 404 for every product.', v_path)
      else null end);
end;
$$;


--
-- Name: mm_url_resolve(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_url_resolve(p_path text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_u record; v_t record; v_s record;
begin
  select * into v_u from public.product_urls where path = p_path and language='en';
  if not found then
    return jsonb_build_object('ok', false, 'status', 404, 'reason','unknown_path');
  end if;
  select * into v_s from public.product_url_settings where id;

  if v_u.status = 'active' then
    return jsonb_build_object('ok', true, 'status', 200, 'path', v_u.path,
      'product_id', v_u.product_id);
  end if;

  if v_u.status = 'redirect' and v_u.redirect_to is not null then
    select * into v_t from public.product_urls where id = v_u.redirect_to;
    if found and v_t.status = 'active' then
      return jsonb_build_object('ok', true, 'status', 301,
        'destination', v_s.site_url || v_t.path, 'path', v_t.path,
        'product_id', v_t.product_id);
    end if;
  end if;

  return jsonb_build_object('ok', false,
    'status', case v_u.status when 'disabled' then 410 when 'soft_deleted' then 410 else 404 end,
    'reason', v_u.status);
end;
$$;


--
-- Name: mm_url_settings_set(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_url_settings_set(p_patch jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_before jsonb; v_after jsonb; v_pattern text; v_prefix text;
begin
  if not public.mm_is_operator() then
    return jsonb_build_object('ok', false, 'reason','not_permitted');
  end if;

  -- 2. A pattern whose prefix nothing serves is refused, because every URL it
  -- produced would be a 404.
  v_pattern := nullif(p_patch->>'canonical_pattern','');
  if v_pattern is not null then
    select prefix into v_prefix from public.product_url_route_prefixes
     where v_pattern like prefix || '/%' order by length(prefix) desc limit 1;
    if v_prefix is null then
      return jsonb_build_object('ok', false, 'reason','no_route',
        'message', format('Nothing serves %s. Add a route for that path before making it the canonical pattern, or every product URL would be a 404.', v_pattern),
        'served_prefixes', (select jsonb_agg(prefix) from public.product_url_route_prefixes));
    end if;
  end if;

  select to_jsonb(s) into v_before from public.product_url_settings s where s.id;

  update public.product_url_settings set
    canonical_pattern = coalesce(v_pattern, canonical_pattern),
    lowercase_hyphenate = coalesce((p_patch->>'lowercase_hyphenate')::boolean, lowercase_hyphenate),
    strip_stop_words = coalesce((p_patch->>'strip_stop_words')::boolean, strip_stop_words),
    include_product_id_suffix = coalesce((p_patch->>'include_product_id_suffix')::boolean, include_product_id_suffix),
    short_link_domain = case when p_patch ? 'short_link_domain'
                             then nullif(p_patch->>'short_link_domain','') else short_link_domain end,
    track_short_link_clicks = coalesce((p_patch->>'track_short_link_clicks')::boolean, track_short_link_clicks),
    generate_qr_on_publish = coalesce((p_patch->>'generate_qr_on_publish')::boolean, generate_qr_on_publish),
    qr_foreground = coalesce(nullif(p_patch->>'qr_foreground',''), qr_foreground),
    qr_background = coalesce(nullif(p_patch->>'qr_background',''), qr_background),
    qr_size = coalesce((p_patch->>'qr_size')::int, qr_size),
    qr_error_correction = coalesce(nullif(p_patch->>'qr_error_correction',''), qr_error_correction),
    analytics_retention_days = coalesce((p_patch->>'analytics_retention_days')::int, analytics_retention_days),
    -- Changing the vanity domain always un-verifies it: a new host has not been
    -- proven to resolve.
    short_link_domain_verified = case when p_patch ? 'short_link_domain' then false
                                      else short_link_domain_verified end,
    updated_by = auth.uid(), updated_at = now()
  where id returning to_jsonb(product_url_settings) into v_after;

  perform public.mm_audit('url.settings_changed','product_url_settings','settings',
                          v_before, v_after, nullif(p_patch->>'reason',''));
  return jsonb_build_object('ok', true, 'settings', v_after);
end;
$$;


--
-- Name: mm_url_slugify(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_url_slugify(p_text text, p_product uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare v_s record; v_base text; v_words text[]; v_kept text[]; w text; v_removed text[] := '{}';
begin
  select * into v_s from public.product_url_settings where id;
  v_base := coalesce(btrim(p_text), '');

  if v_s.lowercase_hyphenate then
    v_base := lower(v_base);
  end if;

  -- Accented Latin becomes its base letter; anything else non-alphanumeric
  -- becomes a separator.
  v_base := translate(v_base,
    'áàâäãåāăąéèêëēĕėęěíìîïĩīĭįóòôöõōŏőúùûüũūŭůýÿñçšžćđłđ',
    'aaaaaaaaaeeeeeeeeeiiiiiiiiooooooooouuuuuuuuyyncszcdld');
  v_base := regexp_replace(v_base, '[^a-zA-Z0-9]+', '-', 'g');
  v_base := regexp_replace(v_base, '(^-+|-+$)', '', 'g');
  v_base := regexp_replace(v_base, '-{2,}', '-', 'g');

  if v_s.strip_stop_words and coalesce(v_base,'') <> '' then
    v_words := string_to_array(v_base, '-');
    v_kept := '{}';
    foreach w in array v_words loop
      if w = any(v_s.stop_words) then v_removed := v_removed || w;
      else v_kept := v_kept || w; end if;
    end loop;
    -- Never strip a name down to nothing.
    if array_length(v_kept,1) is not null and array_length(v_kept,1) > 0 then
      v_base := array_to_string(v_kept, '-');
    else
      v_removed := '{}';
    end if;
  end if;

  v_base := left(v_base, 90);
  v_base := regexp_replace(v_base, '-+$', '', 'g');

  if coalesce(v_base,'') = '' then
    v_base := 'product-' || left(replace(coalesce(p_product, gen_random_uuid())::text,'-',''), 10);
  end if;
  if v_base ~ '^[0-9-]' then v_base := 'p-' || v_base; end if;

  if v_s.include_product_id_suffix and p_product is not null then
    v_base := v_base || '-p' || left(replace(p_product::text,'-',''), 6);
  end if;

  return jsonb_build_object('ok', true, 'slug', v_base,
    'stop_words_removed', to_jsonb(v_removed),
    'lowercased', v_s.lowercase_hyphenate);
end;
$_$;


--
-- Name: mm_vala_tv(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_vala_tv() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if not public.mm_is_operator() then
    return jsonb_build_object('ok', false, 'reason', 'not_permitted');
  end if;

  return jsonb_build_object(
    'ok', true,
    'total',      (select count(*) from public.vala_tv_videos),
    'published',  (select count(*) from public.vala_tv_videos where status='published'),
    'drafts',     (select count(*) from public.vala_tv_videos where status='draft'),
    'scheduled',  (select count(*) from public.vala_tv_videos where status='scheduled'),
    'archived',   (select count(*) from public.vala_tv_videos where status='archived'),
    'categories', (select count(*) from public.vala_tv_categories where not archived),
    'views',      (select count(*) from public.vala_tv_views),
    'live_now',   jsonb_array_length(public.sf_vala_tv()),
    'videos', coalesce((
      select jsonb_agg(jsonb_build_object(
               'id', v.id, 'title', v.title, 'url', v.url, 'status', v.status,
               'category', c.name, 'featured', v.featured, 'position', v.position,
               'product', p.name,
               'views', (select count(*) from public.vala_tv_views w where w.video_id = v.id),
               'publish_at', v.publish_at, 'updated_at', v.updated_at)
             order by v.position, v.created_at desc)
        from public.vala_tv_videos v
        left join public.vala_tv_categories c on c.id = v.category_id
        left join public.marketplace_products p on p.id = v.product_id), '[]'::jsonb),
    'category_list', coalesce((
      select jsonb_agg(jsonb_build_object('id', id, 'name', name, 'slug', slug,
                                          'position', position, 'visible', visible)
             order by position)
        from public.vala_tv_categories where not archived), '[]'::jsonb));
end;
$$;


--
-- Name: mm_vala_tv_save(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_vala_tv_save(p_patch jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_id uuid := nullif(p_patch->>'id','')::uuid; v_before jsonb; v_after jsonb;
begin
  if not public.mm_is_operator() then
    return jsonb_build_object('ok', false, 'reason', 'not_permitted');
  end if;

  if v_id is not null then
    select to_jsonb(v) into v_before from public.vala_tv_videos v where v.id = v_id;
    if v_before is null then
      return jsonb_build_object('ok', false, 'reason', 'unknown_video');
    end if;
  end if;

  if v_id is null then
    insert into public.vala_tv_videos
      (title, description, url, thumbnail_url, duration, category_id, product_id,
       language, country, status, featured, position, publish_at,
       seo_title, seo_description, created_by, updated_by)
    values (
      coalesce(nullif(btrim(p_patch->>'title'),''), 'Untitled video'),
      nullif(p_patch->>'description',''),
      nullif(btrim(p_patch->>'url'),''),
      nullif(p_patch->>'thumbnail_url',''),
      nullif(p_patch->>'duration',''),
      nullif(p_patch->>'category_id','')::uuid,
      nullif(p_patch->>'product_id','')::uuid,
      coalesce(nullif(p_patch->>'language',''), 'en'),
      nullif(p_patch->>'country',''),
      -- A new video is a draft. Adding one must not put it on the homepage
      -- before anybody has watched it.
      'draft',
      coalesce((p_patch->>'featured')::boolean, false),
      coalesce((p_patch->>'position')::int, 50),
      nullif(p_patch->>'publish_at','')::timestamptz,
      nullif(p_patch->>'seo_title',''),
      nullif(p_patch->>'seo_description',''),
      auth.uid(), auth.uid())
    returning to_jsonb(vala_tv_videos) into v_after;
  else
    update public.vala_tv_videos v set
      title         = coalesce(nullif(btrim(p_patch->>'title'),''), v.title),
      description   = case when p_patch ? 'description' then nullif(p_patch->>'description','') else v.description end,
      url           = case when p_patch ? 'url' then nullif(btrim(p_patch->>'url'),'') else v.url end,
      thumbnail_url = case when p_patch ? 'thumbnail_url' then nullif(p_patch->>'thumbnail_url','') else v.thumbnail_url end,
      duration      = case when p_patch ? 'duration' then nullif(p_patch->>'duration','') else v.duration end,
      category_id   = case when p_patch ? 'category_id' then nullif(p_patch->>'category_id','')::uuid else v.category_id end,
      product_id    = case when p_patch ? 'product_id' then nullif(p_patch->>'product_id','')::uuid else v.product_id end,
      language      = coalesce(nullif(p_patch->>'language',''), v.language),
      country       = case when p_patch ? 'country' then nullif(p_patch->>'country','') else v.country end,
      featured      = coalesce((p_patch->>'featured')::boolean, v.featured),
      position      = coalesce((p_patch->>'position')::int, v.position),
      publish_at    = case when p_patch ? 'publish_at' then nullif(p_patch->>'publish_at','')::timestamptz else v.publish_at end,
      seo_title     = case when p_patch ? 'seo_title' then nullif(p_patch->>'seo_title','') else v.seo_title end,
      seo_description = case when p_patch ? 'seo_description' then nullif(p_patch->>'seo_description','') else v.seo_description end,
      updated_by = auth.uid(), updated_at = now()
    where v.id = v_id
    returning to_jsonb(v) into v_after;
  end if;

  perform public.mm_audit(
    case when v_id is null then 'valatv.created' else 'valatv.updated' end,
    'vala_tv_video', coalesce(v_id::text, v_after->>'id'), v_before, v_after, null);

  return jsonb_build_object('ok', true, 'video', v_after);
end;
$$;


--
-- Name: mm_vala_tv_status(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mm_vala_tv_status(p_id uuid, p_to text, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v record; v_before jsonb; v_after jsonb; v_problems text[] := '{}';
begin
  if not public.mm_is_operator() then
    return jsonb_build_object('ok', false, 'reason', 'not_permitted');
  end if;
  if p_to not in ('draft','scheduled','published','archived') then
    return jsonb_build_object('ok', false, 'reason', 'unknown_status');
  end if;

  select * into v from public.vala_tv_videos where id = p_id;
  if not found then
    return jsonb_build_object('ok', false, 'reason', 'unknown_video');
  end if;
  v_before := to_jsonb(v);

  -- Publishing is the step that reaches the public homepage, so it is the one
  -- that checks the video can actually be watched.
  if p_to = 'published' then
    if coalesce(btrim(v.url), '') = '' then
      v_problems := v_problems || 'The video has no address, so nothing would play.'::text;
    end if;
    if coalesce(btrim(v.title), '') = '' then
      v_problems := v_problems || 'The video needs a title.'::text;
    end if;
    if array_length(v_problems, 1) > 0 then
      return jsonb_build_object('ok', false, 'reason', 'validation_failed',
                                'problems', to_jsonb(v_problems));
    end if;
  end if;

  update public.vala_tv_videos set
    status = p_to,
    published_at = case when p_to = 'published' then coalesce(published_at, now()) else published_at end,
    updated_by = auth.uid(), updated_at = now()
  where id = p_id
  returning to_jsonb(vala_tv_videos) into v_after;

  perform public.mm_audit('valatv.' || p_to, 'vala_tv_video', p_id::text,
                          v_before, v_after, p_reason);

  return jsonb_build_object('ok', true, 'video', v_after,
                            'live_now', jsonb_array_length(public.sf_vala_tv()));
end;
$$;


--
-- Name: payment_admin_refund(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.payment_admin_refund(p_payment_id uuid, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_payment public.payments%ROWTYPE;
BEGIN
  IF v_actor IS NULL OR NOT (public.has_role(v_actor, 'admin') OR public.has_role(v_actor, 'boss') OR public.has_role(v_actor, 'finance')) THEN RAISE EXCEPTION 'Authorization required'; END IF;
  SELECT * INTO v_payment FROM public.payments WHERE id = p_payment_id FOR UPDATE;
  IF NOT FOUND OR v_payment.status IN ('refunded','rejected') THEN RAISE EXCEPTION 'Payment cannot be refunded'; END IF;
  UPDATE public.payments SET status = 'refunded', updated_at = now() WHERE id = p_payment_id RETURNING * INTO v_payment;
  UPDATE public.payment_intents SET status = 'refunded', updated_at = now() WHERE id = v_payment.intent_id;
  INSERT INTO public.payment_audit_logs (actor_id, action, intent_id, payment_id, amount, status, metadata)
  VALUES (v_actor, 'refund', v_payment.intent_id, v_payment.id, v_payment.amount, 'refunded', jsonb_build_object('reason', left(coalesce(p_reason, ''), 500)));
  RETURN to_jsonb(v_payment);
END; $$;


--
-- Name: payment_gate_is_open(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.payment_gate_is_open(p_country text DEFAULT NULL::text, p_method text DEFAULT NULL::text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT c.payments_enabled
    AND (p_method IS DISTINCT FROM 'card' OR c.card_enabled)
    AND (p_country IS NULL OR NOT (upper(p_country) = ANY(c.blocked_countries)))
    AND (cardinality(c.allowed_countries) = 0 OR p_country IS NULL OR upper(p_country) = ANY(c.allowed_countries))
    AND NOT EXISTS (SELECT 1 FROM public.payment_blacklist b WHERE b.user_id = auth.uid())
  FROM public.payment_controls c WHERE c.id = true;
$$;


--
-- Name: payment_intent_amount(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.payment_intent_amount(p_item_id text, p_item_type text) RETURNS numeric
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE v_amount numeric;
BEGIN
  IF p_item_id ~ '^[0-9a-fA-F-]{36}$' THEN
    SELECT total INTO v_amount FROM public.marketplace_orders WHERE id = p_item_id::uuid;
    IF v_amount IS NULL THEN SELECT amount INTO v_amount FROM public.reseller_membership_orders WHERE id = p_item_id::uuid; END IF;
    IF v_amount IS NULL THEN SELECT amount INTO v_amount FROM public.reseller_subscriptions WHERE id = p_item_id::uuid; END IF;
  END IF;
  IF v_amount IS NULL AND p_item_type = 'product' AND p_item_id ~ '^[0-9a-fA-F-]{36}$' THEN
    SELECT amount INTO v_amount FROM public.marketplace_product_pricing WHERE product_id = p_item_id::uuid AND active = true ORDER BY created_at DESC LIMIT 1;
  END IF;
  RETURN v_amount;
END; $_$;


--
-- Name: prevent_blackbox_modification(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prevent_blackbox_modification() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RAISE EXCEPTION 'BLACKBOX is immutable - modifications are forbidden';
END; $$;


--
-- Name: process_payment_success_events(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.process_payment_success_events(p_limit integer DEFAULT 25) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_event public.payment_event_outbox%ROWTYPE;
  v_payment public.payments%ROWTYPE;
  v_order uuid;
  v_done integer := 0;
BEGIN
  FOR v_event IN SELECT * FROM public.payment_event_outbox WHERE status IN ('pending','failed') AND available_at <= now() ORDER BY created_at FOR UPDATE SKIP LOCKED LIMIT greatest(1, least(p_limit, 100)) LOOP
    UPDATE public.payment_event_outbox SET status = 'processing', attempts = attempts + 1 WHERE id = v_event.id;
    SELECT * INTO v_payment FROM public.payments WHERE id = v_event.payment_id FOR UPDATE;
    IF NOT FOUND OR v_payment.status NOT IN ('approved','completed') THEN
      UPDATE public.payment_event_outbox SET status = 'failed', last_error = 'Payment is not approved', available_at = now() + interval '5 minutes' WHERE id = v_event.id;
      CONTINUE;
    END IF;
    IF v_payment.item_type = 'product' AND v_payment.item_id ~ '^[0-9a-fA-F-]{36}$' THEN
      SELECT id INTO v_order FROM public.marketplace_orders WHERE id = v_payment.item_id::uuid FOR UPDATE;
      IF v_order IS NOT NULL THEN
        UPDATE public.marketplace_orders SET status = 'paid', updated_at = now() WHERE id = v_order AND status = 'pending_payment';
        INSERT INTO public.marketplace_entitlements (buyer_id, order_item_id, product_id, status)
        SELECT o.buyer_id, oi.id, oi.product_id, 'active' FROM public.marketplace_orders o JOIN public.marketplace_order_items oi ON oi.order_id = o.id WHERE o.id = v_order
        ON CONFLICT (order_item_id) DO NOTHING;
        INSERT INTO public.marketplace_licenses (order_item_id, buyer_id, product_id, status)
        SELECT oi.id, o.buyer_id, oi.product_id, 'issued' FROM public.marketplace_orders o JOIN public.marketplace_order_items oi ON oi.order_id = o.id WHERE o.id = v_order
        ON CONFLICT (order_item_id) DO NOTHING;
      END IF;
    END IF;
    UPDATE public.payment_event_outbox SET status = 'completed', processed_at = now(), last_error = NULL WHERE id = v_event.id;
    INSERT INTO public.payment_audit_logs (action, payment_id, amount, status, metadata) VALUES ('PAYMENT_SUCCESS_PROCESSED', v_payment.id, v_payment.amount, 'completed', jsonb_build_object('event_id', v_event.id));
    v_done := v_done + 1;
  END LOOP;
  RETURN jsonb_build_object('processed', v_done, 'processed_at', now());
END; $_$;


--
-- Name: pt_allowed_transitions(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pt_allowed_transitions(p_from text) RETURNS text[]
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select case p_from
    when 'draft'            then array['pending_approval','pending','active','cancelled']
    when 'pending_approval' then array['active','pending','draft','cancelled']
    when 'pending'          then array['active','due_soon','delayed','fulfilled','cancelled']
    when 'active'           then array['due_soon','delayed','fulfilled','broken','cancelled']
    when 'due_soon'         then array['active','delayed','fulfilled','broken','cancelled']
    when 'delayed'          then array['broken','fulfilled','active','cancelled']
    when 'broken'           then array['fulfilled','delayed','cancelled']
    when 'fulfilled'        then array['locked','active']
    when 'locked'           then array['fulfilled']   -- only via an authorised unlock
    when 'cancelled'        then array[]::text[]
    else array[]::text[]
  end;
$$;


--
-- Name: pt_apply_fine(uuid, uuid, text, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pt_apply_fine(p_promise_id uuid, p_rule_id uuid, p_note text DEFAULT NULL::text, p_basis numeric DEFAULT NULL::numeric, p_actor text DEFAULT 'system'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  p        public.promises%rowtype;
  r        public.promise_rules%rowtype;
  s        public.promise_settings%rowtype;
  v_amount numeric;
  v_id     uuid;
begin
  -- Money is an operator decision. These run as SECURITY DEFINER and were
  -- granted to authenticated, so without this any signed-in person could fine
  -- somebody else or release a tip to themselves.
  if auth.uid() is not null and not public.pt_is_operator() then
    return jsonb_build_object('ok', false, 'reason', 'not_permitted');
  end if;

  select * into s from public.promise_settings limit 1;
  if s is not null and not s.fine_system_enabled then
    return jsonb_build_object('ok', false, 'reason', 'fine_system_disabled');
  end if;

  select * into p from public.promises where id = p_promise_id;
  if not found then return jsonb_build_object('ok', false, 'reason', 'no_such_promise'); end if;

  select * into r from public.promise_rules where id = p_rule_id and is_active;
  if not found then return jsonb_build_object('ok', false, 'reason', 'no_such_rule'); end if;
  if r.kind <> 'fine' then return jsonb_build_object('ok', false, 'reason', 'not_a_fine_rule'); end if;

  -- One rule fines one promise once.
  if exists (select 1 from public.promise_ledger
             where promise_id = p_promise_id and rule_id = p_rule_id
               and kind = 'fine' and status <> 'reversed') then
    return jsonb_build_object('ok', false, 'reason', 'already_applied');
  end if;

  v_amount := public.pt_rule_amount(r, p_basis, p.delay_days);
  if v_amount <= 0 then
    return jsonb_build_object('ok', false, 'reason', 'nothing_to_charge');
  end if;

  insert into public.promise_ledger
    (promise_id, rule_id, kind, amount, currency, basis, status, actor, actor_user_id, note)
  values (p_promise_id, p_rule_id, 'fine', v_amount, p.currency,
          r.rule_type || case when p_basis is not null then ' of ' || p_basis::text else '' end,
          'applied', p_actor, auth.uid(), coalesce(p_note, r.name))
  returning id into v_id;

  update public.promises
     set fine_amount = (select coalesce(sum(amount), 0) from public.promise_ledger
                        where promise_id = p_promise_id and kind = 'fine' and status = 'applied'),
         fine_status = 'applied'
   where id = p_promise_id;

  perform public.pt_audit('Fine Applied', p_promise_id,
    format('%s: %s %s', r.name, p.currency, v_amount), null, v_amount::text,
    'promise_tracker', p_actor = 'system');

  return jsonb_build_object('ok', true, 'ledger_id', v_id, 'amount', v_amount,
                            'rule', r.name);
end;
$$;


--
-- Name: pt_apply_insight(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pt_apply_insight(p_insight_id uuid, p_action text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  i        public.promise_ai_insights%rowtype;
  p        public.promises%rowtype;
  v_action text;
  v_level  integer;
  v_result jsonb;
begin
  select * into i from public.promise_ai_insights where id = p_insight_id;
  if not found then
    return jsonb_build_object('ok', false, 'reason', 'no_such_insight');
  end if;
  if i.state <> 'open' then
    return jsonb_build_object('ok', false, 'reason', 'already_actioned');
  end if;

  select * into p from public.promises where id = i.promise_id;
  if not found then
    return jsonb_build_object('ok', false, 'reason', 'no_such_promise');
  end if;

  if not (public.pt_is_operator() or public.pt_is_manager()) then
    return jsonb_build_object('ok', false, 'reason', 'not_permitted');
  end if;

  -- Where the caller does not name an action, take the one the advice implies.
  v_action := coalesce(p_action,
    case
      when i.escalation_advice ilike '%level 4%' or i.escalation_advice ilike '%legal%'
        then 'notify_manager'   -- never escalate straight to legal on advice alone
      when i.escalation_advice ilike '%level%' then 'raise_escalation'
      when i.delay_risk >= 70 then 'notify_manager'
      else 'send_reminder'
    end);

  if v_action not in ('send_reminder', 'notify_manager', 'raise_escalation') then
    return jsonb_build_object('ok', false, 'reason', 'action_not_allowed');
  end if;

  if v_action = 'send_reminder' then
    perform public.pt_notify(p.id, 'owner',
      format('Reminder - %s', p.code),
      coalesce(i.suggested_action, p.title), 'promise_reminder');
    update public.promises set reminded_at = now() where id = p.id;

  elsif v_action = 'notify_manager' then
    perform public.pt_notify(p.id, 'manager',
      format('Attention - %s', p.code),
      format('%s (miss probability %s%%). %s',
             p.title, i.miss_probability, coalesce(i.suggested_action, '')),
      'promise_attention');

  else
    -- One step up the ladder, never a jump to the end of it. pt_escalate
    -- refuses a level already raised, so applying twice cannot double-escalate.
    v_level := least(4, coalesce(p.escalation_level, 0) + 1);
    v_result := public.pt_escalate(p.id, v_level,
      coalesce(i.escalation_advice, 'raised on AI advice'), 'ai_advice');
    if not coalesce((v_result ->> 'ok')::boolean, false) then
      return jsonb_build_object('ok', false, 'reason', v_result ->> 'reason');
    end if;
  end if;

  update public.promise_ai_insights
     set state = 'applied', acted_by = auth.uid(), acted_at = now()
   where id = p_insight_id;

  perform public.pt_audit('AI Suggestion Applied', p.id,
    format('%s: %s', v_action, coalesce(i.suggested_action, '')), 'open', 'applied');

  return jsonb_build_object('ok', true, 'action', v_action);
end;
$$;


--
-- Name: pt_audit(text, uuid, text, text, text, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pt_audit(p_action text, p_promise_id uuid DEFAULT NULL::uuid, p_details text DEFAULT NULL::text, p_old text DEFAULT NULL::text, p_new text DEFAULT NULL::text, p_source text DEFAULT 'promise_tracker'::text, p_system boolean DEFAULT false) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_id     uuid;
  v_email  text;
  v_role   text;
  v_code   text;
begin
  select u.email into v_email from auth.users u where u.id = auth.uid();
  select ur.role::text into v_role from public.user_roles ur
   where ur.user_id = auth.uid()
   order by case ur.role::text
     when 'boss_owner' then 1 when 'founder' then 2 when 'boss' then 3
     when 'super_admin' then 4 when 'admin' then 5 else 9 end
   limit 1;
  select code into v_code from public.promises where id = p_promise_id;

  insert into public.promise_audit_logs
    (action, promise_id, promise_code, actor, actor_key, actor_user_id,
     actor_role, details, old_value, new_value, source_module, is_system)
  values
    (p_action, p_promise_id, v_code,
     coalesce(v_email, case when auth.uid() is null then 'system' else 'account' end),
     lower(coalesce(v_email, 'system')),
     auth.uid(),
     coalesce(v_role, case when auth.uid() is null then 'System' else 'Member' end),
     p_details, p_old, p_new, p_source,
     p_system or auth.uid() is null)
  returning id into v_id;

  return v_id;
end;
$$;


--
-- Name: pt_audit_is_append_only(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pt_audit_is_append_only() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  raise exception 'the promise audit log is append-only; % is not permitted', tg_op
    using errcode = 'insufficient_privilege';
end;
$$;


--
-- Name: pt_audit_status(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pt_audit_status() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if new.status is distinct from old.status then
    perform public.pt_audit('Status Changed', new.id,
      format('%s to %s', old.status, new.status), old.status, new.status);
  end if;
  if new.is_locked is distinct from old.is_locked then
    perform public.pt_audit(
      case when new.is_locked then 'Promise Locked' else 'Promise Unlocked' end,
      new.id, null, old.is_locked::text, new.is_locked::text);
  end if;
  if new.escalation_level is distinct from old.escalation_level then
    perform public.pt_audit('Escalated', new.id, new.escalation_reason,
      old.escalation_level::text, new.escalation_level::text);
  end if;
  return null;
end;
$$;


--
-- Name: pt_business_minutes(timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pt_business_minutes(p_from timestamp with time zone, p_to timestamp with time zone) RETURNS numeric
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  s          public.promise_settings%rowtype;
  v_cursor   timestamptz;
  v_total    numeric := 0;
  v_day_open timestamptz;
  v_day_shut timestamptz;
  v_from     timestamptz := least(p_from, p_to);
  v_to       timestamptz := greatest(p_from, p_to);
  v_guard    integer := 0;
begin
  select * into s from public.promise_settings limit 1;

  -- With working hours switched off, elapsed time is simply elapsed time.
  if s is null or not s.working_hours_only then
    return extract(epoch from (v_to - v_from)) / 60;
  end if;

  v_cursor := date_trunc('day', v_from);
  while v_cursor < v_to and v_guard < 3660 loop
    v_guard := v_guard + 1;
    -- isodow: Monday is 1. The default configuration is Monday to Friday.
    if extract(isodow from v_cursor)::int = any (s.working_days) then
      v_day_open := v_cursor + s.work_start_time::time;
      v_day_shut := v_cursor + s.work_end_time::time;
      v_total := v_total + greatest(
        extract(epoch from (least(v_to, v_day_shut) - greatest(v_from, v_day_open))) / 60, 0);
    end if;
    v_cursor := v_cursor + interval '1 day';
  end loop;

  return v_total;
end;
$$;


--
-- Name: pt_can_see_promise(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pt_can_see_promise(p_promise_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select exists (
    select 1 from public.promises p
    where p.id = p_promise_id
      and (
        public.pt_is_operator()
        or public.pt_is_manager()
        or p.owner_user_id = auth.uid()
        or p.receiver_user_id = auth.uid()
        or p.created_by = auth.uid()
      )
  );
$$;


--
-- Name: pt_decide_approval(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pt_decide_approval(p_promise_id uuid, p_decision text, p_note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  p public.promises%rowtype;
begin
  if p_decision not in ('approved', 'rejected') then
    return jsonb_build_object('ok', false, 'reason', 'unknown_decision');
  end if;

  -- Approving your own promise is not an approval.
  if not (public.pt_is_operator() or public.pt_is_manager()) then
    return jsonb_build_object('ok', false, 'reason', 'not_permitted');
  end if;

  select * into p from public.promises where id = p_promise_id;
  if not found then
    return jsonb_build_object('ok', false, 'reason', 'no_such_promise');
  end if;
  if p.status <> 'pending_approval' then
    return jsonb_build_object('ok', false, 'reason', 'not_awaiting_approval');
  end if;

  update public.promises
     set status = case when p_decision = 'approved' then 'active' else 'draft' end,
         approval_status = p_decision,
         approved_by = auth.uid(),
         approved_at = now()
   where id = p_promise_id;

  perform public.pt_audit(
    case when p_decision = 'approved' then 'Promise Approved' else 'Promise Rejected' end,
    p_promise_id, p_note, 'pending_approval',
    case when p_decision = 'approved' then 'active' else 'draft' end);

  perform public.pt_notify(p_promise_id, 'owner',
    format('%s - %s', case when p_decision = 'approved' then 'Approved' else 'Sent back' end, p.code),
    coalesce(p_note, p.title), 'promise_approval');

  return jsonb_build_object('ok', true, 'decision', p_decision);
end;
$$;


--
-- Name: pt_dismiss_insight(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pt_dismiss_insight(p_insight_id uuid, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  i public.promise_ai_insights%rowtype;
begin
  select * into i from public.promise_ai_insights where id = p_insight_id;
  if not found then
    return jsonb_build_object('ok', false, 'reason', 'no_such_insight');
  end if;
  if not (public.pt_is_operator() or public.pt_is_manager()) then
    return jsonb_build_object('ok', false, 'reason', 'not_permitted');
  end if;

  -- Dismissed, not deleted. Section 21 wants the dismissal on the record too,
  -- and the source removes the row so nobody can later ask who waved it away.
  update public.promise_ai_insights
     set state = 'dismissed', acted_by = auth.uid(), acted_at = now()
   where id = p_insight_id;

  perform public.pt_audit('AI Suggestion Dismissed', i.promise_id,
    coalesce(p_reason, i.suggested_action), 'open', 'dismissed');

  return jsonb_build_object('ok', true);
end;
$$;


--
-- Name: pt_enforce_lifecycle(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pt_enforce_lifecycle() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if new.status is not distinct from old.status then
    return new;
  end if;

  if not (new.status = any (public.pt_allowed_transitions(old.status))) then
    raise exception
      'invalid promise transition: % cannot become % (allowed: %)',
      old.status, new.status,
      array_to_string(public.pt_allowed_transitions(old.status), ', ')
      using errcode = 'check_violation';
  end if;

  if new.status = 'fulfilled' and new.fulfilled_at is null then
    new.fulfilled_at := now();
  end if;
  if new.status = 'locked' then
    new.is_locked := true;
    if new.locked_at is null then new.locked_at := now(); end if;
  end if;

  return new;
end;
$$;


--
-- Name: pt_escalate(uuid, integer, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pt_escalate(p_promise_id uuid, p_level integer, p_reason text DEFAULT NULL::text, p_raised_by text DEFAULT 'system'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  p         public.promises%rowtype;
  v_label   text;
  v_audience text;
begin
  select * into p from public.promises where id = p_promise_id;
  if not found then
    return jsonb_build_object('ok', false, 'reason', 'no_such_promise');
  end if;
  if p_level < 1 or p_level > 4 then
    return jsonb_build_object('ok', false, 'reason', 'level_out_of_range');
  end if;

  v_label := public.pt_escalation_label(p_level);
  v_audience := case p_level
    when 1 then 'owner' when 2 then 'manager'
    when 3 then 'admin' else 'legal' end;

  -- Section 14: the same level is never raised twice for one promise. The
  -- unique key does the deciding, so two concurrent sweeps cannot both raise it.
  insert into public.promise_escalations
    (promise_id, level, label, reason, raised_by, raised_by_user_id, notified_audience, status)
  values (p_promise_id, p_level, v_label, p_reason, p_raised_by, auth.uid(), v_audience, 'open')
  on conflict (promise_id, level) do nothing;

  if not found then
    return jsonb_build_object('ok', true, 'already_raised', true, 'level', p_level);
  end if;

  update public.promises
     set escalation_level = greatest(escalation_level, p_level),
         escalated_at = now(),
         escalation_reason = coalesce(p_reason, escalation_reason),
         escalation_status = 'pending'
   where id = p_promise_id;

  -- Section 13: the platform's own notification table, not a second one.
  perform public.pt_notify(
    p_promise_id, v_audience,
    format('%s - %s', v_label, p.code),
    coalesce(p_reason, format('%s reached escalation level %s', p.title, p_level)),
    'promise_escalation');

  perform public.pt_audit('Escalated', p_promise_id,
    format('%s: %s', v_label, coalesce(p_reason, 'no reason recorded')),
    (p.escalation_level)::text, p_level::text, 'promise_tracker', p_raised_by = 'system');

  return jsonb_build_object('ok', true, 'level', p_level, 'label', v_label,
                            'audience', v_audience);
end;
$$;


--
-- Name: pt_escalation_label(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pt_escalation_label(p_level integer) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  select case p_level
    when 1 then 'Reminder'
    when 2 then 'Manager Alert'
    when 3 then 'Admin Alert'
    when 4 then 'Legal / Penalty'
    else 'Unknown' end;
$$;


--
-- Name: pt_guard_locked(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pt_guard_locked() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if old.is_locked and not public.pt_is_operator() and auth.uid() is not null then
    raise exception 'promise % is locked; an operator must unlock it first', old.code
      using errcode = 'insufficient_privilege';
  end if;
  return new;
end;
$$;


--
-- Name: pt_is_manager(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pt_is_manager() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  -- Managers may review and escalate their teams' commitments without holding
  -- full Control Panel rights.
  select exists (
    select 1 from public.user_roles ur
    where ur.user_id = auth.uid()
      and ur.role in ('admin','boss','founder','super_admin','boss_owner',
                      'employee','sales','support','finance','sales_support_manager')
  );
$$;


--
-- Name: pt_is_operator(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pt_is_operator() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  -- The same operator roles the Control Panel already uses everywhere else.
  select exists (
    select 1 from public.user_roles ur
    where ur.user_id = auth.uid()
      and ur.role in ('admin','boss','founder','super_admin','boss_owner')
  );
$$;


--
-- Name: pt_link(uuid, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pt_link(p_promise_id uuid, p_module text, p_record_id text, p_relation text DEFAULT 'linked'::text, p_label text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_id uuid;
begin
  if not public.pt_can_see_promise(p_promise_id) then
    return jsonb_build_object('ok', false, 'reason', 'not_permitted');
  end if;

  insert into public.promise_links (promise_id, module, record_id, relation, label, created_by)
  values (p_promise_id, p_module, p_record_id, p_relation, p_label, auth.uid())
  on conflict (promise_id, module, record_id) do update
     set relation = excluded.relation, label = coalesce(excluded.label, promise_links.label)
  returning id into v_id;

  -- The first link is also recorded on the promise itself, which is what
  -- section 32 asks for and what the list screens filter on.
  update public.promises
     set linked_module = coalesce(linked_module, p_module),
         linked_record_id = coalesce(linked_record_id, p_record_id)
   where id = p_promise_id;

  perform public.pt_audit('Promise Linked', p_promise_id,
    format('%s %s (%s)', p_module, p_record_id, p_relation));

  return jsonb_build_object('ok', true, 'link_id', v_id);
end;
$$;


--
-- Name: pt_next_code(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pt_next_code() RETURNS text
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
  -- PRM-001 upwards, continuing from whatever already exists.
  select 'PRM-' || lpad((
    coalesce(max(nullif(regexp_replace(code, '^PRM-', ''), '')::int), 0) + 1
  )::text, 3, '0')
  from public.promises
  where code ~ '^PRM-[0-9]+$';
$_$;


--
-- Name: pt_notify(uuid, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pt_notify(p_promise_id uuid, p_audience text, p_title text, p_body text, p_kind text DEFAULT 'promise'::text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  p       public.promises%rowtype;
  v_count integer := 0;
begin
  select * into p from public.promises where id = p_promise_id;
  if not found then return 0; end if;

  with targets as (
    select distinct u.id as user_id
    from auth.users u
    where
      case p_audience
        when 'owner'    then u.id = p.owner_user_id
        when 'receiver' then u.id = p.receiver_user_id
        when 'both'     then u.id in (p.owner_user_id, p.receiver_user_id)
        when 'manager'  then exists (
          select 1 from public.user_roles ur where ur.user_id = u.id
           and ur.role in ('admin','boss','founder','super_admin','boss_owner',
                           'employee','sales','support','finance','sales_support_manager'))
        when 'admin'    then exists (
          select 1 from public.user_roles ur where ur.user_id = u.id
           and ur.role in ('admin','boss','founder','super_admin','boss_owner'))
        when 'legal'    then exists (
          select 1 from public.user_roles ur where ur.user_id = u.id
           and ur.role in ('admin','boss','founder','super_admin','boss_owner'))
        else false
      end
  )
  insert into public.notifications (user_id, title, body, kind, data)
  select t.user_id, p_title, p_body, p_kind,
         jsonb_build_object('promise_id', p.id, 'promise_code', p.code,
                            'module', 'promise_tracker', 'audience', p_audience)
  from targets t;

  get diagnostics v_count = row_count;
  return v_count;
end;
$$;


--
-- Name: pt_owner_scorecard(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pt_owner_scorecard(p_user_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  -- Every figure is counted from real rows. Where somebody has made no
  -- promises the answer is zero, not a placeholder.
  select jsonb_build_object(
    'user_id', p_user_id,
    'total', count(*),
    'fulfilled', count(*) filter (where status in ('fulfilled','locked')),
    'on_time', count(*) filter (where status in ('fulfilled','locked')
                                  and fulfilled_at is not null
                                  and fulfilled_at <= deadline),
    'late', count(*) filter (where status in ('fulfilled','locked')
                               and fulfilled_at is not null
                               and fulfilled_at > deadline),
    'delayed', count(*) filter (where status = 'delayed'),
    'broken', count(*) filter (where status = 'broken'),
    'open', count(*) filter (where status in ('pending','active','due_soon','pending_approval')),
    'escalations', coalesce(sum(escalation_level), 0),
    'fines_total', coalesce(sum(fine_amount), 0),
    'tips_total', coalesce(sum(tip_amount), 0),
    'sla_rate', case when count(*) filter (where status in ('fulfilled','locked','broken')) = 0
                     then null
                     else round(
                       100.0 * count(*) filter (where status in ('fulfilled','locked')
                                                  and fulfilled_at is not null
                                                  and fulfilled_at <= deadline)
                       / count(*) filter (where status in ('fulfilled','locked','broken')), 1)
                end
  )
  from public.promises
  where owner_user_id = p_user_id;
$$;


--
-- Name: pt_promises_for(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pt_promises_for(p_module text, p_record_id text) RETURNS TABLE(promise_id uuid, code text, title text, status text, priority text, deadline timestamp with time zone, escalation_level integer, owner text, receiver text, fine_amount numeric, tip_amount numeric, relation text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select p.id, p.code, p.title, p.status, p.priority, p.deadline,
         p.escalation_level, p.owner, p.receiver, p.fine_amount, p.tip_amount,
         coalesce(l.relation, 'linked')
  from public.promises p
  left join public.promise_links l
    on l.promise_id = p.id and l.module = p_module and l.record_id = p_record_id
  where (l.id is not null
         or (p.linked_module = p_module and p.linked_record_id = p_record_id))
    and public.pt_can_see_promise(p.id)
  order by p.deadline;
$$;


--
-- Name: pt_prune_health_events(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pt_prune_health_events() RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  delete from public.promise_health_events
   where created_at < now() - make_interval(
     days => coalesce((select health_retention_days from public.promise_settings limit 1), 14));
$$;


--
-- Name: pt_release_tip(uuid, uuid, text, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pt_release_tip(p_promise_id uuid, p_rule_id uuid, p_note text DEFAULT NULL::text, p_basis numeric DEFAULT NULL::numeric, p_actor text DEFAULT 'system'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  p        public.promises%rowtype;
  r        public.promise_rules%rowtype;
  s        public.promise_settings%rowtype;
  v_amount numeric;
  v_id     uuid;
begin
  -- Money is an operator decision. These run as SECURITY DEFINER and were
  -- granted to authenticated, so without this any signed-in person could fine
  -- somebody else or release a tip to themselves.
  if auth.uid() is not null and not public.pt_is_operator() then
    return jsonb_build_object('ok', false, 'reason', 'not_permitted');
  end if;

  select * into s from public.promise_settings limit 1;
  if s is not null and not s.tip_system_enabled then
    return jsonb_build_object('ok', false, 'reason', 'tip_system_disabled');
  end if;

  select * into p from public.promises where id = p_promise_id;
  if not found then return jsonb_build_object('ok', false, 'reason', 'no_such_promise'); end if;

  select * into r from public.promise_rules where id = p_rule_id and is_active;
  if not found then return jsonb_build_object('ok', false, 'reason', 'no_such_rule'); end if;
  if r.kind <> 'tip' then return jsonb_build_object('ok', false, 'reason', 'not_a_tip_rule'); end if;

  if exists (select 1 from public.promise_ledger
             where promise_id = p_promise_id and rule_id = p_rule_id
               and kind = 'tip' and status <> 'reversed') then
    return jsonb_build_object('ok', false, 'reason', 'already_released');
  end if;

  v_amount := public.pt_rule_amount(r, p_basis, p.delay_days);
  if v_amount <= 0 then
    return jsonb_build_object('ok', false, 'reason', 'nothing_to_release');
  end if;

  insert into public.promise_ledger
    (promise_id, rule_id, kind, amount, currency, basis, status, actor, actor_user_id, note)
  values (p_promise_id, p_rule_id, 'tip', v_amount, p.currency,
          r.rule_type || case when p_basis is not null then ' of ' || p_basis::text else '' end,
          'released', p_actor, auth.uid(), coalesce(p_note, r.name))
  returning id into v_id;

  update public.promises
     set tip_amount = (select coalesce(sum(amount), 0) from public.promise_ledger
                       where promise_id = p_promise_id and kind = 'tip' and status = 'released'),
         tip_status = 'released'
   where id = p_promise_id;

  perform public.pt_audit('Tip Released', p_promise_id,
    format('%s: %s %s', r.name, p.currency, v_amount), null, v_amount::text,
    'promise_tracker', p_actor = 'system');

  return jsonb_build_object('ok', true, 'ledger_id', v_id, 'amount', v_amount,
                            'rule', r.name);
end;
$$;


--
-- Name: pt_resolve_identity(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pt_resolve_identity(p_needle text) RETURNS uuid
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_needle text := lower(trim(coalesce(p_needle, '')));
  v_id     uuid;
begin
  if v_needle = '' then
    return null;
  end if;

  -- An email address is unambiguous, so it is tried first.
  select u.id into v_id from auth.users u where lower(u.email) = v_needle limit 1;
  if v_id is not null then return v_id; end if;

  select p.id into v_id from public.profiles p where lower(p.email) = v_needle limit 1;
  if v_id is not null then return v_id; end if;

  -- Then a full name, but only when it identifies exactly one person. Two
  -- people sharing a name is precisely when guessing would do harm.
  select p.id into v_id
  from public.profiles p
  where lower(p.full_name) = v_needle
  group by p.id
  having count(*) = 1
  limit 1;
  if v_id is not null and (
       select count(*) from public.profiles q where lower(q.full_name) = v_needle) = 1 then
    return v_id;
  end if;

  select p.id into v_id
  from public.profiles p
  where lower(p.username) = v_needle
  limit 1;
  if v_id is not null and (
       select count(*) from public.profiles q where lower(q.username) = v_needle) = 1 then
    return v_id;
  end if;

  return null;
end;
$$;


--
-- Name: promise_rules; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.promise_rules (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    code text NOT NULL,
    kind text NOT NULL,
    name text NOT NULL,
    rule_type text DEFAULT 'fixed'::text NOT NULL,
    amount numeric(12,2) DEFAULT 0 NOT NULL,
    auto_apply boolean DEFAULT false NOT NULL,
    is_active boolean DEFAULT true NOT NULL,
    conditions jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT promise_rules_kind_check CHECK ((kind = ANY (ARRAY['fine'::text, 'tip'::text]))),
    CONSTRAINT promise_rules_type_check CHECK ((rule_type = ANY (ARRAY['fixed'::text, 'percentage'::text, 'manual'::text])))
);


--
-- Name: pt_rule_amount(public.promise_rules, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pt_rule_amount(p_rule public.promise_rules, p_basis numeric) RETURNS numeric
    LANGUAGE sql IMMUTABLE
    AS $$
  -- A percentage rule with nothing to take a percentage of yields nothing,
  -- rather than quietly falling back to the fixed amount.
  select case p_rule.rule_type
    when 'percentage' then round(coalesce(p_basis, 0) * p_rule.amount / 100.0, 2)
    else round(p_rule.amount, 2)
  end;
$$;


--
-- Name: pt_rule_amount(public.promise_rules, numeric, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pt_rule_amount(p_rule public.promise_rules, p_basis numeric, p_delay_days integer DEFAULT 0) RETURNS numeric
    LANGUAGE sql IMMUTABLE
    AS $$
  -- A percentage rule with nothing to take a percentage of yields nothing,
  -- rather than quietly falling back to the fixed amount.
  select case p_rule.rule_type
    when 'percentage' then round(coalesce(p_basis, 0) * p_rule.amount / 100.0, 2)
    when 'per_day'    then round(greatest(coalesce(p_delay_days, 0), 1) * p_rule.amount, 2)
    else round(p_rule.amount, 2)
  end;
$$;


--
-- Name: pt_sweep(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pt_sweep() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  s            public.promise_settings%rowtype;
  r            record;
  v_seen       integer := 0;
  v_due_soon   integer := 0;
  v_delayed    integer := 0;
  v_broken     integer := 0;
  v_reminded   integer := 0;
  v_escalated  integer := 0;
  v_fined      integer := 0;
  v_overdue_m  numeric;
  v_level      integer;
  v_target     integer;
  v_rule       public.promise_rules%rowtype;
  v_status     text;   -- r.status is the snapshot taken at the top of the
                       -- loop; this follows what the row actually becomes.
  v_result     jsonb;
begin
  select * into s from public.promise_settings limit 1;
  if s is null then
    return jsonb_build_object('ok', false, 'reason', 'no_settings_row');
  end if;

  for r in
    select * from public.promises
    where status in ('pending','active','due_soon','delayed','broken')
    order by deadline
  loop
    v_seen := v_seen + 1;
    v_status := r.status;
    v_level := coalesce(r.escalation_level, 0);

    -- ---------------------------------------------------------- reminder --
    -- Sent once, in the window before the deadline, and only while there is
    -- still a deadline to meet.
    if s.auto_reminder
       and r.reminded_at is null
       and now() >= r.deadline - make_interval(hours => s.reminder_before_hours)
       and now() < r.deadline then
      update public.promises set reminded_at = now() where id = r.id;
      perform public.pt_notify(r.id, 'owner',
        format('Reminder - %s', r.code),
        format('%s is due %s', r.title, to_char(r.deadline, 'DD Mon YYYY HH24:MI')),
        'promise_reminder');
      perform public.pt_audit('Promise Reminder', r.id,
        format('reminder sent %s hours before the deadline', s.reminder_before_hours),
        null, null, 'promise_tracker', true);
      v_reminded := v_reminded + 1;
    end if;

    -- ------------------------------------------------------- the deadline --
    if now() < r.deadline then
      -- Still in time. Mark it due soon so the board shows what is closing in.
      if r.status in ('pending','active')
         and now() >= r.deadline - make_interval(hours => s.reminder_before_hours) then
        update public.promises
           set status = 'due_soon',
               due_soon_at = coalesce(due_soon_at, now())
         where id = r.id;
        v_status := 'due_soon';
        v_due_soon := v_due_soon + 1;
      end if;
      continue;
    end if;

    -- Past the deadline. How far past, counted the way the business counts it.
    v_overdue_m := public.pt_business_minutes(r.deadline, now());

    if v_status in ('pending','active','due_soon') then
      update public.promises
         set status = 'delayed',
             delay_days = greatest(0, floor(extract(epoch from (now() - r.deadline)) / 86400))::int
       where id = r.id;
      v_status := 'delayed';
      v_delayed := v_delayed + 1;
      perform public.pt_notify(r.id, 'both',
        format('Delayed - %s', r.code),
        format('%s passed its deadline', r.title), 'promise_delayed');
    else
      update public.promises
         set delay_days = greatest(0, floor(extract(epoch from (now() - r.deadline)) / 86400))::int
       where id = r.id;
    end if;

    -- ------------------------------------------------------- escalation ---
    -- Each level is earned by another escalation_delay_hours of working time
    -- spent overdue. Level 1 lands as soon as the deadline passes.
    if s.auto_escalation then
      v_target := least(4, 1 + floor(v_overdue_m / greatest(s.escalation_delay_hours, 1) / 60)::int);
      while v_level < v_target loop
        v_level := v_level + 1;
        v_result := public.pt_escalate(
          r.id, v_level,
          format('%s overdue by %s working hours',
                 r.code, round(v_overdue_m / 60, 1)),
          'system');
        if coalesce((v_result ->> 'ok')::boolean, false)
           and not coalesce((v_result ->> 'already_raised')::boolean, false) then
          v_escalated := v_escalated + 1;
        end if;
      end loop;
    end if;

    -- ------------------------------------------------------------ broken --
    -- A promise is broken once it has run the whole ladder, or once it is past
    -- the configured expiry. Delayed means late; broken means it will not land.
    if v_status = 'delayed'
       and (v_level >= 4
            or now() > r.deadline + make_interval(days => s.promise_expiry_days)) then
      update public.promises
         set status = 'broken',
             breach_reason = coalesce(r.breach_reason,
               case when v_level >= 4 then 'escalation ladder exhausted'
                    else 'past the configured expiry' end)
       where id = r.id;
      v_status := 'broken';
      v_broken := v_broken + 1;
      perform public.pt_notify(r.id, 'admin',
        format('Broken - %s', r.code),
        format('%s was not delivered', r.title), 'promise_broken');
    end if;

    -- -------------------------------------------------------------- fine --
    -- Money last, and only from rules the operator marked auto-apply. A
    -- percentage fine needs something to take a percentage of; where there is
    -- no amount on the promise, pt_apply_fine declines rather than invent one.
    if s.fine_system_enabled then
      for v_rule in
        select * from public.promise_rules
        where kind = 'fine' and is_active and auto_apply
      loop
        if (v_rule.code = 'FR-001' and v_status in ('delayed','broken'))
           or (v_rule.code = 'FR-002' and v_status = 'broken')
           or (v_rule.code = 'FR-004' and r.priority = 'critical' and v_level >= 3) then
          v_result := public.pt_apply_fine(r.id, v_rule.id,
            format('auto-applied by the deadline sweep'), null, 'system');
          if coalesce((v_result ->> 'ok')::boolean, false) then
            v_fined := v_fined + 1;
          end if;
        end if;
      end loop;
    end if;
  end loop;

  -- Housekeeping the source also does, kept here so one schedule covers it.
  delete from public.promise_health_events
   where created_at < now() - make_interval(days => coalesce(s.health_retention_days, 14));

  return jsonb_build_object(
    'ok', true, 'swept_at', now(), 'examined', v_seen,
    'due_soon', v_due_soon, 'delayed', v_delayed, 'broken', v_broken,
    'reminders_sent', v_reminded, 'escalations_raised', v_escalated,
    'fines_applied', v_fined);
end;
$$;


--
-- Name: pt_task_completed(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pt_task_completed(p_task_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  r        record;
  v_closed integer := 0;
begin
  for r in
    select p.id, p.code, p.status
    from public.promises p
    join public.promise_links l on l.promise_id = p.id
    where l.module = 'task_manager'
      and l.record_id = p_task_id::text
      and l.relation = 'delivered_by'
      and p.status in ('pending','active','due_soon','delayed')
  loop
    update public.promises set status = 'fulfilled' where id = r.id;
    perform public.pt_audit('Promise Fulfilled', r.id,
      format('the delivering task %s was completed', p_task_id),
      r.status, 'fulfilled', 'task_manager', true);
    perform public.pt_notify(r.id, 'both',
      format('Fulfilled - %s', r.code),
      'The work this promise was made against has been completed.',
      'promise_fulfilled');
    v_closed := v_closed + 1;
  end loop;

  return jsonb_build_object('ok', true, 'promises_fulfilled', v_closed);
end;
$$;


--
-- Name: pt_touch_updated_at(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pt_touch_updated_at() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin new.updated_at = now(); return new; end; $$;


--
-- Name: reconcile_payment_intents(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reconcile_payment_intents() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_expired integer;
BEGIN
  UPDATE public.payment_intents SET status = 'expired', updated_at = now()
  WHERE status IN ('initiated','pending','partial') AND expires_at <= now();
  GET DIAGNOSTICS v_expired = ROW_COUNT;
  IF v_expired > 0 THEN
    INSERT INTO public.payment_audit_logs (action, status, metadata) VALUES ('reconcile_expired', 'expired', jsonb_build_object('count', v_expired));
  END IF;
  RETURN jsonb_build_object('expired', v_expired, 'checked_at', now());
END; $$;


--
-- Name: reseller_commissions_for_order(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reseller_commissions_for_order(p_order uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_att record; v_item record; v_rate jsonb; v_amount numeric;
  v_created integer := 0; v_skipped integer := 0; v_reseller_user uuid;
  v_buyer uuid; v_notes text[] := '{}';
begin
  select a.*, r.user_id as reseller_user
    into v_att
    from public.marketplace_order_attributions a
    join public.resellers r on r.id = a.reseller_id
   where a.order_id = p_order and a.reseller_id is not null
   limit 1;

  if not found then
    return jsonb_build_object('ok', true, 'created', 0,
      'reason', 'no reseller attribution on this order');
  end if;

  select buyer_id into v_buyer from public.marketplace_orders where id = p_order;
  v_reseller_user := v_att.reseller_user;

  -- Self-referral. Recorded and refused rather than quietly paid: a reseller
  -- buying through their own link is the commonest abuse in section 23.
  if v_reseller_user is not null and v_reseller_user = v_buyer then
    perform public.mm_audit('reseller.self_referral_blocked', 'marketplace_order',
      p_order::text, null,
      jsonb_build_object('reseller_id', v_att.reseller_id, 'buyer_id', v_buyer),
      'The buyer owns the referring reseller account.');
    return jsonb_build_object('ok', false, 'created', 0, 'reason', 'self_referral');
  end if;

  -- A reseller who is not active does not earn.
  if not exists (select 1 from public.resellers
                  where id = v_att.reseller_id and status = 'active') then
    return jsonb_build_object('ok', false, 'created', 0, 'reason', 'reseller_not_active');
  end if;

  for v_item in
    select i.id, i.product_id, i.line_total, i.currency, p.category_id
      from public.marketplace_order_items i
      left join public.marketplace_products p on p.id = i.product_id
     where i.order_id = p_order
  loop
    if exists (select 1 from public.reseller_commissions
                where order_item_id = v_item.id) then
      v_skipped := v_skipped + 1;
      continue;
    end if;

    v_rate := public.reseller_rate_for(v_att.reseller_id, v_item.product_id, v_item.category_id);
    if (v_rate->>'rate_percent') is null then
      v_skipped := v_skipped + 1;
      v_notes := v_notes || (v_rate->>'reason');
      continue;
    end if;

    v_amount := round(
      coalesce(v_item.line_total,0) * (v_rate->>'rate_percent')::numeric / 100
      + coalesce((v_rate->>'fixed_amount')::numeric, 0), 2);

    insert into public.reseller_commissions
      (reseller_id, order_id, order_item_id, attribution_id,
       gross_amount, commission_amount, currency, status, rule_snapshot,
       idempotency_key)
    values (v_att.reseller_id, p_order, v_item.id, v_att.id,
            coalesce(v_item.line_total,0), v_amount,
            coalesce(v_item.currency,'USD'), 'pending', v_rate,
            'reseller_commission:' || v_item.id::text || ':' || v_att.reseller_id::text)
    on conflict do nothing;

    if found then v_created := v_created + 1; else v_skipped := v_skipped + 1; end if;
  end loop;

  if v_created > 0 then
    perform public.mm_audit('reseller.commission_recorded', 'reseller',
      v_att.reseller_id::text, null,
      jsonb_build_object('order_id', p_order, 'lines', v_created), null);

    if v_reseller_user is not null then
      perform public.mm_notify('reseller.commission',
        'You earned commission on a sale',
        format('%s line(s) from a new order have been credited to you, and enter the holding period now.', v_created),
        v_reseller_user, null, '/reseller-manager', 'View', 5, 'success');
    end if;
  end if;

  return jsonb_build_object('ok', true, 'created', v_created, 'skipped', v_skipped,
    'reseller_id', v_att.reseller_id,
    'notes', to_jsonb(v_notes));
end;
$$;


--
-- Name: reseller_commissions_reverse(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reseller_commissions_reverse(p_order uuid, p_reason text DEFAULT 'refund'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_n integer; v_paid integer;
begin
  select count(*) into v_paid from public.reseller_commissions
   where order_id = p_order and status = 'paid';

  update public.reseller_commissions
     set status = 'reversed', updated_at = now()
   where order_id = p_order and status in ('pending','available');
  get diagnostics v_n = row_count;

  if v_n > 0 or v_paid > 0 then
    perform public.mm_audit('reseller.commission_reversed', 'marketplace_order',
      p_order::text, null,
      jsonb_build_object('reversed', v_n, 'already_paid', v_paid), p_reason);
  end if;

  -- Commission already paid out cannot be clawed back automatically. It is
  -- reported so a person can decide, rather than silently adjusting a ledger.
  return jsonb_build_object('ok', true, 'reversed', v_n, 'already_paid', v_paid,
    'note', case when v_paid > 0
      then 'Some of this commission has already been paid out and needs a manual adjustment.'
      else null end);
end;
$$;


--
-- Name: reseller_discount_amount(numeric, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reseller_discount_amount(p_amount numeric, p_percent numeric) RETURNS numeric
    LANGUAGE sql IMMUTABLE
    AS $$ select round(coalesce(p_amount, 0) * greatest(coalesce(p_percent, 0), 0) / 100, 2) $$;


--
-- Name: reseller_is_finance(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reseller_is_finance() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select public.has_role(auth.uid(),'admin') or public.has_role(auth.uid(),'boss')
      or public.has_role(auth.uid(),'super_admin') or public.has_role(auth.uid(),'finance');
$$;


--
-- Name: reseller_membership_event_notify(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reseller_membership_event_notify() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_user uuid;
  v_reseller text;
  v_order public.reseller_membership_orders%rowtype;
  v_plan text;
  v_invoice text;
  v_amount text;
begin
  select user_id, name into v_user, v_reseller from public.resellers where id = new.reseller_id;
  if new.order_id is not null then
    select * into v_order from public.reseller_membership_orders where id = new.order_id;
    select name into v_plan from public.reseller_membership_plans where id = v_order.plan_id;
    select invoice_no into v_invoice from public.finance_invoices where id = v_order.finance_invoice_id;
    v_amount := 'USD ' || to_char(v_order.amount_usd, 'FM999999990.00');
  end if;

  begin
    if new.event_type = 'order.created' and v_user is not null then
      perform public.mm_notify('reseller.membership.order_created',
        'Membership order created',
        format('%s plan, %s. Invoice %s is ready for payment (order %s).',
               coalesce(v_plan, 'Membership'), v_amount, coalesce(v_invoice, '-'), v_order.order_number),
        v_user, null, '/dashboard/reseller', 'Open Membership & Plans', 0, 'info');

    elsif new.event_type = 'payment.pending' then
      if v_user is not null then
        perform public.mm_notify('reseller.membership.payment_submitted',
          'Payment submitted',
          format('Your payment for order %s is with Finance for verification.', v_order.order_number),
          v_user, null, '/dashboard/reseller', 'Open Membership & Plans', 0, 'info');
      end if;
      perform public.mm_notify('finance.reseller_membership.payment_to_verify',
        'Membership payment to verify',
        format('%s submitted a payment for order %s (%s plan, %s).',
               coalesce(v_reseller, 'A reseller'), v_order.order_number, coalesce(v_plan, '-'), v_amount),
        null, array['finance', 'admin', 'boss'], '/finance-manager?view=memberships', 'Verify', 0, 'warning');

    elsif new.event_type = 'membership.activated' and v_user is not null then
      perform public.mm_notify('reseller.membership.activated',
        'Membership activated',
        format('Your %s membership is active.', coalesce(v_plan, '')),
        v_user, null, '/dashboard/reseller', 'Open Membership & Plans', 0, 'success');

    elsif new.event_type in ('payment.failed', 'payment.cancelled', 'payment.expired', 'payment.refunded')
          and v_user is not null then
      perform public.mm_notify('reseller.membership.' || replace(new.event_type, '.', '_'),
        case new.event_type
          when 'payment.failed' then 'Membership payment failed'
          when 'payment.refunded' then 'Membership payment refunded'
          when 'payment.expired' then 'Membership order expired'
          else 'Membership order cancelled' end,
        format('Order %s is now %s.', v_order.order_number, v_order.status),
        v_user, null, '/dashboard/reseller', 'Open Membership & Plans', 0,
        case when new.event_type = 'payment.failed' then 'danger' else 'warning' end);
    end if;
  exception when others then
    -- A notification must never undo the membership step it reports.
    perform public.mm_audit('notification.failed', 'reseller_membership_event', new.id::text, null,
                            jsonb_build_object('event', new.event_type, 'error', sqlerrm), null);
  end;
  return new;
end;
$$;


--
-- Name: reseller_on_order_paid(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reseller_on_order_paid() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if new.status = 'paid' and coalesce(old.status,'') <> 'paid' then
    begin
      perform public.reseller_commissions_for_order(new.id);
    exception when others then
      -- Never block a payment being recorded. The failure is logged so it can
      -- be settled by hand rather than disappearing.
      perform public.mm_audit('reseller.commission_failed', 'marketplace_order',
        new.id::text, null, jsonb_build_object('error', sqlerrm), null);
    end;
  end if;
  return new;
end;
$$;


--
-- Name: reseller_owned_by_user(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reseller_owned_by_user(_user_id uuid, _reseller_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select exists (select 1 from public.resellers r where r.id = _reseller_id and r.user_id = _user_id);
$$;


--
-- Name: reseller_pricing_for(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reseller_pricing_for(p_user uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_reseller public.resellers%rowtype;
  v_membership record;
begin
  if p_user is null then
    return jsonb_build_object('eligible', false, 'percent', 0, 'reason', 'not_signed_in');
  end if;
  select * into v_reseller from public.resellers
   where user_id = p_user and status <> 'terminated'
   order by created_at desc limit 1;
  if not found then
    return jsonb_build_object('eligible', false, 'percent', 0, 'reason', 'not_a_reseller');
  end if;
  if v_reseller.status <> 'active' or v_reseller.approved_at is null then
    return jsonb_build_object('eligible', false, 'percent', 0, 'reseller_id', v_reseller.id,
                              'reason', 'reseller_not_active');
  end if;
  select m.id, m.expires_at, p.code, p.name, p.profit_percent
    into v_membership
    from public.reseller_memberships m
    join public.reseller_membership_plans p on p.id = m.plan_id
   where m.reseller_id = v_reseller.id
     and m.status = 'active'
     and (m.expires_at is null or m.expires_at > now())
   order by p.profit_percent desc, m.activated_at desc nulls last
   limit 1;
  if not found or coalesce(v_membership.profit_percent, 0) <= 0 then
    return jsonb_build_object('eligible', false, 'percent', 0, 'reseller_id', v_reseller.id,
                              'reason', 'no_active_membership');
  end if;
  return jsonb_build_object('eligible', true, 'percent', v_membership.profit_percent,
    'reseller_id', v_reseller.id, 'membership_id', v_membership.id,
    'plan_code', v_membership.code, 'plan_name', v_membership.name,
    'expires_at', v_membership.expires_at, 'reason', 'active_membership');
end;
$$;


--
-- Name: reseller_rate_for(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reseller_rate_for(p_reseller uuid, p_product uuid, p_category uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_rule record; v_plan record; v_volume numeric;
begin
  select coalesce(sum(commission_amount),0) into v_volume
    from public.reseller_commissions
   where reseller_id = p_reseller and status <> 'reversed';

  select * into v_rule
    from public.reseller_commission_rules r
   where r.active
     and (r.reseller_id is null or r.reseller_id = p_reseller)
     and (r.product_id is null or r.product_id = p_product)
     and (r.category_id is null or r.category_id = p_category)
     and v_volume >= r.min_volume
   order by
     (case when r.product_id = p_product then 4
           when r.category_id = p_category then 3
           when r.reseller_id = p_reseller then 2
           else 1 end) desc,
     r.priority desc
   limit 1;

  if found then
    return jsonb_build_object(
      'source', 'rule', 'rule_id', v_rule.id,
      'rate_percent', v_rule.rate_percent, 'fixed_amount', v_rule.fixed_amount,
      'currency', v_rule.currency, 'min_volume', v_rule.min_volume,
      'scope', case when v_rule.product_id is not null then 'product'
                    when v_rule.category_id is not null then 'category'
                    when v_rule.reseller_id is not null then 'reseller'
                    else 'house' end);
  end if;

  select p.* into v_plan
    from public.resellers r
    join public.reseller_membership_plans p on p.code = r.plan_code
   where r.id = p_reseller and p.enabled;

  if found then
    return jsonb_build_object(
      'source', 'plan', 'plan_code', v_plan.code, 'plan_name', v_plan.name,
      'rate_percent', v_plan.profit_percent, 'fixed_amount', 0, 'currency', 'USD');
  end if;

  -- No rule and no plan means no basis for paying anything. Saying so is the
  -- honest answer; inventing a default rate would not be.
  return jsonb_build_object('source', 'none', 'rate_percent', null,
    'reason', 'This reseller has no commission rule and no plan, so no margin can be resolved.');
end;
$$;


--
-- Name: reseller_terminated_is_final(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reseller_terminated_is_final() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  if old.status = 'terminated' then
    if new.status is distinct from old.status then
      raise exception 'Reseller % is terminated. Termination is final: the person must submit a new application.', old.code
        using errcode = 'P0001';
    end if;
    if new.code is distinct from old.code
       or new.application is distinct from old.application
       or new.applied_at is distinct from old.applied_at
       or new.approved_at is distinct from old.approved_at
       or new.approved_by is distinct from old.approved_by
       or new.plan_code is distinct from old.plan_code
       or new.tier is distinct from old.tier
       or (new.user_id is distinct from old.user_id and new.user_id is not null) then
      raise exception 'Reseller % is terminated; its record is kept as history and cannot be changed.', old.code
        using errcode = 'P0001';
    end if;
  end if;
  return new;
end;
$$;


--
-- Name: review_developer_submission(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.review_developer_submission(_submission_id uuid, _decision text, _notes text) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$ DECLARE s public.developer_code_submissions%ROWTYPE; t public.developer_tasks%ROWTYPE; next_status text; BEGIN IF NOT (public.has_role(auth.uid(), 'admin') OR public.has_role(auth.uid(), 'boss')) THEN RAISE EXCEPTION 'Reviewer access required'; END IF; IF _decision NOT IN ('approved', 'changes_requested') OR NULLIF(btrim(_notes), '') IS NULL THEN RAISE EXCEPTION 'Invalid review decision'; END IF; SELECT * INTO s FROM public.developer_code_submissions WHERE id = _submission_id AND review_status = 'submitted' FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Submission is not awaiting review'; END IF; next_status := CASE WHEN _decision = 'approved' THEN 'completed' ELSE 'reopened' END; UPDATE public.developer_code_submissions SET review_status = _decision, review_notes = btrim(_notes), reviewed_by = auth.uid(), reviewed_at = now() WHERE id = _submission_id RETURNING * INTO s; UPDATE public.developer_tasks SET status = next_status, completed_at = CASE WHEN _decision = 'approved' THEN now() ELSE NULL END, updated_at = now() WHERE id = s.task_id AND status = 'submitted' RETURNING * INTO t; IF NOT FOUND THEN RAISE EXCEPTION 'Task is not awaiting review'; END IF; INSERT INTO public.developer_activity_logs (developer_id, activity_type, description, metadata) VALUES (s.developer_id, CASE WHEN _decision = 'approved' THEN 'task_approved' ELSE 'task_changes_requested' END, btrim(_notes), jsonb_build_object('task_id', s.task_id, 'submission_id', _submission_id, 'reviewer_id', auth.uid())); RETURN jsonb_build_object('submission', to_jsonb(s), 'task', to_jsonb(t)); END; $$;


--
-- Name: review_franchise_application(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.review_franchise_application(p_id uuid, p_status text, p_notes text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_before public.franchise_applications%rowtype;
  v_after public.franchise_applications%rowtype;
begin
  if not public.is_franchise_staff() then raise exception 'Franchise staff access required'; end if;
  if p_status not in ('in_review', 'approved', 'rejected') then raise exception 'Invalid application status'; end if;
  if p_status = 'rejected' and nullif(btrim(coalesce(p_notes, '')), '') is null then
    raise exception 'Record why the application is rejected';
  end if;
  select * into v_before from public.franchise_applications where id = p_id for update;
  if not found then raise exception 'Application not found'; end if;
  if v_before.applicant_user_id = auth.uid() then raise exception 'You cannot review your own application'; end if;
  if v_before.status in ('approved', 'rejected') then
    raise exception 'This application is already %', v_before.status;
  end if;

  update public.franchise_applications
     set status = p_status, review_notes = coalesce(nullif(btrim(p_notes), ''), review_notes), updated_at = now()
   where id = p_id returning * into v_after;

  perform public.mm_audit('franchise.application_' || p_status, 'franchise_application', p_id::text,
                          to_jsonb(v_before), to_jsonb(v_after), p_notes);
  if v_after.applicant_user_id is not null then
    perform public.mm_notify('franchise.application_' || p_status,
      case p_status when 'approved' then 'Franchise application approved'
                    when 'rejected' then 'Franchise application not approved'
                    else 'Franchise application in review' end,
      format('Application %s is now %s.%s', v_after.code, replace(p_status, '_', ' '),
             case when p_status = 'rejected' then ' Reason: ' || p_notes else '' end),
      v_after.applicant_user_id, null, null, null, 0,
      case p_status when 'approved' then 'success' when 'rejected' then 'warning' else 'info' end);
  end if;
  return jsonb_build_object('ok', true, 'application', to_jsonb(v_after));
end;
$$;


--
-- Name: review_influencer_application(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.review_influencer_application(p_application_id uuid, p_status text, p_rejection_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_before public.influencer_applications%rowtype;
  v public.influencer_applications%rowtype;
  p public.influencer_profiles%rowtype;
begin
  if not public.application_staff() then raise exception 'Manager access required'; end if;
  if p_status not in ('in_review', 'approved', 'rejected') then raise exception 'Invalid application status'; end if;
  select * into v_before from public.influencer_applications where id = p_application_id for update;
  if not found then raise exception 'Application not found'; end if;
  if v_before.applicant_user_id = auth.uid() then raise exception 'You cannot review your own application'; end if;
  if v_before.status in ('approved', 'rejected') then raise exception 'This application is already %', v_before.status; end if;
  if p_status = 'rejected' and nullif(btrim(coalesce(p_rejection_reason, '')), '') is null then
    raise exception 'Record why the application is rejected';
  end if;
  update public.influencer_applications
     set status = p_status,
         rejection_reason = case when p_status = 'rejected' then p_rejection_reason else null end,
         reviewed_by = auth.uid(), reviewed_at = now(), updated_at = now()
   where id = p_application_id returning * into v;
  if p_status = 'approved' then
    insert into public.influencer_profiles(application_id, user_id, full_name, email, country, region, niche, status)
    values (v.id, v.applicant_user_id, v.full_name, v.email, v.country, v.region, v.niche, 'active')
    on conflict (application_id) do update set status = 'active', user_id = coalesce(influencer_profiles.user_id, excluded.user_id), updated_at = now()
    returning * into p;
    if v.applicant_user_id is not null then
      insert into public.user_roles (user_id, role) values (v.applicant_user_id, 'influencer') on conflict do nothing;
    end if;
  end if;
  insert into public.influencer_audit_logs(actor_user_id, entity_type, entity_id, action, after_data)
  values (auth.uid(), 'application', v.id, p_status, to_jsonb(v));
  if v.applicant_user_id is not null then
    perform public.mm_notify('influencer.application_' || p_status,
      case p_status when 'approved' then 'Influencer application approved'
                    when 'rejected' then 'Influencer application not approved'
                    else 'Influencer application in review' end,
      format('Application %s is now %s.%s', v.application_number, replace(p_status, '_', ' '),
             case when p_status = 'rejected' then ' Reason: ' || p_rejection_reason else '' end),
      v.applicant_user_id, null, null, null, 0,
      case p_status when 'approved' then 'success' when 'rejected' then 'warning' else 'info' end);
  end if;
  return jsonb_build_object('application', to_jsonb(v), 'profile', case when p.id is null then null else to_jsonb(p) end);
end;
$$;


--
-- Name: review_report_count_sync(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.review_report_count_sync() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_review uuid := coalesce(new.review_id, old.review_id);
begin
  update public.marketplace_reviews
     set report_count = (select count(*) from public.review_reports
                          where review_id = v_review and status in ('open','investigating')),
         status = case
           -- A reported review comes off the storefront while it is looked at.
           when tg_op = 'INSERT' and status = 'published' then 'reported'
           else status end,
         updated_at = now()
   where id = v_review;
  perform public.mm_product_rating_refresh(
    (select product_id from public.marketplace_reviews where id = v_review));
  return coalesce(new, old);
end;
$$;


--
-- Name: role_application_missing(jsonb, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.role_application_missing(p_application jsonb, p_required text[]) RETURNS text[]
    LANGUAGE sql IMMUTABLE
    AS $$
  select coalesce(array_agg(k), '{}') from unnest(p_required) k
   where nullif(btrim(coalesce(p_application ->> k, '')), '') is null
$$;


--
-- Name: server_is_operator(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.server_is_operator() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  -- Infrastructure is operator-level. These are the roles the Control Panel
  -- already treats as platform operators, plus developer, who runs the estate.
  SELECT EXISTS (
    SELECT 1 FROM public.user_roles ur
    WHERE ur.user_id = auth.uid()
      AND ur.role IN ('admin','boss','founder','super_admin','boss_owner','developer')
  );
$$;


--
-- Name: set_default_payment_method(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_default_payment_method(p_method_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_method public.payment_methods%ROWTYPE;
BEGIN
  UPDATE public.payment_methods SET is_default = false WHERE user_id = auth.uid();
  UPDATE public.payment_methods SET is_default = true WHERE id = p_method_id AND user_id = auth.uid()
  RETURNING * INTO v_method;
  IF NOT FOUND THEN RAISE EXCEPTION 'Payment method not found'; END IF;
  RETURN to_jsonb(v_method);
END; $$;


--
-- Name: set_updated_at(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_updated_at() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN NEW.updated_at = now(); RETURN NEW; END; $$;


--
-- Name: sf_active_offers(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sf_active_offers() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select coalesce(jsonb_agg(jsonb_build_object(
           'title', o.title,
           'badge', case when o.discount_percent is not null
                         then o.discount_percent::int::text || '% OFF' else null end,
           'code', o.code,
           'href', o.landing_url,
           'ends_at', o.end_date)
         order by o.priority, o.end_date nulls last), '[]'::jsonb)
    from public.marketing_offers o
   where o.status = 'active'
     and coalesce(o.is_seed, false) = false
     and (o.start_date is null or o.start_date <= current_date)
     and (o.end_date   is null or o.end_date   >= current_date);
$$;


--
-- Name: sf_config_draft(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sf_config_draft(p_kind text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v jsonb;
begin
  if not public.mm_is_operator() then
    return jsonb_build_object('ok', false, 'reason', 'not_permitted');
  end if;

  if p_kind = 'footer' then
    select jsonb_build_object(
      'ok', true,
      'kind', 'footer',
      'settings', (select to_jsonb(s) from public.storefront_footer_settings s limit 1),
      'columns', coalesce((
        select jsonb_agg(jsonb_build_object(
                 'id', c.id, 'key', c.key, 'heading', c.heading,
                 'position', c.position, 'enabled', c.enabled,
                 'links', coalesce((
                   select jsonb_agg(jsonb_build_object(
                            'id', l.id, 'label', l.label, 'link_type', l.link_type,
                            'href', l.href, 'legal_policy_type', l.legal_policy_type,
                            'resolved_href', case when l.link_type = 'legal'
                                                  then public.sf_legal_href(l.legal_policy_type)
                                                  else l.href end,
                            'open_in_new', l.open_in_new, 'position', l.position,
                            'enabled', l.enabled, 'audience', l.audience)
                          order by l.position)
                     from public.storefront_footer_links l where l.column_id = c.id), '[]'::jsonb))
               order by c.position)
          from public.storefront_footer_columns c), '[]'::jsonb),
      'socials', coalesce((
        select jsonb_agg(to_jsonb(s) order by s.position)
          from public.storefront_social_links s), '[]'::jsonb),
      'trust', coalesce((
        select jsonb_agg(to_jsonb(t) order by t.position)
          from public.storefront_trust_items t), '[]'::jsonb)
    ) into v;
  elsif p_kind = 'floating' then
    select jsonb_build_object(
      'ok', true,
      'kind', 'floating',
      'elements', coalesce((
        select jsonb_agg(to_jsonb(f) order by f.position, f.priority)
          from public.storefront_floating_elements f), '[]'::jsonb)
    ) into v;
  else
    return jsonb_build_object('ok', false, 'reason', 'unknown_kind');
  end if;

  return v || jsonb_build_object(
    'live_version', (select version from public.storefront_published_config
                      where kind = p_kind and is_live),
    'published_at', (select published_at from public.storefront_published_config
                      where kind = p_kind and is_live));
end;
$$;


--
-- Name: sf_config_live(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sf_config_live(p_kind text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select coalesce(
    (select snapshot from public.storefront_published_config
      where kind = p_kind and is_live limit 1),
    -- Never published: an empty answer, which the storefront reads as "use the
    -- built-in footer". It must not be confused with "everything is switched
    -- off", so it carries a flag saying so.
    jsonb_build_object('published', false));
$$;


--
-- Name: sf_faq_schema(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sf_faq_schema() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select jsonb_build_object(
    '@context', 'https://schema.org',
    '@type', 'FAQPage',
    'mainEntity', coalesce((
      select jsonb_agg(jsonb_build_object(
               '@type','Question',
               'name', f.question,
               'acceptedAnswer', jsonb_build_object('@type','Answer','text', f.answer))
             order by c.position, f.position)
        from public.faqs f
        left join public.faq_categories c on c.id = f.category_id
       where f.status='published' and f.language='en'), '[]'::jsonb));
$$;


--
-- Name: sf_faqs(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sf_faqs() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  update public.faqs
     set status = 'published',
         published_at = coalesce(published_at, now()),
         ai_generated = false,
         updated_at = now()
   where status = 'scheduled' and scheduled_for <= now();

  return coalesce((
    select jsonb_agg(jsonb_build_object(
             'id', f.id, 'question', f.question, 'answer', f.answer,
             'category', coalesce(c.name,'General'), 'slug', f.slug,
             'seo_title', f.seo_title, 'seo_description', f.seo_description)
           order by c.position, f.position)
      from public.faqs f
      left join public.faq_categories c on c.id = f.category_id
     where f.status='published' and f.language='en'), '[]'::jsonb);
end;
$$;


--
-- Name: sf_floating_save(text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sf_floating_save(p_key text, p_patch jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_before jsonb; v_after jsonb;
begin
  if not public.mm_is_operator() then
    return jsonb_build_object('ok', false, 'reason', 'not_permitted');
  end if;

  select to_jsonb(f) into v_before from public.storefront_floating_elements f where f.key = p_key;
  if v_before is null then
    return jsonb_build_object('ok', false, 'reason', 'unknown_element');
  end if;

  update public.storefront_floating_elements f set
    name            = coalesce(nullif(btrim(p_patch->>'name'),''), f.name),
    label           = coalesce(nullif(btrim(p_patch->>'label'),''), f.label),
    enabled         = coalesce((p_patch->>'enabled')::boolean, f.enabled),
    desktop_enabled = coalesce((p_patch->>'desktop_enabled')::boolean, f.desktop_enabled),
    tablet_enabled  = coalesce((p_patch->>'tablet_enabled')::boolean, f.tablet_enabled),
    mobile_enabled  = coalesce((p_patch->>'mobile_enabled')::boolean, f.mobile_enabled),
    position        = coalesce(p_patch->>'position', f.position),
    offset_x        = coalesce((p_patch->>'offset_x')::int, f.offset_x),
    offset_y        = coalesce((p_patch->>'offset_y')::int, f.offset_y),
    theme           = coalesce(p_patch->>'theme', f.theme),
    icon            = case when p_patch ? 'icon' then nullif(p_patch->>'icon','') else f.icon end,
    trigger_type    = coalesce(p_patch->>'trigger_type', f.trigger_type),
    trigger_value   = coalesce((p_patch->>'trigger_value')::int, f.trigger_value),
    action_type     = coalesce(p_patch->>'action_type', f.action_type),
    action_target   = case when p_patch ? 'action_target'
                           then nullif(btrim(p_patch->>'action_target'),'') else f.action_target end,
    priority        = coalesce((p_patch->>'priority')::int, f.priority),
    audience        = coalesce(p_patch->>'audience', f.audience),
    page_scope      = coalesce(p_patch->>'page_scope', f.page_scope),
    starts_at       = case when p_patch ? 'starts_at'
                           then nullif(p_patch->>'starts_at','')::timestamptz else f.starts_at end,
    ends_at         = case when p_patch ? 'ends_at'
                           then nullif(p_patch->>'ends_at','')::timestamptz else f.ends_at end,
    updated_by      = auth.uid(), updated_at = now()
  where f.key = p_key
  returning to_jsonb(f) into v_after;

  perform public.mm_audit('floating.save', 'storefront_floating', p_key,
                          v_before, v_after, null);
  return jsonb_build_object('ok', true, 'element', v_after);
exception
  when unique_violation then
    return jsonb_build_object('ok', false, 'reason', 'corner_taken',
      'message', 'Another element already sits in that corner at that priority.');
  when check_violation then
    return jsonb_build_object('ok', false, 'reason', 'invalid_config',
      'message', 'That combination is not allowed — check the position, '
              || 'trigger, offsets and action target.');
end;
$$;


--
-- Name: sf_footer_link_remove(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sf_footer_link_remove(p_id uuid, p_hard boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_before jsonb;
begin
  if not public.mm_is_operator() then
    return jsonb_build_object('ok', false, 'reason', 'not_permitted');
  end if;

  select to_jsonb(l) into v_before from public.storefront_footer_links l where l.id = p_id;
  if v_before is null then
    return jsonb_build_object('ok', false, 'reason', 'unknown_link');
  end if;

  if p_hard then
    delete from public.storefront_footer_links where id = p_id;
    perform public.mm_audit('footer.link.delete', 'storefront_footer', p_id::text,
                            v_before, null, 'permanently removed');
    return jsonb_build_object('ok', true, 'deleted', true);
  end if;

  update public.storefront_footer_links
     set enabled = false, updated_by = auth.uid(), updated_at = now()
   where id = p_id;
  perform public.mm_audit('footer.link.disable', 'storefront_footer', p_id::text,
                          v_before, jsonb_build_object('enabled', false), null);
  return jsonb_build_object('ok', true, 'deleted', false);
end;
$$;


--
-- Name: sf_footer_link_save(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sf_footer_link_save(p_patch jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_id     uuid := nullif(p_patch->>'id','')::uuid;
  v_col    uuid;
  v_before jsonb;
  v_after  jsonb;
  v_pos    integer;
begin
  if not public.mm_is_operator() then
    return jsonb_build_object('ok', false, 'reason', 'not_permitted');
  end if;

  if v_id is not null then
    select to_jsonb(l), l.column_id into v_before, v_col
      from public.storefront_footer_links l where l.id = v_id;
    if v_before is null then
      return jsonb_build_object('ok', false, 'reason', 'unknown_link');
    end if;
  end if;

  v_col := coalesce(nullif(p_patch->>'column_id','')::uuid, v_col);
  if v_col is null then
    return jsonb_build_object('ok', false, 'reason', 'column_required');
  end if;
  if not exists (select 1 from public.storefront_footer_columns where id = v_col) then
    return jsonb_build_object('ok', false, 'reason', 'unknown_column');
  end if;

  if v_id is null then
    -- A new link goes to the end of its column unless told otherwise.
    v_pos := coalesce((p_patch->>'position')::int,
                      (select coalesce(max(position), 0) + 1
                         from public.storefront_footer_links where column_id = v_col));

    insert into public.storefront_footer_links
      (column_id, label, link_type, href, legal_policy_type, open_in_new,
       position, enabled, audience, created_by, updated_by)
    values (
      v_col,
      coalesce(nullif(btrim(p_patch->>'label'),''), 'Untitled link'),
      coalesce(p_patch->>'link_type', 'internal'),
      nullif(btrim(coalesce(p_patch->>'href','')), ''),
      nullif(p_patch->>'legal_policy_type',''),
      coalesce((p_patch->>'open_in_new')::boolean, false),
      v_pos,
      coalesce((p_patch->>'enabled')::boolean, true),
      coalesce(p_patch->>'audience', 'all'),
      auth.uid(), auth.uid())
    returning to_jsonb(storefront_footer_links) into v_after;
  else
    update public.storefront_footer_links l set
      column_id         = v_col,
      label             = coalesce(nullif(btrim(p_patch->>'label'),''), l.label),
      link_type         = coalesce(p_patch->>'link_type', l.link_type),
      href              = case when p_patch ? 'href'
                               then nullif(btrim(p_patch->>'href'),'') else l.href end,
      legal_policy_type = case when p_patch ? 'legal_policy_type'
                               then nullif(p_patch->>'legal_policy_type','')
                               else l.legal_policy_type end,
      open_in_new       = coalesce((p_patch->>'open_in_new')::boolean, l.open_in_new),
      position          = coalesce((p_patch->>'position')::int, l.position),
      enabled           = coalesce((p_patch->>'enabled')::boolean, l.enabled),
      audience          = coalesce(p_patch->>'audience', l.audience),
      updated_by        = auth.uid(),
      updated_at        = now()
    where l.id = v_id
    returning to_jsonb(l) into v_after;
  end if;

  perform public.mm_audit(
    case when v_id is null then 'footer.link.add' else 'footer.link.edit' end,
    'storefront_footer', coalesce(v_id::text, (v_after->>'id')),
    v_before, v_after, null);

  return jsonb_build_object('ok', true, 'link', v_after);
exception
  when unique_violation then
    return jsonb_build_object('ok', false, 'reason', 'position_taken',
      'message', 'Another link already holds that position in this column.');
  when check_violation then
    return jsonb_build_object('ok', false, 'reason', 'invalid_link',
      'message', 'A link needs a real destination — a path, an https URL, a '
              || 'mailto address, or a legal policy type.');
end;
$$;


--
-- Name: sf_footer_links_reorder(uuid, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sf_footer_links_reorder(p_column_id uuid, p_ids uuid[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_before jsonb; v_after jsonb; v_n integer;
begin
  if not public.mm_is_operator() then
    return jsonb_build_object('ok', false, 'reason', 'not_permitted');
  end if;

  select count(*) into v_n from public.storefront_footer_links
   where column_id = p_column_id and id = any(p_ids);
  if v_n <> coalesce(array_length(p_ids, 1), 0) then
    return jsonb_build_object('ok', false, 'reason', 'unknown_link',
      'message', 'The order names a link that is not in this column.');
  end if;

  select jsonb_agg(jsonb_build_object('id', id, 'label', label, 'position', position)
                   order by position)
    into v_before from public.storefront_footer_links where column_id = p_column_id;

  -- Uniqueness is checked when the statement commits, so the whole column can
  -- be renumbered at once and every intermediate row stays inside 1..60.
  set constraints public.storefront_footer_links_pos_uq deferred;

  update public.storefront_footer_links l
     set position = array_position(p_ids, l.id),
         updated_by = auth.uid(),
         updated_at = now()
   where l.column_id = p_column_id and l.id = any(p_ids);

  select jsonb_agg(jsonb_build_object('id', id, 'label', label, 'position', position)
                   order by position)
    into v_after from public.storefront_footer_links where column_id = p_column_id;

  perform public.mm_audit('footer.links.reorder', 'storefront_footer',
                          p_column_id::text, v_before, v_after, null);
  return jsonb_build_object('ok', true, 'order', v_after);
end;
$$;


--
-- Name: sf_footer_settings_save(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sf_footer_settings_save(p_patch jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_before jsonb; v_after jsonb;
begin
  if not public.mm_is_operator() then
    return jsonb_build_object('ok', false, 'reason', 'not_permitted');
  end if;

  select to_jsonb(s) into v_before from public.storefront_footer_settings s limit 1;

  update public.storefront_footer_settings s set
    show_footer            = coalesce((p_patch->>'show_footer')::boolean, s.show_footer),
    newsletter_enabled     = coalesce((p_patch->>'newsletter_enabled')::boolean, s.newsletter_enabled),
    newsletter_title       = coalesce(nullif(btrim(p_patch->>'newsletter_title'),''), s.newsletter_title),
    newsletter_description = case when p_patch ? 'newsletter_description'
                                  then nullif(p_patch->>'newsletter_description','')
                                  else s.newsletter_description end,
    newsletter_placeholder = coalesce(nullif(btrim(p_patch->>'newsletter_placeholder'),''), s.newsletter_placeholder),
    newsletter_success     = coalesce(nullif(btrim(p_patch->>'newsletter_success'),''), s.newsletter_success),
    newsletter_consent     = case when p_patch ? 'newsletter_consent'
                                  then nullif(p_patch->>'newsletter_consent','')
                                  else s.newsletter_consent end,
    newsletter_provider    = case when p_patch ? 'newsletter_provider'
                                  then nullif(btrim(p_patch->>'newsletter_provider'),'')
                                  else s.newsletter_provider end,
    newsletter_list_id     = case when p_patch ? 'newsletter_list_id'
                                  then nullif(btrim(p_patch->>'newsletter_list_id'),'')
                                  else s.newsletter_list_id end,
    trust_strip_enabled    = coalesce((p_patch->>'trust_strip_enabled')::boolean, s.trust_strip_enabled),
    updated_by = auth.uid(), updated_at = now()
  where s.id
  returning to_jsonb(s) into v_after;

  perform public.mm_audit('footer.settings.save', 'storefront_footer', 'settings',
                          v_before, v_after, null);
  return jsonb_build_object('ok', true, 'settings', v_after);
end;
$$;


--
-- Name: sf_legal_href(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sf_legal_href(p_policy_type text) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select '/legal/' || lower(regexp_replace(p.policy_type, '[^a-zA-Z0-9]+', '-', 'g'))
    from public.legal_policies p
   where p.policy_type = p_policy_type
     and p.status = 'published'
   order by p.last_updated desc nulls last
   limit 1;
$$;


--
-- Name: sf_publish(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sf_publish(p_kind text, p_note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_check    jsonb;
  v_snapshot jsonb;
  v_version  integer;
begin
  if not public.mm_is_operator() then
    return jsonb_build_object('ok', false, 'reason', 'not_permitted');
  end if;
  if p_kind not in ('footer','floating') then
    return jsonb_build_object('ok', false, 'reason', 'unknown_kind');
  end if;

  v_check := public.sf_validate(p_kind);
  if (v_check->>'errors')::int > 0 then
    return jsonb_build_object('ok', false, 'reason', 'validation_failed',
      'message', 'Nothing was published. Fix the errors first.',
      'validation', v_check);
  end if;

  -- The snapshot holds only what the public needs, already resolved: enabled
  -- rows, in order, with legal links turned into real destinations. The
  -- storefront then renders it without another lookup or another decision.
  if p_kind = 'footer' then
    select jsonb_build_object(
      'published', true,
      'show_footer', (select show_footer from public.storefront_footer_settings limit 1),
      'newsletter', (
        select jsonb_build_object(
          'enabled', s.newsletter_enabled
                     and coalesce(btrim(s.newsletter_provider),'') <> '',
          'title', s.newsletter_title, 'description', s.newsletter_description,
          'placeholder', s.newsletter_placeholder, 'consent', s.newsletter_consent,
          'success', s.newsletter_success)
          from public.storefront_footer_settings s limit 1),
      'columns', coalesce((
        select jsonb_agg(jsonb_build_object(
                 'heading', c.heading,
                 'links', (select jsonb_agg(jsonb_build_object(
                                    'label', l.label,
                                    'href', case when l.link_type = 'legal'
                                                 then public.sf_legal_href(l.legal_policy_type)
                                                 else l.href end,
                                    'open_in_new', l.open_in_new,
                                    'audience', l.audience) order by l.position)
                             from public.storefront_footer_links l
                            where l.column_id = c.id and l.enabled
                              and (l.link_type <> 'legal'
                                   or public.sf_legal_href(l.legal_policy_type) is not null)))
               order by c.position)
          from public.storefront_footer_columns c
         where c.enabled
           and exists (select 1 from public.storefront_footer_links l
                        where l.column_id = c.id and l.enabled)), '[]'::jsonb),
      'socials', coalesce((
        select jsonb_agg(jsonb_build_object('label', s.platform, 'href', s.url,
                                            'handle', s.handle) order by s.position)
          from public.storefront_social_links s where s.enabled), '[]'::jsonb),
      'trust', coalesce((
        select jsonb_agg(jsonb_build_object('kind', t.kind, 'name', t.name,
                                            'alt', t.alt_text, 'icon', t.icon,
                                            'href', t.href) order by t.position)
          from public.storefront_trust_items t
         where t.enabled
           and (select trust_strip_enabled from public.storefront_footer_settings limit 1)),
        '[]'::jsonb)
    ) into v_snapshot;
  else
    select jsonb_build_object(
      'published', true,
      'elements', coalesce((
        select jsonb_agg(jsonb_build_object(
                 'key', f.key, 'type', f.element_type, 'label', f.label,
                 'position', f.position, 'offset_x', f.offset_x, 'offset_y', f.offset_y,
                 'theme', f.theme, 'icon', f.icon, 'priority', f.priority,
                 'desktop', f.desktop_enabled, 'tablet', f.tablet_enabled,
                 'mobile', f.mobile_enabled,
                 'trigger', f.trigger_type, 'trigger_value', f.trigger_value,
                 'action', f.action_type, 'target', f.action_target,
                 'audience', f.audience, 'scope', f.page_scope)
               order by f.position, f.priority)
          from public.storefront_floating_elements f
         where f.enabled
           and (f.starts_at is null or f.starts_at <= now())
           and (f.ends_at   is null or f.ends_at   >  now())), '[]'::jsonb)
    ) into v_snapshot;
  end if;

  select coalesce(max(version), 0) + 1 into v_version
    from public.storefront_published_config where kind = p_kind;

  update public.storefront_published_config set is_live = false
   where kind = p_kind and is_live;

  insert into public.storefront_published_config
    (kind, version, snapshot, is_live, note, published_by)
  values (p_kind, v_version, v_snapshot, true, p_note, auth.uid());

  perform public.mm_audit('storefront.publish', 'storefront_' || p_kind,
                          p_kind, null,
                          jsonb_build_object('version', v_version), p_note);

  return jsonb_build_object('ok', true, 'kind', p_kind, 'version', v_version,
                            'validation', v_check, 'snapshot', v_snapshot);
end;
$$;


--
-- Name: sf_rollback(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sf_rollback(p_kind text, p_version integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_snapshot jsonb; v_new integer;
begin
  if not public.mm_is_operator() then
    return jsonb_build_object('ok', false, 'reason', 'not_permitted');
  end if;

  select snapshot into v_snapshot from public.storefront_published_config
   where kind = p_kind and version = p_version;
  if v_snapshot is null then
    return jsonb_build_object('ok', false, 'reason', 'unknown_version');
  end if;

  select coalesce(max(version), 0) + 1 into v_new
    from public.storefront_published_config where kind = p_kind;

  update public.storefront_published_config set is_live = false
   where kind = p_kind and is_live;

  insert into public.storefront_published_config
    (kind, version, snapshot, is_live, note, published_by)
  values (p_kind, v_new, v_snapshot, true,
          format('Rollback to version %s', p_version), auth.uid());

  perform public.mm_audit('storefront.rollback', 'storefront_' || p_kind, p_kind,
                          jsonb_build_object('from_version', p_version),
                          jsonb_build_object('new_version', v_new), null);

  return jsonb_build_object('ok', true, 'version', v_new, 'restored_from', p_version);
end;
$$;


--
-- Name: sf_social_save(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sf_social_save(p_patch jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_before jsonb; v_after jsonb; v_platform text := btrim(coalesce(p_patch->>'platform',''));
begin
  if not public.mm_is_operator() then
    return jsonb_build_object('ok', false, 'reason', 'not_permitted');
  end if;
  if v_platform = '' then
    return jsonb_build_object('ok', false, 'reason', 'platform_required');
  end if;

  select to_jsonb(s) into v_before from public.storefront_social_links s
   where s.platform = v_platform;

  insert into public.storefront_social_links
    (platform, url, handle, position, enabled, created_by, updated_by)
  values (v_platform,
          btrim(coalesce(p_patch->>'url','')),
          nullif(btrim(coalesce(p_patch->>'handle','')), ''),
          coalesce((p_patch->>'position')::int,
                   (select coalesce(max(position),0)+1 from public.storefront_social_links)),
          coalesce((p_patch->>'enabled')::boolean, true),
          auth.uid(), auth.uid())
  on conflict (platform) do update set
    url        = coalesce(nullif(btrim(excluded.url), ''), public.storefront_social_links.url),
    handle     = coalesce(excluded.handle, public.storefront_social_links.handle),
    position   = coalesce(excluded.position, public.storefront_social_links.position),
    enabled    = excluded.enabled,
    updated_by = auth.uid(), updated_at = now()
  returning to_jsonb(storefront_social_links) into v_after;

  perform public.mm_audit('footer.social.save', 'storefront_footer', v_platform,
                          v_before, v_after, null);
  return jsonb_build_object('ok', true, 'social', v_after);
exception when check_violation then
  return jsonb_build_object('ok', false, 'reason', 'invalid_url',
    'message', 'A social profile must be a full https:// address.');
end;
$$;


--
-- Name: sf_trust_save(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sf_trust_save(p_patch jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_id uuid := nullif(p_patch->>'id','')::uuid; v_before jsonb; v_after jsonb;
begin
  if not public.mm_is_operator() then
    return jsonb_build_object('ok', false, 'reason', 'not_permitted');
  end if;

  if v_id is null then
    return jsonb_build_object('ok', false, 'reason', 'unknown_item');
  end if;
  select to_jsonb(t) into v_before from public.storefront_trust_items t where t.id = v_id;
  if v_before is null then
    return jsonb_build_object('ok', false, 'reason', 'unknown_item');
  end if;

  update public.storefront_trust_items t set
    name       = coalesce(nullif(btrim(p_patch->>'name'),''), t.name),
    alt_text   = coalesce(nullif(btrim(p_patch->>'alt_text'),''), t.alt_text),
    icon       = case when p_patch ? 'icon' then nullif(p_patch->>'icon','') else t.icon end,
    href       = case when p_patch ? 'href' then nullif(p_patch->>'href','') else t.href end,
    position   = coalesce((p_patch->>'position')::int, t.position),
    enabled    = coalesce((p_patch->>'enabled')::boolean, t.enabled),
    updated_by = auth.uid(), updated_at = now()
  where t.id = v_id
  returning to_jsonb(t) into v_after;

  perform public.mm_audit('footer.trust.save', 'storefront_footer', v_id::text,
                          v_before, v_after, null);
  return jsonb_build_object('ok', true, 'item', v_after);
end;
$$;


--
-- Name: sf_vala_tv(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sf_vala_tv() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select coalesce(jsonb_agg(jsonb_build_object(
           'id', v.id, 'title', v.title, 'description', v.description,
           'url', v.url, 'thumbnail', v.thumbnail_url, 'duration', v.duration,
           'category', c.name, 'featured', v.featured,
           'product_slug', p.slug,
           -- Counted, not declared. Null when nothing has been recorded, so a
           -- card can omit it rather than print a zero that looks like failure.
           'views', nullif((select count(*) from public.vala_tv_views w
                             where w.video_id = v.id), 0))
         order by v.featured desc, v.position, v.published_at desc nulls last), '[]'::jsonb)
    from public.vala_tv_videos v
    left join public.vala_tv_categories c on c.id = v.category_id
    left join public.marketplace_products p on p.id = v.product_id
   where v.status = 'published'
     and coalesce(btrim(v.url), '') <> ''
     and (v.publish_at is null or v.publish_at <= now());
$$;


--
-- Name: sf_vala_tv_view(uuid, text, integer, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sf_vala_tv_view(p_video uuid, p_session text, p_watched_ms integer DEFAULT NULL::integer, p_completed boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if not exists (select 1 from public.vala_tv_videos
                  where id = p_video and status = 'published') then
    return jsonb_build_object('ok', false, 'reason', 'not_published');
  end if;

  if exists (select 1 from public.vala_tv_views
              where video_id = p_video
                and coalesce(session_id,'') = coalesce(p_session,'')
                and created_at > now() - interval '6 hours') then
    return jsonb_build_object('ok', true, 'counted', false);
  end if;

  insert into public.vala_tv_views (video_id, user_id, session_id, watched_ms, completed)
  values (p_video, auth.uid(), p_session, p_watched_ms, coalesce(p_completed, false));

  return jsonb_build_object('ok', true, 'counted', true);
end;
$$;


--
-- Name: sf_validate(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sf_validate(p_kind text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_problems jsonb := '[]'::jsonb;
begin
  if not public.mm_is_operator() then
    return jsonb_build_object('ok', false, 'reason', 'not_permitted');
  end if;

  if p_kind = 'footer' then
    -- A link with nothing to point at.
    v_problems := v_problems || coalesce((
      select jsonb_agg(jsonb_build_object(
               'severity', 'error', 'item', l.label,
               'message', 'Link has no destination.'))
        from public.storefront_footer_links l
       where l.enabled
         and l.link_type <> 'legal'
         and (l.href is null or btrim(l.href) in ('', '#'))), '[]'::jsonb);

    -- A legal link whose policy is not published. This is every legal link
    -- today, because legal_policies is empty.
    v_problems := v_problems || coalesce((
      select jsonb_agg(jsonb_build_object(
               'severity', 'error', 'item', l.label,
               'message', 'No published ' || coalesce(l.legal_policy_type, 'legal')
                          || ' policy exists in the Legal Manager, so this link '
                          || 'cannot resolve.'))
        from public.storefront_footer_links l
       where l.enabled and l.link_type = 'legal'
         and public.sf_legal_href(l.legal_policy_type) is null), '[]'::jsonb);

    -- An internal link that is not a path.
    v_problems := v_problems || coalesce((
      select jsonb_agg(jsonb_build_object(
               'severity', 'error', 'item', l.label,
               'message', 'Internal links must start with /'))
        from public.storefront_footer_links l
       where l.enabled and l.link_type = 'internal' and l.href not like '/%'), '[]'::jsonb);

    -- An external link that is not https.
    v_problems := v_problems || coalesce((
      select jsonb_agg(jsonb_build_object(
               'severity', 'error', 'item', l.label,
               'message', 'External links must be https.'))
        from public.storefront_footer_links l
       where l.enabled and l.link_type = 'external' and l.href not like 'https://%'), '[]'::jsonb);

    -- A column with a heading and nothing in it.
    v_problems := v_problems || coalesce((
      select jsonb_agg(jsonb_build_object(
               'severity', 'warning', 'item', c.heading,
               'message', 'Column has no enabled links and will not render.'))
        from public.storefront_footer_columns c
       where c.enabled
         and not exists (select 1 from public.storefront_footer_links l
                          where l.column_id = c.id and l.enabled)), '[]'::jsonb);

    -- A trust item with no description. Section 41.
    v_problems := v_problems || coalesce((
      select jsonb_agg(jsonb_build_object(
               'severity', 'error', 'item', t.name,
               'message', 'Trust item needs alt text.'))
        from public.storefront_trust_items t
       where t.enabled and btrim(coalesce(t.alt_text, '')) = ''), '[]'::jsonb);

    -- Section 22. Offering a subscription with nowhere to send it.
    v_problems := v_problems || coalesce((
      select jsonb_agg(jsonb_build_object(
               'severity', 'error', 'item', 'Newsletter',
               'message', 'The newsletter is switched on but no provider is '
                       || 'configured, so a subscription could not be stored. '
                       || 'Connect a provider or switch it off.'))
        from public.storefront_footer_settings s
       where s.newsletter_enabled
         and coalesce(btrim(s.newsletter_provider), '') = ''), '[]'::jsonb);

  elsif p_kind = 'floating' then
    -- Section 11. Two enabled widgets in the same corner at the same rank.
    v_problems := v_problems || coalesce((
      select jsonb_agg(jsonb_build_object(
               'severity', 'error', 'item', f.position,
               'message', 'Two enabled elements share this corner and priority.'))
        from (select position, priority, count(*) n
                from public.storefront_floating_elements
               where enabled group by position, priority having count(*) > 1) f), '[]'::jsonb);

    -- An element that is on but cannot be seen on any device.
    v_problems := v_problems || coalesce((
      select jsonb_agg(jsonb_build_object(
               'severity', 'warning', 'item', f.name,
               'message', 'Enabled but hidden on every device.'))
        from public.storefront_floating_elements f
       where f.enabled
         and not f.desktop_enabled and not f.tablet_enabled and not f.mobile_enabled), '[]'::jsonb);

    -- An element pointing at nothing usable.
    v_problems := v_problems || coalesce((
      select jsonb_agg(jsonb_build_object(
               'severity', 'error', 'item', f.name,
               'message', 'Action target is missing or malformed.'))
        from public.storefront_floating_elements f
       where f.enabled
         and f.action_type in ('route','external','whatsapp','mailto','tel')
         and (f.action_target is null
              or (f.action_type = 'route'    and f.action_target not like '/%')
              or (f.action_type in ('external','whatsapp') and f.action_target not like 'https://%')
              or (f.action_type = 'mailto'   and f.action_target not like 'mailto:%')
              or (f.action_type = 'tel'      and f.action_target not like 'tel:%'))), '[]'::jsonb);

    -- A schedule that has already closed.
    v_problems := v_problems || coalesce((
      select jsonb_agg(jsonb_build_object(
               'severity', 'warning', 'item', f.name,
               'message', 'Enabled but its schedule has ended.'))
        from public.storefront_floating_elements f
       where f.enabled and f.ends_at is not null and f.ends_at <= now()), '[]'::jsonb);
  else
    return jsonb_build_object('ok', false, 'reason', 'unknown_kind');
  end if;

  return jsonb_build_object(
    'ok', true,
    'errors',   (select count(*) from jsonb_array_elements(v_problems) e
                  where e->>'severity' = 'error'),
    'warnings', (select count(*) from jsonb_array_elements(v_problems) e
                  where e->>'severity' = 'warning'),
    'problems', v_problems);
end;
$$;


--
-- Name: sf_versions(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sf_versions(p_kind text, p_limit integer DEFAULT 20) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if not public.mm_is_operator() then
    return jsonb_build_object('ok', false, 'reason', 'not_permitted');
  end if;
  return jsonb_build_object('ok', true, 'versions', coalesce((
    select jsonb_agg(jsonb_build_object(
             'version', v.version, 'is_live', v.is_live, 'note', v.note,
             'published_at', v.published_at,
             'published_by', (select u.email from auth.users u where u.id = v.published_by))
           order by v.version desc)
      from (select * from public.storefront_published_config
             where kind = p_kind order by version desc limit greatest(p_limit,1)) v),
    '[]'::jsonb));
end;
$$;


--
-- Name: submit_franchise_application(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.submit_franchise_application(p_application jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_user uuid := auth.uid();
  v_row public.franchise_applications%rowtype;
  v_missing text[];
  v_code text;
begin
  if v_user is null then raise exception 'Sign in to apply'; end if;
  if coalesce((p_application ->> 'agreementAccepted')::boolean, false) is not true then
    raise exception 'The agreement must be accepted';
  end if;

  select * into v_row from public.franchise_applications
   where applicant_user_id = v_user and status in ('pending', 'in_review')
   order by created_at desc limit 1;
  if found then
    return jsonb_build_object('application_number', v_row.code, 'status', v_row.status, 'duplicate', true);
  end if;

  v_missing := public.role_application_missing(p_application,
    array['fullName','email','phone','country','companyName','territory','investmentCapacity','businessBackground']);
  if array_length(v_missing, 1) > 0 then
    raise exception 'Missing required fields: %', array_to_string(v_missing, ', ');
  end if;

  v_code := 'FRA-' || upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 10));
  insert into public.franchise_applications
    (code, business_name, owner_name, email, phone, requested_territory, city, state, country,
     experience, business_type, investment_capacity, status, applicant_user_id, application)
  values (v_code,
          btrim(p_application ->> 'companyName'), btrim(p_application ->> 'fullName'),
          btrim(p_application ->> 'email'), btrim(p_application ->> 'phone'),
          btrim(p_application ->> 'territory'),
          coalesce(nullif(btrim(p_application ->> 'city'), ''), btrim(p_application ->> 'territory')),
          coalesce(btrim(p_application ->> 'state'), ''),
          btrim(p_application ->> 'country'),
          coalesce(btrim(p_application ->> 'businessBackground'), ''),
          coalesce(btrim(p_application ->> 'companyType'), ''),
          btrim(p_application ->> 'investmentCapacity'),
          'pending', v_user,
          (p_application - 'agreementAccepted') || jsonb_build_object('agreement_accepted_at', now()))
  returning * into v_row;

  perform public.mm_audit('franchise.application_submitted', 'franchise_application', v_row.id::text, null,
                          jsonb_build_object('code', v_code), null);
  perform public.mm_notify('franchise.application_submitted', 'Application received',
    format('Your franchise application %s is pending review.', v_code),
    v_user, null, null, null, 0, 'info');

  return jsonb_build_object('application_number', v_code, 'status', v_row.status, 'duplicate', false);
end;
$$;


--
-- Name: submit_influencer_application(text, text, text, text, text, jsonb, bigint, text, text[], numeric, jsonb, jsonb, boolean, boolean, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.submit_influencer_application(p_full_name text, p_email text, p_phone text, p_country text, p_region text, p_social_profiles jsonb, p_followers bigint, p_niche text, p_content_types text[], p_engagement_rate numeric, p_payment_details jsonb, p_tax_details jsonb, p_agreement_accepted boolean, p_consent_accepted boolean, p_terms_accepted boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v public.influencer_applications%rowtype;
  v_user uuid := auth.uid();
begin
  if v_user is null then raise exception 'Sign in to apply'; end if;
  if not (p_agreement_accepted and p_consent_accepted and p_terms_accepted) then
    raise exception 'All agreement, consent and terms acknowledgements are required';
  end if;
  if nullif(btrim(coalesce(p_full_name, '')), '') is null or nullif(btrim(coalesce(p_email, '')), '') is null
     or nullif(btrim(coalesce(p_niche, '')), '') is null then
    raise exception 'Missing required fields: full name, email and niche';
  end if;
  select * into v from public.influencer_applications
   where applicant_user_id = v_user and status in ('pending', 'in_review')
   order by created_at desc limit 1;
  if found then
    return jsonb_build_object('id', v.id, 'application_number', v.application_number, 'status', v.status,
                              'created_at', v.created_at, 'duplicate', true);
  end if;
  insert into public.influencer_applications(applicant_user_id, full_name, email, phone, country, region, social_profiles,
    followers, niche, content_types, engagement_rate, payment_details, tax_details,
    agreement_accepted, consent_accepted, terms_accepted)
  values (v_user, p_full_name, p_email, p_phone, p_country, p_region, coalesce(p_social_profiles, '{}'),
    p_followers, p_niche, coalesce(p_content_types, '{}'), p_engagement_rate, coalesce(p_payment_details, '{}'),
    coalesce(p_tax_details, '{}'), p_agreement_accepted, p_consent_accepted, p_terms_accepted)
  returning * into v;
  insert into public.influencer_audit_logs(actor_user_id, entity_type, entity_id, action, after_data)
  values (v_user, 'application', v.id, 'submitted', to_jsonb(v));
  perform public.mm_notify('influencer.application_submitted', 'Application received',
    format('Your influencer application %s is pending review.', v.application_number),
    v_user, null, null, null, 0, 'info');
  return jsonb_build_object('id', v.id, 'application_number', v.application_number, 'status', v.status,
                            'created_at', v.created_at, 'duplicate', false);
end;
$$;


--
-- Name: submit_payment_proof(uuid, numeric, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.submit_payment_proof(p_intent_id uuid, p_amount numeric, p_currency text, p_reference_id text, p_method text, p_screenshot text, p_country text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user uuid := auth.uid();
  v_intent public.payment_intents%ROWTYPE;
  v_status text := 'pending';
  v_payment public.payments%ROWTYPE;
BEGIN
  IF v_user IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  SELECT * INTO v_intent FROM public.payment_intents WHERE id = p_intent_id AND user_id = v_user FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Payment intent not found'; END IF;
  IF v_intent.expires_at <= now() THEN UPDATE public.payment_intents SET status = 'expired', updated_at = now() WHERE id = v_intent.id; RAISE EXCEPTION 'Payment intent expired'; END IF;
  IF v_intent.status NOT IN ('initiated','pending','partial') THEN RAISE EXCEPTION 'Payment intent is not payable'; END IF;
  IF p_currency IS DISTINCT FROM v_intent.currency THEN v_status := 'rejected'; END IF;
  IF p_amount IS NULL OR p_amount <> v_intent.amount THEN v_status := CASE WHEN p_amount < v_intent.amount THEN 'partial' ELSE 'rejected' END; END IF;
  IF nullif(trim(p_reference_id), '') IS NULL OR nullif(trim(p_screenshot), '') IS NULL THEN RAISE EXCEPTION 'Proof and reference are required'; END IF;
  IF EXISTS (SELECT 1 FROM public.payments WHERE user_id = v_user AND reference_id = trim(p_reference_id)) THEN RAISE EXCEPTION 'Duplicate payment reference'; END IF;

  INSERT INTO public.payments (user_id, intent_id, item_id, item_type, amount, submitted_amount, currency, order_id, payment_type, reference_id, screenshot, status, country, mismatch_flag)
  VALUES (v_user, v_intent.id, v_intent.item_id, v_intent.item_type, v_intent.amount, p_amount, p_currency, v_intent.order_id, p_method, trim(p_reference_id), p_screenshot, v_status, p_country, v_status = 'rejected')
  RETURNING * INTO v_payment;
  UPDATE public.payment_intents SET status = v_status, updated_at = now() WHERE id = v_intent.id;
  RETURN jsonb_build_object('payment', to_jsonb(v_payment), 'intent', to_jsonb(v_intent), 'remaining_amount', greatest(v_intent.amount - coalesce(p_amount, 0), 0));
END; $$;


--
-- Name: submit_payment_proof_secure(uuid, numeric, text, text, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.submit_payment_proof_secure(p_intent_id uuid, p_amount numeric, p_currency text, p_reference_id text, p_method text, p_screenshot text, p_device_id text, p_session_id text, p_source_ip text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user uuid := auth.uid();
  v_intent public.payment_intents%ROWTYPE;
  v_status text := 'pending';
  v_payment public.payments%ROWTYPE;
  v_hash text;
BEGIN
  IF v_user IS NULL OR nullif(trim(p_reference_id), '') IS NULL OR nullif(trim(p_device_id), '') IS NULL OR nullif(trim(p_session_id), '') IS NULL THEN RAISE EXCEPTION 'Invalid payment request'; END IF;
  SELECT * INTO v_intent FROM public.payment_intents WHERE id = p_intent_id AND user_id = v_user FOR UPDATE;
  IF NOT FOUND OR v_intent.device_id <> p_device_id OR v_intent.session_id <> p_session_id THEN RAISE EXCEPTION 'Payment session mismatch'; END IF;
  IF v_intent.expires_at <= now() THEN UPDATE public.payment_intents SET status = 'expired', updated_at = now() WHERE id = v_intent.id; RAISE EXCEPTION 'Payment session expired'; END IF;
  IF v_intent.status NOT IN ('initiated','pending','partial') OR v_intent.attempt_count >= 5 THEN RAISE EXCEPTION 'Payment attempt unavailable'; END IF;
  UPDATE public.payment_intents SET attempt_count = attempt_count + 1, updated_at = now() WHERE id = v_intent.id;
  IF p_currency IS DISTINCT FROM v_intent.currency THEN v_status := 'rejected'; END IF;
  IF p_amount IS NULL OR p_amount <> v_intent.amount THEN v_status := CASE WHEN p_amount < v_intent.amount THEN 'partial' ELSE 'rejected' END; END IF;
  IF nullif(trim(p_screenshot), '') IS NULL THEN RAISE EXCEPTION 'Payment proof required'; END IF;
  IF EXISTS (SELECT 1 FROM public.payments WHERE user_id = v_user AND reference_id = trim(p_reference_id)) THEN RAISE EXCEPTION 'Duplicate payment reference'; END IF;
  v_hash := encode(digest(v_intent.order_id || ':' || trim(p_reference_id) || ':' || p_amount::text || ':' || upper(p_currency), 'sha256'), 'hex');
  INSERT INTO public.payments (user_id, intent_id, item_id, item_type, amount, submitted_amount, currency, order_id, payment_type, reference_id, screenshot, status, source_ip, device_id, transaction_hash, mismatch_flag)
  VALUES (v_user, v_intent.id, v_intent.item_id, v_intent.item_type, v_intent.amount, p_amount, upper(p_currency), v_intent.order_id, p_method, trim(p_reference_id), p_screenshot, v_status, nullif(p_source_ip, '')::inet, p_device_id, v_hash, v_status = 'rejected')
  RETURNING * INTO v_payment;
  UPDATE public.payment_intents SET status = v_status, updated_at = now() WHERE id = v_intent.id;
  RETURN jsonb_build_object('payment', to_jsonb(v_payment), 'intent', to_jsonb(v_intent), 'remaining_amount', greatest(v_intent.amount - coalesce(p_amount, 0), 0));
END; $$;


--
-- Name: submit_reseller_application(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.submit_reseller_application(p_application jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_user uuid := auth.uid();
  v_existing public.resellers%rowtype;
  v_previous public.resellers%rowtype;
  v_row public.resellers%rowtype;
  v_number text;
  v_missing text[] := array[]::text[];
  f text;
begin
  if v_user is null then raise exception 'Sign in to apply'; end if;

  -- One live application per account: a second submit answers with it.
  select * into v_existing from public.resellers
   where user_id = v_user and status <> 'terminated'
   order by created_at desc limit 1;
  if found then
    return jsonb_build_object('ok', true, 'duplicate', true, 'id', v_existing.id,
      'application_number', v_existing.code, 'status', v_existing.status);
  end if;

  foreach f in array array['fullName','email','phone','country','companyName','businessType'] loop
    if coalesce(btrim(p_application->>f), '') = '' then v_missing := v_missing || f; end if;
  end loop;
  if array_length(v_missing, 1) > 0 then
    raise exception 'Missing required fields: %', array_to_string(v_missing, ', ');
  end if;
  if coalesce((p_application->>'agreementAccepted')::boolean, false) is not true then
    raise exception 'The reseller agreement must be accepted';
  end if;

  -- A person whose earlier reseller record was terminated applies afresh: a new
  -- record and number, linked to the old one, which is left exactly as it is.
  select * into v_previous from public.resellers
   where user_id = v_user and status = 'terminated'
   order by created_at desc limit 1;

  loop
    v_number := 'RSA-' || upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 10));
    exit when not exists (select 1 from public.resellers where code = v_number);
  end loop;

  insert into public.resellers (name, code, email, phone, region, company_name, status, tier,
                                user_id, application, applied_at)
  values (btrim(p_application->>'fullName'), v_number, lower(btrim(p_application->>'email')),
          btrim(p_application->>'phone'), nullif(btrim(p_application->>'country'), ''),
          btrim(p_application->>'companyName'), 'pending', 'bronze',
          v_user,
          (p_application - 'agreementAccepted' - 'previous_reseller_id' - 'previous_application_number')
            || jsonb_build_object('agreement_accepted_at', now())
            || case when v_previous.id is null then '{}'::jsonb
                    else jsonb_build_object('previous_reseller_id', v_previous.id,
                                            'previous_application_number', v_previous.code) end,
          now())
  returning * into v_row;

  if v_previous.id is not null then
    perform public.mm_audit('reseller.reapplied', 'reseller', v_row.id::text,
      jsonb_build_object('previous_reseller_id', v_previous.id, 'previous_application_number', v_previous.code,
                         'previous_status', v_previous.status),
      jsonb_build_object('application_number', v_row.code, 'status', v_row.status), null);
  end if;

  return jsonb_build_object('ok', true, 'duplicate', false, 'id', v_row.id,
    'application_number', v_row.code, 'status', v_row.status,
    'previous_application_number', v_previous.code);
end;
$$;


--
-- Name: submit_reseller_membership_payment(uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.submit_reseller_membership_payment(p_order_id uuid, p_rail_code text, p_reference text, p_proof text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_user uuid := auth.uid();
  v_order public.reseller_membership_orders%rowtype;
  v_rail public.finance_payment_rails%rowtype;
  v_intent public.finance_payment_intents%rowtype;
begin
  select o.* into v_order from public.reseller_membership_orders o
    join public.resellers r on r.id = o.reseller_id
   where o.id = p_order_id and r.user_id = v_user for update;
  if not found then raise exception 'Order not found'; end if;
  if v_order.status not in ('pending','processing') then
    raise exception 'This order is % and cannot take a payment', v_order.status;
  end if;
  select * into v_rail from public.finance_payment_rails where code = lower(trim(p_rail_code)) and enabled;
  if not found then raise exception 'Payment rail is not configured'; end if;
  if nullif(trim(p_reference), '') is null then raise exception 'Payment reference required'; end if;
  update public.finance_payment_intents set rail_id = v_rail.id, client_reference = trim(p_reference), status = 'processing', updated_at = now()
   where id = v_order.finance_intent_id returning * into v_intent;
  update public.reseller_membership_orders
     set proof_reference = trim(p_reference), proof_metadata = jsonb_build_object('proof', nullif(trim(p_proof), '')),
         status = 'processing', payment_status = 'pending', updated_at = now()
   where id = v_order.id returning * into v_order;
  insert into public.reseller_membership_events (reseller_id, order_id, event_key, event_type, payload)
  values (v_order.reseller_id, v_order.id, 'payment-submitted:' || v_order.id::text || ':' || md5(trim(p_reference)), 'payment.pending',
          jsonb_build_object('rail', v_rail.code, 'reference', trim(p_reference)))
  on conflict (event_key) do nothing;
  return jsonb_build_object('order', to_jsonb(v_order), 'payment_intent', to_jsonb(v_intent));
end;
$$;


--
-- Name: submit_seller_application(text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.submit_seller_application(p_kind text, p_application jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_user uuid := auth.uid();
  v_kind text := lower(btrim(coalesce(p_kind, '')));
  v_row public.marketplace_sellers%rowtype;
  v_missing text[];
  v_name text;
  v_number text;
  v_application jsonb;
begin
  if v_user is null then raise exception 'Sign in to apply'; end if;
  if v_kind not in ('vendor', 'author') then raise exception 'Unknown seller application type'; end if;
  if coalesce((p_application ->> 'agreementAccepted')::boolean, false) is not true then
    raise exception 'The agreement must be accepted';
  end if;

  select * into v_row from public.marketplace_sellers where owner_user_id = v_user;
  if found then
    return jsonb_build_object('application_number', coalesce(v_row.application ->> 'application_number', v_row.slug),
                              'status', v_row.status, 'duplicate', true);
  end if;

  v_missing := public.role_application_missing(p_application,
    case v_kind
      when 'vendor' then array['fullName','email','phone','country','companyName','registrationNumber',
                               'gstNumber','businessAddress','contactPerson','categoriesInterested']
      else array['fullName','email','phone','country','experienceYears','experienceSummary','techStack',
                 'languages','github','softwareCategories','productsCount'] end);
  if array_length(v_missing, 1) > 0 then
    raise exception 'Missing required fields: %', array_to_string(v_missing, ', ');
  end if;

  v_name := left(coalesce(nullif(btrim(p_application ->> 'companyName'), ''), btrim(p_application ->> 'fullName')), 120);
  v_number := case v_kind when 'vendor' then 'SVV-' else 'SVA-' end
              || upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 10));
  v_application := (p_application - 'agreementAccepted')
                   || jsonb_build_object('application_number', v_number, 'agreement_accepted_at', now());

  insert into public.marketplace_sellers (owner_user_id, display_name, slug, status, seller_kind, application, applied_at)
  values (v_user, v_name,
          left(trim(both '-' from regexp_replace(lower(v_name), '[^a-z0-9]+', '-', 'g')), 60)
            || '-' || lower(substr(v_number, 5, 6)),
          'pending', v_kind, v_application, now())
  returning * into v_row;

  perform public.mm_audit('seller.application_submitted', 'marketplace_seller', v_row.id::text, null,
                          jsonb_build_object('kind', v_kind, 'application_number', v_number), null);
  perform public.mm_notify('seller.application_submitted', 'Application received',
    format('Your %s application %s is pending review.', v_kind, v_number),
    v_user, null, null, null, 0, 'info');

  return jsonb_build_object('application_number', v_number, 'status', v_row.status, 'duplicate', false);
end;
$$;


--
-- Name: submit_unified_payment(text, text, numeric, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.submit_unified_payment(p_item_id text, p_item_type text, p_amount numeric, p_method text, p_reference_id text, p_screenshot text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user uuid := auth.uid();
  v_payment public.payments%ROWTYPE;
BEGIN
  IF v_user IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  IF p_item_type NOT IN ('product','plan','subscription','wallet_topup') THEN RAISE EXCEPTION 'Invalid payment item type'; END IF;
  IF p_method NOT IN ('wise','remitly','western_union','moneygram','payoneer','skrill','neteller','binance','upi','bank_manual') THEN RAISE EXCEPTION 'Invalid payment method'; END IF;
  IF p_amount IS NULL OR p_amount <= 0 THEN RAISE EXCEPTION 'Payment amount must be positive'; END IF;
  IF nullif(trim(p_reference_id), '') IS NULL OR nullif(trim(p_screenshot), '') IS NULL THEN RAISE EXCEPTION 'Payment reference and screenshot proof are required'; END IF;

  SELECT * INTO v_payment FROM public.payments WHERE user_id = v_user AND reference_id = trim(p_reference_id) FOR UPDATE;
  IF FOUND THEN RETURN to_jsonb(v_payment); END IF;

  INSERT INTO public.payments (user_id, item_id, item_type, amount, payment_type, reference_id, screenshot, last_checked_at)
  VALUES (v_user, trim(p_item_id), p_item_type, p_amount, p_method, trim(p_reference_id), p_screenshot, now())
  RETURNING * INTO v_payment;
  RETURN to_jsonb(v_payment);
END; $$;


--
-- Name: tm_activity_is_append_only(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tm_activity_is_append_only() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  raise exception 'the task audit log is append-only; % is not permitted', tg_op
    using errcode = 'insufficient_privilege';
end;
$$;


--
-- Name: tm_allowed_transitions(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tm_allowed_transitions(p_from text) RETURNS text[]
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select case p_from
    when 'new'                 then array['routed','available_for_claim','assigned','claimed','accepted','cancelled']
    when 'routed'              then array['available_for_claim','assigned','claimed','accepted','cancelled']
    when 'available_for_claim' then array['claimed','assigned','accepted','routed','cancelled']
    when 'claimed'             then array['accepted','in_progress','available_for_claim','cancelled']
    when 'assigned'            then array['accepted','in_progress','claimed','new','cancelled']
    when 'accepted'            then array['in_progress','on_hold','blocked','completed','cancelled']
    when 'in_progress'         then array['on_hold','blocked','waiting_client','ai_review','testing','submitted','completed','failed','cancelled']
    when 'on_hold'             then array['in_progress','accepted','blocked','cancelled']
    when 'blocked'             then array['in_progress','on_hold','failed','cancelled']
    when 'waiting_client'      then array['in_progress','on_hold','cancelled']
    when 'ai_review'           then array['in_progress','testing','submitted','rejected','completed']
    when 'testing'             then array['in_progress','submitted','rejected','failed','completed']
    when 'submitted'           then array['under_review','approved','rejected','in_progress']
    when 'under_review'        then array['approved','rejected','in_progress','testing']
    when 'approved'            then array['completed','closed']
    -- Rejection is a round trip, not an ending: the work goes back and returns.
    when 'rejected'            then array['in_progress','submitted','closed','cancelled']
    when 'completed'           then array['approved','closed']
    when 'failed'              then array['in_progress','closed','cancelled']
    when 'cancelled'           then array['closed']
    when 'closed'              then array[]::text[]
    else array[]::text[]
  end;
$$;


--
-- Name: tm_assignment_candidates(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tm_assignment_candidates(p_task_id uuid) RETURNS TABLE(member_id uuid, full_name text, role text, department text, skills text[], open_tasks integer, committed_hours numeric, capacity_hours numeric, load_percent numeric, skill_matches text[], role_matches boolean, available boolean, score numeric, reasons text[])
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_task     public.tm_tasks%rowtype;
  v_needed   text[];
  v_default  numeric;
begin
  select * into v_task from public.tm_tasks where id = p_task_id;
  if not found then
    return;
  end if;

  -- What the work needs: its tags are the closest thing the model has to a
  -- required-skills list, plus its category.
  v_needed := (
    select array(
      select distinct lower(x) from unnest(
        coalesce(v_task.tags, '{}'::text[]) ||
        case when v_task.category is null then '{}'::text[] else array[v_task.category] end
      ) as x
      where x is not null and x <> ''
    )
  );

  select coalesce(nullif(avg(nullif(m.capacity_hours, 0)), 0), 40)
    into v_default
  from public.tm_members m where m.active;

  return query
  with load as (
    select t.assigned_to as member,
           count(*)::int as open_tasks,
           coalesce(sum(coalesce(t.estimated_hours, 0)), 0)::numeric as committed
    from public.tm_tasks t
    where t.assigned_to is not null
      and t.status not in ('completed', 'cancelled', 'closed', 'approved', 'rejected')
    group by t.assigned_to
  ),
  scored as (
    select
      m.id,
      m.full_name,
      m.role,
      m.department,
      m.skills,
      coalesce(l.open_tasks, 0) as open_tasks,
      coalesce(l.committed, 0)  as committed,
      coalesce(nullif(m.capacity_hours, 0), v_default) as capacity,
      (select array(
         select s from unnest(coalesce(m.skills, '{}'::text[])) s
         where lower(s) = any (v_needed)))                      as matched,
      (v_task.assigned_role is null
        or lower(m.role) = lower(v_task.assigned_role))          as role_ok,
      m.active                                                   as is_active
    from public.tm_members m
    left join load l on l.member = m.id
    where m.active
  )
  select
    s.id,
    s.full_name,
    s.role,
    s.department,
    s.skills,
    s.open_tasks,
    round(s.committed, 2),
    round(s.capacity, 2),
    round(least(s.committed / nullif(s.capacity, 0) * 100, 999), 1) as load_percent,
    s.matched,
    s.role_ok,
    s.is_active,
    round(
      -- Routing by role is the strongest signal, then demonstrated skill,
      -- then how much room the person actually has left.
      (case when s.role_ok then 40 else 0 end)
      + least(coalesce(array_length(s.matched, 1), 0) * 15, 30)
      + greatest(0, 30 * (1 - least(s.committed / nullif(s.capacity, 0), 1)))
    , 1) as score,
    (
      array_remove(array[
        case when s.role_ok and v_task.assigned_role is not null
             then format('routed role: %s', s.role) end,
        case when coalesce(array_length(s.matched, 1), 0) > 0
             then format('skills: %s', array_to_string(s.matched, ', ')) end,
        case when s.committed >= s.capacity
             then format('at or over capacity (%s of %sh)', round(s.committed), round(s.capacity))
             else format('%sh of %sh committed', round(s.committed), round(s.capacity)) end,
        case when s.open_tasks = 0 then 'no open work' end
      ], null)
    ) as reasons
  from scored s
  order by score desc, s.committed asc, s.full_name asc;
end;
$$;


--
-- Name: tm_audit_assignment_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tm_audit_assignment_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_member uuid;
  v_from   text;
  v_to     text;
begin
  if new.assigned_to is not distinct from old.assigned_to then
    return null;
  end if;

  select id into v_member from public.tm_members where user_id = auth.uid();
  select full_name into v_from from public.tm_members where id = old.assigned_to;
  select full_name into v_to   from public.tm_members where id = new.assigned_to;

  insert into public.tm_activity (task_id, actor_id, actor_name, actor_role,
                                  action, action_type, from_value, to_value)
  values (new.id, v_member, 'Task Manager', 'system',
          case when old.assigned_to is null then 'Task assigned' else 'Task reassigned' end,
          'assignment', coalesce(v_from, 'unassigned'), coalesce(v_to, 'unassigned'));
  return null;
end;
$$;


--
-- Name: tm_audit_status_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tm_audit_status_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_member uuid;
  v_actor  text;
  v_role   text;
begin
  if new.status is not distinct from old.status then
    return null;
  end if;

  select m.id, m.full_name, m.role into v_member, v_actor, v_role
  from public.tm_members m
  where m.user_id = auth.uid();

  insert into public.tm_activity (task_id, actor_id, actor_name, actor_role,
                                  action, action_type, from_value, to_value, details)
  values (new.id, v_member,
          coalesce(v_actor, case when auth.uid() is null then 'system' else 'account' end),
          coalesce(v_role, 'system'),
          format('Status %s to %s', old.status, new.status),
          'status', old.status, new.status,
          case when new.blocked_reason is distinct from old.blocked_reason
               then new.blocked_reason end);
  return null;
end;
$$;


--
-- Name: tm_broadcast_pool_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tm_broadcast_pool_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'realtime', 'pg_temp'
    AS $$
declare
  v_task_id uuid;
begin
  if tg_op = 'DELETE' then
    v_task_id := old.id;
  else
    v_task_id := new.id;
  end if;

  -- Only visibility- and alarm-affecting changes are worth waking clients for.
  if tg_op = 'UPDATE'
     and new.assigned_to is not distinct from old.assigned_to
     and new.status is not distinct from old.status
     and new.buzzer_active is not distinct from old.buzzer_active then
    return null;
  end if;

  begin
    perform realtime.send(
      jsonb_build_object('task_id', v_task_id, 'op', tg_op),
      'pool_changed',
      'tm:pool',
      true
    );
  exception when others then
    -- Never let a notification failure roll back the claim it was announcing.
    raise warning 'tm pool broadcast failed for %: %', v_task_id, sqlerrm;
  end;

  return null;
end;
$$;


--
-- Name: tm_claim_task(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tm_claim_task(p_task_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_member  uuid;
  v_claimed public.tm_tasks%rowtype;
  v_current uuid;
begin
  v_member := public.tm_my_member_id();
  if v_member is null then
    return jsonb_build_object('ok', false, 'reason', 'not_a_member');
  end if;

  -- The whole race is decided by this one statement. Postgres locks the row
  -- while it evaluates the WHERE clause, so of two simultaneous callers exactly
  -- one can still see assigned_to IS NULL. The loser updates nothing.
  update public.tm_tasks
     set assigned_to  = v_member,
         status       = 'accepted',
         accepted_at  = now(),
         claimed_at   = coalesce(claimed_at, now()),
         buzzer_active = false,
         buzzer_acknowledged_at = now(),
         acknowledged_by = v_member,
         updated_at   = now()
   where id = p_task_id
     and assigned_to is null
     and status = any (public.tm_pool_statuses())
  returning * into v_claimed;

  if not found then
    select assigned_to into v_current from public.tm_tasks where id = p_task_id;
    return jsonb_build_object(
      'ok', false,
      'reason', case when v_current is null then 'not_claimable' else 'already_claimed' end,
      'claimed_by', v_current
    );
  end if;

  insert into public.tm_activity (task_id, actor_name, actor_role, action, action_type,
                                  from_value, to_value, details)
  values (p_task_id,
          coalesce((select full_name from public.tm_members where id = v_member), 'member'),
          'member', 'Task claimed', 'claim', 'unassigned', v_member::text,
          'Claimed through tm_claim_task');

  return jsonb_build_object('ok', true, 'task_id', p_task_id, 'member_id', v_member);
end;
$$;


--
-- Name: tm_condition_matches(jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tm_condition_matches(p_task jsonb, p_condition jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_clauses jsonb;
  v_clause  jsonb;
  v_mode    text := 'all';
  v_field   text;
  v_op      text;
  v_value   jsonb;
  v_actual  text;
  v_hit     boolean;
  v_any     boolean := false;
begin
  if p_condition is null or p_condition = 'null'::jsonb or p_condition = '{}'::jsonb then
    return true;
  end if;

  if p_condition ? 'all' then
    v_clauses := p_condition -> 'all';
  elsif p_condition ? 'any' then
    v_clauses := p_condition -> 'any';
    v_mode := 'any';
  else
    -- The shape the rule editor writes: {"priority": "critical"} means equality.
    select coalesce(jsonb_agg(jsonb_build_object('field', k, 'op', 'eq', 'value', v)), '[]'::jsonb)
      into v_clauses
    from jsonb_each(p_condition) as e(k, v);
  end if;

  for v_clause in select * from jsonb_array_elements(v_clauses)
  loop
    v_field  := v_clause ->> 'field';
    v_op     := coalesce(v_clause ->> 'op', 'eq');
    v_value  := v_clause -> 'value';
    v_actual := p_task ->> v_field;

    v_hit := case v_op
      when 'eq'       then v_actual is not distinct from (v_value #>> '{}')
      when 'ne'       then v_actual is distinct from (v_value #>> '{}')
      when 'gt'       then v_actual is not null and v_actual::numeric >  (v_value #>> '{}')::numeric
      when 'gte'      then v_actual is not null and v_actual::numeric >= (v_value #>> '{}')::numeric
      when 'lt'       then v_actual is not null and v_actual::numeric <  (v_value #>> '{}')::numeric
      when 'lte'      then v_actual is not null and v_actual::numeric <= (v_value #>> '{}')::numeric
      when 'is_null'  then v_actual is null
      when 'not_null' then v_actual is not null
      when 'contains' then v_actual is not null and position((v_value #>> '{}') in v_actual) > 0
      when 'in'       then v_actual is not null and exists (
                            select 1 from jsonb_array_elements_text(v_value) x where x = v_actual)
      when 'not_in'   then v_actual is null or not exists (
                            select 1 from jsonb_array_elements_text(v_value) x where x = v_actual)
      else false
    end;

    if v_mode = 'all' and not v_hit then
      return false;
    end if;
    if v_hit then
      v_any := true;
    end if;
  end loop;

  return case when v_mode = 'all' then true else v_any end;
end;
$$;


--
-- Name: tm_dependency_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tm_dependency_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if new.task_id = new.depends_on_task_id then
    raise exception 'a task cannot depend on itself'
      using errcode = 'check_violation';
  end if;

  if public.tm_dependency_would_cycle(new.task_id, new.depends_on_task_id) then
    raise exception
      'that dependency would close a loop: % already waits on %',
      new.depends_on_task_id, new.task_id
      using errcode = 'check_violation';
  end if;

  return new;
end;
$$;


--
-- Name: tm_dependency_would_cycle(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tm_dependency_would_cycle(p_task uuid, p_depends_on uuid) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  -- Does p_depends_on already wait, directly or at any remove, on p_task?
  with recursive chain as (
    select depends_on_task_id as node
    from public.tm_dependencies
    where task_id = p_depends_on
    union
    select d.depends_on_task_id
    from public.tm_dependencies d
    join chain c on d.task_id = c.node
  )
  select p_task = p_depends_on or exists (select 1 from chain where node = p_task);
$$;


--
-- Name: tm_developer_for_member(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tm_developer_for_member(p_member_id uuid) RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT d.id FROM public.developers d
  JOIN public.tm_members m ON m.user_id = d.user_id
  WHERE m.id = p_member_id
  LIMIT 1;
$$;


--
-- Name: tm_enforce_transition(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tm_enforce_transition() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if new.status is not distinct from old.status then
    return new;
  end if;

  -- A change arriving from another trigger is the Developer Manager bridge
  -- mapping its own vocabulary across. That mapping is constrained at its own
  -- end; re-checking it here would only fight it.
  if pg_trigger_depth() > 1 then
    return new;
  end if;

  if not (new.status = any (public.tm_allowed_transitions(old.status))) then
    raise exception
      'invalid task transition: % cannot become % (allowed: %)',
      old.status, new.status, array_to_string(public.tm_allowed_transitions(old.status), ', ')
      using errcode = 'check_violation';
  end if;

  -- Stamp the moments the lifecycle cares about, so they cannot be forgotten
  -- by whichever caller happened to make the change.
  if new.status = 'claimed'      and new.claimed_at   is null then new.claimed_at   := now(); end if;
  if new.status = 'in_progress'  and new.started_at   is null then new.started_at   := now(); end if;
  if new.status = 'submitted'    and new.submitted_at is null then new.submitted_at := now(); end if;
  if new.status = 'under_review' and new.reviewed_at  is null then new.reviewed_at  := now(); end if;
  if new.status = 'approved'     and new.approved_at  is null then new.approved_at  := now(); end if;
  if new.status = 'completed'    and new.completed_at is null then new.completed_at := now(); end if;
  if new.status = 'closed'       and new.closed_at    is null then new.closed_at    := now(); end if;

  return new;
end;
$$;


--
-- Name: tm_fire_automations(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tm_fire_automations() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  -- An automation that edits the task would otherwise re-enter this trigger.
  if pg_trigger_depth() > 1 then
    return null;
  end if;

  if tg_op = 'INSERT' then
    perform public.tm_run_automations(new.id, 'task_created');
    if new.assigned_to is not null then
      perform public.tm_run_automations(new.id, 'task_assigned');
    end if;
    return null;
  end if;

  if new.assigned_to is distinct from old.assigned_to and new.assigned_to is not null then
    perform public.tm_run_automations(new.id, 'task_assigned');
  end if;

  if new.approval_status is distinct from old.approval_status and new.approval_status = 'pending' then
    perform public.tm_run_automations(new.id, 'approval_pending');
  end if;

  if new.status is distinct from old.status then
    perform public.tm_run_automations(new.id, 'status_changed');
    case new.status
      when 'blocked'   then perform public.tm_run_automations(new.id, 'task_blocked');
      when 'submitted' then perform public.tm_run_automations(new.id, 'task_submitted');
      when 'approved'  then perform public.tm_run_automations(new.id, 'task_approved');
      when 'completed' then perform public.tm_run_automations(new.id, 'task_completed');
      when 'cancelled' then perform public.tm_run_automations(new.id, 'task_cancelled');
      else null;
    end case;
  end if;

  return null;
end;
$$;


--
-- Name: tm_is_operator(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tm_is_operator() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM public.user_roles ur
    WHERE ur.user_id = auth.uid()
      AND ur.role IN ('admin','boss','founder','super_admin','boss_owner')
  );
$$;


--
-- Name: tm_member_for_developer(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tm_member_for_developer(p_developer_id uuid) RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT m.id FROM public.tm_members m
  JOIN public.developers d ON d.user_id = m.user_id
  WHERE d.id = p_developer_id
  LIMIT 1;
$$;


--
-- Name: tm_mirror_to_developer(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tm_mirror_to_developer() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_dev  uuid;
  v_role text;
begin
  -- Only ever reached from a direct write; the paired trigger going the other
  -- way must not cause this one to write back.
  if pg_trigger_depth() > 1 then
    return null;
  end if;

  if new.assigned_to is null then
    return null;
  end if;

  -- Already bridged: the existing sync trigger keeps it in step.
  if exists (select 1 from public.developer_tasks where tm_task_id = new.id) then
    return null;
  end if;

  select m.role into v_role from public.tm_members m where m.id = new.assigned_to;
  v_dev := public.tm_developer_for_member(new.assigned_to);

  -- Work assigned to somebody who is not a developer does not belong on a
  -- developer board, so nothing is created for it.
  if v_dev is null and coalesce(lower(v_role), '') <> 'developer' then
    return null;
  end if;

  insert into public.developer_tasks
    (title, category, status, developer_id, progress_percent, tm_task_id)
  values (new.title,
          coalesce(new.category, 'general'),
          public.tm_status_to_developer(new.status),
          v_dev,
          coalesce(new.progress, 0),
          new.id);

  insert into public.tm_activity (task_id, actor_name, actor_role, action, action_type, details)
  values (new.id, 'Task Manager', 'system', 'Mirrored to Developer Manager', 'bridge',
          format('developer_id %s', coalesce(v_dev::text, 'unassigned')));

  return null;
end;
$$;


--
-- Name: tm_my_member_id(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tm_my_member_id() RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT id FROM public.tm_members WHERE user_id = auth.uid() LIMIT 1;
$$;


--
-- Name: tm_open_developer_task(text, text, uuid, text, timestamp with time zone, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tm_open_developer_task(p_title text, p_description text DEFAULT ''::text, p_developer_id uuid DEFAULT NULL::uuid, p_priority text DEFAULT 'medium'::text, p_deadline timestamp with time zone DEFAULT NULL::timestamp with time zone, p_amount numeric DEFAULT NULL::numeric, p_module text DEFAULT 'developer_manager'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_task public.tm_tasks%rowtype;
  v_dev  uuid;
  v_code text;
begin
  if not public.tm_is_operator() then
    return jsonb_build_object('ok', false, 'reason', 'forbidden');
  end if;

  v_code := 'DEV-' || upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 8));

  insert into public.tm_tasks (code, title, description, module, status, priority,
                               deadline, assigned_to, billable, cost, buzzer_active)
  values (v_code, p_title, coalesce(p_description, ''), p_module,
          case when p_developer_id is null then 'new' else 'assigned' end,
          p_priority, p_deadline,
          public.tm_member_for_developer(p_developer_id),
          p_amount is not null, coalesce(p_amount, 0),
          p_developer_id is null)
  returning * into v_task;

  -- Assigning the task above may already have mirrored it. Fill in the detail
  -- that only this call knows rather than creating a second row.
  select id into v_dev from public.developer_tasks where tm_task_id = v_task.id;

  if v_dev is null then
    insert into public.developer_tasks (title, description, status, priority,
                                        developer_id, deadline, task_amount, tm_task_id)
    values (p_title, coalesce(p_description, ''),
            public.tm_status_to_developer(v_task.status), p_priority,
            p_developer_id, p_deadline, p_amount, v_task.id)
    returning id into v_dev;
  else
    update public.developer_tasks
       set description  = coalesce(nullif(p_description, ''), description),
           priority     = p_priority,
           developer_id = coalesce(p_developer_id, developer_id),
           deadline     = coalesce(p_deadline, deadline),
           task_amount  = coalesce(p_amount, task_amount)
     where id = v_dev;
  end if;

  insert into public.tm_activity (task_id, actor_name, actor_role, action, action_type, details)
  values (v_task.id, 'developer_manager', 'operator', 'Task opened', 'create',
          'Opened on the canonical engine and mirrored to developer_tasks');

  return jsonb_build_object('ok', true, 'tm_task_id', v_task.id,
                            'developer_task_id', v_dev, 'code', v_code);
end;
$$;


--
-- Name: tm_pool_statuses(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tm_pool_statuses() RETURNS text[]
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  -- Work nobody has taken on yet: raised, routed to a role, offered to the
  -- pool, or handed to somebody who has not yet accepted it.
  select array['new','routed','available_for_claim','assigned']::text[];
$$;


--
-- Name: tm_route_task(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tm_route_task(p_task_id uuid, p_role text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_task    public.tm_tasks%rowtype;
  v_matches int;
begin
  if not public.tm_is_operator() then
    return jsonb_build_object('ok', false, 'reason', 'not_permitted');
  end if;

  select * into v_task from public.tm_tasks where id = p_task_id;
  if not found then
    return jsonb_build_object('ok', false, 'reason', 'no_such_task');
  end if;

  select count(*) into v_matches
  from public.tm_members m where m.active and lower(m.role) = lower(p_role);

  update public.tm_tasks
     set assigned_role = p_role,
         status = case
                    when status in ('new', 'routed') and v_matches > 0 then 'available_for_claim'
                    when status = 'new' then 'routed'
                    else status
                  end,
         buzzer_active = case when v_matches > 0 then true else buzzer_active end,
         updated_at = now()
   where id = p_task_id;

  insert into public.tm_activity (task_id, actor_name, actor_role, action, action_type,
                                  from_value, to_value, details)
  values (p_task_id, 'Task Manager', 'system', 'Task routed', 'routing',
          coalesce(v_task.assigned_role, 'unrouted'), p_role,
          format('%s active member(s) hold that role', v_matches));

  return jsonb_build_object('ok', true, 'role', p_role, 'eligible_members', v_matches);
end;
$$;


--
-- Name: tm_run_automations(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tm_run_automations(p_task_id uuid, p_trigger text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_task    public.tm_tasks%rowtype;
  v_json    jsonb;
  v_rule    public.tm_automations%rowtype;
  v_fired   int := 0;
  v_skipped int := 0;
  v_failed  int := 0;
  v_cfg     jsonb;
  v_target  text;
begin
  select * into v_task from public.tm_tasks where id = p_task_id;
  if not found then
    return jsonb_build_object('ok', false, 'reason', 'no_such_task');
  end if;
  v_json := to_jsonb(v_task);

  for v_rule in
    select * from public.tm_automations
    where enabled and trigger_type = p_trigger
    order by created_at
  loop
    if not public.tm_condition_matches(v_json, v_rule.condition_json) then
      v_skipped := v_skipped + 1;
      continue;
    end if;

    v_cfg := coalesce(v_rule.action_config, '{}'::jsonb);

    begin
      case v_rule.action_type

        when 'notify', 'notify_manager' then
          insert into public.tm_notifications (task_id, title, message, level, channel)
          values (p_task_id,
                  coalesce(v_cfg ->> 'title', v_rule.name),
                  coalesce(v_cfg ->> 'message',
                           format('%s (%s) - %s', v_task.title, v_task.code, p_trigger)),
                  coalesce(v_cfg ->> 'level', case when v_rule.action_type = 'notify_manager'
                                                   then 'warning' else 'info' end),
                  coalesce(v_cfg ->> 'channel', 'in_app'));

        when 'buzzer', 'start_buzzer', 'stop_buzzer' then
          -- 'buzzer' takes its direction from the config; the other two are explicit.
          if v_rule.action_type = 'stop_buzzer'
             or coalesce(v_cfg ->> 'state', 'start') = 'stop' then
            update public.tm_tasks set buzzer_active = false
             where id = p_task_id and buzzer_active is distinct from false;
          else
            update public.tm_tasks set buzzer_active = true, buzzer_acknowledged_at = null
             where id = p_task_id and buzzer_active is distinct from true;
          end if;

        when 'set_priority' then
          v_target := v_cfg ->> 'priority';
          if v_target = any (array['low','medium','high','critical']) then
            update public.tm_tasks set priority = v_target where id = p_task_id;
          else
            v_failed := v_failed + 1;
            continue;
          end if;

        when 'add_tag' then
          v_target := v_cfg ->> 'tag';
          if v_target is not null then
            update public.tm_tasks
               set tags = (select array(select distinct unnest(coalesce(tags, '{}') || v_target)))
             where id = p_task_id;
          end if;

        when 'ai_review' then
          if 'ai_review' = any (public.tm_allowed_transitions(v_task.status)) then
            update public.tm_tasks set status = 'ai_review' where id = p_task_id;
          else
            v_failed := v_failed + 1;
            continue;
          end if;

        when 'escalate' then
          insert into public.tm_escalations (task_id, level, reason, raised_by, raised_to, status)
          values (p_task_id,
                  coalesce((v_cfg ->> 'level')::int, least(v_task.escalation_level + 1, 4)),
                  coalesce(v_cfg ->> 'reason', format('automation: %s', v_rule.name)),
                  'automation',
                  coalesce(v_cfg ->> 'raised_to', 'manager'),
                  'open');
          update public.tm_tasks
             set escalation_level = greatest(escalation_level,
                   coalesce((v_cfg ->> 'level')::int, least(v_task.escalation_level + 1, 4)))
           where id = p_task_id;

        when 'assign', 'reassign' then
          v_target := v_cfg ->> 'member_id';
          if v_target is not null then
            update public.tm_tasks
               set assigned_to = v_target::uuid,
                   status = case when status = 'new' then 'assigned' else status end
             where id = p_task_id;
          end if;

        when 'update_status' then
          v_target := v_cfg ->> 'status';
          if v_target is not null
             and v_target = any (public.tm_allowed_transitions(v_task.status)) then
            update public.tm_tasks set status = v_target where id = p_task_id;
          else
            -- A rule may not smuggle a task through a transition a person
            -- would be refused.
            v_failed := v_failed + 1;
            continue;
          end if;

        when 'create_subtask' then
          insert into public.tm_subtasks (task_id, title, position)
          values (p_task_id,
                  coalesce(v_cfg ->> 'title', 'Follow-up'),
                  coalesce((select max(position) + 1 from public.tm_subtasks where task_id = p_task_id), 0));

        when 'audit' then
          null;  -- the audit row below is the whole action

        else
          v_failed := v_failed + 1;
          continue;
      end case;

      insert into public.tm_activity (task_id, actor_name, actor_role, action, action_type, details, meta)
      values (p_task_id, 'Automation', 'system',
              format('Rule "%s" ran', v_rule.name), 'automation',
              format('trigger %s, action %s', p_trigger, v_rule.action_type),
              jsonb_build_object('rule_id', v_rule.id, 'trigger', p_trigger,
                                 'action', v_rule.action_type));

      update public.tm_automations
         set run_count = run_count + 1, last_run_at = now()
       where id = v_rule.id;

      v_fired := v_fired + 1;

    exception when others then
      -- One broken rule must not stop the others, nor the write that triggered them.
      v_failed := v_failed + 1;
      raise warning 'automation % failed on task %: %', v_rule.id, p_task_id, sqlerrm;
    end;
  end loop;

  return jsonb_build_object('ok', true, 'trigger', p_trigger,
                            'fired', v_fired, 'skipped', v_skipped, 'failed', v_failed);
end;
$$;


--
-- Name: tm_sla_state(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tm_sla_state(p_task_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  t               public.tm_tasks%rowtype;
  v_start         timestamptz;
  v_deadline      timestamptz;
  v_total_seconds numeric;
  v_used_seconds  numeric;
  v_pct           numeric;
  v_state         text;
  v_warn          integer;
begin
  select * into t from public.tm_tasks where id = p_task_id;
  if not found then
    return jsonb_build_object('state', 'unknown', 'reason', 'no_such_task',
                              'server_time', now());
  end if;

  -- A finished task has no clock left to run. Every resting state counts,
  -- not only the two that existed when this was first written.
  if t.status in ('completed', 'cancelled', 'approved', 'closed', 'failed') then
    return jsonb_build_object('state', 'closed', 'status', t.status,
                              'deadline', t.deadline,
                              'server_time', now());
  end if;

  select coalesce(max(sla_warning_percent), 75) into v_warn from public.tm_settings;

  v_start := coalesce(t.accepted_at, t.created_at);
  v_deadline := coalesce(t.deadline, v_start + make_interval(hours => coalesce(t.sla_hours, 24)::int));

  v_total_seconds := greatest(extract(epoch from (v_deadline - v_start)), 1);
  -- Time the task spent on hold is not charged against the person doing it.
  v_used_seconds := greatest(
    extract(epoch from (now() - v_start)) - coalesce(t.total_paused_minutes, 0) * 60, 0);
  v_pct := round((v_used_seconds / v_total_seconds) * 100, 1);

  v_state := case
    when v_pct >= 100 then 'breached'
    when v_pct >= 90  then 'critical'
    when v_pct >= v_warn then 'warning'
    else 'on_track'
  end;

  return jsonb_build_object(
    'state', v_state,
    'status', t.status,
    'percent_used', v_pct,
    'deadline', v_deadline,
    'started_from', v_start,
    'paused_minutes', coalesce(t.total_paused_minutes, 0),
    'seconds_remaining', greatest(v_total_seconds - v_used_seconds, 0),
    'warning_percent', v_warn,
    'server_time', now()
  );
end;
$$;


--
-- Name: tm_sla_sweep(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tm_sla_sweep() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  r           record;
  v_state     jsonb;
  v_level     integer;
  v_checked   integer := 0;
  v_raised    integer := 0;
  v_buzzed    integer := 0;
  v_autos     integer := 0;
  v_unclaimed integer := 0;
  v_grace     integer;
  v_result    jsonb;
begin
  select coalesce(max(buzzer_repeat_minutes), 10) into v_grace from public.tm_settings;

  for r in
    select id, escalation_level, buzzer_active, status, assigned_to, created_at
    from public.tm_tasks
    where status not in ('completed', 'cancelled', 'closed', 'approved')
  loop
    v_checked := v_checked + 1;

    -- Work sitting in the pool with nobody on it is its own kind of alarm.
    if r.assigned_to is null
       and r.status in ('new', 'routed', 'available_for_claim', 'assigned')
       and r.created_at < now() - make_interval(mins => v_grace) then
      v_result := public.tm_run_automations(r.id, 'unassigned_timeout');
      v_autos := v_autos + coalesce((v_result ->> 'fired')::int, 0);
      v_unclaimed := v_unclaimed + 1;
    end if;

    v_state := public.tm_sla_state(r.id);

    v_level := case v_state ->> 'state'
      when 'warning'  then 1
      when 'critical' then 2
      when 'breached' then 3
      else 0
    end;

    if v_level = 0 then
      continue;
    end if;

    if v_level > coalesce(r.escalation_level, 0) then
      insert into public.tm_escalations (task_id, level, reason, raised_by, raised_to, status)
      values (r.id, v_level,
              format('SLA %s at %s%% of the window',
                     v_state ->> 'state', v_state ->> 'percent_used'),
              'sla_engine', 'task_manager', 'open');

      update public.tm_tasks
         set escalation_level = v_level,
             buzzer_active = (v_level >= 3),
             updated_at = now()
       where id = r.id;

      insert into public.tm_activity (task_id, actor_name, actor_role, action, action_type,
                                      from_value, to_value, details)
      values (r.id, 'sla_engine', 'system',
              format('SLA %s', v_state ->> 'state'), 'escalation',
              coalesce(r.escalation_level, 0)::text, v_level::text,
              format('%s%% of the SLA window used', v_state ->> 'percent_used'));

      v_raised := v_raised + 1;
      if v_level >= 3 then v_buzzed := v_buzzed + 1; end if;

      v_result := public.tm_run_automations(
        r.id, case when v_level >= 3 then 'sla_breached' else 'sla_at_risk' end);
      v_autos := v_autos + coalesce((v_result ->> 'fired')::int, 0);
    end if;
  end loop;

  return jsonb_build_object('checked', v_checked, 'escalations_raised', v_raised,
                            'buzzers_started', v_buzzed, 'unclaimed_seen', v_unclaimed,
                            'automations_fired', v_autos, 'swept_at', now());
end;
$$;


--
-- Name: tm_status_from_developer(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tm_status_from_developer(p text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT CASE lower(coalesce(p,''))
    WHEN 'assigned'    THEN 'assigned'
    WHEN 'accepted'    THEN 'accepted'
    WHEN 'working'     THEN 'in_progress'
    WHEN 'in_progress' THEN 'in_progress'
    WHEN 'paused'      THEN 'on_hold'
    WHEN 'on_hold'     THEN 'on_hold'
    WHEN 'blocked'     THEN 'blocked'
    WHEN 'submitted'   THEN 'ai_review'
    WHEN 'review'      THEN 'ai_review'
    WHEN 'testing'     THEN 'testing'
    WHEN 'completed'   THEN 'completed'
    WHEN 'delivered'   THEN 'completed'
    WHEN 'cancelled'   THEN 'cancelled'
    ELSE 'assigned'
  END;
$$;


--
-- Name: tm_status_to_developer(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tm_status_to_developer(p text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select case lower(coalesce(p, ''))
    when 'new'                 then 'assigned'
    when 'routed'              then 'assigned'
    when 'available_for_claim' then 'assigned'
    when 'claimed'             then 'accepted'
    when 'assigned'            then 'assigned'
    when 'accepted'            then 'accepted'
    when 'in_progress'         then 'working'
    when 'on_hold'             then 'paused'
    when 'blocked'             then 'blocked'
    when 'waiting_client'      then 'submitted'
    when 'ai_review'           then 'submitted'
    when 'testing'             then 'testing'
    when 'submitted'           then 'submitted'
    when 'under_review'        then 'testing'
    when 'approved'            then 'completed'
    when 'rejected'            then 'working'
    when 'completed'           then 'completed'
    when 'failed'              then 'cancelled'
    when 'closed'              then 'completed'
    when 'cancelled'           then 'cancelled'
    else 'assigned'
  end;
$$;


--
-- Name: tm_sync_from_developer_task(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tm_sync_from_developer_task() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  -- fired by the other trigger's write; the change is already applied
  IF pg_trigger_depth() > 1 THEN RETURN NEW; END IF;
  IF NEW.tm_task_id IS NULL THEN RETURN NEW; END IF;

  UPDATE public.tm_tasks t
     SET status      = public.tm_status_from_developer(NEW.status),
         progress    = coalesce(NEW.progress_percent, t.progress),
         deadline    = coalesce(NEW.deadline, t.deadline),
         assigned_to = coalesce(public.tm_member_for_developer(NEW.developer_id), t.assigned_to),
         updated_at  = now()
   WHERE t.id = NEW.tm_task_id
     AND (t.status IS DISTINCT FROM public.tm_status_from_developer(NEW.status)
          OR t.progress IS DISTINCT FROM coalesce(NEW.progress_percent, t.progress));
  RETURN NEW;
END;
$$;


--
-- Name: tm_sync_to_developer_task(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tm_sync_to_developer_task() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF pg_trigger_depth() > 1 THEN RETURN NEW; END IF;

  UPDATE public.developer_tasks d
     SET status           = public.tm_status_to_developer(NEW.status),
         progress_percent = coalesce(NEW.progress, d.progress_percent),
         deadline         = coalesce(NEW.deadline, d.deadline),
         developer_id     = coalesce(public.tm_developer_for_member(NEW.assigned_to), d.developer_id),
         updated_at       = now()
   WHERE d.tm_task_id = NEW.id
     AND (d.status IS DISTINCT FROM public.tm_status_to_developer(NEW.status)
          OR d.progress_percent IS DISTINCT FROM coalesce(NEW.progress, d.progress_percent));
  RETURN NEW;
END;
$$;


--
-- Name: tm_task_blockers(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tm_task_blockers(p_task_id uuid) RETURNS TABLE(dependency_id uuid, blocking_task_id uuid, blocking_code text, blocking_title text, blocking_status text, dependency_type text, resolved boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select d.id,
         t.id,
         t.code,
         t.title,
         t.status,
         d.dependency_type,
         t.status = any (array['completed','approved','closed','cancelled'])
  from public.tm_dependencies d
  join public.tm_tasks t on t.id = d.depends_on_task_id
  where d.task_id = p_task_id
  order by t.status, t.code;
$$;


--
-- Name: tm_task_completion_to_promises(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tm_task_completion_to_promises() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if pg_trigger_depth() > 1 then
    return null;
  end if;
  if new.status is distinct from old.status
     and new.status in ('completed', 'approved', 'closed') then
    perform public.pt_task_completed(new.id);
  end if;
  return null;
end;
$$;


