    CONSTRAINT ai_content_settings_daily_request_cap_check CHECK (((daily_request_cap >= 0) AND (daily_request_cap <= 100000))),
    CONSTRAINT ai_content_settings_duplicate_threshold_check CHECK (((duplicate_threshold >= 0.3) AND (duplicate_threshold <= (1)::numeric))),
    CONSTRAINT ai_content_settings_high_similarity_threshold_check CHECK (((high_similarity_threshold >= 0.3) AND (high_similarity_threshold <= (1)::numeric))),
    CONSTRAINT ai_content_settings_id_check CHECK (id),
    CONSTRAINT ai_content_settings_max_output_tokens_check CHECK (((max_output_tokens >= 256) AND (max_output_tokens <= 32000))),
    CONSTRAINT ai_content_settings_publish_policy_check CHECK ((publish_policy = ANY (ARRAY['MANUAL_APPROVAL'::text, 'AUTO_PUBLISH'::text, 'ROLE_BASED_APPROVAL'::text, 'LEGAL_REVIEW_REQUIRED'::text]))),
    CONSTRAINT ai_content_settings_request_timeout_ms_check CHECK (((request_timeout_ms >= 5000) AND (request_timeout_ms <= 300000))),
    CONSTRAINT ai_content_settings_temperature_check CHECK (((temperature >= (0)::numeric) AND (temperature <= (2)::numeric)))
);


