    CONSTRAINT i18n_glossary_terms_source_term_check CHECK (((char_length(btrim(source_term)) >= 1) AND (char_length(btrim(source_term)) <= 200))),
    CONSTRAINT i18n_glossary_terms_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'approved'::text, 'deprecated'::text]))),
