    desktop_enabled boolean DEFAULT true NOT NULL,
    tablet_enabled boolean DEFAULT true NOT NULL,
    mobile_enabled boolean DEFAULT true NOT NULL,
    "position" text DEFAULT 'bottom-right'::text NOT NULL,
    offset_x integer DEFAULT 24 NOT NULL,
    offset_y integer DEFAULT 24 NOT NULL,
    theme text DEFAULT 'accent'::text NOT NULL,
    icon text,
    label text NOT NULL,
    trigger_type text DEFAULT 'immediate'::text NOT NULL,
    trigger_value integer DEFAULT 0 NOT NULL,
    action_type text DEFAULT 'route'::text NOT NULL,
    action_target text,
    priority integer DEFAULT 10 NOT NULL,
    audience text DEFAULT 'all'::text NOT NULL,
    page_scope text DEFAULT 'all'::text NOT NULL,
    starts_at timestamp with time zone,
    ends_at timestamp with time zone,
    created_by uuid,
    updated_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT storefront_floating_action_ck CHECK (((action_type = ANY (ARRAY['none'::text, 'lead_form'::text])) OR ((action_target IS NOT NULL) AND (action_target <> ''::text)))),
    CONSTRAINT storefront_floating_elements_action_type_check CHECK ((action_type = ANY (ARRAY['route'::text, 'external'::text, 'whatsapp'::text, 'mailto'::text, 'tel'::text, 'lead_form'::text, 'none'::text]))),
    CONSTRAINT storefront_floating_elements_audience_check CHECK ((audience = ANY (ARRAY['all'::text, 'guest'::text, 'authenticated'::text]))),
    CONSTRAINT storefront_floating_elements_element_type_check CHECK ((element_type = ANY (ARRAY['ai_chat'::text, 'support'::text, 'request_demo'::text, 'actions'::text, 'link'::text]))),
    CONSTRAINT storefront_floating_elements_offset_x_check CHECK (((offset_x >= 0) AND (offset_x <= 200))),
    CONSTRAINT storefront_floating_elements_offset_y_check CHECK (((offset_y >= 0) AND (offset_y <= 200))),
    CONSTRAINT storefront_floating_elements_page_scope_check CHECK ((page_scope = ANY (ARRAY['all'::text, 'home'::text, 'marketplace'::text, 'product'::text, 'category'::text]))),
    CONSTRAINT storefront_floating_elements_position_check CHECK (("position" = ANY (ARRAY['bottom-right'::text, 'bottom-left'::text, 'top-right'::text, 'top-left'::text]))),
    CONSTRAINT storefront_floating_elements_priority_check CHECK (((priority >= 1) AND (priority <= 100))),
    CONSTRAINT storefront_floating_elements_theme_check CHECK ((theme = ANY (ARRAY['accent'::text, 'primary'::text, 'success'::text, 'premium'::text, 'neutral'::text]))),
    CONSTRAINT storefront_floating_elements_trigger_type_check CHECK ((trigger_type = ANY (ARRAY['immediate'::text, 'delay'::text, 'scroll'::text, 'exit_intent'::text]))),
    CONSTRAINT storefront_floating_elements_trigger_value_check CHECK (((trigger_value >= 0) AND (trigger_value <= 100000)))
);


