CREATE TABLE public.tm_notifications (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    task_id uuid,
    title text NOT NULL,
    message text NOT NULL,
    level text DEFAULT 'info'::text NOT NULL,
    channel text DEFAULT 'in_app'::text NOT NULL,
    read boolean DEFAULT false NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT tm_notifications_level_check CHECK ((level = ANY (ARRAY['info'::text, 'success'::text, 'warning'::text, 'critical'::text])))
);


--
-- Name: tm_reviews; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.tm_reviews (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    task_id uuid NOT NULL,
    reviewer_id uuid,
    reviewer_name text NOT NULL,
    quality_score integer DEFAULT 0 NOT NULL,
    timeliness_score integer DEFAULT 0 NOT NULL,
    verdict text DEFAULT 'pending'::text NOT NULL,
    remarks text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT tm_reviews_quality_score_check CHECK (((quality_score >= 0) AND (quality_score <= 100))),
    CONSTRAINT tm_reviews_timeliness_score_check CHECK (((timeliness_score >= 0) AND (timeliness_score <= 100))),
    CONSTRAINT tm_reviews_verdict_check CHECK ((verdict = ANY (ARRAY['pending'::text, 'passed'::text, 'failed'::text, 'rework'::text])))
);


--
-- Name: tm_settings; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.tm_settings (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    singleton boolean DEFAULT true NOT NULL,
    default_sla_hours numeric(6,2) DEFAULT 24 NOT NULL,
    critical_sla_hours numeric(6,2) DEFAULT 4 NOT NULL,
    sla_warning_percent integer DEFAULT 75 NOT NULL,
    auto_assign boolean DEFAULT true NOT NULL,
    auto_escalate boolean DEFAULT true NOT NULL,
    buzzer_enabled boolean DEFAULT true NOT NULL,
    buzzer_repeat_minutes integer DEFAULT 10 NOT NULL,
    require_approval boolean DEFAULT true NOT NULL,
    ai_review_enabled boolean DEFAULT true NOT NULL,
    working_hours_start text DEFAULT '09:30'::text NOT NULL,
    working_hours_end text DEFAULT '19:00'::text NOT NULL,
    timezone text DEFAULT 'Asia/Kolkata'::text NOT NULL,
    escalation_matrix jsonb DEFAULT '[]'::jsonb NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: tm_subtasks; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.tm_subtasks (
