    "position" integer DEFAULT 0 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: tm_tasks; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.tm_tasks (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    code text NOT NULL,
    title text NOT NULL,
    description text DEFAULT ''::text NOT NULL,
    category text DEFAULT 'development'::text NOT NULL,
    module text,
    client_name text,
    status text DEFAULT 'new'::text NOT NULL,
    priority text DEFAULT 'medium'::text NOT NULL,
    difficulty text DEFAULT 'medium'::text NOT NULL,
    created_by uuid,
    assigned_to uuid,
    estimated_hours numeric(6,2) DEFAULT 4 NOT NULL,
    actual_minutes integer DEFAULT 0 NOT NULL,
    sla_hours numeric(6,2) DEFAULT 24 NOT NULL,
    promised_at timestamp with time zone,
    deadline timestamp with time zone,
    accepted_at timestamp with time zone,
    started_at timestamp with time zone,
    paused_at timestamp with time zone,
    completed_at timestamp with time zone,
    total_paused_minutes integer DEFAULT 0 NOT NULL,
    timer_running boolean DEFAULT false NOT NULL,
    progress integer DEFAULT 0 NOT NULL,
    billable boolean DEFAULT true NOT NULL,
    cost numeric(12,2) DEFAULT 0 NOT NULL,
    tags text[] DEFAULT '{}'::text[] NOT NULL,
    blocked_reason text,
    buzzer_active boolean DEFAULT false NOT NULL,
    buzzer_acknowledged_at timestamp with time zone,
    escalation_level integer DEFAULT 0 NOT NULL,
    approval_status text DEFAULT 'not_required'::text NOT NULL,
    ai_generated boolean DEFAULT false NOT NULL,
    quality_score integer,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    task_type text,
    severity text DEFAULT 'medium'::text NOT NULL,
    source_reference text,
    assigned_role text,
    currency text DEFAULT 'INR'::text NOT NULL,
    project_name text,
    claimed_at timestamp with time zone,
    submitted_at timestamp with time zone,
    reviewed_at timestamp with time zone,
    approved_at timestamp with time zone,
    closed_at timestamp with time zone,
    sla_policy text,
    hold_reason text,
    hold_until timestamp with time zone,
    acknowledged_by uuid,
    billing_status text DEFAULT 'not_billable'::text NOT NULL,
    invoice_reference text,
    payment_reference text,
    settled_at timestamp with time zone,
    updated_by uuid,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    CONSTRAINT tm_tasks_approval_status_check CHECK ((approval_status = ANY (ARRAY['not_required'::text, 'pending'::text, 'approved'::text, 'rejected'::text, 'changes_requested'::text]))),
    CONSTRAINT tm_tasks_billing_status_check CHECK ((billing_status = ANY (ARRAY['not_billable'::text, 'pending'::text, 'invoiced'::text, 'settled'::text, 'written_off'::text]))),
    CONSTRAINT tm_tasks_difficulty_check CHECK ((difficulty = ANY (ARRAY['easy'::text, 'medium'::text, 'hard'::text, 'expert'::text]))),
    CONSTRAINT tm_tasks_priority_check CHECK ((priority = ANY (ARRAY['low'::text, 'medium'::text, 'high'::text, 'critical'::text]))),
    CONSTRAINT tm_tasks_progress_check CHECK (((progress >= 0) AND (progress <= 100))),
    CONSTRAINT tm_tasks_severity_check CHECK ((severity = ANY (ARRAY['low'::text, 'medium'::text, 'high'::text, 'critical'::text]))),
    CONSTRAINT tm_tasks_status_check CHECK ((status = ANY (ARRAY['new'::text, 'routed'::text, 'available_for_claim'::text, 'claimed'::text, 'assigned'::text, 'accepted'::text, 'in_progress'::text, 'on_hold'::text, 'blocked'::text, 'waiting_client'::text, 'ai_review'::text, 'testing'::text, 'submitted'::text, 'under_review'::text, 'approved'::text, 'rejected'::text, 'completed'::text, 'cancelled'::text, 'failed'::text, 'closed'::text])))
);

ALTER TABLE ONLY public.tm_tasks REPLICA IDENTITY FULL;


